// Hyperrealistic study: A tight crop of a child's scraped knee with a half-peeled
// adhesive plaster, built the way birch bark is built.

const PAL = {
  bgPaper: "#dfdbd2",
  bgCool1: "#cbc7be",
  bgCool2: "#b8b4aa",
  bgShadow: "#9e9a90",

  // Chalky whites & pale bone sheets (birch-bark skin construction)
  chalkPure: "#fbfaf7",
  chalkWarm: "#f5f2eb",
  chalkCool: "#eef0ed",
  boneLight: "#ebe5d8",
  boneMid: "#dfd6c5",
  boneWarm: "#d2c6b2",
  boneDeep: "#c2b49e",
  barkShadow: "#8c8173",
  barkCrevice: "#574e46",

  // Soft graphite & cool overcast form modeling
  graphLight: "#b5b0a6",
  graphMid: "#918c82",
  graphDark: "#6e6960",
  graphDeep: "#4d4842",
  charcoalDark: "#2b2522",
  charcoalMid: "#423934",

  // Raw skin accents: Raw Sienna & Pink Madder
  siennaLight: "#d89a5b",
  siennaMid: "#bf7636",
  siennaDeep: "#96511e",
  madderLight: "#dfa0a0",
  madderMid: "#c76467",
  madderDeep: "#9e3e43",
  madderBruise: "#8c585c",

  // Adhesive plaster & gauze tones
  plasterLight: "#e8e0d2",
  plasterMid: "#d8ccb8",
  plasterDark: "#bfb09a",
  plasterUnder: "#cfc2ae",
  plasterGlue: "#b8a68e",
  gauzeWhite: "#f7f5f0",
  gauzeShadow: "#d4cec3"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7429);
  noiseSeed(7429);

  // Custom fine brushes for hyperreal details
  brush.add("fine2H", {
    type: "default",
    weight: 0.28,
    scatter: 0.08,
    sharpness: 0.88,
    grain: 18,
    opacity: 165,
    spacing: 0.15,
    pressure: [0.4, 1.0, 0.3],
    noise: 0.35
  });

  brush.add("softGraphite", {
    type: "default",
    weight: 1.35,
    scatter: 0.65,
    sharpness: 0.22,
    grain: 38,
    opacity: 48,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.5
  });

  brush.add("barkCharcoal", {
    type: "default",
    weight: 0.95,
    scatter: 0.42,
    sharpness: 0.45,
    grain: 45,
    opacity: 180,
    spacing: 0.18,
    pressure: [0.6, 1.15, 0.4],
    noise: 0.65
  });

  brush.add("chalkEdge", {
    type: "default",
    weight: 1.1,
    scatter: 0.25,
    sharpness: 0.6,
    grain: 30,
    opacity: 210,
    spacing: 0.16,
    pressure: [0.3, 1.1, 0.3],
    noise: 0.4
  });
}

// ============================================================================
// ANATOMICAL KNEE SURFACE MODEL
// ============================================================================

function getKneeBounds(y) {
  let t = y / 1200;
  // Subtle S-curve of child's leg from lower thigh through patella to upper shin
  let cx = 605 - t * 48 + sin(t * 180) * 14;

  // Patellar & condylar bulge between y = 340 and y = 780
  let patellaBulge = exp(-pow((y - 565) / 250, 2));
  let infraHollow = exp(-pow((y - 845) / 130, 2));
  let thighTaper = (1 - t) * 38;

  let leftHw = 338 + patellaBulge * 52 - infraHollow * 26 + thighTaper * 0.6;
  let rightHw = 345 + patellaBulge * 72 - infraHollow * 32 + thighTaper * 0.9;

  // Slight organic contour modulation
  let nL = (noise(y * 0.004, 1.2) - 0.5) * 16;
  let nR = (noise(y * 0.004, 5.8) - 0.5) * 16;

  return {
    cx: cx,
    left: cx - leftHw + nL,
    right: cx + rightHw + nR,
    width: leftHw + rightHw
  };
}

// Maps normalized cross-parameter u in [-1, 1] and base y to 2D canvas coordinates
// with realistic 3D cylindrical + patellar dome cross-contour deflection
function kneePt(u, yBase) {
  let b = getKneeBounds(yBase);
  let x = map(u, -1, 1, b.left, b.right);

  // Cylindrical wrap curve (slight downward view on upper knee, slight upward on lower)
  let cylArch = (1 - sqrt(max(0, 1 - u * u))) * 34;
  let viewTilt = map(yBase, 0, 1200, -0.55, 0.75);

  // Patellar dome deflection centered around (585, 555)
  let dx = (x - 585) / 245;
  let dy = (yBase - 555) / 215;
  let r2 = dx * dx + dy * dy;
  let domeDeflect = 0;
  if (r2 < 1.8) {
    domeDeflect = exp(-r2 * 1.45) * dy * 28;
  }

  // Infrapatellar tendon bridge & dimples around y = 810
  let tendonDeflect = exp(-pow((yBase - 820) / 110, 2)) * exp(-pow(u * 2.2, 2)) * 12;

  let y = yBase + cylArch * viewTilt + domeDeflect + tendonDeflect;
  return [x, y];
}

// Helper to draw a closed or open shape from point array
function drawShapePts(pts, curvature = 0.2, closed = true) {
  if (!pts || pts.length < 2) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Builds a horizontal birch-like sheet polygon across the knee from u1 to u2
function buildKneeSheetPoly(u1, u2, yTop, thickness, waviness = 6, steps = 14) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let f = i / steps;
    let u = lerp(u1, u2, f);
    let n = (noise(u * 3.5 + yTop * 0.02, yTop * 0.015) - 0.5) * waviness * 2;
    let p = kneePt(u, yTop + n);
    pts.push(p);
  }
  for (let i = steps; i >= 0; i--) {
    let f = i / steps;
    let u = lerp(u1, u2, f);
    // Taper thickness at ends like peeling birch bark strips
    let edgeTaper = sin(f * 180);
    let localH = thickness * (0.35 + 0.65 * pow(edgeTaper, 0.55));
    let n = (noise(u * 3.5 + (yTop + 40) * 0.02, yTop * 0.015 + 9) - 0.5) * waviness * 2;
    let p = kneePt(u, yTop + localH + n);
    pts.push(p);
  }
  return pts;
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.bgPaper);

  // 1. Overcast clinical atmosphere & recessed background around the knee
  drawOvercastBackground();

  // 2. Base knee undertone & birch-bark papery washes (chalky white & pale bone)
  drawKneeBarkSheets();

  // 3. Soft graphite volumetric modeling (carrying the 3D rounded form of the knee)
  drawSoftGraphiteForm();

  // 4. Raw skin in the scrape (raw sienna & pink madder washes, capillary stipple)
  drawRawScrapeSkin();

  // 5. Lifted, curling papery birch-bark edges around the scrape & across the patella
  drawLiftedCurlingBarkEdges();

  // 6. Short horizontal charcoal dashes (grazes, lenticel pores, and flexion creases)
  drawHorizontalCharcoalDashes();

  // 7. Cast shadow of the half-peeled plaster falling across the knee and raw scrape
  drawPlasterCastShadow();

  // 8. Half-peeled adhesive plaster: adhered wing, stretched glue fibers,
  //    curling gauze pad with raw sienna/madder stain, and hard-pencil fabric weave
  drawHalfPeeledPlaster();

  // 9. Final clinical highlights, curling gauze threads, and delicate foreground grain
  drawFinalMicroDetails();

  noLoop();
}

// ============================================================================
// 1. OVERCAST CLINICAL ATMOSPHERE & BACKGROUND
// ============================================================================

function drawOvercastBackground() {
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.3);

  // Left and right negative space flanks (recessed cool overcast tone)
  brush.fill(PAL.bgCool1, 130);
  for (let side of [-1, 1]) {
    for (let pass = 0; pass < 3; pass++) {
      let pts = [];
      let xEdge = side < 0 ? -40 : 1240;
      pts.push([xEdge, -40]);
      for (let y = -40; y <= 1240; y += 100) {
        let b = getKneeBounds(y);
        let bx = side < 0 ? b.left + pass * 18 : b.right - pass * 18;
        pts.push([bx + random(-12, 12), y]);
      }
      pts.push([xEdge, 1240]);
      drawShapePts(pts, 0.2, true);
    }
  }

  // Deeper cool shadow right outside the leg contour to make the chalky knee glow
  brush.fill(PAL.bgCool2, 110);
  for (let side of [-1, 1]) {
    let pts = [];
    for (let y = -20; y <= 1220; y += 80) {
      let b = getKneeBounds(y);
      let bx = side < 0 ? b.left - 4 : b.right + 4;
      pts.push([bx, y]);
    }
    for (let y = 1220; y >= -20; y -= 80) {
      let b = getKneeBounds(y);
      let bx = side < 0 ? b.left - 95 - random(20, 60) : b.right + 95 + random(20, 60);
      pts.push([bx, y]);
    }
    drawShapePts(pts, 0.25, true);
  }
  brush.noFill();

  // Fine clinical graphite background hatching in negative space
  brush.set("2H", PAL.bgShadow, 0.55);
  for (let y = 20; y < 1180; y += 9) {
    let b = getKneeBounds(y);
    // Left negative space
    if (b.left > 20) {
      brush.line(0, y + random(-3, 3), b.left - random(2, 14), y + random(-4, 4));
    }
    // Right negative space
    if (b.right < 1180) {
      brush.line(b.right + random(2, 14), y + random(-4, 4), 1200, y + random(-3, 3));
    }
  }
}

// ============================================================================
// 2. CHALKY WHITE & PALE BONE BIRCH-BARK SHEETS
// ============================================================================

function drawKneeBarkSheets() {
  brush.noStroke();

  // Pass A: Underlying warm bone base wash across the entire leg cylinder
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.5, 0.25);
  brush.fill(PAL.boneLight, 150);
  let fullLeg = [];
  for (let y = -30; y <= 1230; y += 60) fullLeg.push(kneePt(-0.98, y));
  for (let y = 1230; y >= -30; y -= 60) fullLeg.push(kneePt(0.98, y));
  drawShapePts(fullLeg, 0.15, true);
  brush.noFill();

  // Pass B: Laminar horizontal birch-bark sheets in batched bone & chalk tones
  // Using wash() and fill() to create thin papery overlapping strata
  let boneSheets = [];
  let midBoneSheets = [];
  let deepBoneSheets = [];
  let chalkSheets = [];
  let pureChalkSheets = [];

  for (let y = -10; y < 1190; y += 22) {
    let numStrips = floor(random(2, 4));
    for (let s = 0; s < numStrips; s++) {
      let uCenter = random(-0.75, 0.75);
      let uSpan = random(0.32, 0.78);
      let u1 = constrain(uCenter - uSpan * 0.5, -0.97, 0.8);
      let u2 = constrain(uCenter + uSpan * 0.5, -0.8, 0.97);
      if (u2 - u1 < 0.18) continue;

      let h = random(20, 56);
      let poly = buildKneeSheetPoly(u1, u2, y + random(-8, 8), h, random(4, 9), 14);

      // Lighting logic: cool overcast light from upper-left (-0.25, 440)
      let lightFactor = -uCenter * 0.45 - ((y - 480) / 700) * 0.35 + random(-0.18, 0.18);

      if (lightFactor > 0.22) {
        pureChalkSheets.push(poly);
      } else if (lightFactor > 0.02) {
        chalkSheets.push(poly);
      } else if (lightFactor > -0.15) {
        boneSheets.push(poly);
      } else if (lightFactor > -0.32) {
        midBoneSheets.push(poly);
      } else {
        deepBoneSheets.push(poly);
      }
    }
  }

  // Render deep bone sheets on the right/lower shaded turn of the knee
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.65, 0.55);
  brush.fill(PAL.boneDeep, 115);
  for (let p of deepBoneSheets) drawShapePts(p, 0.18, true);

  // Render mid bone sheets
  brush.fill(PAL.boneMid, 120);
  for (let p of midBoneSheets) drawShapePts(p, 0.18, true);

  // Render light bone sheets
  brush.fill(PAL.boneLight, 130);
  for (let p of boneSheets) drawShapePts(p, 0.18, true);
  brush.noFill();

  // Render papery opaque chalk washes (thin laminar birch bark feel)
  for (let p of chalkSheets) {
    brush.wash(PAL.chalkWarm, 135);
    drawShapePts(p, 0.15, true);
  }
  for (let p of pureChalkSheets) {
    brush.wash(PAL.chalkPure, 155);
    drawShapePts(p, 0.15, true);
  }

  // Extra luminous chalky sheets over the patellar dome highlight (upper-left of knee)
  for (let i = 0; i < 18; i++) {
    let y = random(240, 620);
    let u1 = random(-0.68, -0.25);
    let u2 = u1 + random(0.35, 0.65);
    let p = buildKneeSheetPoly(u1, u2, y, random(18, 42), 5, 12);
    brush.wash(i % 2 === 0 ? PAL.chalkPure : PAL.chalkCool, 145);
    drawShapePts(p, 0.16, true);
  }
  brush.noWash();
}

// ============================================================================
// 3. SOFT GRAPHITE CARRYING THE ROUNDED FORM
// ============================================================================

function drawSoftGraphiteForm() {
  // Anatomical shadow zones modeled with soft watercolor-graphite under-washes
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.25);

  // Right turning flank shadow of the knee & medial condyle
  brush.fill(PAL.graphLight, 75);
  let rightFlank = [];
  for (let y = -20; y <= 1220; y += 60) rightFlank.push(kneePt(0.32 + sin(y * 0.3) * 0.08, y));
  for (let y = 1220; y >= -20; y -= 60) rightFlank.push(kneePt(0.99, y));
  drawShapePts(rightFlank, 0.25, true);

  // Deeper core shadow along the right edge and lower patellar underside
  brush.fill(PAL.graphMid, 68);
  let rightCore = [];
  for (let y = -20; y <= 1220; y += 60) rightCore.push(kneePt(0.62, y));
  for (let y = 1220; y >= -20; y -= 60) rightCore.push(kneePt(0.99, y));
  drawShapePts(rightCore, 0.25, true);

  // Left edge reflected-light turning shadow
  brush.fill(PAL.graphLight, 62);
  let leftTurn = [];
  for (let y = -20; y <= 1220; y += 60) leftTurn.push(kneePt(-0.99, y));
  for (let y = 1220; y >= -20; y -= 60) leftTurn.push(kneePt(-0.72, y));
  drawShapePts(leftTurn, 0.25, true);

  // Infrapatellar hollows (below the kneecap around y = 700..920)
  brush.fill(PAL.graphMid, 58);
  let underPatella = buildKneeSheetPoly(-0.62, 0.72, 685, 165, 12, 16);
  drawShapePts(underPatella, 0.3, true);
  brush.noFill();

  // Soft graphite cross-contour shading strokes following the 3D knee curvature
  for (let y = -10; y < 1210; y += 4.5) {
    // Right side volumetric shading
    let uStartR = map(noise(y * 0.01, 2), 0, 1, 0.08, 0.42);
    // Extend further left under the patellar shelf (y = 660..860) and suprapatellar fold (y = 220..340)
    let patellaShelf = exp(-pow((y - 745) / 95, 2)) * 0.55;
    let supraFold = exp(-pow((y - 285) / 65, 2)) * 0.38;
    uStartR = constrain(uStartR - patellaShelf - supraFold, -0.55, 0.6);

    let ptsR = [];
    for (let u = uStartR; u <= 0.98; u += 0.06) {
      ptsR.push(kneePt(u, y + random(-2, 2)));
    }
    if (ptsR.length > 2) {
      let col = random() < 0.55 ? PAL.graphMid : PAL.graphLight;
      brush.set("softGraphite", col, random(0.75, 1.35));
      brush.spline(ptsR, 0.35);
    }

    // Denser terminal shadow near right contour
    if (y % 9 < 4.5) {
      let ptsEdgeR = [];
      for (let u = 0.62 + random(-0.08, 0.08); u <= 0.99; u += 0.05) {
        ptsEdgeR.push(kneePt(u, y + random(-1.5, 1.5)));
      }
      brush.set("2B", PAL.graphDark, random(0.45, 0.85));
      brush.spline(ptsEdgeR, 0.3);
    }

    // Left turning edge soft graphite modeling
    let uEndL = -0.64 + exp(-pow((y - 790) / 110, 2)) * 0.24 + random(-0.06, 0.06);
    let ptsL = [];
    for (let u = -0.99; u <= uEndL; u += 0.05) {
      ptsL.push(kneePt(u, y + random(-2, 2)));
    }
    if (ptsL.length > 2) {
      brush.set("softGraphite", PAL.graphMid, random(0.65, 1.1));
      brush.spline(ptsL, 0.35);
    }
  }

  // Longitudinal anatomical graphite strokes following the patellar tendon & condyles
  for (let i = 0; i < 160; i++) {
    let u = random(-0.95, 0.95);
    // Concentrate on shaded flanks and tendon grooves
    if (u > -0.58 && u < 0.18 && random() < 0.72) continue;
    let y1 = random(0, 1120);
    let y2 = y1 + random(60, 190);
    let pts = [];
    for (let y = y1; y <= y2; y += 22) {
      let drift = (noise(u * 4, y * 0.01) - 0.5) * 0.04;
      pts.push(kneePt(constrain(u + drift, -0.98, 0.98), y));
    }
    brush.set("HB", abs(u) > 0.68 ? PAL.graphDark : PAL.graphMid, random(0.35, 0.65));
    brush.spline(pts, 0.25);
  }

  // Crisp yet soft outer contour of the child's leg
  for (let side of [-1, 1]) {
    for (let y = -10; y < 1180; y += 75) {
      let pts = [];
      for (let yy = y; yy <= y + 90; yy += 15) {
        pts.push(kneePt(side * 0.985, yy));
      }
      brush.set("2B", side > 0 ? PAL.graphDeep : PAL.graphDark, random(0.55, 0.95));
      brush.spline(pts, 0.3);
    }
  }
}

// ============================================================================
// 4. RAW SKIN IN THE SCRAPE (RAW SIENNA & PINK MADDER)
// ============================================================================

function drawRawScrapeSkin() {
  // The scrape sits across the crown of the patella (roughly x = 465..820, y = 445..695),
  // emerging from beneath the peel line of the plaster at x ~ 530.
  brush.noStroke();
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.68, 0.48);

  // Parallel horizontal skid tracks of raw abraded dermis (Pink Madder washes)
  const scrapeTracks = [
    { u1: -0.15, u2: 0.42, y: 468, h: 28, col: PAL.madderLight, op: 135 },
    { u1: -0.18, u2: 0.54, y: 496, h: 38, col: PAL.madderMid,   op: 155 },
    { u1: -0.16, u2: 0.58, y: 534, h: 44, col: PAL.madderDeep,  op: 145 },
    { u1: -0.14, u2: 0.51, y: 578, h: 40, col: PAL.madderMid,   op: 160 },
    { u1: -0.12, u2: 0.46, y: 618, h: 34, col: PAL.madderLight, op: 140 },
    { u1: -0.05, u2: 0.35, y: 652, h: 26, col: PAL.madderBruise, op: 125 },
    // Smaller satellite grazes above and below
    { u1: 0.04,  u2: 0.34, y: 428, h: 16, col: PAL.madderLight, op: 115 },
    { u1: 0.08,  u2: 0.38, y: 688, h: 18, col: PAL.madderLight, op: 110 }
  ];

  for (let tr of scrapeTracks) {
    brush.fill(tr.col, tr.op);
    let poly = buildKneeSheetPoly(tr.u1, tr.u2, tr.y, tr.h, 7, 14);
    drawShapePts(poly, 0.25, true);
  }

  // Touches of Raw Sienna sitting in the raw skin (serous crust & amber plasma edges)
  const siennaPatches = [
    { u1: -0.14, u2: 0.22, y: 484, h: 22, col: PAL.siennaLight, op: 145 },
    { u1: 0.12,  u2: 0.48, y: 512, h: 26, col: PAL.siennaMid,   op: 155 },
    { u1: -0.12, u2: 0.32, y: 552, h: 28, col: PAL.siennaDeep,  op: 135 },
    { u1: 0.18,  u2: 0.55, y: 568, h: 24, col: PAL.siennaMid,   op: 150 },
    { u1: -0.08, u2: 0.28, y: 602, h: 25, col: PAL.siennaLight, op: 140 },
    { u1: 0.15,  u2: 0.44, y: 632, h: 20, col: PAL.siennaMid,   op: 135 },
    { u1: 0.08,  u2: 0.26, y: 432, h: 12, col: PAL.siennaLight, op: 120 }
  ];

  for (let sp of siennaPatches) {
    brush.fill(sp.col, sp.op);
    let poly = buildKneeSheetPoly(sp.u1, sp.u2, sp.y, sp.h, 6, 12);
    drawShapePts(poly, 0.22, true);
  }
  brush.noFill();

  // Surviving thin bridges of chalky/bone epidermis running horizontally between raw tracks
  for (let yBridge of [490, 530, 574, 614, 648]) {
    let u1 = random(-0.08, 0.05);
    let u2 = u1 + random(0.25, 0.42);
    let bridgePoly = buildKneeSheetPoly(u1, u2, yBridge, random(7, 13), 4, 12);
    brush.wash(PAL.chalkWarm, 175);
    drawShapePts(bridgePoly, 0.18, true);
  }
  brush.noWash();

  // Fine colored pencil & hard pencil dermal texture inside the raw scrape
  for (let i = 0; i < 220; i++) {
    let u = random(-0.14, 0.54);
    let y = random(455, 675);
    // Stay within oval scrape envelope
    let normD = pow((u - 0.18) / 0.36, 2) + pow((y - 565) / 115, 2);
    if (normD > 1.05) continue;

    let p1 = kneePt(u, y);
    let p2 = kneePt(u + random(0.015, 0.055), y + random(-2, 2));
    let c = random() < 0.52 ? (random() < 0.5 ? PAL.madderDeep : PAL.madderMid)
                            : (random() < 0.5 ? PAL.siennaMid : PAL.siennaDeep);
    brush.set("cpencil", c, random(0.35, 0.75));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// 5. LIFTED, CURLING PAPERY BIRCH-BARK EDGES
// ============================================================================

function drawLiftedCurlingBarkEdges() {
  // Helper that draws a lifted, curling papery skin/bark sheet edge
  // dir = 1 means edge curls upward (shadow below); dir = -1 means curls downward
  function drawCurlingSheetEdge(u1, u2, yBase, curlHeight, dir, isChalky = true) {
    let steps = 14;
    let baseEdge = [];
    let liftedLip = [];
    let shadowEdge = [];

    for (let i = 0; i <= steps; i++) {
      let f = i / steps;
      let u = lerp(u1, u2, f);
      let arch = sin(f * 180); // Curl lifts highest in middle or toward one end
      let jitter = (noise(u * 8, yBase * 0.05) - 0.5) * 5;
      let pBase = kneePt(u, yBase + jitter);
      let lift = curlHeight * (0.25 + 0.75 * pow(arch, 0.7));

      baseEdge.push(pBase);
      liftedLip.push([pBase[0] + arch * 3, pBase[1] - dir * lift]);
      shadowEdge.push([pBase[0] + arch * 2, pBase[1] + dir * (lift * 0.65 + 3)]);
    }

    // 1. Dark crevice cast shadow directly beneath the lifted papery edge
    brush.noStroke();
    brush.wash(PAL.barkCrevice, 155);
    let shPoly = [...liftedLip, ...shadowEdge.slice().reverse()];
    drawShapePts(shPoly, 0.18, true);

    // 2. Soft penumbra shadow
    brush.wash(PAL.barkShadow, 95);
    let penPoly = [];
    for (let p of liftedLip) penPoly.push(p);
    for (let i = shadowEdge.length - 1; i >= 0; i--) {
      penPoly.push([shadowEdge[i][0], shadowEdge[i][1] + dir * 5]);
    }
    drawShapePts(penPoly, 0.2, true);

    // 3. The curled papery ribbon itself (underside bone, top edge chalky white)
    let ribbonPoly = [...baseEdge, ...liftedLip.slice().reverse()];
    brush.wash(isChalky ? PAL.chalkPure : PAL.boneLight, 220);
    drawShapePts(ribbonPoly, 0.18, true);
    brush.noWash();

    // 4. Crisp hard-pencil contour along the lifted edge and fold seam
    brush.set("chalkEdge", PAL.chalkPure, 0.9);
    brush.spline(liftedLip, 0.25);

    brush.set("fine2H", PAL.barkCrevice, 0.75);
    brush.spline(liftedLip, 0.25);

    brush.set("2H", PAL.barkShadow, 0.45);
    brush.spline(baseEdge, 0.25);
  }

  // Lifted, curling papery sheets framing the raw scrape (like exfoliating birch bark)
  const scrapeCurls = [
    { u1: -0.12, u2: 0.36, y: 456, h: 14, dir: -1, chalk: true },
    { u1: 0.16,  u2: 0.52, y: 482, h: 16, dir: -1, chalk: false },
    { u1: -0.06, u2: 0.28, y: 526, h: 13, dir: 1,  chalk: true },
    { u1: 0.22,  u2: 0.58, y: 548, h: 17, dir: -1, chalk: true },
    { u1: -0.04, u2: 0.34, y: 572, h: 14, dir: 1,  chalk: false },
    { u1: 0.18,  u2: 0.54, y: 608, h: 16, dir: 1,  chalk: true },
    { u1: -0.08, u2: 0.42, y: 644, h: 15, dir: 1,  chalk: true },
    { u1: 0.02,  u2: 0.38, y: 678, h: 13, dir: 1,  chalk: false }
  ];

  for (let c of scrapeCurls) {
    drawCurlingSheetEdge(c.u1, c.u2, c.y, c.h, c.dir, c.chalk);
  }

  // Broader birch-bark papery sheet seams across the patella, upper knee, and shin
  const kneeBarkSeams = [
    { u1: -0.58, u2: -0.08, y: 245, h: 11, dir: 1,  chalk: true },
    { u1: -0.15, u2: 0.45,  y: 295, h: 12, dir: 1,  chalk: false },
    { u1: -0.68, u2: -0.12, y: 358, h: 14, dir: 1,  chalk: true },
    { u1: -0.04, u2: 0.52,  y: 392, h: 13, dir: -1, chalk: true },
    { u1: 0.28,  u2: 0.74,  y: 445, h: 11, dir: -1, chalk: false },
    { u1: -0.64, u2: -0.18, y: 715, h: 13, dir: 1,  chalk: true },
    { u1: -0.12, u2: 0.48,  y: 758, h: 15, dir: 1,  chalk: true },
    { u1: 0.14,  u2: 0.68,  y: 815, h: 12, dir: 1,  chalk: false },
    { u1: -0.52, u2: 0.12,  y: 868, h: 14, dir: 1,  chalk: true },
    { u1: -0.25, u2: 0.38,  y: 945, h: 11, dir: 1,  chalk: false },
    { u1: -0.45, u2: 0.18,  y: 1035, h: 12, dir: 1, chalk: true }
  ];

  for (let s of kneeBarkSeams) {
    drawCurlingSheetEdge(s.u1, s.u2, s.y, s.h, s.dir, s.chalk);
  }

  // Small curling papery spirals/tags at the raw abrasion borders (peeled cuticle scrolls)
  for (let i = 0; i < 28; i++) {
    let angle = random(0, 360);
    let u = 0.18 + cos(angle) * random(0.12, 0.34);
    let y = 565 + sin(angle) * random(45, 115);
    let p = kneePt(u, y);
    let w = random(14, 32);
    let h = random(6, 13);

    // Cast shadow of small peeled tag
    brush.noStroke();
    brush.wash(PAL.barkCrevice, 145);
    drawShapePts([
      [p[0], p[1] + 2],
      [p[0] + w * 0.6, p[1] + h + 3],
      [p[0] + w, p[1] + 3]
    ], 0.25, true);

    // Curled chalky-white papery flake
    brush.wash(PAL.chalkPure, 235);
    drawShapePts([
      [p[0], p[1]],
      [p[0] + w * 0.45, p[1] - h],
      [p[0] + w, p[1] - 2],
      [p[0] + w * 0.55, p[1] + 3]
    ], 0.3, true);
    brush.noWash();

    brush.set("fine2H", PAL.barkCrevice, 0.65);
    brush.spline([
      [p[0], p[1]],
      [p[0] + w * 0.45, p[1] - h],
      [p[0] + w, p[1] - 2]
    ], 0.35);
  }
}

// ============================================================================
// 6. SHORT HORIZONTAL CHARCOAL DASHES (GRAZES, PORES, AND CREASES)
// ============================================================================

function drawHorizontalCharcoalDashes() {
  // A. Inside and around the scrape: dense, sharp horizontal charcoal dashes = the grazes
  for (let i = 0; i < 340; i++) {
    let u = random(-0.15, 0.56);
    let y = random(438, 692);
    let normD = pow((u - 0.19) / 0.38, 2) + pow((y - 565) / 125, 2);
    if (normD > 1.1) continue;

    // Foreshorten dash length and cluster along horizontal skid lines
    let dashSpan = random(0.012, 0.068) * (1.15 - normD * 0.4);
    let p1 = kneePt(u, y);
    let p2 = kneePt(u + dashSpan, y + random(-1.5, 1.5));

    let isCore = normD < 0.55 && random() < 0.65;
    let col = isCore ? PAL.charcoalDark : (random() < 0.5 ? PAL.charcoalMid : PAL.madderDeep);
    let w = isCore ? random(0.65, 1.35) : random(0.38, 0.85);

    brush.set(random() < 0.6 ? "barkCharcoal" : "charcoal", col, w);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Subtle chalk highlight lip directly below deep horizontal graze dashes
    if (isCore && random() < 0.35) {
      brush.set("chalkEdge", PAL.chalkPure, 0.45);
      brush.line(p1[0], p1[1] + 2.2, p2[0], p2[1] + 2.2);
    }
  }

  // B. Across the entire knee: birch-lenticel-like short horizontal charcoal dashes
  //    representing pores, micro-creases, and skin texture
  for (let i = 0; i < 620; i++) {
    let y = random(15, 1185);
    let u = random(-0.94, 0.94);

    // Avoid drawing over the adhered left wing of the plaster (drawn later, but cleaner)
    if (u > -0.74 && u < -0.08 && y > 460 && y < 675) continue;

    // Foreshorten horizontal dashes near the turning edges of the knee cylinder
    let cylForeshorten = sqrt(max(0.12, 1 - u * u));
    let spanU = random(0.006, 0.032) * cylForeshorten;

    let p1 = kneePt(u, y);
    let p2 = kneePt(u + spanU, y + random(-0.8, 0.8));

    // Darker/denser in creases (suprapatellar y~290, infrapatellar y~770) and shaded right flank
    let inCrease = abs(y - 290) < 55 || abs(y - 765) < 65 || abs(y - 365) < 40;
    let col = (u > 0.35 || inCrease)
      ? (random() < 0.45 ? PAL.charcoalMid : PAL.graphDeep)
      : (random() < 0.5 ? PAL.graphDark : PAL.barkShadow);

    let w = inCrease ? random(0.45, 0.9) : random(0.25, 0.58);
    brush.set(random() < 0.45 ? "barkCharcoal" : "2B", col, w);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // C. Longer segmented horizontal flexion creases above and below the patella
  const creaseRows = [215, 255, 292, 338, 378, 728, 768, 812, 858, 915];
  for (let cy of creaseRows) {
    let uCur = random(-0.68, -0.42);
    let uMax = random(0.42, 0.72);
    while (uCur < uMax) {
      let seg = random(0.035, 0.11);
      let pts = [
        kneePt(uCur, cy + random(-2, 2)),
        kneePt(uCur + seg * 0.5, cy + random(-2, 2)),
        kneePt(uCur + seg, cy + random(-2, 2))
      ];
      brush.set("barkCharcoal", PAL.charcoalMid, random(0.45, 0.85));
      brush.spline(pts, 0.3);

      // Tiny pale lower ridge catchlight on skin crease
      brush.set("chalkEdge", PAL.chalkWarm, 0.5);
      brush.line(pts[0][0], pts[0][1] + 2.5, pts[2][0], pts[2][1] + 2.5);

      uCur += seg + random(0.015, 0.055);
    }
  }
}

// ============================================================================
// 7. CAST SHADOW OF THE HALF-PEELED PLASTER
// ============================================================================

