  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.35);

  // Soft outer penumbra shadow
  brush.fill(PAL.graphDark, 95);
  let penumbra = [
    [522, 472],
    [610, 505],
    [735, 532],
    [855, 560],
    [935, 615],
    [915, 725],
    [795, 762],
    [645, 738],
    [525, 682]
  ];
  drawShapePts(penumbra, 0.3, true);

  // Deeper umbra shadow close to the peel line and under the curled arch
  brush.fill(PAL.graphDeep, 125);
  let umbra = [
    [524, 475],
    [590, 515],
