    brush.set("2B", y < 680 && x1 < 590 ? PAL.charcoalMid : PAL.graphDeep, random(0.4, 0.75));
    brush.line(x1 + random(-4, 8), y, x2 + random(-15, 15), y + random(8, 22));
  }
}

// ============================================================================
// 8. THE HALF-PEELED ADHESIVE PLASTER (FABRIC WEAVE & CURLING GAUZE EDGE)
// ============================================================================

// Parametric helper for the Left Adhered Wing of the plaster
// s in [0, 1] runs from left rounded tip (x ~ 255) to the peel seam (x ~ 532)
// v in [0, 1] runs from top edge (y ~ 468) to bottom edge (y ~ 674)
function adheredPlasterPt(s, v) {
  let u = lerp(-0.76, -0.10, s);
  let yCenter = 568 + s * 6;
  let halfH = 103;

  // Rounded stadium cap on the left end (s < 0.28)
  let capFactor = 1.0;
  if (s < 0.28) {
    let cs = constrain(s / 0.28, 0, 1);
    capFactor = sqrt(max(0.02, 1 - pow(1 - cs, 2)));
  }

  let vCentered = (v - 0.5) * 2 * capFactor; // in [-1, 1]
  // Slight fabric tension pinch near the peel line (s > 0.82)
  let peelLift = s > 0.82 ? pow((s - 0.82) / 0.18, 1.6) * 8 : 0;

  let p = kneePt(u, yCenter + vCentered * halfH);
  return [p[0], p[1] - peelLift];
}

// Parametric helper for the Right Peeled & Curling Wing of the plaster
// s in [0, 1] runs from the peel seam (s=0 at x~532) up and over the 3D arch
// to the tightly curled-back right tip (s=1)
function peeledPlasterPt(s, v) {
  let baseS = adheredPlasterPt(1.0, v);

  // Rounded stadium cap at the right tip (s > 0.76)
  let capFactor = 1.0;
  if (s > 0.76) {
    let cs = constrain((1.0 - s) / 0.24, 0, 1);
    capFactor = sqrt(max(0.04, 1 - pow(1 - cs, 2)));
  }
  let vEff = 0.5 + (v - 0.5) * capFactor;

  // 3D curling trajectory: rises off the knee, arches right, then curls back on itself
  let dx = 0;
  let dy = 0;
  if (s <= 0.74) {
    let t = s / 0.74;
    dx = 365 * sin(t * 92);
    // Arch lifts upward (negative dy) then sweeps slightly down
    dy = -62 * sin(t * 155) + 28 * t * t;
  } else {
    // Tight curl-back scroll at the right end (s from 0.74 to 1.0)
    let tc = (s - 0.74) / 0.26;
    let endX = 365 * sin(92);
    let endY = -62 * sin(155) + 28;
    dx = endX + 24 * sin(tc * 110) - 78 * pow(tc, 1.45);
    dy = endY + 46 * sin(tc * 135) + 18 * tc;
  }

  // Slight perspective narrowing & birch-like edge curl across width v
  let widthScale = 1.0 + 0.10 * sin(s * 160) - 0.08 * s;
  let edgeCurlY = pow((vEff - 0.5) * 2, 2) * 14 * sin(s * 180);

  let ySpan = (vEff - 0.5) * 206 * widthScale;
  let yMid = lerp(adheredPlasterPt(1.0, 0.5)[1], baseS[1], 0.15) + ySpan;

  return [baseS[0] + dx, yMid + dy + edgeCurlY];
}

function drawHalfPeeledPlaster() {
  // --------------------------------------------------------------------------
  // PART A: LEFT ADHERED WING (Conforming to the knee, fabric weave & holes)
  // --------------------------------------------------------------------------
  let adheredOutline = [];
  for (let s = 0; s <= 1.0; s += 0.04) adheredOutline.push(adheredPlasterPt(s, 0));
  for (let v = 0; v <= 1.0; v += 0.08) adheredOutline.push(adheredPlasterPt(1.0, v));
  for (let s = 1.0; s >= 0; s -= 0.04) adheredOutline.push(adheredPlasterPt(s, 1.0));
  for (let v = 1.0; v >= 0; v -= 0.08) adheredOutline.push(adheredPlasterPt(0, v));

  // Tiny contact shadow around adhered perimeter
  brush.noStroke();
  brush.wash(PAL.barkCrevice, 130);
  let adheredShadow = adheredOutline.map(p => [p[0] + 1.5, p[1] + 3.2]);
  drawShapePts(adheredShadow, 0.15, true);

  // Base bone/putty fabric body of adhered plaster
  brush.wash(PAL.plasterMid, 235);
  drawShapePts(adheredOutline, 0.15, true);

  // Birch-like papery chalky highlight sheets across upper-left of adhered wing
  for (let i = 0; i < 6; i++) {
    let s1 = random(0.05, 0.35);
    let s2 = s1 + random(0.35, 0.55);
    let v1 = random(0.06, 0.45);
    let v2 = v1 + random(0.18, 0.32);
    let sheet = [
      adheredPlasterPt(s1, v1),
      adheredPlasterPt(s2, v1),
      adheredPlasterPt(s2, v2),
      adheredPlasterPt(s1, v2)
    ];
    brush.wash(i % 2 === 0 ? PAL.plasterLight : PAL.chalkWarm, 155);
    drawShapePts(sheet, 0.15, true);
  }
  brush.noWash();

  // Subtle fabric creases & tension folds radiating from the peel seam
  for (let i = 0; i < 12; i++) {
    let vStart = random(0.12, 0.88);
    let vEnd = vStart + random(-0.18, 0.18);
    let sStart = random(0.35, 0.65);
    let p1 = adheredPlasterPt(sStart, vStart);
    let p2 = adheredPlasterPt((sStart + 1.0) * 0.5, (vStart + vEnd) * 0.5 + random(-0.04, 0.04));
    let p3 = adheredPlasterPt(0.99, vEnd);

    brush.set("2H", PAL.barkShadow, 0.55);
    brush.spline([p1, p2, p3], 0.35);
    brush.set("chalkEdge", PAL.chalkPure, 0.55);
    brush.spline([[p1[0], p1[1] - 2], [p2[0], p2[1] - 2], [p3[0], p3[1] - 2]], 0.35);
  }

  // HARD PENCIL FABRIC WEAVE on Adhered Wing (Warp & Weft orthogonal grid)
  // Horizontal warp threads
  for (let v = 0.02; v <= 0.98; v += 0.014) {
    let pts = [];
    for (let s = 0.01; s <= 0.99; s += 0.07) {
      let p = adheredPlasterPt(s, v);
      // Tiny thread crimp
      let crimp = sin(s * 1400 + v * 900) * 0.6;
      pts.push([p[0], p[1] + crimp]);
    }
    let col = v < 0.45 ? PAL.graphMid : PAL.barkShadow;
    brush.set("fine2H", col, random(0.45, 0.78));
    brush.spline(pts, 0.2);
  }

  // Vertical weft threads
  for (let s = 0.02; s <= 0.99; s += 0.013) {
    let pts = [];
    for (let v = 0.02; v <= 0.98; v += 0.08) {
      let p = adheredPlasterPt(s, v);
      let crimp = cos(v * 1400 + s * 900) * 0.6;
      pts.push([p[0] + crimp, p[1]]);
    }
    let col = s < 0.55 ? PAL.graphMid : PAL.barkShadow;
    brush.set("fine2H", col, random(0.45, 0.78));
    brush.spline(pts, 0.2);
  }

  // Perforation grid (Aeration Holes) on the adhered wing
  for (let s = 0.14; s <= 0.90; s += 0.095) {
    for (let v = 0.15; v <= 0.86; v += 0.115) {
      // Skip corners outside stadium cap
      if (s < 0.25 && (v < 0.24 || v > 0.76)) continue;
      let p = adheredPlasterPt(s, v);
      let r = 3.4;

      // Dark hole interior
      brush.noStroke();
      brush.wash(PAL.barkCrevice, 210);
      brush.circle(p[0], p[1], r, 0.15);
      brush.noWash();

      // Hard pencil upper-left inner rim shadow & chalk lower-right rim highlight
      brush.set("fine2H", PAL.charcoalDark, 0.8);
      brush.arc(p[0], p[1], r, 140, 330);
      brush.set("chalkEdge", PAL.chalkPure, 0.55);
      brush.arc(p[0] + 0.6, p[1] + 0.6, r, 320, 490);
    }
  }

  // Crisp hard-pencil outer border & chalky thickness bevel of adhered wing
  brush.set("chalkEdge", PAL.chalkPure, 0.95);
  let topBorderAdh = [];
  for (let s = 0; s <= 1.0; s += 0.04) topBorderAdh.push(adheredPlasterPt(s, 0.01));
  brush.spline(topBorderAdh, 0.2);

  brush.set("fine2H", PAL.barkCrevice, 0.9);
  brush.spline(adheredOutline, 0.2);

  // --------------------------------------------------------------------------
  // PART B: MICROSCOPIC STRETCHED ADHESIVE STRANDS AT THE PEEL SEAM
  // --------------------------------------------------------------------------
  for (let i = 0; i < 42; i++) {
    let v = random(0.05, 0.95);
    let sLift = random(0.02, 0.14);
    let pPlaster = peeledPlasterPt(sLift, v);
    let pSkin = adheredPlasterPt(1.0, v);
    pSkin[0] += random(4, 24);
    pSkin[1] += random(2, 12);

    let midX = lerp(pPlaster[0], pSkin[0], 0.5) - random(2, 7);
    let midY = lerp(pPlaster[1], pSkin[1], 0.5);

    brush.set("fine2H", PAL.plasterLight, random(0.45, 0.85));
    brush.spline([pPlaster, [midX, midY], pSkin], 0.35);

    if (random() < 0.5) {
      brush.set("chalkEdge", PAL.chalkPure, 0.38);
      brush.line(pPlaster[0], pPlaster[1], midX, midY);
    }
  }

  // --------------------------------------------------------------------------
  // PART C: RIGHT PEELED & CURLING WING (Underside + Curled Tip)
  // --------------------------------------------------------------------------
  // 1. Underside of peeled strip (s from 0.0 to 0.75)
  let underPoly = [];
  for (let s = 0; s <= 0.75; s += 0.03) underPoly.push(peeledPlasterPt(s, 0));
  for (let v = 0; v <= 1.0; v += 0.08) underPoly.push(peeledPlasterPt(0.75, v));
  for (let s = 0.75; s >= 0; s -= 0.03) underPoly.push(peeledPlasterPt(s, 1.0));
  for (let v = 1.0; v >= 0; v -= 0.08) underPoly.push(peeledPlasterPt(0, v));

  brush.noStroke();
  brush.wash(PAL.plasterUnder, 240);
  drawShapePts(underPoly, 0.18, true);

  // Subtle shading across the curved underside (darker near peel crease & before the tip roll)
  let creaseShade = [];
  for (let s = 0; s <= 0.16; s += 0.04) creaseShade.push(peeledPlasterPt(s, 0));
  for (let s = 0.16; s >= 0; s -= 0.04) creaseShade.push(peeledPlasterPt(s, 1.0));
  brush.wash(PAL.barkShadow, 110);
  drawShapePts(creaseShade, 0.18, true);

  // Luminous arch highlight where the underside catches cool overcast light (s = 0.22..0.56)
  let archLight = [];
  for (let s = 0.20; s <= 0.56; s += 0.04) archLight.push(peeledPlasterPt(s, 0.04));
  for (let s = 0.56; s >= 0.20; s -= 0.04) archLight.push(peeledPlasterPt(s, 0.96));
  brush.wash(PAL.plasterLight, 165);
  drawShapePts(archLight, 0.18, true);
  brush.noWash();

  // Faint fabric weave & aeration dots showing through the tacky adhesive underside
  for (let v = 0.04; v <= 0.96; v += 0.022) {
    let pts = [];
    for (let s = 0.02; s <= 0.73; s += 0.06) pts.push(peeledPlasterPt(s, v));
    brush.set("fine2H", PAL.plasterGlue, 0.48);
    brush.spline(pts, 0.22);
  }
  for (let s = 0.03; s <= 0.73; s += 0.02) {
    let pts = [];
    for (let v = 0.04; v <= 0.96; v += 0.08) pts.push(peeledPlasterPt(s, v));
    brush.set("fine2H", PAL.plasterGlue, 0.48);
    brush.spline(pts, 0.22);
  }

  // Exposed adhesive wing holes on the right side of the gauze pad (s = 0.56..0.72)
  for (let s = 0.58; s <= 0.71; s += 0.06) {
    for (let v = 0.16; v <= 0.84; v += 0.12) {
      let p = peeledPlasterPt(s, v);
      brush.set("fine2H", PAL.barkShadow, 0.65);
      brush.circle(p[0], p[1], 2.6, 0.2);
    }
  }

  // --------------------------------------------------------------------------
  // PART D: THE ABSORBENT GAUZE PAD & CURLING GAUZE EDGE IN HARD PENCIL
  // --------------------------------------------------------------------------
  // The gauze pad sits on the underside from s = 0.04 to s = 0.54, v = 0.13 to 0.87.
  // Its edges lift and curl away from the plaster backing like papery birch bark!
  function gauzePt(gs, gv) {
    let s = lerp(0.04, 0.54, gs);
    let v = lerp(0.13, 0.87, gv);
    let p = peeledPlasterPt(s, v);

    // Curling lift at the edges of the gauze pad (especially bottom-right & left edge)
    let edgeDistS = min(gs, 1 - gs);
    let edgeDistV = min(gv, 1 - gv);
    let curlLift = 0;
    if (edgeDistS < 0.18) curlLift += pow((0.18 - edgeDistS) / 0.18, 1.5) * 14;
    if (edgeDistV < 0.18) curlLift += pow((0.18 - edgeDistV) / 0.18, 1.5) * 11;

    // Extra dramatic curl at the lower-right corner of the gauze pad
    let cornerCurl = exp(-pow((gs - 0.92) / 0.22, 2) - pow((gv - 0.88) / 0.22, 2)) * 18;

    return [p[0] - (curlLift + cornerCurl) * 0.45, p[1] - (curlLift + cornerCurl)];
  }

  let gauzeOutline = [];
  for (let gs = 0; gs <= 1.0; gs += 0.05) gauzeOutline.push(gauzePt(gs, 0));
  for (let gv = 0; gv <= 1.0; gv += 0.06) gauzeOutline.push(gauzePt(1.0, gv));
  for (let gs = 1.0; gs >= 0; gs -= 0.05) gauzeOutline.push(gauzePt(gs, 1.0));
  for (let gv = 1.0; gv >= 0; gv -= 0.06) gauzeOutline.push(gauzePt(0, gv));

  // Cast shadow of the curling gauze pad onto the plaster backing strip
  brush.noStroke();
  brush.wash(PAL.barkCrevice, 165);
  let gauzeShadow = gauzeOutline.map(p => [p[0] + 5, p[1] + 9]);
  drawShapePts(gauzeShadow, 0.2, true);

  brush.wash(PAL.barkShadow, 110);
  let gauzePenumbra = gauzeOutline.map(p => [p[0] + 9, p[1] + 15]);
  drawShapePts(gauzePenumbra, 0.22, true);

  // Chalky white cotton gauze pad base
  brush.wash(PAL.gauzeWhite, 245);
  drawShapePts(gauzeOutline, 0.18, true);
  brush.noWash();

  // Raw Sienna & Pink Madder transfer stain in the center of the lifted gauze pad
  // (where the pad was pressed against the raw scrape)
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.65, 0.45);

  brush.fill(PAL.siennaLight, 145);
  let stain1 = [];
  for (let a = 0; a < 360; a += 30) {
    let gs = 0.44 + cos(a) * (0.28 + random(-0.04, 0.04));
    let gv = 0.52 + sin(a) * (0.26 + random(-0.04, 0.04));
    stain1.push(gauzePt(constrain(gs, 0.08, 0.92), constrain(gv, 0.08, 0.92)));
  }
  drawShapePts(stain1, 0.3, true);

  brush.fill(PAL.madderMid, 155);
  let stain2 = [];
  for (let a = 0; a < 360; a += 30) {
    let gs = 0.40 + cos(a) * (0.20 + random(-0.04, 0.04));
    let gv = 0.50 + sin(a) * (0.19 + random(-0.04, 0.04));
    stain2.push(gauzePt(constrain(gs, 0.1, 0.9), constrain(gv, 0.1, 0.9)));
  }
  drawShapePts(stain2, 0.3, true);

  brush.fill(PAL.siennaDeep, 130);
  let stain3 = [];
  for (let a = 0; a < 360; a += 36) {
    let gs = 0.36 + cos(a) * 0.12;
    let gv = 0.48 + sin(a) * 0.12;
    stain3.push(gauzePt(gs, gv));
  }
  drawShapePts(stain3, 0.3, true);
  brush.noFill();

  // HARD PENCIL GAUZE WEAVE & CURLING GAUZE EDGE
  // Open cheesecloth cotton mesh across the gauze pad
  for (let gv = 0.01; gv <= 0.99; gv += 0.018) {
    let pts = [];
    for (let gs = 0.0; gs <= 1.0; gs += 0.08) {
      let p = gauzePt(gs, gv);
      let wave = sin(gs * 950 + gv * 600) * 0.9;
      pts.push([p[0], p[1] + wave]);
    }
    let isEdge = gv < 0.08 || gv > 0.92;
    brush.set("fine2H", isEdge ? PAL.charcoalMid : PAL.graphMid, isEdge ? 0.85 : 0.55);
    brush.spline(pts, 0.25);
  }

  for (let gs = 0.01; gs <= 0.99; gs += 0.018) {
    let pts = [];
    for (let gv = 0.0; gv <= 1.0; gv += 0.08) {
      let p = gauzePt(gs, gv);
      let wave = cos(gv * 950 + gs * 600) * 0.9;
      pts.push([p[0] + wave, p[1]]);
    }
    let isEdge = gs < 0.08 || gs > 0.92;
    brush.set("fine2H", isEdge ? PAL.charcoalMid : PAL.graphMid, isEdge ? 0.85 : 0.55);
    brush.spline(pts, 0.25);
  }

  // Folded, curling gauze margin along the right & bottom edges of the gauze pad
  let curledGauzeLip = [];
  for (let gs = 0.15; gs <= 1.0; gs += 0.05) {
    let p = gauzePt(gs, 0.98);
    curledGauzeLip.push([p[0] - 2, p[1] - 5 * sin(gs * 180)]);
  }
  for (let gv = 0.98; gv >= 0.12; gv -= 0.05) {
    let p = gauzePt(0.98, gv);
    curledGauzeLip.push([p[0] - 6 * sin(gv * 180), p[1] - 2]);
  }
  brush.set("chalkEdge", PAL.chalkPure, 1.1);
  brush.spline(curledGauzeLip, 0.28);
  brush.set("fine2H", PAL.charcoalDark, 0.85);
  brush.spline(curledGauzeLip, 0.28);

  // Frayed, curling individual gauze threads & loops along all four edges of the pad
  for (let i = 0; i < 145; i++) {
    let edge = floor(random(4));
    let gs = edge === 0 ? 0 : (edge === 1 ? 1 : random(0, 1));
    let gv = edge === 2 ? 0 : (edge === 3 ? 1 : random(0, 1));
    let p0 = gauzePt(gs, gv);

    let len = random(6, 22);
    let ang = edge === 0 ? random(145, 225)
            : edge === 1 ? random(-45, 45)
            : edge === 2 ? random(-135, -45)
                         : random(45, 135);
    let curlAng = ang + random(-65, 65);

    let p1 = [p0[0] + cos(ang) * len * 0.55, p0[1] + sin(ang) * len * 0.55];
    let p2 = [p1[0] + cos(curlAng) * len * 0.5, p1[1] + sin(curlAng) * len * 0.5];

    brush.set("fine2H", random() < 0.6 ? PAL.charcoalMid : PAL.graphDark, random(0.45, 0.85));
    brush.spline([p0, p1, p2], 0.45);

    if (random() < 0.45) {
      brush.set("chalkEdge", PAL.chalkPure, 0.4);
      brush.spline([[p0[0], p0[1] - 0.8], [p1[0], p1[1] - 0.8], [p2[0], p2[1] - 0.8]], 0.45);
    }
  }

  // --------------------------------------------------------------------------
  // PART E: THE CURLED-OVER RIGHT TIP OF THE PLASTER (s = 0.73 to 1.0)
  // --------------------------------------------------------------------------
  // Where the tip of the plaster rolls over in a tight birch-bark scroll,
  // showing the woven outer fabric face again and casting a shadow on the underside!
  let tipRollPoly = [];
  for (let s = 0.73; s <= 1.0; s += 0.03) tipRollPoly.push(peeledPlasterPt(s, 0));
  for (let v = 0; v <= 1.0; v += 0.08) tipRollPoly.push(peeledPlasterPt(1.0, v));
  for (let s = 1.0; s >= 0.73; s -= 0.03) tipRollPoly.push(peeledPlasterPt(s, 1.0));
  for (let v = 1.0; v >= 0; v -= 0.08) tipRollPoly.push(peeledPlasterPt(0.73, v));

  // Self-shadow cast by the curled tip onto the plaster underside
  brush.noStroke();
  brush.wash(PAL.barkCrevice, 160);
  let tipShadow = [];
  for (let v = 0.04; v <= 0.96; v += 0.08) {
    let p = peeledPlasterPt(0.98, v);
    tipShadow.push([p[0] - 14, p[1] + 8]);
  }
  for (let v = 0.96; v >= 0.04; v -= 0.08) {
    let p = peeledPlasterPt(0.84, v);
    tipShadow.push([p[0] - 2, p[1] + 4]);
  }
  drawShapePts(tipShadow, 0.22, true);

  // Outer woven fabric surface of the curled tip
  brush.wash(PAL.plasterMid, 240);
  drawShapePts(tipRollPoly, 0.2, true);

  // Chalky highlight along the apex of the 3D turn (s ~ 0.74..0.82)
  let rollHighlight = [];
  for (let v = 0.03; v <= 0.97; v += 0.08) rollHighlight.push(peeledPlasterPt(0.74, v));
  for (let v = 0.97; v >= 0.03; v -= 0.08) rollHighlight.push(peeledPlasterPt(0.82, v));
  brush.wash(PAL.chalkPure, 185);
  drawShapePts(rollHighlight, 0.2, true);
  brush.noWash();

  // Hard pencil fabric weave on the curled tip
  for (let v = 0.05; v <= 0.95; v += 0.02) {
    let pts = [];
    for (let s = 0.73; s <= 0.99; s += 0.04) pts.push(peeledPlasterPt(s, v));
    brush.set("fine2H", PAL.barkShadow, 0.65);
    brush.spline(pts, 0.25);
  }
  for (let s = 0.74; s <= 0.99; s += 0.022) {
    let pts = [];
    for (let v = 0.05; v <= 0.95; v += 0.08) pts.push(peeledPlasterPt(s, v));
    brush.set("fine2H", PAL.barkShadow, 0.65);
    brush.spline(pts, 0.25);
  }

  // Foreshortened oval aeration holes on the curled tip
  for (let s = 0.79; s <= 0.94; s += 0.065) {
    for (let v = 0.20; v <= 0.80; v += 0.13) {
      let p = peeledPlasterPt(s, v);
      brush.set("fine2H", PAL.charcoalDark, 0.75);
      brush.arc(p[0], p[1], 2.5, 110, 310);
      brush.set("chalkEdge", PAL.chalkPure, 0.45);
      brush.arc(p[0] + 0.5, p[1] + 0.5, 2.5, 300, 470);
    }
  }

  // Crisp hard-pencil contours and papery thickness edges along the entire peeled strip
  let topPeeledEdge = [];
  let botPeeledEdge = [];
  for (let s = 0; s <= 1.0; s += 0.03) {
    topPeeledEdge.push(peeledPlasterPt(s, 0));
    botPeeledEdge.push(peeledPlasterPt(s, 1.0));
  }

  brush.set("chalkEdge", PAL.chalkPure, 1.15);
  brush.spline(topPeeledEdge.map(p => [p[0], p[1] + 1.5]), 0.22);
  brush.spline(botPeeledEdge.map(p => [p[0], p[1] - 1.5]), 0.22);

  brush.set("fine2H", PAL.charcoalDark, 0.95);
  brush.spline(topPeeledEdge, 0.22);
  brush.spline(botPeeledEdge, 0.22);

  // Frayed fabric edge fibers along the peeled plaster rim (birch-bark papery edge feel)
  for (let s = 0.05; s <= 0.95; s += 0.025) {
    for (let side of [0, 1]) {
      let p = peeledPlasterPt(s, side);
      let dirY = side === 0 ? -1 : 1;
      brush.set("fine2H", PAL.barkShadow, 0.55);
      brush.line(p[0], p[1], p[0] + random(-6, 6), p[1] + dirY * random(3, 9));
    }
  }
}

