// 9. FINAL CLINICAL MICRO-DETAILS & BIRCH-BARK TEXTURAL UNITY
// ============================================================================

function drawFinalMicroDetails() {
  // Fine chalky highlights on tiny skin pores, scrape ridges, and patellar dome
  for (let i = 0; i < 180; i++) {
    let u = random(-0.65, 0.48);
    let y = random(280, 740);
    // Skip adhered plaster region
    if (u > -0.74 && u < -0.09 && y > 465 && y < 675) continue;

    let p = kneePt(u, y);
    let len = random(3, 11);
    brush.set("chalkEdge", PAL.chalkPure, random(0.35, 0.75));
    brush.line(p[0], p[1], p[0] + len, p[1] + random(-1, 1));
  }

  // Pinpoint capillary & crust accents in raw sienna and pink madder along the exposed graze
  for (let i = 0; i < 95; i++) {
    let u = random(-0.08, 0.52);
    let y = random(465, 665);
    let normD = pow((u - 0.22) / 0.32, 2) + pow((y - 565) / 105, 2);
    if (normD > 0.95) continue;

    let p = kneePt(u, y);
    let col = random() < 0.55 ? PAL.madderDeep : PAL.siennaDeep;
    brush.set("fine2H", col, random(0.65, 1.15));
    brush.line(p[0], p[1], p[0] + random(2, 6), p[1] + random(-0.8, 0.8));
  }

  // Ultra-fine hard pencil (2H) clinical grain across the patella & shin
  for (let i = 0; i < 240; i++) {
    let u = random(-0.88, 0.88);
    let y = random(40, 1160);
    let p1 = kneePt(u, y);
    let p2 = kneePt(u + random(0.01, 0.03), y + random(-2, 2));
    brush.set("fine2H", PAL.graphMid, random(0.25, 0.48));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

