// Helper: closed shape using beginShape/vertex for reliable fill/wash/hatch behavior
function drawClosedShape(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Helper: ellipse approximation as closed vertex shape
function drawEllipseShape(cx, cy, rx, ry, rotDeg = 0, steps = 28, curvature = 0.4) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  drawClosedShape(pts, curvature);
}

// Helper: motion-blurred spline (primary crisp stroke + shutter-dragged ghost trails)
function motionSpline(bName, colHex, w, pts, dx, dy, ghosts = 3, curv = 0.5) {
  for (let g = ghosts; g >= 1; g--) {
    let frac = g / ghosts;
    let shifted = pts.map(p => [
      p[0] + dx * frac + random(-0.8, 0.8),
      p[1] + dy * frac + random(-0.8, 0.8),
      (p[2] !== undefined ? p[2] : 1) * (1 - frac * 0.45)
    ]);
    brush.set("glaze", colHex, w * 0.35 * (1 - frac * 0.3));
    brush.spline(shifted, curv);
  }
  brush.set(bName, colHex, w);
  brush.spline(pts, curv);
}

