// Smoothly fillet a polyline of [x, y, bendRadius] into evenly spaced samples with normals
function buildTubeGeometry(rawPts, stepLen = 4.5) {
  let filleted = [];
  const n = rawPts.length;
  if (n < 2) return [];

  filleted.push([rawPts[0][0], rawPts[0][1]]);

  for (let i = 1; i < n - 1; i++) {
    let p0 = rawPts[i - 1];
    let p1 = rawPts[i];
    let p2 = rawPts[i + 1];
    let r = p1[2] !== undefined ? p1[2] : 18;

    let vx1 = p0[0] - p1[0];
    let vy1 = p0[1] - p1[1];
    let len1 = Math.hypot(vx1, vy1) || 1;

    let vx2 = p2[0] - p1[0];
    let vy2 = p2[1] - p1[1];
    let len2 = Math.hypot(vx2, vy2) || 1;

    let d = Math.min(r, len1 * 0.46, len2 * 0.46);
    let ax = p1[0] + (vx1 / len1) * d;
    let ay = p1[1] + (vy1 / len1) * d;
    let bx = p1[0] + (vx2 / len2) * d;
    let by = p1[1] + (vy2 / len2) * d;

    let arcSteps = Math.max(5, Math.ceil((d * 1.8) / stepLen));
    for (let s = 0; s <= arcSteps; s++) {
      let t = s / arcSteps;
      let omt = 1 - t;
      // Rational quadratic bezier approximation of circular bend
      let w = 0.78;
      let denom = omt * omt + 2 * w * omt * t + t * t;
      let qx = (omt * omt * ax + 2 * w * omt * t * p1[0] + t * t * bx) / denom;
      let qy = (omt * omt * ay + 2 * w * omt * t * p1[1] + t * t * by) / denom;
      filleted.push([qx, qy]);
    }
  }

  filleted.push([rawPts[n - 1][0], rawPts[n - 1][1]]);

  // Resample at uniform stepLen
  let samples = [];
  samples.push({ x: filleted[0][0], y: filleted[0][1] });
  let accum = 0;
  for (let i = 1; i < filleted.length; i++) {
    let x0 = filleted[i - 1][0], y0 = filleted[i - 1][1];
    let x1 = filleted[i][0], y1 = filleted[i][1];
    let seg = Math.hypot(x1 - x0, y1 - y0);
    if (seg < 0.01) continue;
    let dist = stepLen - accum;
    while (dist <= seg) {
      let u = dist / seg;
      samples.push({ x: x0 + (x1 - x0) * u, y: y0 + (y1 - y0) * u });
      dist += stepLen;
    }
    accum = seg - (dist - stepLen);
  }
  let lastF = filleted[filleted.length - 1];
  let lastS = samples[samples.length - 1];
  if (Math.hypot(lastF[0] - lastS.x, lastF[1] - lastS.y) > 1.0) {
    samples.push({ x: lastF[0], y: lastF[1] });
  }

  // Compute smoothed tangents, normals, and curvature
  for (let i = 0; i < samples.length; i++) {
    let prev = samples[Math.max(0, i - 1)];
    let next = samples[Math.min(samples.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let l = Math.hypot(dx, dy) || 1;
    samples[i].tx = dx / l;
    samples[i].ty = dy / l;
    // Normal points upward when moving left-to-right
    samples[i].nx = dy / l;
    samples[i].ny = -dx / l;
  }

  for (let i = 0; i < samples.length; i++) {
    let p = samples[Math.max(0, i - 1)];
    let nPt = samples[Math.min(samples.length - 1, i + 1)];
    let curv = Math.hypot(nPt.tx - p.tx, nPt.ty - p.ty);
    samples[i].curv = curv;
  }

  return samples;
}

function makeOffsetSplinePts(samples, offset, sx = 0, sy = 0, stride = 2) {
  let pts = [];
  for (let i = 0; i < samples.length; i += stride) {
    let s = samples[i];
    pts.push([s.x + s.nx * offset + sx, s.y + s.ny * offset + sy, 1.0]);
  }
  let last = samples[samples.length - 1];
  let endPt = [last.x + last.nx * offset + sx, last.y + last.ny * offset + sy, 1.0];
  if (pts.length === 0 || Math.hypot(pts[pts.length - 1][0] - endPt[0], pts[pts.length - 1][1] - endPt[1]) > 0.5) {
    pts.push(endPt);
  }
  return pts;
}

// Render a cast shadow from a glass tube onto the frame/backdrop
function drawTubeShadow(samples, R, dx = 7, dy = 11, opacityMult = 1.0) {
  if (samples.length < 3) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("phosphor", "#221e1a", (R / 6.5) * opacityMult);
  brush.spline(makeOffsetSplinePts(samples, 0, dx, dy, 3), 0.45);
  brush.set("charcoal", "#1a1714", 0.55 * opacityMult);
  brush.spline(makeOffsetSplinePts(samples, R * 0.25, dx, dy, 3), 0.45);
}

// Render a hyperreal bent glass neon tube (coral, mint, or painted block-out)
function drawNeonTube(rawPts, R, style = "coral") {
  let samples = buildTubeGeometry(rawPts, 4.2);
  if (samples.length < 3) return samples;

  brush.noFill();
  brush.noWash();
  brush.noHatch();

  let pal;
  if (style === "coral") {
    pal = {
      outerGlassFill: "#b8ae9f",
      phosphorBase: "#df9d8b",
      phosphorLight: "#f0bfb0",
      phosphorWarm: "#e6ab99",
      phosphorShade: "#b57868",
      phosphorDeep: "#8f5d50",
      innerWallL: "#66524b",
      innerWallD: "#4f3e38",
      outerWallL: "#382f2a",
      outerWallD: "#211c18",
      specMain: "#faf6ee",
      specPair: "#e8e0d3",
      reflBottom: "#d4c8ba"
    };
  } else if (style === "mint") {
    pal = {
      outerGlassFill: "#b4b2a5",
      phosphorBase: "#9ec2b2",
      phosphorLight: "#c4dfd2",
      phosphorWarm: "#add0c0",
      phosphorShade: "#78998a",
      phosphorDeep: "#5a786b",
      innerWallL: "#4d5e56",
      innerWallD: "#394740",
      outerWallL: "#2e302c",
      outerWallD: "#1e201d",
      specMain: "#faf7f0",
      specPair: "#e3e6de",
      reflBottom: "#c9d1c9"
    };
  } else {
    // Painted matte black/sepia block-out return tubing
    pal = {
      outerGlassFill: "#4a443e",
      phosphorBase: "#3b3530",
      phosphorLight: "#544c45",
      phosphorWarm: "#453e38",
      phosphorShade: "#292420",
      phosphorDeep: "#1c1815",
      innerWallL: "#332e29",
      innerWallD: "#211d1a",
      outerWallL: "#1c1916",
      outerWallD: "#12100e",
      specMain: "#a89f93",
      specPair: "#787066",
      reflBottom: "#59524a"
    };
  }

  let wScale = R / 11.0;

  // 1. Subtle glass cylinder bed (clear outer glass refraction)
  brush.set("phosphor", pal.outerGlassFill, 0.72 * wScale);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.62, 0, 0, 2), 0.45);
  brush.spline(makeOffsetSplinePts(samples, R * 0.62, 0, 0, 2), 0.45);

  // 2. Internal powdery phosphor coating (or matte block-out paint)
  brush.set("phosphor", pal.phosphorBase, 0.95 * wScale);
  brush.spline(makeOffsetSplinePts(samples, 0, 0, 0, 2), 0.45);

  brush.set("phosphor", pal.phosphorWarm, 0.78 * wScale);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.22, 0, 0, 2), 0.45);

  brush.set("phosphor", pal.phosphorLight, 0.62 * wScale);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.42, 0, 0, 2), 0.45);

  // Underside cylindrical core shadow inside the phosphor
  brush.set("phosphor", pal.phosphorShade, 0.75 * wScale);
  brush.spline(makeOffsetSplinePts(samples, R * 0.34, 0, 0, 2), 0.45);

  brush.set("cpencil", pal.phosphorDeep, 0.85 * wScale);
  brush.spline(makeOffsetSplinePts(samples, R * 0.56, 0, 0, 2), 0.45);

  // Fine chalky grain inside the phosphor tube
  brush.set("2H", pal.phosphorLight, 0.45 * wScale);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.12, 0, 0, 2), 0.45);

  // 3. Lower internal glass reflection line
  brush.set("glassPen", pal.reflBottom, 0.62 * wScale);
  brush.spline(makeOffsetSplinePts(samples, R * 0.66, 0, 0, 2), 0.45);

  // 4. CRISP PAIRED WALL LINES (Outer wall + Inner wall on both sides of the tube)
  // Side A (-R and -0.75*R)
  brush.set("glassPen", pal.innerWallL, 0.68 * wScale);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.74, 0, 0, 2), 0.45);

  brush.set("rotring", pal.outerWallL, 0.52 * wScale);
  brush.spline(makeOffsetSplinePts(samples, -R, 0, 0, 2), 0.45);

  // Side B (+0.75*R and +R)
  brush.set("glassPen", pal.innerWallD, 0.68 * wScale);
  brush.spline(makeOffsetSplinePts(samples, R * 0.74, 0, 0, 2), 0.45);

  brush.set("rotring", pal.outerWallD, 0.58 * wScale);
  brush.spline(makeOffsetSplinePts(samples, R, 0, 0, 2), 0.45);

  // 5. CRISP PAIRED SPECULAR HIGHLIGHT LINES along the glass cylinder wall
  let specWeight1 = style === "painted" ? 0.55 * wScale : 0.88 * wScale;
  let specWeight2 = style === "painted" ? 0.42 * wScale : 0.65 * wScale;

  brush.set("glassPen", pal.specMain, specWeight1);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.48, 0, 0, 2), 0.45);

  brush.set("glassPen", pal.specPair, specWeight2);
  brush.spline(makeOffsetSplinePts(samples, -R * 0.26, 0, 0, 2), 0.45);

  // 6. Cross-contour glass rings & refraction ticks at sharp bends
  for (let i = 3; i < samples.length - 3; i += 2) {
    let s = samples[i];
    if (s.curv > 0.22) {
      let ringPts = [
        [s.x - s.nx * R * 0.85, s.y - s.ny * R * 0.85, 0.5],
        [s.x - s.tx * R * 0.28, s.y - s.ty * R * 0.28, 0.9],
        [s.x + s.nx * R * 0.85, s.y + s.ny * R * 0.85, 0.5]
      ];
      brush.set("glassPen", pal.innerWallL, 0.48);
      brush.spline(ringPts, 0.5);

      // Bright crescent pinch highlight on the bend
      let pinchPts = [
        [s.x - s.nx * R * 0.58 - s.tx * 2, s.y - s.ny * R * 0.58 - s.ty * 2, 0.6],
        [s.x - s.nx * R * 0.18 - s.tx * 4, s.y - s.ny * R * 0.18 - s.ty * 4, 1.0],
        [s.x + s.nx * R * 0.35 - s.tx * 2, s.y + s.ny * R * 0.35 - s.ty * 2, 0.6]
      ];
      brush.set("glassPen", pal.specMain, 0.65);
      brush.spline(pinchPts, 0.5);
    }
  }

  // 7. Settled dust along upper-facing horizontal surfaces of the glass tube
  for (let i = 2; i < samples.length - 2; i++) {
    let s = samples[i];
    // Upper edge in screen coordinates (y pointing down)
    let upX = s.nx * (s.ny < 0 ? 1 : -1);
    let upY = -Math.abs(s.ny);
    if (Math.abs(s.tx) > 0.55) {
      // Nearly horizontal segment collects dust on its top ridge
      let dx = s.x + upX * (R * 0.86);
      let dy = s.y + upY * (R * 0.86);
      brush.set("cpencil", "#c7beaf", 0.52 * wScale);
      brush.line(dx - s.tx * 3.5, dy - s.ty * 3.5, dx + s.tx * 3.5, dy + s.ty * 3.5);
      if (i % 3 === 0) {
        brush.set("2H", "#dbd3c5", 0.38);
        brush.line(dx - 2, dy - 1.2, dx + 2.5, dy - 0.5);
      }
    }
  }

  return samples;
}

// Chalky collar where black block-out paint stops on clear/phosphor glass
function drawPaintCollar(x, y, nx, ny, R) {
  brush.noFill();
  brush.noWash();
  let tx = -ny, ty = nx;
  let pts1 = [
    [x - nx * R, y - ny * R, 0.8],
    [x + tx * (R * 0.35), y + ty * (R * 0.35), 1.0],
    [x + nx * R, y + ny * R, 0.8]
  ];
  let pts2 = [
    [x - nx * R + tx * 3, y - ny * R + ty * 3, 0.7],
    [x + tx * (R * 0.35 + 3), y + ty * (R * 0.35 + 3), 1.0],
    [x + nx * R + tx * 3, y + ny * R + ty * 3, 0.7]
  ];
  brush.set("rotring", "#1f1b18", 0.55);
  brush.spline(pts1, 0.5);
  brush.set("cpencil", "#7d746a", 0.45);
  brush.spline(pts2, 0.5);
}

// Clear glass elevation post (standoff) with U-cradle and twisted copper tie-wire
function drawGlassStandoff(x, y, barY, R, cradleonly = false) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  if (!cradleonly) {
    // Metal L-tab welded to the frame crossbar
    brush.set("marker", "#2b2622", 0.65);
    brush.line(x - 6, barY - 3, x + 6, barY - 3);
    brush.line(x - 5, barY + 2, x + 5, barY + 2);
    brush.set("rotring", "#171412", 0.42);
    brush.rect(x - 7, barY - 5, 14, 9, "corner");
    // Dusty top of metal tab
    brush.set("cpencil", "#a89f91", 0.45);
    brush.line(x - 7, barY - 5.5, x + 7, barY - 5.5);

    // Clear glass stem from barY to (x, y)
    let stemTopY = Math.min(y, barY);
    let stemBotY = Math.max(y, barY);
    brush.set("glassPen", "#4a433c", 0.52);
    brush.line(x - 3.2, stemTopY, x - 3.2, stemBotY);
    brush.line(x + 3.2, stemTopY, x + 3.2, stemBotY);
    // Paired inner glass wall lines on stem
    brush.set("glassPen", "#787067", 0.38);
    brush.line(x - 1.8, stemTopY, x - 1.8, stemBotY);
    brush.line(x + 1.8, stemTopY, x + 1.8, stemBotY);
    // Bright highlight down the stem
    brush.set("glassPen", "#f2ece1", 0.55);
    brush.line(x - 0.8, stemTopY + 2, x - 0.8, stemBotY - 2);
  } else {
    // U-shaped glass cradle arms + twisted copper tie-wires wrapping over the front of the tube
    let rC = R + 2.8;
    brush.set("glassPen", "#3d3630", 0.55);
    brush.arc(x, y, rC, 15, 165);
    brush.set("glassPen", "#f5f0e6", 0.55);
    brush.arc(x, y, rC - 1.4, 22, 158);

    // Fine copper tie-wire wrapped diagonally across the tube with twisted pigtails
    brush.set("rotring", "#3b2316", 0.48);
    brush.line(x - rC, y - 3, x + rC, y + 4);
    brush.line(x - rC, y + 4, x + rC, y - 3);
    brush.set("glassPen", "#c78c63", 0.48);
    brush.line(x - rC + 1, y - 3.6, x + rC - 1, y + 3.4);
    brush.line(x - rC + 1, y + 3.4, x + rC - 1, y - 3.6);

    // Twisted wire pigtail sticking out to the side
    brush.set("rotring", "#3b2316", 0.38);
    brush.line(x + rC, y - 2, x + rC + 8, y - 6);
    brush.line(x + rC, y - 0.5, x + rC + 7, y - 4);
    brush.set("glassPen", "#d9a57e", 0.35);
    brush.line(x + rC + 1, y - 2.5, x + rC + 7, y - 5.5);
  }
}

// Blackened electrode cap with rubber boot, blackened glass chamber, and spring wire clip
function drawElectrodeCap(x, y, dirAngle, R = 11, wireToX = null, wireToY = null) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  let rad = (dirAngle * Math.PI) / 180;
  let tx = Math.cos(rad);
  let ty = Math.sin(rad);
  let nx = -ty;
  let ny = tx;

  let bootLen = R * 2.55;
  let bootR = R * 1.18;

  // Cast shadow of the electrode boot
  brush.set("charcoal", "#171412", 0.85);
  brush.line(x + 5, y + 8, x + tx * bootLen + 5, y + ty * bootLen + 8);

  // Soot-blackened glass transition neck before the rubber cap
  let neckLen = R * 0.9;
  for (let s = -0.8; s <= 0.8; s += 0.25) {
    let col = s < -0.1 ? "#453e38" : s < 0.3 ? "#2b2622" : "#1a1714";
    brush.set("cpencil", col, 0.65);
    brush.line(
      x - tx * neckLen + nx * R * s,
      y - ty * neckLen + ny * R * s,
      x + nx * R * s,
      y + ny * R * s
    );
  }
  // Faint internal mica ring & cylindrical metal electrode visible inside smoked glass
  brush.set("glassPen", "#8c7f70", 0.42);
  brush.line(
    x - tx * neckLen * 0.6 - nx * R * 0.52,
    y - ty * neckLen * 0.6 - ny * R * 0.52,
    x - tx * neckLen * 0.6 + nx * R * 0.52,
    y - ty * neckLen * 0.6 + ny * R * 0.52
  );
  // Paired glass wall highlight over the blackened glass neck
  brush.set("glassPen", "#ded6c8", 0.52);
  brush.line(
    x - tx * neckLen - nx * R * 0.48,
    y - ty * neckLen - ny * R * 0.48,
    x - nx * R * 0.48,
    y - ny * R * 0.48
  );
  brush.set("rotring", "#171412", 0.52);
  brush.line(x - tx * neckLen - nx * R, y - ty * neckLen - ny * R, x - nx * R, y - ny * R);
  brush.line(x - tx * neckLen + nx * R, y - ty * neckLen + ny * R, x + nx * R, y + ny * R);

  // Blackened rubber/mica electrode cap body (ribbed cylindrical boot)
  for (let s = -0.9; s <= 0.9; s += 0.2) {
    let c = s < -0.35 ? "#4a433c" : s < 0.15 ? "#2e2925" : "#181512";
    brush.set("marker", c, 0.48);
    brush.line(
      x + nx * bootR * s,
      y + ny * bootR * s,
      x + tx * bootLen + nx * bootR * 0.78 * s,
      y + ty * bootLen + ny * bootR * 0.78 * s
    );
  }

  // Ribbed rings along the blackened cap + dust in crevices
  let ribs = 5;
  for (let r = 0; r <= ribs; r++) {
    let u = r / ribs;
    let rx = x + tx * (bootLen * u);
    let ry = y + ty * (bootLen * u);
    let rr = bootR * (1 - u * 0.2);
    brush.set("rotring", "#120f0d", 0.52);
    brush.line(rx - nx * rr, ry - ny * rr, rx + nx * rr, ry + ny * rr);
    if (r < ribs) {
      brush.set("glassPen", "#8a8073", 0.38);
      brush.line(
        rx + tx * 2 - nx * rr * 0.85,
        ry + ty * 2 - ny * rr * 0.85,
        rx + tx * 2 + nx * rr * 0.3,
        ry + ty * 2 + ny * rr * 0.3
      );
    }
  }

  // Outline of blackened electrode cap
  brush.set("rotring", "#14110f", 0.55);
  brush.line(x - nx * bootR, y - ny * bootR, x + tx * bootLen - nx * bootR * 0.78, y + ty * bootLen - ny * bootR * 0.78);
  brush.line(x + nx * bootR, y + ny * bootR, x + tx * bootLen + nx * bootR * 0.78, y + ty * bootLen + ny * bootR * 0.78);

  // Settled dust on top of electrode boot
  brush.set("cpencil", "#bfb6a6", 0.55);
  let topSign = ny < 0 ? 1 : -1;
  brush.line(
    x + nx * bootR * topSign,
    y + ny * bootR * topSign,
    x + tx * bootLen + nx * bootR * 0.78 * topSign,
    y + ty * bootLen + ny * bootR * 0.78 * topSign
  );

  // Metallic spring WIRE CLIP clamping the electrode terminal
  let tipX = x + tx * (bootLen + 3);
  let tipY = y + ty * (bootLen + 3);

  // Pinched glass exhaust tip-off & brass terminal post
  brush.set("rotring", "#29231e", 0.55);
  brush.line(x + tx * bootLen, y + ty * bootLen, tipX + tx * 7, tipY + ty * 7);
  brush.set("glassPen", "#d9cdb8", 0.55);
  brush.line(x + tx * bootLen - nx * 2, y + ty * bootLen - ny * 2, tipX + tx * 6 - nx * 1, tipY + ty * 6 - ny * 1);

  // Spring wire clip loops (pinch-ear spring clip)
  let ear1X = tipX - nx * (bootR * 0.95) - tx * 2;
  let ear1Y = tipY - ny * (bootR * 0.95) - ty * 2;
  let ear2X = tipX + nx * (bootR * 0.85) + tx * 4;
  let ear2Y = tipY + ny * (bootR * 0.85) + ty * 4;

  let clipPts = [
    [ear1X - tx * 5, ear1Y - ty * 5, 0.7],
    [ear1X, ear1Y, 1.0],
    [tipX, tipY, 1.0],
    [ear2X, ear2Y, 1.0],
    [tipX + tx * 8, tipY + ty * 8, 0.8]
  ];
  brush.set("rotring", "#1f1b18", 0.58);
  brush.spline(clipPts, 0.55);
  brush.set("glassPen", "#e0d5c3", 0.48);
  brush.spline(
    clipPts.map((p) => [p[0] - 0.8, p[1] - 0.8, p[2]]),
    0.55
  );

  // Coiled wire spiral at clip base + high-voltage GTO cable to target
  if (wireToX !== null && wireToY !== null) {
    let midX = (tipX + wireToX) * 0.5 + (wireToY - tipY) * 0.12;
    let midY = (tipY + wireToY) * 0.5 + Math.abs(wireToX - tipX) * 0.18 + 18;
    let cablePts = [
      [tipX + tx * 5, tipY + ty * 5, 0.9],
      [midX, midY, 1.0],
      [wireToX, wireToY, 0.9]
    ];
    // Cable shadow
    brush.set("charcoal", "#1c1815", 0.55);
    brush.spline(
      cablePts.map((p) => [p[0] + 4, p[1] + 7, p[2]]),
      0.5
    );
    // Insulated dark GTO cable
    brush.set("rotring", "#1a1715", 0.95);
    brush.spline(cablePts, 0.5);
    brush.set("cpencil", "#453e38", 0.55);
    brush.spline(
      cablePts.map((p) => [p[0] - 0.8, p[1] - 1.2, p[2]]),
      0.5
    );
    // Dust highlight along top of cable
    brush.set("glassPen", "#a89f92", 0.42);
    brush.spline(
      cablePts.map((p) => [p[0] - 1.2, p[1] - 1.8, p[2]]),
      0.5
    );
  }
}

// Forensic drawing of a dead housefly / blowfly on the dusty windowsill
function drawDeadFly(x, y, sc = 1.0, angle = 20, upsideDown = true) {
  push();
  translate(x, y);
  rotate(angle);
  scale(sc);

  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // 1. Soft disturbed dust halo & flat contact shadow on the sill
  brush.set("cpencil", "#cfc7b8", 0.65);
  brush.circle(1, 1, 16, 0.25);

  brush.set("charcoal", "#595146", 0.8);
  brush.line(-9, 5, 11, 6);
  brush.line(-7, 7, 9, 8);
  brush.set("cpencil", "#423b32", 0.7);
  brush.line(-6, 3.5, 8, 4.5);

  // 2. Translucent veined wings splayed out at forensic angles
  let wingAngles = upsideDown ? [-38, 148] : [-25, 22];
  for (let w = 0; w < 2; w++) {
    let wa = (wingAngles[w] * Math.PI) / 180;
    let wx = Math.cos(wa) * 15;
    let wy = Math.sin(wa) * 11 - (upsideDown ? 2 : 4);
    let nx = -Math.sin(wa) * 4.5;
    let ny = Math.cos(wa) * 4.5;

    let wLoop = [
      [0, -1, 0.8],
      [wx * 0.55 + nx, wy * 0.55 + ny, 0.9],
      [wx, wy, 1.0],
      [wx * 0.6 - nx * 0.9, wy * 0.6 - ny * 0.9, 0.9],
      [0, 1, 0.8]
    ];
    // Wing membrane sheen
    brush.set("cpencil", "#dcd5c7", 0.55);
    brush.spline(
      [
        [wx * 0.2, wy * 0.2, 0.8],
        [wx * 0.65 + nx * 0.3, wy * 0.65 + ny * 0.3, 1.0],
        [wx * 0.88, wy * 0.88, 0.7]
      ],
      0.4
    );
    brush.set("glassPen", "#f5f0e6", 0.42);
    brush.spline(
      [
        [wx * 0.3 + nx * 0.4, wy * 0.3 + ny * 0.4, 0.7],
        [wx * 0.75 + nx * 0.2, wy * 0.75 + ny * 0.2, 0.9]
      ],
      0.4
    );
    // Wing margin & dark microscopic venation (R1, R4+5, M1, cross-veins)
    brush.set("glassPen", "#524a42", 0.38);
    brush.spline(wLoop, 0.5);
    brush.line(0, 0, wx * 0.92, wy * 0.92);
    brush.line(wx * 0.25, wy * 0.25, wx * 0.82 + nx * 0.45, wy * 0.82 + ny * 0.45);
    brush.line(wx * 0.2, wy * 0.2, wx * 0.75 - nx * 0.45, wy * 0.75 - ny * 0.45);
    brush.line(wx * 0.48 + nx * 0.2, wy * 0.48 + ny * 0.2, wx * 0.52 - nx * 0.25, wy * 0.52 - ny * 0.25);
  }

  // 3. Abdomen (segmented oval at rear, x = +3..+13)
