// =============================================================================
// GEOMETRY & LIGHTING INITIALIZATION
// =============================================================================

function rot3D(x, y, z, ax, ay, az) {
  let radX = (ax * Math.PI) / 180;
  let radY = (ay * Math.PI) / 180;
  let radZ = (az * Math.PI) / 180;

  // Rotate X
  let y1 = y * Math.cos(radX) - z * Math.sin(radX);
  let z1 = y * Math.sin(radX) + z * Math.cos(radX);
  let x1 = x;

  // Rotate Y
  let x2 = x1 * Math.cos(radY) + z1 * Math.sin(radY);
  let z2 = -x1 * Math.sin(radY) + z1 * Math.cos(radY);
  let y2 = y1;

  // Rotate Z
  let x3 = x2 * Math.cos(radZ) - y2 * Math.sin(radZ);
  let y3 = x2 * Math.sin(radZ) + y2 * Math.cos(radZ);
  let z3 = z2;

  return { x: x3, y: y3, z: z3 };
}

function initSeamCurve() {
  seamPoints3D = [];
  const N = 420;
  const a = 0.71;
  const b = 0.29;
  const c = 2 * Math.sqrt(a * b);

  for (let i = 0; i < N; i++) {
    let t = (i / N) * Math.PI * 2;
    let x0 = a * Math.cos(t) + b * Math.cos(3 * t);
    let y0 = a * Math.sin(t) - b * Math.sin(3 * t);
    let z0 = c * Math.sin(2 * t);
    let len = Math.sqrt(x0 * x0 + y0 * y0 + z0 * z0);
    let p = rot3D(x0 / len, y0 / len, z0 / len, -32, 38, -22);
    seamPoints3D.push(p);
  }

  for (let i = 0; i < N; i++) {
    let pPrev = seamPoints3D[(i - 1 + N) % N];
    let pNext = seamPoints3D[(i + 1) % N];
    let tx = pNext.x - pPrev.x;
    let ty = pNext.y - pPrev.y;
    let tz = pNext.z - pPrev.z;
    let tlen = Math.sqrt(tx * tx + ty * ty + tz * tz) || 1;
    seamPoints3D[i].tx = tx / tlen;
    seamPoints3D[i].ty = ty / tlen;
    seamPoints3D[i].tz = tz / tlen;
  }
}

function getSeamInfo(nx, ny, nz) {
  let minDistSq = 999;
  let bestIdx = 0;
  const N = seamPoints3D.length;

  // Coarse search
  for (let i = 0; i < N; i += 6) {
    let p = seamPoints3D[i];
    let dx = nx - p.x;
    let dy = ny - p.y;
    let dz = nz - p.z;
    let d2 = dx * dx + dy * dy + dz * dz;
    if (d2 < minDistSq) {
      minDistSq = d2;
      bestIdx = i;
    }
  }

  // Local refine
  for (let k = -6; k <= 6; k++) {
    let idx = (bestIdx + k + N) % N;
    let p = seamPoints3D[idx];
    let dx = nx - p.x;
    let dy = ny - p.y;
    let dz = nz - p.z;
    let d2 = dx * dx + dy * dy + dz * dz;
    if (d2 < minDistSq) {
      minDistSq = d2;
      bestIdx = idx;
    }
  }

  let p = seamPoints3D[bestIdx];
  let dist = Math.sqrt(minDistSq);
  // 2D tangent angle on screen
  let tangAngle = (Math.atan2(p.ty, p.tx) * 180) / Math.PI;
  // Cross product (N_seam x T_seam) dot (N - N_seam) for signed side
  let bx = p.y * p.tz - p.z * p.ty;
  let by = p.z * p.tx - p.x * p.tz;
  let bz = p.x * p.ty - p.y * p.tx;
  let side = (nx - p.x) * bx + (ny - p.y) * by + (nz - p.z) * bz >= 0 ? 1 : -1;

  return { dist, tangAngle, side, p };
}

function evalBezier(p0, p1, p2, t) {
  let u = 1 - t;
  return {
    x: u * u * p0.x + 2 * u * t * p1.x + t * t * p2.x,
    y: u * u * p0.y + 2 * u * t * p1.y + t * t * p2.y,
  };
}

function evalBezierTangent(p0, p1, p2, t) {
  let dx = 2 * (1 - t) * (p1.x - p0.x) + 2 * t * (p2.x - p1.x);
  let dy = 2 * (1 - t) * (p1.y - p0.y) + 2 * t * (p2.y - p1.y);
  let len = Math.sqrt(dx * dx + dy * dy) || 1;
  return { x: dx / len, y: dy / len, angle: (Math.atan2(dy, dx) * 180) / Math.PI };
}

