}

function getDentInfo(x, y) {
  let minD = 9999;
  let bestSample = null;
  let bestBlade = null;

  for (let b of indentBlades) {
    // Only check if within rough bounding box
    if (y < 640 || x < 180 || x > 1020) continue;
    for (let s of b.samples) {
      if (s.t < 0.25) continue; // Only upper part of blade contacts ball
      let dx = x - s.x;
      let dy = y - s.y;
      let d = Math.sqrt(dx * dx + dy * dy);
      if (d < minD) {
        minD = d;
        bestSample = s;
        bestBlade = b;
      }
    }
  }

  if (!bestBlade || minD > bestBlade.dentRadius) {
    return { factor: 0, minD: 999, angle: 0, pushX: 0, pushY: 0, strength: 0 };
  }

  let normD = minD / bestBlade.dentRadius;
  let factor = Math.pow(1 - normD, 1.6);
  let dx = x - bestSample.x;
  let dy = y - bestSample.y;
  let len = Math.sqrt(dx * dx + dy * dy) || 1;

  return {
    factor,
    minD,
    angle: bestSample.angle,
    pushX: (dx / len) * factor,
    pushY: (dy / len) * factor,
    strength: bestBlade.dentStrength * factor,
  };
}

