// =============================================================================
// SHADING & COLOR PALETTE HELPERS
// =============================================================================

function lerpHex(c1, c2, amt) {
  amt = constrain(amt, 0, 1);
  let r1 = parseInt(c1.slice(1, 3), 16);
  let g1 = parseInt(c1.slice(3, 5), 16);
  let b1 = parseInt(c1.slice(5, 7), 16);
  let r2 = parseInt(c2.slice(1, 3), 16);
  let g2 = parseInt(c2.slice(3, 5), 16);
  let b2 = parseInt(c2.slice(5, 7), 16);
  let r = Math.round(r1 + (r2 - r1) * amt);
  let g = Math.round(g1 + (g2 - g1) * amt);
  let b = Math.round(b1 + (b2 - b1) * amt);
  return (
    "#" +
    ((1 << 24) + (r << 16) + (g << 8) + b)
      .toString(16)
      .slice(1)
  );
}

// Computes high-contrast hyperrealistic color at any point on the tennis ball
function evaluateBallSurface(x, y) {
  let dx = (x - BALL_X) / BALL_R;
  let dy = (y - BALL_Y) / BALL_R;
  let r2 = dx * dx + dy * dy;
  let r = Math.sqrt(r2);

  let clampedR = Math.min(0.998, r);
  let scale = r > 0 ? clampedR / r : 0;
  let nx = dx * scale;
  let ny = dy * scale;
  let nz = Math.sqrt(Math.max(0.001, 1 - nx * nx - ny * ny));

  // Sun direction: upper-left, slightly forward, raking morning angle
  const sunX = -0.62;
  const sunY = -0.58;
  const sunZ = 0.53;

  let ndotl = nx * sunX + ny * sunY + nz * sunZ;
  let diffuse = constrain((ndotl + 0.25) / 1.25, 0, 1);
  diffuse = Math.pow(diffuse, 1.15);

  // Rim backlighting along upper-left, top, and sides
  let rimSun = constrain((nx * -0.75 + ny * -0.64 + 0.45) / 1.45, 0, 1);
  let rim = Math.pow(1 - nz, 2.2) * (0.25 + 0.95 * rimSun);

  // Bounce light from wet grass on lower-right
  let bounce = Math.pow(constrain(nx * 0.35 + ny * 0.78 - nz * 0.3, 0, 1), 2.0) * 0.28;

  // Bottom contact occlusion with the lawn
  let bottomOcc = constrain((ny - 0.52) / 0.48, 0, 1);
  let shadowCore = constrain((-ndotl + 0.15) / 0.85, 0, 1);

  // Wear & dirt noise (weathered court smudges & matted patches)
  let wearNoise = noise(nx * 3.2 + 11.3, ny * 3.2 + 27.1, nz * 3.2 + 5.7);
  let fineNoise = noise(x * 0.035, y * 0.035);
  let dirt = constrain((wearNoise - 0.44) * 2.2, 0, 1);

  // Seam distance & recess
  let seam = getSeamInfo(nx, ny, nz);
  let isSeam = seam.dist < 0.031;
  let isSeamLip = seam.dist >= 0.031 && seam.dist < 0.062;

  // Grass dent compression
  let dent = getDentInfo(x, y);

  // Base optic yellow / chartreuse color ramp (high contrast values!)
  let colShadowDeep = "#111604";
  let colShadowCore = "#273009";
  let colMidDark = "#556414";
  let colMidChartreuse = "#97ad1f";
  let colBrightYellow = "#d9ed34";
  let colSunHighlight = "#f6ff82";
  let colRimBlaze = "#ffffd6";
  let colDirtMid = "#7c7b33";
  let colBounce = "#465e18";

  let col;
  if (diffuse < 0.22) {
    col = lerpHex(colShadowDeep, colShadowCore, diffuse / 0.22);
  } else if (diffuse < 0.48) {
    col = lerpHex(colShadowCore, colMidDark, (diffuse - 0.22) / 0.26);
  } else if (diffuse < 0.74) {
    col = lerpHex(colMidDark, colMidChartreuse, (diffuse - 0.48) / 0.26);
  } else if (diffuse < 0.91) {
    col = lerpHex(colMidChartreuse, colBrightYellow, (diffuse - 0.74) / 0.17);
  } else {
    col = lerpHex(colBrightYellow, colSunHighlight, (diffuse - 0.91) / 0.09);
  }

  // Blend in worn dirty court patches in midtones
  if (dirt > 0.05) {
    let dirtAmt = dirt * (0.25 + 0.45 * (1 - Math.abs(diffuse - 0.55)));
    col = lerpHex(col, colDirtMid, dirtAmt);
  }

  // Subtle fiber clumping variation
  if (fineNoise > 0.55) {
    col = lerpHex(col, colSunHighlight, (fineNoise - 0.55) * 0.35 * diffuse);
  } else {
    col = lerpHex(col, colShadowCore, (0.55 - fineNoise) * 0.35 * (1 - diffuse * 0.5));
  }

  // Reflected turf bounce
  if (bounce > 0.02 && diffuse < 0.4) {
    col = lerpHex(col, colBounce, bounce);
  }

  // Bottom turf occlusion
  if (bottomOcc > 0.05) {
    col = lerpHex(col, "#080d03", Math.pow(bottomOcc, 1.5) * 0.75);
  }

  // Seam lip micro-shading (ridge next to the white seam)
  if (isSeamLip) {
    let lipT = 1 - (seam.dist - 0.031) / 0.031;
    if (seam.side > 0) {
      col = lerpHex(col, colSunHighlight, lipT * 0.28 * (0.3 + 0.7 * diffuse));
    } else {
      col = lerpHex(col, colShadowDeep, lipT * 0.35);
    }
  }

  // Felted white seam color
  if (isSeam) {
    let seamShadow = "#1c1f14";
    let seamDark = "#484a3a";
    let seamMid = "#8c8b77";
    let seamLight = "#d8d6c3";
    let seamBright = "#f7f6eb";
    let sLight = constrain(diffuse * 0.92 + rim * 0.25 - 0.08, 0, 1);

    if (sLight < 0.25) col = lerpHex(seamShadow, seamDark, sLight / 0.25);
    else if (sLight < 0.55) col = lerpHex(seamDark, seamMid, (sLight - 0.25) / 0.30);
    else if (sLight < 0.82) col = lerpHex(seamMid, seamLight, (sLight - 0.55) / 0.27);
    else col = lerpHex(seamLight, seamBright, (sLight - 0.82) / 0.18);

    // Groove edge shadow inside seam
    let grooveEdge = seam.dist / 0.031;
    if (grooveEdge > 0.65 && seam.side < 0) {
      col = lerpHex(col, seamShadow, (grooveEdge - 0.65) * 1.4);
    }
    if (dirt > 0.2) {
      col = lerpHex(col, "#7d7760", dirt * 0.35);
    }
  }

  // Grass dent trough shading
  if (dent.factor > 0.01) {
    col = lerpHex(col, "#0b1104", dent.factor * 0.65);
  }

  // Rim light blaze
  if (rim > 0.15 && !isSeam) {
    col = lerpHex(col, colRimBlaze, constrain((rim - 0.15) * 0.75, 0, 0.88));
  }

  return {
    col,
    nx,
    ny,
    nz,
    r,
    diffuse,
    rim,
    shadowCore,
    isSeam,
    isSeamLip,
    seam,
    dent,
    dirt,
  };
}

// =============================================================================
// 1. BACKGROUND LAWN (WASHES & MISTED SPRAY BOKEH)
// =============================================================================

function drawBackgroundLawn() {
  brush.noStroke();

  // Deep shadow turf washes (lower & right background)
  const darkZones = [
    { x: 600, y: 650, r: 680, col: "#0b1408", op: 160 },
    { x: 920, y: 820, r: 520, col: "#070e05", op: 190 },
    { x: 280, y: 950, r: 480, col: "#091206", op: 180 },
    { x: 980, y: 340, r: 450, col: "#12210c", op: 150 },
  ];
  for (let z of darkZones) {
    brush.wash(z.col, z.op);
    brush.circle(z.x, z.y, z.r, 0.35);
  }
  brush.noWash();

  // Warm morning sunlight filtering through upper-left lawn
  const lightZones = [
    { x: 180, y: 160, r: 420, col: "#354d14", op: 95 },
    { x: 110, y: 110, r: 310, col: "#62821e", op: 85 },
    { x: 460, y: 140, r: 340, col: "#263b0f", op: 90 },
    { x: 120, y: 420, r: 320, col: "#2c4211", op: 85 },
    { x: 780, y: 150, r: 300, col: "#1c2e0b", op: 80 },
  ];
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.15);
  for (let z of lightZones) {
    brush.fill(z.col, z.op);
    brush.circle(z.x, z.y, z.r, 0.4);
  }
  brush.noFill();

  // Soft out-of-focus bokeh circles in upper-left & top lawn
  const bokehs = [
    { x: 95, y: 85, r: 95, col: "#b5cf3e", op: 55 },
    { x: 240, y: 70, r: 75, col: "#9ab530", op: 50 },
    { x: 65, y: 240, r: 80, col: "#8da828", op: 45 },
    { x: 350, y: 115, r: 65, col: "#748f22", op: 45 },
    { x: 165, y: 195, r: 110, col: "#d8eb65", op: 40 },
    { x: 520, y: 80, r: 70, col: "#5a731b", op: 40 },
  ];
  brush.fillBleed(0.6, "out");
  for (let b of bokehs) {
    brush.fill(b.col, b.op);
    brush.circle(b.x, b.y, b.r, 0.3);
  }
  brush.noFill();

  // Misted spray atmosphere over the background lawn
  for (let i = 0; i < 220; i++) {
    let x = random(0, W);
    let y = random(0, H);
    // Skip interior of the ball to save render budget
    let dBall = dist(x, y, BALL_X, BALL_Y);
    if (dBall < BALL_R - 30) continue;

    let sunFactor = constrain(1 - dist(x, y, 120, 100) / 850, 0, 1);
    let col = lerpHex("#0b1407", "#7d9925", Math.pow(sunFactor, 1.6));
    if (random() < 0.25 && sunFactor > 0.45) {
      col = lerpHex(col, "#d6eb5e", 0.55);
    }
    brush.set("spray", col, random(1.8, 4.2));
    let ang = random(65, 115);
    let len = random(45, 130);
    brush.line(
      x,
      y,
      x + cos(ang) * len,
      y + sin(ang) * len
    );
  }
}

// =============================================================================
// 2. MID-GROUND GRASS & DEEP OCCLUSION SHADOW
// =============================================================================

function drawMidgroundGrassAndShadow() {
  // Soft out-of-focus background grass strokes around upper/side edges
  for (let i = 0; i < 260; i++) {
    let x = random(-40, W + 40);
    let y = random(40, H + 40);
    if (dist(x, y, BALL_X, BALL_Y) < BALL_R - 25) continue;

    let sun = constrain(1 - dist(x, y, 140, 140) / 950, 0, 1);
    let col = lerpHex("#091106", "#5e781c", Math.pow(sun, 1.5));
    if (random() < 0.2) col = lerpHex(col, "#a9c438", sun * 0.7);

    let len = random(70, 190);
    let ang = -90 + random(-28, 28);
    let midX = x + cos(ang) * len * 0.5 + random(-12, 12);
    let midY = y + sin(ang) * len * 0.5;
    let endX = x + cos(ang + random(-15, 15)) * len;
    let endY = y + sin(ang + random(-15, 15)) * len;

    brush.set(random() < 0.5 ? "charcoal" : "cpencil", col, random(1.2, 3.2));
    brush.spline(
      [
        [x, y, 0.9],
        [midX, midY, 0.6],
        [endX, endY, 0.1],
      ],
      0.5
    );
  }

  // Deep occlusion shadow directly beneath the tennis ball in the turf
  brush.noStroke();
  const shadowLayers = [
    { x: BALL_X + 65, y: BALL_Y + 385, rx: 380, ry: 135, col: "#060b04", op: 210 },
    { x: BALL_X + 45, y: BALL_Y + 395, rx: 310, ry: 105, col: "#040802", op: 230 },
    { x: BALL_X + 20, y: BALL_Y + 405, rx: 245, ry: 78, col: "#020501", op: 245 },
  ];

  for (let s of shadowLayers) {
    brush.wash(s.col, s.op);
    brush.beginShape(0.45);
    for (let a = 0; a < 360; a += 20) {
      let px = s.x + cos(a) * s.rx + random(-12, 12);
      let py = s.y + sin(a) * s.ry + random(-8, 8);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }
  brush.noWash();
}

// =============================================================================
// 3. TENNIS BALL UNDERPAINTING & MISTED SPRAY MASS (NO HARD OUTLINE)
// =============================================================================

function drawOrganicBallDisk(cx, cy, r, col, op, useWash = true) {
  brush.noStroke();
  if (useWash) {
    brush.wash(col, op);
  } else {
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.45, 0.1);
    brush.fill(col, op);
  }

  brush.beginShape(0.45);
  const steps = 36;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let px = cx + cos(a) * r;
    let py = cy + sin(a) * r;
    let dent = getDentInfo(px, py);
    let rad = r - dent.strength + (noise(i * 0.3, r * 0.01) - 0.5) * 18;
    brush.vertex(cx + cos(a) * rad, cy + sin(a) * rad);
  }
  brush.endShape(true);

  if (useWash) brush.noWash();
  else brush.noFill();
}

function drawBallUnderpaintingAndSpray() {
  // Soft layered base washes building the 3D sphere from dark shadow to bright crown
  drawOrganicBallDisk(BALL_X, BALL_Y, BALL_R - 4, "#232b08", 230, true);
  drawOrganicBallDisk(BALL_X + 45, BALL_Y + 50, BALL_R - 55, "#151b04", 210, true);
  drawOrganicBallDisk(BALL_X - 28, BALL_Y - 28, BALL_R - 32, "#596915", 190, true);
  drawOrganicBallDisk(BALL_X - 65, BALL_Y - 65, BALL_R - 75, "#98b021", 185, true);
  drawOrganicBallDisk(BALL_X - 105, BALL_Y - 105, BALL_R - 135, "#d4eb36", 185, true);
  drawOrganicBallDisk(BALL_X - 140, BALL_Y - 140, BALL_R - 205, "#f2ff70", 175, false);

  // Dense misted spray pass across the entire ball body & fuzzy rim
  // Builds the powdery chartreuse and dirty optic-yellow fibrous mass
  const sprayCount = 1350;
  for (let i = 0; i < sprayCount; i++) {
    // Biased distribution covering center to rim
    let u = random();
    let rad = BALL_R * Math.pow(u, 0.55) * random(0.94, 1.03);
    let ang = random(360);
    let x = BALL_X + cos(ang) * rad;
    let y = BALL_Y + sin(ang) * rad;

    let dent = getDentInfo(x, y);
    if (rad > BALL_R - dent.strength - 4) {
      rad = BALL_R - dent.strength - 4;
      x = BALL_X + cos(ang) * rad;
      y = BALL_Y + sin(ang) * rad;
    }

    let surf = evaluateBallSurface(x, y);
    let weight = random(1.2, 2.8) * (0.65 + 0.55 * surf.nz);
    brush.set("spray", surf.col, weight);

    let strokeLen = random(18, 42);
    let strokeAng = ang + 90 + random(-35, 35);
    brush.line(
      x - cos(strokeAng) * strokeLen * 0.5,
      y - sin(strokeAng) * strokeLen * 0.5,
      x + cos(strokeAng) * strokeLen * 0.5,
      y + sin(strokeAng) * strokeLen * 0.5
    );
  }
}

// =============================================================================
// 4. FELTED, MATTED WHITE SEAM BASE
// =============================================================================

function drawFeltedSeamBase() {
  // Trace visible points of the 3D seam and build the recessed felted white channel
  const N = seamPoints3D.length;

  for (let pass = 0; pass < 3; pass++) {
    for (let i = 0; i < N; i++) {
      let p = seamPoints3D[i];
      if (p.z <= -0.05) continue; // Only visible hemisphere

      let sx = BALL_X + p.x * BALL_R;
      let sy = BALL_Y + p.y * BALL_R;

      // Foreshortening of seam width near the limb
      let foreshorten = Math.pow(constrain(p.z, 0.05, 1), 0.55);
      let halfW = 14.5 * foreshorten;

      let tangAngle = (Math.atan2(p.ty, p.tx) * 180) / Math.PI;
      let normAngle = tangAngle + 90;

      let surf = evaluateBallSurface(sx, sy);

      if (pass === 0) {
        // Soft recessed channel shadow & lip border
        let lipShadowCol = lerpHex(surf.col, "#181c0c", 0.55);
        brush.set("charcoal", lipShadowCol, random(0.9, 1.5));
        let off = halfW * 0.85;
        brush.line(
          sx + cos(normAngle) * off - cos(tangAngle) * 7,
          sy + sin(normAngle) * off - sin(tangAngle) * 7,
          sx + cos(normAngle) * off + cos(tangAngle) * 7,
          sy + sin(normAngle) * off + sin(tangAngle) * 7
        );
      } else if (pass === 1) {
        // Matted spray & soft chalky base along seam core
        brush.set("spray", surf.col, random(0.9, 1.6) * foreshorten);
        brush.line(
          sx - cos(normAngle) * halfW * 0.6,
          sy - sin(normAngle) * halfW * 0.6,
          sx + cos(normAngle) * halfW * 0.6,
          sy + sin(normAngle) * halfW * 0.6
        );
      } else {
        // Dense matted, felted cross-fibres inside the white seam
        for (let k = 0; k < 4; k++) {
          let across = random(-halfW * 0.85, halfW * 0.85);
          let along = random(-6, 6);
          let fx = sx + cos(normAngle) * across + cos(tangAngle) * along;
          let fy = sy + sin(normAngle) * across + sin(tangAngle) * along;

          let fSurf = evaluateBallSurface(fx, fy);
          let col = fSurf.col;
          if (random() < 0.3) col = lerpHex(col, "#ffffff", 0.25 * fSurf.diffuse);
          if (random() < 0.25) col = lerpHex(col, "#75735c", 0.3);

          let fAng = tangAngle + random(-65, 65);
          let fLen = random(6, 15) * (0.5 + 0.5 * foreshorten);
          let curl = random(-4, 4);

          brush.set(random() < 0.6 ? "cpencil" : "2B", col, random(0.45, 0.85));
          brush.spline(
            [
              [fx - cos(fAng) * fLen * 0.5, fy - sin(fAng) * fLen * 0.5, 0.4],
              [fx + cos(fAng + 90) * curl, fy + sin(fAng + 90) * curl, 0.9],
              [fx + cos(fAng) * fLen * 0.5, fy + sin(fAng) * fLen * 0.5, 0.3],
            ],
            0.65
          );
        }
      }
    }
  }
}

// =============================================================================
// 5. GRASS DENT TROUGHS PRESSED INTO THE NAP
// =============================================================================

function drawGrassDentTroughs() {
  for (let b of indentBlades) {
    for (let s of b.samples) {
      if (s.t < 0.35) continue;
      let dBall = dist(s.x, s.y, BALL_X, BALL_Y);
      if (dBall > BALL_R + 12) continue;

      let surf = evaluateBallSurface(s.x, s.y);
      let troughCol = lerpHex(surf.col, "#080d02", 0.72);
      let cushionHighlight = lerpHex(surf.col, "#e8fa52", 0.28 * surf.diffuse);

      let perp = s.angle + 90;
      let w = map(s.t, 0.35, 1.0, b.w0 * 0.9, b.w2 * 1.4);

      // Deep compressed shadow under the pressing blade
      brush.set("charcoal", troughCol, random(1.1, 2.0));
      brush.line(
        s.x - cos(s.angle) * 10,
        s.y - sin(s.angle) * 10,
        s.x + cos(s.angle) * 10,
        s.y + sin(s.angle) * 10
      );

      // Bulging felt ridge on the sunlit side of the dent
      let sideOff = w * 0.85;
      brush.set("cpencil", cushionHighlight, random(0.6, 1.1));
      brush.line(
        s.x - cos(perp) * sideOff - cos(s.angle) * 8,
        s.y - sin(perp) * sideOff - sin(s.angle) * 8,
        s.x - cos(perp) * sideOff + cos(s.angle) * 8,
        s.y - sin(perp) * sideOff + sin(s.angle) * 8
      );
    }
  }
}

// =============================================================================
// 6. HALO OF LOOSE BACKLIT FUZZ ALONG THE RIM
// =============================================================================

function drawRimFuzzHalo() {
  // First: soft golden-chartreuse atmospheric glow along the sunlit upper-left rim
  for (let i = 0; i < 180; i++) {
    let ang = random(145, 345); // Focused around left, top-left, top, and upper-right
    let rad = BALL_R + random(-6, 22);
    let x = BALL_X + cos(ang) * rad;
    let y = BALL_Y + sin(ang) * rad;
    let dent = getDentInfo(x, y);
    rad -= dent.strength;
    x = BALL_X + cos(ang) * rad;
    y = BALL_Y + sin(ang) * rad;

    let sunRim = constrain(cos(ang - 228) * 0.5 + 0.5, 0, 1);
    let col = lerpHex("#5a6e18", "#f7ff88", Math.pow(sunRim, 1.3));
    brush.set("spray", col, random(1.0, 2.2));
    brush.line(
      x,
      y,
      x + cos(ang + random(-25, 25)) * random(15, 32),
      y + sin(ang + random(-25, 25)) * random(15, 32)
    );
  }

  // Second: ~1,450 individual curled loose fuzz fibres standing proud around the entire circumference
  const rimFibreCount = 1450;
  for (let i = 0; i < rimFibreCount; i++) {
    let ang = (i / rimFibreCount) * 360 + random(-0.4, 0.4);
    let baseRad = BALL_R - random(2, 16);
    let bx0 = BALL_X + cos(ang) * baseRad;
    let by0 = BALL_Y + sin(ang) * baseRad;

    let dent = getDentInfo(bx0, by0);
    baseRad -= dent.strength;

    let x0 = BALL_X + cos(ang) * baseRad;
    let y0 = BALL_Y + sin(ang) * baseRad;
    let surf = evaluateBallSurface(x0, y0);

    // Sunlit rim factor (strongest at upper-left 225 deg, wrapping around top and lower-left)
    let sunRim = constrain(cos(ang - 225) * 0.55 + 0.45, 0, 1);
    let isHeroHair = random() < 0.22;
    let hairLen = isHeroHair
      ? random(28, 62) * (0.65 + 0.45 * sunRim)
      : random(12, 30);

    // Deflect hair angle if pressed by a grass blade
    let outAng = ang + random(-32, 32);
    if (dent.factor > 0.1) {
      outAng = lerp(outAng, dent.angle + (random() < 0.5 ? 25 : -25), dent.factor * 0.8);
      hairLen *= 1 - dent.factor * 0.35;
    }

    let curlDir = random() < 0.5 ? 1 : -1;
    let curlAng = outAng + curlDir * random(25, 85);

    let x1 = x0 + cos(outAng) * (hairLen * 0.55);
    let y1 = y0 + sin(outAng) * (hairLen * 0.55);
    let x2 = x1 + cos(curlAng) * (hairLen * 0.5);
    let y2 = y1 + sin(curlAng) * (hairLen * 0.5);

    // Color of the rim fibre: incandescent golden-white in sun, glowing chartreuse in mid, olive in shadow
    let col;
    if (surf.isSeam) {
      col = lerpHex("#575946", "#ffffff", Math.pow(sunRim, 0.9));
    } else if (sunRim > 0.65) {
      col = lerpHex("#e3f542", "#ffffde", (sunRim - 0.65) / 0.35);
      if (random() < 0.35) col = "#ffffff";
    } else if (sunRim > 0.3) {
      col = lerpHex("#6e851c", "#e3f542", (sunRim - 0.3) / 0.35);
    } else {
      col = lerpHex("#2c380a", "#6e851c", sunRim / 0.3);
    }

    let bName = sunRim > 0.6 && isHeroHair ? "2H" : "cpencil";
    let w = isHeroHair ? random(0.32, 0.62) : random(0.45, 0.82);

    brush.set(bName, col, w);
    brush.spline(
      [
        [x0, y0, 0.85],
        [x1, y1, 0.6],
        [x2, y2, 0.15],
      ],
      0.75
    );
  }
}

// =============================================================================
// 7. THOUSANDS OF TINY CURLED PENCIL FIBRES (THE PLUSH WOOL NAP)
// =============================================================================

function drawCurledPencilFibres() {
  // Generate points across the sphere using Fibonacci spiral + jitter for organic clumping
  const numFibres = 4800;
  const goldenAngle = 137.507764;
  let fibres = [];

  for (let i = 0; i < numFibres; i++) {
    let frac = (i + 0.5) / numFibres;
    // Slight density boost toward the sunlit crown and outer rim
    let rNorm = Math.pow(frac, 0.48);
    let theta = i * goldenAngle + random(-2.5, 2.5);

    let rawRad = rNorm * (BALL_R - 4);
    let x = BALL_X + cos(theta) * rawRad + random(-4, 4);
    let y = BALL_Y + sin(theta) * rawRad + random(-4, 4);

    let dent = getDentInfo(x, y);
    let maxAllowedRad = BALL_R - dent.strength - 3;
    let curDist = dist(x, y, BALL_X, BALL_Y);
    if (curDist > maxAllowedRad) {
      let a = atan2(y - BALL_Y, x - BALL_X);
      x = BALL_X + cos(a) * (maxAllowedRad - random(0, 8));
      y = BALL_Y + sin(a) * (maxAllowedRad - random(0, 8));
    }

    let surf = evaluateBallSurface(x, y);
    fibres.push({ x, y, theta, surf });
  }

  // Sort from outer rim (low nz) to front crown (high nz) for natural overlapping pile
  fibres.sort((a, b) => a.surf.nz - b.surf.nz);

  for (let i = 0; i < fibres.length; i++) {
    let f = fibres[i];
    let s = f.surf;
    let x = f.x;
    let y = f.y;

    // Clump orientation field using low-frequency noise
    let fieldAng = noise(x * 0.012, y * 0.012) * 360;
    let radialAng = atan2(y - BALL_Y, x - BALL_X);

    // Near the rim, fibres lean outward; near the center, they swirl in wooly tufts
    let rimLean = Math.pow(1 - s.nz, 1.5);
    let baseAng = lerp(fieldAng, radialAng + random(-35, 35), rimLean * 0.75);

    // If on or near the seam, fibres either mat along the seam or overhang its lip
    if (s.isSeam) {
      baseAng = s.seam.tangAngle + random(-55, 55);
    } else if (s.isSeamLip) {
      baseAng = s.seam.tangAngle + 90 * s.seam.side + random(-30, 30);
    }

    // If near a grass dent, fibres part around the pressing blade
    if (s.dent.factor > 0.15) {
      baseAng = s.dent.angle + (random() < 0.5 ? 18 : -18);
    }

    // Fibre length & curl geometry:
    // Near the center (nz ~ 1), we see foreshortened tight little C-curls and hooks;
    // Toward the rim (nz -> 0), we see longer projecting curved hairs
    let len = map(s.nz, 0.05, 1.0, 24, 11) * random(0.75, 1.35);
    if (s.isSeam) len *= 0.72; // Matted shorter in the seam

    let curlSign = random() < 0.5 ? 1 : -1;
    let hookAng = baseAng + curlSign * map(s.nz, 0.1, 1.0, 42, 95);

    let x1 = x + cos(baseAng) * (len * 0.55);
    let y1 = y + sin(baseAng) * (len * 0.55);
    let x2 = x1 + cos(hookAng) * (len * 0.52);
    let y2 = y1 + sin(hookAng) * (len * 0.52);

    // Individual fibre color variation (Creates rich optical mixing of the wool nap!)
    let col = s.col;
    let rv = random();
    if (s.isSeam) {
      if (rv < 0.35) col = lerpHex(col, "#ffffff", 0.38 * (0.3 + 0.7 * s.diffuse));
      else if (rv < 0.65) col = lerpHex(col, "#63624e", 0.35);
      // Occasional stray yellow fibre overhanging the seam border
      if (s.seam.dist > 0.022 && random() < 0.38) {
        col = lerpHex("#8da11e", "#f2ff6e", s.diffuse);
      }
    } else {
      if (rv < 0.28) {
        // Sun-kissed bright fibre standing proud of the nap
        let highlightCol = s.diffuse > 0.5 ? "#ffffb5" : "#a8bf24";
        col = lerpHex(col, highlightCol, 0.45 + 0.35 * s.rim);
      } else if (rv < 0.52) {
        // Deeper root shadow fibre giving micro-depth between tufts
        col = lerpHex(col, "#141a03", 0.42);
      } else if (rv < 0.68 && s.dirt > 0.15) {
        // Weathered olive-ochre fibre
        col = lerpHex(col, "#7d7832", 0.45);
      }
    }

    // Choose pencil grade based on tonal value
    let brushName = "cpencil";
    if (s.diffuse > 0.78 && rv < 0.35) brushName = "2H";
    else if (s.diffuse < 0.28) brushName = "2B";
    else if (rv > 0.75) brushName = "HB";

    let w = random(0.42, 0.85) * (0.75 + 0.25 * (1 - s.nz));
    brush.set(brushName, col, w);
    brush.spline(
      [
        [x, y, 0.8],
        [x1, y1, 0.95],
        [x2, y2, 0.2],
      ],
      0.8
    );
  }

  // Extra pass of bright, crisp standing pilling/tufts on the sunlit crown & terminator
  for (let i = 0; i < 420; i++) {
    let rad = random(20, BALL_R - 12);
    let ang = random(150, 330); // Upper-left / sunlit hemisphere
    let x = BALL_X + cos(ang) * rad;
    let y = BALL_Y + sin(ang) * rad;
    let s = evaluateBallSurface(x, y);
    if (s.diffuse < 0.35) continue;

    let tuftCol = s.isSeam
      ? lerpHex(s.col, "#ffffff", 0.65)
      : lerpHex(s.col, "#ffffcc", 0.62);

    let a1 = random(360);
    let a2 = a1 + (random() < 0.5 ? 75 : -75);
    let l = random(8, 18);

    brush.set("2H", tuftCol, random(0.35, 0.65));
    brush.spline(
      [
        [x, y, 0.7],
        [x + cos(a1) * l * 0.55, y + sin(a1) * l * 0.55, 0.9],
        [
          x + cos(a1) * l * 0.55 + cos(a2) * l * 0.5,
          y + sin(a1) * l * 0.55 + sin(a2) * l * 0.5,
          0.15,
        ],
      ],
      0.85
    );
  }
}

// =============================================================================
// 8. FOREGROUND GRASS BLADES (PRESSING DENTS INTO THE NAP)
// =============================================================================

function drawSingleGrassBlade(b, isIndentBlade) {
  const steps = 24;
  let spine = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalBezier(b.p0, b.p1, b.p2, t);
    let tang = evalBezierTangent(b.p0, b.p1, b.p2, t);
    let w = lerp(b.w0, b.w2, Math.pow(t, 0.85));
    spine.push({
      x: pt.x,
      y: pt.y,
      t,
      w,
      nx: -tang.y,
      ny: tang.x,
      angle: tang.angle,
    });
  }

  // 1. Cast shadow right next to the blade where it presses into the ball or turf
  if (isIndentBlade) {
    let shadowPts = [];
    for (let i = 6; i <= steps; i++) {
      let s = spine[i];
      shadowPts.push([s.x + s.nx * (s.w * 0.55 + 3), s.y + s.ny * (s.w * 0.55 + 3), 0.7]);
    }
    brush.set("charcoal", "#070c02", 1.1);
    brush.spline(shadowPts, 0.5);
  }

  // 2. Base opaque wash for the blade body
  let baseCol = lerpHex("#0b1706", "#3b5912", b.light * 0.75);
  brush.noStroke();
  brush.wash(baseCol, 235);
  brush.beginShape(0.2);
  for (let i = 0; i <= steps; i++) {
    let s = spine[i];
    brush.vertex(s.x - s.nx * s.w * 0.5, s.y - s.ny * s.w * 0.5);
  }
  for (let i = steps; i >= 0; i--) {
    let s = spine[i];
    brush.vertex(s.x + s.nx * s.w * 0.5, s.y + s.ny * s.w * 0.5);
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Longitudinal fibrous striations along the grass blade
  const numVeins = 11;
  for (let v = 0; v < numVeins; v++) {
    let across = map(v, 0, numVeins - 1, -0.46, 0.46);
    let pts = [];
    for (let i = 0; i <= steps; i += 3) {
      let s = spine[i];
      pts.push([
        s.x + s.nx * s.w * across,
        s.y + s.ny * s.w * across,
        1 - s.t * 0.65,
      ]);
    }

    // Sunlit left edge vs shaded right edge + translucent tip
    let sideLight = constrain(0.5 - across, 0, 1);
    let colDark = "#081204";
    let colMid = lerpHex("#182e09", "#4f7317", b.light);
    let colBright = lerpHex("#587a1a", "#c8e346", b.light);

    let vCol = across < -0.15
      ? lerpHex(colMid, colBright, sideLight)
      : lerpHex(colDark, colMid, 1 - Math.abs(across));

    if (v === 0 || v === 1) {
      // Sun-catching rim vein on the blade
      vCol = lerpHex(vCol, "#efff7a", b.light * 0.65);
    }

    brush.set(v <= 1 ? "2H" : "cpencil", vCol, random(0.45, 0.85));
    brush.spline(pts, 0.45);
  }

  // 4. Glowing sunlit upper tip of the blade
  let tipPts = [];
  for (let i = Math.floor(steps * 0.55); i <= steps; i += 2) {
    let s = spine[i];
    tipPts.push([s.x - s.nx * s.w * 0.25, s.y - s.ny * s.w * 0.25, 1 - s.t * 0.5]);
  }
  let tipCol = lerpHex("#6d8c1f", "#f3ff85", b.light);
  brush.set("cpencil", tipCol, 0.55);
  brush.spline(tipPts, 0.4);
}

function drawForegroundGrass() {
  // Draw background/framing foreground blades first
  for (let b of fgBlades) {
    drawSingleGrassBlade(b, false);
  }

  // Draw the hero indenting blades that press into the tennis ball nap
  for (let b of indentBlades) {
    drawSingleGrassBlade(b, true);
  }

  // Add fine wild grass shoots & damp moss texture at the bottom turf border
  for (let i = 0; i < 190; i++) {
    let x = random(0, W);
    let y = random(940, H + 30);
    let sun = constrain(1 - x / 950, 0.15, 0.95);
    let col = lerpHex("#070f03", "#82a324", sun * random(0.4, 1.0));
    if (random() < 0.18) col = lerpHex(col, "#e5fa64", sun * 0.75);

    let ang = -90 + random(-35, 35);
    let len = random(35, 115);
    let x1 = x + cos(ang) * len * 0.5 + random(-8, 8);
    let y1 = y + sin(ang) * len * 0.5;
    let x2 = x + cos(ang + random(-20, 20)) * len;
    let y2 = y + sin(ang + random(-20, 20)) * len;

    brush.set("cpencil", col, random(0.45, 0.95));
    brush.spline(
      [
        [x, y, 0.85],
        [x1, y1, 0.65],
        [x2, y2, 0.15],
      ],
      0.55
    );
  }
}

// =============================================================================
// 9. OVERLAPPING CONTACT FUZZ AROUND INDENTING GRASS BLADES
// =============================================================================

function drawOverlappingContactFuzz() {
  // Where grass blades press into the ball, tufts of wool felt bulge out and a few
  // stray curled yellow fibres wrap right over the edge of the grass blade!
  for (let b of indentBlades) {
    for (let s of b.samples) {
      if (s.t < 0.42) continue;
      let dBall = dist(s.x, s.y, BALL_X, BALL_Y);
      if (dBall > BALL_R + 6) continue;

      let w = lerp(b.w0, b.w2, Math.pow(s.t, 0.85));
      let perp = s.angle + 90;

      for (let side of [-1, 1]) {
        if (random() < 0.35) continue;
        let bx = s.x + cos(perp) * (w * 0.52 * side);
        let by = s.y + sin(perp) * (w * 0.52 * side);
        let surf = evaluateBallSurface(bx, by);

        let fCol = lerpHex(surf.col, "#f4ff78", 0.35 * surf.diffuse + 0.15);
        // Curve slightly over the grass blade edge
        let fAng = perp - side * random(10, 45);
        let fLen = random(9, 19);
        let curlAng = fAng + (random() < 0.5 ? 55 : -55);

        brush.set("cpencil", fCol, random(0.38, 0.68));
        brush.spline(
          [
            [bx, by, 0.75],
            [bx + cos(fAng) * fLen * 0.5, by + sin(fAng) * fLen * 0.5, 0.85],
            [
              bx + cos(fAng) * fLen * 0.5 + cos(curlAng) * fLen * 0.45,
              by + sin(fAng) * fLen * 0.5 + sin(curlAng) * fLen * 0.45,
              0.15,
            ],
          ],
          0.75
        );
      }
    }
  }
}

// =============================================================================
// 10. DEW BEADS WITH SHARP REFRACTIONS
// =============================================================================

function drawDewBeads() {
  // "Dew beads sit on the fibres with sharp refractions.
  //  There is no hard outline anywhere except the water droplets."

  const sunAngle = 225; // Upper-left sun direction
  const causticAngle = 45; // Lower-right focused caustic direction

  for (let d of dewDrops) {
    let x = d.x;
    let y = d.y;
    let r = d.r;

    // Determine underlying color & illumination
    let baseCol = "#a8c424";
    let causticCol = "#f7ff78";
    let shadowCol = "#131c04";
    let rimDarkCol = "#0c1403";
    let localLight = 0.75;

    if (d.type === "ball" || d.type === "rim") {
      let surf = evaluateBallSurface(x, y);
      baseCol = surf.col;
      localLight = constrain(surf.diffuse + surf.rim * 0.5, 0.2, 1.0);
      if (surf.isSeam) {
        causticCol = "#ffffff";
        shadowCol = "#26291c";
        rimDarkCol = "#1a1c12";
      } else {
        causticCol = lerpHex("#d4ed32", "#ffffc2", localLight);
        shadowCol = "#121a03";
        rimDarkCol = "#0d1402";
      }
    } else {
      // Grass droplet
      localLight = d.light || 0.65;
      baseCol = lerpHex("#1e380a", "#658c1c", localLight);
      causticCol = lerpHex("#99bd28", "#f6ff85", localLight);
      shadowCol = "#050b02";
      rimDarkCol = "#040901";
    }

    // 1. Cast shadow + focused lens caustic on the fibres/blade beneath the droplet
    let cOff = r * 0.38;
    let cx = x + cos(causticAngle) * cOff;
    let cy = y + sin(causticAngle) * cOff;

    brush.noStroke();
    brush.wash(shadowCol, 175);
    brush.circle(cx + cos(causticAngle) * r * 0.18, cy + sin(causticAngle) * r * 0.18, r * 0.92, 0.12);
    brush.noWash();

    // Bright focused caustic spot inside the cast shadow
    brush.wash(causticCol, 195);
    brush.circle(cx, cy, r * 0.55, 0.1);
    brush.noWash();

    // 2. Dark inverted refraction cap on the sun-facing interior of the droplet
    let darkCapCol = lerpHex(rimDarkCol, baseCol, 0.25);
    brush.wash(darkCapCol, 225);
    brush.circle(x, y, r * 0.96, 0.05);
    brush.noWash();

    // 3. Radiant internal refracted crescent on the lower-right interior
    let innerCx = x + cos(causticAngle) * r * 0.22;
    let innerCy = y + sin(causticAngle) * r * 0.22;
    brush.wash(causticCol, 215);
    brush.circle(innerCx, innerCy, r * 0.68, 0.06);
    brush.noWash();

    if (r > 6) {
      // Pure incandescent core of the internal caustic
      brush.wash("#ffffe0", 190);
      brush.circle(
        x + cos(causticAngle) * r * 0.34,
        y + sin(causticAngle) * r * 0.34,
        r * 0.38,
        0.05
      );
      brush.noWash();
    }

    // 4. Magnified micro-fibres visible inside larger droplets on the ball!
    if ((d.type === "ball" || d.type === "rim") && r >= 7.5) {
      for (let m = 0; m < 3; m++) {
        let ma = random(360);
        let ml = r * 0.45;
        brush.set("2H", causticCol, 0.38);
        brush.line(
          x - cos(ma) * ml * 0.4,
          y - sin(ma) * ml * 0.4,
          x + cos(ma) * ml * 0.4,
          y + sin(ma) * ml * 0.4
        );
      }
    }

    // 5. SHARP HARD OUTLINE around the water droplet (the ONLY crisp outline in the artwork!)
    // Outer dark refractive ring with "rotring" / "pen"
    let penW = map(r, 4, 14, 0.45, 0.95);
    brush.set("rotring", rimDarkCol, penW);
    brush.circle(x, y, r, 0.03);

    // Crisp dark crescent on the upper-left refractive edge
    brush.set("pen", "#050801", penW * 1.15);
    brush.arc(x, y, r * 0.96, 145, 315);

    // Crisp luminous lower-right refractive rim arc
    brush.set("rotring", "#ffffd8", penW * 0.85);
    brush.arc(x, y, r * 0.92, -35, 125);

    // 6. Razor-sharp primary solar specular highlight on the upper-left cap
    let specX = x + cos(sunAngle) * r * 0.42;
    let specY = y + sin(sunAngle) * r * 0.42;
    let specR = Math.max(1.6, r * 0.22);

    brush.noStroke();
    brush.wash("#ffffff", 255);
    brush.circle(specX, specY, specR, 0.02);
    brush.noWash();

    // Sharp glinting pinpoint and micro-arc on the specular reflection
    brush.set("rotring", "#ffffff", penW * 1.1);
    brush.circle(specX, specY, specR * 0.7, 0.01);

    if (r >= 7.5) {
      // Secondary tiny specular glint adjacent to primary highlight
      let spec2X = specX + cos(sunAngle + 75) * (r * 0.24);
      let spec2Y = specY + sin(sunAngle + 75) * (r * 0.24);
      brush.set("rotring", "#ffffff", penW * 0.85);
      brush.line(spec2X - 1, spec2Y - 1, spec2X + 1.5, spec2Y + 1.5);

      // Tiny opposite-rim internal bounce highlight
      let bounceX = x + cos(causticAngle) * r * 0.72;
      let bounceY = y + sin(causticAngle) * r * 0.72;
      brush.set("rotring", "#ffffeb", penW * 0.75);
      brush.line(bounceX - 1.5, bounceY + 1, bounceX + 1.5, bounceY - 1);
    }
  }
}

// Hyperrealism in p5.brush:
// "From inside a parked pickup, a towering wall of dust fills the windshield..."

const PALETTE = {
  // Dust wall gradient: bruised umber -> rust -> ochre -> strained amber
  umberDeep: "#1b0f13",
  umberBruise: "#2c181e",
  umberMid: "#3f2127",
  umberRust: "#572928",
  rustDark: "#733124",
  rustCore: "#913d25",
  rustBright: "#ad4e28",
  ochreDark: "#c4662e",
  ochreCore: "#d98238",
  ochreWarm: "#e69d49",
  amberStrained: "#f0b862",
  amberGlow: "#f7ce7e",
  amberSpec: "#ffe4a8",

  // Foreground interior: dark vinyl, plastic, metal, foam
  inkBlack: "#0b0607",
  vinylAbyss: "#120a0c",
  vinylDark: "#1c1114",
  vinylShadow: "#28181b",
  vinylMid: "#3b2325",
  vinylLit: "#54312d",
  vinylWarm: "#704134",
  vinylRim: "#96593c",
  foamDark: "#693918",
  foamMid: "#9c5c26",
  foamLight: "#c97e38",

  // Plastic coffee lid & rosary
  lidShadow: "#291619",
  lidMidDark: "#4a2826",
  lidMid: "#734033",
  lidWarm: "#a3613e",
  lidAmber: "#cf874c",
  lidLit: "#eab065",
  lidHighlight: "#f7cf86",
  lidSpec: "#ffebb8",
  coffeeStain: "#4d2010"
};

// Helper to draw a polygon using beginShape/vertex/endShape
function drawShapePoly(pts, curvature = 0, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Helper to generate points along a rotated ellipse
function getEllipsePts(cx, cy, rx, ry, rotDeg = 0, numPts = 48, startDeg = 0, endDeg = 360) {
  let pts = [];
  let radRot = (rotDeg * Math.PI) / 180;
  let cosR = Math.cos(radRot);
  let sinR = Math.sin(radRot);
  for (let i = 0; i <= numPts; i++) {
    let a = ((startDeg + ((endDeg - startDeg) * i) / numPts) * Math.PI) / 180;
    let ex = Math.cos(a) * rx;
    let ey = Math.sin(a) * ry;
    let px = cx + ex * cosR - ey * sinR;
    let py = cy + ex * sinR + ey * cosR;
    pts.push([px, py]);
  }
  return pts;
}

// Interpolate hex colors
function lerpHex(hex1, hex2, t) {
  t = constrain(t, 0, 1);
  let c1 = color(hex1);
  let c2 = color(hex2);
  return lerpColor(c1, c2, t);
}

// Multi-stop gradient color sampler for the dust wall
function sampleDustColor(normY, sunProx = 0) {
  // normY: 0 (top of windshield) to 1 (bottom of windshield)
  const stops = [
    { pos: 0.0, col: PALETTE.umberDeep },
    { pos: 0.14, col: PALETTE.umberBruise },
    { pos: 0.28, col: PALETTE.umberMid },
    { pos: 0.40, col: PALETTE.umberRust },
    { pos: 0.52, col: PALETTE.rustDark },
    { pos: 0.64, col: PALETTE.rustCore },
    { pos: 0.75, col: PALETTE.ochreDark },
    { pos: 0.86, col: PALETTE.ochreCore },
    { pos: 0.94, col: PALETTE.ochreWarm },
    { pos: 1.0, col: PALETTE.rustDark }
  ];
  let n = constrain(normY, 0, 1);
  let baseCol = color(PALETTE.umberDeep);
  for (let i = 0; i < stops.length - 1; i++) {
    if (n >= stops[i].pos && n <= stops[i + 1].pos) {
      let localT = (n - stops[i].pos) / (stops[i + 1].pos - stops[i].pos);
      baseCol = lerpHex(stops[i].col, stops[i + 1].col, localT);
      break;
    }
  }
  if (sunProx > 0) {
    let glowCol = lerpHex(PALETTE.ochreWarm, PALETTE.amberGlow, pow(sunProx, 1.4));
    baseCol = lerpColor(baseCol, glowCol, constrain(sunProx * 0.85, 0, 0.9));
  }
  return baseCol;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom spray and marker/pen brushes tailored for 1200x1200 hyperrealism
  brush.add("dust_billow", {
    type: "spray",
    weight: 16,
    scatter: 5.8,
    opacity: 20,
    spacing: 0.35,
    pressure: [0.4, 1.3, 0.4],
    rotate: "random"
  });

  brush.add("dust_grain", {
    type: "spray",
    weight: 7,
    scatter: 3.2,
    opacity: 38,
    spacing: 0.25,
    pressure: [0.5, 1.15, 0.5],
    rotate: "random"
  });

  brush.add("silt_stipple", {
    type: "spray",
    weight: 2.2,
    scatter: 1.4,
    opacity: 95,
    spacing: 0.2,
    pressure: [0.7, 1.2, 0.6],
    rotate: "random"
  });

  brush.add("chisel_marker", {
    type: "marker",
    weight: 4.5,
    scatter: 0.03,
    opacity: 48,
    spacing: 0.14,
    pressure: [0.9, 1.0, 0.9],
    markerTip: false,
    noise: 0.12
  });

  brush.add("fine_marker", {
    type: "marker",
    weight: 1.8,
    scatter: 0.02,
    opacity: 65,
    spacing: 0.12,
    pressure: [0.85, 1.0, 0.85],
    markerTip: false,
    noise: 0.08
  });

  brush.add("razor_pen", {
    type: "default",
    weight: 0.42,
    scatter: 0.01,
    sharpness: 0.95,
    grain: 0.1,
    opacity: 235,
    spacing: 0.1,
    pressure: [0.8, 1.0, 0.7],
    noise: 0.05
  });

  // Custom turbulent haboob vector field for the rolling dust wall
  brush.addField("haboob_turbulence", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.07;
        let ny = row * 0.07;
        let curl = noise(nx, ny, 1.5) * 220 - 110;
        let roll = Math.sin(col * 0.18 + row * 0.09) * 35;
        field[col][row] = -12 + curl * 0.55 + roll;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.umberDeep);

  // 1. RENDER THE TOWERING WALL OF DUST (WINDSHIELD: y = 0..770)
  renderDustWall();

  // 2. RENDER WINDSHIELD WIPERS & ACCUMULATED GRIT
  renderWipersAndGrit();

  // 3. RENDER CRACKED VINYL DASHBOARD & INSTRUMENT BROW
  renderDashboard();

  // 4. RENDER UPPER CABIN FRAME, A-PILLAR & REARVIEW MIRROR MOUNT
  renderCabinFrameAndMirror();

  // 5. RENDER COFFEE CUP & PLASTIC DOME LID ON DASHBOARD
  renderCoffeeCupAndLid();

  // 6. RENDER DANGLING ROSARY IN FRONT OF THE DUST WALL
  renderDanglingRosary();

  noLoop();
}

// =============================================================================
// 1. THE TOWERING WALL OF DUST (DENSE SPRAY GRADIENT)
// =============================================================================
function renderDustWall() {
  brush.noField();
  brush.noStroke();

  const sunX = 485;
  const sunY = 470;

  // Step 1A: Fast tonal base washes establishing bruised umber -> rust -> ochre
  const numBands = 28;
  for (let i = 0; i < numBands; i++) {
    let t = i / (numBands - 1);
    let y0 = lerp(-20, 740, t);
    let bh = 65;
    let col = sampleDustColor(t, 0);
    brush.wash(col, 160);
    let pts = [
      [-20, y0],
      [1220, y0 - 15 * Math.sin(t * Math.PI)],
      [1220, y0 + bh],
      [-20, y0 + bh + 15 * Math.sin(t * Math.PI)]
    ];
    drawShapePoly(pts, 0, true);
  }
  brush.noWash();

  // Step 1B: Soft watercolor bleed masses for the billowing haboob lobes & strained sun
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.2);

  // Bruised umber upper billowing canopy
  brush.fill(PALETTE.umberBruise, 95);
  for (let i = 0; i < 6; i++) {
    let cx = 120 + i * 200 + random(-35, 35);
    let cy = 90 + random(-30, 45);
    brush.circle(cx, cy, random(150, 230), 0.35);
  }

  // Rust mid-level boiling cloud lobes
  brush.fill(PALETTE.rustCore, 85);
  for (let i = 0; i < 7; i++) {
    let cx = 80 + i * 180 + random(-30, 30);
    let cy = 330 + random(-40, 40);
    brush.circle(cx, cy, random(140, 210), 0.4);
  }

  // Ochre lower turbulent wall swallowing the horizon
  brush.fill(PALETTE.ochreCore, 90);
  for (let i = 0; i < 7; i++) {
    let cx = 90 + i * 175 + random(-25, 25);
    let cy = 540 + random(-35, 35);
    brush.circle(cx, cy, random(130, 195), 0.35);
  }

  // Strained amber sun diffused through the dust curtain
  brush.fill(PALETTE.amberStrained, 65);
  brush.circle(sunX, sunY, 260, 0.3);
  brush.fill(PALETTE.amberGlow, 55);
  brush.circle(sunX, sunY, 150, 0.25);
  brush.noFill();

  // Step 1C: Ghostly swallowed horizon detail on far left (fence posts & leaning pole)
  // Barely perceptible, drowned inside the silt
  brush.set("chisel_marker", PALETTE.rustDark, 0.7);
  brush.line(215, 655, 222, 555);
  brush.line(198, 572, 240, 568);
  brush.set("chisel_marker", PALETTE.umberRust, 0.5);
  brush.line(310, 675, 313, 622);
  brush.line(385, 682, 387, 638);

  // Step 1D: Colossal 3D Haboob Lobes sculpted with spray splines
  // Define several massive rolling cloud fronts across the windshield
  const lobes = [
    { cx: 260, cy: 230, rx: 240, ry: 135, rot: -12 },
    { cx: 610, cy: 195, rx: 280, ry: 150, rot: 8 },
    { cx: 960, cy: 250, rx: 250, ry: 140, rot: 16 },
    { cx: 190, cy: 410, rx: 230, ry: 130, rot: -8 },
    { cx: 510, cy: 385, rx: 260, ry: 145, rot: 5 },
    { cx: 840, cy: 420, rx: 270, ry: 135, rot: 14 },
    { cx: 1080, cy: 460, rx: 210, ry: 120, rot: 20 },
    { cx: 340, cy: 565, rx: 280, ry: 125, rot: -4 },
    { cx: 740, cy: 580, rx: 310, ry: 130, rot: 6 }
  ];

  for (let l of lobes) {
    let normY = constrain(l.cy / 720, 0, 1);
    let dSun = dist(l.cx, l.cy, sunX, sunY);
    let sunProx = constrain(1 - dSun / 460, 0, 1);

    // Shadow belly of the dust lobe (bruised umber / dark rust)
    let bellyCol = sampleDustColor(constrain(normY - 0.16, 0, 1), sunProx * 0.3);
    for (let s = 0; s < 14; s++) {
      let rScale = map(s, 0, 13, 0.45, 1.08);
      let arcPts = getEllipsePts(
        l.cx + random(-18, 18),
        l.cy + 25 + random(-12, 12),
        l.rx * rScale,
        l.ry * rScale,
        l.rot,
        16,
        15,
        165
      );
      brush.set("dust_billow", bellyCol, random(1.1, 2.2));
      brush.spline(arcPts, 0.5);
    }

    // Lit boiling crown/crest facing the strained amber sun
    let crestCol = sampleDustColor(constrain(normY + 0.14, 0, 1), constrain(sunProx + 0.25, 0, 1));
    for (let s = 0; s < 16; s++) {
      let rScale = map(s, 0, 15, 0.35, 1.02);
      let arcPts = getEllipsePts(
        l.cx + random(-15, 15),
        l.cy - 15 + random(-12, 12),
        l.rx * rScale,
        l.ry * rScale,
        l.rot,
        16,
        190,
        350
      );
      brush.set("dust_billow", crestCol, random(1.0, 2.0));
      brush.spline(arcPts, 0.5);
    }
  }

  // Step 1E: Dense Spray Gradient Field (thousands of layered airborne dust marks)
  brush.field("haboob_turbulence");

  // Broad atmospheric spray pass
  const numBroadStrokes = 950;
  for (let i = 0; i < numBroadStrokes; i++) {
    let x = random(-40, 1240);
    let y = random(-20, 765);

    // Billowing vertical displacement from noise so the gradient locks into cloud structures
    let nVal = noise(x * 0.0035, y * 0.0045);
    let effectiveY = constrain((y + (nVal - 0.5) * 190) / 730, 0, 1);

    let dSun = dist(x, y, sunX, sunY);
    let sunProx = constrain(1 - dSun / 430, 0, 1);
    let col = sampleDustColor(effectiveY, sunProx);

    let w = map(effectiveY, 0, 1, 1.8, 1.1) * random(0.75, 1.35);
    brush.set("dust_billow", col, w);
    brush.flowLine(x, y, random(65, 165), random(-25, 25));
  }

  // Finer granular spray pass for tactile airborne silt and ochre-rust grain
  const numGrainStrokes = 1100;
  for (let i = 0; i < numGrainStrokes; i++) {
    let x = random(-20, 1220);
    let y = random(0, 765);
    let nVal = noise(x * 0.006 + 10, y * 0.006 + 10);
    let effectiveY = constrain((y + (nVal - 0.48) * 140) / 730, 0, 1);

    let dSun = dist(x, y, sunX, sunY);
    let sunProx = constrain(1 - dSun / 380, 0, 1);
    let col = sampleDustColor(effectiveY, sunProx);

    brush.set("dust_grain", col, random(0.65, 1.45));
    brush.flowLine(x, y, random(35, 95), random(-20, 20));
  }

  brush.noField();

  // Step 1F: "As if the sun has been strained through cloth"
  // Subtle cross-woven amber/ochre spray striation around the diffused sun core
  for (let i = 0; i < 180; i++) {
    let sx = sunX + randomGaussian(0, 165);
    let sy = sunY + randomGaussian(0, 125);
    if (sy > 40 && sy < 730) {
      let d = dist(sx, sy, sunX, sunY);
      let prox = constrain(1 - d / 360, 0, 1);
      if (prox > 0.05) {
        let col = lerpHex(PALETTE.ochreWarm, PALETTE.amberGlow, prox * random(0.5, 1.0));
        brush.set("silt_stipple", col, random(0.6, 1.3));
        if (i % 2 === 0) {
          brush.line(sx - random(25, 65), sy, sx + random(25, 65), sy + random(-4, 4));
        } else {
          brush.line(sx, sy - random(20, 50), sx + random(-3, 3), sy + random(20, 50));
        }
      }
    }
  }

  // Step 1G: Subtle Windshield Wiper Sweep Arc on the Glass
  // Outside the wiper's arc, a thicker film of ochre-umber silt clings to the glass
  const sweepCx = 460;
  const sweepCy = 760;
  for (let r = 615; r < 860; r += 12) {
    let arcPts = getEllipsePts(sweepCx, sweepCy, r, r * 0.95, 0, 28, 195, 345);
    let filtered = arcPts.filter((p) => p[0] > 40 && p[0] < 1180 && p[1] > 20 && p[1] < 730);
    if (filtered.length > 3) {
      brush.set("dust_grain", PALETTE.umberRust, 0.9);
      brush.spline(filtered, 0.4);
    }
  }
  // Faint radial wiper drag marks inside the glass arc
  for (let a = 202; a <= 332; a += 7) {
    let r1 = random(240, 580);
    let r2 = r1 + random(35, 85);
    let x1 = sweepCx + Math.cos(radians(a)) * r1;
    let y1 = sweepCy + Math.sin(radians(a)) * r1 * 0.95;
    let x2 = sweepCx + Math.cos(radians(a + 8)) * r2;
    let y2 = sweepCy + Math.sin(radians(a + 8)) * r2 * 0.95;
    if (y1 > 60 && y2 < 710) {
      brush.set("silt_stipple", PALETTE.amberStrained, 0.55);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Fine airborne grit stipple across the lower windshield
  for (let i = 0; i < 320; i++) {
    let gx = random(60, 1180);
    let gy = random(420, 745);
    let col = random() < 0.5 ? PALETTE.ochreWarm : PALETTE.rustCore;
    brush.set("silt_stipple", col, random(0.4, 1.1));
    brush.line(gx, gy, gx + random(2, 10), gy + random(-2, 2));
  }
}

// =============================================================================
// 2. WINDSHIELD WIPERS & SETTLING GRIT (BRUTALLY SHARP FOREGROUND)
// =============================================================================
function renderWipersAndGrit() {
  brush.noField();

  // --- Driver-side main wiper assembly ---
  // Blade spans from (125, 684) to (805, 728)
  const bx1 = 125, by1 = 684;
  const bx2 = 805, by2 = 728;

  // 2A: Heavy bank of ochre/rust grit settled along the top lip of the wiper blade
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let gx = lerp(bx1, bx2, t);
    let gy = lerp(by1, by2, t);
    // Wind-drifted silt mound just above the rubber blade
    let driftH = 8 + Math.sin(t * Math.PI) * 10 + noise(t * 12) * 8;
    brush.set("fine_marker", lerpHex(PALETTE.rustDark, PALETTE.ochreCore, noise(t * 8)), 0.8);
    brush.line(gx, gy - 2, gx + random(6, 18), gy - driftH);
  }

  // Dense spray of settled sand along the wiper trough
  for (let i = 0; i < 160; i++) {
    let t = random(0, 1);
    let gx = lerp(bx1 - 10, bx2 + 20, t);
    let gy = lerp(by1, by2, t) - random(-3, 14);
    let c = random([PALETTE.ochreWarm, PALETTE.ochreCore, PALETTE.rustCore, PALETTE.amberStrained]);
    brush.set("silt_stipple", c, random(0.6, 1.5));
    brush.line(gx, gy, gx + random(3, 12), gy - random(0, 5));
  }

  // 2B: Rubber squeegee strip & backing spine (exact marker + rotring pen)
  let rubberPoly = [
    [bx1, by1],
    [bx2, by2],
    [bx2, by2 + 12],
    [bx1, by1 + 12]
  ];
  brush.noStroke();
  brush.wash(PALETTE.inkBlack, 240);
  drawShapePoly(rubberPoly, 0, true);
  brush.noWash();

  // Steel backing spine on top of rubber
  let spinePoly = [
    [bx1 + 4, by1 - 4],
    [bx2 - 4, by2 - 4],
    [bx2, by2 + 2],
    [bx1, by1 + 2]
  ];
  brush.wash(PALETTE.vinylShadow, 230);
  drawShapePoly(spinePoly, 0, true);
  brush.noWash();

  // Tight marker shading along the blade
  for (let i = 0; i < 36; i++) {
    let t1 = i / 36;
    let t2 = (i + 0.7) / 36;
    let xA = lerp(bx1, bx2, t1), yA = lerp(by1, by2, t1);
    let xB = lerp(bx1, bx2, t2), yB = lerp(by1, by2, t2);
    brush.set("fine_marker", i % 2 === 0 ? PALETTE.vinylLit : PALETTE.vinylDark, 0.7);
    brush.line(xA, yA - 2, xB, yB - 2);
  }

  // 2C: Articulated steel wiper bridge / pantograph yokes
  // Left secondary yoke: (155, 684) -> arch at (270, 668) -> (385, 698)
  // Right secondary yoke: (535, 708) -> arch at (650, 692) -> (765, 723)
  // Primary central bridge: (270, 668) -> central pivot (460, 664) -> (650, 692)
  const drawBridgeBar = (x1, y1, xMid, yMid, x2, y2, thickness) => {
    let barPts = [
      [x1, y1],
      [xMid, yMid],
      [x2, y2],
      [x2, y2 + thickness],
      [xMid, yMid + thickness * 1.15],
