// 3. CRACKED VINYL DASHBOARD (HARD FINE PEN & TIGHT MARKER SHADING)
// =============================================================================
function renderDashboard() {
  brush.noField();

  // Dashboard upper contour (instrument hump on left, flat shelf on center/right)
  const dashTopProfile = [
    [0, 718],
    [85, 706],
