  const dashBrowProfile = [
    [0, 918],
    [110, 888],
    [255, 874],
    [415, 882],
    [535, 922],
    [680, 946],
    [860, 956],
    [1040, 964],
    [1200, 970]
  ];

  // Lower overhang lip of the padded vinyl brow
  const dashLipProfile = [
    [0, 968],
