  ];

  // Step 3A: Solid dark base washes for the dashboard zones
  brush.noStroke();

  // Full lower cabin abyss (y = 700..1200)
  brush.wash(PALETTE.vinylAbyss, 255);
  drawShapePoly(
    [
      ...dashTopProfile,
      [1200, 1200],
      [0, 1200]
    ],
    0,
    true
  );

  // Top vinyl pad base wash
  let topPadPoly = [...dashTopProfile, ...dashBrowProfile.slice().reverse()];
  brush.wash(PALETTE.vinylDark, 250);
  drawShapePoly(topPadPoly, 0, true);

  // Bullnose front roll base wash
  let bullnosePoly = [...dashBrowProfile, ...dashLipProfile.slice().reverse()];
  brush.wash(PALETTE.vinylAbyss, 250);
  drawShapePoly(bullnosePoly, 0, true);
  brush.noWash();

  // Step 3B: Tight Marker Shading Across the Top Vinyl Pad
  // We shade in directional strips following the molded contour of the pickup dash
  const numCols = 115;
  for (let i = 0; i < numCols; i++) {
    let t = i / (numCols - 1);
    let x = t * 1200;

    // Interpolate top Y and brow Y at this X
    let yTop = interpProfileY(dashTopProfile, x);
    let yBrow = interpProfileY(dashBrowProfile, x);
    let yLip = interpProfileY(dashLipProfile, x);

    // Surface angle lighting: brighter near the strained sun X (485) and on the instrument hump crown
    let sunFactor = constrain(1 - Math.abs(x - 490) / 580, 0, 1);
    let humpBoost = x > 140 && x < 480 ? 0.25 : 0;
    let lightLevel = constrain(sunFactor * 0.75 + humpBoost, 0.1, 1.0);

    // Back zone of dash pad (closest to windshield glass - catches warm amber skylight)
    let yMid1 = lerp(yTop, yBrow, 0.35);
    let yMid2 = lerp(yTop, yBrow, 0.72);

    let colBack = lerpHex(PALETTE.vinylMid, PALETTE.vinylWarm, lightLevel);
    let colCenter = lerpHex(PALETTE.vinylShadow, PALETTE.vinylLit, lightLevel);
    let colFront = lerpHex(PALETTE.vinylDark, PALETTE.vinylMid, lightLevel * 0.8);

    brush.set("chisel_marker", colBack, 1.15);
