// Helper to interpolate Y along a profile polyline at a given X
function interpProfileY(profile, x) {
  if (x <= profile[0][0]) return profile[0][1];
  if (x >= profile[profile.length - 1][0]) return profile[profile.length - 1][1];
  for (let i = 0; i < profile.length - 1; i++) {
    let x1 = profile[i][0], y1 = profile[i][1];
    let x2 = profile[i + 1][0], y2 = profile[i + 1][1];
    if (x >= x1 && x <= x2) {
      let t = (x - x1) / (x2 - x1);
      return lerp(y1, y2, t);
    }
  }
  return profile[0][1];
}

// Detailed renderer for a sun-split vinyl crack with curled edges and exposed foam
function renderVinylCrack(spinePts, maxWidth) {
  // Resample spine into fine steps with jagged micro-jitter
  let dense = [];
  for (let i = 0; i < spinePts.length - 1; i++) {
    let p1 = spinePts[i];
    let p2 = spinePts[i + 1];
    let steps = 8;
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let jx = (i === 0 && s === 0) ? 0 : random(-2.2, 2.2);
      let jy = (i === 0 && s === 0) ? 0 : random(-1.5, 1.5);
      dense.push([lerp(p1[0], p2[0], t) + jx, lerp(p1[1], p2[1], t) + jy]);
    }
  }
  dense.push(spinePts[spinePts.length - 1]);

  let leftEdge = [];
  let rightEdge = [];
  let outerCurlLeft = [];
  let outerCurlRight = [];

  for (let i = 0; i < dense.length; i++) {
    let u = i / (dense.length - 1);
    // Width tapers to 0 at both ends, widest in middle
    let wProfile = Math.sin(u * Math.PI) * maxWidth * (0.75 + 0.35 * noise(i * 0.6));
    let p = dense[i];
    leftEdge.push([p[0] - wProfile * 0.5, p[1]]);
    rightEdge.push([p[0] + wProfile * 0.5, p[1]]);
    outerCurlLeft.push([p[0] - wProfile * 0.5 - 4.5, p[1] - 1]);
    outerCurlRight.push([p[0] + wProfile * 0.5 + 4.5, p[1] - 1]);
  }

  // 1. Dark shadow trough cast under the curled-up vinyl lips
  brush.set("fine_marker", PALETTE.inkBlack, 0.95);
  brush.spline(outerCurlLeft, 0.2);
  brush.spline(outerCurlRight, 0.2);

  // 2. Exposed crumbling ochre-rust polyurethane foam inside the crack canyon
  let crackPoly = [...leftEdge, ...rightEdge.slice().reverse()];
  brush.noStroke();
  brush.wash(PALETTE.foamDark, 245);
  drawShapePoly(crackPoly, 0, true);
  brush.noWash();

  // Cellular foam texture and cross-hatching inside the split
  for (let i = 2; i < dense.length - 2; i++) {
    let lPt = leftEdge[i];
    let rPt = rightEdge[i];
    let cw = rPt[0] - lPt[0];
    if (cw > 2.5) {
      brush.set("razor_pen", i % 2 === 0 ? PALETTE.foamLight : PALETTE.inkBlack, 0.45);
      brush.line(lPt[0] + 1, lPt[1], rPt[0] - 1, rPt[1] + random(-2, 2));
      if (cw > 6) {
        brush.set("razor_pen", PALETTE.amberStrained, 0.45);
        brush.line(
          lerp(lPt[0], rPt[0], 0.3),
          lPt[1] - 1,
          lerp(lPt[0], rPt[0], 0.75),
          rPt[1] + 1
        );
      }
    }
  }

  // 3. Crisp rotring pen edges of the torn vinyl skin
  brush.set("rotring", PALETTE.inkBlack, 0.65);
  brush.spline(leftEdge, 0.15);
  brush.spline(rightEdge, 0.15);

  // 4. Sharp amber specular highlight on the upturned curl facing the windshield light
  brush.set("razor_pen", PALETTE.amberGlow, 0.7);
  brush.spline(rightEdge, 0.15);
  brush.set("razor_pen", PALETTE.ochreWarm, 0.55);
  brush.spline(leftEdge, 0.15);
}

