// =============================================================================
// 5. COFFEE CUP & PLASTIC LID ON DASHBOARD (EXACT PLASTIC TEXTURES)
// =============================================================================
function renderCoffeeCupAndLid() {
  brush.noField();

  const cx = 945;
  const lidY = 738;
  const cupBottomY = 1012;
  const topRx = 110;
  const botRx = 78;
  const botRy = 22;

  // Step 5A: Cast Shadow of the Coffee Cup across the Cracked Vinyl Dashboard
  let shadowPts = getEllipsePts(cx + 68, cupBottomY + 4, 118, 30, 8, 36);
  brush.noStroke();
  brush.wash(PALETTE.inkBlack, 215);
  drawShapePoly(shadowPts, 0, true);
  brush.noWash();

  // Tight marker hatching feathering the cast shadow over the dashboard bullnose
  for (let sy = cupBottomY - 18; sy <= cupBottomY + 28; sy += 4) {
    brush.set("fine_marker", PALETTE.inkBlack, 0.85);
    brush.line(cx - 45, sy, cx + 175, sy + 8);
  }

  // Step 5B: Paper Coffee Cup Body & Corrugated Kraft Insulating Sleeve
  let bottomArc = getEllipsePts(cx, cupBottomY, botRx, botRy, 0, 28, 0, 180);
  let cupBodyPoly = [
    [cx - topRx, lidY + 18],
    [cx + topRx, lidY + 18],
    ...bottomArc
  ];
  brush.noStroke();
  brush.wash(PALETTE.lidMidDark, 250);
  drawShapePoly(cupBodyPoly, 0, true);
  brush.noWash();

  // Cylindrical vertical marker shading across the cup body (lit from left/amber dust wall)
  const numCupStrips = 46;
  for (let i = 0; i < numCupStrips; i++) {
    let u = i / (numCupStrips - 1); // 0 (left edge) to 1 (right edge)
    let xTop = lerp(cx - topRx + 2, cx + topRx - 2, u);
    let xBot = lerp(cx - botRx + 2, cx + botRx - 2, u);
    let yBot = cupBottomY + Math.sin(Math.acos(constrain((u - 0.5) * 2, -1, 1))) * botRy;

    // Cylindrical lighting profile: bright warm amber at u ~ 0.18, core shadow at u ~ 0.78, rim bounce at u ~ 0.95
    let col;
    if (u < 0.12) {
      col = lerpHex(PALETTE.lidWarm, PALETTE.lidLit, u / 0.12);
    } else if (u < 0.35) {
      col = lerpHex(PALETTE.lidLit, PALETTE.lidAmber, (u - 0.12) / 0.23);
    } else if (u < 0.68) {
      col = lerpHex(PALETTE.lidAmber, PALETTE.lidMidDark, (u - 0.35) / 0.33);
    } else if (u < 0.88) {
      col = lerpHex(PALETTE.lidMidDark, PALETTE.vinylAbyss, (u - 0.68) / 0.2);
    } else {
      col = lerpHex(PALETTE.vinylAbyss, PALETTE.lidMid, (u - 0.88) / 0.12);
    }

    brush.set("fine_marker", col, 1.05);
    brush.line(xTop, lidY + 20, xBot, yBot - 2);
  }

  // Corrugated cardboard coffee sleeve (y = 805..945)
  const sleeveTopY = 806;
  const sleeveBotY = 944;
  const slTopRx = lerp(topRx, botRx, (sleeveTopY - lidY) / (cupBottomY - lidY)) + 3;
  const slBotRx = lerp(topRx, botRx, (sleeveBotY - lidY) / (cupBottomY - lidY)) + 3;

  let slTopArc = getEllipsePts(cx, sleeveTopY, slTopRx, 28, 0, 28, 0, 180);
  let slBotArc = getEllipsePts(cx, sleeveBotY, slBotRx, 24, 0, 28, 0, 180);
  let sleevePoly = [...slTopArc, ...slBotArc.slice().reverse()];

  // Vertical corrugated flutes on the cardboard sleeve
  const numFlutes = 34;
  for (let f = 0; f < numFlutes; f++) {
    let u = f / (numFlutes - 1);
    let a = radians(lerp(178, 2, u));
    let x1 = cx + Math.cos(a) * slTopRx;
    let y1 = sleeveTopY + Math.sin(a) * 28;
    let x2 = cx + Math.cos(a) * slBotRx;
    let y2 = sleeveBotY + Math.sin(a) * 24;

    // Dark flute trough + warm kraft ridge
    let ridgeCol = u < 0.45 ? PALETTE.ochreCore : u < 0.75 ? PALETTE.rustDark : PALETTE.umberBruise;
    brush.set("fine_marker", ridgeCol, 0.75);
    brush.line(x1, y1, x2, y2);

    brush.set("rotring", PALETTE.inkBlack, 0.45);
    brush.line(x1 + 2.2, y1, x2 + 2.2, y2);

    if (u > 0.06 && u < 0.48) {
      brush.set("razor_pen", PALETTE.amberStrained, 0.45);
      brush.line(x1 - 1, y1, x2 - 1, y2);
    }
  }

  // Crisp pen outlines for cup body and sleeve
  brush.set("rotring", PALETTE.inkBlack, 0.65);
  brush.spline(slTopArc, 0.3);
  brush.spline(slBotArc, 0.3);
  brush.line(cx - slTopRx, sleeveTopY, cx - slBotRx, sleeveBotY);
  brush.line(cx + slTopRx, sleeveTopY, cx + slBotRx, sleeveBotY);
  brush.spline(bottomArc, 0.3);
  brush.line(cx - topRx, lidY + 20, cx - slTopRx + 2, sleeveTopY);
  brush.line(cx + topRx, lidY + 20, cx + slTopRx - 2, sleeveTopY);
  brush.line(cx - slBotRx + 2, sleeveBotY, cx - botRx, cupBottomY);
  brush.line(cx + slBotRx - 2, sleeveBotY, cx + botRx, cupBottomY);

  // Dark cast shadow directly under the overhanging plastic lid skirt
  let underLidArc = getEllipsePts(cx, lidY + 22, topRx + 1, 33, 0, 28, 0, 180);
  brush.set("chisel_marker", PALETTE.inkBlack, 0.9);
  brush.spline(underLidArc, 0.35);

  // ===========================================================================
  // Step 5C: THE THERMOFORMED PLASTIC COFFEE CUP LID (BRUTALLY SHARP FOCUS)
  // ===========================================================================
  // Concentric anatomical tiers of the disposable dome lid:
  // Tier 1: Lower snap-fit skirt (cy = 738..748, rx = 116, ry = 34)
  // Tier 2: Sloped conical dome wall rising to (cy = 712, rx = 105, ry = 30)
  // Tier 3: Raised outer drinking rim torus (cy = 710, rx = 104->88, ry = 30->24)
  // Tier 4: Recessed top basin well (cy = 718, rx = 86, ry = 23)
  // Tier 5: Central raised caution disk (cy = 713, rx = 50, ry = 13.5)

  // Base solid wash for the entire plastic lid silhouette
  let skirtBotArc = getEllipsePts(cx, lidY + 12, 116, 35, 0, 36, 0, 180);
  let rimTopArc = getEllipsePts(cx, lidY - 28, 104, 29, 0, 36, 180, 360);
  let lidSilhouette = [...rimTopArc, ...skirtBotArc];

  brush.noStroke();
  brush.wash(PALETTE.lidMid, 250);
  drawShapePoly(lidSilhouette, 0, true);
  brush.noWash();

  // Shade the outer skirt & conical dome wall with tight vertical marker strokes
  const numLidStrips = 56;
  for (let i = 0; i < numLidStrips; i++) {
    let u = i / (numLidStrips - 1);
    let a = radians(lerp(180, 0, u));
    let cosA = Math.cos(a);
    let sinA = Math.sin(a);

    let xTop = cx + cosA * 104;
    let yTop = (lidY - 26) + sinA * 29;
    let xMid = cx + cosA * 115;
    let yMid = (lidY + 2) + sinA * 34;
    let xBot = cx + cosA * 116;
    let yBot = (lidY + 12) + sinA * 35;

    // High-contrast plastic reflection of the strained amber light
    let colWall, colSkirt;
    if (u < 0.14) {
      colWall = PALETTE.lidAmber;
      colSkirt = PALETTE.lidWarm;
    } else if (u < 0.34) {
      colWall = PALETTE.lidHighlight;
      colSkirt = PALETTE.lidLit;
    } else if (u < 0.58) {
      colWall = lerpHex(PALETTE.lidLit, PALETTE.lidWarm, (u - 0.34) / 0.24);
      colSkirt = lerpHex(PALETTE.lidAmber, PALETTE.lidMid, (u - 0.34) / 0.24);
    } else if (u < 0.84) {
      colWall = lerpHex(PALETTE.lidWarm, PALETTE.lidShadow, (u - 0.58) / 0.26);
      colSkirt = lerpHex(PALETTE.lidMid, PALETTE.inkBlack, (u - 0.58) / 0.26);
    } else {
      colWall = PALETTE.lidMid;
      colSkirt = PALETTE.lidMidDark;
    }

    brush.set("fine_marker", colWall, 0.85);
    brush.line(xTop, yTop, xMid, yMid);
    brush.set("fine_marker", colSkirt, 0.85);
    brush.line(xMid, yMid, xBot, yBot);

    // Fine vertical grip serrations molded into the lower snap skirt
    if (i % 2 === 0) {
      brush.set("razor_pen", u < 0.45 ? PALETTE.lidSpec : PALETTE.inkBlack, 0.45);
      brush.line(xMid, yMid + 1, xBot, yBot - 1);
    }
  }

  // Recessed Top Basin Well (cy = 716, rx = 88, ry = 24)
  // Because light comes from the left, the INSIDE left wall of the recess is in shadow,
  // while the INSIDE right wall faces the light!
  let wellEllipse = getEllipsePts(cx, lidY - 22, 88, 24, 0, 48);
  brush.noStroke();
  brush.wash(PALETTE.lidWarm, 245);
  drawShapePoly(wellEllipse, 0, true);
  brush.noWash();

  // Shade across the recessed basin floor and inner walls with tight marker lines
  for (let i = -84; i <= 84; i += 4) {
    let u = (i + 84) / 168; // 0 (left) to 1 (right)
    let halfH = Math.sqrt(Math.max(0, 1 - (i / 86) * (i / 86))) * 23;
    let x = cx + i;
    let y1 = lidY - 22 - halfH;
    let y2 = lidY - 22 + halfH;

    // Inside a recessed well, left side (u < 0.28) has a cast shadow from the left rim;
    // right side (u > 0.55) catches the warm amber light!
    let wellCol =
      u < 0.25
        ? lerpHex(PALETTE.lidShadow, PALETTE.lidMidDark, u / 0.25)
        : u < 0.65
        ? lerpHex(PALETTE.lidMid, PALETTE.lidAmber, (u - 0.25) / 0.4)
        : lerpHex(PALETTE.lidAmber, PALETTE.lidHighlight, (u - 0.65) / 0.35);

    brush.set("fine_marker", wellCol, 0.8);
    brush.line(x, y1 + 1, x, y2 - 1);
  }

  // Inner vertical wall of the recessed well (visible along the back half: 180..360 deg)
  for (let a = 185; a <= 355; a += 4) {
    let rad = radians(a);
    let wx = cx + Math.cos(rad) * 87;
    let wyTop = lidY - 28 + Math.sin(rad) * 24;
    let wyBot = lidY - 19 + Math.sin(rad) * 24;
    let isLitRight = a > 265;
    brush.set("fine_marker", isLitRight ? PALETTE.lidHighlight : PALETTE.lidShadow, 0.7);
    brush.line(wx, wyTop, wx, wyBot);
  }

  // Raised Outer Drinking Rim Torus (between rx = 104 and rx = 88 at cy = lidY - 28)
  for (let a = 0; a < 360; a += 5) {
    let rad1 = radians(a);
    let rad2 = radians(a + 6);
    let x1 = cx + Math.cos(rad1) * 96;
    let y1 = lidY - 28 + Math.sin(rad1) * 26.5;
    let x2 = cx + Math.cos(rad2) * 96;
    let y2 = lidY - 28 + Math.sin(rad2) * 26.5;

    let isBright = a > 125 && a < 265;
    let rimCol = isBright
      ? PALETTE.lidHighlight
      : a > 265 || a < 45
      ? PALETTE.lidWarm
      : PALETTE.lidAmber;
    brush.set("fine_marker", rimCol, 0.9);
    brush.line(x1, y1, x2, y2);
  }

  // Central Raised Plateau Disk inside the well (cx, lidY - 24, rx = 48, ry = 13)
  let centerDisk = getEllipsePts(cx, lidY - 24, 48, 13, 0, 36);
  let centerDiskBase = getEllipsePts(cx, lidY - 20, 50, 14, 0, 24, 0, 180);
  brush.noStroke();
  brush.wash(PALETTE.lidAmber, 245);
  drawShapePoly(centerDisk, 0, true);
  brush.noWash();

  // Shade central plateau & its front step bevel
  brush.set("fine_marker", PALETTE.lidShadow, 0.75);
  brush.spline(centerDiskBase, 0.35);
  brush.set("fine_marker", PALETTE.lidLit, 0.8);
  brush.line(cx - 42, lidY - 25, cx + 25, lidY - 25);

  // Embossed micro-details on central disk (recycling triangle, "HOT" ridges, vent pinhole)
  brush.set("rotring", PALETTE.inkBlack, 0.5);
  brush.spline(centerDisk, 0.35);
  brush.set("razor_pen", PALETTE.lidSpec, 0.65);
  let diskGlint = getEllipsePts(cx, lidY - 24, 47, 12.5, 0, 18, 130, 270);
  brush.spline(diskGlint, 0.35);

  // Tiny steam vent pinhole at (cx + 22, lidY - 24)
  brush.set("rotring", PALETTE.inkBlack, 0.65);
  brush.circle(cx + 22, lidY - 24, 2.2, 0.05);
  brush.set("razor_pen", PALETTE.lidSpec, 0.5);
  brush.arc(cx + 22, lidY - 24, 2.6, 0, 180);

  // Embossed caution ridges across the center disk
  for (let ex = cx - 28; ex <= cx + 8; ex += 5) {
    brush.set("razor_pen", PALETTE.lidMidDark, 0.4);
    brush.line(ex, lidY - 26, ex + 2, lidY - 22);
    brush.set("razor_pen", PALETTE.lidSpec, 0.4);
    brush.line(ex + 1, lidY - 26, ex + 3, lidY - 22);
  }

  // SIP HOLE & FOLDED-BACK DRINKING TAB on the Front-Left Rim (around a = 152 deg)
  const sipX = cx - 84;
  const sipY = lidY - 15;
  let sipHolePts = getEllipsePts(sipX, sipY, 13, 5.5, 18, 20);
  brush.noStroke();
  brush.wash(PALETTE.inkBlack, 255);
  drawShapePoly(sipHolePts, 0, true);
  brush.noWash();

  // Folded-back plastic lock tab behind the sip hole at (sipX + 18, sipY - 5)
  let tabPts = getEllipsePts(sipX + 17, sipY - 4, 11, 4.5, 15, 18);
  brush.noStroke();
  brush.wash(PALETTE.lidLit, 240);
  drawShapePoly(tabPts, 0, true);
  brush.noWash();
  brush.set("rotring", PALETTE.inkBlack, 0.5);
  drawShapePoly(tabPts, 0, true);
  brush.set("razor_pen", PALETTE.lidSpec, 0.65);
  brush.line(sipX + 8, sipY - 6, sipX + 25, sipY - 3);

  // Dried amber-brown coffee ring stain around the sip hole!
  brush.set("fine_marker", PALETTE.coffeeStain, 0.6);
  let stainPts = getEllipsePts(sipX + 2, sipY + 1, 15, 6.5, 18, 20);
  brush.spline(stainPts, 0.35);
  brush.set("razor_pen", PALETTE.rustCore, 0.55);
  brush.arc(sipX - 4, sipY + 5, 5, 10, 190);

  // Crisp Technical Pen Contour Ellipses & Specular Highlights on the Lid
  const lidEllipses = [
    { cy: lidY + 12, rx: 116, ry: 35, start: 0, end: 180, w: 0.7 },
    { cy: lidY + 2, rx: 115, ry: 34, start: 0, end: 180, w: 0.6 },
    { cy: lidY - 4, rx: 112, ry: 32.5, start: 0, end: 180, w: 0.45 },
    { cy: lidY - 28, rx: 104, ry: 29, start: 0, end: 360, w: 0.65 },
    { cy: lidY - 28, rx: 88, ry: 24, start: 0, end: 360, w: 0.55 },
    { cy: lidY - 19, rx: 86, ry: 23, start: 185, end: 355, w: 0.5 }
  ];

  for (let el of lidEllipses) {
    let pts = getEllipsePts(cx, el.cy, el.rx, el.ry, 0, 44, el.start, el.end);
    brush.set("rotring", PALETTE.inkBlack, el.w);
    brush.spline(pts, 0.35);
  }
  // Left & right profile edges of the conical lid wall
  brush.set("rotring", PALETTE.inkBlack, 0.7);
  brush.line(cx - 104, lidY - 28, cx - 115, lidY + 2);
  brush.line(cx - 115, lidY + 2, cx - 116, lidY + 12);
  brush.line(cx + 104, lidY - 28, cx + 115, lidY + 2);
  brush.line(cx + 115, lidY + 2, cx + 116, lidY + 12);

  // Razor-sharp amber-white specular streaks on the plastic lid rims
  const specArcs = [
    { cy: lidY - 29, rx: 100, ry: 27.5, s: 135, e: 245, w: 0.9 },
    { cy: lidY - 28, rx: 93, ry: 25.5, s: 300, e: 55, w: 0.75 },
    { cy: lidY + 1, rx: 114, ry: 33.5, s: 120, e: 172, w: 0.85 },
    { cy: lidY + 10, rx: 115, ry: 34.5, s: 125, e: 168, w: 0.65 }
  ];
  for (let sp of specArcs) {
    let sPts = getEllipsePts(cx, sp.cy, sp.rx, sp.ry, 0, 20, sp.s, sp.e);
    brush.set("razor_pen", PALETTE.lidSpec, sp.w);
    brush.spline(sPts, 0.35);
  }

  // Fine radial pen hatching on the shadow side of the plastic lid (right side)
  for (let a = 10; a <= 82; a += 5) {
    let rad = radians(a);
    let x1 = cx + Math.cos(rad) * 104;
    let y1 = lidY - 28 + Math.sin(rad) * 29;
    let x2 = cx + Math.cos(rad) * 115;
    let y2 = lidY + 2 + Math.sin(rad) * 34;
    brush.set("razor_pen", PALETTE.inkBlack, 0.42);
    brush.line(x1, y1, x2, y2);
  }
}

// =============================================================================
// 6. DANGLING ROSARY (SHARP FOREGROUND SILHOUETTE & BEAD SPECULARS)
// =============================================================================
function renderDanglingRosary() {
  brush.noField();

  // The rosary hangs from the rearview mirror stem at (639, 62),
  // looping down to the San Benito / Marian centerpiece medal at (636, 312),
