// ============================================================================
// GEOMETRY & SPLINE EVALUATION HELPERS
// ============================================================================

function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * t +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
  let r =
    0.5 *
    (2 * p1[2] +
      (-p0[2] + p2[2]) * t +
      (2 * p0[2] - 5 * p1[2] + 4 * p2[2] - p3[2]) * t2 +
      (-p0[2] + 3 * p1[2] - 3 * p2[2] + p3[2]) * t3);
  return [x, y, r];
}

function sampleTubeCurve(ctrlPts, numSamples = 120) {
  let pts = [];
  let n = ctrlPts.length;
  // Extrapolate endpoints for smooth Catmull-Rom evaluation
  let ext = [
    [
      2 * ctrlPts[0][0] - ctrlPts[1][0],
      2 * ctrlPts[0][1] - ctrlPts[1][1],
      ctrlPts[0][2]
    ],
    ...ctrlPts,
    [
      2 * ctrlPts[n - 1][0] - ctrlPts[n - 2][0],
      2 * ctrlPts[n - 1][1] - ctrlPts[n - 2][1],
      ctrlPts[n - 1][2]
    ]
  ];

  let segCount = n - 1;
  for (let i = 0; i <= numSamples; i++) {
    let u = (i / numSamples) * segCount;
    let idx = Math.min( Math.floor(u), segCount - 1 );
    let localT = u - idx;
    let p = evalCatmullRom(
      ext[idx],
      ext[idx + 1],
      ext[idx + 2],
      ext[idx + 3],
      localT
    );
    pts.push({ x: p[0], y: p[1], r: p[2], t: i / numSamples });
  }

  // Compute smooth tangents and normals
  for (let i = 0; i <= numSamples; i++) {
    let prev = pts[Math.max(0, i - 1)];
    let next = pts[Math.min(numSamples, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let len = Math.hypot(dx, dy) || 1;
    pts[i].tx = dx / len;
    pts[i].ty = dy / len;
    // Left-hand normal
    pts[i].nx = -pts[i].ty;
    pts[i].ny = pts[i].tx;
  }
  return pts;
}

function drawPolyShape(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function extractOffsetSubcurve(samples, iStart, iEnd, sFn, numOut = 10) {
  let out = [];
  for (let k = 0; k <= numOut; k++) {
    let idxF = iStart + ((iEnd - iStart) * k) / numOut;
    let i0 = Math.floor(idxF);
    let i1 = Math.min(samples.length - 1, i0 + 1);
    let f = idxF - i0;
    let p0 = samples[i0];
    let p1 = samples[i1];
    let x = p0.x + (p1.x - p0.x) * f;
    let y = p0.y + (p1.y - p0.y) * f;
    let r = p0.r + (p1.r - p0.r) * f;
    let nx = p0.nx + (p1.nx - p0.nx) * f;
    let ny = p0.ny + (p1.ny - p0.ny) * f;
    let nLen = Math.hypot(nx, ny) || 1;
    nx /= nLen;
    ny /= nLen;
    let t = p0.t + (p1.t - p0.t) * f;
    let s = typeof sFn === "function" ? sFn(t, nx, ny) : sFn;
    out.push([x + s * r * nx, y + s * r * ny]);
  }
  return out;
}

