  // Vanishing point high above canvas for worm's-eye vertical convergence
  const vpX = 600;
  const vpY = -2400;

  // Course Y heights (expanding slightly downward as courses get closer to viewer)
  const courseY = [-20, 110, 260, 425, 610, 815, 1040, 1250];

  // Helper for arched worm's-eye horizontal course Y
  function archY(x, baseY) {
    let normX = (x - 600) / 600;
    // Slight upward bow in center due to wide-angle worm's-eye elevation
    let arch = -18 * (1 - normX * normX) * (1 - baseY / 1600);
    return baseY + arch;
  }

  // Helper to project x along converging vertical lines toward high VP
  function convX(baseX, y) {
    let factor = (y - vpY) / (600 - vpY);
    return vpX + (baseX - vpX) * factor;
  }

  // Collect stone block polygons into 4 muted cool-limestone color batches
  let batches = {
    "#dcdbd2": [],
    "#cfd4cc": [],
    "#c4cbc4": [],
    "#e2e1d8": []
  };
  let batchKeys = Object.keys(batches);
  let allBlocks = [];

  for (let r = 0; r < courseY.length - 1; r++) {
    let yTop = courseY[r];
    let yBot = courseY[r + 1];
    let offset = (r % 2) * 165 - 80;
    let joints = [-140];
    let curX = -140 + offset;
    while (curX < 1340) {
      curX += 290 + ((r * 53 + joints.length * 71) % 90);
      joints.push(curX);
    }

    for (let c = 0; c < joints.length - 1; c++) {
      let bx1 = joints[c] + 5;
      let bx2 = joints[c + 1] - 5;
      let xm = (bx1 + bx2) * 0.5;
      let poly = [
        [convX(bx1, yTop + 4), archY(bx1, yTop + 4)],
        [convX(xm, yTop + 4), archY(xm, yTop + 4)],
        [convX(bx2, yTop + 4), archY(bx2, yTop + 4)],
        [convX(bx2, yBot - 5), archY(bx2, yBot - 5)],
        [convX(xm, yBot - 5), archY(xm, yBot - 5)],
        [convX(bx1, yBot - 5), archY(bx1, yBot - 5)]
      ];
      let bKey = batchKeys[(r * 3 + c * 5) % batchKeys.length];
      batches[bKey].push(poly);
      allBlocks.push({ poly, r, c, bx1, bx2, yTop, yBot });
    }
  }

  // Render stone block washes in color batches for optimal fill caching
  brush.set("HB", "#b8beb7", 0.5);
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.22);

  for (let col of batchKeys) {
    brush.fill(col, 34);
    for (let poly of batches[col]) {
      // Inset slightly for soft stone modulation
      let inset = poly.map((p) => [
        p[0] + random(-6, 6),
        p[1] + random(-4, 4)
      ]);
      drawPolyShape(inset, 0.15);
    }
  }

  // Vertical damp/verdigris mineral weathering trail beneath the bracket & hose
  brush.fill("#aec2ba", 24);
  brush.fillBleed(0.35, "out");
  drawPolyShape([
    [520, 260],
    [680, 260],
    [760, 720],
    [710, 1190],
    [510, 1190],
    [465, 720]
  ], 0.3);

  brush.fill("#9bb3aa", 20);
  drawPolyShape([
    [560, 340],
    [645, 340],
    [690, 880],
    [665, 1190],
    [555, 1190],
    [530, 880]
  ], 0.3);

  brush.noFill();

  // Worm's-eye mortar joints: each stone block shows a dark underside soffit lip
  // along its bottom edge and a pale sky-lit upper arris below the joint!
  for (let r = 1; r < courseY.length - 1; r++) {
    let by = courseY[r];
    let shadowPts = [];
    let groovePts = [];
    let highlightPts = [];
    for (let x = -40; x <= 1240; x += 80) {
      let cx = convX(x, by);
      let cy = archY(cx, by);
      shadowPts.push([cx, cy - 3.5]);
      groovePts.push([cx, cy]);
      highlightPts.push([cx, cy + 3.2]);
    }
    // Dark underside soffit of upper stone block (worm's-eye reveal)
    brush.set("blend_marker", "#8d9690", 1.1);
    brush.spline(shadowPts, 0.3);

    // Recessed mortar joint shadow line
    brush.set("2B", "#626c66", 0.75);
    brush.spline(groovePts, 0.3);

    // Pale top edge catchlight on lower stone block
    brush.set("enamel_pen", "#f4f3ec", 0.55);
    brush.spline(highlightPts, 0.3);
  }

  // Vertical mortar joints with worm's-eye side reveal
  for (let b of allBlocks) {
    if (b.bx2 < 1220) {
      let xTop = convX(b.bx2 + 2.5, b.yTop + 4);
      let yTop = archY(xTop, b.yTop + 4);
      let xBot = convX(b.bx2 + 2.5, b.yBot - 4);
      let yBot = archY(xBot, b.yBot - 4);

      brush.set("blend_marker", "#97a19b", 0.85);
      brush.line(xTop, yTop, xBot, yBot);

      brush.set("2B", "#66706a", 0.65);
      brush.line(xTop + 2.5, yTop, xBot + 2.5, yBot);

      brush.set("enamel_pen", "#f2f1ea", 0.45);
      brush.line(xTop + 5.5, yTop, xBot + 5.5, yBot);
    }

    // Subtle chiselled draft marks & weathered stone pores (kept muted)
    let cx = (convX(b.bx1, b.yTop) + convX(b.bx2, b.yBot)) * 0.5;
    let cy = (archY(cx, b.yTop) + archY(cx, b.yBot)) * 0.5;
    brush.set("2H", "#8f9892", 0.42);
    for (let k = 0; k < 5; k++) {
      let px = cx + random(-110, 110);
      let py = cy + random(-55, 55);
      if (px > 20 && px < 1180 && py > 20 && py < 1180) {
        brush.line(px, py, px + random(14, 34), py + random(-6, 6));
      }
    }
  }
}

