// ============================================================================
// 3. SOFT ARCHITECTURAL CAST SHADOWS ON THE LIMESTONE WALL
// ============================================================================

function drawWallCastShadows(coils) {
  brush.set("HB", "#68756e", 0.5);
  brush.noStroke();

  // Outer soft penumbra batch
  brush.fill("#87968f", 38);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.35, 0.18);

  for (let c = 0; c < coils.length; c++) {
    let samples = coils[c];
    // Shift increases with coil index (more forward coils cast further shadows)
    let dxBase = 20 + c * 6.5;
    let dyBase = 30 + c * 9.5;
    let poly = [];
    for (let i = 0; i < samples.length; i += 3) {
      let p = samples[i];
      let depthScale = 0.8 + (p.y / 1000) * 0.55;
      poly.push([
        p.x + dxBase * depthScale + p.r * 0.92 * p.nx,
        p.y + dyBase * depthScale + p.r * 0.92 * p.ny
      ]);
    }
    for (let i = samples.length - 1; i >= 0; i -= 3) {
      let p = samples[i];
      let depthScale = 0.8 + (p.y / 1000) * 0.55;
      poly.push([
        p.x + dxBase * depthScale - p.r * 0.92 * p.nx,
        p.y + dyBase * depthScale - p.r * 0.92 * p.ny
      ]);
    }
    drawPolyShape(poly, 0.1);
  }

  // Bracket & Nozzle cast shadow on wall
  drawPolyShape([
    [555, 165],
    [675, 185],
    [735, 315],
    [685, 545],
    [575, 535],
    [545, 310]
  ], 0.25);

  drawPolyShape([
    [735, 965],
    [775, 985],
    [705, 1125],
    [658, 1105]
  ], 0.2);

  // Darker inner umbra for rear coils & bracket contact
  brush.fill("#63736b", 42);
  brush.fillBleed(0.18, "out");
  for (let c = 0; c < 3; c++) {
    let samples = coils[c];
    let dxBase = 16 + c * 5;
    let dyBase = 24 + c * 7;
    let poly = [];
    for (let i = 0; i < samples.length; i += 4) {
      let p = samples[i];
      poly.push([
        p.x + dxBase + p.r * 0.55 * p.nx,
        p.y + dyBase + p.r * 0.55 * p.ny
      ]);
    }
    for (let i = samples.length - 1; i >= 0; i -= 4) {
      let p = samples[i];
      poly.push([
        p.x + dxBase - p.r * 0.55 * p.nx,
        p.y + dyBase - p.r * 0.55 * p.ny
      ]);
    }
    drawPolyShape(poly, 0.1);
  }

  brush.noFill();
}

