// 6. HYPERREAL LAYERED MARKER & PEN HOSE RENDERING ENGINE
// ============================================================================

function getHoseMarkerColor(n3d, s) {
  // Dot products with 3D sky key light and worm's-eye ground/wall bounce light
  let skyDot =
    n3d[0] * LIGHT_3D[0] + n3d[1] * LIGHT_3D[1] + n3d[2] * LIGHT_3D[2];
  let bounceDot =
    n3d[0] * BOUNCE_3D[0] + n3d[1] * BOUNCE_3D[1] + n3d[2] * BOUNCE_3D[2];

  // Layered verdigris & bottle-green marker palette
  if (skyDot > 0.78) return "#7cd4b8"; // Brilliant cool verdigris sheen
  if (skyDot > 0.64) return "#52b898"; // Luminous verdigris marker
  if (skyDot > 0.48) return "#369c7b"; // Rich verdigris mid-light
  if (skyDot > 0.32) return "#238060"; // Verdigris-to-bottle transition
  if (skyDot > 0.16) return "#176348"; // Classic bottle green
  if (skyDot > 0.02) return "#0f4a35"; // Deep bottle green

  // Shadow hemisphere: check for worm's-eye underside reflected bounce light near rim
  if (bounceDot > 0.52 && Math.abs(s) > 0.68) return "#245e50"; // Cool slate-verdigris bounce rim
  if (bounceDot > 0.36 && Math.abs(s) > 0.55) return "#164236"; // Subtle reflected underside
  if (skyDot > -0.14) return "#0b3324"; // Core shadow entry
  return "#061d14"; // Abyssal bottle-green core shadow
}

function drawHyperrealHoseSegment(samples, frontCoils, coilIndex) {
  const N = samples.length - 1;

  // --- STEP A: Solid Opaque Base Under-Wash ---
  let outlinePoly = [];
  for (let i = 0; i <= N; i += 2) {
    let p = samples[i];
    outlinePoly.push([p.x - p.r * p.nx, p.y - p.r * p.ny]);
  }
  for (let i = N; i >= 0; i -= 2) {
    let p = samples[i];
    outlinePoly.push([p.x + p.r * p.nx, p.y + p.r * p.ny]);
  }
  brush.set("tech_pen", "#0b291e", 0.5);
  brush.noStroke();
  brush.wash("#0f3829", 252);
  drawPolyShape(outlinePoly, 0);
  brush.noWash();

  // --- STEP B: Layered Longitudinal Marker Shading (17 Cross-Sectional Bands) ---
  // Divide the curve into overlapping longitudinal marker passes so the color
  // responds accurately to the 3D cylindrical normal at every turn.
  const numChunks = 7;
  const bandOffsets = [
    -0.92, -0.82, -0.71, -0.59, -0.47, -0.35, -0.23, -0.11,
    0.0, 0.11, 0.23, 0.35, 0.47, 0.59, 0.71, 0.82, 0.92
  ];

  for (let b = 0; b < bandOffsets.length; b++) {
    let s = bandOffsets[b];
    let zComp = Math.sqrt(Math.max(0.02, 1 - s * s));
    let bName = Math.abs(s) > 0.75 ? "blend_marker" : "chisel_marker";
    let bWeight = Math.abs(s) > 0.75 ? 1.05 : 1.15;

    for (let c = 0; c < numChunks; c++) {
      let iStart = Math.max(0, Math.floor(((c - 0.18) / numChunks) * N));
      let iEnd = Math.min(N, Math.ceil(((c + 1.18) / numChunks) * N));
      let iMid = Math.floor((iStart + iEnd) * 0.5);
      let pm = samples[iMid];

      let n3d = [s * pm.nx, s * pm.ny, zComp];
      let col = getHoseMarkerColor(n3d, s);

      let subPts = extractOffsetSubcurve(samples, iStart, iEnd, s, 8);
      brush.set(bName, col, bWeight);
      brush.spline(subPts, 0.45);
    }
  }

  // --- STEP C: Subtle Rubber Extrusion Ribs & Core-Shadow Cross-Contour Pen Hatching ---
  const ribOffsets = [-0.64, -0.28, 0.08, 0.44, 0.74];
  for (let rOff of ribOffsets) {
    for (let c = 0; c < 4; c++) {
      let iStart = Math.floor((c / 4) * N);
      let iEnd = Math.min(N, Math.ceil(((c + 1.05) / 4) * N));
      let pm = samples[Math.floor((iStart + iEnd) * 0.5)];
      let lightDot = rOff * (pm.nx * LIGHT_3D[0] + pm.ny * LIGHT_3D[1]);
      let ribCol = lightDot > 0.1 ? "#42a888" : "#061c14";
      let ribPts = extractOffsetSubcurve(samples, iStart, iEnd, rOff, 9);
      brush.set("rotring", ribCol, 0.35);
      brush.spline(ribPts, 0.45);
    }
  }

  // Fine cylindrical cross-contour pen ticks along the core shadow side
  brush.set("rotring", "#051710", 0.36);
  for (let i = 4; i < N - 4; i += 3) {
    let p = samples[i];
    // Determine which side of p.nx/ny faces away from light
    let sideSign = p.nx * LIGHT_3D[0] + p.ny * LIGHT_3D[1] < 0 ? 1 : -1;
    let s1 = sideSign * 0.18;
    let s2 = sideSign * 0.86;
    // Slight elliptical curve along tangent for worm's-eye 3D cylinder contour
    let arch = 0.26 * p.r;
    let arcPts = [
      [p.x + s1 * p.r * p.nx, p.y + s1 * p.r * p.ny],
      [
        p.x + ((s1 + s2) * 0.5) * p.r * p.nx + arch * p.tx,
        p.y + ((s1 + s2) * 0.5) * p.r * p.ny + arch * p.ty
      ],
      [p.x + s2 * p.r * p.nx, p.y + s2 * p.r * p.ny]
    ];
    brush.spline(arcPts, 0.5);
  }

  // --- STEP D: Automatic 3D Cross-Coil Occlusion Shadows from Front Coils ---
  // Wherever a higher-Z front coil crosses over this coil, cast a curved dark
  // occlusion band across this cylinder's cross-section!
  for (let i = 2; i <= N - 2; i++) {
    let p = samples[i];
    let minDist = 9999;
    for (let fc of frontCoils) {
      for (let j = 0; j < fc.length; j += 3) {
        let fp = fc[j];
        // Offset front coil shadow slightly down-right (+5, +8) along light ray
        let d = Math.hypot(p.x - (fp.x + 5), p.y - (fp.y + 8)) - fp.r;
        if (d < minDist) minDist = d;
      }
    }
    if (minDist < p.r * 0.85) {
      let shadowStrength = map(minDist, -p.r * 0.6, p.r * 0.85, 1.0, 0.15, true);
      let arch = 0.22 * p.r;
      let occPts = [
        [p.x - 0.92 * p.r * p.nx, p.y - 0.92 * p.r * p.ny],
        [p.x + arch * p.tx, p.y + arch * p.ty],
        [p.x + 0.92 * p.r * p.nx, p.y + 0.92 * p.r * p.ny]
      ];
      brush.set(
        "blend_marker",
        minDist < 0 ? "#04120c" : "#0a261b",
        1.15 * shadowStrength
      );
      brush.spline(occPts, 0.45);

      if (minDist < p.r * 0.25) {
        brush.set("tech_pen", "#030d09", 0.65 * shadowStrength);
        brush.spline(occPts, 0.45);
      }
    }
  }

  // Also add saddle-arch underside shadow at the very top where coils rest under the bracket horn
  for (let i = 0; i <= N; i++) {
    let p = samples[i];
    if (p.y < 292 && p.x > 515 && p.x < 685 && coilIndex < 5) {
      brush.set("blend_marker", "#071f16", 0.95);
      brush.line(
        p.x - 0.8 * p.r * p.nx,
        p.y - 0.8 * p.r * p.ny,
        p.x + 0.8 * p.r * p.nx,
        p.y + 0.8 * p.r * p.ny
      );
    }
  }

  // --- STEP E: Hard Enamel Specular Highlights ---
  // Compute continuous 3D specular ridge s_spec(t) = A(t) / sqrt(A(t)^2 + H_z^2)
  let specHaloFn = (t, nx, ny) => {
    let A = nx * SPEC_HALF_3D[0] + ny * SPEC_HALF_3D[1];
    return A / Math.hypot(A, SPEC_HALF_3D[2] * 0.72);
  };

  // 1. Luminous cyan-verdigris enamel under-glaze along the specular ridge
  for (let c = 0; c < 6; c++) {
    let iStart = Math.floor((c / 6) * N);
    let iEnd = Math.min(N, Math.ceil(((c + 1) / 6) * N));
    let pm = samples[Math.floor((iStart + iEnd) * 0.5)];
    let A = Math.abs(pm.nx * LIGHT_3D[0] + pm.ny * LIGHT_3D[1]);
    if (A > 0.18) {
      let haloPts = extractOffsetSubcurve(samples, iStart, iEnd, specHaloFn, 9);
      brush.set("blend_marker", "#9ae6cf", 0.85 * A);
      brush.spline(haloPts, 0.45);
    }
  }

  // 2. Primary crisp hard-enamel white & ice-mint specular strips (broken into glossy runs)
  const specIntervals = [
    [0.03, 0.19],
    [0.22, 0.41],
    [0.45, 0.66],
    [0.70, 0.88],
    [0.90, 0.97]
  ];
  for (let [t0, t1] of specIntervals) {
    let iStart = Math.floor(t0 * N);
    let iEnd = Math.floor(t1 * N);
    if (iEnd - iStart < 3) continue;
    let pm = samples[Math.floor((iStart + iEnd) * 0.5)];
    let A = Math.abs(pm.nx * LIGHT_3D[0] + pm.ny * LIGHT_3D[1]);

    let enamelPts = extractOffsetSubcurve(samples, iStart, iEnd, specHaloFn, 8);
    brush.set("enamel_pen", "#d8faf0", 0.95 + 0.45 * A);
    brush.spline(enamelPts, 0.45);

    if (A > 0.32) {
      brush.set("enamel_pen", "#ffffff", 0.75 + 0.45 * A);
      brush.spline(enamelPts, 0.45);
    }

    // Secondary razor-thin parallel enamel reflection line
    let secFn = (t, nx, ny) => specHaloFn(t, nx, ny) * 0.72;
    let secPts = extractOffsetSubcurve(samples, iStart + 1, iEnd - 1, secFn, 7);
    brush.set("rotring", "#bef5e4", 0.48);
    brush.spline(secPts, 0.45);
  }

  // --- STEP F: Fine Pen Line Holding Every Curve + Dark Hairline Shadow Under Each Coil ---
  // Trace both boundaries (s = -1 and s = +1).
  // Wherever the outward boundary normal points downward/away from the sky light,
  // reinforce it with the signature DARK HAIRLINE SHADOW sitting under the coil!
  const contourChunks = 8;
  for (let side of [-1, 1]) {
    for (let c = 0; c < contourChunks; c++) {
      let iStart = Math.max(0, Math.floor(((c - 0.08) / contourChunks) * N));
      let iEnd = Math.min(N, Math.ceil(((c + 1.08) / contourChunks) * N));
      let pm = samples[Math.floor((iStart + iEnd) * 0.5)];

      // Outward normal at this boundary
      let outNx = side * pm.nx;
      let outNy = side * pm.ny;
      // Downward-right orientation score: positive means this edge is the UNDERSIDE of the coil!
      let underScore = outNy * 0.86 + outNx * 0.5;

      // Primary fine technical pen contour holding every curve
      let edgePts = extractOffsetSubcurve(
        samples,
        iStart,
        iEnd,
        side * 0.98,
        8
      );
      brush.set(
        "tech_pen",
        underScore > 0 ? "#04100b" : "#0b261c",
        underScore > 0 ? 1.05 : 0.78
      );
      brush.spline(edgePts, 0.45);

      // Dark hairline shadow sitting immediately under the coil when underScore > -0.05
      if (underScore > -0.05) {
        let shadowW = map(underScore, -0.05, 1.0, 0.55, 1.45, true);
        let hairlinePts = extractOffsetSubcurve(
          samples,
          iStart,
          iEnd,
          side * 1.08,
          8
        );
        // Subtle dark marker bleed right along the hairline shadow
        brush.set("blend_marker", "#1c2e28", shadowW * 0.65);
        brush.spline(hairlinePts, 0.45);

        // Razor-sharp ink hairline shadow sitting under the coil
        brush.set("tech_pen", "#020806", shadowW);
        brush.spline(hairlinePts, 0.45);
      }
    }
  }
}

// ============================================================================
// 8. SOLID BRASS SWIVEL COUPLING & ADJUSTABLE NOZZLE (WORM'S-EYE VIEW)
// ============================================================================

function drawBrassNozzleAssembly(x0, y0, angleDeg) {
  let ux = cos(angleDeg);
  let uy = sin(angleDeg);
  // Left/upper-left normal (faces sky light) vs right/lower-right normal (faces shadow)
  let nx = sin(angleDeg);  // +0.88 (right/shadow side)
  let ny = -cos(angleDeg); // +0.47 (down/shadow side)

  // Helper to convert (axial distance L, radial offset r, ellipse depth z) to canvas [x, y]
  // Worm's-eye aspect ratio for circular cross-sections: 0.34 (we see up into the rings!)
  const tilt = 0.34;
  function pt(L, r, z = 0) {
    return [
      x0 + L * ux + r * nx - z * tilt * ux,
      y0 + L * uy + r * ny - z * tilt * uy
    ];
  }

  function drawBrassCylinderTier(L1, L2, R1, R2, isKnurled = false) {
    // 1. Opaque base wash
    let poly = [];
    for (let a = 0; a <= 180; a += 30) {
      let c = cos(a);
      let s = sin(a);
      poly.push(pt(L1, R1 * c, -R1 * s));
    }
    for (let a = 180; a >= 0; a -= 30) {
      let c = cos(a);
      let s = sin(a);
      poly.push(pt(L2, R2 * c, R2 * s));
    }
    brush.set("tech_pen", "#1f1b0d", 0.6);
    brush.noStroke();
    brush.wash("#6e6539", 252);
    drawPolyShape(poly, 0.1);
    brush.noWash();

    // 2. Longitudinal metallic marker bands across the brass cylinder
    const brassBands = [
      { s: -0.92, col: "#576e5e", w: 0.9 }, // Cool verdigris/sky edge reflection
      { s: -0.76, col: "#b8ad6c", w: 1.0 },
      { s: -0.56, col: "#e3da98", w: 1.1 }, // Bright brass highlight zone
      { s: -0.36, col: "#f7f3c8", w: 1.1 }, // Specular core
      { s: -0.16, col: "#c9be76", w: 1.0 },
      { s: 0.06, col: "#998e50", w: 1.0 },
      { s: 0.28, col: "#665e32", w: 1.0 },
      { s: 0.50, col: "#3d371b", w: 1.1 }, // Deep antique bronze core shadow
      { s: 0.72, col: "#262210", w: 1.0 }, // Darkest umber-brass shadow
      { s: 0.90, col: "#4f5c4a", w: 0.9 }  // Underside cool bounce rim
    ];

    for (let band of brassBands) {
      let p1 = pt(L1, band.s * R1, Math.sqrt(1 - band.s * band.s) * R1 * 0.4);
      let p2 = pt(L2, band.s * R2, Math.sqrt(1 - band.s * band.s) * R2 * 0.4);
      brush.set("blend_marker", band.col, band.w);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // 3. Optional diamond knurling with verdigris patina in recesses
    if (isKnurled) {
      let steps = 11;
      for (let k = -steps; k <= steps; k++) {
        let sA = clampVal(k / steps, -0.95, 0.95);
        let sB = clampVal((k + 4) / steps, -0.95, 0.95);
        let sC = clampVal((k - 4) / steps, -0.95, 0.95);
        let pA1 = pt(L1, sA * R1, 4);
        let pB2 = pt(L2, sB * R2, 4);
        let pC2 = pt(L2, sC * R2, 4);
        brush.set("rotring", sA < 0 ? "#49695a" : "#1f1b0c", 0.38);
        brush.line(pA1[0], pA1[1], pB2[0], pB2[1]);
        brush.line(pA1[0], pA1[1], pC2[0], pC2[1]);
      }
    }

    // 4. Hard enamel metallic highlight along s = -0.42
    let h1 = pt(L1 + 2, -0.42 * R1, R1 * 0.35);
    let h2 = pt(L2 - 2, -0.42 * R2, R2 * 0.35);
    brush.set("enamel_pen", "#ffffff", 1.25);
    brush.line(h1[0], h1[1], h2[0], h2[1]);

    // 5. Elliptical worm's-eye lower rim (visible underside ring lip)
    let rimPts = [];
    for (let a = -90; a <= 90; a += 22.5) {
      let s = sin(a);
      let c = cos(a);
      rimPts.push(pt(L2, s * R2, c * R2));
    }
    brush.set("tech_pen", "#141208", 0.95);
    brush.spline(rimPts, 0.45);

    let rimHighlight = [];
    for (let a = -75; a <= 15; a += 22.5) {
      let s = sin(a);
      let c = cos(a);
      rimHighlight.push(pt(L2 - 1.5, s * R2 * 0.96, c * R2 * 0.96));
    }
    brush.set("enamel_pen", "#fcf8d4", 0.7);
    brush.spline(rimHighlight, 0.45);

    // 6. Outer silhouette pen lines + dark hairline shadow on lower-right edge
    let left1 = pt(L1, -R1, 0);
    let left2 = pt(L2, -R2, 0);
    let right1 = pt(L1, R1, 0);
    let right2 = pt(L2, R2, 0);
    brush.set("tech_pen", "#1c180b", 0.85);
    brush.line(left1[0], left1[1], left2[0], left2[1]);
    brush.set("tech_pen", "#090804", 1.3);
    brush.line(right1[0], right1[1], right2[0], right2[1]);
  }

  // Tier 1: Crimped Brass Ferrule Collar gripping the rubber hose (L = 0..26, R = 27.5)
  drawBrassCylinderTier(0, 26, 28, 27.5, false);
  // Crimp grooves
  for (let Lc of [8, 17]) {
    let gPts = [];
    for (let a = -85; a <= 85; a += 28) {
      gPts.push(pt(Lc, sin(a) * 28, cos(a) * 28));
    }
    brush.set("tech_pen", "#24200e", 0.75);
    brush.spline(gPts, 0.45);
  }

  // Tier 2: Heavy Hexagonal Swivel Nut (L = 26..54, R = 32)
  drawBrassCylinderTier(26, 54, 32, 32, false);
  // Hexagonal flat ridges
  for (let sHex of [-0.42, 0.32]) {
    let p1 = pt(26, sHex * 32, 22);
    let p2 = pt(54, sHex * 32, 22);
    brush.set("tech_pen", "#1f1b0c", 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("enamel_pen", "#fcf9d8", 0.75);
    brush.line(p1[0] - 1.5, p1[1] - 1, p2[0] - 1.5, p2[1] - 1);
  }

  // Tier 3: Recessed Neck Ring (L = 54..66, R = 23)
  drawBrassCylinderTier(54, 66, 23, 23, false);

  // Tier 4: Diamond-Knurled Adjustment Sleeve (L = 66..102, R = 26.5)
  drawBrassCylinderTier(66, 102, 26.5, 26, true);

  // Tier 5: Tapered Bell Barrel (L = 102..148, R = 24.5 -> 14.5)
  drawBrassCylinderTier(102, 148, 24.5, 14.5, false);

  // Tier 6: Flared Nozzle Tip Collar (L = 148..164, R = 17)
  drawBrassCylinderTier(148, 164, 17, 17, false);

  // Worm's-Eye Nozzle Aperture Bore (looking up into the dark circular opening at L = 164!)
  let borePoly = [];
  for (let a = 0; a < 360; a += 30) {
    borePoly.push(pt(164, sin(a) * 12.5, cos(a) * 12.5));
  }
  brush.set("tech_pen", "#050d0b", 0.9);
  brush.wash("#0b1a16", 252);
  drawPolyShape(borePoly, 0.25);
  brush.noWash();

  // Inner brass valve stem tip gleaming inside the dark aperture
  let stemTip = pt(161, -2, 0);
  brush.set("enamel_pen", "#e8df9b", 1.1);
  brush.circle(stemTip[0], stemTip[1], 3.2, 0.1);

  // Bulging clear water meniscus dome emerging from the nozzle bore
  let meniscusPts = [
    pt(164, -10, 2),
    pt(171, -6, 6),
    pt(174, 0, 8),
    pt(171, 6, 6),
    pt(164, 10, 2)
  ];
  brush.set("blend_marker", "#5ca89d", 1.15);
  brush.spline(meniscusPts, 0.5);
  brush.set("enamel_pen", "#ffffff", 1.1);
  brush.spline(meniscusPts.slice(0, 3), 0.5);
}

function clampVal(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

