    { x: 342, y: 1020, r: 3.2, angle: 5 },
    // Below Coil 4 & 5 (right)
    { x: 738, y: 1034, r: 5.2, angle: 10 },
    { x: 748, y: 1066, r: 3.6, angle: -8 },
    { x: 838, y: 1104, r: 5.4, angle: 12 },
