}

function drawSingleWaterTendril(ctrlPts) {
  let samples = sampleTubeCurve(ctrlPts, 36);
  let N = samples.length - 1;

  // 1. Subtle cool refractive cast shadow on the limestone wall behind the water tendril
  let shadowPts = extractOffsetSubcurve(samples, 0, N, 0, 8).map((p) => [
    p[0] + 9,
    p[1] + 12
  ]);
  brush.set("blend_marker", "#8fa69f", 0.75);
  brush.spline(shadowPts, 0.45);

  // 2. Dark bottle-green/teal refractive core along the left/shadow side of the glassy stream
  let darkCore = extractOffsetSubcurve(samples, 0, N, -0.45, 9);
  brush.set("blend_marker", "#1d4f45", 0.85);
  brush.spline(darkCore, 0.45);

  // 3. Luminous aqua-verdigris internal caustic glow along the right/interior side
  let causticBand = extractOffsetSubcurve(samples, 0, N, 0.35, 9);
  brush.set("blend_marker", "#8cd9ce", 0.9);
  brush.spline(causticBand, 0.45);

  // 4. Fine technical pen contour holding the liquid Art Nouveau whiplash edges
  let leftEdge = extractOffsetSubcurve(samples, 0, N, -0.95, 9);
  let rightEdge = extractOffsetSubcurve(samples, 0, N, 0.95, 9);
  brush.set("rotring", "#123830", 0.55);
  brush.spline(leftEdge, 0.45);
  brush.set("rotring", "#19473e", 0.65);
  brush.spline(rightEdge, 0.45);

  // 5. Crisp pure-white enamel specular highlight ribbon along the stream
  let specRibbon = extractOffsetSubcurve(samples, 0, N, -0.2, 9);
  brush.set("enamel_pen", "#ffffff", 0.95);
  brush.spline(specRibbon, 0.45);
}

function drawWaterDroplet(cx, cy, r, angleDeg) {
  let ux = sin(angleDeg);
  let uy = -cos(angleDeg);
  let nx = cos(angleDeg);
  let ny = sin(angleDeg);

  // Wall shadow of droplet
  brush.set("blend_marker", "#839992", 0.7);
  brush.circle(cx + 8, cy + 10, r * 0.85, 0.15);

  // Teardrop silhouette polygon
  let dropPoly = [
    [cx + ux * r * 1.65, cy + uy * r * 1.65], // pinched upper tail
    [cx + nx * r * 0.85 + ux * r * 0.3, cy + ny * r * 0.85 + uy * r * 0.3],
    [cx + nx * r, cy + ny * r],
    [cx - ux * r * 1.05, cy - uy * r * 1.05], // rounded bottom belly
    [cx - nx * r, cy - ny * r],
    [cx - nx * r * 0.85 + ux * r * 0.3, cy - ny * r * 0.85 + uy * r * 0.3]
  ];

  // Glassy aqua base wash
  brush.set("rotring", "#123830", 0.6);
  brush.wash("#a8e3da", 220);
  drawPolyShape(dropPoly, 0.35);
  brush.noWash();

  // Dark upper-left refractive crescent inside droplet
  brush.set("blend_marker", "#16453b", 0.75);
  brush.arc(cx - 0.15 * r, cy - 0.15 * r, r * 0.72, 135, 285);

  // Luminous lower-right internal caustic crescent
  brush.set("enamel_pen", "#e6faf7", 0.8);
  brush.arc(cx + 0.15 * r, cy + 0.15 * r, r * 0.68, -45, 95);

  // Crisp outer pen contour
  brush.set("rotring", "#0e2e27", 0.62);
  drawPolyShape(dropPoly, 0.35);

  // Bright white enamel pinpoint catchlight
  brush.set("enamel_pen", "#ffffff", 1.15);
  brush.line(
    cx - r * 0.38,
    cy - r * 0.38,
    cx - r * 0.18,
    cy - r * 0.12
  );
}

