// ============================================================================
// 1. MATHEMATICAL LORENZ ATTRACTOR + CONTINUOUS RIBBON GEOMETRY
// ============================================================================
function buildLorenzPeelRibbon() {
  const sigma = 10.0;
  const rho = 28.0;
  const beta = 8.0 / 3.0;

  function lorenzDeriv(x, y, z) {
    return [
      sigma * (y - x),
      x * (rho - z) - y,
      x * y - beta * z
    ];
  }

  function rk4Step(p, dt) {
    const [x, y, z] = p;
    const k1 = lorenzDeriv(x, y, z);
    const k2 = lorenzDeriv(x + 0.5 * dt * k1[0], y + 0.5 * dt * k1[1], z + 0.5 * dt * k1[2]);
    const k3 = lorenzDeriv(x + 0.5 * dt * k2[0], y + 0.5 * dt * k2[1], z + 0.5 * dt * k2[2]);
    const k4 = lorenzDeriv(x + dt * k3[0], y + dt * k3[1], z + dt * k3[2]);
    return [
      x + (dt / 6) * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]),
      y + (dt / 6) * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]),
      z + (dt / 6) * (k1[2] + 2 * k2[2] + 2 * k3[2] + k4[2])
    ];
  }

  // Search for an initial state that produces balanced left/right lobes,
  // multiple saddle crossings, and finishes on the lower-left lobe above the apple
  let bestRaw = null;
  let bestScore = -1e9;
  const steps = 760;
  const dt = 0.0062;

  for (let trial = 0; trial < 45; trial++) {
    let p = [0.25, 0.9 + trial * 0.09, 20.2 + (trial % 5) * 0.4];
    // Warmup
    for (let w = 0; w < 80; w++) p = rk4Step(p, dt);

    let pts = [];
    let leftCount = 0;
    let rightCount = 0;
    let crossings = 0;
    let prevSign = Math.sign(p[0]);

    for (let i = 0; i < steps; i++) {
      p = rk4Step(p, dt);
      pts.push(p);
      if (p[0] < -2) leftCount++;
      if (p[0] > 2) rightCount++;
      let s = Math.sign(p[0]);
      if (s !== 0 && s !== prevSign) {
        crossings++;
        prevSign = s;
      }
    }

    const balance = 1.0 - Math.abs(leftCount - rightCount) / steps;
    const endP = pts[pts.length - 1];
    const endPrev = pts[pts.length - 2];
    const endU = 0.76 * endP[0] + 0.65 * endP[1];
    const endZ = endP[2];
    const du = (0.76 * endP[0] + 0.65 * endP[1]) - (0.76 * endPrev[0] + 0.65 * endPrev[1]);
    const dz = endP[2] - endPrev[2];

    // Prefer balanced two-lobe trajectories that end moving downward on the left side
    let score = balance * 120 + Math.min(crossings, 6) * 25;
    if (leftCount > 180 && rightCount > 180) score += 100;
    if (endU < -2 && endU > -16 && endZ < 26) score += 70;
    if (dz < 0) score += 45;
    if (du > -0.5) score += 20;

    if (score > bestScore) {
      bestScore = score;
      bestRaw = pts;
    }
  }

  // Project 3D Lorenz coordinates into canvas 3D space (X, Y on canvas, Z depth)
  const scaleX = 16.8;
  const scaleY = 14.5;
  const scaleZ = 15.0;
  const centerX = 605;
  const centerY = 395;

  let lorenzScreen = [];
  for (let i = 0; i < bestRaw.length; i++) {
    const [lx, ly, lz] = bestRaw[i];
    // Rotate slightly in XY so both butterfly lobes open wide and show 3D depth
    const u = 0.77 * lx + 0.64 * ly;
    const v = 0.64 * lx - 0.77 * ly;
    const w = lz - 26.2;

    const sx = centerX + u * scaleX;
    const sy = centerY - w * scaleY + v * 1.9;
    const sz = v * scaleZ;
    lorenzScreen.push({ x: sx, y: sy, z: sz, isTail: 0 });
  }

  // Create a smooth unbroken descending catenary/helical tail from the end of the
  // Lorenz trajectory right down to the uncut skin collar on the naked apple
  const pEnd = lorenzScreen[lorenzScreen.length - 1];
  const pPrev = lorenzScreen[lorenzScreen.length - 4];
  let tx = pEnd.x - pPrev.x;
  let ty = pEnd.y - pPrev.y;
  let tz = pEnd.z - pPrev.z;
  const tLen = Math.hypot(tx, ty, tz) || 1;
  tx /= tLen; ty /= tLen; tz /= tLen;

  // Target attachment point on the upper-right shoulder of the naked apple
  const appleAttach = { x: 472, y: 744, z: 58 };
  const c1 = {
    x: pEnd.x + tx * 115,
    y: Math.max(pEnd.y + ty * 115, pEnd.y + 55),
    z: pEnd.z + tz * 90 + 30
  };
  const c2 = {
    x: appleAttach.x + 88,
    y: appleAttach.y - 95,
    z: appleAttach.z + 55
  };

  const tailSteps = 135;
  for (let i = 1; i <= tailSteps; i++) {
    const t = i / tailSteps;
    const mt = 1 - t;
    // Cubic Bezier + gentle helical curl as it approaches the apple
    const spiralAngle = t * 340;
    const spiralAmp = Math.sin(t * Math.PI) * 26;
    const bx = mt * mt * mt * pEnd.x + 3 * mt * mt * t * c1.x + 3 * mt * t * t * c2.x + t * t * t * appleAttach.x
      + Math.cos(spiralAngle * Math.PI / 180) * spiralAmp;
    const by = mt * mt * mt * pEnd.y + 3 * mt * mt * t * c1.y + 3 * mt * t * t * c2.y + t * t * t * appleAttach.y
      + Math.sin(spiralAngle * Math.PI / 180) * spiralAmp * 0.35;
    const bz = mt * mt * mt * pEnd.z + 3 * mt * mt * t * c1.z + 3 * mt * t * t * c2.z + t * t * t * appleAttach.z
      + Math.sin(spiralAngle * Math.PI / 180) * spiralAmp;

    lorenzScreen.push({ x: bx, y: by, z: bz, isTail: t });
  }

  // Resample the entire 3D path at uniform 2D/3D arc-length spacing (ds = 5.6 px)
  let uniformPts = [lorenzScreen[0]];
  let accum = 0;
  const targetDs = 5.6;

  for (let i = 1; i < lorenzScreen.length; i++) {
    const a = lorenzScreen[i - 1];
    const b = lorenzScreen[i];
    const segLen = Math.hypot(b.x - a.x, b.y - a.y, (b.z - a.z) * 0.45);
    if (segLen < 0.001) continue;
    let rem = segLen;
    let curr = { ...a };
    while (accum + rem >= targetDs) {
      const need = targetDs - accum;
      const f = need / rem;
      curr = {
        x: curr.x + (b.x - curr.x) * f,
        y: curr.y + (b.y - curr.y) * f,
        z: curr.z + (b.z - curr.z) * f,
        isTail: curr.isTail + (b.isTail - curr.isTail) * f
      };
      uniformPts.push(curr);
      rem -= need;
      accum = 0;
    }
    accum += rem;
  }

  // Build parallel-transport 3D ribbon frames with natural peel torsion
  const N = uniformPts.length;
  let stations = [];
  let prevU = { x: 0, y: 0, z: 1 };
  let twistAngle = 25;

  for (let i = 0; i < N; i++) {
    const p0 = uniformPts[Math.max(0, i - 1)];
    const p1 = uniformPts[Math.min(N - 1, i + 1)];
    let tx = p1.x - p0.x;
    let ty = p1.y - p0.y;
    let tz = p1.z - p0.z;
    const tl = Math.hypot(tx, ty, tz) || 1;
    const T = { x: tx / tl, y: ty / tl, z: tz / tl };

    // Project prevU orthogonal to T
    const dot = prevU.x * T.x + prevU.y * T.y + prevU.z * T.z;
    let ux = prevU.x - dot * T.x;
    let uy = prevU.y - dot * T.y;
    let uz = prevU.z - dot * T.z;
    const ul = Math.hypot(ux, uy, uz) || 1;
    const U = { x: ux / ul, y: uy / ul, z: uz / ul };
    prevU = U;

    // V = T x U
    const V = {
      x: T.y * U.z - T.z * U.y,
      y: T.z * U.x - T.x * U.z,
      z: T.x * U.y - T.y * U.x
    };

    // Advance torsional twist so the peel turns over in space, revealing both
    // the crimson/chartreuse skin and the moist white underside
    const sNorm = i / (N - 1);
    const localCurv = Math.sin(i * 0.055) * 1.4 + 2.35;
    twistAngle += localCurv;

    const rad = (twistAngle * Math.PI) / 180;
    const cosA = Math.cos(rad);
    const sinA = Math.sin(rad);

    // B = ribbon width vector, Nvec = outer skin surface normal
    const B = {
      x: cosA * U.x + sinA * V.x,
      y: cosA * U.y + sinA * V.y,
      z: cosA * U.z + sinA * V.z
    };
    const Nvec = {
      x: -sinA * U.x + cosA * V.x,
      y: -sinA * U.y + cosA * V.y,
      z: -sinA * U.z + cosA * V.z
    };

    // Ribbon width with organic hand-peeled undulation, tapering at starter tip and apple collar
    let taper = 1.0;
    if (sNorm < 0.045) taper = map(sNorm, 0, 0.045, 0.22, 1.0);
    if (sNorm > 0.96) taper = map(sNorm, 0.96, 1.0, 1.0, 0.42);

    const depthScale = map(uniformPts[i].z, -240, 240, 0.82, 1.22, true);
    const organicWave = 1.0 + 0.14 * Math.sin(i * 0.11) + 0.08 * (noise(i * 0.07) - 0.5);
    const halfW = 15.5 * taper * depthScale * organicWave;

    // Slight transverse cupping toward the pith side
    const cupOffset = 2.6 * taper;
    const cx = uniformPts[i].x;
    const cy = uniformPts[i].y;
    const cz = uniformPts[i].z;

    const e1 = {
      x: cx - B.x * halfW - Nvec.x * cupOffset,
      y: cy - B.y * halfW - Nvec.y * cupOffset,
      z: cz - B.z * halfW - Nvec.z * cupOffset
    };
    const e2 = {
      x: cx + B.x * halfW - Nvec.x * cupOffset,
      y: cy + B.y * halfW - Nvec.y * cupOffset,
      z: cz + B.z * halfW - Nvec.z * cupOffset
    };

    stations.push({
      idx: i,
      sNorm,
      x: cx,
      y: cy,
      z: cz,
      T,
      B,
      N: Nvec,
      halfW,
      e1,
      e2,
      shadowFactor: 0
    });
  }

  // Compute self-shadowing where a nearer ribbon loop passes closely over a deeper loop
  const lightDir = { x: -0.42, y: -0.56, z: 0.71 };
  for (let i = 0; i < N; i++) {
    const stA = stations[i];
    let maxOcc = 0;
    for (let j = 0; j < N; j += 2) {
      if (Math.abs(i - j) < 18) continue;
      const stB = stations[j];
      const dz = stB.z - stA.z;
      if (dz > 6 && dz < 180) {
        // Project stB along light ray onto stA's depth plane
        const shiftX = stB.x - (lightDir.x / lightDir.z) * dz * 0.35;
        const shiftY = stB.y - (lightDir.y / lightDir.z) * dz * 0.35;
        const d2 = Math.hypot(stA.x - shiftX, stA.y - shiftY);
        const thresh = stB.halfW + stA.halfW * 0.75;
        if (d2 < thresh) {
          const occ = map(d2, 0, thresh, 0.68, 0, true);
          if (occ > maxOcc) maxOcc = occ;
        }
      }
    }
    stA.shadowFactor = maxOcc;
  }

  return { stations, rawPoints: bestRaw };
}

// ============================================================================
// 2. DARK SLATE ENVIRONMENT & SUBTLE MATHEMATICAL PHASE-SPACE WHISPERS
// ============================================================================
function drawDarkSlateSurround(ribbonData) {
  // Deep slate washes around the periphery
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.35);

  // Outer dark slate vignette slabs
  brush.fill(PAL.slateDeep, 165);
  brush.rect(0, 0, 1200, 180, "corner");
  brush.rect(0, 0, 170, 1200, "corner");
  brush.rect(1030, 0, 170, 1200, "corner");

  // Warm ambient glow behind the attractor and cutting board
  brush.fill(PAL.slateWarm, 95);
  brush.circle(600, 460, 420, 0.25);
  brush.fill("#261b14", 85);
  brush.circle(560, 820, 380, 0.25);
  brush.noFill();

  // Fine slate stone diagonal grain & charcoal atmosphere
  brush.hatchStyle("2B", "#1a1f26", 0.42);
  brush.hatch(14, 28, { rand: 0.18 });
  brush.noStroke();
  brush.rect(40, 40, 1120, 770, "corner");
  brush.noHatch();

  // Subtle spray grain in dark slate
  for (let i = 0; i < 65; i++) {
    const sx = random(60, 1140);
    const sy = random(50, 780);
    brush.set("spray", i % 2 === 0 ? "#090b0e" : "#232830", random(0.4, 0.9));
    brush.line(sx, sy, sx + random(-90, 90), sy + random(-40, 40));
  }

  // Whisper-faint mathematical construction traces on the dark slate
  // (faint phase-space lobe centers, tangent arcs, and coordinate ticks)
  const leftLobeX = 415;
  const leftLobeY = 390;
  const rightLobeX = 795;
  const rightLobeY = 385;

  brush.set("2H", "#2c323b", 0.22);
  // Faint crosshair ticks at the two strange attractor equilibria C- and C+
  brush.line(leftLobeX - 18, leftLobeY, leftLobeX + 18, leftLobeY);
  brush.line(leftLobeX, leftLobeY - 18, leftLobeX, leftLobeY + 18);
  brush.line(rightLobeX - 18, rightLobeY, rightLobeX + 18, rightLobeY);
  brush.line(rightLobeX, rightLobeY - 18, rightLobeX, rightLobeY + 18);

  // Ghostly orbital envelope arcs around the two lobes
  brush.set("2H", "#262b33", 0.2);
  brush.arc(leftLobeX, leftLobeY, 175, 195, 340);
  brush.arc(leftLobeX, leftLobeY, 215, 20, 145);
  brush.arc(rightLobeX, rightLobeY, 180, 210, 355);
  brush.arc(rightLobeX, rightLobeY, 220, 35, 165);

  // Ghost trajectory echo (offset slightly in phase space as a pencil construction line)
  const st = ribbonData.stations;
  brush.set("2H", "#2a2729", 0.18);
  for (let i = 10; i < st.length - 140; i += 8) {
    const a = st[i];
    const b = st[i + 5];
    if (a && b && (i % 24 < 16)) {
      brush.line(a.x + 6, a.y - 4, b.x + 6, b.y - 4);
    }
  }
}

// ============================================================================
// 3. SCARRED WOODEN CUTTING BOARD
// ============================================================================
function drawScarredCuttingBoard(ribbonData) {
  // Perspective coordinates of the heavy butcher-block cutting board
  const tl = { x: 105, y: 800 };
  const tr = { x: 1070, y: 782 };
  const br = { x: 1140, y: 1068 };
  const bl = { x: 35, y: 1090 };
  const blBot = { x: 42, y: 1158 };
  const brBot = { x: 1132, y: 1134 };

  // Helper to bilinearly interpolate on top surface (u in [0,1], v in [0,1])
  function boardPt(u, v) {
    const topX = lerp(tl.x, tr.x, u);
    const topY = lerp(tl.y, tr.y, u);
    const botX = lerp(bl.x, br.x, u);
    const botY = lerp(bl.y, br.y, u);
    return {
      x: lerp(topX, botX, v),
      y: lerp(topY, botY, v)
    };
  }

  // Deep shadow under the cutting board slab on the dark slate surface
  brush.noStroke();
  brush.wash("#050608", 235);
  brush.beginShape(0);
  brush.vertex(blBot.x - 10, blBot.y - 8);
  brush.vertex(brBot.x + 12, brBot.y - 8);
  brush.vertex(brBot.x + 25, brBot.y + 28);
  brush.vertex(blBot.x - 20, blBot.y + 28);
  brush.endShape(true);
  brush.noWash();

  // Solid base wash for the cutting board top surface
  brush.noStroke();
  brush.wash(PAL.woodMid, 245);
  brush.beginShape(0);
  brush.vertex(tl.x, tl.y);
  brush.vertex(tr.x, tr.y);
  brush.vertex(br.x, br.y);
  brush.vertex(bl.x, bl.y);
  brush.endShape(true);

  // Solid dark base wash for the front end-grain thickness slab
  brush.wash(PAL.woodDark, 250);
  brush.beginShape(0);
  brush.vertex(bl.x, bl.y);
  brush.vertex(br.x, br.y);
  brush.vertex(brBot.x, brBot.y);
  brush.vertex(blBot.x, blBot.y);
  brush.endShape(true);
  brush.noWash();

  // Watercolor tonal modulation across the board (burnished lighter chopping zone in center)
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.7, 0.4);
  brush.fill(PAL.woodOchre, 145);
  brush.circle(540, 925, 290, 0.3);
  brush.fill(PAL.woodLight, 110);
  brush.circle(490, 910, 195, 0.35);
  brush.fill(PAL.woodShadow, 150);
  brush.circle(160, 950, 150, 0.25);
  brush.circle(1010, 920, 160, 0.25);
  brush.noFill();

  // Laminated hardwood plank strips & continuous wood grain splines
  const plankDivs = [0.0, 0.23, 0.48, 0.74, 1.0];
  for (let p = 0; p < plankDivs.length - 1; p++) {
    const v0 = plankDivs[p];
    const v1 = plankDivs[p + 1];

    // Plank seam line
    if (p > 0) {
      const sL = boardPt(0, v0);
      const sR = boardPt(1, v0);
      brush.set("rotring", PAL.woodDark, 0.45);
      brush.line(sL.x, sL.y, sR.x, sR.y);
      brush.set("2H", PAL.woodLight, 0.3);
      brush.line(sL.x, sL.y + 1.5, sR.x, sR.y + 1.5);
    }

    // Wood grain flow lines along each plank strip
    const knotU = 0.25 + ((p * 0.37) % 0.55);
    const knotV = lerp(v0, v1, 0.52);

    const grainLines = 42;
    for (let g = 0; g < grainLines; g++) {
      const vg = lerp(v0 + 0.01, v1 - 0.01, g / (grainLines - 1));
      let pts = [];
      const segs = 22;
      for (let s = 0; s <= segs; s++) {
        const u = s / segs;
        // Deflect around knot & add natural grain wave
        const du = u - knotU;
        const dv = vg - knotV;
        const distK = Math.hypot(du * 2.2, dv * 8.0);
        const knotPush = distK < 0.45 ? Math.sin((1 - distK / 0.45) * Math.PI) * 0.022 * Math.sign(dv || 1) : 0;
        const wave = (noise(u * 3.5 + p * 7, g * 0.25) - 0.5) * 0.018;
        const vFinal = constrain(vg + knotPush + wave, v0 + 0.004, v1 - 0.004);
        const pt = boardPt(u, vFinal);
        pts.push([pt.x, pt.y, random(0.6, 1.15)]);
      }

      const colChoice = (g + p) % 4 === 0 ? PAL.woodDark
        : (g + p) % 3 === 0 ? PAL.woodShadow
        : (g % 2 === 0 ? PAL.woodWarm : PAL.woodLight);
      brush.set("fine_cpencil", colChoice, random(0.45, 0.85));
      brush.spline(pts, 0.4);
    }
  }

  // Front edge bevel highlight and end-grain annual growth rings
  brush.set("cpencil", PAL.woodHighlight, 0.75);
  brush.line(bl.x, bl.y, br.x, br.y);
  brush.set("rotring", PAL.woodLight, 0.35);
  brush.line(bl.x, bl.y + 1.8, br.x, br.y + 1.8);

  // End-grain blocks along front lip
  for (let p = 0; p < plankDivs.length - 1; p++) {
    const u0 = plankDivs[p];
    const u1 = plankDivs[p + 1];
    const xL = lerp(bl.x, br.x, u0);
    const yL = lerp(bl.y, br.y, u0);
    const xR = lerp(bl.x, br.x, u1);
    const yR = lerp(bl.y, br.y, u1);
    const ringCx = lerp(xL, xR, 0.5);
    const ringCy = lerp(yL, yR, 0.5) + 45;

    for (let r = 12; r < 140; r += 7) {
      brush.set("2B", r % 14 === 0 ? PAL.woodDark : PAL.woodWarm, 0.42);
      for (let x = xL + 4; x < xR - 4; x += 8) {
        const dx = x - ringCx;
        const archY = yL + 10 + Math.sin(((x - xL) / (xR - xL)) * Math.PI) * 32 + (r % 28) * 0.8;
        if (archY > yL + 3 && archY < yL + 62) {
          brush.line(x, archY, x + 6, archY + (dx > 0 ? 2.5 : -2.5));
        }
      }
    }
  }

  // Soft cast shadow on the board from the hovering Lorenz peel above
  const st = ribbonData.stations;
  for (let i = 0; i < st.length - 90; i += 6) {
    const s = st[i];
    const shadowX = 620 + (s.x - 600) * 0.55 + (850 - s.y) * 0.18;
    const shadowY = 855 + (s.z + 200) * 0.14;
    if (shadowX > 180 && shadowX < 1030 && shadowY > 805 && shadowY < 1030) {
      brush.set("fine_cpencil", PAL.woodDark, 1.1);
      brush.line(shadowX - 12, shadowY, shadowX + 12, shadowY + 2);
    }
  }

  // Deep cast shadow of the naked apple on the board (stretching right)
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill(PAL.woodDark, 190);
  brush.beginShape(0.5);
  brush.vertex(340, 938);
  brush.vertex(470, 922);
  brush.vertex(625, 938);
  brush.vertex(615, 972);
  brush.vertex(445, 982);
  brush.vertex(335, 962);
  brush.endShape(true);

  // Warm honey subsurface caustic inside the apple's shadow
  brush.fill("#8c5219", 130);
  brush.circle(485, 952, 48, 0.25);
  brush.noFill();

  // Hundreds of crisp, tactile knife scars & nicks across the chopping board
  // Paired dark incision + bright splintered lip gives photorealistic 3D relief
  for (let i = 0; i < 290; i++) {
    // Concentrate scars in the central working area
    const u = constrain(randomGaussian(0.5, 0.21), 0.05, 0.94);
    const v = constrain(randomGaussian(0.52, 0.22), 0.06, 0.93);
    const pt = boardPt(u, v);

    const scarLen = random(14, 78);
    const ang = (random() < 0.78 ? random(-22, 28) : random(-65, 75)) * (Math.PI / 180);
    const dx = Math.cos(ang) * scarLen * 0.5;
    const dy = Math.sin(ang) * scarLen * 0.28;

    const x1 = pt.x - dx;
    const y1 = pt.y - dy;
    const x2 = pt.x + dx;
    const y2 = pt.y + dy;

    // Dark incision groove
    brush.set("rotring", PAL.woodDark, random(0.28, 0.52));
    brush.line(x1, y1, x2, y2);

    // Lit splintered lower ridge catching the top-left key light
    const highlightCol = i % 3 === 0 ? PAL.woodHighlight : PAL.woodLight;
    brush.set("2H", highlightCol, random(0.22, 0.42));
    brush.line(x1 + 0.4, y1 + 1.3, x2 + 0.4, y2 + 1.3);
  }
}

// ============================================================================
// 4. THE NAKED HAND-PEELED APPLE (HELICAL LATHE FACETS & MOIST FLESH)
// ============================================================================
function drawNakedApple() {
  const cx = 415;
  const cy = 838;
  const rx = 114;
  const ry = 104;

  // Apple contour generator with realistic crown lobes and tapered bottom calyx
  function appleProfile(angleDeg, scaleR = 1.0) {
    const a = (angleDeg * Math.PI) / 180;
    const sinA = Math.sin(a);
    const cosA = Math.cos(a);

    // Slight top dip at -90 deg (stem cavity) and bottom taper at +90 deg
    let rMod = 1.0;
    // Crown shoulders around -55 and -125 deg
    rMod += 0.06 * Math.cos(2 * a);
    // Slight narrowing toward bottom
    if (sinA > 0) rMod -= 0.08 * sinA * Math.abs(cosA);
    // Stem indentation at very top
    if (sinA < -0.82) {
      const t = map(sinA, -0.82, -1.0, 0, 1);
      rMod -= 0.14 * t * t;
    }

    return {
      x: cx + cosA * rx * rMod * scaleR,
      y: cy + sinA * ry * rMod * scaleR
    };
  }

  // 1. Solid opaque base wash for the peeled apple flesh
  brush.noStroke();
  brush.wash(PAL.appleCream, 250);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 8) {
    const p = appleProfile(a, 1.0);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Watercolor shading layers for 3D volume, oxidation blush, and reflected wood light
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.55, 0.25);

  // Shadow hemisphere (right & lower-right)
  brush.fill(PAL.appleOchre, 145);
  brush.circle(cx + 34, cy + 18, 78, 0.25);
  brush.fill(PAL.appleShadow, 155);
  brush.circle(cx + 50, cy + 28, 56, 0.25);

  // Bright illuminated upper-left flesh
  brush.fill(PAL.appleLit, 170);
  brush.circle(cx - 32, cy - 22, 66, 0.2);
  brush.fill(PAL.appleGreenHint, 110);
  brush.circle(cx - 42, cy - 34, 42, 0.2);
  brush.noFill();

  // 3. Helical Lathe-Like Peeled Facet Tiers
  // A hand-peeled apple has 8 horizontal/helical flat-ish bands where the knife passed
  const numTiers = 8;
  const topY = cy - ry * 0.88;
  const botY = cy + ry * 0.95;

  for (let tier = 0; tier < numTiers; tier++) {
    const f0 = tier / numTiers;
    const f1 = (tier + 1) / numTiers;
    const yMid = lerp(topY, botY, (f0 + f1) * 0.5);
    const tierNormY = (yMid - cy) / ry;

    // Approximate half-width at this latitude
    const latCos = Math.sqrt(Math.max(0.04, 1 - tierNormY * tierNormY * 0.92));
    const halfSpanX = rx * latCos * (tierNormY > 0 ? 1 - 0.06 * tierNormY : 1.02);

    // Dense coloured-pencil cross-contour shading within each helical facet band
    const strokesInTier = 38;
    for (let s = 0; s < strokesInTier; s++) {
      const u = map(s, 0, strokesInTier - 1, -0.96, 0.96);
      const sx = cx + u * halfSpanX;
      // Helical tilt across the apple face
      const tiltY = u * 9.5 + Math.sqrt(Math.max(0, 1 - u * u)) * 11 * (tierNormY * 0.6 + 0.25);
      const sy0 = lerp(topY, botY, f0) + tiltY;
      const sy1 = lerp(topY, botY, f1) + tiltY;

      // 3D normal & lighting for this facet strip
      const nx = u * 0.88;
      const ny = (tier % 2 === 0 ? tierNormY - 0.06 : tierNormY + 0.05);
      const nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
      const lightDot = nx * -0.48 + ny * -0.52 + nz * 0.71;

      let col = PAL.appleCream;
      if (lightDot > 0.55) col = s % 3 === 0 ? PAL.appleGreenHint : PAL.appleLit;
      else if (lightDot > 0.2) col = PAL.appleCream;
      else if (lightDot > -0.1) col = PAL.appleHoney;
      else if (lightDot > -0.35) col = PAL.appleOchre;
      else col = tierNormY > 0.55 ? PAL.woodWarm : PAL.appleShadow;

      brush.set("fine_cpencil", col, random(0.55, 0.95));
      brush.line(sx, sy0, sx + random(-2.5, 2.5), sy1);
    }

    // Crisp helical ridge line where one pass of the paring knife met the next
    if (tier > 0) {
      let ridgePtsLit = [];
      let ridgePtsShad = [];
      for (let u = -0.94; u <= 0.94; u += 0.08) {
        const rxPt = cx + u * halfSpanX;
        const ryPt = lerp(topY, botY, f0) + u * 9.5 + Math.sqrt(Math.max(0, 1 - u * u)) * 11 * (tierNormY * 0.6 + 0.25);
        if (u < 0.22) ridgePtsLit.push([rxPt, ryPt, 0.9]);
        if (u > -0.15) ridgePtsShad.push([rxPt, ryPt, 0.85]);
      }
      // Subtle amber oxidation line along the facet ridge
      brush.set("2H", PAL.appleOchre, 0.35);
      if (ridgePtsShad.length > 2) brush.spline(ridgePtsShad, 0.35);
      // Glistening wet catchlight along the lit facet ridge
      brush.set("rotring", PAL.pithBright, 0.32);
      if (ridgePtsLit.length > 2) brush.spline(ridgePtsLit, 0.35);
    }
  }

  // 4. Moist cellular sparkles & enzymatic browning flecks on the naked flesh
  for (let i = 0; i < 240; i++) {
    const a = random(0, 360);
    const r = Math.sqrt(random(0.05, 0.92));
    const p = appleProfile(a, r);
    const isLit = (p.x < cx + 15 && p.y < cy + 25);

    if (isLit && i % 2 === 0) {
      brush.set("lenticel_tip", PAL.pithBright, random(0.35, 0.7));
      brush.line(p.x, p.y, p.x + 1.2, p.y + 0.6);
    } else {
      brush.set("fine_cpencil", isLit ? PAL.appleHoney : PAL.appleShadow, random(0.3, 0.55));
      brush.line(p.x - 1.5, p.y, p.x + 1.5, p.y + 1);
    }
  }

  // 5. Stem Cavity, Woody Stem, and Uncut Crimson/Chartreuse Skin Collar
  const cavX = cx - 2;
  const cavY = cy - 86;

  // Deep shadow inside the stem bowl
  brush.set("fine_cpencil", PAL.appleDeep, 0.85);
  for (let x = cavX - 28; x <= cavX + 28; x += 2.5) {
    const depth = Math.cos(((x - cavX) / 30) * (Math.PI / 2)) * 12;
    brush.line(x, cavY - depth * 0.4, x, cavY + depth);
  }

  // Uncut collar of red & chartreuse skin around the stem cavity and right shoulder
  // (where the Lorenz peel ribbon is still attached at (472, 744)!)
  for (let s = 0; s < 48; s++) {
    const t = s / 47;
    const sx = lerp(cavX - 24, 482, t);
    const sy = cavY + Math.sin(t * Math.PI) * 10 - t * 6;
    const collarH = lerp(7, 16, t);
    const skinCol = s % 5 === 0 ? PAL.chartreuse
      : s % 3 === 0 ? PAL.scarlet : PAL.crimsonMid;
    brush.set("peel_base", skinCol, 0.55);
    brush.line(sx, sy, sx + 2, sy + collarH);
    brush.set("fine_cpencil", PAL.crimsonDeep, 0.45);
    brush.line(sx, sy + collarH - 2, sx + 2, sy + collarH + 1);
  }
  // White pith cut edge under the skin collar
  brush.set("rotring", PAL.pithCream, 0.55);
  brush.line(cavX - 24, cavY + 7, 482, 754);

  // Curved woody apple stem rising from the cavity
  const stemPts = [
    [cavX - 1, cavY + 5, 1.2],
    [cavX - 5, cavY - 14, 1.0],
    [cavX - 14, cavY - 32, 0.95],
    [cavX - 25, cavY - 46, 1.3]
  ];
  brush.set("peel_base", PAL.woodDark, 0.7);
  brush.spline(stemPts, 0.45);
  brush.set("fine_cpencil", PAL.woodWarm, 0.55);
  brush.spline(stemPts.map(p => [p[0] - 1.8, p[1], p[2]]), 0.45);
  brush.set("rotring", PAL.woodHighlight, 0.35);
  brush.spline(stemPts.map(p => [p[0] - 2.6, p[1], p[2]]), 0.45);

  // Crisp outer contour of the naked apple in fine continuous pen
  let leftContour = [];
  let rightContour = [];
  for (let a = 110; a <= 265; a += 6) {
    const p = appleProfile(a, 1.0);
    leftContour.push([p.x, p.y, 0.8]);
  }
  for (let a = -65; a <= 115; a += 6) {
    const p = appleProfile(a, 1.0);
    rightContour.push([p.x, p.y, 0.95]);
  }
  brush.set("rotring", PAL.appleOchre, 0.32);
  brush.spline(leftContour, 0.4);
  brush.set("rotring", PAL.woodDark, 0.48);
  brush.spline(rightContour, 0.4);

  // Dark occlusion line where the wet apple base meets the cutting board
  brush.set("rotring", "#120803", 0.65);
  brush.line(cx - 58, cy + 98, cx + 62, cy + 96);
}

// ============================================================================
// 5. THE SHARP PARING KNIFE
// ============================================================================
function drawParingKnife() {
  // Blade tip pointing toward the apple base; handle extending to the right
  const tip = { x: 558, y: 954 };
  const spineHeel = { x: 792, y: 902 };
  const edgeHeel = { x: 798, y: 938 };
  const handleEndTop = { x: 1035, y: 856 };
  const handleEndBot = { x: 1044, y: 896 };

  // Helper for point along the curved cutting edge (t = 0 at tip, 1 at heel)
  function bladeEdgePt(t) {
    const mt = 1 - t;
    const ctrl = { x: 678, y: 960 };
    return {
      x: mt * mt * tip.x + 2 * mt * t * ctrl.x + t * t * edgeHeel.x,
      y: mt * mt * tip.y + 2 * mt * t * ctrl.y + t * t * edgeHeel.y
    };
  }

  function bladeSpinePt(t) {
    return {
      x: lerp(tip.x, spineHeel.x, t),
      y: lerp(tip.y, spineHeel.y, t)
    };
  }

  // 1. Crisp cast shadow beneath the slightly elevated blade & resting handle
  brush.noStroke();
  brush.wash("#140a04", 215);
  brush.beginShape(0);
  brush.vertex(tip.x + 6, tip.y + 9);
  brush.vertex(edgeHeel.x + 6, edgeHeel.y + 11);
  brush.vertex(handleEndBot.x + 8, handleEndBot.y + 12);
  brush.vertex(handleEndTop.x + 8, handleEndTop.y + 22);
  brush.vertex(spineHeel.x + 6, spineHeel.y + 18);
  brush.endShape(true);
  brush.noWash();

  // 2. Steel Blade Solid Base
  brush.noStroke();
  brush.wash(PAL.steelDark, 250);
  brush.beginShape(0);
  brush.vertex(tip.x, tip.y);
  brush.vertex(spineHeel.x, spineHeel.y);
  for (let t = 1.0; t >= 0; t -= 0.1) {
    const ep = bladeEdgePt(t);
    brush.vertex(ep.x, ep.y);
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Metallic reflections across the steel blade (dark slate sky vs warm apple/board reflection)
  const bladeStrips = 85;
  for (let i = 0; i <= bladeStrips; i++) {
    const t = i / bladeStrips;
    const sp = bladeSpinePt(t);
    const ep = bladeEdgePt(t);

    // Upper half reflects dark slate; lower half reflects warm wood & creamy apple
    const midX = lerp(sp.x, ep.x, 0.48);
    const midY = lerp(sp.y, ep.y, 0.48);

    // Specular band modulation along blade length
    const wave = Math.sin(t * 9.5) * 0.5 + 0.5;
    const topCol = wave > 0.65 ? PAL.steelMid : PAL.steelDark;
    const botCol = t < 0.42 ? PAL.appleCream : (wave > 0.4 ? PAL.steelLight : PAL.steelWarm);

    brush.set("fine_cpencil", topCol, 0.65);
    brush.line(sp.x, sp.y, midX, midY);

    brush.set("fine_cpencil", botCol, 0.65);
    brush.line(midX, midY, ep.x, ep.y);

    // Vertical satin steel grind lines
    if (i % 3 === 0) {
      brush.set("rotring", i % 6 === 0 ? PAL.steelLight : PAL.steelDark, 0.22);
      brush.line(sp.x, sp.y, ep.x, ep.y);
    }
  }

  // Spine thickness bevel highlight
  brush.set("rotring", PAL.steelLight, 0.48);
  brush.line(tip.x, tip.y, spineHeel.x, spineHeel.y);
  brush.set("rotring", PAL.slateDeep, 0.35);
  brush.line(tip.x, tip.y + 1.4, spineHeel.x, spineHeel.y + 1.4);

  // Razor-sharp honed cutting edge bevel in pure white continuous pen
  let edgeCurve = [];
  let bevelInner = [];
  for (let t = 0; t <= 1.0; t += 0.05) {
    const ep = bladeEdgePt(t);
    edgeCurve.push([ep.x, ep.y, 0.95]);
    bevelInner.push([ep.x - 0.5, ep.y - 2.4, 0.7]);
  }
  brush.set("rotring", PAL.steelEdge, 0.52);
  brush.spline(edgeCurve, 0.35);
  brush.set("2H", PAL.appleCream, 0.32);
  brush.spline(bevelInner, 0.35);

  // Tiny crimson peel fleck and wet apple pith crumb clinging to the steel blade
  brush.set("peel_base", PAL.crimsonBright, 0.42);
  brush.line(622, 941, 631, 939);
  brush.set("rotring", PAL.pithBright, 0.45);
  brush.line(623, 942, 630, 940.5);

  // 4. Brushed Bolster & Contoured Rosewood/Cocobolo Handle
  brush.noStroke();
  brush.wash(PAL.handleDark, 252);
  brush.beginShape(0);
  brush.vertex(spineHeel.x, spineHeel.y - 2);
  brush.vertex(handleEndTop.x, handleEndTop.y);
  brush.vertex(handleEndBot.x, handleEndBot.y);
  brush.vertex(edgeHeel.x, edgeHeel.y - 2);
  brush.endShape(true);
  brush.noWash();

  // Rosewood grain and cylindrical highlight along the handle
  for (let s = 0; s <= 18; s++) {
    const f = s / 18;
    const hx0 = lerp(spineHeel.x + 14, edgeHeel.x + 14, f);
    const hy0 = lerp(spineHeel.y - 1, edgeHeel.y - 3, f);
    const hx1 = lerp(handleEndTop.x, handleEndBot.x, f);
    const hy1 = lerp(handleEndTop.y, handleEndBot.y, f);

    // Belly swell in middle of handle
    const mx = (hx0 + hx1) * 0.5;
    const my = (hy0 + hy1) * 0.5 + (f - 0.35) * 8;

    let hCol = PAL.handleDark;
    if (f > 0.15 && f < 0.42) hCol = PAL.handleLight;
    else if (f >= 0.42 && f < 0.72) hCol = PAL.handleMid;

    brush.set("fine_cpencil", hCol, 0.75);
    brush.spline([[hx0, hy0, 0.9], [mx, my, 1.1], [hx1, hy1, 0.9]], 0.4);
  }

  // Polished steel/brass bolster at the heel of the handle
  for (let b = 0; b < 14; b++) {
    const bxTop = spineHeel.x + b * 1.1;
    const byTop = spineHeel.y - 1 - b * 0.2;
    const bxBot = edgeHeel.x + b * 1.1;
    const byBot = edgeHeel.y - 3 - b * 0.2;
    const bCol = b < 5 ? PAL.steelEdge : (b < 10 ? PAL.brassBright : PAL.brassDark);
    brush.set("rotring", bCol, 0.48);
    brush.line(bxTop, byTop, bxBot, byBot);
  }

  // Three brass rivets along the rosewood handle centerline
  const rivetTs = [0.24, 0.54, 0.84];
  for (let r = 0; r < rivetTs.length; r++) {
    const rt = rivetTs[r];
    const rx = lerp((spineHeel.x + edgeHeel.x) * 0.5, (handleEndTop.x + handleEndBot.x) * 0.5, rt);
    const ry = lerp((spineHeel.y + edgeHeel.y) * 0.5, (handleEndTop.y + handleEndBot.y) * 0.5, rt);

    brush.set("rotring", PAL.handleDark, 0.45);
    brush.circle(rx, ry, 5.5, 0.1);
    brush.set("marker", PAL.brassDark, 0.45);
    brush.line(rx - 3, ry, rx + 3, ry);
    brush.set("rotring", PAL.brassBright, 0.5);
    brush.line(rx - 2, ry - 1, rx + 2, ry + 1);
    brush.set("rotring", PAL.steelEdge, 0.45);
    brush.line(rx - 1.5, ry - 1.5, rx - 0.2, ry - 1.5);
  }

  // Crisp outer pen contour around the handle
  brush.set("rotring", "#0d0503", 0.48);
  brush.line(spineHeel.x, spineHeel.y - 2, handleEndTop.x, handleEndTop.y);
  brush.line(handleEndTop.x, handleEndTop.y, handleEndBot.x, handleEndBot.y);
  brush.line(handleEndBot.x, handleEndBot.y, edgeHeel.x, edgeHeel.y - 2);
}

