// ============================================================================
// 7. THE UNBROKEN 3D LORENZ APPLE PEEL RIBBON (PAINTER'S DEPTH SORTING)
// ============================================================================
function drawLorenzPeelRibbon(ribbonData) {
  const stations = ribbonData.stations;
  const N = stations.length;

  // Group stations into short overlapping micro-slices of 2 segments each
  // and sort them from back (lowest Z) to front (highest Z) so every 3D lobe
  // crossing occludes background loops cleanly and accurately.
  let slices = [];
  for (let i = 0; i < N - 2; i += 2) {
    const s0 = stations[i];
    const s1 = stations[i + 1];
    const s2 = stations[Math.min(N - 1, i + 2)];
    const avgZ = (s0.z + s1.z + s2.z) / 3.0;
    slices.push({ idx: i, s0, s1, s2, avgZ });
  }

  slices.sort((a, b) => a.avgZ - b.avgZ);

  const lightDir = { x: -0.45, y: -0.55, z: 0.7 };

  // Helper to evaluate intrinsic longitudinal colour streaks on the apple skin
  // v in [-1, 1] across the width of the ribbon, idx along the length
  function getSkinColor(idx, v, lightVal, shadowFactor) {
    // Continuous longitudinal vascular streaks in chartreuse and golden-amber
    const streakNoise = noise(idx * 0.028, (v + 1.5) * 2.8);
    const fineStreak = noise(idx * 0.08, (v + 2.0) * 6.5);
    const netLight = lightVal * (1.0 - shadowFactor * 0.75);

    // Chartreuse streak bands
    if (streakNoise > 0.61 || (Math.abs(v - 0.25) < 0.22 && fineStreak > 0.56)) {
      if (netLight > 0.35) return fineStreak > 0.62 ? PAL.chartreuseBright : PAL.chartreuse;
      if (netLight > -0.05) return PAL.chartreuseDark;
      return "#4d5914";
    }
    // Golden-orange transition margin around chartreuse streaks
    if (streakNoise > 0.54) {
      return netLight > 0.15 ? PAL.amberStreak : PAL.scarlet;
    }
    // Rich crimson & scarlet apple skin
    if (netLight > 0.48) return PAL.scarlet;
    if (netLight > 0.15) return PAL.crimsonBright;
    if (netLight > -0.18) return PAL.crimsonMid;
    if (netLight > -0.45) return PAL.crimsonShadow;
    return PAL.crimsonDeep;
  }

  // Helper to evaluate moist white pith underside colour
  function getPithColor(idx, v, lightVal, shadowFactor) {
    const netLight = lightVal * (1.0 - shadowFactor * 0.72);
    // Faint greenish-cream vascular veins running longitudinally along pith
    const isVein = Math.abs(Math.abs(v) - 0.38) < 0.12 && noise(idx * 0.05, v * 4) > 0.42;
    if (isVein && netLight > -0.1) return PAL.pithVein;
    // Slight greenish-ivory near the cut edge
    if (Math.abs(v) > 0.78 && netLight > 0.1) return PAL.appleGreenHint;

    if (netLight > 0.45) return PAL.pithBright;
    if (netLight > 0.12) return PAL.pithCream;
    if (netLight > -0.2) return PAL.pithMid;
    if (netLight > -0.48) return PAL.pithShadow;
    return PAL.pithDeep;
  }

  // Render every slice in strict back-to-front 3D depth order
  for (let k = 0; k < slices.length; k++) {
    const { idx, s0, s1, s2 } = slices[k];

    // Determine whether we are viewing the outer red skin (N.z >= 0)
    // or the moist white underside pith (N.z < 0)
    const nz = s1.N.z;
    const isSkinSide = nz >= 0;

    // Surface normal oriented toward the camera
    const faceNx = isSkinSide ? s1.N.x : -s1.N.x;
    const faceNy = isSkinSide ? s1.N.y : -s1.N.y;
    const faceNz = Math.abs(nz);

    const lightVal = faceNx * lightDir.x + faceNy * lightDir.y + faceNz * lightDir.z;
    const shadow = s1.shadowFactor;

    // 1. SOLID OPAQUE UNDERPAINTING ("peel_base" marker cross-strokes)
    // Ensures foreground ribbon lobes 100% occlude background lobes passing behind them
    const subSteps = 3;
    for (let m = 0; m <= subSteps; m++) {
      const f = m / subSteps;
      const stA = f < 0.5 ? s0 : s1;
      const stB = f < 0.5 ? s1 : s2;
      const tLocal = f < 0.5 ? f * 2 : (f - 0.5) * 2;

      const lx1 = lerp(stA.e1.x, stB.e1.x, tLocal);
      const ly1 = lerp(stA.e1.y, stB.e1.y, tLocal);
      const lx2 = lerp(stA.e2.x, stB.e2.x, tLocal);
      const ly2 = lerp(stA.e2.y, stB.e2.y, tLocal);
      const mx = (lx1 + lx2) * 0.5;
      const my = (ly1 + ly2) * 0.5;

      const colL = isSkinSide
        ? getSkinColor(idx, -0.5, lightVal, shadow)
        : getPithColor(idx, -0.5, lightVal, shadow);
      const colR = isSkinSide
        ? getSkinColor(idx, 0.5, lightVal, shadow)
        : getPithColor(idx, 0.5, lightVal, shadow);

      brush.set("peel_base", colL, 0.95);
      brush.line(lx1, ly1, mx, my);
      brush.set("peel_base", colR, 0.95);
      brush.line(mx, my, lx2, ly2);
    }

    // 2. DENSE COLOURED-PENCIL LAYERING ("fine_cpencil" & "cpencil")
    // Longitudinal streaks across the ribbon width (v in [-0.92, 0.92])
    const numStreaks = 7;
    for (let s = 0; s < numStreaks; s++) {
      const v = map(s, 0, numStreaks - 1, -0.9, 0.9);
      const u01 = (v + 1) * 0.5;

      // Transverse curvature across the ribbon width modifies the local normal
      const curveLight = lightVal + v * 0.22 * (isSkinSide ? 1 : -1);

      const x0 = lerp(s0.e1.x, s0.e2.x, u01);
      const y0 = lerp(s0.e1.y, s0.e2.y, u01);
      const x2 = lerp(s2.e1.x, s2.e2.x, u01);
      const y2 = lerp(s2.e1.y, s2.e2.y, u01);

      const streakCol = isSkinSide
        ? getSkinColor(idx, v, curveLight, shadow)
        : getPithColor(idx, v, curveLight, shadow);

      brush.set("fine_cpencil", streakCol, random(0.65, 1.05));
      brush.line(x0, y0, x2, y2);
    }

    // 3. LENTICELS ON SKIN OR MOIST GLISTENING HIGHLIGHTS ON PITH UNDERSIDE
    if (isSkinSide) {
      // Fleck the crimson & chartreuse skin with starry pale cream lenticels
      const numLenticels = (idx % 2 === 0) ? 2 : 1;
      for (let l = 0; l < numLenticels; l++) {
        const lv = random(-0.78, 0.78);
        const lu = (lv + 1) * 0.5;
        const lx = lerp(s1.e1.x, s1.e2.x, lu);
        const ly = lerp(s1.e1.y, s1.e2.y, lu);
        const lentCol = shadow > 0.35 ? PAL.appleOchre : PAL.lenticel;

        brush.set("lenticel_tip", lentCol, random(0.45, 0.85));
        brush.line(lx, ly, lx + s1.T.x * 1.6, ly + s1.T.y * 1.6);
      }

      // Waxy cuticle specular sheen where the skin catches direct light
      if (lightVal > 0.52 && shadow < 0.2 && faceNz > 0.35) {
        const sx0 = lerp(s0.e1.x, s0.e2.x, 0.38);
        const sy0 = lerp(s0.e1.y, s0.e2.y, 0.38);
        const sx2 = lerp(s2.e1.x, s2.e2.x, 0.38);
        const sy2 = lerp(s2.e1.y, s2.e2.y, 0.38);
        brush.set("rotring", PAL.skinSheen, 0.38);
        brush.line(sx0, sy0, sx2, sy2);
      }
    } else {
      // Moist white underside catching light with wet cellular highlights
      if (lightVal > 0.22 && shadow < 0.3) {
        const gx0 = lerp(s0.e1.x, s0.e2.x, 0.52);
        const gy0 = lerp(s0.e1.y, s0.e2.y, 0.52);
        const gx2 = lerp(s2.e1.x, s2.e2.x, 0.52);
        const gy2 = lerp(s2.e1.y, s2.e2.y, 0.52);

        brush.set("fine_cpencil", PAL.pithBright, 0.9);
        brush.line(gx0, gy0, gx2, gy2);

        if (idx % 2 === 0) {
          brush.set("rotring", "#ffffff", 0.42);
          brush.line(gx0, gy0, (gx0 + gx2) * 0.5, (gy0 + gy2) * 0.5);
        }
      }
    }

    // 4. FLESHY CUT-EDGE THICKNESS BEVEL (3px pith rim along both edges of the ribbon)
    // Gives the ribbon unmistakable hyperreal 3D thickness as it twists through space
    const rimThick = 2.8;
    const rimNx = -s1.N.x * rimThick;
    const rimNy = -s1.N.y * rimThick;
    const pithEdgeCol = shadow > 0.35 ? PAL.pithShadow : PAL.pithCream;

    // Edge 1 fleshy pith thickness
    brush.set("cpencil", pithEdgeCol, 0.65);
    brush.line(s0.e1.x + rimNx, s0.e1.y + rimNy, s2.e1.x + rimNx, s2.e1.y + rimNy);
    // Edge 2 fleshy pith thickness
    brush.line(s0.e2.x + rimNx, s0.e2.y + rimNy, s2.e2.x + rimNx, s2.e2.y + rimNy);

    // Bright red skin cuticle line along the outer edge of the pith bevel
    const cuticleCol = shadow > 0.35 ? PAL.crimsonShadow : PAL.crimsonBright;
    brush.set("rotring", cuticleCol, 0.42);
    brush.line(s0.e1.x, s0.e1.y, s2.e1.x, s2.e1.y);
    brush.line(s0.e2.x, s0.e2.y, s2.e2.x, s2.e2.y);

    // 5. FINE CONTINUOUS PEN CONTOURS & CROSS-CONTOUR ENGRAVING ("rotring" & "pen")
    const inkCol = isSkinSide
      ? (shadow > 0.3 ? "#140204" : PAL.crimsonDeep)
      : (shadow > 0.3 ? "#2b2015" : "#4a3723");

    // Continuous pen outlines on both ribbon edges
    brush.set("rotring", inkCol, 0.38);
    brush.line(s0.e1.x + rimNx * 1.15, s0.e1.y + rimNy * 1.15, s2.e1.x + rimNx * 1.15, s2.e1.y + rimNy * 1.15);
    brush.line(s0.e2.x, s0.e2.y, s2.e2.x, s2.e2.y);

    // Delicate cross-contour pen hatching along shadowed twists & folds
    if (lightVal < 0.15 || shadow > 0.25 || Math.abs(nz) < 0.35) {
      brush.set("rotring", inkCol, 0.26);
      const hatchSpan = map(lightVal, -0.8, 0.3, 0.85, 0.32, true);
      const hx = lerp(s1.e1.x, s1.e2.x, hatchSpan);
      const hy = lerp(s1.e1.y, s1.e2.y, hatchSpan);
      brush.line(s1.e1.x, s1.e1.y, hx, hy);
    }
  }

  // Tiny mist droplets of apple juice suspended in the air near sharp twists of the peel
  const mistIndices = [65, 142, 218, 295, 360, 415];
  for (let m = 0; m < mistIndices.length; m++) {
    const st = stations[Math.min(stations.length - 10, mistIndices[m])];
    if (!st) continue;
    const mx = st.e2.x + st.B.x * random(8, 22);
    const my = st.e2.y + st.B.y * random(8, 22);
    brush.set("marker", PAL.juiceGold, 0.28);
    brush.line(mx - 1.5, my, mx + 1.5, my);
    brush.set("rotring", "#ffffff", 0.38);
    brush.line(mx - 0.8, my - 0.8, mx + 0.4, my - 0.4);
  }
}

