// ============================================================================
// GEOMETRY & 3D RELIEF HEIGHTFIELD CONSTRUCTION
// ============================================================================

function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function subdivideClosedSpline(ctrlPts, subdivisionsPerSeg) {
  let out = [];
  let n = ctrlPts.length;
  for (let i = 0; i < n; i++) {
    let p0 = ctrlPts[(i - 1 + n) % n];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[(i + 1) % n];
    let p3 = ctrlPts[(i + 2) % n];
    for (let s = 0; s < subdivisionsPerSeg; s++) {
      let t = s / subdivisionsPerSeg;
      out.push(evalCatmullRom(p0, p1, p2, p3, t));
    }
  }
  return out;
}

function subdivideOpenSpline(ctrlPts, subdivisionsPerSeg) {
  let out = [];
  let n = ctrlPts.length;
  for (let i = 0; i < n - 1; i++) {
    let p0 = ctrlPts[Math.max(0, i - 1)];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[i + 1];
    let p3 = ctrlPts[Math.min(n - 1, i + 2)];
    for (let s = 0; s < subdivisionsPerSeg; s++) {
      let t = s / subdivisionsPerSeg;
      out.push(evalCatmullRom(p0, p1, p2, p3, t));
    }
  }
  out.push(ctrlPts[n - 1]);
  return out;
}

