    [343, 743],
    [365, 757], // Gnathion
    [402, 765], // Submental line
    [442, 767],
    [462, 771], // Neck-jaw junction
    // Anterior neck, larynx & bust termination
    [463, 795],
    [454, 825], // Laryngeal prominence
    [459, 852],
    [455, 895],
    [443, 945],
    [430, 982],
    // Cameo bust base curve
    [458, 1002],
    [528, 1018],
    [615, 1023],
    [705, 1011],
    [775, 985],
    [810, 950],
    // Posterior neck, nape & occipital skull with cropped curls
    [788, 898],
    [765, 835],
    [751, 770],
    [747, 705], // Nape hollow
    [759, 642], // Nape hairline
    [792, 585],
    [828, 520],
    [850, 448], // Occiput
    [846, 372],
    [815, 302],
    [762, 244],
    [688, 202]
  ];

  let rawPoly = subdivideClosedSpline(silhouetteControl, 10);

  // Add subtle micro-curl undulations along the cranial hair silhouette
  profilePoly = rawPoly.map((pt) => {
    let x = pt[0];
    let y = pt[1];
    // Hair portion of outer contour: above forehead (y < 284) or back of head (x > 640 and y < 645)
    let isHairRim = (y < 284 && x > 366) || (x > 640 && y < 645);
    if (isHairRim) {
      let ang = Math.atan2(y - 420, x - 600);
      let bump = 3.2 * Math.sin(ang * 42) + 1.8 * Math.cos(ang * 79);
      let nx = Math.cos(ang);
      let ny = Math.sin(ang);
      return [x + nx * bump, y + ny * bump];
    }
    return [x, y];
  });

  // Jawline & posterior ramus curve
  jawPoly = subdivideOpenSpline([
    [362, 756],
    [412, 764],
    [475, 761],
    [548, 744],
    [618, 702], // Gonion (jaw angle)
    [634, 635],
    [638, 535]
  ], 12);

  // Hairline boundary separating facial/neck skin from cropped curls
  hairlinePoly = subdivideOpenSpline([
    [368, 286],
    [418, 302],
    [460, 318], // Frontal-temporal recess
    [496, 358], // Temporal peak
    [510, 405],
    [560, 442],
