    [705, 428],
    [734, 472],
    [732, 548],
    [724, 602],
    [758, 646]  // Nape hairline
  ], 12);
}

// Oriented elliptical Gaussian lobe helper
function evalLobe(x, y, cx, cy, rx, ry, deg, amp) {
  let rad = deg * Math.PI / 180;
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);
  let dx = x - cx;
  let dy = y - cy;
  let ux = (dx * cosA + dy * sinA) / rx;
  let uy = (-dx * sinA + dy * cosA) / ry;
  let r2 = ux * ux + uy * uy;
  if (r2 > 9.0) return 0;
  return amp * Math.exp(-r2);
}

// Minimum distance from (x, y) to open polyline + normalized arc parameter t
function distToPolyline(x, y, poly) {
  let minD2 = 1e12;
  let bestT = 0;
  let bestSide = 1;
  let n = poly.length;
  for (let i = 0; i < n - 1; i++) {
    let ax = poly[i][0], ay = poly[i][1];
    let bx = poly[i + 1][0], by = poly[i + 1][1];
    let vx = bx - ax, vy = by - ay;
    let len2 = vx * vx + vy * vy + 1e-9;
    let u = ((x - ax) * vx + (y - ay) * vy) / len2;
    u = Math.max(0, Math.min(1, u));
    let px = ax + u * vx;
    let py = ay + u * vy;
    let dx = x - px, dy = y - py;
    let d2 = dx * dx + dy * dy;
    if (d2 < minD2) {
      minD2 = d2;
      bestT = (i + u) / (n - 1);
      // Cross product for side sign
      bestSide = (vx * (y - ay) - vy * (x - ax)) >= 0 ? 1 : -1;
    }
  }
  return { d: Math.sqrt(minD2), t: bestT, side: bestSide };
}

function evalRidge(x, y, pts, radius, amp) {
  let minD2 = 1e12;
  let bestT = 0;
  let n = pts.length;
  for (let i = 0; i < n - 1; i++) {
    let ax = pts[i][0], ay = pts[i][1];
    let bx = pts[i + 1][0], by = pts[i + 1][1];
    let vx = bx - ax, vy = by - ay;
    let len2 = vx * vx + vy * vy + 1e-9;
    let u = Math.max(0, Math.min(1, ((x - ax) * vx + (y - ay) * vy) / len2));
    let dx = x - (ax + u * vx);
    let dy = y - (ay + u * vy);
    let d2 = dx * dx + dy * dy;
    if (d2 < minD2) {
      minD2 = d2;
      bestT = (i + u) / (n - 1);
    }
  }
  let r2 = minD2 / (radius * radius);
  if (r2 > 9.0) return 0;
  let taper = Math.sin(Math.PI * Math.max(0.05, Math.min(0.95, bestT)));
  return amp * (0.35 + 0.65 * taper) * Math.exp(-r2);
}

function buildReliefHeightfield() {
  // 1. Pre-bucket profile polygon segments by y-band for fast signed distance
  const BAND_SIZE = 16;
  const NUM_BANDS = Math.ceil(1200 / BAND_SIZE);
  let segBands = Array.from({ length: NUM_BANDS }, () => []);
  let nPoly = profilePoly.length;

  for (let i = 0; i < nPoly; i++) {
    let a = profilePoly[i];
    let b = profilePoly[(i + 1) % nPoly];
    let minY = Math.min(a[1], b[1]) - 36;
    let maxY = Math.max(a[1], b[1]) + 36;
    let b0 = Math.max(0, Math.floor(minY / BAND_SIZE));
    let b1 = Math.min(NUM_BANDS - 1, Math.floor(maxY / BAND_SIZE));
    for (let bi = b0; bi <= b1; bi++) {
      segBands[bi].push([a[0], a[1], b[0], b[1]]);
    }
  }

  // Pre-define feature ridge polylines
  const browRidgePts = [[346, 410], [385, 408], [430, 412], [468, 422]];
  const temporalLinePts = [[466, 414], [492, 375], [536, 326]];
  const upperLidPts = [[402, 450], [428, 444], [462, 460]];
  const lidCreasePts = [[401, 439], [430, 435], [466, 452]];
  const lowerLidPts = [[411, 469], [436, 468], [460, 463]];
  const tearTroughPts = [[416, 479], [445, 482], [478, 485]];
  const noseBridgePts = [[358, 440], [335, 472], [312, 508], [292, 548]];
  const alarCreasePts = [[355, 535], [384, 544], [388, 560], [376, 574]];
  const nasolabialPts = [[384, 556], [398, 594], [408, 632]];
  const upperLipPts = [[326, 612], [362, 622], [402, 635]];
  const stomionPts = [[342, 631], [374, 634], [407, 637]];
  const lowerLipPts = [[329, 650], [364, 648], [397, 641]];
  const helixPts = [[654, 488], [652, 454], [676, 437], [712, 455], [721, 502], [705, 548], [678, 572]];
  const scaphaPts = [[668, 454], [701, 468], [706, 514], [692, 544]];
  const antihelixPts = [[664, 466], [690, 486], [691, 522], [674, 546]];
  const antihelixCrusPts = [[684, 460], [690, 486]];
  const earUndercutPts = [[716, 452], [728, 502], [714, 558]];
  const scmPts = [[695, 588], [625, 705], [545, 835], [452, 976]];
  const neckHollowPts = [[565, 765], [518, 845], [472, 925]];
  const claviclePts = [[448, 976], [545, 964], [655, 954]];
  const bustRimPts = [[434, 982], [528, 1015], [625, 1020], [725, 1004], [806, 952]];
  // Tiny scar paths (furrow + posterior lip)
  const scar1FurrowPts = [[434, 396], [445, 418], [456, 440]];
  const scar1LipPts = [[438, 395], [449, 417], [460, 439]];
  const scar2FurrowPts = [[462, 510], [474, 518], [486, 525]];
  const scar2LipPts = [[465, 508], [477, 516], [489, 523]];

  // 2. Compute inside/outside via scanline & signed distance
  for (let gy = 0; gy < GRID_H; gy++) {
    let y = gy * STEP + 0.5;
    // Find scanline intersections with profilePoly
    let xs = [];
    for (let i = 0; i < nPoly; i++) {
      let a = profilePoly[i];
      let b = profilePoly[(i + 1) % nPoly];
      if ((a[1] <= y && b[1] > y) || (b[1] <= y && a[1] > y)) {
        let t = (y - a[1]) / (b[1] - a[1]);
        xs.push(a[0] + t * (b[0] - a[0]));
      }
    }
    xs.sort((a, b) => a - b);

    let band = segBands[Math.min(NUM_BANDS - 1, Math.max(0, Math.floor(y / BAND_SIZE)))];

    for (let gx = 0; gx < GRID_W; gx++) {
      let x = gx * STEP + 0.5;
      let idx = gy * GRID_W + gx;

      // Determine inside/outside from sorted scanline crossings
      let inside = false;
      for (let k = 0; k < xs.length; k += 2) {
        if (k + 1 < xs.length && x >= xs[k] && x <= xs[k + 1]) {
          inside = true;
          break;
        }
      }

      // Quick distance to nearby silhouette segments
      let minD2 = 1225.0; // cap at 35px if far
      for (let s = 0; s < band.length; s++) {
        let seg = band[s];
        let ax = seg[0], ay = seg[1], bx = seg[2], by = seg[3];
        let vx = bx - ax, vy = by - ay;
        let len2 = vx * vx + vy * vy + 1e-9;
        let u = ((x - ax) * vx + (y - ay) * vy) / len2;
        u = u < 0 ? 0 : (u > 1 ? 1 : u);
        let dx = x - (ax + u * vx);
        let dy = y - (ay + u * vy);
        let d2 = dx * dx + dy * dy;
        if (d2 < minD2) minD2 = d2;
      }

      let d = Math.sqrt(minD2);
      let signedD = inside ? d : -d;
      distGrid[idx] = signedD;

      if (!inside) {
        heightGrid[idx] = 0;
        continue;
      }

      // Compute broader interior cushion using smooth vertical/horizontal span
      let spanX = (xs.length >= 2) ? Math.max(10, xs[xs.length - 1] - xs[0]) : 300;
      let leftX = (xs.length >= 2) ? xs[0] : 350;
      let rightX = (xs.length >= 2) ? xs[xs.length - 1] : 800;
      let dBroad = Math.min(x - leftX, rightX - x, Math.max(0, y - 186), Math.max(0, 1020 - y));

      // Steep cameo edge wall + rounded cranial/facial base volume
      let edgeWall = (1.0 - Math.exp(-d / 5.5)) * Math.min(1.0, d / 2.5);
      let baseDome = 0.22 * edgeWall + 0.44 * (1.0 - Math.exp(-dBroad / 78.0));

      // Jawline & submental step separation
      let jawInfo = distToPolyline(x, y, jawPoly);
      // Above/left of jawPoly is the face/mandible; below/right is the shadowed neck
      let onFaceSide = (y < 765 && x < 642 && jawInfo.side < 0);
      let jawTrans = onFaceSide ? (1.0 / (1.0 + Math.exp(-jawInfo.d / 7.5))) : (1.0 / (1.0 + Math.exp(jawInfo.d / 6.0)));
      // Fade out jaw step above the ear tragus (y < 535)
      if (y < 535) {
        let fadeUp = Math.max(0, Math.min(1, (y - 470) / 65.0));
        jawTrans = 1.0 * (1.0 - fadeUp) + jawTrans * fadeUp;
      }
      let jawPlatform = 0.24 * (jawTrans - 0.5);
      let jawBoneRidge = evalRidge(x, y, jawPoly, 15.0, 0.12);

      // Submental shadow zone mask (for rich dark pencil hatching under the jaw)
      if (!onFaceSide && jawInfo.d < 52 && y > 545 && y < 840 && x < 680) {
        jawShadowGrid[idx] = Math.exp(-jawInfo.d / 24.0);
      }

      // Anatomical 3D Sculpting Lobes & Ridges
      let h = baseDome + jawPlatform + jawBoneRidge;

      // Forehead, brow & temple
      h += evalLobe(x, y, 412, 345, 66, 46, -12, 0.14);
      h += evalRidge(x, y, browRidgePts, 20.0, 0.18);
      h += evalLobe(x, y, 526, 396, 48, 42, -20, -0.09); // Temporal fossa hollow
      h += evalRidge(x, y, temporalLinePts, 9.0, 0.045);

      // Orbit, eyeball & eyelids
      h += evalLobe(x, y, 422, 452, 42, 28, 8, -0.15); // Orbital socket
      h += evalLobe(x, y, 424, 458, 23, 21, 0, 0.15);  // Eyeball sphere
      h += evalRidge(x, y, upperLidPts, 7.5, 0.11);    // Upper eyelid
      h += evalRidge(x, y, lidCreasePts, 4.5, -0.085); // Supratarsal crease
      h += evalRidge(x, y, lowerLidPts, 6.0, 0.075);   // Lower eyelid
      h += evalRidge(x, y, tearTroughPts, 7.5, -0.045);

      // Nose bridge, tip, alar wing, alar crease, nostril
      h += evalRidge(x, y, noseBridgePts, 17.0, 0.16);
      h += evalLobe(x, y, 304, 548, 18, 15, -10, 0.14); // Nasal tip cartilage
      h += evalLobe(x, y, 368, 554, 22, 16, -15, 0.16); // Alar wing
      h += evalRidge(x, y, alarCreasePts, 5.5, -0.11);  // Alar crease
      h += evalLobe(x, y, 338, 565, 14, 6.5, -18, -0.22); // Nostril undercut

      // Cheekbone (zygoma), malar mound, nasolabial & buccal hollow
      h += evalLobe(x, y, 458, 520, 56, 34, 14, 0.20);  // Malar prominence
      h += evalLobe(x, y, 556, 514, 54, 22, -6, 0.13);  // Zygomatic arch
      h += evalRidge(x, y, nasolabialPts, 6.5, -0.055);
      h += evalLobe(x, y, 504, 608, 55, 42, 24, -0.09); // Buccal hollow

      // Philtrum, lips, stomion & chin
      h += evalLobe(x, y, 344, 596, 12, 16, -18, 0.065);
      h += evalRidge(x, y, upperLipPts, 10.5, 0.13);
      h += evalRidge(x, y, stomionPts, 4.2, -0.18);
      h += evalRidge(x, y, lowerLipPts, 12.5, 0.16);
      h += evalLobe(x, y, 364, 679, 26, 12, 10, -0.12); // Labiomental groove
      h += evalLobe(x, y, 362, 722, 32, 26, -10, 0.18); // Chin dome

      // Ear (Pinna) high-relief structure
      let earEnv = evalLobe(x, y, 680, 512, 46, 78, 8, 1.0);
      earMaskGrid[idx] = Math.min(1.0, earEnv * 1.4);
      h += 0.12 * earEnv;
      h += evalRidge(x, y, earUndercutPts, 8.0, -0.19);
      h += evalRidge(x, y, helixPts, 7.5, 0.18);
      h += evalRidge(x, y, scaphaPts, 5.0, -0.085);
      h += evalRidge(x, y, antihelixPts, 8.0, 0.15);
      h += evalRidge(x, y, antihelixCrusPts, 6.5, 0.11);
      h += evalLobe(x, y, 670, 512, 16, 24, 5, -0.22); // Concha bowl
      h += evalLobe(x, y, 645, 514, 9, 12, 0, 0.14);   // Tragus
      h += evalLobe(x, y, 668, 548, 10, 8, -10, 0.12); // Antitragus
      h += evalLobe(x, y, 666, 576, 18, 16, -12, 0.15);// Lobule

      // Neck musculature (SCM, larynx, clavicle, bust bevel)
      h += evalRidge(x, y, scmPts, 34.0, 0.16);
      h += evalRidge(x, y, neckHollowPts, 24.0, -0.095);
      h += evalLobe(x, y, 474, 828, 22, 20, -8, 0.09);  // Larynx
      h += evalLobe(x, y, 590, 922, 45, 28, -12, -0.08);// Supraclavicular fossa
      h += evalRidge(x, y, claviclePts, 18.0, 0.11);
      h += evalRidge(x, y, bustRimPts, 14.0, 0.09);

      // Tiny healed scars (brow/orbital rim + malar cheekbone)
      h += evalRidge(x, y, scar1FurrowPts, 2.2, -0.075);
      h += evalRidge(x, y, scar1LipPts, 3.0, 0.06);
      h += evalRidge(x, y, scar2FurrowPts, 2.0, -0.055);
      h += evalRidge(x, y, scar2LipPts, 2.8, 0.045);

      // Cranial vault fullness
      h += evalLobe(x, y, 650, 385, 165, 145, -15, 0.18);

      // Determine Hair Zone vs. Skin Zone from hairlinePoly
      let hlInfo = distToPolyline(x, y, hairlinePoly);
      let inHairRegion = false;
      if (y < 650 && earMaskGrid[idx] < 0.32) {
        if (y < 285) {
          inHairRegion = true;
        } else if (hlInfo.side < 0 && x > 365) {
          inHairRegion = true;
        }
      }

      if (inHairRegion) {
        let hairFade = Math.min(1.0, hlInfo.d / 18.0);
        hairMaskGrid[idx] = hairFade;
        skinMaskGrid[idx] = 1.0 - hairFade;
        h += 0.08 * hairFade; // Slight elevation of curl cap over scalp
      } else {
        hairMaskGrid[idx] = 0;
        skinMaskGrid[idx] = 1.0;
      }

      heightGrid[idx] = Math.max(0.01, h);
    }
  }

  // 3. Generate Poisson-disc close-cropped curl clusters & add their 3D relief bumps
  generateCurlClusters();

  for (let c of curlClusters) {
    let gcx = Math.floor(c.x / STEP);
    let gcy = Math.floor(c.y / STEP);
    let gr = Math.ceil((c.r * 1.4) / STEP);
    for (let dy = -gr; dy <= gr; dy++) {
      let gy = gcy + dy;
      if (gy < 0 || gy >= GRID_H) continue;
      for (let dx = -gr; dx <= gr; dx++) {
        let gx = gcx + dx;
        if (gx < 0 || gx >= GRID_W) continue;
        let idx = gy * GRID_W + gx;
        let hm = hairMaskGrid[idx];
        if (hm <= 0.02) continue;
        let px = gx * STEP + 0.5 - c.x;
        let py = gy * STEP + 0.5 - c.y;
        let rNorm = Math.sqrt(px * px + py * py) / c.r;
        if (rNorm < 1.25) {
          let dome = Math.max(0, 1.0 - rNorm * rNorm);
          let ang = Math.atan2(py, px) * c.spin + rNorm * 4.2 + c.phase;
          let swirl = 0.032 * dome * Math.cos(ang * 2.0);
          heightGrid[idx] += hm * (0.065 * dome + swirl);
        }
      }
    }
  }

  // 4. Compute surface normals (nx, ny, nz) and raking light intensity
  const Z_SCALE = 115.0;
  for (let gy = 1; gy < GRID_H - 1; gy++) {
    for (let gx = 1; gx < GRID_W - 1; gx++) {
      let idx = gy * GRID_W + gx;
      if (distGrid[idx] <= 0) continue;

      let dhdx = (heightGrid[idx + 1] - heightGrid[idx - 1]) * 0.5 * Z_SCALE / STEP;
      let dhdy = (heightGrid[idx + GRID_W] - heightGrid[idx - GRID_W]) * 0.5 * Z_SCALE / STEP;

      let nx = -dhdx;
      let ny = -dhdy;
      let nz = 1.0;
      let invLen = 1.0 / Math.sqrt(nx * nx + ny * ny + nz * nz);
      nx *= invLen;
      ny *= invLen;
      nz *= invLen;

      nxGrid[idx] = nx;
      nyGrid[idx] = ny;
      nzGrid[idx] = nz;

      // Raking illumination from front-upper-left
      let ndotl = nx * LIGHT_X + ny * LIGHT_Y + nz * LIGHT_Z;
      let diff = Math.max(0, ndotl);

      // Subtle warm bounce light on posterior edge
      let rimBounce = Math.max(0, nx * 0.65 - ny * 0.25) * 0.22;

      // Ambient occlusion in submental jaw shadow and deep cavities
      let ao = 1.0 - 0.55 * jawShadowGrid[idx];
      let hVal = heightGrid[idx];
      let reliefBoost = Math.min(1.15, 0.55 + 0.65 * hVal);

      let lit = (diff * 0.88 * ao + rimBounce) * reliefBoost;
      lightGrid[idx] = Math.max(0, Math.min(1.0, lit));
    }
  }
}

function generateCurlClusters() {
  curlClusters = [];
  // Candidate grid with jitter for organic tight curl packing
  for (let y = 188; y < 650; y += 15) {
    for (let x = 365; x < 855; x += 15) {
      let jx = x + random(-5.5, 5.5);
      let jy = y + random(-5.5, 5.5);
      let gx = Math.floor(jx / STEP);
      let gy = Math.floor(jy / STEP);
      if (gx < 2 || gx >= GRID_W - 2 || gy < 2 || gy >= GRID_H - 2) continue;
      let idx = gy * GRID_W + gx;
      let hm = hairMaskGrid[idx];
      let dEdge = distGrid[idx];
      if (hm < 0.12 && !(dEdge > -4 && dEdge < 14 && ((jy < 285 && jx > 368) || (jx > 645 && jy < 640)))) {
        continue;
      }

      // Smaller tight curls at temple/sideburn/nape fade; fuller curls at crown
      let fadeFactor = Math.min(1.0, Math.max(0.35, hm));
      let radius = random(11, 21) * (0.55 + 0.45 * fadeFactor);

      // Check minimum spacing against existing clusters
      let tooClose = false;
      for (let k = curlClusters.length - 1; k >= 0; k--) {
        let o = curlClusters[k];
        let dx = jx - o.x;
        let dy = jy - o.y;
        let minSep = (radius + o.r) * 0.52;
        if (dx * dx + dy * dy < minSep * minSep) {
          tooClose = true;
          break;
        }
      }
      if (!tooClose) {
        curlClusters.push({
          x: jx,
          y: jy,
          r: radius,
          spin: random() < 0.5 ? 1 : -1,
          phase: random(0, Math.PI * 2),
          fade: fadeFactor
        });
      }
    }
  }
}

function sampleGrid(grid, x, y) {
  let gx = Math.max(0, Math.min(GRID_W - 1, Math.floor(x / STEP)));
  let gy = Math.max(0, Math.min(GRID_H - 1, Math.floor(y / STEP)));
  return grid[gy * GRID_W + gx];
}

function insideOval(x, y, margin = 0) {
  let dx = (x - OVAL_CX) / (OVAL_RX + margin);
  let dy = (y - OVAL_CY) / (OVAL_RY + margin);
  return (dx * dx + dy * dy) <= 1.0;
}

