function renderSardonyxGround() {
  brush.noStroke();
  brush.noHatch();

  // Base caramel-brown wash across canvas
  brush.wash("#3A190B", 230);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Layered sardonyx chalcedony strata bands (gently undulating at -14 deg)
  const strataColors = [
    { col: "#4F2310", op: 85 },
    { col: "#683118", op: 72 },
    { col: "#2A1006", op: 95 },
    { col: "#7C3E20", op: 60 },
    { col: "#3D1A0B", op: 90 }
  ];

  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.62, 0.22);

  for (let b = 0; b < strataColors.length; b++) {
    brush.fill(strataColors[b].col, strataColors[b].op);
    for (let band = 0; band < 3; band++) {
      let baseY = 120 + (b * 3 + band) * 68 + random(-18, 18);
      let bandH = random(42, 88);
      brush.beginShape(0.35);
      for (let x = 60; x <= 1140; x += 90) {
        let wave = 24 * Math.sin(x * 0.0055 + b * 1.3) + 14 * noise(x * 0.004, baseY * 0.004);
        let yTop = baseY - (x - 600) * 0.24 + wave;
        brush.vertex(x, yTop);
      }
      for (let x = 1140; x >= 60; x -= 90) {
        let wave = 24 * Math.sin(x * 0.0055 + b * 1.3 + 0.4) + 14 * noise(x * 0.004, (baseY + bandH) * 0.004);
        let yBot = baseY + bandH - (x - 600) * 0.24 + wave;
        brush.vertex(x, yBot);
      }
      brush.endShape(true);
    }
  }

  // Deep espresso-caramel vignette outside oval and behind relief
  brush.fill("#1E0B03", 125);
  // Left shadow pool in front of face
  brush.circle(260, 560, 145, 0.25);
  // Deep shadow pool under jaw & behind neck
  brush.circle(495, 815, 130, 0.25);
  brush.circle(785, 720, 155, 0.25);
  brush.noFill();

  // Delicate sardonyx mineral grain veins across the stone ground
  const veinPalette = ["#8B4A27", "#5E2B13", "#230C03", "#A6633C", "#471F0C"];
  for (let v = 0; v < 95; v++) {
    let col = veinPalette[v % veinPalette.length];
    let y0 = random(80, 1120);
    let pts = [];
    let xStart = random(90, 260);
    let xEnd = random(940, 1110);
    for (let x = xStart; x <= xEnd; x += 45) {
      let y = y0 - (x - 600) * 0.24 + 18 * Math.sin(x * 0.006 + v * 0.7) + (noise(x * 0.005, v * 0.2) - 0.5) * 28;
      if (insideOval(x, y, 30)) {
        pts.push([x, y, random(0.3, 0.9)]);
      }
    }
    if (pts.length >= 3) {
      brush.set("sard_wash_brush", col, random(0.35, 0.85));
      brush.spline(pts, 0.5);
    }
  }
}

