// ============================================================================
// LAYER 3: FORM-FOLLOWING CROSS-CONTOUR PENCIL MODELING
// ============================================================================

function getAnatomicalFlowAngle(x, y, gx, gy) {
  let idx = gy * GRID_W + gx;
  let nx = nxGrid[idx];
  let ny = nyGrid[idx];

  // Surface contour tangent direction
  let surfAng = Math.atan2(nx, -ny);

  // Blend with anatomical muscle/plane flow direction for sculptural realism
  let anatAng = surfAng;
  if (y < 430 && x < 530) {
    // Forehead & brow: gently arched horizontal sweep
    anatAng = -0.12 + (y - 360) * 0.002;
  } else if (x < 395 && y >= 430 && y < 580) {
    // Nose bridge & alar wing: cross-contour wrapping across bridge
    anatAng = 0.35;
  } else if (x >= 395 && x < 625 && y >= 460 && y < 680) {
    // Cheek & zygomatic arch: sweeping curve from malar down-back toward jaw/ear
    anatAng = 0.28 + (x - 450) * 0.0018;
  } else if (y >= 680 && y < 768 && x < 630) {
    // Chin & jawline: wrapping along mandibular curve
    anatAng = -0.18 + (x - 420) * 0.0015;
  } else if (y >= 740) {
    // Neck & SCM muscle: diagonal sweep parallel/cross to sternocleidomastoid
    anatAng = 2.18;
  }

  // Smooth circular blend between surface tangent and anatomical flow
  let vx = Math.cos(surfAng) * 0.52 + Math.cos(anatAng) * 0.48;
  let vy = Math.sin(surfAng) * 0.52 + Math.sin(anatAng) * 0.48;
  return Math.atan2(vy, vx);
}

function traceSculpturalStroke(x0, y0, steps, stepLen, crossAngleOffset) {
  let pts = [];
  let x = x0;
  let y = y0;
  for (let s = 0; s < steps; s++) {
    let gx = Math.floor(x / STEP);
    let gy = Math.floor(y / STEP);
    if (gx < 2 || gx >= GRID_W - 2 || gy < 2 || gy >= GRID_H - 2) break;
    let idx = gy * GRID_W + gx;
    if (distGrid[idx] < 1.5) break;

    let ang = getAnatomicalFlowAngle(x, y, gx, gy) + crossAngleOffset;
    let pressure = Math.sin((s / Math.max(1, steps - 1)) * Math.PI);
    pts.push([x, y, 0.35 + 0.75 * pressure]);

    x += Math.cos(ang) * stepLen;
    y += Math.sin(ang) * stepLen;
  }
  return pts;
}

function renderFormModeling() {
  // Pass 3A: Deep Espresso & Burnt Umber Shadow Hatching (Submental jaw shadow, cavities, back of neck)
  const darkTones = ["#160601", "#240C04", "#361609", "#4A210E"];

  for (let y = 195; y < 1015; y += 6) {
    for (let x = 285; x < 850; x += 6) {
      let jx = x + random(-2.5, 2.5);
      let jy = y + random(-2.5, 2.5);
      let gx = Math.floor(jx / STEP);
      let gy = Math.floor(jy / STEP);
      if (gx < 2 || gx >= GRID_W - 2 || gy < 2 || gy >= GRID_H - 2) continue;
      let idx = gy * GRID_W + gx;
      if (distGrid[idx] < 2.0) continue;

      let lit = lightGrid[idx];
      let jawShad = jawShadowGrid[idx];

      // Shadow zones & deep under-jaw relief shadow
      if (lit < 0.44 || jawShad > 0.25) {
        let darkness = Math.max(1.0 - lit * 2.1, jawShad * 0.95);
        if (random() < darkness * 0.85) {
          let cIdx = Math.min(darkTones.length - 1, Math.floor((1.0 - darkness) * darkTones.length));
          let pts = traceSculpturalStroke(jx, jy, 5, 4.2, random(-0.12, 0.12));
          if (pts.length >= 3) {
            brush.set("cpencil", darkTones[cIdx], random(0.45, 0.82));
            brush.spline(pts, 0.45);
          }
          // Cross-hatch pass in deepest shadows (especially soft shadow under the jaw)
          if (darkness > 0.58 && random() < 0.65) {
            let pts2 = traceSculpturalStroke(jx, jy, 4, 3.8, 0.52);
            if (pts2.length >= 3) {
              brush.set("2H", "#1A0702", random(0.38, 0.68));
              brush.spline(pts2, 0.4);
            }
          }
        }
      }
    }
  }

  // Pass 3B: Translucent Sardonyx Warm Caramel, Ochre & Biscuit Midtone Pencil Layer
  const midTones = ["#68341A", "#854827", "#A4643E", "#C1865E", "#D8A580"];

  for (let y = 195; y < 1015; y += 5.5) {
    for (let x = 285; x < 850; x += 5.5) {
      let jx = x + random(-2.2, 2.2);
      let jy = y + random(-2.2, 2.2);
      let gx = Math.floor(jx / STEP);
      let gy = Math.floor(jy / STEP);
      if (gx < 2 || gx >= GRID_W - 2 || gy < 2 || gy >= GRID_H - 2) continue;
      let idx = gy * GRID_W + gx;
      if (distGrid[idx] < 2.0 || hairMaskGrid[idx] > 0.65) continue;

      let lit = lightGrid[idx];
      if (lit >= 0.22 && lit <= 0.78) {
        let tNorm = (lit - 0.22) / 0.56;
        let cIdx = Math.min(midTones.length - 1, Math.floor(tNorm * midTones.length));
        let pts = traceSculpturalStroke(jx, jy, 5, 4.4, random(-0.08, 0.08));
        if (pts.length >= 3) {
          brush.set("glaze_pencil", midTones[cIdx], random(0.55, 0.95));
          brush.spline(pts, 0.5);
        }
      }
    }
  }

  // Pass 3C: Subtle Sardonyx Mineral Strata Warped by 3D Relief Height
  const reliefStrataCols = ["#B87B52", "#D9A682", "#7A3E1F", "#EBC4A4"];
  for (let sBand = 210; sBand < 990; sBand += 28) {
    let col = reliefStrataCols[Math.floor(sBand / 28) % reliefStrataCols.length];
    let curPts = [];
    for (let x = 290; x <= 845; x += 8) {
      let baseY = sBand - (x - 550) * 0.22 + 9 * Math.sin(x * 0.012 + sBand * 0.05);
      let d = sampleGrid(distGrid, x, baseY);
      let h = sampleGrid(heightGrid, x, baseY);
      let hm = sampleGrid(hairMaskGrid, x, baseY);
      if (d > 4.0 && hm < 0.4) {
        // Displace mineral band upward by 3D relief height to read as carved stone strata
        let warpedY = baseY - h * 26.0;
        let lit = sampleGrid(lightGrid, x, warpedY);
        if (lit > 0.28) {
          curPts.push([x, warpedY, 0.3 + 0.6 * lit]);
        } else {
          if (curPts.length >= 3) {
            brush.set("2H", col, 0.32);
            brush.spline(curPts, 0.45);
          }
          curPts = [];
        }
      } else {
        if (curPts.length >= 3) {
          brush.set("2H", col, 0.32);
          brush.spline(curPts, 0.45);
        }
        curPts = [];
      }
    }
    if (curPts.length >= 3) {
      brush.set("2H", col, 0.32);
      brush.spline(curPts, 0.45);
    }
  }

  // Pass 3D: Cream & Pale Shell-White Raking Relief Pencil Highlights
  const creamHighlights = ["#E3BA98", "#EED0B5", "#F6E2CE", "#FBF0E4", "#FFFDF9"];

  for (let y = 195; y < 1015; y += 4.2) {
    for (let x = 285; x < 845; x += 4.2) {
      let jx = x + random(-1.8, 1.8);
      let jy = y + random(-1.8, 1.8);
      let gx = Math.floor(jx / STEP);
      let gy = Math.floor(jy / STEP);
      if (gx < 2 || gx >= GRID_W - 2 || gy < 2 || gy >= GRID_H - 2) continue;
      let idx = gy * GRID_W + gx;
      if (distGrid[idx] < 1.5 || hairMaskGrid[idx] > 0.45) continue;

      let lit = lightGrid[idx];
      if (lit >= 0.46) {
        let hNorm = Math.min(1.0, (lit - 0.46) / 0.46);
        let cIdx = Math.min(creamHighlights.length - 1, Math.floor(hNorm * creamHighlights.length));
        let col = creamHighlights[cIdx];

        let pts = traceSculpturalStroke(jx, jy, 5, 3.8, random(-0.06, 0.06));
        if (pts.length >= 3) {
          let w = (0.45 + 0.55 * hNorm) * random(0.85, 1.15);
          brush.set("shell_pencil", col, w);
          brush.spline(pts, 0.5);
        }

        // Extra crisp cross-contour shell-white pass on the brightest raking ridges
        if (lit > 0.72 && random() < 0.75) {
          let ptsHi = traceSculpturalStroke(jx + random(-1, 1), jy + random(-1, 1), 4, 3.2, 0.24);
          if (ptsHi.length >= 3) {
            brush.set("micro_etch", lit > 0.82 ? "#FFFDF9" : "#FAF0E4", random(0.65, 1.05));
            brush.spline(ptsHi, 0.45);
          }
        }
      }
    }
  }
}

// ============================================================================
// LAYER 4: CLOSE-CROPPED CURLS IN FINE DIRECTIONAL HATCHING
// ============================================================================

function renderCroppedCurls() {
  // Sort curl clusters from back/top to front/bottom for natural overlap
  let sortedCurls = curlClusters.slice().sort((a, b) => (a.y - a.x * 0.25) - (b.y - b.x * 0.25));

  for (let c of sortedCurls) {
    let cx = c.x;
    let cy = c.y;
    let r = c.r;
    let spin = c.spin;

    // Global cranial illumination at this curl cluster
    let gLit = sampleGrid(lightGrid, cx - r * 0.25, cy - r * 0.15);
    // Boost illumination on anterior/upper crown facing raking light
    let posBoost = Math.max(0, (660 - cx) / 290.0) * 0.32 + Math.max(0, (440 - cy) / 250.0) * 0.24;
    let curlLit = Math.min(1.0, gLit * 0.75 + posBoost);

    // 1. Dark Espresso-Umber Interstice & Shadow Core Hatching (lower-right of curl)
    let shadowCount = Math.floor(map(r, 7, 21, 5, 11));
    for (let s = 0; s < shadowCount; s++) {
      let a0 = random(15, 155) * Math.PI / 180; // Lower-right shadow side
      let rad = r * random(0.45, 1.05);
      let span = random(0.7, 1.35) * spin;
      let pts = [];
      for (let k = 0; k <= 4; k++) {
        let t = k / 4;
        let a = a0 + t * span;
        let rk = rad * (1.0 - 0.18 * t);
        pts.push([cx + Math.cos(a) * rk, cy + Math.sin(a) * rk, 0.4 + 0.6 * Math.sin(t * Math.PI)]);
      }
      let darkCol = (s % 2 === 0) ? "#160501" : "#2D1206";
      brush.set("micro_etch", darkCol, random(0.65, 1.1));
      brush.spline(pts, 0.55);
    }

    // 2. Warm Caramel & Toasted Biscuit Mid-Strand Hatching (coiling through the lock)
    let midCount = Math.floor(map(r, 7, 21, 6, 13));
    for (let m = 0; m < midCount; m++) {
      let a0 = random(-90, 180) * Math.PI / 180;
      let rad = r * random(0.28, 0.92);
      let span = random(0.85, 1.65) * spin;
      let pts = [];
      for (let k = 0; k <= 4; k++) {
        let t = k / 4;
        let a = a0 + t * span;
        let rk = rad * (0.95 - 0.22 * t);
        pts.push([cx + Math.cos(a) * rk, cy + Math.sin(a) * rk, 0.35 + 0.65 * Math.sin(t * Math.PI)]);
      }
      let midCol = curlLit > 0.5 ? ((m % 2 === 0) ? "#B87A52" : "#8F502D") : ((m % 2 === 0) ? "#733A1C" : "#522510");
      brush.set("2H", midCol, random(0.35, 0.62));
      brush.spline(pts, 0.55);
    }

    // 3. Raking Cream & Shell-White Highlight Strands on Upper-Left Ridge of Each Curl
    if (curlLit > 0.26) {
      let hiCount = Math.floor(map(curlLit, 0.26, 1.0, 3, 12) * (r / 16.0));
      for (let h = 0; h < hiCount; h++) {
        // Upper-left crescent facing the raking light (-175 deg to -35 deg)
        let a0 = random(-185, -45) * Math.PI / 180;
        let rad = r * random(0.35, 0.96);
        let span = random(0.65, 1.25) * spin;
        let pts = [];
        for (let k = 0; k <= 4; k++) {
          let t = k / 4;
          let a = a0 + t * span;
          let rk = rad * (1.0 - 0.12 * t);
          pts.push([cx + Math.cos(a) * rk, cy + Math.sin(a) * rk, 0.3 + 0.8 * Math.sin(t * Math.PI)]);
        }
        let hiCol = "#E8C5A5";
        if (curlLit > 0.72 && h % 2 === 0) hiCol = "#FFFDF9";
        else if (curlLit > 0.52) hiCol = "#F8E8D6";
        else if (curlLit > 0.38) hiCol = "#ECCBB0";

        brush.set("micro_etch", hiCol, random(0.55, 0.98));
        brush.spline(pts, 0.55);
      }
    }
  }

  // 4. Delicate Edge Baby-Curls & Temple/Sideburn/Nape Tapered Fade Hairs
  for (let i = 0; i < hairlinePoly.length - 1; i++) {
    let p = hairlinePoly[i];
    let hx = p[0];
    let hy = p[1];
    // Draw short curved taper hairs bridging skin and hair at the hairline & sideburn fade
    for (let k = 0; k < 5; k++) {
      let sx = hx + random(-9, 9);
      let sy = hy + random(-9, 9);
      let lit = sampleGrid(lightGrid, sx, sy);
      let ang = random(-0.9, 0.6);
      let len = random(4.5, 10.5);
      let mx = sx + Math.cos(ang) * len * 0.5 - Math.sin(ang) * 2.2;
      let my = sy + Math.sin(ang) * len * 0.5 + Math.cos(ang) * 2.2;
      let ex = sx + Math.cos(ang) * len;
      let ey = sy + Math.sin(ang) * len;

      let col = (k % 2 === 0) ? "#230B03" : (lit > 0.52 ? "#F5E2CE" : "#9E5E3B");
      brush.set("micro_etch", col, random(0.45, 0.75));
      brush.spline([[sx, sy, 0.8], [mx, my, 0.6], [ex, ey, 0.2]], 0.5);
    }
  }
}

// ============================================================================
// LAYER 5: FOCAL ANATOMICAL FEATURES (EYE, BROW, SCAR, NOSE, LIPS, EAR, RIM)
// ============================================================================

function renderFocalAnatomy() {
  // 1. Crisp Cameo Profile Relief Edge (Dark undercut outside + luminous shell-white rim inside)
  for (let i = 0; i < profilePoly.length; i++) {
    let p0 = profilePoly[i];
    let p1 = profilePoly[(i + 1) % profilePoly.length];
    let p2 = profilePoly[(i + 2) % profilePoly.length];

    let x = p1[0], y = p1[1];
    let tx = p2[0] - p0[0];
    let ty = p2[1] - p0[1];
    let len = Math.sqrt(tx * tx + ty * ty) + 1e-6;
    // Outward normal (for counter-clockwise polygon)
    let onx = ty / len;
    let ony = -tx / len;

    // Dark relief drop-off shadow on the outer edge of the carving
    brush.set("micro_etch", "#140501", 0.85);
    brush.line(p0[0] + onx * 1.2, p0[1] + ony * 1.2, p1[0] + onx * 1.2, p1[1] + ony * 1.2);

    // Raking shell-white highlight on the anterior profile edge (forehead, nose, lips, chin, throat)
    let edgeLit = -(onx * LIGHT_X + ony * LIGHT_Y);
    if (x < 485 && y > 275 && y < 980 && edgeLit > 0.15) {
      let hiCol = edgeLit > 0.62 ? "#FFFDF9" : (edgeLit > 0.38 ? "#FAF0E4" : "#E8C6A8");
      let hiW = map(edgeLit, 0.15, 0.95, 0.55, 1.35, true);
      brush.set("shell_pencil", hiCol, hiW);
      brush.line(p0[0] - onx * 1.0, p0[1] - ony * 1.0, p1[0] - onx * 1.0, p1[1] - ony * 1.0);
    }
  }

  // 2. The Eye in Side Profile (Cornea, Iris, Lashes, Eyelids)
  // Supratarsal upper eyelid fold shadow & lit rim
  brush.set("micro_etch", "#180601", 0.95);
  brush.spline([[399, 440, 0.5], [418, 434, 1.0], [442, 439, 0.9], [468, 453, 0.4]], 0.5);
  brush.set("shell_pencil", "#FAF0E4", 0.85);
  brush.spline([[402, 446, 0.6], [422, 441, 1.1], [445, 446, 0.9], [464, 457, 0.4]], 0.5);

  // Oblique eyeball & iris in profile (x: 410..428, y: 451..468)
  // Sclera warm cream shading on lower-posterior portion
  for (let sy = 454; sy <= 466; sy += 1.5) {
    brush.set("micro_etch", sy < 459 ? "#9E5E3B" : "#F3DEC8", 0.65);
    brush.line(416, sy, 446 - (sy - 454) * 0.8, sy + 1);
  }
  // Iris & pupil in side view (dark espresso core with warm amber-sardonyx iris rim)
  for (let a = -75; a <= 75; a += 12) {
    let rad = a * Math.PI / 180;
    let ix = 415 + Math.cos(rad) * 6.5;
    let iy = 459 + Math.sin(rad) * 8.5;
    brush.set("micro_etch", Math.abs(a) < 35 ? "#120401" : "#6B3418", 0.85);
    brush.line(413, 459, ix, iy);
  }
  // Upper lash line & individual sweeping eyelashes in profile
  brush.set("micro_etch", "#100300", 1.25);
  brush.spline([[403, 451, 0.9], [422, 449, 1.1], [444, 455, 0.9], [462, 462, 0.6]], 0.5);
  for (let l = 0; l < 18; l++) {
    let t = l / 17;
    let lx = 404 + t * 50;
    let ly = 450 + t * 11 - Math.sin(t * Math.PI) * 3.5;
    let sweep = (1.0 - t * 0.55);
    let pMid = [lx - 7 * sweep, ly + 1.5 - t * 2, 0.8];
    let pTip = [lx - 13 * sweep, ly - 2.5 - t * 2, 0.2];
    brush.set("micro_etch", "#120401", 0.82);
    brush.spline([[lx, ly, 1.0], pMid, pTip], 0.5);
  }
  // Lower eyelid wet rim (waterline catchlight) & subtle lower lashes
  brush.set("micro_etch", "#FBF0E4", 0.88);
  brush.spline([[412, 468, 0.7], [432, 467, 1.0], [456, 463, 0.5]], 0.5);
  brush.set("micro_etch", "#240C04", 0.7);
  brush.spline([[412, 470, 0.6], [434, 470, 0.9], [458, 465, 0.4]], 0.5);
  for (let l = 0; l < 10; l++) {
    let t = l / 9;
    let lx = 415 + t * 38;
    let ly = 470 - t * 4;
    brush.set("micro_etch", "#2B1005", 0.5);
    brush.spline([[lx, ly, 0.8], [lx - 4, ly + 4, 0.5], [lx - 7, ly + 6, 0.2]], 0.5);
  }
  // Pin-sharp shell-white corneal highlight on anterior corneal dome
  brush.set("micro_etch", "#FFFFFF", 1.35);
  brush.spline([[411, 454, 0.8], [412.5, 456.5, 1.2], [414, 459, 0.7]], 0.5);
  brush.set("shell_pencil", "#FFFDF9", 0.9);
  brush.line(412, 455, 413, 458);

  // 3. The Eyebrow & The Tiny Healed Scar Interrupting the Brow
  for (let b = 0; b < 85; b++) {
    let t = b / 84;
    let bx = 356 + t * 122 + random(-2, 2);
    let by = 412 - Math.sin(t * Math.PI) * 7 + t * 10 + random(-4, 4);

