// LAYER 6: REAL SKIN TEXTURE — MICRO-PORES & FINE STUBBLE
// ============================================================================

function renderSkinPoresAndStubble() {
  // 1. Skin Micro-Pores (Nose, Malar Cheek, Brow, Temple)
  // Paired dark micro-indent on left + cream catchlight on right
  for (let p = 0; p < 1450; p++) {
    let px = random(292, 625);
    let py = random(310, 745);
    let d = sampleGrid(distGrid, px, py);
    let sm = sampleGrid(skinMaskGrid, px, py);
    let em = sampleGrid(earMaskGrid, px, py);
    if (d < 5 || sm < 0.6 || em > 0.3) continue;

    // Exclude eyeball & lip vermilion from pores
    let dEye = Math.hypot(px - 426, py - 458);
    let dMouth = Math.hypot(px - 358, py - 634);
    if (dEye < 26 || dMouth < 32) continue;

    // Higher pore density on nose wing/tip, malar cheek, and glabella
    let dNose = Math.hypot(px - 342, py - 540);
    let dCheek = Math.hypot(px - 458, py - 535);
    let dBrow = Math.hypot(px - 392, py - 395);
    let poreProb = (dNose < 55 || dCheek < 75 || dBrow < 55) ? 0.92 : 0.38;
    if (random() > poreProb) continue;

    let lit = sampleGrid(lightGrid, px, py);
    if (lit < 0.25 || lit > 0.90) continue;

    // Tiny dark pore pit
    brush.set("micro_etch", lit > 0.55 ? "#5A2913" : "#2D1106", random(0.42, 0.68));
    brush.line(px, py, px + 1.1, py + 0.9);

    // Tiny shell-white/cream catchlight on posterior rim of pore
    if (lit > 0.42) {
      brush.set("micro_etch", lit > 0.68 ? "#FFFDF9" : "#F3DAC2", random(0.45, 0.72));
      brush.line(px + 1.4, py - 0.3, px + 2.5, py + 1.1);
    }
  }

  // 2. Fine Facial Stubble (Upper Lip, Chin, Mandible, Lower Cheek, Upper Neck)
  for (let s = 0; s < 1650; s++) {
    let sx = random(322, 635);
    let sy = random(575, 825);
    let d = sampleGrid(distGrid, sx, sy);
    if (d < 1.5) continue;

    // Exclude lip vermilion cushions (stomion/vermilion region)
    let inVermilion = (sx < 406 && sy > 606 && sy < 664 && (sx - 325) * 0.35 + Math.abs(sy - 634) < 28);
    if (inVermilion) continue;

    // Define beard/stubble zone mask (upper lip philtrum, chin, jawline, lower cheek, submental)
    let onUpperLip = (sx < 405 && sy >= 578 && sy <= 632);
    let onChinAndJaw = (sy >= 655 && sy <= 772 && sx < 632);
    let onLowerCheek = (sx >= 405 && sx < 625 && sy >= 565 + (600 - sx) * 0.32 && sy < 720);
    let onUpperNeck = (sy >= 755 && sy <= 818 && sx >= 400 && sx <= 585);

    if (!(onUpperLip || onChinAndJaw || onLowerCheek || onUpperNeck)) continue;

    let lit = sampleGrid(lightGrid, sx, sy);
    // Natural follicle growth angle sweeping downward and backward along the jaw
    let follAng = 0.65 + (sx - 350) * 0.0022 + random(-0.18, 0.18);
    let len = random(2.4, 4.8);

    // Alternate dark follicle shafts and glistening raking cream/shell-white stubble tips
    let isGlint = (lit > 0.48 && random() < 0.58) || (lit > 0.25 && random() < 0.22);
    let col = isGlint ? (lit > 0.72 ? "#FFFDF9" : "#F5E0CA") : (lit > 0.5 ? "#471F0E" : "#1C0802");

    brush.set("micro_etch", col, random(0.48, 0.78));
    brush.line(sx, sy, sx + Math.cos(follAng) * len, sy + Math.sin(follAng) * len);
  }

  // 3. Profile-Edge Micro-Stubble Catching Raking Light (Upper Lip, Chin & Under-Jaw Silhouette)
  for (let i = 0; i < profilePoly.length; i++) {
    let p = profilePoly[i];
    let x = p[0], y = p[1];
    // Along philtrum (580..608) and chin/under-jaw (668..768)
    if (x < 455 && ((y >= 580 && y <= 606) || (y >= 668 && y <= 768))) {
      for (let k = 0; k < 2; k++) {
        let jx = x + random(-1.5, 0.5);
        let jy = y + random(-2, 2);
        let ang = (y < 610) ? random(2.4, 2.9) : (y < 745 ? random(2.5, 3.2) : random(1.5, 2.2));
        let len = random(2.5, 4.5);
        brush.set("micro_etch", k === 0 ? "#FFFDF9" : "#E8C4A2", random(0.55, 0.85));
        brush.line(jx, jy, jx + Math.cos(ang) * len, jy + Math.sin(ang) * len);
      }
    }
  }
}

// ============================================================================
// LAYER 7: THIN OVAL CAMEO BORDER WITH RAKING RELIEF LIGHTING
// ============================================================================

function renderOvalCameoBorder() {
  const N_SEG = 180;

  // Draw concentric elliptical cameo bezel strokes modulated by raking light angle
  const rings = [
    { rx: OVAL_RX - 10, ry: OVAL_RY - 10, role: "inner_wall" },
    { rx: OVAL_RX - 5,  ry: OVAL_RY - 5,  role: "inner_ridge" },
    { rx: OVAL_RX,      ry: OVAL_RY,      role: "crown" },
    { rx: OVAL_RX + 6,  ry: OVAL_RY + 6,  role: "outer_ridge" },
    { rx: OVAL_RX + 11, ry: OVAL_RY + 11, role: "outer_wall" }
  ];

  for (let rObj of rings) {
    let rx = rObj.rx;
    let ry = rObj.ry;
    let role = rObj.role;

    for (let i = 0; i < N_SEG; i++) {
      let a0 = (i / N_SEG) * Math.PI * 2;
      let a1 = ((i + 0.5) / N_SEG) * Math.PI * 2;
      let a2 = ((i + 1.05) / N_SEG) * Math.PI * 2;

      let p0 = [OVAL_CX + Math.cos(a0) * rx, OVAL_CY + Math.sin(a0) * ry, 0.8];
      let p1 = [OVAL_CX + Math.cos(a1) * rx, OVAL_CY + Math.sin(a1) * ry, 1.0];
      let p2 = [OVAL_CX + Math.cos(a2) * rx, OVAL_CY + Math.sin(a2) * ry, 0.8];

      // Outward normal of ellipse at a1
      let nx = Math.cos(a1) / rx;
      let ny = Math.sin(a1) / ry;
      let nLen = Math.sqrt(nx * nx + ny * ny);
      nx /= nLen;
      ny /= nLen;

      // Raking light dot product on outer vs. inner bevel of the oval border
      let outerDot = -(nx * LIGHT_X + ny * LIGHT_Y); // Lit on upper-left outer edge
      let innerDot = -outerDot;                      // Lit on lower-right inner edge

      let col = "#6B351B";
      let w = 0.75;
      let bName = "cpencil";

      if (role === "outer_wall") {
        col = outerDot > 0.2 ? "#1A0702" : "#120400";
        w = 0.9;
        bName = "micro_etch";
      } else if (role === "outer_ridge") {
        if (outerDot > 0.25) {
          col = outerDot > 0.65 ? "#FFFDF9" : "#F6E2CE";
          w = map(outerDot, 0.25, 1.0, 0.7, 1.35);
          bName = "shell_pencil";
        } else {
          col = "#2E1207";
          w = 0.75;
        }
      } else if (role === "crown") {
        col = (outerDot > 0.0) ? "#EED0B5" : "#C48A62";
        w = 0.85;
        bName = "shell_pencil";
      } else if (role === "inner_ridge") {
        if (innerDot > 0.25) {
          col = innerDot > 0.65 ? "#FFFDF9" : "#FAF0E4";
          w = map(innerDot, 0.25, 1.0, 0.75, 1.4);
          bName = "shell_pencil";
        } else {
          col = "#240C04";
          w = 0.85;
        }
      } else if (role === "inner_wall") {
        col = innerDot > 0.2 ? "#5A2913" : "#140501";
        w = 0.95;
        bName = "micro_etch";
      }

      brush.set(bName, col, w);
      brush.spline([p0, p1, p2], 0.45);
    }
  }
}

