// ============================================================================
// MATHEMATICAL & GEOMETRIC HELPERS
// ============================================================================

function evalCubicBezier(p0, p1, p2, p3, t) {
  const u = 1 - t;
  const tt = t * t;
  const uu = u * u;
  const uuu = uu * u;
  const ttt = tt * t;
  return {
    x: uuu * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + ttt * p3.x,
    y: uuu * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + ttt * p3.y
  };
}

function evalCatmullRomChain(pts, t) {
  const n = pts.length - 1;
  const st = constrain(t, 0, 0.999999) * n;
  const i = Math.floor(st);
  const f = st - i;
  const p0 = pts[max(0, i - 1)];
  const p1 = pts[i];
  const p2 = pts[min(n, i + 1)];
  const p3 = pts[min(n, i + 2)];

  const f2 = f * f;
  const f3 = f2 * f;
  return {
    x: 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * f + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * f2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * f3),
    y: 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * f + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * f2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * f3)
  };
}

function curveTangent(pts, t) {
  const eps = 0.002;
  const a = evalCatmullRomChain(pts, max(0, t - eps));
  const b = evalCatmullRomChain(pts, min(1, t + eps));
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = Math.hypot(dx, dy) || 1;
  return { x: dx / len, y: dy / len, angle: atan2(dy, dx) };
}

function makeBeadPolygon(cx, cy, rx, ry, rotDeg, sides = 7, irregularity = 0.08) {
  const pts = [];
  const c = cos(rotDeg);
  const s = sin(rotDeg);
  for (let i = 0; i < sides; i++) {
    const a = (i / sides) * 360;
    const nVal = 1 + (noise(cx * 0.03 + i, cy * 0.03) - 0.5) * irregularity * 2;
    const lx = cos(a) * rx * nVal;
    const ly = sin(a) * ry * nVal;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function drawClosedSplineShape(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

