  brush.rect(55, 55, 1090, 1090, "corner");

  // Corner floral lotus medallions in the 4 corners of the border
  const corners = [
    [42, 42], [1158, 42], [1158, 1158], [42, 1158]
  ];
  for (const [cx, cy] of corners) {
    brush.wash(PAL.saffronGold, 150);
    brush.set("rotring", PAL.inkDeep, 0.38);
    brush.circle(cx, cy, 9, 0.08);
    brush.wash(PAL.madderRed, 170);
    brush.circle(cx, cy, 4.5, 0.05);
  }
  brush.noWash();

  // Running bead resist dots along the madder border
  brush.set("rotring", PAL.resistCream, 0.42);
  for (let d = 64; d <= 1136; d += 18) {
    brush.circle(d, 42, 2.2, 0.05);
    brush.circle(d, 1158, 2.2, 0.05);
    brush.circle(42, d, 2.2, 0.05);
    brush.circle(1158, d, 2.2, 0.05);
  }
}

