function buildChameleonGeometry() {
  // Torso Dorsal Spine (Nape u=0 to Pelvis u=1)
  const dorsalPts = [
    { x: 655, y: 330 },
    { x: 752, y: 382 },
    { x: 836, y: 482 },
    { x: 862, y: 598 },
    { x: 828, y: 718 },
    { x: 765, y: 786 },
    { x: 709, y: 825 }
  ];

  // Torso Ventral Belly Curve (Throat base u=0 to Pelvis u=1)
  const ventralPts = [
    { x: 580, y: 405 },
    { x: 604, y: 485 },
    { x: 614, y: 575 },
    { x: 620, y: 662 },
    { x: 634, y: 736 },
    { x: 655, y: 791 }
  ];

  // Helper to evaluate point on Torso for (u in [0,1], v in [0,1] from ventral to dorsal)
  function evalTorso(u, v) {
    const vp = evalCatmullRomChain(ventralPts, u);
    const dp = evalCatmullRomChain(dorsalPts, u);
    // Slight barrel rib curve
    const ribArc = sin(v * 180) * sin(u * 180) * 14;
    const dx = dp.x - vp.x;
    const dy = dp.y - vp.y;
    const dist = Math.hypot(dx, dy) || 1;
    const tx = -dy / dist;
    const ty = dx / dist;
    return {
      x: lerp(vp.x, dp.x, v) + tx * ribArc * 0.35,
      y: lerp(vp.y, dp.y, v) + ty * ribArc * 0.35,
      span: dist,
      angle: atan2(dy, dx)
    };
  }

  // Prehensile Spiral Tail centerline & half-width for s in [0, 1]
  // Starts seamlessly at pelvis midpoint (682, 808) with width 64px (half-width 32px)
  const spiralCenter = { x: 725, y: 960 };
  const alphaStart = 254.2; // polar angle of (682, 808) from (725, 960)
  const totalTurns = 890;   // ~2.47 full counter-clockwise revolutions

  function evalTail(s) {
    const alpha = alphaStart - totalTurns * Math.pow(s, 0.92);
    // Radius decays smoothly from 158px at s=0 down to 3px at s=1
    const rBase = 158.3 * Math.pow(1 - s, 1.08) + 2.5 * (1 - s);
    // Smooth C1 entry blend near s=0 to match torso tangent
    const entryPull = s * Math.pow(1 - s, 4) * 42;
    const x = spiralCenter.x + rBase * cos(alpha) - entryPull * 0.7;
    const y = spiralCenter.y + rBase * sin(alpha) + entryPull * 0.4;
    const halfW = 31.8 * Math.pow(1 - s, 1.18) + 1.4;
    return { x, y, halfW, alpha };
  }

  function evalTailWithNormal(s) {
    const eps = 0.002;
    const p = evalTail(s);
    const pPrev = evalTail(max(0, s - eps));
    const pNext = evalTail(min(1, s + eps));
    const tx = pNext.x - pPrev.x;
    const ty = pNext.y - pPrev.y;
    const len = Math.hypot(tx, ty) || 1;
    // Normal pointing outward from spiral center ( toward dorsal edge )
    const nx = ty / len;
    const ny = -tx / len;
    return {
      x: p.x,
      y: p.y,
      halfW: p.halfW,
      tx: tx / len,
      ty: ty / len,
      nx,
      ny,
      angle: atan2(ty, tx)
    };
  }

  // Head & Casque (Veil) key landmarks
  const head = {
    snout: { x: 486, y: 312 },
    nasalMid: { x: 535, y: 262 },
    casqueFrontUpper: { x: 598, y: 202 },
    casquePeak: { x: 662, y: 156 },
    casqueBackUpper: { x: 680, y: 218 },
    casqueBackLower: { x: 670, y: 278 },
    nape: { x: 655, y: 330 },
    jawCorner: { x: 612, y: 324 },
    mouthMid: { x: 545, y: 326 },
    chin: { x: 492, y: 325 },
    gularMid: { x: 528, y: 378 },
    throatBase: { x: 580, y: 405 },
    eyeCenter: { x: 568, y: 288, rx: 35, ry: 32 }
  };

  return {
    dorsalPts,
    ventralPts,
    evalTorso,
    evalTail,
    evalTailWithNormal,
    head
  };
}

// ============================================================================
// CHINTZ PATTERN & MORDANT DYE COLOR FUNCTIONS
// ============================================================================

function getTorsoChintzColor(u, v) {
  // Curved rib coordinate so bands follow anatomical ribs
  const uRib = u - 0.08 * sin(v * 180);

  // 4 major vertical leaf-shaped Chintz saddles along torso
  const bandCenters = [0.16, 0.41, 0.65, 0.87];
  let minBandDist = 999;
  let bandIdx = 0;
  for (let i = 0; i < bandCenters.length; i++) {
    const d = Math.abs(uRib - bandCenters[i]);
    if (d < minBandDist) {
      minBandDist = d;
      bandIdx = i;
    }
  }

  // Saddle width narrows near belly and spine (leaf-shaped bar)
  const saddleHalfW = 0.068 * (0.45 + 0.75 * sin(v * 180));

  // Rosette ocelli centers along upper & mid flank
  const ocelli = [
    { u: 0.28, v: 0.55, r: 0.055 },
    { u: 0.53, v: 0.52, r: 0.058 },
    { u: 0.76, v: 0.56, r: 0.052 },
    { u: 0.29, v: 0.26, r: 0.042 },
    { u: 0.53, v: 0.24, r: 0.044 }
  ];
  for (const oc of ocelli) {
    const du = (u - oc.u) * 1.35;
    const dv = (v - oc.v) * 0.65;
    const dist = Math.hypot(du, dv);
    if (dist < oc.r * 0.42) return { col: PAL.saffronBright, op: 195, ring: "core" };
    if (dist < oc.r * 0.72) return { col: PAL.madderRed, op: 190, ring: "mid" };
    if (dist < oc.r) return { col: PAL.indigoDeep, op: 205, ring: "rim" };
  }

  // Inside one of the 4 major vertical Chintz saddles
  if (minBandDist < saddleHalfW) {
    const norm = minBandDist / saddleHalfW;
    if (norm < 0.26) {
      return { col: bandIdx % 2 === 0 ? PAL.saffronGold : PAL.madderBright, op: 190 };
    } else if (norm < 0.56) {
      return { col: bandIdx % 2 === 0 ? PAL.madderRed : PAL.lacPlum, op: 185 };
    } else if (norm < 0.82) {
      return { col: PAL.indigoMid, op: 195 };
    } else {
      return { col: PAL.indigoDeep, op: 215 };
    }
  }

  // Inter-saddle reticulated ground (cool leaf greens, verdigris, indigo & lac)
  const checker = sin(u * 1100) * cos(v * 650);
  if (v > 0.84) {
    return { col: checker > 0 ? PAL.indigoDeep : PAL.lacPlum, op: 195 };
  } else if (v < 0.16) {
    return { col: checker > 0 ? PAL.greenCeladon : PAL.indigoPale, op: 165 };
  } else if (checker > 0.35) {
    return { col: PAL.greenJade, op: 185 };
  } else if (checker > -0.25) {
    return { col: PAL.greenLeaf, op: 175 };
  } else {
    return { col: PAL.indigoBright, op: 180 };
  }
}

function getTailChintzColor(s, vNorm) {
  // 22 rhythmic bands wrapping around the coiled tail
  const bandPos = (s * 22.5) % 1;
  if (bandPos < 0.22) {
    return { col: PAL.indigoDeep, op: 210 };
  } else if (bandPos < 0.38) {
    return { col: vNorm > 0 ? PAL.lacPlum : PAL.indigoMid, op: 190 };
  } else if (bandPos < 0.56) {
    return { col: Math.abs(vNorm) < 0.45 ? PAL.madderRed : PAL.lacMid, op: 190 };
  } else if (bandPos < 0.72) {
    return { col: Math.abs(vNorm) < 0.4 ? PAL.saffronGold : PAL.greenJade, op: 185 };
  } else {
    return { col: vNorm > 0 ? PAL.greenJade : PAL.greenSage, op: 175 };
  }
}

// ============================================================================
// 3 & 4 & 8. POMEGRANATE BRANCHES, LEAVES & BLOSSOMS
// ============================================================================

function drawBackgroundFoliage(branchData) {
  for (const lf of branchData.leaves) {
    if (lf.back) drawChintzLeaf(lf);
  }
}

function drawForegroundFoliageAndFlowers(branchData) {
  for (const lf of branchData.leaves) {
    if (!lf.back) drawChintzLeaf(lf);
  }
  for (const fl of branchData.flowers) {
    drawPomegranateFlower(fl);
  }
}

function drawPomegranateBranches(branchData) {
  // Draw main branch and all secondary twigs
  drawSingleBranchSpline(branchData.mainSpine, true);
  for (const tw of branchData.twigs) {
    drawSingleBranchSpline(tw.pts, false);
  }
}

function drawSingleBranchSpline(spinePts, isMain) {
  const steps = isMain ? 55 : 24;
  const leftEdge = [];
  const rightEdge = [];

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const p = evalCatmullRomChain(spinePts, t);
    const tang = curveTangent(spinePts, t);
    // Interpolate radius
    const idx = constrain(t * (spinePts.length - 1), 0, spinePts.length - 1.001);
    const i0 = Math.floor(idx);
    const r = lerp(spinePts[i0].r, spinePts[min(spinePts.length - 1, i0 + 1)].r, idx - i0);
    // Slight gnarled node swellings
    const nodeSwell = 1 + 0.12 * Math.pow(sin(t * 180 * (isMain ? 6 : 3)), 4);
    const rw = r * nodeSwell;
    const nx = -tang.y;
    const ny = tang.x;
    leftEdge.push([p.x + nx * rw, p.y + ny * rw]);
    rightEdge.unshift([p.x - nx * rw, p.y - ny * rw]);
  }

  const poly = leftEdge.concat(rightEdge);

  // 1. Base warm bark wash
  brush.noStroke();
  brush.wash(PAL.barkLight, 165);
  drawClosedSplineShape(poly, 0.2);

  // 2. Indigo-sepia shaded right side of stem
  const shadowPoly = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const p = evalCatmullRomChain(spinePts, t);
    const tang = curveTangent(spinePts, t);
    const idx = constrain(t * (spinePts.length - 1), 0, spinePts.length - 1.001);
    const i0 = Math.floor(idx);
    const r = lerp(spinePts[i0].r, spinePts[min(spinePts.length - 1, i0 + 1)].r, idx - i0);
    const nx = -tang.y;
    const ny = tang.x;
    shadowPoly.push([p.x - nx * r * 0.1, p.y - ny * r * 0.1]);
  }
  for (let i = 0; i < rightEdge.length; i++) {
    shadowPoly.push(rightEdge[i]);
  }
  brush.wash(PAL.barkMid, 150);
  drawClosedSplineShape(shadowPoly, 0.2);
  brush.noWash();

  // 3. Longitudinal bark texture lines & nodal rings
  brush.set("rotring", PAL.barkDark, 0.3);
  for (let k = -0.55; k <= 0.65; k += 0.4) {
    const linePts = [];
    for (let i = 0; i <= steps; i += 3) {
      const t = i / steps;
      const p = evalCatmullRomChain(spinePts, t);
      const tang = curveTangent(spinePts, t);
      const idx = constrain(t * (spinePts.length - 1), 0, spinePts.length - 1.001);
      const i0 = Math.floor(idx);
      const r = lerp(spinePts[i0].r, spinePts[min(spinePts.length - 1, i0 + 1)].r, idx - i0);
      const nx = -tang.y;
      const ny = tang.x;
      linePts.push([p.x + nx * r * k, p.y + ny * r * k]);
    }
    brush.spline(linePts, 0.3);
  }

  // Crisp Kalam contour outline of the branch
  brush.set("rotring", PAL.inkDeep, isMain ? 0.52 : 0.4);
  drawClosedSplineShape(poly, 0.25);

  // Nodal growth rings along stem
  if (isMain) {
    brush.set("rotring", PAL.inkWarm, 0.35);
    for (let t = 0.12; t < 0.92; t += 0.13) {
      const p = evalCatmullRomChain(spinePts, t);
      const tang = curveTangent(spinePts, t);
      const nx = -tang.y;
      const ny = tang.x;
      const r = lerp(16, 5, t);
      brush.line(p.x - nx * r, p.y - ny * r, p.x + nx * r, p.y + ny * r);
    }
  }
}

function drawChintzLeaf(lf) {
  push();
  translate(lf.x, lf.y);
  rotate(lf.ang);

  const L = lf.len;
  const W = lf.w;

  // Lanceolate leaf contour with slightly wavy chintz margin
  const upperHalf = [
    [0, 0],
    [L * 0.18, -W * 0.42],
    [L * 0.45, -W * 0.54],
    [L * 0.74, -W * 0.38],
    [L * 0.92, -W * 0.14],
    [L, 0]
  ];
  const lowerHalf = [
    [L, 0],
    [L * 0.92, W * 0.14],
    [L * 0.74, W * 0.38],
    [L * 0.45, W * 0.54],
    [L * 0.18, W * 0.42],
    [0, 0]
  ];
  const fullPoly = upperHalf.slice(0, -1).concat(lowerHalf.slice(0, -1));

  // Choose mordant leaf palette
  let topCol = PAL.greenJade;
  let botCol = PAL.greenSage;
  let tipCol = PAL.indigoMid;
  if (lf.type === "indigo") {
    topCol = PAL.indigoDeep;
    botCol = PAL.greenJade;
    tipCol = PAL.indigoBright;
  } else if (lf.type === "cool") {
    topCol = PAL.greenLeaf;
    botCol = PAL.greenCeladon;
    tipCol = PAL.indigoMid;
  } else if (lf.type === "bronze") {
    topCol = PAL.madderCoral;
    botCol = PAL.greenSage;
    tipCol = PAL.saffronGold;
  }

  // Dye washes on upper and lower leaf halves (leaving pale resist midrib!)
  brush.noStroke();
  brush.wash(topCol, 185);
  drawClosedSplineShape(upperHalf, 0.3);

  brush.wash(botCol, 170);
  drawClosedSplineShape(lowerHalf, 0.3);

  // Subtle tip blush wash
  brush.fillBleed(0.2, "in");
  brush.fill(tipCol, 95);
  brush.circle(L * 0.72, 0, W * 0.35, 0.2);
  brush.noFill();
  brush.noWash();

  // Resist midrib line (unbleached cotton / saffron)
  brush.set("kalam", PAL.resistCream, 0.65);
  brush.line(2, 0, L * 0.94, 0);

  // Fine Kalam ink outline and pinnate secondary veins
  brush.set("rotring", PAL.inkDeep, 0.38);
  drawClosedSplineShape(fullPoly, 0.3);
  brush.line(0, 0, L * 0.96, 0);

  brush.set("rotring", PAL.inkWarm, 0.24);
  for (let i = 1; i <= 6; i++) {
    const vx = L * (0.14 * i);
    const vw = W * 0.44 * sin((i / 7) * 180);
    brush.spline([[vx, -0.8], [vx + L * 0.06, -vw * 0.55], [vx + L * 0.11, -vw * 0.88]], 0.35);
    brush.spline([[vx, 0.8],  [vx + L * 0.06,  vw * 0.55], [vx + L * 0.11,  vw * 0.88]], 0.35);
  }

  pop();
}

function drawPomegranateFlower(fl) {
  push();
  translate(fl.x, fl.y);
  rotate(fl.ang);
  scale(fl.scale);

  if (fl.kind === "full") {
    // 1. Crinkled scarlet-madder & lac-rose outer petals fanning out from calyx mouth
    const petalSpecs = [
      { ang: -38, dist: 58, rx: 28, ry: 22, col: PAL.madderRed, vein: PAL.lacDeep },
      { ang: 38,  dist: 58, rx: 28, ry: 22, col: PAL.madderRed, vein: PAL.lacDeep },
      { ang: -18, dist: 68, rx: 32, ry: 25, col: PAL.madderBright, vein: PAL.madderDark },
      { ang: 18,  dist: 68, rx: 32, ry: 25, col: PAL.madderBright, vein: PAL.madderDark },
      { ang: 0,   dist: 74, rx: 34, ry: 27, col: PAL.madderCoral, vein: PAL.madderRed }
    ];

    for (const ps of petalSpecs) {
      push();
      rotate(ps.ang);
      const px = ps.dist;
      const petalPoly = [];
      const nPts = 14;
      for (let i = 0; i < nPts; i++) {
        const a = (i / nPts) * 360;
        // Crinkled ruffled edge
        const ruffle = 1 + 0.14 * sin(a * 5) + 0.07 * cos(a * 8);
        petalPoly.push([px + cos(a) * ps.rx * ruffle, sin(a) * ps.ry * ruffle]);
      }

      brush.noStroke();
      brush.wash(ps.col, 185);
      drawClosedSplineShape(petalPoly, 0.4);

      // Deep lac-purple shadow at petal base
      brush.fillBleed(0.25, "in");
      brush.fill(PAL.lacPlum, 110);
      brush.circle(px - ps.rx * 0.35, 0, ps.ry * 0.55, 0.2);
      brush.noFill();
      brush.noWash();

      // Delicate branching Chintz petal veins
      brush.set("rotring", ps.vein, 0.22);
      for (let v = -3; v <= 3; v++) {
        const va = v * 14;
        brush.spline([
          [px - ps.rx * 0.6, 0],
          [px + cos(va) * ps.rx * 0.1, sin(va) * ps.ry * 0.45],
          [px + cos(va) * ps.rx * 0.78, sin(va) * ps.ry * 0.82]
        ], 0.35);
      }

      // Crisp resist & ink outline on petal
      brush.set("rotring", PAL.inkDeep, 0.34);
      drawClosedSplineShape(petalPoly, 0.4);
      pop();
    }

    // 2. Crown of golden-saffron stamens bursting from the throat
    brush.set("rotring", PAL.madderDark, 0.26);
    for (let i = -11; i <= 11; i++) {
      const sa = i * 3.8;
      const sLen = 46 + (i % 3) * 6;
      const sx = 24 + cos(sa) * sLen;
      const sy = sin(sa) * sLen * 0.65;
      brush.line(26, sy * 0.2, sx, sy);
    }
    brush.set("rotring", PAL.inkDeep, 0.22);
    brush.wash(PAL.saffronBright, 225);
    for (let i = -11; i <= 11; i++) {
      const sa = i * 3.8;
      const sLen = 46 + (i % 3) * 6;
      const sx = 24 + cos(sa) * sLen;
      const sy = sin(sa) * sLen * 0.65;
      brush.circle(sx, sy, 2.6, 0.1);
    }
    brush.noWash();
  } else if (fl.kind === "splitting") {
    // Splitting scarlet petal dome emerging from calyx
    brush.noStroke();
    brush.wash(PAL.madderBright, 200);
    brush.circle(36, 0, 18, 0.15);
    brush.noWash();
    brush.set("rotring", PAL.inkDeep, 0.35);
    brush.circle(36, 0, 18, 0.15);
  }

  // 3. Iconic Leathery Urn-Shaped Pomegranate Calyx (Hypanthium) with pointed lobes
  const calyxPoly = [
    [0, -4],
    [8, -14],
    [18, -22],
    [30, -19],
    [44, -24], // Top sepal lobe tip
    [35, -12],
    [47, -7],  // Upper-mid sepal lobe tip
    [36, 0],
    [47, 7],   // Lower-mid sepal lobe tip
    [35, 12],
    [44, 24],  // Bottom sepal lobe tip
    [30, 19],
    [18, 22],
    [8, 14],
    [0, 4]
  ];

  // Layered mordant dye washes on the leathery urn calyx
  brush.noStroke();
  brush.wash(PAL.madderRed, 205);
  drawClosedSplineShape(calyxPoly, 0.25);

  // Lac-purple base shadow & saffron highlight on the swollen belly of the urn
  brush.fillBleed(0.25, "in");
  brush.fill(PAL.lacDeep, 125);
  brush.circle(14, 5, 13, 0.2);
  brush.fill(PAL.saffronGold, 115);
  brush.circle(22, -7, 10, 0.2);
  brush.noFill();
  brush.noWash();

  // Stippled pore texture & resist highlight on calyx
  brush.set("kalam", PAL.resistCream, 0.45);
  brush.spline([[10, -10], [20, -15], [32, -14]], 0.3);

  brush.set("rotring", PAL.inkDeep, 0.44);
  drawClosedSplineShape(calyxPoly, 0.25);

  // Sepal rib lines
  brush.set("rotring", PAL.madderDark, 0.26);
  brush.spline([[6, 0], [22, -4], [45, -7]], 0.3);
  brush.spline([[6, 0], [22, 4],  [45, 7]],  0.3);

  pop();
}

// ============================================================================
// 5. CHAMELEON BASE WATERCOLOR WASHES (MORDANT DYE UNDERPAINTING)
// ============================================================================

function drawChameleonBaseWashes(bodyData) {
  // Build full torso silhouette polygon
  const torsoPoly = [];
  const N = 40;
  for (let i = 0; i <= N; i++) {
    const p = bodyData.evalTorso(i / N, 1.0);
    torsoPoly.push([p.x, p.y]);
  }
  for (let i = N; i >= 0; i--) {
    const p = bodyData.evalTorso(i / N, 0.0);
    torsoPoly.push([p.x, p.y]);
  }

  // Build full spiral tail silhouette polygon
  const tailOut = [];
  const tailIn = [];
  const TN = 160;
  for (let i = 0; i <= TN; i++) {
    const s = i / TN;
    const tp = bodyData.evalTailWithNormal(s);
    tailOut.push([tp.x + tp.nx * tp.halfW, tp.y + tp.ny * tp.halfW]);
    tailIn.unshift([tp.x - tp.nx * tp.halfW, tp.y - tp.ny * tp.halfW]);
  }
  const tailPoly = tailOut.concat(tailIn);

  // Build head & casque silhouette polygon
  const h = bodyData.head;
  const headPoly = [
    [h.snout.x, h.snout.y],
    [h.nasalMid.x, h.nasalMid.y],
    [h.casqueFrontUpper.x, h.casqueFrontUpper.y],
    [h.casquePeak.x, h.casquePeak.y],
    [h.casqueBackUpper.x, h.casqueBackUpper.y],
    [h.casqueBackLower.x, h.casqueBackLower.y],
    [h.nape.x, h.nape.y],
    [h.throatBase.x, h.throatBase.y],
    [h.gularMid.x, h.gularMid.y],
    [h.chin.x, h.chin.y]
  ];

  // Seal paper beneath chameleon with warm resist cotton tone
  brush.noStroke();
  brush.wash(PAL.resistCream, 235);
  drawClosedSplineShape(torsoPoly, 0.25);
  drawClosedSplineShape(tailPoly, 0.2);
  drawClosedSplineShape(headPoly, 0.25);

  // Luminous transparent watercolor under-washes across torso, tail & casque
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.5, 0.28);

  // Cool verdigris-jade base wash on torso and head
  brush.fill(PAL.greenCeladon, 75);
  drawClosedSplineShape(torsoPoly, 0.25);
  drawClosedSplineShape(headPoly, 0.25);

  // Indigo and lac-purple saddle washes along the arched back
  const saddleUs = [0.16, 0.41, 0.65, 0.87];
  for (let k = 0; k < saddleUs.length; k++) {
    const u0 = saddleUs[k];
    const pMid = bodyData.evalTorso(u0, 0.58);
    brush.fill(k % 2 === 0 ? PAL.indigoMid : PAL.lacPlum, 70);
    brush.circle(pMid.x, pMid.y, 44, 0.25);
  }
  brush.noFill();
  brush.noWash();
}

// ============================================================================
// 6A. HYPERREAL BEAD-SCALE MOSAIC: TORSO
// ============================================================================

function drawTorsoBeadScales(bodyData) {
  const scalesByColor = new Map();
  const ocelliHighlights = [];

  const uCols = 42;
  for (let ic = 0; ic < uCols; ic++) {
    const u = (ic + 0.5) / uCols;
    const sample = bodyData.evalTorso(u, 0.5);
    const vRows = Math.max(12, Math.round(sample.span / 9.2));

    for (let ir = 0; ir < vRows; ir++) {
      // Hexagonal stagger between adjacent columns
      const vOffset = (ic % 2 === 0) ? 0.28 : 0.72;
      const v = (ir + vOffset) / vRows;
      if (v < 0.04 || v > 0.96) continue;

      const pos = bodyData.evalTorso(u, v);
      const dye = getTorsoChintzColor(u, v);

      // Scale bead size varies naturally: larger tubercle plates in rosettes & mid-flank
      let baseR = (sample.span / vRows) * 0.46;
      if (dye.ring === "core") {
        baseR *= 1.25;
        ocelliHighlights.push({ x: pos.x, y: pos.y, r: baseR });
      } else if (dye.ring === "mid") {
        baseR *= 1.12;
      }

      const rx = constrain(baseR * 1.06, 2.6, 6.4);
      const ry = constrain(baseR * 0.92, 2.3, 5.6);

      const poly = makeBeadPolygon(pos.x, pos.y, rx, ry, pos.angle, 7, 0.09);

      if (!scalesByColor.has(dye.col)) {
        scalesByColor.set(dye.col, { op: dye.op, polys: [], centers: [] });
      }
      const group = scalesByColor.get(dye.col);
      group.polys.push(poly);
      group.centers.push({ x: pos.x, y: pos.y, r: rx });
    }
  }

  // Render all torso bead scales batched by mordant dye color!
  // Each bead is flooded with dye and outlined with confident black Kalam ink,
  // leaving a delicate resist line of unbleached cotton between beads.
  brush.set("rotring", PAL.inkDeep, 0.32);
  for (const [col, group] of scalesByColor.entries()) {
    brush.wash(col, group.op);
    for (const poly of group.polys) {
      drawClosedSplineShape(poly, 0.35);
    }
  }
  brush.noWash();

  // Add tiny raised tubercle specular dots on rosette & dorsal scales
  brush.set("kalam", PAL.resistCream, 0.38);
  for (const oh of ocelliHighlights) {
    brush.circle(oh.x - 1.2, oh.y - 1.2, oh.r * 0.28, 0.05);
  }

  // Confident outer torso contour lines
  const dorsalLine = [];
  const ventralLine = [];
  for (let i = 0; i <= 45; i++) {
    const dp = bodyData.evalTorso(i / 45, 1.0);
    const vp = bodyData.evalTorso(i / 45, 0.0);
    dorsalLine.push([dp.x, dp.y]);
    ventralLine.push([vp.x, vp.y]);
  }
  brush.set("rotring", PAL.inkDeep, 0.55);
  brush.spline(dorsalLine, 0.35);
  brush.spline(ventralLine, 0.35);
}

// ============================================================================
// 6B. HYPERREAL BEAD-SCALE MOSAIC: PREHENSILE SPIRAL TAIL
// ============================================================================

function drawTailSpiralBeadScales(bodyData) {
  const scalesByColor = new Map();

  // Step along the spiral arc from s=0 (pelvis) to s=0.985 (coiled tip)
  let s = 0.008;
  let stepIdx = 0;
  while (s < 0.985) {
    const tp = bodyData.evalTailWithNormal(s);
    const fullW = tp.halfW * 2;
    const nRows = Math.max(2, Math.min(8, Math.round(fullW / 8.2)));
    const rowH = fullW / nRows;

    for (let r = 0; r < nRows; r++) {
      const vNorm = -1 + (2 * (r + 0.5)) / nRows; // in [-1, 1]
      const stagger = (r % 2 === 0 ? 0 : 0.0018 * (1 - s * 0.7));
      const tpStag = bodyData.evalTailWithNormal(min(0.99, s + stagger));

      const offset = vNorm * tpStag.halfW * 0.86;
      const cx = tpStag.x + tpStag.nx * offset;
      const cy = tpStag.y + tpStag.ny * offset;

      const rx = constrain(rowH * 0.46, 1.4, 5.2);
      const ry = constrain(rowH * 0.42, 1.3, 4.6);

      const dye = getTailChintzColor(s, vNorm);
      const poly = makeBeadPolygon(cx, cy, rx, ry, tpStag.angle, 6, 0.07);

      if (!scalesByColor.has(dye.col)) {
        scalesByColor.set(dye.col, { op: dye.op, polys: [] });
      }
      scalesByColor.get(dye.col).polys.push(poly);
    }

    // Advance s proportional to scale width so scales remain equidimensional beads
    const ds = constrain((rowH * 0.95) / 1450, 0.0035, 0.014);
    s += ds;
    stepIdx++;
  }

  // Batch render all spiral tail bead scales
  brush.set("rotring", PAL.inkDeep, 0.3);
  for (const [col, group] of scalesByColor.entries()) {
    brush.wash(col, group.op);
    for (const poly of group.polys) {
      drawClosedSplineShape(poly, 0.3);
    }
  }
  brush.noWash();

  // Confident outer and inner spiral ink contours
  const outerSpiral = [];
  const innerSpiral = [];
  const TN = 180;
  for (let i = 0; i <= TN; i++) {
    const tp = bodyData.evalTailWithNormal(i / TN);
    outerSpiral.push([tp.x + tp.nx * tp.halfW, tp.y + tp.ny * tp.halfW]);
    innerSpiral.push([tp.x - tp.nx * tp.halfW, tp.y - tp.ny * tp.halfW]);
  }
  brush.set("rotring", PAL.inkDeep, 0.56);
  brush.spline(outerSpiral, 0.35);
  brush.spline(innerSpiral, 0.35);

  // Center jewel dot at the very tip of the spiral
  const tipP = bodyData.evalTail(0.995);
  brush.wash(PAL.madderRed, 215);
  brush.set("rotring", PAL.inkDeep, 0.4);
  brush.circle(tipP.x, tipP.y, 3.2, 0.08);
  brush.noWash();
}

// ============================================================================
// 6C. HEAD, TALL CASQUE (VEIL), EYE TURRET & SPINE CRESTS
// ============================================================================

function drawHeadAndCasqueScales(bodyData) {
  const h = bodyData.head;
  const scalesByColor = new Map();

  function addHeadScale(cx, cy, rx, ry, ang, col, op) {
    // Skip scales inside the circular eye turret zone (drawn separately in high detail)
    const dex = (cx - h.eyeCenter.x) / (h.eyeCenter.rx + 3);
    const dey = (cy - h.eyeCenter.y) / (h.eyeCenter.ry + 3);
    if (dex * dex + dey * dey < 1.0) return;

    const poly = makeBeadPolygon(cx, cy, rx, ry, ang, 6, 0.08);
    if (!scalesByColor.has(col)) {
      scalesByColor.set(col, { op, polys: [] });
    }
    scalesByColor.get(col).polys.push(poly);
  }

  // 1. Casque (Veil) triangular mosaic between snout/eye-ridge, apex, and occipital back
  const cRows = 18;
  for (let ir = 0; ir < cRows; ir++) {
    const t = (ir + 0.5) / cRows; // 0 = base near eye/jaw, 1 = apex (662, 156)
    // Front edge point along nasal/parietal crest
    const pFront = evalCubicBezier(
      h.snout,
      h.nasalMid,
      h.casqueFrontUpper,
      h.casquePeak,
      t
    );
    // Back edge point along occipital curve
    const pBack = evalCubicBezier(
      h.nape,
      h.casqueBackLower,
      h.casqueBackUpper,
      h.casquePeak,
      t
    );

    const span = Math.hypot(pBack.x - pFront.x, pBack.y - pFront.y);
    const cols = Math.max(2, Math.round(span / 9.5));
    const rowAng = atan2(pBack.y - pFront.y, pBack.x - pFront.x);

    for (let ic = 0; ic < cols; ic++) {
      const s = (ic + 0.5) / cols;
      const cx = lerp(pFront.x, pBack.x, s);
      const cy = lerp(pFront.y, pBack.y, s);

      // Ornate Chintz casque banding (diagonal indigo, lac purple, saffron & madder bars)
      const bandVal = sin((t * 5 + s * 3) * 180);
      let col = PAL.greenJade;
      let op = 185;
      if (s < 0.16 || s > 0.86) {
        col = ic % 2 === 0 ? PAL.saffronGold : PAL.indigoDeep;
        op = 205;
      } else if (bandVal > 0.45) {
        col = PAL.madderRed;
        op = 195;
      } else if (bandVal > 0.0) {
        col = PAL.saffronGold;
        op = 190;
      } else if (bandVal > -0.45) {
        col = PAL.lacPlum;
        op = 190;
      } else {
        col = PAL.indigoMid;
        op = 195;
      }

      const rx = constrain((span / cols) * 0.46, 2.8, 6.2);
      const ry = constrain(rx * 0.85, 2.5, 5.2);
      addHeadScale(cx, cy, rx, ry, rowAng, col, op);
    }
  }

  // 2. Lower Jaw & Gular Throat Pouch scales
  const gRows = 8;
  for (let ir = 0; ir < gRows; ir++) {
    const v = (ir + 0.5) / gRows;
    const gCols = 14 - Math.floor(v * 4);
    for (let ic = 0; ic < gCols; ic++) {
      const u = (ic + 0.5) / gCols;
      const topP = evalCubicBezier(h.snout, h.mouthMid, h.jawCorner, h.nape, u * 0.85);
      const botP = evalCubicBezier(h.chin, h.gularMid, { x: 558, y: 396 }, h.throatBase, u);

      const cx = lerp(topP.x, botP.x, v);
      const cy = lerp(topP.y, botP.y, v);

      // Diagonal throat stripes in madder red, saffron, indigo & jade
      const stripe = (ic + ir) % 4;
      const col = stripe === 0 ? PAL.indigoDeep
                : stripe === 1 ? PAL.madderRed
                : stripe === 2 ? PAL.saffronGold
                : PAL.greenLeaf;

      addHeadScale(cx, cy, 4.4, 3.6, 28, col, 190);
    }
  }

  // Render head & casque scales batched by color
  brush.set("rotring", PAL.inkDeep, 0.32);
  for (const [col, group] of scalesByColor.entries()) {
    brush.wash(col, group.op);
    for (const poly of group.polys) {
      drawClosedSplineShape(poly, 0.35);
    }
  }
  brush.noWash();

  // Confident Kalam outlines for casque crest ridges & mouth line
  brush.set("rotring", PAL.inkDeep, 0.58);
  // Parietal front ridge
  brush.spline([
    [h.snout.x, h.snout.y],
    [h.nasalMid.x, h.nasalMid.y],
    [h.casqueFrontUpper.x, h.casqueFrontUpper.y],
    [h.casquePeak.x, h.casquePeak.y]
  ], 0.35);
  // Occipital back ridge
  brush.spline([
    [h.casquePeak.x, h.casquePeak.y],
    [h.casqueBackUpper.x, h.casqueBackUpper.y],
    [h.casqueBackLower.x, h.casqueBackLower.y],
    [h.nape.x, h.nape.y]
  ], 0.35);
  // Lateral casque ridge
  brush.set("rotring", PAL.inkDeep, 0.45);
  brush.spline([
    [536, 268],
    [588, 232],
    [635, 195],
    [h.casquePeak.x, h.casquePeak.y]
  ], 0.35);

  // Mouth line (rictus) with serrated labial scales
  brush.set("rotring", PAL.inkDeep, 0.65);
  brush.spline([
    [h.snout.x, h.snout.y],
    [h.mouthMid.x, h.mouthMid.y],
    [h.jawCorner.x, h.jawCorner.y]
  ], 0.3);

  // Labial bead row along upper & lower lip
  const labialCols = [PAL.saffronBright, PAL.madderRed, PAL.indigoMid];
  brush.set("rotring", PAL.inkDeep, 0.3);
  for (let i = 0; i < 13; i++) {
    const t = i / 12;
    const mp = evalCubicBezier(h.snout, h.mouthMid, { x: 582, y: 325 }, h.jawCorner, t);
    brush.wash(labialCols[i % 3], 210);
    brush.circle(mp.x, mp.y - 3.2, 2.8, 0.08);
    brush.circle(mp.x + 1, mp.y + 3.2, 2.6, 0.08);
  }
  brush.noWash();
}

function drawEyeTurret(bodyData) {
  const ec = bodyData.head.eyeCenter;

  // Base cream resist circle for eye turret
  brush.noStroke();
  brush.wash(PAL.resistCream, 245);
  brush.circle(ec.x, ec.y, ec.rx + 2, 0.08);
  brush.noWash();

  // 4 concentric rings of bead scales arranged in 18 radial Chintz sectors
  const rings = [
    { r: 32, beadR: 4.5, sectors: 20 },
    { r: 24, beadR: 3.8, sectors: 18 },
    { r: 17, beadR: 3.1, sectors: 16 },
    { r: 11, beadR: 2.3, sectors: 14 }
  ];

  const sectorPalette = [
    PAL.indigoDeep, PAL.saffronGold, PAL.madderRed,
    PAL.greenJade,  PAL.lacPlum,     PAL.saffronBright
  ];

  const turretBatches = new Map();
  for (const col of sectorPalette) turretBatches.set(col, []);

  for (const rg of rings) {
    for (let s = 0; s < rg.sectors; s++) {
      const ang = (s / rg.sectors) * 360;
      const bx = ec.x + cos(ang) * rg.r;
      const by = ec.y + sin(ang) * (rg.r * 0.92);
      const col = sectorPalette[s % sectorPalette.length];
      const poly = makeBeadPolygon(bx, by, rg.beadR, rg.beadR * 0.85, ang + 90, 6, 0.06);
      turretBatches.get(col).push(poly);
    }
  }

  brush.set("rotring", PAL.inkDeep, 0.3);
  for (const [col, polys] of turretBatches.entries()) {
    brush.wash(col, 205);
    for (const poly of polys) {
      drawClosedSplineShape(poly, 0.3);
    }
  }

  // Outer turret rim outline
  brush.noWash();
  brush.set("rotring", PAL.inkDeep, 0.5);
  brush.circle(ec.x, ec.y, ec.rx + 2, 0.08);

  // Central eyelid aperture, golden-saffron iris & deep onyx pupil
  brush.wash(PAL.saffronBright, 240);
  brush.set("rotring", PAL.inkDeep, 0.45);
  brush.circle(ec.x - 1, ec.y, 7.8, 0.05);

  brush.wash(PAL.madderRed, 210);
  brush.circle(ec.x - 1, ec.y, 5.8, 0.05);

  brush.wash(PAL.inkDeep, 250);
  brush.circle(ec.x - 1, ec.y, 3.8, 0.03);
  brush.noWash();

  // Crisp glazed white catchlight on eye
  brush.noStroke();
  brush.wash(PAL.cottonSheen, 250);
  brush.circle(ec.x - 2.6, ec.y - 1.8, 1.6, 0.02);
  brush.noWash();
}

function drawCrestsAndSpines(bodyData) {
  const spineColors = [PAL.indigoDeep, PAL.saffronGold, PAL.madderRed, PAL.lacPlum];

  // 1. Dorsal Crest conical spines along the arched back (u from 0.02 to 0.98)
  brush.set("rotring", PAL.inkDeep, 0.36);
  const nDorsal = 34;
  for (let i = 0; i < nDorsal; i++) {
    const u = 0.02 + (i / nDorsal) * 0.96;
    const p = bodyData.evalTorso(u, 1.0);
    const pNext = bodyData.evalTorso(min(1, u + 0.015), 1.0);
    const tx = pNext.x - p.x;
    const ty = pNext.y - p.y;
    const len = Math.hypot(tx, ty) || 1;
    // Outward normal
    const nx = ty / len;
    const ny = -tx / len;

    const spineH = (9.5 - u * 4.2) * (i % 2 === 0 ? 1.15 : 0.85);
    const baseHalf = 3.8 - u * 1.2;

    const poly = [
      [p.x - (tx / len) * baseHalf, p.y - (ty / len) * baseHalf],
      [p.x + nx * spineH + (tx / len) * 1.5, p.y + ny * spineH + (ty / len) * 1.5],
      [p.x + (tx / len) * baseHalf, p.y + (ty / len) * baseHalf]
    ];

    brush.wash(spineColors[i % spineColors.length], 215);
    drawClosedSplineShape(poly, 0.15);
  }

  // Smaller dorsal serrulations continuing along the outer spiral tail
  for (let i = 0; i < 28; i++) {
    const s = 0.02 + (i / 28) * 0.55;
    const tp = bodyData.evalTailWithNormal(s);
    const bx = tp.x + tp.nx * tp.halfW;
    const by = tp.y + tp.ny * tp.halfW;
    const spineH = 5.2 * (1 - s * 1.3);
    const poly = [
      [bx - tp.tx * 2.5, by - tp.ty * 2.5],
      [bx + tp.nx * spineH, by + tp.ny * spineH],
      [bx + tp.tx * 2.5, by + tp.ty * 2.5]
    ];
    brush.wash(spineColors[i % spineColors.length], 205);
    drawClosedSplineShape(poly, 0.15);
  }

  // 2. Gular (throat) conical spines along lower jaw pouch
  const h = bodyData.head;
  const nGular = 15;
  for (let i = 0; i < nGular; i++) {
    const t = 0.08 + (i / nGular) * 0.86;
    const gp = evalCubicBezier(h.chin, h.gularMid, { x: 558, y: 396 }, h.throatBase, t);
    const ang = 135 - t * 25;
    const spineLen = 11.5 * sin(t * 180) + 3.5;
    const poly = [
      [gp.x - 2.8, gp.y - 2.2],
      [gp.x + cos(ang) * spineLen, gp.y + sin(ang) * spineLen],
      [gp.x + 2.8, gp.y + 2.2]
    ];
    brush.wash(spineColors[(i + 1) % spineColors.length], 215);
    drawClosedSplineShape(poly, 0.12);
  }

  // 3. Ventral (belly) saw-tooth fringe
  const nVentral = 24;
  for (let i = 0; i < nVentral; i++) {
    const u = 0.05 + (i / nVentral) * 0.88;
    const vp = bodyData.evalTorso(u, 0.0);
    const poly = [
      [vp.x - 1, vp.y - 3],
      [vp.x - 6.5, vp.y + 1.5],
      [vp.x + 1, vp.y + 3]
    ];
    brush.wash(i % 2 === 0 ? PAL.saffronBright : PAL.indigoMid, 200);
    drawClosedSplineShape(poly, 0.12);
  }
  brush.noWash();
}

