function drawScaledLimbSegment(jointA, jointB, jointC, isBack) {
  const segs = [
    [jointA, jointB],
    [jointB, jointC]
  ];

  const limbPalette = isBack
    ? [PAL.indigoDeep, PAL.greenDeep, PAL.lacDeep]
    : [PAL.greenJade, PAL.indigoMid, PAL.madderRed, PAL.saffronGold, PAL.lacPlum];

  for (let sIdx = 0; sIdx < segs.length; sIdx++) {
    const [p0, p1] = segs[sIdx];
    const dx = p1.x - p0.x;
    const dy = p1.y - p0.y;
    const len = Math.hypot(dx, dy) || 1;
    const tx = dx / len;
    const ty = dy / len;
    const nx = -ty;
    const ny = tx;
    const ang = atan2(dy, dx);

    // Base resist & dye wash under segment
    const poly = [
      [p0.x + nx * p0.r, p0.y + ny * p0.r],
      [p1.x + nx * p1.r, p1.y + ny * p1.r],
      [p1.x - nx * p1.r, p1.y - ny * p1.r],
      [p0.x - nx * p0.r, p0.y - ny * p0.r]
    ];
    brush.noStroke();
    brush.wash(PAL.resistCream, 235);
    drawClosedSplineShape(poly, 0.25);

    // Bead scales along the limb segment
    const cols = Math.round(len / 7.5);
    const scaleGroups = new Map();
    for (const c of limbPalette) scaleGroups.set(c, []);

    for (let ic = 0; ic <= cols; ic++) {
      const u = ic / cols;
      const cxBase = lerp(p0.x, p1.x, u);
      const cyBase = lerp(p0.y, p1.y, u);
      const rSpan = lerp(p0.r, p1.r, u);
      const rows = Math.max(3, Math.round((rSpan * 2) / 7.2));

      for (let ir = 0; ir < rows; ir++) {
        const v = -0.82 + (1.64 * (ir + 0.5)) / rows;
        const cx = cxBase + nx * rSpan * v;
        const cy = cyBase + ny * rSpan * v;
        const col = limbPalette[(ic + ir + sIdx * 2) % limbPalette.length];
        const bead = makeBeadPolygon(cx, cy, 3.8, 3.2, ang, 6, 0.08);
        scaleGroups.get(col).push(bead);
      }
    }

    brush.set("rotring", PAL.inkDeep, 0.3);
    for (const [col, beads] of scaleGroups.entries()) {
      brush.wash(col, isBack ? 215 : 195);
      for (const b of beads) {
        drawClosedSplineShape(b, 0.3);
      }
    }
    brush.noWash();

    // Crisp limb segment outline
    brush.set("rotring", PAL.inkDeep, 0.48);
    drawClosedSplineShape(poly, 0.28);
  }
}

function drawZygodactylousHand(wx, wy, dirDeg, sc) {
  push();
  translate(wx, wy);
  rotate(dirDeg);
  scale(sc);

  // Two opposing fused digit bundles (tongs-like chameleon grip over the branch)
  const digitSpecs = [
    { yOff: -6, len: 24, curve: -8, col: PAL.saffronGold },
    { yOff: -1, len: 27, curve: -4, col: PAL.madderRed },
    { yOff:  5, len: 23, curve:  6, col: PAL.greenJade }
  ];

  for (const d of digitSpecs) {
    const pts = [
      [0, d.yOff - 3.5],
      [d.len * 0.55, d.yOff + d.curve * 0.5 - 3],
      [d.len, d.yOff + d.curve],
      [d.len * 0.55, d.yOff + d.curve * 0.5 + 3],
      [0, d.yOff + 3.5]
    ];

    brush.wash(d.col, 205);
    brush.set("rotring", PAL.inkDeep, 0.38);
    drawClosedSplineShape(pts, 0.3);

    // Bead scale segments along digit
    for (let k = 1; k <= 3; k++) {
      const fx = (d.len * k) / 4;
      const fy = d.yOff + (d.curve * k) / 4;
      brush.wash(k % 2 === 0 ? PAL.indigoMid : d.col, 200);
      brush.circle(fx, fy, 2.8, 0.08);
    }

    // Sharp curved claw gripping the bark
    const tipX = d.len;
    const tipY = d.yOff + d.curve;
    brush.wash(PAL.saffronPale, 235);
    brush.set("rotring", PAL.inkDeep, 0.42);
    drawClosedSplineShape([
      [tipX - 1, tipY - 2.2],
      [tipX + 7.5, tipY + 3.5],
      [tipX - 1, tipY + 2.2]
    ], 0.15);
  }
  brush.noWash();
  pop();
}

