function drawGlazedSheenAndFinalInk(bodyData) {
  // Subtle glazed specular highlights along the high arch of the back, casque & tail coil
  brush.noStroke();
  brush.fillBleed(0.18, "out");

  for (let u = 0.15; u <= 0.85; u += 0.14) {
