  // Glazed highlight on the coiled tail
  for (let s = 0.08; s <= 0.72; s += 0.12) {
    const tp = bodyData.evalTail(s);
    brush.fill(PAL.cottonSheen, 28);
    brush.circle(tp.x, tp.y, tp.halfW * 0.75, 0.2);
  }
  brush.noFill();

  // Delicate Kalamkari botanical corner scroll accents inside the frame corners
  const scrollPts = [
    { x: 88, y: 88, sx: 1, sy: 1 },
    { x: 1112, y: 88, sx: -1, sy: 1 },
    { x: 1112, y: 1112, sx: -1, sy: -1 },
    { x: 88, y: 1112, sx: 1, sy: -1 }
