    brush.set("rotring", PAL.indigoMid, 0.32);
    brush.spline([[0, 42], [6, 14], [14, 6], [42, 0]], 0.4);
    brush.wash(PAL.madderRed, 165);
    brush.circle(16, 16, 4.5, 0.08);
    brush.wash(PAL.saffronGold, 175);
    brush.circle(8, 28, 3.0, 0.08);
    brush.circle(28, 8, 3.0, 0.08);
    brush.noWash();
    pop();
  }
}

