// =============================================================================
// PRIMITIVE HELPERS (Pure p5.brush)
// =============================================================================

function polyWash(pts, col, alpha = 255) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  brush.noWash();
}

function rectWash(x, y, w, h, col, alpha = 255) {
  polyWash([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], col, alpha);
}

function polyStroke(pts, brushName = "techpen", col = PAL.chromeBlack, weight = 0.8, closed = true) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noFill();
  brush.noHatch();
  brush.set(brushName, col, weight);
  let n = pts.length;
  let limit = closed ? n : n - 1;
  for (let i = 0; i < limit; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.noStroke();
}

function rectStroke(x, y, w, h, brushName = "techpen", col = PAL.chromeBlack, weight = 0.8) {
  polyStroke([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], brushName, col, weight, true);
}

function polyWashStroke(pts, washCol, washAlpha, brushName = "techpen", strokeCol = PAL.chromeBlack, weight = 0.8) {
  polyWash(pts, washCol, washAlpha);
  if (brushName && strokeCol) {
    polyStroke(pts, brushName, strokeCol, weight, true);
  }
}

function rectWashStroke(x, y, w, h, washCol, washAlpha, brushName = "techpen", strokeCol = PAL.chromeBlack, weight = 0.8) {
  let pts = [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
  polyWashStroke(pts, washCol, washAlpha, brushName, strokeCol, weight);
}

function polyHatch(pts, brushName, col, weight, dist, angle, rand = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist, angle, { rand: rand });
  brush.noHatch();
}

function ruledLine(x1, y1, x2, y2, col = PAL.chromeBlack, weight = 0.8, brushName = "techpen") {
  brush.noWash();
  brush.noFill();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
  brush.noStroke();
}

function ellipsePts(cx, cy, rx, ry, segs = 36) {
  let pts = [];
  for (let i = 0; i < segs; i++) {
    let a = (i / segs) * 360;
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  return pts;
}

function ellipseWashStroke(cx, cy, rx, ry, washCol, washAlpha, brushName = "techpen", strokeCol = PAL.chromeBlack, weight = 0.8, segs = 36) {
  let pts = ellipsePts(cx, cy, rx, ry, segs);
  if (washCol) polyWash(pts, washCol, washAlpha);
  if (brushName && strokeCol) polyStroke(pts, brushName, strokeCol, weight, true);
}

function ringSectorPts(cx, cy, rxIn, ryIn, rxOut, ryOut, aStart, aEnd, steps = 10) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rxOut, cy + sin(a) * ryOut]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rxIn, cy + sin(a) * ryIn]);
  }
  return pts;
}

function drawChromeRing(cx, cy, rxIn, ryIn, rxOut, ryOut, alphaScale = 1.0, segs = 36) {
  // 8-sector photorealist metallic reflection ring
  const sectors = [
    { a0: -150, a1: -95,  col: PAL.white },
    { a0: -95,  a1: -35,  col: PAL.skyBright },
    { a0: -35,  a1: 15,   col: PAL.chromeDark },
    { a0: 15,   a1: 65,   col: PAL.tangBright },
    { a0: 65,   a1: 115,  col: PAL.chromeLight },
    { a0: 115,  a1: 155,  col: PAL.chromeBlack },
    { a0: 155,  a1: 195,  col: PAL.mintBright },
    { a0: 195,  a1: 210,  col: PAL.chromeSilver }
  ];
  for (let s of sectors) {
    let pts = ringSectorPts(cx, cy, rxIn, ryIn, rxOut, ryOut, s.a0, s.a1, 7);
    polyWash(pts, s.col, Math.round(245 * alphaScale));
  }
  polyStroke(ellipsePts(cx, cy, rxOut, ryOut, segs), "techpen", PAL.chromeBlack, 0.85, true);
  polyStroke(ellipsePts(cx, cy, rxIn, ryIn, segs), "techpen", PAL.chromeBlack, 0.75, true);
}

