// Geometric 1970s Architectural Block Font Renderer
function drawSignText(str, startX, startY, h, w, gap, fillCol, shadowCol, extrude = 3) {
  let x = startX;
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    if (ch !== " ") {
      // 3D drop shadow
      if (shadowCol) {
        drawGlyph(ch, x + extrude, startY + extrude, w, h, shadowCol, null);
      }
      // Main letter face with ruled pen outline
      drawGlyph(ch, x, startY, w, h, fillCol, PAL.chromeBlack);
    }
    x += w + gap;
  }
}

function drawGlyph(ch, x, y, w, h, fillCol, strokeCol) {
  let t = Math.max(3, w * 0.24); // stroke thickness of block letter
  let bars = [];
  const B = (bx, by, bw, bh) => bars.push([x + bx * w, y + by * h, bw * w, bh * h]);

  switch (ch) {
    case "A":
      B(0, 0, 1, 0.22); B(0, 0, 0.26, 1); B(0.74, 0, 0.26, 1); B(0, 0.44, 1, 0.2);
      break;
    case "B":
      B(0, 0, 0.26, 1); B(0, 0, 0.88, 0.2); B(0, 0.4, 0.88, 0.2); B(0, 0.8, 0.92, 0.2);
      B(0.72, 0.12, 0.24, 0.32); B(0.74, 0.54, 0.26, 0.34);
      break;
    case "C":
      B(0, 0, 1, 0.22); B(0, 0, 0.27, 1); B(0, 0.78, 1, 0.22);
      break;
    case "D":
      B(0, 0, 0.27, 1); B(0, 0, 0.82, 0.22); B(0, 0.78, 0.82, 0.22); B(0.73, 0.14, 0.27, 0.72);
      break;
    case "E":
      B(0, 0, 0.27, 1); B(0, 0, 1, 0.22); B(0, 0.4, 0.82, 0.2); B(0, 0.78, 1, 0.22);
      break;
    case "F":
      B(0, 0, 0.27, 1); B(0, 0, 1, 0.22); B(0, 0.42, 0.8, 0.2);
      break;
    case "H":
      B(0, 0, 0.27, 1); B(0.73, 0, 0.27, 1); B(0, 0.4, 1, 0.22);
      break;
    case "I":
      B(0.15, 0, 0.7, 0.22); B(0.36, 0, 0.28, 1); B(0.15, 0.78, 0.7, 0.22);
      break;
    case "L":
      B(0, 0, 0.28, 1); B(0, 0.78, 1, 0.22);
      break;
    case "M":
      B(0, 0, 0.24, 1); B(0.76, 0, 0.24, 1); B(0.2, 0.08, 0.22, 0.45); B(0.58, 0.08, 0.22, 0.45); B(0.39, 0.32, 0.22, 0.45);
      break;
    case "N":
      B(0, 0, 0.26, 1); B(0.74, 0, 0.26, 1); B(0.22, 0.15, 0.28, 0.4); B(0.48, 0.45, 0.28, 0.4);
      break;
    case "O":
    case "0":
      B(0, 0, 1, 0.22); B(0, 0.78, 1, 0.22); B(0, 0, 0.27, 1); B(0.73, 0, 0.27, 1);
      break;
    case "P":
      B(0, 0, 0.27, 1); B(0, 0, 0.95, 0.22); B(0, 0.44, 0.95, 0.2); B(0.73, 0, 0.27, 0.62);
      break;
    case "R":
      B(0, 0, 0.27, 1); B(0, 0, 0.92, 0.22); B(0, 0.42, 0.92, 0.2); B(0.72, 0, 0.26, 0.56); B(0.58, 0.56, 0.38, 0.44);
      break;
    case "S":
      B(0, 0, 1, 0.22); B(0, 0, 0.27, 0.55); B(0, 0.4, 1, 0.2); B(0.73, 0.45, 0.27, 0.55); B(0, 0.78, 1, 0.22);
      break;
    case "T":
      B(0, 0, 1, 0.22); B(0.36, 0, 0.28, 1);
      break;
    case "U":
      B(0, 0, 0.27, 1); B(0.73, 0, 0.27, 1); B(0, 0.78, 1, 0.22);
      break;
    case "V":
      B(0, 0, 0.27, 0.72); B(0.73, 0, 0.27, 0.72); B(0.2, 0.65, 0.6, 0.35);
      break;
    case "W":
      B(0, 0, 0.23, 1); B(0.77, 0, 0.23, 1); B(0.38, 0.35, 0.24, 0.65); B(0, 0.78, 1, 0.22);
      break;
    case "Y":
      B(0, 0, 0.27, 0.5); B(0.73, 0, 0.27, 0.5); B(0.2, 0.4, 0.6, 0.2); B(0.36, 0.45, 0.28, 0.55);
      break;
    case "2":
      B(0, 0, 1, 0.22); B(0.73, 0, 0.27, 0.55); B(0, 0.4, 1, 0.2); B(0, 0.45, 0.27, 0.55); B(0, 0.78, 1, 0.22);
      break;
    case "4":
      B(0, 0, 0.26, 0.58); B(0, 0.42, 1, 0.2); B(0.68, 0, 0.26, 1);
      break;
    case "-":
      B(0.15, 0.42, 0.7, 0.2);
      break;
    default:
      B(0.1, 0.1, 0.8, 0.8);
  }
  for (let b of bars) {
    rectWash(b[0], b[1], b[2], b[3], fillCol, 255);
    if (strokeCol) rectStroke(b[0], b[1], b[2], b[3], "techpen", strokeCol, 0.55);
  }
}

