function drawPerspectiveLeftWasher(cx, cy, w, h, hoodCol) {
  let x = cx - w * 0.5;
  let y = cy - h * 0.5;
  let depthW = w * 0.42;

  // Visible front-left cabinet return panel
  polyWashStroke(
    [[x - depthW, y + 8], [x, y], [x, y + h], [x - depthW, y + h + 8]],
    PAL.chromeMid, 255, "techpen", PAL.chromeBlack, 0.8
  );
  polyWash([[x - depthW, y + 8], [x, y], [x, y + h * 0.22], [x - depthW, y + h * 0.22 + 8]], hoodCol, 255);

  // Foreshortened stainless front face
  polyWashStroke(
    [[x, y], [x + w * 0.65, y - 8], [x + w * 0.65, y + h - 10], [x, y + h]],
    PAL.chromeLight, 255, "techpen", PAL.chromeBlack, 0.85
  );
  // Slanted control hood
  polyWashStroke(
    [[x, y], [x + w * 0.65, y - 8], [x + w * 0.65, y + h * 0.19 - 8], [x, y + h * 0.19]],
    hoodCol, 255, "techpen", PAL.chromeBlack, 0.8
  );
  // Dark toe kick
  polyWashStroke(
    [[x, y + h * 0.86], [x + w * 0.65, y + h * 0.86 - 9], [x + w * 0.65, y + h - 10], [x, y + h]],
    PAL.chromeBlack, 255, "techpen", PAL.chromeBlack, 0.75
  );

  // Elliptical foreshortened chrome porthole door
  let dcx = x + w * 0.34;
  let dcy = y + h * 0.52;
  let rx = w * 0.23;
  let ry = h * 0.24;
  drawChromeRing(dcx, dcy, rx * 0.66, ry * 0.66, rx, ry, 1.0, 28);
  ellipseWashStroke(dcx, dcy, rx * 0.65, ry * 0.65, PAL.chromeBlack, 255, "techpen", PAL.chromeBlack, 0.7, 24);
  polyWash(ringSectorPts(dcx, dcy, 0, 0, rx * 0.6, ry * 0.6, 15, 165, 8), PAL.skyVivid, 230);
  // White glass bowl highlight
  polyWash(ringSectorPts(dcx, dcy, rx * 0.35, ry * 0.35, rx * 0.55, ry * 0.55, -145, -55, 6), PAL.white, 240);
}

function drawFrontFacingWasher(x, y, w, h, hoodCol, waterCol, seedIdx) {
  // 1. Recessed black toe-kick base
  rectWashStroke(x + 2, y + h * 0.87, w - 4, h * 0.13, PAL.chromeBlack, 255, "techpen", PAL.chromeBlack, 0.85);
  rectWash(x + 8, y + h * 0.9, w * 0.35, h * 0.05, PAL.chromeMid, 210);

  // 2. Main Brushed Chrome Cabinet Body
  rectWashStroke(x, y + h * 0.21, w, h * 0.67, PAL.chromeLight, 255, "techpen", PAL.chromeBlack, 0.95);

  // Vertical metallic specular bands across the stainless steel front
  rectWash(x + w * 0.04, y + h * 0.21, w * 0.14, h * 0.67, PAL.white, 235);
  rectWash(x + w * 0.18, y + h * 0.21, w * 0.12, h * 0.67, PAL.skyPale, 190);
  rectWash(x + w * 0.56, y + h * 0.21, w * 0.16, h * 0.67, PAL.chromeMid, 195);
  rectWash(x + w * 0.72, y + h * 0.21, w * 0.12, h * 0.67, PAL.chromeGleam, 230);
  rectWash(x + w * 0.84, y + h * 0.21, w * 0.14, h * 0.67, PAL.chromeDark, 185);

  // Lower service panel seam line
  let seamY = y + h * 0.74;
  ruledLine(x, seamY, x + w, seamY, PAL.chromeBlack, 0.9);
  ruledLine(x, seamY + 2, x + w, seamY + 2, PAL.white, 0.8);

  // 3. Upper Enamel Control Console (Tangerine or Mint)
  rectWashStroke(x, y, w, h * 0.21, hoodCol, 255, "techpen", PAL.chromeBlack, 0.95);
  // Slanted top bevel catching fluorescent light
  polyWashStroke(
    [[x, y], [x + w, y], [x + w - 4, y + h * 0.06], [x + 4, y + h * 0.06]],
    (hoodCol === PAL.tangVivid) ? PAL.tangLight : PAL.mintLight,
    245, "techpen", PAL.chromeBlack, 0.7
  );
  // Chrome trim molding strip under console
  rectWashStroke(x, y + h * 0.185, w, h * 0.03, PAL.white, 255, "techpen", PAL.chromeBlack, 0.75);

  // Control Dials, Coin Slide & Indicator Light
  let dialY = y + h * 0.125;
  let dialR = Math.max(3.5, w * 0.055);
  for (let d = 0; d < 2; d++) {
    let dx = x + w * (0.2 + d * 0.16);
    ellipseWashStroke(dx, dialY, dialR, dialR, PAL.white, 255, "techpen", PAL.chromeBlack, 0.7, 16);
    ellipseWashStroke(dx, dialY, dialR * 0.5, dialR * 0.5, PAL.chromeBlack, 255, "techpen", PAL.chromeBlack, 0.5, 12);
  }
  // Chrome coin-slot box on right of console
  rectWashStroke(x + w * 0.64, y + h * 0.075, w * 0.26, h * 0.095, PAL.chromeLight, 255, "techpen", PAL.chromeBlack, 0.75);
  rectWash(x + w * 0.66, y + h * 0.085, w * 0.1, h * 0.07, PAL.chromeBlack, 255);
  // Glowing cycle indicator jewel
  ellipseWashStroke(x + w * 0.52, dialY, dialR * 0.6, dialR * 0.6, PAL.tangGold, 255, "techpen", PAL.chromeBlack, 0.55, 12);

  // 4. THE GLEAMING CHROME PORTHOLE DOOR
  let cx = x + w * 0.5;
  let cy = y + h * 0.48;
  let rOut = w * 0.37;
  let rMid = w * 0.29;
  let rIn  = w * 0.245;

  // Cast shadow beneath chrome bezel
  ellipseWashStroke(cx + 2, cy + 4, rOut, rOut, PAL.chromeBlack, 195, null, null, 0, 32);

  // Outer multi-faceted chrome bezel
  drawChromeRing(cx, cy, rMid, rMid, rOut, rOut, 1.0, 36);

  // Inner recessed stainless lip
  drawChromeRing(cx, cy, rIn, rIn, rMid, rMid, 0.95, 32);

  // Heavy chrome hinge on left & latch handle on right
  rectWashStroke(cx - rOut - w * 0.05, cy - h * 0.05, w * 0.07, h * 0.1, PAL.chromeLight, 255, "techpen", PAL.chromeBlack, 0.8);
  rectWash(cx - rOut - w * 0.04, cy - h * 0.04, w * 0.05, h * 0.03, PAL.white, 255);
  rectWashStroke(cx + rOut - w * 0.02, cy - h * 0.035, w * 0.08, h * 0.07, PAL.white, 255, "techpen", PAL.chromeBlack, 0.85);
  rectWash(cx + rOut - w * 0.02, cy + h * 0.005, w * 0.08, h * 0.03, PAL.chromeDark, 240);

  // 5. Drum Interior & Tumbling Laundry / Soapy Water
  ellipseWashStroke(cx, cy, rIn, rIn, PAL.chromeBlack, 255, "techpen", PAL.chromeBlack, 0.9, 32);
  // Perforated stainless back of drum in upper half
  polyWash(ringSectorPts(cx, cy, 0, 0, rIn * 0.88, rIn * 0.88, -165, -15, 12), PAL.chromeDark, 240);
  polyWash(ringSectorPts(cx, cy, rIn * 0.3, rIn * 0.3, rIn * 0.82, rIn * 0.82, -135, -45, 8), PAL.chromeMid, 210);

  // Swirling laundry & suds in lower half of drum
  polyWash(ringSectorPts(cx, cy, 0, 0, rIn * 0.94, rIn * 0.94, 5, 175, 12), waterCol, 245);
  let altCol = (waterCol === PAL.skyBright) ? PAL.tangBright : PAL.skyVivid;
  polyWash(ringSectorPts(cx, cy, rIn * 0.2, rIn * 0.2, rIn * 0.85, rIn * 0.85, 35, 135, 8), altCol, 235);
  // White soapy foam line
  let foamY = cy + rIn * 0.1;
