  for (let i = 0; i < 16; i++) {
    let sx1 = 120 + i * 46;
    let sx2 = sx1 + 46;
    let col = (i % 4 === 0) ? PAL.tangBright : ((i % 4 === 1) ? PAL.white : ((i % 4 === 2) ? PAL.mintBright : PAL.skyBright));
