  // --- 2. THE "DOUBLED AWNING" (Reflected Awning of the Shop Across the Street: x 135..685, y 476..542) ---
  // Slanted trapezoidal canopy in vivid Tangerine, Mint, and White cutting right across the upper washers!
  let awTopY = 476, awMidY = 518, awBotY = 538;
  for (let i = 0; i < 12; i++) {
