function drawSedanWheel(cx, cy, r) {
  // Chrome wheel-well arch molding
  let archPts = ringSectorPts(cx, cy, r + 2, r + 2, r + 10, r + 10, -180, 0, 14);
  polyWashStroke(archPts, PAL.white, 245, "techpen", PAL.chromeBlack, 0.85);

  // Dark wheel well cavity
  polyWash(ringSectorPts(cx, cy, 0, 0, r + 2, r + 2, -180, 180, 24), PAL.chromeBlack, 165);

  // Tire tread & sidewall
  ellipseWashStroke(cx, cy, r, r, PAL.chromeDark, 190, "techpen", PAL.chromeBlack, 0.95, 32);

  // Crisp 1970s Whitewall Stripe
  let wwPts = ringSectorPts(cx, cy, r * 0.64, r * 0.64, r * 0.78, r * 0.78, -180, 180, 28);
  polyWashStroke(wwPts, PAL.cream, 235, "techpen", PAL.chromeBlack, 0.7);

  // Gleaming Chrome Hubcap (multi-sector specular ring + center spinner dome)
  drawChromeRing(cx, cy, r * 0.24, r * 0.24, r * 0.62, r * 0.62, 0.98, 28);
  ellipseWashStroke(cx, cy, r * 0.24, r * 0.24, PAL.white, 250, "techpen", PAL.chromeBlack, 0.8, 20);
  ellipseWashStroke(cx, cy, r * 0.1, r * 0.1, PAL.tangVivid, 245, "techpen", PAL.chromeBlack, 0.6, 14);
}

function drawReflectedBusStopSign(cx, topY, w, h, alphaMult = 1.0) {
  let x = cx - w * 0.5;
  let A = (v) => Math.round(v * alphaMult);

  // Galvanized steel signpost rising from curb through the composition
  rectWashStroke(cx - 5, topY - 25, 10, 510, PAL.chromeLight, A(235), "techpen", PAL.chromeBlack, 0.85);
  rectWash(cx - 5, topY - 25, 4, 510, PAL.white, A(250));
  rectWash(cx + 1, topY - 25, 4, 510, PAL.chromeDark, A(220));

  // Sign blade backing shadow
  rectWash(x + 4, topY + 4, w, h, PAL.chromeBlack, A(175));

  // Main Sign Blade Frame (White border)
  rectWashStroke(x, topY, w, h, PAL.white, A(245), "techpen", PAL.chromeBlack, 1.0);

  // Top Vivid Tangerine Header ("NO STANDING")
  rectWashStroke(x + 4, topY + 4, w - 8, h * 0.26, PAL.tangVivid, A(245), "techpen", PAL.chromeBlack, 0.75);
  drawSignText("BUS STOP", x + 10, topY + 11, h * 0.14, w * 0.082, 2.5, PAL.white, null, 0);

  // Center Sky Blue & White Pictogram Panel
  rectWashStroke(x + 4, topY + h * 0.32, w - 8, h * 0.42, PAL.skyVivid, A(240), "techpen", PAL.chromeBlack, 0.75);
  // Crisp geometric front-view Bus Icon inside panel
  let bx = cx - w * 0.22, by = topY + h * 0.37, bw = w * 0.44, bh = h * 0.31;
  rectWashStroke(bx, by, bw, bh, PAL.white, A(255), "techpen", PAL.chromeBlack, 0.75);
  rectWashStroke(bx + 4, by + 4, bw - 8, bh * 0.42, PAL.skyDeep, A(245), "techpen", PAL.chromeBlack, 0.6);
  ellipseWashStroke(bx + 7, by + bh * 0.72, 3.5, 3.5, PAL.tangVivid, A(255), "techpen", PAL.chromeBlack, 0.5, 12);
  ellipseWashStroke(bx + bw - 7, by + bh * 0.72, 3.5, 3.5, PAL.tangVivid, A(255), "techpen", PAL.chromeBlack, 0.5, 12);

  // Bottom Vivid Mint Route Band
  rectWashStroke(x + 4, topY + h * 0.76, w - 8, h * 0.2, PAL.mintVivid, A(245), "techpen", PAL.chromeBlack, 0.75);
  rectWash(x + 10, topY + h * 0.81, w - 20, 4, PAL.white, A(245));
  rectWash(x + 10, topY + h * 0.88, w * 0.6, 4, PAL.white, A(245));

  // Chrome U-bolts clamping sign to pole
  rectWashStroke(cx - 9, topY + h * 0.15, 18, 5, PAL.white, A(255), "techpen", PAL.chromeBlack, 0.7);
  rectWashStroke(cx - 9, topY + h * 0.85, 18, 5, PAL.white, A(255), "techpen", PAL.chromeBlack, 0.7);
}

