function drawForegroundAwning() {
  // Cast noon shadow from awning onto upper plate glass & mullions (y: 315..358)
  polyWash([[82, 315], [888, 315], [888, 356], [82, 356]], PAL.chromeBlack, 130);

  // Main Awning Slope (from fascia y: 224 down-outward to front roller bar y: 298)
  const numStripes = 18;
  const topX0 = 88, topX1 = 876;
  const botX0 = 70, botX1 = 886;
  const topY = 224, midY = 298, valY = 328;

  for (let i = 0; i < numStripes; i++) {
    let t0 = i / numStripes;
    let t1 = (i + 1) / numStripes;
    let tx0 = lerp(topX0, topX1, t0);
    let tx1 = lerp(topX0, topX1, t1);
    let bx0 = lerp(botX0, botX1, t0);
    let bx1 = lerp(botX0, botX1, t1);

    // Vivid 1970s stripe sequence: Tangerine, Cream-White, Mint, Sky Blue
    let topCol, valCol;
    if (i % 4 === 0) {
      topCol = PAL.tangVivid; valCol = PAL.tangDeep;
    } else if (i % 4 === 1) {
      topCol = PAL.cream;     valCol = PAL.chromeSilver;
    } else if (i % 4 === 2) {
      topCol = PAL.mintVivid; valCol = PAL.mintDeep;
    } else {
      topCol = PAL.skyVivid;  valCol = PAL.skyShadow;
    }

    // Slanted top canvas plane in bright noon sun
    polyWashStroke(
      [[tx0, topY], [tx1, topY], [bx1, midY], [bx0, midY]],
      topCol, 255, "techpen", PAL.chromeBlack, 0.85
    );
    // Sunlit highlight band near front roller
    let hx0 = lerp(tx0, bx0, 0.78);
    let hx1 = lerp(tx1, bx1, 0.78);
    polyWash([[hx0, lerp(topY, midY, 0.78)], [hx1, lerp(topY, midY, 0.78)], [bx1, midY], [bx0, midY]], PAL.white, 95);

    // Vertical hanging valance tab (in steeper shadow)
    let tabPts = [
      [bx0, midY], [bx1, midY],
      [bx1 - 3, valY], [bx0 + 3, valY]
    ];
    polyWashStroke(tabPts, valCol, 255, "techpen", PAL.chromeBlack, 0.85);
  }

  // Gleaming tubular chrome awning roller bar along y: 295..302
  drawHorizontalChromeBar(botX0 - 2, midY - 3, (botX1 - botX0) + 4, 7);

  // Exposed dark underside & tubular chrome support arms on left end of awning
  polyWashStroke([[88, topY], [70, midY], [88, midY + 12]], PAL.chromeBlack, 245, "techpen", PAL.chromeBlack, 0.9);
  ruledLine(88, 285, 74, 300, PAL.white, 1.4);

  // Secondary Side Awning over Right Return Window (x: 886..1200, y: 228..324)
  for (let j = 0; j < 7; j++) {
    let t0 = j / 7, t1 = (j + 1) / 7;
    let tx0 = lerp(886, 1200, t0), tx1 = lerp(886, 1200, t1);
    let bx0 = lerp(894, 1208, t0), bx1 = lerp(894, 1208, t1);
    let topCol = (j % 2 === 0) ? PAL.tangVivid : PAL.mintBright;
    let valCol = (j % 2 === 0) ? PAL.tangDeep : PAL.mintDeep;
    polyWashStroke([[tx0, 228 + j * 1.1], [tx1, 228 + (j + 1) * 1.1], [bx1, 298], [bx0, 298]], topCol, 255, "techpen", PAL.chromeBlack, 0.85);
    polyWashStroke([[bx0, 298], [bx1, 298], [bx1 - 2, 326], [bx0 + 2, 326]], valCol, 255, "techpen", PAL.chromeBlack, 0.85);
  }
  drawHorizontalChromeBar(892, 295, 308, 7);
}

