// Catmull-Rom / cubic interpolation along a 4-point finger spine
function evalFingerFrame(finger, t) {
  let sp = finger.spine;
  let ws = finger.widths;
  t = constrain(t, 0, 1);

  // De Casteljau / smooth cubic through the 4 control points
  let u = t * 3;
  let idx = min(2, floor(u));
  let f = u - idx;

  let p0 = sp[max(0, idx - 1)];
  let p1 = sp[idx];
  let p2 = sp[min(3, idx + 1)];
  let p3 = sp[min(3, idx + 2)];

  let x = catmullRom(p0[0], p1[0], p2[0], p3[0], f);
  let y = catmullRom(p0[1], p1[1], p2[1], p3[1], f);

  let eps = 0.01;
  let t2 = min(1, t + eps);
  let t1 = max(0, t - eps);
  let u2 = t2 * 3, idx2 = min(2, floor(u2)), f2 = u2 - idx2;
  let u1 = t1 * 3, idx1 = min(2, floor(u1)), f1 = u1 - idx1;

  let x2 = catmullRom(sp[max(0, idx2 - 1)][0], sp[idx2][0], sp[min(3, idx2 + 1)][0], sp[min(3, idx2 + 2)][0], f2);
  let y2 = catmullRom(sp[max(0, idx2 - 1)][1], sp[idx2][1], sp[min(3, idx2 + 1)][1], sp[min(3, idx2 + 2)][1], f2);
  let x1 = catmullRom(sp[max(0, idx1 - 1)][0], sp[idx1][0], sp[min(3, idx1 + 1)][0], sp[min(3, idx1 + 2)][0], f1);
  let y1 = catmullRom(sp[max(0, idx1 - 1)][1], sp[idx1][1], sp[min(3, idx1 + 1)][1], sp[min(3, idx1 + 2)][1], f1);

  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty;
  let ny = tx;

  let wBase = catmullRom(ws[max(0, idx - 1)], ws[idx], ws[min(3, idx + 1)], ws[min(3, idx + 2)], f);
  // Subtle anatomical phalanx belly swell and joint pinch
  let jointPinch = 1.0 - 0.045 * exp(-pow((t - finger.joints[0]) / 0.07, 2)) - 0.045 * exp(-pow((t - finger.joints[1]) / 0.07, 2));
  let tipRound = t > 0.82 ? sqrt(max(0.02, 1 - pow((t - 0.82) / 0.185, 2))) : 1.0;
  let w = wBase * jointPinch * tipRound;

  return { x, y, tx, ty, nx, ny, w };
}

function catmullRom(v0, v1, v2, v3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  return 0.5 * (
    (2 * v1) +
    (-v0 + v2) * t +
    (2 * v0 - 5 * v1 + 4 * v2 - v3) * t2 +
    (-v0 + 3 * v1 - 3 * v2 + v3) * t3
  );
}

// Map (t along finger [0..1], s across finger [-1..1]) to 2D canvas coordinates with 3D cylindrical foreshortening
function fingerPt(finger, t, s) {
  let fr = evalFingerFrame(finger, t);
  let cylS = sin(constrain(s, -1, 1) * 90);
  return [fr.x + fr.nx * fr.w * cylS, fr.y + fr.ny * fr.w * cylS];
}

function getFingerPolygon(finger, tStart = 0, tEnd = 1, sMin = -1, sMax = 1, steps = 18) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = lerp(tStart, tEnd, i / steps);
    pts.push(fingerPt(finger, t, sMax));
  }
  for (let i = steps; i >= 0; i--) {
    let t = lerp(tStart, tEnd, i / steps);
    pts.push(fingerPt(finger, t, sMin));
  }
  return pts;
}

function drawOrganicPoly(pts, curvature = 0.5) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curv);
  }
}

