function drawCoolLaceLattice() {
  // Cooled lattice of bridal Chantilly/Guipure lace across the table
  let gridStep = 64;
  let angle = -16;
  let cosA = cos(angle);
  let sinA = sin(angle);

  function laceToWorld(u, v) {
    let cx = 600 + u * cosA - v * sinA;
    let cy = 600 + u * sinA + v * cosA;
    // Slight fabric wave
    let wave = 4 * sin(u * 0.45) * cos(v * 0.45);
    return [cx + wave, cy - wave * 0.7];
  }

  // Only draw lace where not completely buried under solid hand/tumbler cores
  function isUnderCore(x, y) {
    let dTumbler = pow((x - 425) / 165, 2) + pow((y - 395) / 140, 2);
    if (dTumbler < 0.85) return true;
    let dPalm = pow((x - 765) / 145, 2) + pow((y - 695) / 155, 2);
    if (dPalm < 0.82) return true;
    let dWrist = pow((x - 965) / 150, 2) + pow((y - 940) / 160, 2);
    if (dWrist < 0.85) return true;
    return false;
  }

  // 1. Fine hexagonal diagonal lace net (tulle ground)
  brush.set("2H", "#456382", 0.32);
  for (let u = -720; u <= 720; u += gridStep * 0.5) {
    let pts1 = [];
    let pts2 = [];
    for (let v = -720; v <= 720; v += 48) {
      let pA = laceToWorld(u + v * 0.5, v);
      if (!isUnderCore(pA[0], pA[1])) {
        pts1.push(pA);
      } else {
        if (pts1.length >= 2) safeSpline(pts1, 0.3);
        pts1 = [];
      }

      let pB = laceToWorld(u - v * 0.5, v);
      if (!isUnderCore(pB[0], pB[1])) {
        pts2.push(pB);
      } else {
        if (pts2.length >= 2) safeSpline(pts2, 0.3);
        pts2 = [];
      }
    }
    if (pts1.length >= 2) safeSpline(pts1, 0.3);
    if (pts2.length >= 2) safeSpline(pts2, 0.3);
  }

  // 2. Woven floral lace medallions & cooled lattice nodes
  for (let u = -640; u <= 640; u += gridStep) {
    for (let v = -640; v <= 640; v += gridStep) {
      let c = laceToWorld(u, v);
      let x = c[0], y = c[1];
      if (x < -30 || x > 1230 || y < -30 || y > 1230) continue;
      if (isUnderCore(x, y)) continue;

      // Determine local illumination (brighter in upper-left, cooler/darker near shadows)
      let distToLight = dist(x, y, 260, 220);
      let isLit = distToLight < 580 && y < 780;

      // Shadow offset of lace motif
      brush.set("2H", "#101b2b", 0.45);
      brush.circle(x + 2, y + 2.5, 16, 0.15);

      // Mid-tone periwinkle/ice-blue lace thread
      brush.set("cpencil", isLit ? "#7ea1c4" : "#4b6888", 0.42);
      brush.circle(x, y, 16, 0.18);
      brush.circle(x, y, 7, 0.12);

      // 6-petal lace rosette inside each lattice cell
      let highlightCol = isLit ? "#cae0f5" : "#7898b8";
      brush.set("2H", highlightCol, 0.34);
      for (let a = 0; a < 360; a += 60) {
        let px1 = x + cos(a) * 6;
        let py1 = y + sin(a) * 6;
        let px2 = x + cos(a) * 19;
        let py2 = y + sin(a) * 19;
        brush.line(px1, py1, px2, py2);
        // Tiny picot loop at tip
        brush.arc(px2, py2, 4.2, a - 70, a + 70);
      }

      // Crisp ice-white thread catchlights on upper-left of lit lace medallions
      if (isLit) {
        brush.set("rotring", "#e3f2ff", 0.25);
        brush.arc(x - 1, y - 1, 15.5, 195, 330);
      }
    }
  }
}

