// 3. DENTED STEEL TUMBLER & MILKY CHAI WITH ANAMORPHIC REFLECTIONS
// =============================================================================

function ellipsePt(cx, cy, rx, ry, rotDeg, angDeg) {
  let cRot = cos(rotDeg), sRot = sin(rotDeg);
  let ex = rx * cos(angDeg);
  let ey = ry * sin(angDeg);
  return [cx + ex * cRot - ey * sRot, cy + ex * sRot + ey * cRot];
}

function drawDentedSteelTumbler() {
  let rimCx = 432, rimCy = 368, rimRx = 192, rimRy = 158, rot = -14;
  let baseCx = 406, baseCy = 532, baseRx = 150, baseRy = 124;

  // Helper to compute point on the tapered tumbler wall with realistic dents
  function tumblerWallPt(ang, v) {
    let pRim = ellipsePt(rimCx, rimCy, rimRx, rimRy, rot, ang);
    let pBase = ellipsePt(baseCx, baseCy, baseRx, baseRy, rot, ang);
    let x = lerp(pRim[0], pBase[0], v);
    let y = lerp(pRim[1], pBase[1], v);

    // Dent 1: Sharp planar/concave dent on lower-left steel wall (ang ~ 125..168, v ~ 0.28..0.82)
    let d1Ang = exp(-pow((ang - 146) / 18, 2));
    let d1V = exp(-pow((v - 0.56) / 0.24, 2));
    let dent1 = d1Ang * d1V;
    x += dent1 * 14;
    y -= dent1 * 7;

    // Dent 2: Concave facet on lower-right wall near gripping fingers (ang ~ 38..78, v ~ 0.32..0.85)
    let d2Ang = exp(-pow((ang - 58) / 16, 2));
    let d2V = exp(-pow((v - 0.58) / 0.22, 2));
    let dent2 = d2Ang * d2V;
    x -= dent2 * 11;
    y -= dent2 * 8;

    return [x, y];
  }

  function buildWallPatch(ang1, ang2, v1, v2, steps = 10) {
    let pts = [];
    for (let i = 0; i <= steps; i++) {
      pts.push(tumblerWallPt(lerp(ang1, ang2, i / steps), v1));
    }
    for (let i = 0; i <= steps; i++) {
      pts.push(tumblerWallPt(ang2, lerp(v1, v2, i / steps)));
    }
    for (let i = steps; i >= 0; i--) {
      pts.push(tumblerWallPt(lerp(ang1, ang2, i / steps), v2));
    }
    for (let i = steps; i >= 0; i--) {
      pts.push(tumblerWallPt(ang1, lerp(v1, v2, i / steps)));
    }
    return pts;
  }

  brush.noStroke();

  // Base metallic slate wash for the visible steel wall (from ang = -35 around bottom to ang = 208)
  brush.wash("#2a3d54", 235);
  drawOrganicPoly(buildWallPatch(-35, 208, 0.0, 1.0, 24), 0.35);
  brush.noWash();

  // Layered watercolor metallic reflection zones & dented facets
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.38, 0.32);

  // Deep obsidian-navy core reflection bands
  brush.fill("#101c2e", 150);
  drawOrganicPoly(buildWallPatch(105, 142, 0.02, 0.98, 8), 0.3);
  drawOrganicPoly(buildWallPatch(8, 36, 0.02, 0.95, 8), 0.3);

  // Cool ice-blue & silver reflection bands on left side (reflecting cool window & lace)
  brush.fill("#9ab8d4", 125);
  drawOrganicPoly(buildWallPatch(148, 182, 0.02, 0.96, 8), 0.3);
  drawOrganicPoly(buildWallPatch(78, 102, 0.04, 0.94, 8), 0.3);

  // Bright specular bevel on Dent 1 (lower-left dent)
  brush.fill("#d8ecff", 145);
  drawOrganicPoly(buildWallPatch(126, 154, 0.24, 0.54, 6), 0.2);

  // Deep concave shadow inside Dent 1 lower facet
  brush.fill("#0c1624", 165);
  drawOrganicPoly(buildWallPatch(128, 162, 0.54, 0.86, 6), 0.2);

  // Distorted warm sienna & rose reflections of the hand on the right/lower-right steel wall!
  brush.fill("#b86242", 125);
  drawOrganicPoly(buildWallPatch(-28, 12, 0.05, 0.92, 8), 0.35);
  drawOrganicPoly(buildWallPatch(36, 78, 0.12, 0.92, 8), 0.35);

  // Distorted rose-carmine & bright orange henna stain reflection in Dent 2!
  brush.fill("#d96548", 115);
  drawOrganicPoly(buildWallPatch(42, 72, 0.28, 0.65, 6), 0.25);

  brush.fill("#e87420", 110);
  drawOrganicPoly(buildWallPatch(-18, 6, 0.22, 0.58, 6), 0.25);
  drawOrganicPoly(buildWallPatch(48, 68, 0.55, 0.85, 6), 0.25);

  brush.noFill();

  // Anamorphic linear reflections:
  // 1. Cooled lace lattice reflected in warped arcs on the left steel wall
  brush.set("2H", "#c6e0f7", 0.32);
  for (let v = 0.15; v <= 0.88; v += 0.14) {
    let lPts = [];
    for (let a = 82; a <= 195; a += 8) {
      let p = tumblerWallPt(a, v + 0.04 * sin(a * 4));
      lPts.push(p);
    }
    safeSpline(lPts, 0.45);
  }
  brush.set("2H", "#5c7ea1", 0.35);
  for (let a = 88; a <= 190; a += 16) {
    let dPts = [];
    for (let v = 0.12; v <= 0.90; v += 0.15) {
      dPts.push(tumblerWallPt(a + 8 * sin(v * 180), v));
    }
    safeSpline(dPts, 0.45);
  }

  // 2. Distorted henna paste dark lines & orange stain flecks reflected on the right steel wall
  brush.set("pen", "#252b14", 0.55);
  for (let v = 0.18; v <= 0.82; v += 0.13) {
    let hPts = [];
    for (let a = -24; a <= 74; a += 8) {
      let p = tumblerWallPt(a, v + 0.035 * cos(a * 5));
      hPts.push(p);
    }
    safeSpline(hPts, 0.5);
  }
  brush.set("cpencil", "#f06d18", 0.55);
  for (let v = 0.22; v <= 0.78; v += 0.18) {
    let oPts = [];
    for (let a = -15; a <= 68; a += 10) {
      oPts.push(tumblerWallPt(a, v - 0.02));
    }
    safeSpline(oPts, 0.5);
  }

  // 3. Sharp polygonal ridge crease lines for Dent 1 & Dent 2 + horizontal spun steel grooves
  brush.set("rotring", "#e8f5ff", 0.42);
  safeSpline([tumblerWallPt(122, 0.48), tumblerWallPt(146, 0.36), tumblerWallPt(168, 0.50)], 0.25);
  safeSpline([tumblerWallPt(38, 0.52), tumblerWallPt(58, 0.42), tumblerWallPt(76, 0.56)], 0.25);

  brush.set("2B", "#0a1320", 0.48);
  safeSpline([tumblerWallPt(124, 0.52), tumblerWallPt(146, 0.64), tumblerWallPt(166, 0.54)], 0.25);
  safeSpline([tumblerWallPt(40, 0.56), tumblerWallPt(58, 0.68), tumblerWallPt(74, 0.58)], 0.25);

  // Two classic lathe-spun horizontal decorative beads near the top of the tumbler
  for (let beadV of [0.16, 0.27]) {
    let ridgeHi = [], ridgeLo = [];
    for (let a = -32; a <= 205; a += 8) {
      ridgeHi.push(tumblerWallPt(a, beadV - 0.012));
      ridgeLo.push(tumblerWallPt(a, beadV + 0.012));
    }
    brush.set("rotring", "#dceeff", 0.38);
    safeSpline(ridgeHi, 0.45);
    brush.set("2B", "#0f1c2e", 0.45);
    safeSpline(ridgeLo, 0.45);
  }

  // Fine brushed steel micro-scratches along the cylinder
  brush.set("2H", "#7fa1c2", 0.22);
  for (let i = 0; i < 42; i++) {
    let a1 = random(-25, 195);
    let a2 = a1 + random(12, 28);
    let v = random(0.05, 0.90);
    let p1 = tumblerWallPt(a1, v);
    let p2 = tumblerWallPt(a2, v + random(-0.03, 0.03));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawMilkyChaiSurface() {
  let rimCx = 432, rimCy = 368, rimRx = 192, rimRy = 158, rot = -14;
  let chaiCx = 432, chaiCy = 375, chaiRx = 177, chaiRy = 145;

  function getEllipsePoly(cx, cy, rx, ry, rDeg, aStart = 0, aEnd = 360, steps = 36) {
    let pts = [];
    for (let i = 0; i <= steps; i++) {
      let a = lerp(aStart, aEnd, i / steps);
      pts.push(ellipsePt(cx, cy, rx, ry, rDeg, a));
    }
    return pts;
  }

  brush.noStroke();

  // Rolled steel rim base & inner wall above the liquid
  brush.wash("#334963", 230);
  drawOrganicPoly(getEllipsePoly(rimCx, rimCy, rimRx + 6, rimRy + 5, rot, 0, 359, 40), 0.5);

