  drawOrganicPoly(getEllipsePoly(chaiCx - 10, chaiCy + 8, chaiRx * 0.82, chaiRy * 0.80, rot, 0, 359, 28), 0.5);

  // Warm lactescent cream highlight swirl
  brush.fill("#f0c699", 90);
  drawOrganicPoly(getEllipsePoly(chaiCx - 22, chaiCy + 16, chaiRx * 0.58, chaiRy * 0.55, rot, 0, 359, 24), 0.5);

  // Cool sky-blue / periwinkle window reflection skimming across the glossy tea surface!
  brush.fill("#c5ddf2", 82);
  drawOrganicPoly([
    ...getEllipsePoly(chaiCx, chaiCy, chaiRx * 0.90, chaiRy * 0.88, rot, 135, 255, 16),
    ...getEllipsePoly(chaiCx + 15, chaiCy + 10, chaiRx * 0.62, chaiRy * 0.60, rot, 255, 135, 16)
  ], 0.45);

  brush.fill("#e8f4ff", 70);
  drawOrganicPoly([
    ...getEllipsePoly(chaiCx, chaiCy, chaiRx * 0.84, chaiRy * 0.82, rot, 155, 232, 12),
    ...getEllipsePoly(chaiCx + 8, chaiCy + 6, chaiRx * 0.70, chaiRy * 0.68, rot, 232, 155, 12)
  ], 0.45);

  brush.noFill();

  // Floating green cardamom pods & crushed black tea / spice specks
  let pods = [
    { x: 468, y: 348, ang: 25, rx: 11, ry: 5.5 },
    { x: 382, y: 412, ang: -38, rx: 9.5, ry: 4.8 }
  ];
  for (let pod of pods) {
    // Meniscus ring around floating pod
    brush.set("cpencil", "#f7dfc4", 0.45);
    brush.circle(pod.x, pod.y, pod.rx * 1.15, 0.2);

    // Cardamom husk
    let podPts = getEllipsePoly(pod.x, pod.y, pod.rx, pod.ry, pod.ang, 0, 350, 12);
    brush.noStroke();
    brush.wash("#5d734b", 210);
    drawOrganicPoly(podPts, 0.4);
    brush.noWash();

    brush.set("2B", "#334226", 0.38);
    safeSpline(podPts, 0.4);
    // Ridges on cardamom pod & tiny black seeds
    brush.set("rotring", "#8fa679", 0.25);
    brush.line(pod.x - 6, pod.y - 2, pod.x + 6, pod.y + 2);
    brush.set("rotring", "#1f1510", 0.45);
    brush.circle(pod.x + 2, pod.y + 1, 1.5);
    brush.circle(pod.x - 2, pod.y - 1, 1.2);
  }

  // Tiny floating Assam tea specks & cinnamon dust
  brush.set("2B", "#4a2410", 0.35);
  for (let i = 0; i < 45; i++) {
    let r = random(15, 140);
    let a = random(0, 360);
    let p = ellipsePt(chaiCx, chaiCy, r * 1.1, r * 0.9, rot, a);
    brush.line(p[0], p[1], p[0] + random(-1.5, 1.5), p[1] + random(-1.5, 1.5));
  }

  // Creamy micro-foam bubbles clinging to the inner steel meniscus
  for (let a = 0; a < 360; a += 4) {
    if (random() < 0.72) {
      let bR = random(0.93, 0.995);
      let p = ellipsePt(chaiCx, chaiCy, chaiRx * bR, chaiRy * bR, rot, a);
      let sz = random(1.8, 5.2);
      brush.set("cpencil", "#f7e3c8", 0.38);
      brush.circle(p[0], p[1], sz, 0.15);
      if (sz > 3.2) {
        brush.set("rotring", "#ffffff", 0.22);
        brush.arc(p[0] - 0.6, p[1] - 0.6, sz * 0.7, 190, 320);
      }
    }
  }

  // Rolled steel rim 3D rendering (inner dark bevel, metallic crown, razor-sharp specular highlights)
  brush.set("2B", "#101c2c", 0.75);
  safeSpline(getEllipsePoly(rimCx, rimCy, rimRx + 6, rimRy + 5, rot, 0, 360, 48), 0.5);

  brush.set("cpencil", "#6482a1", 0.85);
  safeSpline(getEllipsePoly(rimCx, rimCy, rimRx + 2, rimRy + 1.5, rot, 0, 360, 48), 0.5);

  brush.set("2B", "#1d2d42", 0.65);
  safeSpline(getEllipsePoly(rimCx, rimCy, rimRx - 4, rimRy - 3.5, rot, 0, 360, 48), 0.5);

  // Brilliant cool-white & ice-cyan specular highlights along the rolled rim
  brush.set("rotring", "#f2f9ff", 0.65);
  safeSpline(getEllipsePoly(rimCx, rimCy, rimRx + 1.5, rimRy + 1, rot, 115, 265, 28), 0.5);
  safeSpline(getEllipsePoly(rimCx, rimCy, rimRx + 1.5, rimRy + 1, rot, -45, 55, 22), 0.5);

  brush.set("pen", "#ffffff", 0.45);
  safeSpline(getEllipsePoly(rimCx, rimCy, rimRx + 2.5, rimRy + 2, rot, 145, 225, 18), 0.5);
}

