    // Central vertical / Fate crease
    [[812, 835], [768, 748], [732, 668], [695, 592]],
    // Wrist Rascette creases (double bracelet lines of skin)
    [[782, 902], [838, 845], [892, 782], [936, 720]],
    [[796, 918], [852, 862], [906, 798], [950, 736]]
  ];

  for (let cr of palmarCreases) {
    // Soft rose-sienna pencil halo
    brush.set("cpencil", "#9c4836", 0.65);
    safeSpline(cr, 0.5);

    // Crisp 2B graphite-umber core crease
    brush.set("2B", "#4f1f18", 0.42);
    safeSpline(cr, 0.5);

    // Luminous highlight ridge right beside the crease
    let hiCr = cr.map(p => [p[0] + 1.8, p[1] - 1.8]);
    brush.set("cpencil", "#f2bc9b", 0.35);
    safeSpline(hiCr, 0.5);

    // Tiny feathered micro-creases branching off the main palmar crease
    brush.set("HB", "#6e3024", 0.26);
    for (let i = 0; i < cr.length - 1; i++) {
      for (let m = 0; m < 4; m++) {
        let f = random(0.1, 0.9);
        let bx = lerp(cr[i][0], cr[i + 1][0], f);
        let by = lerp(cr[i][1], cr[i + 1][1], f);
        let ang = random(-75, 75);
        let len = random(6, 15);
        brush.line(bx, by, bx + cos(ang) * len, by + sin(ang) * len);
      }
    }
  }

  // 3. Knuckle / Interphalangeal Flexion Creases on all 5 digits (MCP, PIP, DIP joints)
  for (let i = 0; i < fingers.length; i++) {
    let fg = fingers[i];
    let jointTs = [0.04, fg.joints[0], fg.joints[1]];
    for (let jt of jointTs) {
      // Triple elliptical skin folds at each finger joint
      for (let offset of [-0.022, 0, 0.022]) {
        let t = jt + offset;
        let foldPts = [];
        let bow = offset === 0 ? 0.012 : (offset < 0 ? -0.015 : 0.015);
        for (let s = -0.88; s <= 0.88; s += 0.22) {
          let tCurv = t + bow * (1 - s * s);
          foldPts.push(fingerPt(fg, tCurv, s));
        }
        brush.set("cpencil", "#944232", 0.45);
        safeSpline(foldPts, 0.5);
        brush.set("2B", "#4a1c15", offset === 0 ? 0.40 : 0.28);
        safeSpline(foldPts, 0.5);
      }
      // Highlight ridge between knuckle folds
      let hiPts = [];
      for (let s = -0.7; s <= 0.7; s += 0.25) {
        hiPts.push(fingerPt(fg, jt - 0.011, s));
      }
      brush.set("cpencil", "#f5c4a6", 0.30);
      safeSpline(hiPts, 0.5);
    }
  }

  // 4. Dermatoglyphic papillary skin ridges (fine 2H pencil curves across palm mounts & finger pads)
  brush.set("2H", "#8f4536", 0.22);
  for (let i = 0; i < fingers.length; i++) {
    let fg = fingers[i];
    for (let t = 0.08; t <= 0.92; t += 0.032) {
      let rPts = [];
      for (let s = -0.78; s <= 0.78; s += 0.26) {
        let arch = (t > 0.72 ? -0.028 : -0.012) * (1 - s * s);
        rPts.push(fingerPt(fg, t + arch, s));
      }
      safeSpline(rPts, 0.5);
    }
  }

  // Sweeping epidermal ridge arcs across the Thenar & Hypothenar palm mounts
  for (let r = 20; r <= 125; r += 6.5) {
    let thPts = [];
    for (let a = 125; a <= 235; a += 18) {
      thPts.push([855 + cos(a) * r, 585 + sin(a) * r]);
    }
    safeSpline(thPts, 0.5);

    let hyPts = [];
    for (let a = 165; a <= 275; a += 18) {
      hyPts.push([805 + cos(a) * (r * 0.85), 855 + sin(a) * (r * 0.85)]);
    }
    safeSpline(hyPts, 0.5);
  }

  // 5. Stippled Pencil Pores across the skin (Thenar, Hypothenar, Wrist, and Finger sides)
  brush.set("HB", "#6b2d22", 0.28);
  for (let i = 0; i < 620; i++) {
    // Palm & wrist pores
    let px = random(625, 980);
    let py = random(500, 960);
    if (dist(px, py, 765, 700) < 175 || (px > 780 && py > 700 && px + py < 2080)) {
      brush.line(px, py, px + 0.9, py + 0.9);
    }
  }
  brush.set("2H", "#873e30", 0.25);
  for (let i = 0; i < fingers.length; i++) {
    let fg = fingers[i];
    for (let k = 0; k < 85; k++) {
      let t = random(0.04, 0.95);
      let s = random(-0.88, 0.88);
      let p = fingerPt(fg, t, s);
      brush.line(p[0], p[1], p[0] + 0.8, p[1] + 0.8);
    }
  }
}

function drawFingernails() {
  // The thumb (seen in 3/4 profile gripping the upper-right rim) shows its thumbnail clearly,
  // and the tilted fingertips show a sliver of nail edge with warm orange henna stain!
  let thumb = fingers[0];
  let nailPoly = [
    fingerPt(thumb, 0.83, -0.95),
    fingerPt(thumb, 0.91, -0.98),
    fingerPt(thumb, 0.99, -0.78),
    fingerPt(thumb, 0.97, -0.35),
    fingerPt(thumb, 0.86, -0.38)
  ];

  brush.noStroke();
  brush.wash("#e3a39b", 225);
  drawOrganicPoly(nailPoly, 0.4);
  brush.noWash();

  // Translucent orange-tinted cuticle & cool specular nail highlight
  brush.set("cpencil", "#d95b16", 0.42);
  safeSpline([nailPoly[4], nailPoly[3], nailPoly[2]], 0.4);

  brush.set("2B", "#5c231a", 0.35);
  safeSpline([nailPoly[0], nailPoly[1], nailPoly[2]], 0.4);

  brush.set("rotring", "#f2f8ff", 0.38);
  let pHi1 = fingerPt(thumb, 0.86, -0.75);
  let pHi2 = fingerPt(thumb, 0.96, -0.68);
  brush.line(pHi1[0], pHi1[1], pHi2[0], pHi2[1]);
}

// =============================================================================
// 6. BRIDAL MEHNDI ENGINE: ORANGE SKIN STAIN + RAISED GLOSSY PASTE + FLAKING
// =============================================================================

// Determines if a canvas coordinate (x, y) lies inside one of the cracked/flaked henna zones
// where the dried paste has dropped off to reveal the vivid bright orange stain beneath!
function isHennaFlakedAt(x, y, extraBias = 0) {
  // Cracked/flaked zones near flexing palmar creases & finger joints
  let d1 = dist(x, y, 725, 645) < 34; // Central palm head-line flex zone
  let d2 = dist(x, y, 775, 765) < 32; // Lower jali lattice flex zone
  let d3 = dist(x, y, 818, 622) < 26; // Thenar crease flex zone
  let d4 = dist(x, y, 495, 558) < 25; // Index PIP joint
  let d5 = dist(x, y, 466, 650) < 26; // Middle PIP joint
  let d6 = dist(x, y, 495, 746) < 24; // Ring PIP joint
  let d7 = dist(x, y, 360, 520) < 22; // Index DIP joint
  let d8 = dist(x, y, 695, 395) < 25; // Thumb joint
  let d9 = dist(x, y, 882, 815) < 28; // Wrist crease flex zone
  if (d1 || d2 || d3 || d4 || d5 || d6 || d7 || d8 || d9) return true;

  let n = noise(x * 0.025, y * 0.025);
  return n + extraBias > 0.68;
}

// Renders a henna curve with:
// 1) Bright orange-saffron skin stain underneath
// 2) Raised 3D dark olive-brown paste (marker + fine pen) + cool glossy specular highlight where intact
function drawHennaStroke(pts, weight = 0.65, forceStainOnly = false) {
  if (!pts || pts.length < 2) return;

  // Step 1: Underlying bright orange henna stain dyed into the skin
  brush.set("marker", "#e8620c", weight * 0.92);
  safeSpline(pts, 0.5);
  brush.set("cpencil", "#ff7b1c", weight * 0.75);
  safeSpline(pts, 0.5);

  if (forceStainOnly) {
    // Deep burnt-orange core of the exposed stain + faint skin crease texture showing through
    brush.set("pen", "#cc4400", weight * 0.48);
    safeSpline(pts, 0.5);
    return;
  }

  // Step 2: Check sub-segments for intact raised paste vs flaked-off segments
  let run = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (!isHennaFlakedAt(p[0], p[1])) {
      run.push(p);
    } else {
      if (run.length >= 2) {
        renderRaisedPasteSegment(run, weight);
      }
      // Reinforce glowing tangerine stain on the exposed segment!
      if (i > 0) {
        brush.set("cpencil", "#ff6a08", weight * 0.82);
        brush.line(pts[i - 1][0], pts[i - 1][1], p[0], p[1]);
        brush.set("pen", "#d44200", weight * 0.42);
        brush.line(pts[i - 1][0], pts[i - 1][1], p[0], p[1]);
      }
      run = [];
    }
  }
  if (run.length >= 2) {
    renderRaisedPasteSegment(run, weight);
  }
}

function renderRaisedPasteSegment(pts, weight) {
  // 1. Tight drop shadow on skin (+2.0, +2.5 px) so the paste physically stands above the skin
  let shPts = pts.map(p => [p[0] + 2.0, p[1] + 2.5]);
  brush.set("pen", "#3b140d", weight * 0.85);
  safeSpline(shPts, 0.5);

  // 2. Thick marker body of dark olive-ebony henna paste
  brush.set("marker", "#1c220f", weight * 0.95);
  safeSpline(pts, 0.5);

  // 3. Fine pen sculptural ridge
  brush.set("pen", "#111608", weight * 0.62);
  safeSpline(pts, 0.5);

  // 4. Razor-sharp glossy specular highlight along the upper-left crest of the piped paste
  let hiPts = pts.map(p => [p[0] - 0.85, p[1] - 0.95]);
  brush.set("rotring", "#deeffc", weight * 0.28);
  safeSpline(hiPts, 0.5);
}

// Renders a piped 3D henna pearl dot (or exposed bright orange dot if flaked)
function drawHennaDot(x, y, r = 3.2, forceFlaked = false) {
  let flaked = forceFlaked || isHennaFlakedAt(x, y);

  // Bright orange stain halo in the skin
  brush.set("marker", "#f06810", r * 0.35);
  brush.circle(x, y, r * 0.9, 0.1);
  brush.set("cpencil", "#d94800", r * 0.25);
  brush.circle(x, y, r * 0.5, 0.1);

  if (!flaked) {
    // Drop shadow
    brush.set("pen", "#38120c", r * 0.28);
    brush.circle(x + 1.8, y + 2.2, r * 0.85, 0.1);

    // Raised dark paste dome
    brush.set("marker", "#1a200e", r * 0.38);
    brush.circle(x, y, r * 0.8, 0.1);
    brush.set("pen", "#101407", r * 0.25);
    brush.circle(x, y, r * 0.45, 0.08);

    // Pinpoint cool-white glossy catchlight on apex of paste bead
    brush.set("rotring", "#f0f9ff", 0.32);
    brush.line(x - r * 0.3, y - r * 0.3, x - r * 0.1, y - r * 0.35);
  }
}

// Renders a piped teardrop henna bud / leaf
function drawHennaTeardrop(x, y, angDeg, len = 14, w = 5) {
  let c = cos(angDeg), s = sin(angDeg);
  let nx = -s, ny = c;
  let loopPts = [
    [x, y],
    [x + c * len * 0.45 + nx * w * 0.5, y + s * len * 0.45 + ny * w * 0.5],
    [x + c * len, y + s * len],
    [x + c * len * 0.45 - nx * w * 0.5, y + s * len * 0.45 - ny * w * 0.5],
    [x, y]
  ];
  drawHennaStroke(loopPts, 0.52);
  drawHennaDot(x + c * len * 0.42, y + s * len * 0.42, w * 0.45);
}

function drawBridalMehndiDesign() {
  // =========================================================================
  // A. CENTRAL PALM MANDALA (LOTUS CHAKRI AT (748, 675))
  // =========================================================================
  let mCx = 748, mCy = 675;

  // Central spiral & bold raised dome
  drawHennaDot(mCx, mCy, 8.5);
  let spiralPts = [];
  for (let a = 0; a <= 720; a += 20) {
    let r = 4 + (a / 720) * 19;
    spiralPts.push([mCx + cos(a) * r, mCy + sin(a) * r]);
  }
  drawHennaStroke(spiralPts, 0.58);

  // Concentric rings around mandala
  for (let r of [26, 36, 48, 86, 95]) {
    let ringPts = [];
    for (let a = 0; a <= 360; a += 10) {
      ringPts.push([mCx + cos(a) * r, mCy + sin(a) * r]);
    }
    drawHennaStroke(ringPts, r === 86 ? 0.68 : 0.52);
  }

  // Scalloped Kangura frills on r = 36 and r = 95
  for (let ringDef of [{ r: 36, n: 20, h: 6.5 }, { r: 95, n: 32, h: 8.5 }]) {
    let stepA = 360 / ringDef.n;
    for (let i = 0; i < ringDef.n; i++) {
      let a1 = i * stepA;
      let aMid = (i + 0.5) * stepA;
      let a2 = (i + 1) * stepA;
      let scPts = [
        [mCx + cos(a1) * ringDef.r, mCy + sin(a1) * ringDef.r],
        [mCx + cos(aMid) * (ringDef.r + ringDef.h), mCy + sin(aMid) * (ringDef.r + ringDef.h)],
        [mCx + cos(a2) * ringDef.r, mCy + sin(a2) * ringDef.r]
      ];
      drawHennaStroke(scPts, 0.45);
    }
  }

  // 8 Ornate Lotus Petals between r = 48 and r = 84
  for (let p = 0; p < 8; p++) {
    let baseA = p * 45;
    let aL = baseA - 19;
    let aR = baseA + 19;
    let petalPts = [
      [mCx + cos(aL) * 48, mCy + sin(aL) * 48],
      [mCx + cos(baseA - 15) * 68, mCy + sin(baseA - 15) * 68],
      [mCx + cos(baseA) * 84, mCy + sin(baseA) * 84],
      [mCx + cos(baseA + 15) * 68, mCy + sin(baseA + 15) * 68],
      [mCx + cos(aR) * 48, mCy + sin(aR) * 48]
    ];
    drawHennaStroke(petalPts, 0.62);

    // Fine internal shading (varak) inside each lotus petal
    for (let f = 0.25; f <= 0.78; f += 0.16) {
      let rIn = lerp(50, 78, f);
      let span = lerp(15, 5, f);
      let shPts = [
        [mCx + cos(baseA - span) * rIn, mCy + sin(baseA - span) * rIn],
        [mCx + cos(baseA) * (rIn + 4), mCy + sin(baseA) * (rIn + 4)],
        [mCx + cos(baseA + span) * rIn, mCy + sin(baseA + span) * rIn]
      ];
      drawHennaStroke(shPts, 0.36);
    }
    drawHennaDot(mCx + cos(baseA) * 58, mCy + sin(baseA) * 58, 3.6);
  }

  // Outer halo of 32 piped pearl dots around the mandala (r = 109)
  for (let i = 0; i < 32; i++) {
    let a = i * (360 / 32) + 5.6;
    drawHennaDot(mCx + cos(a) * 109, mCy + sin(a) * 109, 3.8);
  }

  // =========================================================================
  // B. THENAR MOUNT PAISLEYS (AMBI) & LEAFY VINES (UPPER-RIGHT PALM)
  // =========================================================================
  // Large bridal paisley curling from mandala toward thumb base
  let ambiOutline = [
    [785, 588], [802, 545], [838, 528], [872, 545],
    [882, 585], [865, 622], [835, 636], [818, 618], [832, 602]
  ];
  drawHennaStroke(ambiOutline, 0.68);

  // Inner concentric paisley border & grid fill
  let ambiInner = [
    [795, 586], [810, 554], [838, 540], [862, 554],
    [870, 584], [855, 612], [832, 622]
  ];
  drawHennaStroke(ambiInner, 0.45);
  for (let k = 0; k < 5; k++) {
    let yLine = 552 + k * 13;
    drawHennaStroke([[808, yLine], [838, yLine - 6], [864, yLine + 2]], 0.36);
  }
  drawHennaDot(836, 610, 4.5);

  // Radiating teardrop buds & curls around the paisley crest
  for (let a = -135; a <= 45; a += 25) {
    let bx = 838 + cos(a) * 46;
    let by = 580 + sin(a) * 48;
    drawHennaTeardrop(bx, by, a, 15, 5.5);
  }

  // Connecting vine from thumb web into palm
  let webVine = [[658, 520], [702, 535], [742, 560], [785, 588]];
  drawHennaStroke(webVine, 0.58);
  for (let i = 0; i < 4; i++) {
    let vx = lerp(668, 768, i / 3);
    let vy = lerp(524, 575, i / 3);
    drawHennaTeardrop(vx, vy, -55, 13, 4.8);
    drawHennaTeardrop(vx + 6, vy + 4, 125, 12, 4.5);
  }

  // =========================================================================
  // C. HYPOTHENAR CHECKERED JALI LATTICE (LOWER PALM CUSHION)
  // =========================================================================
  let jCx = 782, jCy = 796;
  let uVec = [cos(-35), sin(-35)];
  let vVec = [cos(55), sin(55)];

  for (let i = -3; i <= 3; i++) {
    let s = i * 16;
    let lineU = [];
    let lineV = [];
    for (let j = -3; j <= 3; j++) {
      let t = j * 16;
      lineU.push([jCx + uVec[0] * s + vVec[0] * t, jCy + uVec[1] * s + vVec[1] * t]);
      lineV.push([jCx + uVec[0] * t + vVec[0] * s, jCy + uVec[1] * t + vVec[1] * s]);
    }
    drawHennaStroke(lineU, 0.45);
    drawHennaStroke(lineV, 0.45);
  }
  // Pearl dots at jali intersections & tiny 4-dot flowers in cell centers
  for (let i = -2; i <= 2; i++) {
    for (let j = -2; j <= 2; j++) {
      let ix = jCx + uVec[0] * (i * 16) + vVec[0] * (j * 16);
      let iy = jCy + uVec[1] * (i * 16) + vVec[1] * (j * 16);
      drawHennaDot(ix, iy, 3.0);
    }
  }

  // =========================================================================
  // D. ORNATE BRIDAL WRIST CUFF (CROSSING WRIST AT -42 DEG)
  // =========================================================================
  let wP1 = [790, 905];
  let wP2 = [942, 728];
  let wDx = wP2[0] - wP1[0], wDy = wP2[1] - wP1[1];
  let wLen = sqrt(wDx * wDx + wDy * wDy);
  let wTx = wDx / wLen, wTy = wDy / wLen;
  let wNx = -wTy, wNy = wTx; // Points down-right toward forearm

  function wristPt(u, v) {
    // Slight cylindrical curvature of the wrist
    let arch = -14 * sin(u * 180);
    return [
      lerp(wP1[0], wP2[0], u) + wNx * (v + arch),
      lerp(wP1[1], wP2[1], u) + wNy * (v + arch)
    ];
  }

  for (let vBand of [-18, -10, 12, 20, 46, 54, 78, 86]) {
    let bPts = [];
    for (let u = 0.02; u <= 0.98; u += 0.08) {
      bPts.push(wristPt(u, vBand));
    }
    drawHennaStroke(bPts, (vBand === -10 || vBand === 54) ? 0.65 : 0.48);
  }

  // Scallops & lotus arches inside the wrist cuff bands
  for (let k = 0; k < 14; k++) {
    let u1 = 0.04 + k * (0.92 / 14);
    let uMid = u1 + 0.46 / 14;
    let u2 = u1 + 0.92 / 14;

    // Upper cuff scallops pointing toward palm
    drawHennaStroke([wristPt(u1, -18), wristPt(uMid, -28), wristPt(u2, -18)], 0.44);
    drawHennaDot(wristPt(uMid, -34)[0], wristPt(uMid, -34)[1], 3.2);

    // Zigzag lehariya motif inside band 1 (-10 to 12)
    drawHennaStroke([wristPt(u1, 10), wristPt(uMid, -8), wristPt(u2, 10)], 0.45);
    drawHennaDot(wristPt(uMid, 4)[0], wristPt(uMid, 4)[1], 3.0);
  }

  // Ornate domes in band 2 (20 to 46)
  for (let k = 0; k < 7; k++) {
    let u1 = 0.05 + k * (0.90 / 7);
    let uMid = u1 + 0.45 / 7;
    let u2 = u1 + 0.90 / 7;
    drawHennaStroke([wristPt(u1, 20), wristPt(uMid, 44), wristPt(u2, 20)], 0.56);
    drawHennaStroke([wristPt(u1 + 0.02, 20), wristPt(uMid, 36), wristPt(u2 - 0.02, 20)], 0.40);
    drawHennaDot(wristPt(uMid, 27)[0], wristPt(uMid, 27)[1], 3.8);
  }

  // Crisscross lattice in band 3 (54 to 78)
  for (let k = 0; k < 10; k++) {
    let u1 = 0.05 + k * (0.90 / 10);
    let u2 = u1 + 0.90 / 10;
    drawHennaStroke([wristPt(u1, 54), wristPt(u2, 78)], 0.42);
    drawHennaStroke([wristPt(u2, 54), wristPt(u1, 78)], 0.42);
  }

  // =========================================================================
  // E. ALL 5 DIGITS: SOLID STAINED FINGERTIP CAPS + 3D CROSS-CONTOUR BANDS
  // =========================================================================
  for (let fIdx = 0; fIdx < fingers.length; fIdx++) {
    let fg = fingers[fIdx];

    // 1. Solid Bridal Fingertip Henna Cap (t from capStart to 1.0)
    let capPoly = getFingerPolygon(fg, fg.capStart, 1.0, -0.96, 0.96, 14);

    // Vivid glowing tangerine-saffron skin stain base on the fingertip!
    brush.noStroke();
    brush.wash("#e65808", 215);
    drawOrganicPoly(capPoly, 0.45);
    brush.noWash();

    brush.fillBleed(0.10, "in");
    brush.fillTexture(0.45, 0.3);
    brush.fill("#c43800", 110);
    drawOrganicPoly(getFingerPolygon(fg, fg.capStart + 0.03, 0.99, -0.5, 0.95, 10), 0.45);
    brush.noFill();

    // Re-etch fine papillary skin ridges over the orange fingertip stain so it looks dyed into the skin
    brush.set("2H", "#8f2800", 0.24);
    for (let t = fg.capStart + 0.02; t <= 0.96; t += 0.03) {
      let rPts = [];
      for (let s = -0.75; s <= 0.75; s += 0.25) {
        rPts.push(fingerPt(fg, t - 0.015 * (1 - s * s), s));
      }
      safeSpline(rPts, 0.5);
    }

    // Thick cracked dark henna paste patches still clinging to the upper/distal half of the fingertip cap
    for (let t = fg.capStart + 0.04; t <= 0.96; t += 0.028) {
      let cPts = [];
      for (let s = -0.82; s <= 0.82; s += 0.22) {
        let p = fingerPt(fg, t, s);
        // Leave cracked gaps near the DIP joint edge so bright orange stain shines through!
        if (t > fg.capStart + 0.06 || sin(s * 180 + fIdx * 50) > -0.2) {
          cPts.push(p);
        } else {
          if (cPts.length >= 2) renderRaisedPasteSegment(cPts, 0.72);
          cPts = [];
        }
      }
      if (cPts.length >= 2) renderRaisedPasteSegment(cPts, 0.72);
    }

    // Border ring & scalloped fringe at the base of the fingertip cap (t = fg.capStart)
    let capBorder = [];
    for (let s = -0.92; s <= 0.92; s += 0.18) {
      capBorder.push(fingerPt(fg, fg.capStart, s));
    }
    drawHennaStroke(capBorder, 0.62);

    let capBorder2 = [];
    for (let s = -0.92; s <= 0.92; s += 0.18) {
      capBorder2.push(fingerPt(fg, fg.capStart - 0.025, s));
    }
    drawHennaStroke(capBorder2, 0.48);

    for (let s = -0.75; s <= 0.75; s += 0.30) {
      let dp = fingerPt(fg, fg.capStart - 0.052, s);
      drawHennaDot(dp[0], dp[1], 3.2);
    }

    // 2. Joint Rings & Scalloped Bands at MCP (0.04), PIP (joints[0]), and DIP (joints[1])
    for (let jt of [0.05, fg.joints[0], fg.joints[1]]) {
      for (let d of [-0.018, 0.018]) {
        let rPts = [];
        for (let s = -0.90; s <= 0.90; s += 0.18) {
          rPts.push(fingerPt(fg, jt + d, s));
        }
        drawHennaStroke(rPts, 0.52);
      }
      // Scalloped arches along joint ring
      for (let s = -0.80; s < 0.75; s += 0.32) {
        let sc = [
          fingerPt(fg, jt - 0.018, s),
          fingerPt(fg, jt - 0.042, s + 0.16),
          fingerPt(fg, jt - 0.018, s + 0.32)
        ];
        drawHennaStroke(sc, 0.42);
      }
    }

    // 3. Intricate Phalanx Motifs between joints (Proximal: 0.10..0.31, Middle: 0.43..0.63)
    // Proximal phalanx: graceful S-vine with paired leaves and spiral buds
    let vinePts = [];
    for (let k = 0; k <= 10; k++) {
      let t = lerp(0.09, 0.31, k / 10);
      let s = 0.42 * sin((k / 10) * 360);
      vinePts.push(fingerPt(fg, t, s));
    }
    drawHennaStroke(vinePts, 0.54);

    for (let t of [0.13, 0.19, 0.25, 0.30]) {
      let pL = fingerPt(fg, t, -0.45);
      let pR = fingerPt(fg, t, 0.45);
      drawHennaDot(pL[0], pL[1], 3.4);
      drawHennaDot(pR[0], pR[1], 3.4);
      let leafL = [fingerPt(fg, t - 0.02, -0.15), fingerPt(fg, t, -0.68), fingerPt(fg, t + 0.02, -0.25)];
      let leafR = [fingerPt(fg, t - 0.02, 0.15), fingerPt(fg, t, 0.68), fingerPt(fg, t + 0.02, 0.25)];
      drawHennaStroke(leafL, 0.44);
      drawHennaStroke(leafR, 0.44);
    }

    // Middle phalanx: Diagonal jali lattice & central mandala flower
    if (fIdx % 2 === 1) {
      // Crisscross diamond lattice on Index & Ring middle phalanges
      for (let k = 0; k < 4; k++) {
        let t1 = 0.43 + k * 0.05;
        let t2 = t1 + 0.05;
        drawHennaStroke([fingerPt(fg, t1, -0.75), fingerPt(fg, t2, 0.75)], 0.42);
        drawHennaStroke([fingerPt(fg, t1, 0.75), fingerPt(fg, t2, -0.75)], 0.42);
      }
      for (let t of [0.455, 0.505, 0.555, 0.605]) {
        let cp = fingerPt(fg, t, 0);
        drawHennaDot(cp[0], cp[1], 3.0);
      }
    } else {
      // Concentric arch dome / rosette on Thumb, Middle, and Pinky middle phalanges
      let cPos = fingerPt(fg, 0.53, 0);
      drawHennaDot(cPos[0], cPos[1], 4.2);
      for (let rT of [0.045, 0.075]) {
        let domePts = [];
        for (let a = 0; a <= 360; a += 30) {
          let t = 0.53 + cos(a) * rT;
          let s = sin(a) * (rT * 8.5);
          domePts.push(fingerPt(fg, t, s));
        }
        drawHennaStroke(domePts, 0.45);
      }
      for (let a = 0; a < 360; a += 45) {
        let dp = fingerPt(fg, 0.53 + cos(a) * 0.095, sin(a) * 0.72);
        drawHennaDot(dp[0], dp[1], 2.8);
      }
    }
  }
}

