// Point-to-segment distance and closest parameter t along capsule
function distToSegmentInfo(px, py, ax, ay, bx, by) {
  let dx = bx - ax;
  let dy = by - ay;
  let len2 = dx * dx + dy * dy;
  let t = 0;
  if (len2 > 0.0001) {
    t = ((px - ax) * dx + (py - ay) * dy) / len2;
    t = constrain(t, 0, 1);
  }
  let cx = ax + t * dx;
  let cy = ay + t * dy;
  let d = dist(px, py, cx, cy);
  let tang = atan2(dy, dx);
  return { d, t, cx, cy, tang };
}

// Check if point is inside either sculpted ear
function sampleEars(px, py) {
  // Upper/Right Ear: base (385,435)-(465,470), apex (445,340)
  let e1 = pointInTriangle(px, py, 382, 438, 468, 472, 446, 336);
  if (e1.inside) {
    return {
      inside: true,
      name: "ear_right",
      priority: 9,
      nx: (px - 428) / 55,
      ny: (py - 418) / 65 - 0.35,
      nz: 0.75,
      flowAngle: -68,
      edgeDist: e1.edgeDist
    };
  }
  // Lower/Left Ear: base (275,485)-(335,430), apex (242,392)
  let e2 = pointInTriangle(px, py, 272, 488, 338, 428, 240, 390);
  if (e2.inside) {
    return {
      inside: true,
      name: "ear_left",
      priority: 8,
      nx: (px - 295) / 50 - 0.2,
      ny: (py - 445) / 55 - 0.3,
      nz: 0.72,
      flowAngle: -135,
      edgeDist: e2.edgeDist
    };
  }
  return { inside: false };
}

function pointInTriangle(px, py, x1, y1, x2, y2, x3, y3) {
  let denom = (y2 - y3) * (x1 - x3) + (x3 - x2) * (y1 - y3);
  let a = ((y2 - y3) * (px - x3) + (x3 - x2) * (py - y3)) / denom;
  let b = ((y3 - y1) * (px - x3) + (x1 - x3) * (py - y3)) / denom;
  let c = 1 - a - b;
  if (a >= 0 && b >= 0 && c >= 0) {
    let minBary = min(a, min(b, c));
    return { inside: true, edgeDist: minBary * 95 };
  }
  return { inside: false, edgeDist: 0 };
}

// Query 3D surface normal, anatomical part, and flow angle at (px, py)
function sampleCatSurface(px, py) {
  // Check central breathing hollow between paws, chest, and thigh
  let hollowDist = dist(px, py, 578, 578);

  let earHit = sampleEars(px, py);
  if (earHit.inside) {
    return earHit;
  }

  let bestPart = null;
  let bestScore = -999;

  for (let cap of anatomyCapsules) {
    let pts = cap.pts;
    for (let i = 0; i < pts.length - 1; i++) {
      let A = pts[i];
      let B = pts[i + 1];
      let info = distToSegmentInfo(px, py, A.x, A.y, B.x, B.y);
      let r = lerp(A.r, B.r, info.t);
      // Organic noise modulation along silhouette
      let nMod = (noise(px * 0.012, py * 0.012) - 0.5) * 10;
      let effR = r + nMod;
      if (info.d <= effR) {
        let u = info.d / effR; // 0 at spine centerline, 1 at silhouette edge
        let nz = sqrt(max(0.02, 1 - u * u));
        // Score prioritizes anatomical layering + smooth blending
        let score = cap.priority * 10 + nz * 6;
        if (score > bestScore) {
          bestScore = score;
          let nx = (px - info.cx) / effR;
          let ny = (py - info.cy) / effR;
          bestPart = {
            inside: true,
            name: cap.name,
            priority: cap.priority,
            nx: nx,
            ny: ny,
            nz: nz,
            flowAngle: info.tang,
            edgeDist: effR - info.d,
            cx: info.cx,
            cy: info.cy,
            u: u
          };
        }
      }
    }
  }

  // Carve out the intimate dark velvet breathing pocket in the center
  if (bestPart && bestPart.name === "belly" && hollowDist < 66) {
    return { inside: false };
  }

  if (!bestPart) {
    return { inside: false };
  }

  // Refine fur flow angle for head (radiating from nose bridge) and haunch
  if (bestPart.name === "head") {
    let noseX = 369,
      noseY = 632;
    let angFromNose = atan2(py - noseY, px - noseX);
    bestPart.flowAngle = angFromNose;
  }

  return bestPart;
}

// Compute Scythian Spiral & Comma Tabby Pattern + Swirl Flow Deflection
function sampleScythianPattern(px, py, baseFlowAngle) {
  let stripeStrength = 0;
  let embossedEdge = 0; // Positive on top-lit bevel of raised gold stripes
  let swirlAngle = baseFlowAngle;

  // 1. Check Scythian Spirals
  for (let sp of spirals) {
    let dx = px - sp.cx;
    let dy = py - sp.cy;
    let r = sqrt(dx * dx + dy * dy);
    if (r < sp.maxR && r > 4) {
      let theta = atan2(dy, dx); // -180 to 180
      let normR = r / sp.maxR;
      // Spiral equation: expected angle wraps with radius
      let targetTheta = sp.phase + sp.dir * normR * sp.turns * 360;
      let diff = ((theta - targetTheta + 5400) % 360) - 180;
      let angularWidth = (sp.thickness / max(18, r)) * 57.3 * (1.15 - 0.55 * normR);
      if (abs(diff) < angularWidth) {
        let s = cos((diff / angularWidth) * 90);
        stripeStrength = max(stripeStrength, s * (1 - 0.15 * normR));
        // Bevel highlight on the outer/upper side of the spiral groove
        embossedEdge += sin((diff / angularWidth) * 180) * 0.65;
      }
      // Deflect fur flow smoothly into the spiral scroll
      let spiralTangent = theta + sp.dir * 72;
      let blend = pow(1 - normR, 1.3) * 0.78;
      swirlAngle = lerpAngleDeg(swirlAngle, spiralTangent, blend);
    }
  }

  // 2. Check Scythian Comma Stripes
  for (let cm of commas) {
    // Sample 8 points along quadratic Bezier comma curve
    let minDist = 999;
    let bestT = 0;
    let bestTang = 0;
    let bestCy = 0;
    for (let k = 0; k <= 8; k++) {
      let t = k / 8;
      let it = 1 - t;
      let bx = it * it * cm.x1 + 2 * it * t * cm.cx + t * t * cm.x2;
      let by = it * it * cm.y1 + 2 * it * t * cm.cy + t * t * cm.y2;
      let d = dist(px, py, bx, by);
      if (d < minDist) {
        minDist = d;
        bestT = t;
        bestCy = by;
        let tx = 2 * it * (cm.cx - cm.x1) + 2 * t * (cm.x2 - cm.cx);
        let ty = 2 * it * (cm.cy - cm.y1) + 2 * t * (cm.y2 - cm.cy);
        bestTang = atan2(ty, tx);
      }
    }
    // Comma profile: round bulbous head at t=0.15, tapering to a sharp point at t=1
    let wAtT = cm.w * sin(pow(bestT, 0.55) * 180) * (1.15 - 0.45 * bestT);
    if (minDist < wAtT && wAtT > 1) {
      let u = minDist / wAtT;
      let s = cos(u * 90);
      if (s > stripeStrength) {
        stripeStrength = s;
        // Top bevel catches light if py < bestCy
        embossedEdge = ((bestCy - py) / wAtT) * 0.8;
      }
      swirlAngle = lerpAngleDeg(swirlAngle, bestTang, s * 0.65);
    }
  }

  // 3. Dark tip of the tail
  let tailTipDist = dist(px, py, 315, 575);
  if (tailTipDist < 55 && px < 355 && py > 545 && py < 625) {
    stripeStrength = max(stripeStrength, map(tailTipDist, 0, 55, 0.9, 0, true));
  }

  return {
    stripe: constrain(stripeStrength, 0, 1),
    bevel: constrain(embossedEdge, -1, 1),
    flowAngle: swirlAngle
  };
}

function lerpAngleDeg(a, b, amt) {
  let diff = ((((b - a) % 360) + 540) % 360) - 180;
  return a + diff * amt;
}

// Find closest Voronoi hammer facet for repoussé metal normal perturbation
function sampleHammerFacet(px, py) {
  let d1 = 999999;
  let d2 = 999999;
  let best = hammerFacets[0];
  for (let i = 0; i < hammerFacets.length; i++) {
    let f = hammerFacets[i];
    let dx = px - f.x;
    let dy = py - f.y;
    let dSq = dx * dx + dy * dy;
    if (dSq < d1) {
      d2 = d1;
      d1 = dSq;
      best = f;
    } else if (dSq < d2) {
      d2 = dSq;
    }
  }
  let ridge = exp(-abs(sqrt(d2) - sqrt(d1)) * 0.35);
  return { facet: best, ridge: ridge };
}

// Compute full hammered-metal + pastel-gold lighting color at (px, py)
function computeCatColor(px, py, surf, pat, facetInfo) {
  // Perturb normal with hammered metal facet + embossed stripe bevel
  let nx = surf.nx + facetInfo.facet.dnx * 0.65;
  let ny = surf.ny + facetInfo.facet.dny * 0.65 - pat.bevel * 0.28;
  let nz = surf.nz;
  let nLen = sqrt(nx * nx + ny * ny + nz * nz);
  nx /= nLen;
  ny /= nLen;
  nz /= nLen;

  // Strong Top Light direction: slightly from top-right/top-center
  let lx = 0.08,
    ly = -0.80,
    lz = 0.59;
  let ndotl = constrain(nx * lx + ny * ly + nz * lz, 0, 1);

  // Hammered metal specular reflection (half-vector with viewer [0,0,1])
  let hx = lx,
    hy = ly,
    hz = lz + 1.0;
  let hLen = sqrt(hx * hx + hy * hy + hz * hz);
  hx /= hLen;
  hy /= hLen;
  hz /= hLen;
  let ndoth = constrain(nx * hx + ny * hy + nz * hz, 0, 1);
  let spec = pow(ndoth, 11) + facetInfo.ridge * 0.22 * pow(ndotl, 2);

  // Boost specular on upper haunch, shoulder hump, and ear rims
  if (surf.name === "haunch" && py < 565 && px > 760) {
    spec += 0.32 * pow(ndotl, 2);
  }
  if (surf.name === "ear_right" || surf.name === "ear_left") {
    spec += 0.28;
  }

  // Darken inside Scythian spiral & comma tabby stripes (raw sienna / burnished bronze)
  let s = pat.stripe;
  let tone = ndotl * (1 - 0.48 * s) + spec * (1 - 0.55 * s);

  // Palette mapping: Deep Bronze -> Raw Sienna -> Burnished Ochre -> Pastel Peach-Gold -> Naples Yellow -> White-Gold
  if (tone > 1.12) {
    return "#fffdf0"; // Sharp White-Gold highlight
  } else if (tone > 0.88) {
    return "#fff3be"; // Luminous White-Gold / Pale Naples
  } else if (tone > 0.68) {
    return facetInfo.facet.warmth > 0 ? "#fae194" : "#f6d483"; // Pastel Naples Yellow
  } else if (tone > 0.52) {
    return facetInfo.facet.warmth > 0 ? "#f2c185" : "#e5ab61"; // Soft Pastel Peach-Ochre
  } else if (tone > 0.36) {
    return s > 0.4 ? "#b86728" : "#d68e3b"; // Burnished Ochre / Light Sienna
  } else if (tone > 0.22) {
    return s > 0.45 ? "#8c4416" : "#ae5d24"; // Raw Sienna
  } else {
    // Underside reflected pastel lavender-bronze sheen vs deep burnished umber
    if (ny > 0.55 && s < 0.35) {
      return "#9e7c68";
    }
    return s > 0.5 ? "#4a200a" : "#6e3412";
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm luminous champagne-ivory paper ground (enables glowing translucent watercolor on the cat)
  background("#fbf3e2");

  // =========================================================================
  // 1. LAYERED WATERCOLOR UNDERPAINTING ON THE CAT (Batched by pigment)
  // =========================================================================
  drawCatWatercolorWashes();

  // =========================================================================
  // 2. HAMMERED METAL FACETS (Marker planes & chased gold bevels)
  // =========================================================================
  drawHammeredMetalFacets();

  // =========================================================================
  // 3. DEEP BLACK VELVET BACKGROUND & DRAPERY FOLDS
  // =========================================================================
  drawDeepBlackVelvet();

  // =========================================================================
  // 4. SCYTHIAN SPIRALS & COMMA STRIPES (Raw Sienna & Burnished Ochre Relief)
  // =========================================================================
  drawScythianSpiralsAndCommas();

  // =========================================================================
  // 5. HYPERREALISTIC REAL FUR (12,500+ Directional Hairs & Metallic Sheen)
  // =========================================================================
  drawHyperrealisticFur();

  // =========================================================================
  // 6. FOCAL ANATOMY: EARS, SLEEPING EYE, NOSE, PAW PADS & WHITE-GOLD HIGHLIGHTS
  // =========================================================================
  drawEarsHeadAndPawPads();

  // =========================================================================
  // 7. FINE PEN CLAWS & WHISKERS (Rotring & Pen Details)
  // =========================================================================
  drawFinePenClawsAndWhiskers();

  noLoop();
}

// ---------------------------------------------------------------------------
// STEP 1: LAYERED WATERCOLOR WASHES (Batched by Color for Performance & Bleed)
// ---------------------------------------------------------------------------
function drawCatWatercolorWashes() {
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.58, 0.38);

  // Batch 1: Pastel Naples Yellow (#fae39c) across top-lit dorsal arch, shoulder, haunch
  brush.fill("#fae39c", 115);
  brush.circle(490, 330, 145, 0.25);
  brush.circle(645, 285, 140, 0.25);
  brush.circle(795, 355, 140, 0.25);
  brush.circle(845, 485, 148, 0.25);
  brush.circle(365, 480, 108, 0.25);

  // Batch 2: Soft Pastel Peach-Ochre (#f3c388) across mid-body, cheek, forelegs, tail
  brush.fill("#f3c388", 120);
  brush.circle(425, 565, 105, 0.28);
  brush.circle(555, 435, 130, 0.28);
  brush.circle(735, 520, 135, 0.28);
  brush.circle(835, 615, 135, 0.28);
  brush.circle(615, 920, 68, 0.22);
  brush.circle(455, 905, 64, 0.22);
  brush.circle(325, 815, 58, 0.22);

  // Batch 3: Burnished Ochre (#d9913d) for sculptural depth & muscular valleys
  brush.fill("#d9913d", 115);
  brush.circle(505, 375, 112, 0.3);
  brush.circle(810, 560, 125, 0.3);
  brush.circle(760, 690, 105, 0.3);
  brush.circle(475, 635, 88, 0.3);
  brush.circle(755, 855, 66, 0.25);
  brush.circle(275, 695, 48, 0.25);

  // Batch 4: Raw Sienna (#a85820) in deep Scythian spiral channels & underside shadows
  brush.fill("#a85820", 110);
  brush.circle(492, 372, 68, 0.32);
  brush.circle(812, 555, 76, 0.32);
  brush.circle(650, 525, 92, 0.35);
  brush.circle(520, 560, 82, 0.35);
  brush.circle(685, 665, 74, 0.32);

  // Batch 5: Soft Pastel Rose-Coral (#f0aba0) on paw pad zones, nose & inner ears
  brush.fill("#f0aba0", 125);
  brush.circle(625, 675, 46, 0.2);
  brush.circle(485, 678, 44, 0.2);
  brush.circle(370, 628, 28, 0.2);
  brush.circle(428, 422, 34, 0.2);

  brush.noFill();
}

// ---------------------------------------------------------------------------
// STEP 2: HAMMERED METAL FACETS (Marker & Chased Gold Planes)
// ---------------------------------------------------------------------------
function drawHammeredMetalFacets() {
  // Sample a dense staggered grid of hammered repoussé facets across the cat
  let step = 18;
  for (let y = 140; y <= 990; y += step) {
    for (let x = 210; x <= 1020; x += step) {
      let px = x + random(-5, 5);
      let py = y + random(-5, 5);
      let surf = sampleCatSurface(px, py);
      if (!surf.inside) continue;

      let pat = sampleScythianPattern(px, py, surf.flowAngle);
      let facetInfo = sampleHammerFacet(px, py);
      let col = computeCatColor(px, py, surf, pat, facetInfo);

      // Draw flat marker plane oriented along hammered facet & fur flow
      let ang = pat.flowAngle + facetInfo.facet.dnx * 35;
      let len = map(surf.nz, 0, 1, 10, 22);
      let dx = (len * 0.5) * cos(ang);
      let dy = (len * 0.5) * sin(ang);

      brush.set("marker", col, map(surf.nz, 0, 1, 1.1, 2.2));
      brush.line(px - dx, py - dy, px + dx, py + dy);

      // Add chased-gold bevel stroke on facet ridges facing the strong top light
      if (facetInfo.ridge > 0.45 && surf.ny < 0.2) {
        let bevelCol = surf.ny < -0.35 ? "#fffbe6" : "#fae298";
        brush.set("chased_gold", bevelCol, 0.9);
        brush.line(px - dx * 0.8, py - dy * 0.8 - 2, px + dx * 0.8, py + dy * 0.8 - 2);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// STEP 3: DEEP BLACK VELVET BACKGROUND & PLUSH DRAPERY FOLDS
// ---------------------------------------------------------------------------
function drawDeepBlackVelvet() {
  brush.noStroke();
  brush.noFill();

  // 1. Opaque deep obsidian velvet wash around the cat's outer contour (24 wedges)
  let n = outerContour.length;
  let wedgeSize = 5;
  for (let i = 0; i < n; i += wedgeSize) {
    brush.wash("#08070c", 255);
    brush.beginShape(0);
    for (let k = 0; k <= wedgeSize; k++) {
      let pt = outerContour[(i + k) % n];
      brush.vertex(pt.x, pt.y);
    }
    // Project outer arc to far outside canvas boundary
    let aEnd = outerContour[(i + wedgeSize) % n].ang;
    let aMid = outerContour[(i + floor(wedgeSize / 2)) % n].ang;
    let aStart = outerContour[i].ang;
    let rFar = 1050;
    brush.vertex(600 + rFar * cos(aEnd), 600 + rFar * sin(aEnd));
    brush.vertex(600 + rFar * cos(aMid), 600 + rFar * sin(aMid));
    brush.vertex(600 + rFar * cos(aStart), 600 + rFar * sin(aStart));
    brush.endShape(true);
  }

  // 2. Opaque deep velvet wash in the intimate central breathing pocket (578, 578)
  brush.wash("#09070e", 255);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 30) {
    let r = 68 + 8 * sin(a * 3);
    brush.vertex(578 + r * cos(a), 578 + r * sin(a));
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Sculpted velvet drapery folds radiating from the weight of the golden cat
  let foldAngles = [-145, -105, -62, -22, 18, 55, 98, 138, 175];
  for (let fa of foldAngles) {
    for (let s = 0; s < 55; s++) {
      let r1 = random(385, 760);
      let r2 = r1 + random(45, 110);
      let spread = random(-11, 11);
      let a1 = fa + spread + 6 * sin(r1 * 0.02);
      let a2 = fa + spread + 6 * sin(r2 * 0.02);
      let x1 = 600 + r1 * cos(a1);
      let y1 = 600 + r1 * sin(a1);
      let x2 = 600 + r2 * cos(a2);
      let y2 = 600 + r2 * sin(a2);

      if (x1 < -20 || x1 > 1220 || y1 < -20 || y1 > 1220) continue;
      if (sampleCatSurface(x1, y1).inside || sampleCatSurface(x2, y2).inside) continue;

      // Crushed velvet catches subtle pastel midnight-plum sheen on fold crests
      let sheen = abs(spread) < 4.5;
      let vCol = sheen ? (y1 < 600 ? "#282238" : "#1c1828") : "#0c0a12";
      brush.set("marker", vCol, random(1.8, 3.6));
      brush.line(x1, y1, x2, y2);

      if (sheen && random() < 0.5) {
        brush.set("charcoal", "#352d47", random(0.6, 1.2));
        brush.line(x1, y1, (x1 + x2) * 0.5, (y1 + y2) * 0.5);
      }
    }
  }

  // 4. Tactile velvet pile texture across the background & deep contact shadow around cat
  for (let i = 0; i < 1600; i++) {
    let vx = random(15, 1185);
    let vy = random(15, 1185);
    if (sampleCatSurface(vx, vy).inside) continue;

    let dCenter = dist(vx, vy, 600, 600);
    let ang = atan2(vy - 600, vx - 600) + 90 + random(-25, 25);
    let len = random(14, 34);
    let x2 = vx + len * cos(ang);
    let y2 = vy + len * sin(ang);
    if (sampleCatSurface(x2, y2).inside) continue;

    // Deep abyssal occlusion halo right next to the cat's body
    let col = dCenter < 445 ? "#050408" : random(["#09080e", "#110e19", "#181423", "#06050a"]);
    brush.set(i % 4 === 0 ? "velvet_pile" : "charcoal", col, random(0.8, 1.8));
    brush.line(vx, vy, x2, y2);
  }
}

// ---------------------------------------------------------------------------
// STEP 4: SCYTHIAN SPIRALS & COMMA STRIPES (Embossed Gold & Raw Sienna)
// ---------------------------------------------------------------------------
function drawScythianSpiralsAndCommas() {
  // 1. Trace the spiral grooves and their hammered gold upper rims
  for (let sp of spirals) {
    let steps = 110;
    let ptsCore = [];
    let ptsRim = [];
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let r = lerp(6, sp.maxR, u);
      let theta = sp.phase + sp.dir * u * sp.turns * 360;
      let sx = sp.cx + r * cos(theta);
      let sy = sp.cy + r * sin(theta);
      if (sampleCatSurface(sx, sy).inside) {
        ptsCore.push([sx, sy, sin(u * 180) * 1.3 + 0.3]);
        ptsRim.push([sx, sy - 5.5, sin(u * 180) * 1.1 + 0.2]);
      }
    }
    if (ptsRim.length > 3) {
      brush.set("marker", "#fae296", 1.5);
      brush.spline(ptsRim, 0.5);
    }
    if (ptsCore.length > 3) {
      brush.set("marker", "#8c4416", 1.8);
      brush.spline(ptsCore, 0.5);
      brush.set("cpencil", "#4e2209", 1.1);
      brush.spline(ptsCore, 0.5);
    }
  }

  // 2. Trace the stylised Scythian Comma Stripes with raw sienna core & gold bevel
  for (let cm of commas) {
    let ptsCore = [];
    let ptsGold = [];
    for (let k = 0; k <= 10; k++) {
      let t = k / 10;
      let it = 1 - t;
      let bx = it * it * cm.x1 + 2 * it * t * cm.cx + t * t * cm.x2;
      let by = it * it * cm.y1 + 2 * it * t * cm.cy + t * t * cm.y2;
      let p = sin(pow(t, 0.55) * 180) * 1.4 + 0.15;
      ptsCore.push([bx, by, p]);
      ptsGold.push([bx, by - 4.5, p * 0.85]);
    }
    brush.set("marker", "#f7dc8a", map(cm.w, 12, 25, 0.9, 1.7));
    brush.spline(ptsGold, 0.45);

    brush.set("marker", "#964a19", map(cm.w, 12, 25, 1.1, 2.1));
    brush.spline(ptsCore, 0.45);

    brush.set("2B", "#52230a", map(cm.w, 12, 25, 0.7, 1.3));
    brush.spline(ptsCore, 0.45);
  }
}

// ---------------------------------------------------------------------------
// STEP 5: HYPERREALISTIC FUR RENDERING (12,500+ Real Swirling Hairs)
// ---------------------------------------------------------------------------
function drawHyperrealisticFur() {
  // Pass A: Plush Undercoat (~3,600 soft directional strokes)
  for (let i = 0; i < 3600; i++) {
    let rx = random(210, 1020);
    let ry = random(140, 995);
    let surf = sampleCatSurface(rx, ry);
    if (!surf.inside) continue;

    let pat = sampleScythianPattern(rx, ry, surf.flowAngle);
    let facetInfo = sampleHammerFacet(rx, ry);
    let col = computeCatColor(rx, ry, surf, pat, facetInfo);

    let ang = pat.flowAngle + random(-8, 8);
    let len = random(13, 24);
    let x2 = rx + len * cos(ang);
    let y2 = ry + len * sin(ang);

    brush.set("cpencil", col, random(0.65, 1.15));
    brush.line(rx, ry, x2, y2);
  }

  // Pass B: Individual Real Guard Hairs (~6,500 razor-sharp curved hairs)
  for (let i = 0; i < 6500; i++) {
    let rx = random(210, 1020);
    let ry = random(140, 995);
    let surf = sampleCatSurface(rx, ry);
    if (!surf.inside) continue;

    let pat = sampleScythianPattern(rx, ry, surf.flowAngle);
    let facetInfo = sampleHammerFacet(rx, ry);
    let col = computeCatColor(rx, ry, surf, pat, facetInfo);

    let ang1 = pat.flowAngle + (noise(rx * 0.025, ry * 0.025) - 0.5) * 18;
    let stepLen = random(8, 15);
    let mx = rx + stepLen * cos(ang1);
    let my = ry + stepLen * sin(ang1);

    let pat2 = sampleScythianPattern(mx, my, surf.flowAngle);
    let ang2 = pat2.flowAngle + (noise(mx * 0.025, my * 0.025) - 0.5) * 18;
    let ex = mx + stepLen * cos(ang2);
    let ey = my + stepLen * sin(ang2);

    // Avoid spilling far outside the silhouette unless creating furry rim edge
    if (surf.edgeDist > 16 && !sampleCatSurface(ex, ey).inside) continue;

    brush.set("fine_hair", col, random(0.55, 1.05));
    brush.spline(
      [
        [rx, ry, 0.3],
        [mx, my, 1.0],
        [ex, ey, 0.1]
      ],
      0.4
    );
  }

  // Pass C: Golden Rim-Lit Silhouette Guard Hairs extending over the Black Velvet
  for (let pt of outerContour) {
    for (let k = 0; k < 7; k++) {
      let jitterA = pt.ang + random(-2.2, 2.2);
      let rBase = pt.r - random(2, 10);
      let sx = 600 + rBase * cos(jitterA);
      let sy = 600 + rBase * sin(jitterA);
      let surf = sampleCatSurface(sx, sy);
      if (!surf.inside) continue;

      let pat = sampleScythianPattern(sx, sy, surf.flowAngle);
      let outAng = lerpAngleDeg(pat.flowAngle, jitterA, 0.38) + random(-10, 10);
      let hLen = random(14, 26);
      let ex = sx + hLen * cos(outAng);
      let ey = sy + hLen * sin(outAng);

      // Strong top light gives top silhouette hairs a gleaming white-gold / Naples yellow rim
      let rimCol =
        sy < 450
          ? "#fffbe6"
          : sy < 680
            ? "#fae296"
            : pat.stripe > 0.5
              ? "#b56426"
              : "#e6aa5e";
      brush.set("fine_hair", rimCol, random(0.5, 0.9));
      brush.line(sx, sy, ex, ey);
    }
  }

  // Pass D: Hammered Metal Specular Hair Gleams under Strong Top Light (~2,400 hairs)
  for (let i = 0; i < 2400; i++) {
    let rx = random(235, 995);
    let ry = random(145, 760);
    let surf = sampleCatSurface(rx, ry);
    if (!surf.inside) continue;

    // Concentrate on top-facing surfaces, haunch scroll, shoulder crest, and brow
    if (surf.ny > 0.15 && !(surf.name === "haunch" && rx > 770 && ry < 610)) continue;

    let pat = sampleScythianPattern(rx, ry, surf.flowAngle);
    if (pat.stripe > 0.45 && pat.bevel < 0.2) continue;

    let facetInfo = sampleHammerFacet(rx, ry);
    let isWhiteGold =
      (surf.ny < -0.42 && facetInfo.ridge > 0.25) ||
      (surf.name === "haunch" && rx > 785 && ry > 390 && ry < 545 && surf.nz > 0.55) ||
      (surf.name === "back" && ry < 265 && surf.nz > 0.5);

    let gleamCol = isWhiteGold ? "#fffef2" : random(["#fff5c2", "#fae39a", "#f5ce7e"]);
    let ang = pat.flowAngle + random(-5, 5);
    let len = random(10, 19);

    brush.set("fine_hair", gleamCol, isWhiteGold ? random(0.65, 1.1) : random(0.45, 0.85));
    brush.line(rx, ry, rx + len * cos(ang), ry + len * sin(ang));
  }
}

// ---------------------------------------------------------------------------
// STEP 6: EARS, SLEEPING EYE, NOSE, PAW PADS & SHARP WHITE-GOLD HIGHLIGHTS
// ---------------------------------------------------------------------------
function drawEarsHeadAndPawPads() {
  // 1. SCULPTED EARS WITH SHARP WHITE-GOLD HIGHLIGHTS
  // Right (Upper) Ear: base (382,438)-(468,472), apex (446,336)
  brush.noStroke();
  brush.wash("#d6826e", 165);
  brush.beginShape(0.15);
  brush.vertex(402, 442);
  brush.vertex(444, 355);
  brush.vertex(456, 462);
  brush.endShape(true);
  brush.noWash();

  // Inner ear shadow depth
  brush.set("marker", "#8f4228", 1.8);
  brush.line(412, 442, 442, 372);
  brush.set("marker", "#eb9e8f", 1.5);
  brush.line(432, 452, 446, 365);

