function drawSculptedPawPad(cx, cy, rx, ry, ang) {
  // Dark burnished recess around the pad
  brush.noStroke();
  brush.wash("#6b3116", 190);
  drawOvalShape(cx, cy + 1.5, rx + 2.5, ry + 2.5, ang);

  // Soft pastel coral-rose & golden ochre pad body
  brush.wash("#e6978c", 235);
  drawOvalShape(cx, cy, rx, ry, ang);

  // Pastel peach-gold upper dome transition
  brush.wash("#f7cfa4", 210);
  drawOvalShape(cx, cy - ry * 0.22, rx * 0.78, ry * 0.62, ang);
  brush.noWash();

  // Sharp White-Gold Specular Highlight on top-facing rim of every paw pad
  let ca = cos(ang);
  let sa = sin(ang);
  let p1x = cx + (-rx * 0.68) * ca - (-ry * 0.42) * sa;
  let p1y = cy + (-rx * 0.68) * sa + (-ry * 0.42) * ca;
  let p2x = cx + 0 * ca - (-ry * 0.65) * sa;
  let p2y = cy + 0 * sa + (-ry * 0.65) * ca;
  let p3x = cx + (rx * 0.68) * ca - (-ry * 0.42) * sa;
  let p3y = cy + (rx * 0.68) * sa + (-ry * 0.42) * ca;

  brush.set("marker", "#fffef2", 1.3);
  brush.spline(
    [
      [p1x, p1y, 0.5],
      [p2x, p2y, 1.3],
      [p3x, p3y, 0.5]
    ],
    0.5
  );
  brush.set("rotring", "#ffffff", 1.0);
  brush.spline(
    [
      [p1x, p1y, 0.4],
      [p2x, p2y, 1.1],
      [p3x, p3y, 0.4]
    ],
    0.5
  );
}

function drawOvalShape(cx, cy, rx, ry, ang) {
  let ca = cos(ang);
  let sa = sin(ang);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 30) {
    let lx = rx * cos(a);
    let ly = ry * sin(a);
    let vx = cx + lx * ca - ly * sa;
    let vy = cy + lx * sa + ly * ca;
    brush.vertex(vx, vy);
  }
  brush.endShape(true);
}

