function degToRad(d) {
  return (d * Math.PI) / 180;
}

// Helper for organic oval/stone/berry shapes using p5.brush vertices
function drawOrganicOval(cx, cy, rx, ry, rotDeg, irregularity = 0.04, seedOffset = 0, steps = 16, flattenBottom = 0) {
  let rad = degToRad(rotDeg);
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);

  brush.beginShape(0.55);
  for (let i = 0; i < steps; i++) {
    let theta = (i / steps) * Math.PI * 2;
    let n = noise(
      Math.cos(theta) * 1.3 + seedOffset,
      Math.sin(theta) * 1.3 + seedOffset * 0.7
    );
    let rMod = 1 + (n - 0.5) * 2 * irregularity;

    let lx = Math.cos(theta) * rx * rMod;
    let ly = Math.sin(theta) * ry * rMod;

    // Slight natural berry taper or pebble flattening
    if (flattenBottom > 0 && Math.sin(theta) > 0) {
      ly *= 1 - flattenBottom * Math.sin(theta);
    }

    let gx = cx + lx * cosA - ly * sinA;
    let gy = cy + lx * sinA + ly * cosA;
    brush.vertex(gx, gy);
  }
  brush.endShape(true);
}

