function draw() {
  translate(-width / 2, -height / 2);

  // 1. Base Twilight Shoreline Ground
  background(PALETTE.twilightDeep);
  drawTwilightAtmosphere();

  // 2. Wet Pebbles (Batched Watercolor Fills + Individual Wet Reflections & Crevices)
  drawWetPebbles();

  // 3. Cast Shadow & Translucent Caustic Glow of the Grape Cluster on the Stones
  drawClusterShadowAndCaustics();

  // 4. Render the Grape Bunch & Stems Interleaved by Depth Tier (0 -> 3)
  for (let tier = 0; tier <= 3; tier++) {
    // Draw stems belonging to this tier first so berries overlap them naturally
    let tierStems = stems.filter(s => s.tier === tier);
    for (let s of tierStems) {
      drawWoodyStem(s);
    }

    // Draw pedicels connecting berries in this tier to the stem spine
    let tierGrapes = grapes.filter(g => g.tier === tier);
    drawTierPedicels(tierGrapes, tier);

    // Batch watercolor glazes for all berries in this tier
    drawTierGrapeWatercolors(tierGrapes, tier);

    // Individual hyperrealistic sea-glass modeling, chalky bloom & thumb-polished spots
    for (let g of tierGrapes) {
      drawGrapeHyperrealDetails(g);
    }
  }

  // 5. Render Tiny Beaded Water Droplets on Stems & Berries
  for (let d of droplets) {
    drawWaterDroplet(d.x, d.y, d.r, d.onStem);
  }

  // 6. Final Shoreline Atmosphere & Quiet Twilight Integration
  drawFinalShorelinePolish();

  noLoop();
}

// =============================================================================
// LAYER 1: TWILIGHT ATMOSPHERE & DUSKY SHORELINE UNDERPAINTING
// =============================================================================
function drawTwilightAtmosphere() {
  brush.noStroke();

  // Soft backlit twilight glow in upper-left / top center
  brush.fill(PALETTE.wetStoneBlue, 85);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);
  drawOrganicOval(360, 230, 480, 320, -15, 0.12, 11, 16);

  brush.fill(PALETTE.skySheen, 55);
  brush.fillBleed(0.4, "out");
  drawOrganicOval(290, 175, 360, 220, -10, 0.14, 22, 16);

  // Deepening twilight shadow toward lower-right and corners
  brush.fill(PALETTE.abyss, 110);
  brush.fillBleed(0.3, "out");
  drawOrganicOval(960, 980, 520, 420, 20, 0.12, 33, 16);
  drawOrganicOval(180, 1060, 420, 260, -10, 0.12, 44, 16);

  brush.noFill();
}

// =============================================================================
// LAYER 2: WET PEBBLES WITH DUSKY TWILIGHT REFLECTIONS
// =============================================================================
function drawWetPebbles() {
  const stoneColors = [
    PALETTE.wetStoneBlue,
    PALETTE.twilightMauve,
    PALETTE.wetBasalt,
    PALETTE.wetStoneTeal,
    PALETTE.wetStoneTaupe
  ];

  // Pass 2A: Dark pooled water in crevices underneath every stone
  brush.noStroke();
  for (let p of pebbles) {
    if (p.isBuried) continue;
    brush.wash(PALETTE.abyss, 175);
    drawOrganicOval(p.x + 6, p.y + p.ry * 0.22 + 8, p.rx * 1.04, p.ry * 0.98, p.rot, 0.06, p.seed, 14);
  }
  brush.noWash();

  // Pass 2B: Batched Watercolor Fills by stone mineral tone
  for (let tone = 0; tone < stoneColors.length; tone++) {
    brush.noStroke();
    brush.fill(stoneColors[tone], 185);
    brush.fillBleed(0.09, "in");
    brush.fillTexture(0.55, 0.42);

    for (let p of pebbles) {
      if (p.isBuried || p.toneIdx !== tone) continue;
      drawOrganicOval(p.x, p.y, p.rx, p.ry, p.rot, 0.06, p.seed, 16, 0.08);
    }
  }
  brush.noFill();

  // Pass 2C: Individual wet sheen, mineral veins, dark undersides & water meniscus
  for (let p of pebbles) {
    if (p.isBuried) continue;

    let rad = degToRad(p.rot);
    let cosA = Math.cos(rad);
    let sinA = Math.sin(rad);

    // 1. Lower-right stone shadow volume
    brush.noStroke();
    brush.wash(PALETTE.abyss, 85);
    drawOrganicOval(
      p.x + p.rx * 0.14 * cosA,
      p.y + p.ry * 0.24,
      p.rx * 0.86,
      p.ry * 0.72,
      p.rot,
      0.05,
      p.seed + 5,
      12
    );

    // 2. Broad wet twilight sky reflection across upper-left stone dome
    let sheenAlpha = floor(lerp(24, 52, p.sheenStrength) * (1 - p.t * 0.25));
    brush.wash(PALETTE.skySheen, sheenAlpha);
    drawOrganicOval(
      p.x - p.rx * 0.16 * cosA,
      p.y - p.ry * 0.24,
      p.rx * 0.68,
      p.ry * 0.48,
      p.rot - 4,
      0.04,
      p.seed + 9,
      12
    );

    // Brighter secondary wet reflection core
    if (p.sheenStrength > 0.72) {
      brush.wash(PALETTE.skyGlint, floor(sheenAlpha * 0.65));
      drawOrganicOval(
        p.x - p.rx * 0.22 * cosA,
        p.y - p.ry * 0.32,
        p.rx * 0.36,
        p.ry * 0.22,
        p.rot - 6,
        0.03,
        p.seed + 13,
        10
      );
    }
    brush.noWash();

    // 3. Subtle mineral texture & quartz veins on closer stones
    if (p.t > 0.25) {
      // Fine mineral grain strokes
      brush.set("2H", PALETTE.abyss, 0.45);
      for (let k = 0; k < 4; k++) {
        let a = random(0, 360);
        let d = random(0.1, 0.55);
        let sx = p.x + Math.cos(degToRad(a)) * p.rx * d;
        let sy = p.y + Math.sin(degToRad(a)) * p.ry * d;
        let ex = sx + Math.cos(rad) * p.rx * random(0.2, 0.45);
        let ey = sy + Math.sin(rad) * p.ry * random(0.2, 0.45);
        brush.line(sx, sy, ex, ey);
      }

      // Quartz mineral vein
      if (p.hasVeins) {
        brush.set("cpencil", PALETTE.skySheen, 0.55);
        let vx1 = p.x - p.rx * 0.55 * cosA;
        let vy1 = p.y - p.ry * 0.25;
        let vx2 = p.x + p.rx * 0.05;
        let vy2 = p.y + p.ry * 0.08;
        let vx3 = p.x + p.rx * 0.52 * cosA;
        let vy3 = p.y + p.ry * 0.28;
        brush.spline([[vx1, vy1, 0.3], [vx2, vy2, 0.8], [vx3, vy3, 0.3]], 0.4);
      }
    }

    // 4. Razor-sharp wet water-film glint along the upper rim or crevice meniscus
    if (p.sheenStrength > 0.76) {
      brush.set("cpencil", PALETTE.meniscus, 0.5);
      let gx1 = p.x - p.rx * 0.38 * cosA;
      let gy1 = p.y - p.ry * 0.54;
      let gx2 = p.x - p.rx * 0.12 * cosA;
      let gy2 = p.y - p.ry * 0.64;
      let gx3 = p.x + p.rx * 0.14 * cosA;
      let gy3 = p.y - p.ry * 0.58;
      brush.spline([[gx1, gy1, 0.2], [gx2, gy2, 0.9], [gx3, gy3, 0.2]], 0.5);
    }

    // Crevice meniscus reflection where water pools at the bottom edge of the stone
    if (random() < 0.55) {
      brush.set("glass_glint", PALETTE.skyGlint, 0.42);
      let mx1 = p.x - p.rx * 0.25;
      let my1 = p.y + p.ry * 0.88;
      let mx2 = p.x + p.rx * 0.05;
      let my2 = p.y + p.ry * 0.94;
      let mx3 = p.x + p.rx * 0.32;
      let my3 = p.y + p.ry * 0.86;
      brush.spline([[mx1, my1, 0.2], [mx2, my2, 0.7], [mx3, my3, 0.2]], 0.4);
    }
  }
}

// =============================================================================
// LAYER 3: CLUSTER CAST SHADOW & SUBSURFACE CAUSTICS ON WET STONES
// =============================================================================
function drawClusterShadowAndCaustics() {
  brush.noStroke();

  // Broad dusky twilight shadow underneath the heavy bunch
  brush.fill(PALETTE.abyss, 165);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.3);
  drawOrganicOval(625, 625, 310, 215, -22, 0.12, 501, 18);
  drawOrganicOval(355, 825, 155, 95, -18, 0.1, 502, 16);

  // Tight contact shadows directly beneath the bottom-most berries
  for (let g of grapes) {
    if (g.y > 610 || g.tier === 0 || g.id >= 39) {
      brush.wash(PALETTE.abyss, 150);
      drawOrganicOval(g.x + 12, g.y + g.ry * 0.65, g.rx * 0.95, g.ry * 0.58, g.rot * 0.3, 0.05, g.seed, 12);
    }
  }

  // Caustic seafoam light transmitted through the translucent berries onto the wet pebbles
  for (let g of grapes) {
    if (g.y > 640 || g.id >= 39) {
      brush.wash(PALETTE.celadonMid, 42);
      drawOrganicOval(g.x + 16, g.y + g.ry * 0.55, g.rx * 0.62, g.ry * 0.35, 10, 0.04, g.seed + 3, 10);
      brush.wash(PALETTE.aquamarinePale, 28);
      drawOrganicOval(g.x + 18, g.y + g.ry * 0.52, g.rx * 0.35, g.ry * 0.2, 10, 0.04, g.seed + 7, 10);
    }
  }
  brush.noWash();
  brush.noFill();
}

// =============================================================================
// LAYER 4A: WOODY STEMS & PEDICELS
// =============================================================================
function drawWoodyStem(stemObj) {
  let pts = stemObj.pts;
  let w = stemObj.weight;

  // 1. Dark shadow underside of stem
  brush.set("2B", PALETTE.stemDark, w * 0.55);
  let shadowPts = pts.map((p, i) => [p[0] + 2, p[1] + 4, i === 0 || i === pts.length - 1 ? 0.5 : 1.0]);
  brush.spline(shadowPts, 0.45);

  // 2. Olive-bark core body
  brush.set("HB", PALETTE.stemBark, w * 0.48);
  let corePts = pts.map(p => [p[0], p[1], 0.95]);
  brush.spline(corePts, 0.45);

  // 3. Sage-celadon upper illuminated side of stem
  brush.set("cpencil", PALETTE.stemOlive, w * 0.38);
  let midPts = pts.map(p => [p[0] - 1.5, p[1] - 1.5, 0.85]);
  brush.spline(midPts, 0.45);

  brush.set("cpencil", PALETTE.stemHighlight, w * 0.22);
  let hiPts = pts.map(p => [p[0] - 2.5, p[1] - 2.8, 0.7]);
  brush.spline(hiPts, 0.45);

  // 4. Knobby stem nodes where pedicels branch off
  brush.noStroke();
  for (let i = 0; i < pts.length; i++) {
    let [nx, ny] = pts[i];
    let nodeR = w * 1.45;
    brush.wash(PALETTE.stemBark, 180);
    drawOrganicOval(nx, ny, nodeR, nodeR * 0.8, 25, 0.1, i * 19, 10);
    brush.wash(PALETTE.stemHighlight, 110);
    drawOrganicOval(nx - 1.5, ny - 2, nodeR * 0.6, nodeR * 0.45, 25, 0.08, i * 23, 8);
  }
  brush.noWash();
}

function drawTierPedicels(tierGrapes, tier) {
  // Draw visible short pedicels linking berries near stem hollows to the main stem spine
  for (let g of tierGrapes) {
    // Find nearest point on any stem
    let bestDist = 9999;
    let bestPt = null;
    for (let s of stems) {
      for (let pt of s.pts) {
        let d = dist(g.x, g.y, pt[0], pt[1]);
        if (d < bestDist) {
          bestDist = d;
          bestPt = pt;
        }
      }
    }

    if (bestPt && bestDist < 125) {
      let rad = degToRad(g.rot);
      // Attachment point on the proximal (stem-ward) end of the berry
      let attachX = g.x + Math.cos(rad) * g.rx * 0.72;
      let attachY = g.y + Math.sin(rad) * g.ry * 0.72;
      let midX = lerp(bestPt[0], attachX, 0.5) + random(-4, 4);
      let midY = lerp(bestPt[1], attachY, 0.5) - 4;

      brush.set("2B", PALETTE.stemDark, 1.3);
      brush.spline([[bestPt[0], bestPt[1], 0.7], [midX, midY + 2, 0.8], [attachX, attachY + 2, 1.1]], 0.4);

      brush.set("cpencil", PALETTE.stemSage, 0.95);
      brush.spline([[bestPt[0], bestPt[1] - 1, 0.6], [midX, midY - 1, 0.7], [attachX, attachY - 1, 1.0]], 0.4);

      // Flared pedicel torus cushion plugging into the berry
      brush.noStroke();
      brush.wash(PALETTE.stemBark, 190);
      drawOrganicOval(attachX, attachY, 6.5, 4.5, g.rot + 90, 0.08, g.seed, 8);
      brush.noWash();
    }

    // Little detached stem stub on loose berries on the pebbles
    if (g.pedicelStub) {
      let rad = degToRad(g.rot + 180);
      let ax = g.x + Math.cos(rad) * g.rx * 0.82;
      let ay = g.y + Math.sin(rad) * g.ry * 0.82;
      let sx = ax + Math.cos(rad - 0.3) * 24;
      let sy = ay + Math.sin(rad - 0.3) * 24;
      brush.set("2B", PALETTE.stemBark, 1.4);
      brush.spline([[ax, ay, 1.1], [(ax + sx) / 2, (ay + sy) / 2 - 3, 0.8], [sx, sy, 0.6]], 0.4);
      brush.set("cpencil", PALETTE.stemHighlight, 0.8);
      brush.line(ax, ay - 1, sx, sy - 1);
    }
  }
}

// =============================================================================
// LAYER 4B: BATCHED WATERCOLOR GLAZES (SEAFOAM, CELADON & PALE AQUAMARINE)
// =============================================================================
function drawTierGrapeWatercolors(tierGrapes, tier) {
  brush.noStroke();

  // 1. Ambient Occlusion Halo behind each grape to separate overlapping berries
  for (let g of tierGrapes) {
    brush.wash(PALETTE.abyss, tier === 0 ? 115 : 95);
    drawOrganicOval(g.x + 3, g.y + 5, g.rx * 1.03, g.ry * 1.03, g.rot, 0.03, g.seed, 14);
  }
  brush.noWash();

  // 2. Watercolor Glaze 1: Outer Celadon / Slate-Green Body (Batched per tier)
  let baseColor =
    tier === 0 ? PALETTE.grapeDeepCeladon :
    tier === 1 ? PALETTE.grapeSlateGreen :
    tier === 2 ? PALETTE.celadonDark :
                 PALETTE.celadonMid;

  brush.fill(baseColor, tier === 0 ? 195 : 175);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.48, 0.35);
  for (let g of tierGrapes) {
    drawOrganicOval(g.x, g.y, g.rx, g.ry, g.rot, 0.025, g.seed, 18);
  }

  // 3. Watercolor Glaze 2: Translucent Seafoam Mid-Interior (Shifted toward transmitted light)
  let midColor = tier === 0 ? PALETTE.celadonMid : PALETTE.seafoamMid;
  brush.fill(midColor, tier === 0 ? 125 : 150);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.42, 0.25);
  for (let g of tierGrapes) {
    let gx = g.x + g.rx * 0.08;
    let gy = g.y + g.ry * 0.1;
    drawOrganicOval(gx, gy, g.rx * 0.82, g.ry * 0.82, g.rot, 0.025, g.seed + 11, 16);
  }

  // 4. Watercolor Glaze 3: Glowing Pale Aquamarine Heart (Backlit Sea-Glass Core)
  if (tier >= 1) {
    brush.fill(PALETTE.aquamarinePale, tier === 1 ? 130 : 165);
    brush.fillBleed(0.15, "out");
    brush.fillTexture(0.35, 0.2);
    for (let g of tierGrapes) {
      let gx = g.x + g.rx * 0.14;
      let gy = g.y + g.ry * 0.15;
      drawOrganicOval(gx, gy, g.rx * 0.58 * g.glow, g.ry * 0.58 * g.glow, g.rot, 0.02, g.seed + 23, 14);
    }
  }

  brush.noFill();
}

// =============================================================================
// LAYER 4C: HYPERREALISTIC SEA-GLASS GLOW, CHALKY BLOOM & THUMB-POLISHED SPOTS
// =============================================================================
function drawGrapeHyperrealDetails(g) {
  let rad = degToRad(g.rot);
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);

  // --- 1. Subsurface Scattering Luminous Heart & Seed Hints ---
  brush.noStroke();
  if (g.tier >= 1) {
    // Deepest luminous aquamarine-chartreuse glow where light exits the lower-right belly
    let glowX = g.x + g.rx * 0.16;
    let glowY = g.y + g.ry * 0.18;

    brush.wash(PALETTE.aquamarineGlow, floor(85 * g.glow));
    drawOrganicOval(glowX, glowY, g.rx * 0.46, g.ry * 0.44, g.rot, 0.02, g.seed + 31, 12);

    brush.wash(PALETTE.innerChartreuse, floor(65 * g.glow));
    drawOrganicOval(glowX + g.rx * 0.05, glowY + g.ry * 0.05, g.rx * 0.28, g.ry * 0.26, g.rot, 0.02, g.seed + 37, 10);

    // Faint internal seed shadow suspended inside the translucent flesh
    if (g.tier >= 2) {
      brush.wash(PALETTE.seedShadow, 36);
      drawOrganicOval(g.x - g.rx * 0.04, g.y - g.ry * 0.02, g.rx * 0.22, g.ry * 0.12, g.rot + 12, 0.04, g.seed + 41, 10);
      drawOrganicOval(g.x + g.rx * 0.06, g.y - g.ry * 0.08, g.rx * 0.18, g.ry * 0.1, g.rot - 10, 0.04, g.seed + 43, 10);
    }
  }

  // Darker celadon crescent along the upper/outer shaded edge to give spherical density
  brush.wash(PALETTE.grapeShadow, g.tier === 0 ? 85 : 55);
  drawOrganicOval(g.x - g.rx * 0.16, g.y - g.ry * 0.18, g.rx * 0.78, g.ry * 0.72, g.rot, 0.03, g.seed + 47, 12);
  brush.noWash();

  // --- 2. Precompute Thumb-Polished Window Geometry (if present on this berry) ---
  let rubCx = 0, rubCy = 0, rubRx = 0, rubRy = 0, rubRot = g.rot - 25;
  if (g.thumb) {
    let rAng = degToRad(g.rubA);
    rubCx = g.x + Math.cos(rAng) * g.rx * g.rubD;
    rubCy = g.y + Math.sin(rAng) * g.ry * g.rubD;
    rubRx = g.rx * g.rubS;
    rubRy = g.ry * g.rubS * 0.76;
  }

  // Helper to check normalized distance to thumb-polished patch
  function distToThumbRub(px, py) {
    if (!g.thumb) return 999;
    let rRad = degToRad(rubRot);
    let dx = px - rubCx;
    let dy = py - rubCy;
    let lx = dx * Math.cos(-rRad) - dy * Math.sin(-rRad);
    let ly = dx * Math.sin(-rRad) + dy * Math.cos(-rRad);
    return Math.sqrt((lx * lx) / (rubRx * rubRx) + (ly * ly) / (rubRy * rubRy));
  }

  // --- 3. Matte Frosted Bloom (Chalky White Pencil Rubbed Over) ---
  // Layer soft chalky washes first across the upper-left and side surfaces
  if (!g.thumb) {
    brush.noStroke();
    brush.wash(PALETTE.bloomMist, floor(46 * g.bloom));
    drawOrganicOval(g.x - g.rx * 0.12, g.y - g.ry * 0.14, g.rx * 0.76, g.ry * 0.72, g.rot, 0.03, g.seed + 51, 12);
    brush.noWash();
  }

  // Rubbed chalk_bloom & cpencil curved contour strokes across the berry skin
  let bloomPasses = g.tier === 0 ? 22 : g.tier === 1 ? 34 : 48;
  for (let i = 0; i < bloomPasses; i++) {
    // Concentrate bloom more on upper, outer, and side surfaces so lower-right sea-glass glow shines through
    let a1 = random(-210, 85);
    let span = random(28, 65);
    let rFrac = random(0.22, 0.94);

    let p1x = g.x + Math.cos(degToRad(a1)) * g.rx * rFrac;
    let p1y = g.y + Math.sin(degToRad(a1)) * g.ry * rFrac;
    let aMid = a1 + span * 0.5;
    let p2x = g.x + Math.cos(degToRad(aMid)) * g.rx * rFrac;
    let p2y = g.y + Math.sin(degToRad(aMid)) * g.ry * rFrac;
    let a2 = a1 + span;
    let p3x = g.x + Math.cos(degToRad(a2)) * g.rx * rFrac;
    let p3y = g.y + Math.sin(degToRad(a2)) * g.ry * rFrac;

    // Skip strokes that fall inside the thumb-polished window
    let dRub = Math.min(distToThumbRub(p1x, p1y), distToThumbRub(p2x, p2y), distToThumbRub(p3x, p3y));
    if (dRub < 0.92) continue;

    // Pick chalk tone
    let cRoll = (i + g.id) % 4;
    let bloomCol =
      cRoll === 0 ? PALETTE.bloomWhite :
      cRoll === 1 ? PALETTE.bloomChalk :
      cRoll === 2 ? PALETTE.bloomMist :
                    PALETTE.bloomBlue;

    if (i % 3 === 0) {
      brush.set("chalk_bloom", bloomCol, random(0.55, 0.95) * g.bloom);
    } else {
      brush.set("cpencil", bloomCol, random(0.45, 0.85) * g.bloom);
    }

    brush.spline([[p1x, p1y, 0.3], [p2x, p2y, 0.9], [p3x, p3y, 0.3]], 0.5);
  }

  // Additional fine dusty cross-grain pencil rubbing near the frosty crown of the berry
  if (g.tier >= 1) {
    let grainCount = g.tier >= 2 ? 26 : 14;
    for (let i = 0; i < grainCount; i++) {
      let ang = random(-185, 35);
      let rf = random(0.35, 0.88);
      let cx = g.x + Math.cos(degToRad(ang)) * g.rx * rf;
      let cy = g.y + Math.sin(degToRad(ang)) * g.ry * rf;
      if (distToThumbRub(cx, cy) < 1.0) continue;

      let tang = degToRad(ang + 90 + random(-25, 25));
      let len = g.rx * random(0.14, 0.26);
      brush.set("cpencil", i % 2 === 0 ? PALETTE.bloomWhite : PALETTE.bloomLav, random(0.4, 0.7));
      brush.line(
        cx - Math.cos(tang) * len * 0.5,
        cy - Math.sin(tang) * len * 0.5,
        cx + Math.cos(tang) * len * 0.5,
        cy + Math.sin(tang) * len * 0.5
      );
    }
  }

  // --- 4. Glowing Translucent Sea-Glass Rim Light (Bottom-Right & Lower Contour) ---
  if (g.tier >= 1) {
    let rimPts = [];
    for (let a = -10; a <= 115; a += 25) {
      let rxPt = g.x + Math.cos(degToRad(a)) * g.rx * 0.91;
      let ryPt = g.y + Math.sin(degToRad(a)) * g.ry * 0.91;
      rimPts.push([rxPt, ryPt, a === 40 || a === 65 ? 0.95 : 0.35]);
    }
    brush.set("velvet_wash", PALETTE.aquamarineGlow, 0.48 * g.glow);
    brush.spline(rimPts, 0.5);

    brush.set("cpencil", PALETTE.bloomWhite, 0.55);
    brush.spline(rimPts.slice(1, 5), 0.5);
  }

  // --- 5. Thumb-Polished Spot with Crisp Glassy Highlight ---
  if (g.thumb) {
    brush.noStroke();

    // Dark, smooth emerald-celadon window where the matte white bloom was rubbed off by a thumb
    brush.wash(PALETTE.polishedMid, 165);
    drawOrganicOval(rubCx, rubCy, rubRx, rubRy, rubRot, 0.04, g.seed + 71, 14);

    brush.wash(PALETTE.polishedDeep, 155);
    drawOrganicOval(rubCx - rubRx * 0.08, rubCy - rubRy * 0.08, rubRx * 0.82, rubRy * 0.78, rubRot, 0.03, g.seed + 73, 12);

    // Rich translucent emerald transition at the lower edge of the thumb rub
    brush.wash(PALETTE.polishedEmerald, 120);
    drawOrganicOval(rubCx + rubRx * 0.14, rubCy + rubRy * 0.18, rubRx * 0.65, rubRy * 0.55, rubRot, 0.03, g.seed + 77, 10);
    brush.noWash();

    // Chalky bloom ridge smudged around the perimeter of the thumb print
    let rRad = degToRad(rubRot);
    for (let k = 0; k < 18; k++) {
      let theta = degToRad(k * 20 + random(-8, 8));
      let theta2 = theta + degToRad(26);
      let lx1 = Math.cos(theta) * rubRx * 1.04;
      let ly1 = Math.sin(theta) * rubRy * 1.04;
      let lx2 = Math.cos(theta2) * rubRx * 1.06;
      let ly2 = Math.sin(theta2) * rubRy * 1.06;

      let wx1 = rubCx + lx1 * Math.cos(rRad) - ly1 * Math.sin(rRad);
      let wy1 = rubCy + lx1 * Math.sin(rRad) + ly1 * Math.cos(rRad);
      let wx2 = rubCx + lx2 * Math.cos(rRad) - ly2 * Math.sin(rRad);
      let wy2 = rubCy + lx2 * Math.sin(rRad) + ly2 * Math.cos(rRad);

      brush.set("cpencil", PALETTE.bloomWhite, 0.65);
      brush.line(wx1, wy1, wx2, wy2);
    }

    // Crisp, Glassy Specular Highlight inside the polished dark window!
    let hiX = rubCx - rubRx * 0.18;
    let hiY = rubCy - rubRy * 0.18;

    // Soft sky halo right around the crisp highlight
    brush.noStroke();
    brush.wash(PALETTE.glassSky, 135);
    drawOrganicOval(hiX, hiY, rubRx * 0.42, rubRy * 0.28, rubRot - 8, 0.02, g.seed + 81, 10);

    // Razor-sharp pure white window highlight
    brush.wash(PALETTE.glassPure, 240);
    drawOrganicOval(hiX, hiY, rubRx * 0.28, rubRy * 0.16, rubRot - 8, 0.01, g.seed + 83, 10);

    // Secondary smaller window pane glint right beside it
    let hi2X = rubCx + rubRx * 0.2;
    let hi2Y = rubCy - rubRy * 0.04;
    brush.wash(PALETTE.glassPure, 210);
    drawOrganicOval(hi2X, hi2Y, rubRx * 0.12, rubRy * 0.08, rubRot - 5, 0.01, g.seed + 85, 8);
    brush.noWash();

    // Crisp specular edge definition
    brush.set("glass_glint", PALETTE.glassPure, 0.75);
    let gAng = degToRad(rubRot - 8);
    let gx1 = hiX - Math.cos(gAng) * rubRx * 0.26;
    let gy1 = hiY - Math.sin(gAng) * rubRx * 0.26;
    let gx2 = hiX;
    let gy2 = hiY - 1.5;
    let gx3 = hiX + Math.cos(gAng) * rubRx * 0.26;
    let gy3 = hiY + Math.sin(gAng) * rubRx * 0.26;
    brush.spline([[gx1, gy1, 0.3], [gx2, gy2, 1.0], [gx3, gy3, 0.3]], 0.4);
  }

  // --- 6. Stylar Scar (Tiny Russet Dot at Distal End of Berry) ---
  if (g.hasScar && g.tier >= 2) {
    let scarX = g.x - cosA * g.rx * 0.72;
    let scarY = g.y - sinA * g.ry * 0.72;
    brush.noStroke();
    brush.wash(PALETTE.bloomWhite, 120);
    drawOrganicOval(scarX, scarY, 4.5, 4.0, g.rot, 0.05, g.seed, 8);
    brush.wash(PALETTE.stemBark, 210);
    drawOrganicOval(scarX, scarY, 2.4, 2.0, g.rot, 0.05, g.seed + 1, 8);
    brush.noWash();
  }

  // --- 7. Delicate Contour Whisper ---
  // Crisp graphite/colored-pencil edge where the berry meets dark crevices
  brush.set("2H", g.tier >= 2 ? PALETTE.bloomMist : PALETTE.celadonLight, 0.35);
  let arcPts = [];
  for (let a = -150; a <= -40; a += 28) {
    arcPts.push([
      g.x + Math.cos(degToRad(a)) * g.rx * 0.98,
      g.y + Math.sin(degToRad(a)) * g.ry * 0.98,
      0.5
    ]);
  }
  brush.spline(arcPts, 0.5);
}

// =============================================================================
// LAYER 5: TINY WATER DROPLETS BEADING ON STEMS & BERRIES
// =============================================================================
function drawWaterDroplet(x, y, r, onStem) {
  brush.noStroke();

  // 1. Tiny dark cast shadow underneath the bead
  brush.wash(PALETTE.abyss, 170);
  drawOrganicOval(x + r * 0.25, y + r * 0.48, r * 0.95, r * 0.75, 15, 0.03, x + y, 10);

  // 2. Dark refractive upper body of the droplet
  brush.wash(PALETTE.polishedDeep, 210);
  drawOrganicOval(x, y, r, r * 0.88, -15, 0.03, x * 2, 12);

  // 3. Bright aquamarine / seafoam internal caustic glow at the bottom of the bead
  brush.wash(PALETTE.seafoamBright, 195);
  drawOrganicOval(x + r * 0.14, y + r * 0.2, r * 0.68, r * 0.52, -10, 0.02, x * 3, 10);

  brush.wash(PALETTE.aquamarineGlow, 220);
  drawOrganicOval(x + r * 0.18, y + r * 0.28, r * 0.44, r * 0.3, -10, 0.02, x * 4, 8);

  // 4. Pinpoint pure white specular highlight on the upper-left curve
  brush.wash(PALETTE.glassPure, 250);
  drawOrganicOval(x - r * 0.32, y - r * 0.28, r * 0.28, r * 0.2, -25, 0.01, x * 5, 8);
  brush.noWash();

  // Crisp glint touch
  brush.set("glass_glint", PALETTE.glassPure, Math.max(0.28, r * 0.06));
  brush.line(x - r * 0.38, y - r * 0.26, x - r * 0.2, y - r * 0.32);
}

// =============================================================================
// LAYER 6: FINAL SHORELINE ATMOSPHERE & QUIET TWILIGHT INTEGRATION
// =============================================================================
function drawFinalShorelinePolish() {
  // Subtle misty sea-salt spray & chalk texture uniting the backlit crown of the cluster
  brush.set("spray", PALETTE.bloomWhite, 0.35);
  brush.line(480, 390, 740, 360);
  brush.line(540, 490, 680, 560);

  brush.set("spray", PALETTE.aquamarineGlow, 0.3);
  brush.line(560, 580, 690, 650);
}

// Hyperreal Portrait of an Old Surfer — Weathered Driftwood & Salt
// Rendered with p5.js 2.x and p5.brush in WEBGL mode

const SEED = 4279;

// Anatomical landmark constants (1200x1200 frame, cropped brow to chin)
const CX = 600;
const LX = 402, LY = 328; // Left eye center
const RX = 798, RY = 326; // Right eye center
const EYE_W = 186;
const NOSE_X = 602, NOSE_Y = 628;
const MOUTH_Y = 836;
const CHIN_Y = 1035;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);
  background("#d8d3c8");
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Sea-haze paper ground & atmospheric base washes
  renderGroundAndBaseWashes();

  // 2. Anatomical undertone washes (driftwood greys, bone, and sunburnt pink on nose/lips)
  renderAnatomicalWashes();

  // 3. Soft charcoal & dry-pigment massing for deep facial hollows and stubble bed
  renderDeepToneMasses();

  // 4. Long flowing wood-grain graphite hatching across the entire face
  renderDriftwoodGrainField();

  // 5. Deep carved driftwood crevices & major anatomical wrinkles (shadow + core + bone rim)
  renderCarvedWrinkleSystem();

  // 6. Hyperreal squinting surfer's eyes & wind-bleached eyebrows
  renderEyesAndBrows();

  // 7. Nose details: sun-peeled skin, pores, and sunburnt rose-earth texture
  renderNoseDetails();

  // 8. Stoic chapped lips: vertical bark fissures, sunburnt pink & parched skin scales
  renderMouthAndLips();

  // 9. Coarse grey/white stubble & encrusted sea-salt crystals against soft grey shading
  renderStubbleAndSaltCrystals();

  // 10. Final sea-haze atmospheric grain & highlights
  renderFinalHighlights();

  noLoop();
}

// ============================================================================
// MATHEMATICAL ANATOMY & WOOD-GRAIN TOPOGRAPHY ENGINE
// ============================================================================

function gauss2D(x, y, cx, cy, sx, sy) {
  let dx = (x - cx) / sx;
  let dy = (y - cy) / sy;
  return Math.exp(-0.5 * (dx * dx + dy * dy));
}

function rotGauss2D(x, y, cx, cy, sx, sy, deg) {
  let rad = deg * Math.PI / 180;
  let c = Math.cos(rad), s = Math.sin(rad);
  let dx = x - cx, dy = y - cy;
  let rx = (dx * c + dy * s) / sx;
  let ry = (-dx * s + dy * c) / sy;
  return Math.exp(-0.5 * (rx * rx + ry * ry));
}

function distToSegment(px, py, x1, y1, x2, y2) {
  let vx = x2 - x1, vy = y2 - y1;
  let l2 = vx * vx + vy * vy;
  let t = Math.max(0, Math.min(1, ((px - x1) * vx + (py - y1) * vy) / l2));
  let projX = x1 + t * vx, projY = y1 + t * vy;
  return {
    d: Math.hypot(px - projX, py - projY),
    t: t,
    nx: px - projX,
    ny: py - projY
  };
}

// Returns [0..1] luminance of the 3D facial topography under flat sea-haze light
// 0 = deepest crevice shadow, 1 = brightest bone/salt highlight
function getFaceLuminance(x, y) {
  let lum = 0.56;

  // Global cylindrical falloff toward temples and jaw sides
  let edgeDist = Math.abs(x - CX) / 560;
  lum -= 0.24 * Math.pow(edgeDist, 2.1);

  // Forehead bosses & supraorbital brow ridge highlights
  lum += 0.16 * gauss2D(x, y, 470, 95, 160, 65);
  lum += 0.16 * gauss2D(x, y, 730, 95, 160, 65);
  lum += 0.22 * rotGauss2D(x, y, 390, 210, 145, 36, -8);
  lum += 0.22 * rotGauss2D(x, y, 810, 208, 145, 36, 8);

  // Glabella frown cleft shadows
  lum -= 0.26 * gauss2D(x, y, 568, 210, 16, 65);
  lum -= 0.26 * gauss2D(x, y, 632, 210, 16, 65);
  lum += 0.12 * gauss2D(x, y, 600, 205, 18, 55);

  // Deep orbital sockets beneath the overhanging brow
  lum -= 0.42 * rotGauss2D(x, y, 415, 290, 120, 52, -6);
  lum -= 0.42 * rotGauss2D(x, y, 785, 288, 120, 52, 6);
  // Inner orbital shadow beside nasal root
  lum -= 0.30 * gauss2D(x, y, 505, 315, 42, 55);
  lum -= 0.30 * gauss2D(x, y, 695, 315, 42, 55);

  // Puffy lower eyelid bags (lit upper roll, shadowed tear trough below)
  lum += 0.14 * rotGauss2D(x, y, 405, 368, 92, 20, 6);
  lum += 0.14 * rotGauss2D(x, y, 795, 366, 92, 20, -6);
  lum -= 0.24 * rotGauss2D(x, y, 410, 398, 100, 18, 10);
  lum -= 0.24 * rotGauss2D(x, y, 790, 396, 100, 18, -10);
  // Secondary malar festoon groove
  lum -= 0.16 * rotGauss2D(x, y, 395, 442, 110, 16, 14);
  lum -= 0.16 * rotGauss2D(x, y, 805, 440, 110, 16, -14);

  // Prominent wind-carved cheekbones (zygomatic arch highlights)
  lum += 0.25 * rotGauss2D(x, y, 275, 465, 125, 58, 18);
  lum += 0.25 * rotGauss2D(x, y, 925, 465, 125, 58, -18);

  // Gaunt buccal cheek hollows below cheekbones
  lum -= 0.30 * rotGauss2D(x, y, 280, 690, 105, 135, -12);
  lum -= 0.30 * rotGauss2D(x, y, 920, 690, 105, 135, 12);

  // Nose bridge & bulbous surfer's nose (slightly crooked to the left at mid-bridge)
  let noseCenterOffset = 7 * gauss2D(x, y, 600, 445, 90, 85);
  let nx = x - (CX - noseCenterOffset);
  if (y > 260 && y < 650) {
    let bridgeW = map(y, 260, 630, 34, 62);
    let bridgeRidge = Math.exp(-0.5 * Math.pow(nx / (bridgeW * 0.55), 2));
    let bridgeSides = Math.exp(-0.5 * Math.pow((Math.abs(nx) - bridgeW * 0.95) / 28, 2));
    let yEnv = Math.sin( map(constrain(y, 265, 645), 265, 645, 0, Math.PI) );
    lum += 0.28 * bridgeRidge * yEnv;
    lum -= 0.26 * bridgeSides * yEnv;
  }
  // Bulbous nose tip highlight & lower shadow
  lum += 0.28 * gauss2D(x, y, 598, 608, 48, 40);
  lum -= 0.34 * gauss2D(x, y, 600, 668, 68, 26);
  // Nostril wings (alae) and deep nostril cavities
  lum += 0.15 * gauss2D(x, y, 508, 628, 32, 26);
  lum += 0.15 * gauss2D(x, y, 692, 628, 32, 26);
  lum -= 0.48 * rotGauss2D(x, y, 535, 656, 26, 13, -18);
  lum -= 0.48 * rotGauss2D(x, y, 665, 656, 26, 13, 18);

  // Deep Nasolabial Canyons
  let nlfL = distToSegment(x, y, 492, 610, 402, 855);
  if (nlfL.d < 65) {
    let env = Math.sin(nlfL.t * Math.PI);
    // Deep trench on the inner side, lit cheek roll just above/outside it
    lum -= 0.36 * Math.exp(-0.5 * Math.pow(nlfL.d / 14, 2)) * env;
    if (nlfL.nx < 0) {
      lum += 0.16 * Math.exp(-0.5 * Math.pow((nlfL.d - 22) / 16, 2)) * env;
    }
  }
  let nlfR = distToSegment(x, y, 708, 610, 798, 855);
  if (nlfR.d < 65) {
    let env = Math.sin(nlfR.t * Math.PI);
    lum -= 0.36 * Math.exp(-0.5 * Math.pow(nlfR.d / 14, 2)) * env;
    if (nlfR.nx > 0) {
      lum += 0.16 * Math.exp(-0.5 * Math.pow((nlfR.d - 22) / 16, 2)) * env;
    }
  }

  // Marionette folds from mouth corners toward jaw
  let marL = distToSegment(x, y, 435, 842, 412, 1045);
  if (marL.d < 45) lum -= 0.22 * Math.exp(-0.5 * Math.pow(marL.d / 13, 2)) * Math.sin(marL.t * Math.PI);
  let marR = distToSegment(x, y, 765, 842, 788, 1045);
  if (marR.d < 45) lum -= 0.22 * Math.exp(-0.5 * Math.pow(marR.d / 13, 2)) * Math.sin(marR.t * Math.PI);

  // Philtrum trough & ridges
  lum -= 0.22 * gauss2D(x, y, 600, 742, 20, 42);
  lum += 0.14 * gauss2D(x, y, 574, 748, 12, 38);
  lum += 0.14 * gauss2D(x, y, 626, 748, 12, 38);

  // Mouth & Lips
  // Upper lip is angled downward/inward -> in shadow
  lum -= 0.26 * gauss2D(x, y, 600, 814, 145, 20);
  // Stomion (parting line between lips)
  lum -= 0.45 * gauss2D(x, y, 600, 836, 155, 7);
  // Lower lip cushion catches sea-haze overhead light
  lum += 0.22 * gauss2D(x, y, 600, 862, 118, 18);
  // Deep labiomental crease under lower lip
  lum -= 0.35 * gauss2D(x, y, 600, 916, 115, 24);

  // Chin boss (strong, eroded, slightly cleft in center)
  lum += 0.24 * gauss2D(x, y, 555, 1005, 75, 58);
  lum += 0.24 * gauss2D(x, y, 645, 1005, 75, 58);
  lum -= 0.16 * gauss2D(x, y, 600, 1015, 18, 48); // Chin cleft

  // Submental shadow & weathered neck cords below jaw
  if (y > 1060) {
    let jawLine = 1135 - 0.00085 * Math.pow(x - CX, 2);
    if (y > jawLine) {
      lum -= 0.32 * constrain((y - jawLine) / 65, 0, 1);
    }
  }

  // Fine driftwood bark modulation
  let bark = (noise(x * 0.012, y * 0.025) - 0.5) * 0.12;
  return constrain(lum + bark, 0.04, 0.98);
}

// Computes the continuous wood-grain & contour wrinkle flow angle (in degrees) at (x, y)
function getWoodGrainAngle(x, y) {
  // Base vector starts roughly horizontal
  let vx = 1.0;
  let vy = 0.0;

  // 1. Forehead & Brow Arch (y < 280)
  if (y < 290) {
    let browArch = -0.22 * Math.sin((x - CX) / 280 * Math.PI);
    // Dip sharply into vertical wood-splits at the glabella (between brows)
    let glabPull = gauss2D(x, y, 600, 215, 55, 55);
    vy += browArch * (1 - glabPull);
    if (glabPull > 0.05) {
      let side = x < CX ? 1 : -1;
      vx = lerp(vx, 0.18 * side, glabPull * 0.85);
      vy = lerp(vy, 0.95, glabPull * 0.85);
    }
  }

  // 2. Left Eye Knot (wraps like wood grain around a branch knot at LX, LY)
  let dxL = x - LX, dyL = y - LY;
  let dEyeL = Math.hypot(dxL / 1.35, dyL * 1.35);
  if (dEyeL < 220 && x < CX) {
    let wL = Math.exp(-0.5 * Math.pow(dEyeL / 95, 2));
    // Tangent around elliptical eye contour, always flowing left-to-right
    let tx = Math.abs(dyL) + 18;
    let ty = -dxL * (dyL >= 0 ? 0.55 : -0.55) / (Math.abs(dyL) + 35);
    if (dyL < 0) ty = (x - LX) * 0.0042 * 90; // Arch over upper lid
    else ty = -(x - LX) * 0.0048 * 90;        // Scoop under lower lid & eye bags
    // Crow's feet radiating outward/downward at left temple (x < 320)
    if (x < 330) {
      let crowAng = map(constrain(y, 250, 440), 250, 440, 18, -38);
      let rad = crowAng * Math.PI / 180;
      tx = Math.cos(rad);
      ty = Math.sin(rad);
    }
    vx = lerp(vx, tx, wL * 0.92);
    vy = lerp(vy, ty, wL * 0.92);
  }

  // 3. Right Eye Knot (wraps around RX, RY)
  let dxR = x - RX, dyR = y - RY;
  let dEyeR = Math.hypot(dxR / 1.35, dyR * 1.35);
  if (dEyeR < 220 && x >= CX) {
    let wR = Math.exp(-0.5 * Math.pow(dEyeR / 95, 2));
    let tx = 1.0;
    let ty = 0.0;
    if (dyR < 0) ty = (x - RX) * 0.0042 * 90;
    else ty = -(x - RX) * 0.0048 * 90;
    // Crow's feet radiating at right temple (x > 870)
    if (x > 870) {
      let crowAng = map(constrain(y, 250, 440), 250, 440, -18, 38);
      let rad = crowAng * Math.PI / 180;
      tx = Math.cos(rad);
      ty = Math.sin(rad);
    }
    vx = lerp(vx, tx, wR * 0.92);
    vy = lerp(vy, ty, wR * 0.92);
  }

  // 4. Nose Bridge & Bulbous Tip Saddle Contour
  let dNose = gauss2D(x, y, CX, 490, 95, 165);
  if (dNose > 0.05) {
    // Grain arches up over the bridge and wraps around the bulbous tip
    let nx = (x - CX) / 95;
    let saddleVy = nx * 0.65;
    if (y > 575) {
      // Curve under the bulbous tip
      saddleVy = -nx * 0.75;
    }
    vx = lerp(vx, 1.0, dNose * 0.7);
    vy = lerp(vy, saddleVy, dNose * 0.85);
  }

  // 5. Cheekbones, Gaunt Hollows & Nasolabial Flow (y = 400..950)
  if (y > 380 && y < 1050) {
    // Left cheek sweeps down along the nasolabial fold toward the jaw
    if (x < CX - 50) {
      let cheekW = gauss2D(x, y, 340, 680, 175, 210);
      // Flow downward and inward along the cheek and nasolabial trench
      let targetAng = map(x, 80, 520, 62, 114);
      if (y > 820) targetAng = map(x, 120, 500, 48, 82);
      let rad = targetAng * Math.PI / 180;
      vx = lerp(vx, Math.cos(rad), cheekW * 0.88);
      vy = lerp(vy, Math.sin(rad), cheekW * 0.88);
    }
    // Right cheek sweeps down symmetrically
    if (x > CX + 50) {
      let cheekW = gauss2D(x, y, 860, 680, 175, 210);
      let targetAng = map(x, 680, 1120, 66, 118);
      if (y > 820) targetAng = map(x, 700, 1080, 98, 132);
      let rad = targetAng * Math.PI / 180;
      vx = lerp(vx, Math.cos(rad), cheekW * 0.88);
      vy = lerp(vy, Math.sin(rad), cheekW * 0.88);
    }
  }

  // 6. Mouth & Chin Burl Knot (wrapping around the mouth and chin boss)
  let dMouthChin = gauss2D(x, y, CX, 940, 185, 165);
  if (dMouthChin > 0.05 && y > 690) {
    let mx = (x - CX) / 185;
    let my = (y - 960) / 145;
    let ty = 0;
    if (y < 836) {
      // Arch over upper lip and philtrum
      ty = mx * 0.52;
    } else if (y < 935) {
      // Scoop under lower lip into labiomental crease
      ty = -mx * 0.45;
    } else {
      // Arch over the square chin boss like wood burl
      ty = mx * 0.58 * (my < 0 ? 1 : -0.7);
    }
    vx = lerp(vx, 1.0, dMouthChin * 0.82);
    vy = lerp(vy, ty, dMouthChin * 0.82);
  }

  // 7. Organic driftwood grain waviness (multi-octave Perlin noise)
  let baseAng = Math.atan2(vy, vx) * 180 / Math.PI;
  let n1 = (noise(x * 0.0045, y * 0.0045) - 0.5) * 22;
  let n2 = (noise(x * 0.016, y * 0.016) - 0.5) * 9;
  return baseAng + n1 + n2;
}

// Avoid drawing continuous skin grain directly over the open eyeballs
function isInsideOpenEye(x, y) {
  // Left eye almond opening
  let lx = (x - LX) / 84;
  let ly = (y - (LY + 3)) / 21;
  if (lx * lx + ly * ly < 0.92) return true;

  // Right eye almond opening
  let rx = (x - RX) / 84;
  let ry = (y - (RY + 3)) / 21;
  if (rx * rx + ry * ry < 0.92) return true;

  return false;
}

// Helper to draw an organic polygon for washes
function drawWashPoly(pts, curvature = 0.5) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeEllipsePoly(cx, cy, rx, ry, n = 14, jitter = 0.08, rotDeg = 0) {
  let pts = [];
  let rad = rotDeg * Math.PI / 180;
  let c = Math.cos(rad), s = Math.sin(rad);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let rMod = 1 + (noise(cx * 0.01 + Math.cos(a) * 2, cy * 0.01 + Math.sin(a) * 2) - 0.5) * jitter * 2;
    let px = Math.cos(a) * rx * rMod;
    let py = Math.sin(a) * ry * rMod;
    pts.push([cx + px * c - py * s, cy + px * s + py * c]);
  }
  return pts;
}

