// ============================================================================
// LAYER 4: LONG FLOWING DRIFTWOOD GRAPHITE HATCHING FIELD
// ============================================================================

function renderDriftwoodGrainField() {
  brush.noFill();
  brush.noMass();
  brush.noHatch();

  const paletteDark   = ["#282420", "#38332e", "#49433d"];
  const paletteMid    = ["#5c564e", "#6e685f", "#827b71"];
  const paletteSilver = ["#999389", "#b0aaa0", "#c7c2b8"];
  const paletteBone   = ["#dfd9ce", "#ece8df", "#f5f3ed"];
  const palettePink   = ["#a6685f", "#bc7d73", "#8f554d"];

  // Trace streamlines on a dense jittered grid covering the 1200x1200 portrait
  const stepX = 34;
  const stepY = 10.5;

  for (let gy = 14; gy < height - 10; gy += stepY) {
    for (let gx = 18; gx < width - 18; gx += stepX) {
      let sx = gx + random(-14, 14);
      let sy = gy + random(-4.5, 4.5);

      if (isInsideOpenEye(sx, sy)) continue;

      // Trace a long flowing wood-grain spline forward and backward from (sx, sy)
      let pts = traceGrainStreamline(sx, sy, 18, 11);
      if (pts.length < 5) continue;

      let midPt = pts[Math.floor(pts.length / 2)];
      let mx = midPt[0], my = midPt[1];
      let lum = getFaceLuminance(mx, my);

      // Periodic driftwood ridge wave perpendicular to flow creates natural wood ring banding
      let ringWave = Math.sin(sy * 0.19 + noise(sx * 0.008, sy * 0.008) * 14);

      // Check if we are in the sunburnt nose or lip zone
      let isNosePink = gauss2D(mx, my, 600, 560, 88, 125) > 0.35;
      let isLipPink  = gauss2D(mx, my, 600, 848, 135, 38) > 0.38;

      if ((isNosePink || isLipPink) && random() < 0.36) {
        let col = random(palettePink);
        brush.set("cpencil", col, random(0.28, 0.48));
        brush.spline(pts, 0.5);
        continue;
      }

      // Select graphite medium & tone based on local anatomical luminance + wood ring phase
      if (lum < 0.34 || (lum < 0.48 && ringWave < -0.45)) {
        // Deep driftwood fissure / shadow grain
        let col = random(paletteDark);
        let br = random() < 0.45 ? "2B" : "HB";
        brush.set(br, col, random(0.26, 0.46));
        brush.spline(pts, 0.5);
      } else if (lum < 0.58 || ringWave < 0.15) {
        // Midtone weathered graphite contour grain
        let col = random(paletteMid);
        let br = random() < 0.65 ? "HB" : "cpencil";
        brush.set(br, col, random(0.22, 0.38));
        brush.spline(pts, 0.5);
      } else if (lum < 0.74) {
        // Silver-grey sea-haze mid-highlight grain
        let col = random(paletteSilver);
        brush.set("2H", col, random(0.22, 0.36));
        brush.spline(pts, 0.5);
      } else {
        // Bright bleached bone & salt-white driftwood ridge highlight
        let col = random(paletteBone);
        let br = random() < 0.5 ? "cpencil" : "2H";
        brush.set(br, col, random(0.28, 0.46));
        brush.spline(pts, 0.5);
      }
    }
  }

  // Secondary cross-contour & diagonal wood-check hatching in deep shadow hollows
  for (let i = 0; i < 320; i++) {
    let sx = random(40, width - 40);
    let sy = random(40, height - 40);
    if (isInsideOpenEye(sx, sy)) continue;

    let lum = getFaceLuminance(sx, sy);
    if (lum < 0.42) {
      let baseAng = getWoodGrainAngle(sx, sy) + random([-24, 24, -18, 18]);
      let len = random(35, 85);
      let pts = [];
      let cx = sx, cy = sy;
      for (let k = 0; k < 6; k++) {
        let p = map(0.45 - lum, 0, 0.45, 0.4, 1.35) * Math.sin((k / 5) * Math.PI + 0.2);
        pts.push([cx, cy, p]);
        let rad = (baseAng + random(-5, 5)) * Math.PI / 180;
        cx += Math.cos(rad) * (len / 5);
        cy += Math.sin(rad) * (len / 5);
        if (isInsideOpenEye(cx, cy)) break;
      }
      if (pts.length >= 4) {
        brush.set("2B", lum < 0.26 ? "#221e1b" : "#4a443e", random(0.2, 0.34));
        brush.spline(pts, 0.45);
      }
    }
  }
}

function traceGrainStreamline(startX, startY, numSteps, stepLen) {
  let pts = [];
  let cx = startX, cy = startY;

  for (let i = 0; i < numSteps; i++) {
    if (cx < 10 || cx > width - 10 || cy < 10 || cy > height - 10) break;
    if (isInsideOpenEye(cx, cy)) break;

    let lum = getFaceLuminance(cx, cy);
    // Taper pressure at both ends of the stroke and press harder in shadow grooves
    let env = Math.sin(((i + 0.5) / numSteps) * Math.PI);
    let tonePress = map(constrain(lum, 0.15, 0.85), 0.15, 0.85, 1.35, 0.55);
    let pressure = constrain(env * tonePress, 0.25, 1.5);

    pts.push([cx, cy, pressure]);

    let ang = getWoodGrainAngle(cx, cy);
    let rad = ang * Math.PI / 180;
    cx += Math.cos(rad) * stepLen;
    cy += Math.sin(rad) * stepLen;
  }
  return pts;
}

// ============================================================================
// LAYER 5: CARVED 3D DRIFTWOOD WRINKLES (BEVEL + CREVICE CORE + BONE HIGHLIGHT)
// ============================================================================

// Renders a 3-part hyperreal carved wrinkle groove along a control point array
function drawCarvedWrinkle(rawPts, depth = 1.0, lightOffsetX = 0, lightOffsetY = 2.4) {
  if (rawPts.length < 3) return;

  let corePts = [];
  let bevelPts = [];
  let rimPts = [];

  for (let i = 0; i < rawPts.length; i++) {
    let t = i / (rawPts.length - 1);
    let env = Math.sin(t * Math.PI);
    let jx = (noise(rawPts[i][0] * 0.03, rawPts[i][1] * 0.03) - 0.5) * 4.5;
    let jy = (noise(rawPts[i][1] * 0.03, rawPts[i][0] * 0.03) - 0.5) * 4.5;
    let px = rawPts[i][0] + jx;
    let py = rawPts[i][1] + jy;
    let p = (rawPts[i][2] !== undefined ? rawPts[i][2] : 1.0) * (0.35 + 0.85 * env);

    corePts.push([px, py, p]);
    bevelPts.push([px - lightOffsetX * 0.7, py - lightOffsetY * 0.7, p * 0.85]);
    rimPts.push([px + lightOffsetX, py + lightOffsetY, p * 0.9]);
  }

  // 1. Soft shadow bevel on the upper/inner slope of the fissure
  brush.set("cpencil", "#59524a", 0.38 * depth);
  brush.spline(bevelPts, 0.5);

  // 2. Crisp dark bone-dry crevice core
  brush.set("2B", depth > 0.85 ? "#1f1c19" : "#36312c", 0.34 * depth);
  brush.spline(corePts, 0.5);

  // 3. Lit driftwood ridge highlight catching the sea-haze glare
  brush.set("2H", "#ebe7dd", 0.32 * depth);
  brush.spline(rimPts, 0.5);
}

function renderCarvedWrinkleSystem() {
  // 1. Deep Horizontal Forehead & Supraorbital Furrows (like split timber rings)
  const foreheadRows = [38, 66, 96, 128, 160];
  for (let r = 0; r < foreheadRows.length; r++) {
    let baseY = foreheadRows[r];
    // Left to center-left arch
    let ptsL = [];
    for (let x = 110; x <= 565; x += 38) {
      let arch = -22 * Math.sin(((x - 110) / 455) * Math.PI);
      let dip = (x > 480) ? (x - 480) * 0.28 : 0;
      ptsL.push([x, baseY + arch + dip, 1.1]);
    }
    drawCarvedWrinkle(ptsL, 0.95, 0, 2.6);

    // Center-right to right arch
    let ptsR = [];
    for (let x = 635; x <= 1090; x += 38) {
      let arch = -22 * Math.sin(((1090 - x) / 455) * Math.PI);
      let dip = (x < 720) ? (720 - x) * 0.28 : 0;
      ptsR.push([x, baseY + arch + dip, 1.1]);
    }
    drawCarvedWrinkle(ptsR, 0.95, 0, 2.6);
  }

  // 2. Deep Glabella Vertical Splits (The "11" frown lines between brows)
  drawCarvedWrinkle([[562, 95, 0.5], [566, 155, 1.3], [570, 215, 1.5], [562, 268, 0.8]], 1.25, -2.5, 0.5);
  drawCarvedWrinkle([[638, 95, 0.5], [634, 155, 1.3], [630, 215, 1.5], [638, 268, 0.8]], 1.25, 2.5, 0.5);
  drawCarvedWrinkle([[598, 125, 0.4], [600, 185, 1.1], [601, 250, 0.9]], 0.9, 2.0, 0.5);
  // Transverse radix crease across top of nose bridge
  drawCarvedWrinkle([[538, 268, 0.6], [570, 278, 1.2], [600, 281, 1.3], [630, 278, 1.2], [662, 268, 0.6]], 1.05, 0, 2.4);
  drawCarvedWrinkle([[548, 294, 0.5], [600, 304, 1.1], [652, 294, 0.5]], 0.85, 0, 2.2);

  // 3. Radiating Crow's Feet & Temple Wood-Knot Fissures
  // Left outer eye fan
  const leftCrowAngles = [-34, -22, -11, 0, 11, 22, 34, 45];
  for (let a of leftCrowAngles) {
    let pts = [];
    let rad = (180 + a) * Math.PI / 180;
    let sx = 308, sy = LY + a * 0.55;
    for (let step = 0; step <= 6; step++) {
      let d = step * 34;
      let bend = (a > 0 ? 1 : 0.4) * step * step * 1.4;
      pts.push([sx + Math.cos(rad) * d, sy + Math.sin(rad) * d + bend, map(step, 0, 6, 1.35, 0.4)]);
    }
    drawCarvedWrinkle(pts, 1.05, 0.5, 2.3);
  }
  // Right outer eye fan
  for (let a of leftCrowAngles) {
    let pts = [];
    let rad = (-a) * Math.PI / 180;
    let sx = 892, sy = RY + a * 0.55;
    for (let step = 0; step <= 6; step++) {
      let d = step * 34;
      let bend = (a > 0 ? 1 : 0.4) * step * step * 1.4;
      pts.push([sx + Math.cos(rad) * d, sy + Math.sin(rad) * d + bend, map(step, 0, 6, 1.35, 0.4)]);
    }
    drawCarvedWrinkle(pts, 1.05, -0.5, 2.3);
  }

  // 4. Under-Eye Bags, Tear Troughs & Malar Festoons
  const bagOffsets = [32, 52, 76, 104, 134];
  for (let idx = 0; idx < bagOffsets.length; idx++) {
    let off = bagOffsets[idx];
    let w = 1.15 - idx * 0.12;
    // Left eye bags sweeping from inner corner out to cheekbone
    drawCarvedWrinkle([
      [495, LY + 14 + idx * 9, 0.6],
      [450, LY + off * 0.85, 1.2],
      [395, LY + off, 1.3],
      [330, LY + off * 0.92, 1.1],
      [255, LY + off * 0.65 + idx * 12, 0.5]
    ], w, 0, 2.5);

    // Right eye bags
    drawCarvedWrinkle([
      [705, RY + 14 + idx * 9, 0.6],
      [750, RY + off * 0.85, 1.2],
      [805, RY + off, 1.3],
      [870, RY + off * 0.92, 1.1],
      [945, RY + off * 0.65 + idx * 12, 0.5]
    ], w, 0, 2.5);
  }

  // 5. Deep Nasolabial Canyons & Parallel Cheek Bark Fissures
  // Left Nasolabial Fold & parallel cheek grain grooves
  for (let k = -2; k <= 4; k++) {
    let shiftX = k * 24;
    let shiftY = Math.abs(k) * 8;
    let strength = k === 0 ? 1.45 : map(Math.abs(k), 1, 4, 1.05, 0.65);
    drawCarvedWrinkle([
      [494 - shiftX * 0.55, 598 + shiftY, 0.7],
      [462 - shiftX * 0.8, 675 + shiftY, 1.35],
      [426 - shiftX, 765 + shiftY, 1.4],
      [402 - shiftX * 1.05, 855 + shiftY, 1.2],
      [395 - shiftX * 1.1, 955 + shiftY, 0.85],
      [405 - shiftX * 0.9, 1055, 0.4]
    ], strength, -2.4, 1.2);
  }
  // Right Nasolabial Fold & parallel cheek grain grooves
  for (let k = -2; k <= 4; k++) {
    let shiftX = k * 24;
    let shiftY = Math.abs(k) * 8;
    let strength = k === 0 ? 1.45 : map(Math.abs(k), 1, 4, 1.05, 0.65);
    drawCarvedWrinkle([
      [706 + shiftX * 0.55, 598 + shiftY, 0.7],
      [738 + shiftX * 0.8, 675 + shiftY, 1.35],
      [774 + shiftX, 765 + shiftY, 1.4],
      [798 + shiftX * 1.05, 855 + shiftY, 1.2],
      [805 + shiftX * 1.1, 955 + shiftY, 0.85],
      [795 + shiftX * 0.9, 1055, 0.4]
    ], strength, 2.4, 1.2);
  }

  // 6. Gaunt Cheek & Temple Vertical/Curved Driftwood Grain Splits
  for (let side of [-1, 1]) {
    for (let c = 0; c < 6; c++) {
      let baseX = CX + side * (310 + c * 34);
      let pts = [];
      for (let y = 440; y <= 1040; y += 55) {
        let curve = side * Math.sin(((y - 440) / 600) * Math.PI) * 38;
        pts.push([baseX + curve, y, 0.95]);
      }
      drawCarvedWrinkle(pts, 0.78, -side * 2.0, 1.2);
    }
  }

  // 7. Labiomental Crease & Concentric Chin Burl Wrinkles
  drawCarvedWrinkle([
    [475, 938, 0.5], [535, 916, 1.2], [600, 910, 1.4], [665, 916, 1.2], [725, 938, 0.5]
  ], 1.2, 0, 2.6);
  drawCarvedWrinkle([
    [455, 978, 0.5], [525, 946, 1.0], [600, 938, 1.15], [675, 946, 1.0], [745, 978, 0.5]
  ], 0.9, 0, 2.4);
  // Vertical chin cleft split
  drawCarvedWrinkle([[600, 965, 0.6], [599, 1015, 1.3], [601, 1072, 0.8]], 1.05, 2.2, 0.5);
}

// ============================================================================
// LAYER 6: HYPERREAL SQUINTING EYES & WIND-BLEACHED BROWS
// ============================================================================

function renderEyesAndBrows() {
  renderSingleEye(LX, LY, -1);
  renderSingleEye(RX, RY, 1);
  renderEyebrows();
}

function renderSingleEye(ex, ey, side) {
  // side: -1 for left eye, +1 for right eye
  let innerX = ex - side * 92; // toward nose (left eye: 494, right eye: 706)
  let outerX = ex + side * 92; // toward temple (left eye: 310, right eye: 890)

  // 1. Sclera base fill (shaded blue-grey bone, slightly wind-stung at corners)
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.35, 0.25);

  let upperLidPts = [
    [outerX, ey + 5],
    [ex + side * 42, ey - 16],
    [ex - side * 28, ey - 18],
    [innerX, ey + 8]
  ];
  let lowerLidPts = [
    [innerX, ey + 8],
    [ex - side * 32, ey + 20],
    [ex + side * 38, ey + 17],
    [outerX, ey + 5]
  ];
  let eyeContour = upperLidPts.concat(lowerLidPts.slice(1, -1));

  // Shadowed sclera wash
  brush.fill("#b4b8ba", 185);
  drawWashPoly(eyeContour, 0.4);

  // Corner scleral shadows & caruncle rose tone
  brush.fill("#74787a", 130);
  drawWashPoly(makeEllipsePoly(outerX - side * 20, ey + 2, 24, 12, 10, 0.05));
  brush.fill("#a86d66", 145);
  drawWashPoly(makeEllipsePoly(innerX + side * 12, ey + 6, 15, 9, 10, 0.05));

  // 2. Iris Base Wash (pale sea-glass / silver-slate)
  let ix = ex - side * 4;
  let iy = ey - 1;
  let irisR = 29;

  brush.fill("#586366", 210);
  brush.circle(ix, iy, irisR, 0.04);
  brush.fill("#9ca8aa", 175);
  brush.circle(ix, iy, irisR * 0.82, 0.04);
  brush.noFill();

  // 3. Detailed Iris Radial Stroma Fibers & Limbal Ring
  for (let a = 0; a < 360; a += 3.5) {
    let rad = a * Math.PI / 180;
    let rIn = irisR * random(0.30, 0.38);
    let rOut = irisR * random(0.86, 0.98);
    let x1 = ix + Math.cos(rad) * rIn;
    let y1 = iy + Math.sin(rad) * rIn;
    let x2 = ix + Math.cos(rad) * rOut;
    let y2 = iy + Math.sin(rad) * rOut;

    // Restrict iris fibers to stay between upper and lower squinting lids
    if (y1 < ey - 17 || y2 < ey - 17 || y1 > ey + 18 || y2 > ey + 18) continue;

    let isLightFiber = random() < 0.52;
    brush.set("2H", isLightFiber ? "#d4dede" : "#434d50", random(0.16, 0.26));
    brush.line(x1, y1, x2, y2);
  }

  // Dark limbal ring around iris perimeter
  for (let a = -25; a < 205; a += 10) {
    let rad = a * Math.PI / 180;
    let x1 = ix + Math.cos(rad) * (irisR - 1);
    let y1 = iy + Math.sin(rad) * (irisR * 0.58);
    let x2 = ix + Math.cos(rad + 0.2) * (irisR - 1);
    let y2 = iy + Math.sin(rad + 0.2) * (irisR * 0.58);
    brush.set("2B", "#22282a", 0.32);
    brush.line(x1, y1, x2, y2);
  }

  // 4. Constricted Dark Pupil (squinting into bright ocean glare)
  brush.noStroke();
  brush.wash("#111314", 245);
  brush.circle(ix, iy - 1, 9.5, 0.02);
  brush.noWash();
  brush.set("rotring", "#0c0d0e", 0.38);
  for (let r = 2; r <= 9; r += 2.2) {
    brush.circle(ix, iy - 1, r, 0.03);
  }

  // 5. Cast shadow of heavy upper eyelid across top of iris & sclera
  brush.set("charcoal", "#1c1917", 0.44);
  brush.spline([
    [outerX - side * 6, ey + 6, 0.7],
    [ex + side * 42, ey - 14, 1.4],
    [ex - side * 28, ey - 16, 1.45],
    [innerX + side * 4, ey + 7, 0.8]
  ], 0.5);

  // Heavy hooded upper eyelid fold (epicanthic/weather hood hanging over outer corner)
  drawCarvedWrinkle([
    [outerX + side * 34, ey + 18, 0.7],
    [outerX, ey - 8, 1.3],
    [ex + side * 35, ey - 28, 1.4],
    [ex - side * 35, ey - 29, 1.3],
    [innerX - side * 12, ey - 6, 0.8]
  ], 1.25, 0, 2.4);

  // Secondary upper eyelid crease
  drawCarvedWrinkle([
    [outerX + side * 22, ey + 4, 0.5],
    [ex + side * 25, ey - 42, 1.15],
    [ex - side * 35, ey - 40, 1.1],
    [innerX - side * 8, ey - 18, 0.6]
  ], 0.95, 0, 2.2);

  // 6. Wet Lower Eyelid Margin (Waterline) & Specular Catchlights
  // Bright white-bone waterline ledge
  brush.set("cpencil", "#f4f2ec", 0.38);
  brush.spline([
    [innerX - side * 8, ey + 8, 0.6],
    [ex - side * 30, ey + 21, 1.25],
    [ex + side * 36, ey + 18, 1.2],
    [outerX + side * 4, ey + 6, 0.5]
  ], 0.5);

  // Shadow line just below the lower lid rim (lash line root)
  brush.set("2B", "#332e2a", 0.32);
  brush.spline([
    [innerX - side * 6, ey + 11, 0.5],
    [ex - side * 30, ey + 25, 1.1],
    [ex + side * 36, ey + 22, 1.1],
    [outerX + side * 6, ey + 9, 0.5]
  ], 0.5);

  // Crisp sea-horizon corneal catchlight on the upper-left edge of the pupil/iris
  brush.set("rotring", "#ffffff", 0.52);
  brush.line(ix - 8, iy - 7, ix + 3, iy - 8);
  brush.line(ix - 7, iy - 5, ix + 1, iy - 6);
  // Secondary moisture glint on tear duct and lower tear meniscus
  brush.set("rotring", "#ffffff", 0.38);
  brush.line(innerX + side * 10, ey + 6, innerX + side * 15, ey + 7);
  brush.line(ix - 6, ey + 17, ix + 8, ey + 17);

  // Sparse, short, sun-bleached eyelashes
  for (let i = 0; i < 22; i++) {
    let t = i / 21;
    let lx = lerp(innerX - side * 10, outerX + side * 4, t);
    let arch = Math.sin(t * Math.PI);
    let ly = ey + 5 - arch * 22;
    let ang = map(t, 0, 1, side < 0 ? -115 : -65, side < 0 ? -155 : -25);
    let rad = ang * Math.PI / 180;
    let len = random(8, 16) * (0.5 + 0.6 * arch);
    brush.set("2H", random() < 0.45 ? "#e8e4da" : "#38332e", 0.24);
    brush.line(lx, ly, lx + Math.cos(rad) * len, ly + Math.sin(rad) * len);
  }
}

function renderEyebrows() {
  // Unruly, coarse, sun-bleached surfer eyebrows arching over the supraorbital ridge
  const browColors = [
    "#2c2825", "#3f3a35", "#5c564e", "#7a7369",
    "#aba499", "#d8d3c8", "#f0ede6", "#ffffff"
  ];

  for (let side of [-1, 1]) {
    let startX = CX + side * 52; // Inner brow near glabella
    let endX   = CX + side * 335; // Outer brow tail

    for (let i = 0; i < 240; i++) {
      let t = Math.pow(random(), 0.92);
      let bx = lerp(startX, endX, t);
      // Brow arch peaks around 60% outward
      let archY = 232 - 34 * Math.sin(t * Math.PI * 0.92) + (t > 0.7 ? (t - 0.7) * 55 : 0);
      let by = archY + random(-18, 18);

      // Growth angle starts steep near glabella and sweeps outward/downward toward temple
      let baseAng = side < 0
        ? map(t, 0, 1, -118, -198)
        : map(t, 0, 1, -62, 18);
      baseAng += random(-16, 16);

      let len = random(24, 54) * (1 - 0.25 * Math.abs(t - 0.4));
      let rad = baseAng * Math.PI / 180;
      let mx = bx + Math.cos(rad) * len * 0.5;
      let my = by + Math.sin(rad) * len * 0.5 - random(2, 7);
      let ex = bx + Math.cos(rad + side * 0.22) * len;
      let ey = by + Math.sin(rad + side * 0.22) * len;

      // Draw dark root/shadow hair first, then bright salt-bleached coarse hairs on top
      let isWhiteHair = i > 130;
      let col = isWhiteHair
        ? browColors[Math.floor(random(4, 8))]
        : browColors[Math.floor(random(0, 5))];

      let br = isWhiteHair ? (random() < 0.5 ? "cpencil" : "2H") : "HB";
      let wt = isWhiteHair ? random(0.28, 0.46) : random(0.22, 0.36);

      brush.set(br, col, wt);
      brush.spline([[bx, by, 0.9], [mx, my, 1.25], [ex, ey, 0.35]], 0.5);
    }
  }
}

