    // Adjacent salt-white / bone highlight rim or sun-peeled skin flake
    if (random() < 0.65) {
      brush.set("2H", random() < 0.5 ? "#f4f1ea" : "#e3ddd2", random(0.22, 0.36));
      let flakeLen = random(3, 9);
