// LAYER 8: STOIC CHAPPED LIPS & VERTICAL BARK FISSURES
// ============================================================================

function renderMouthAndLips() {
  // 1. Subtle Sunburnt Rose-Taupe & Dry-Pigment Texture on Upper & Lower Vermilion
  const lipTones = ["#a86b62", "#bf8177", "#8c544c", "#c99288", "#754943"];
  for (let i = 0; i < 180; i++) {
    let lx = random(445, 755);
    let t = (lx - 445) / 310;
    let env = Math.sin(t * Math.PI);
    let isLower = random() < 0.62;
    let ly = isLower
      ? MOUTH_Y + random(3, 46 * env)
      : MOUTH_Y - random(2, 34 * env);

    // Curve vertically around the cylindrical volume of the lips
    let curveX = (lx - CX) * 0.04;
    let len = random(10, 24) * env;
    brush.set("cpencil", random(lipTones), random(0.24, 0.42));
    brush.line(lx, ly - len * 0.4, lx + curveX, ly + len * 0.6);
  }

  // 2. Stoic Mouth Parting Line (Stomion) — deep weathered crevice
  let stomionPts = [
    [432, MOUTH_Y + 6, 0.7],
    [485, MOUTH_Y - 2, 1.25],
    [545, MOUTH_Y - 5, 1.35],
    [600, MOUTH_Y + 1, 1.45],
    [655, MOUTH_Y - 5, 1.35],
    [715, MOUTH_Y - 2, 1.25],
    [768, MOUTH_Y + 6, 0.7]
  ];
  brush.set("charcoal", "#1c1615", 0.48);
  brush.spline(stomionPts, 0.5);
  brush.set("2B", "#362724", 0.36);
  brush.spline(stomionPts.map(p => [p[0], p[1] - 2.5, p[2] * 0.85]), 0.5);

  // Deep oral commissure pockets at mouth corners
  drawCarvedWrinkle([[415, MOUTH_Y - 8, 0.5], [435, MOUTH_Y + 6, 1.35], [424, MOUTH_Y + 28, 0.8]], 1.15, -2.0, 1.5);
  drawCarvedWrinkle([[785, MOUTH_Y - 8, 0.5], [765, MOUTH_Y + 6, 1.35], [776, MOUTH_Y + 28, 0.8]], 1.15, 2.0, 1.5);

  // 3. Chapped Vertical Lip Fissures & Parched Salt-White Skin Scales
  for (let x = 462; x <= 738; x += random(7, 13)) {
    let t = (x - 445) / 310;
    let env = Math.sin(t * Math.PI);
    let topY = MOUTH_Y + 2;
    let botY = MOUTH_Y + 46 * env;
    let midX = x + (x - CX) * 0.08;
    let botX = x + (x - CX) * 0.14;

    // Dark vertical bark-like crack on the lower lip
    brush.set("2B", "#3d2825", random(0.22, 0.35));
    brush.spline([
      [x, topY, 0.8],
      [midX, lerp(topY, botY, 0.5), 1.25],
      [botX, botY, 0.5]
    ], 0.5);

    // Bright parched bone/salt-white skin ridge right beside each crack
    brush.set("2H", "#efeae0", random(0.24, 0.38));
    brush.spline([
      [x + 2.2, topY + 3, 0.6],
      [midX + 2.5, lerp(topY, botY, 0.48), 1.15],
      [botX + 2.2, botY - 4, 0.4]
    ], 0.5);

    // Upper lip vertical sun-lines (smoker's/surfer's vertical lip creases)
    if (random() < 0.75) {
      let uTopY = MOUTH_Y - 42 * env - random(8, 22);
      let uBotY = MOUTH_Y - 2;
      drawCarvedWrinkle([
        [x + (x - CX) * 0.05, uTopY, 0.5],
        [x + (x - CX) * 0.02, lerp(uTopY, uBotY, 0.55), 1.05],
        [x, uBotY, 0.9]
      ], 0.72, 1.8, 0.4);
    }
  }
}

// ============================================================================
// LAYER 9: COARSE STUBBLE & ENCRUSTED SEA-SALT CRYSTALS
// ============================================================================

function isStubbleRegion(x, y) {
  // Exclude open mouth vermilion core (though moustache overhangs the upper border)
  let inLowerLip = gauss2D(x, y, CX, MOUTH_Y + 24, 118, 22) > 0.52;
  if (inLowerLip) return false;
  let inMouthSlit = gauss2D(x, y, CX, MOUTH_Y, 135, 8) > 0.45;
  if (inMouthSlit) return false;

  // Moustache zone (from below nose to upper lip border)
  let moustache = gauss2D(x, y, CX, 755, 155, 52) > 0.25 && y > 672 && y < 832;
  if (moustache) return true;

  // Chin, sub-labial soul patch, jawline, and lower cheeks
  if (y > 620) {
    let cheekBoundary = 630 + 0.0022 * Math.pow(x - CX, 2);
    // Keep upper central cheeks & nose clear of heavy beard
    let midFaceClear = gauss2D(x, y, CX, 560, 290, 175) > 0.35;
    if (!midFaceClear && y > cheekBoundary - 140) return true;
  }
  return false;
}

function getStubbleAngle(x, y) {
  // Moustache hairs grow downward and fan outward toward mouth corners
  if (y < MOUTH_Y + 12 && Math.abs(x - CX) < 185) {
    return 90 + ((x - CX) / 170) * 36 + random(-10, 10);
  }
  // Sub-labial & chin hairs grow downward with a slight outward fan
  if (Math.abs(x - CX) < 150 && y >= MOUTH_Y + 12) {
    return 90 + ((x - CX) / 150) * 24 + (noise(x * 0.01, y * 0.01) - 0.5) * 25;
  }
  // Cheek & jaw stubble sweeps downward and slightly inward/backward
  let side = x < CX ? -1 : 1;
  return 90 + side * map(Math.abs(x - CX), 140, 480, 18, 42) + random(-12, 12);
}

function renderStubbleAndSaltCrystals() {
  // 1. Soft Charcoal-Grey Follicle Shading Bed & Pore Shadows
  for (let i = 0; i < 650; i++) {
    let sx = random(95, width - 95);
    let sy = random(640, height - 15);
    if (!isStubbleRegion(sx, sy)) continue;

    let ang = getStubbleAngle(sx, sy);
    let rad = ang * Math.PI / 180;
    let len = random(10, 24);

    // Dark follicle root shadow
    brush.set("2B", random() < 0.5 ? "#24211e" : "#3d3833", random(0.24, 0.38));
    brush.line(sx, sy, sx + Math.cos(rad) * len, sy + Math.sin(rad) * len);
  }

  // 2. Mid-tone Silver-Grey & Bone Stubble Bristles
  const silverWhiskers = ["#8a847b", "#a6a096", "#c4bfb5", "#dcd7cd"];
  for (let i = 0; i < 850; i++) {
    let sx = random(85, width - 85);
    let sy = random(635, height - 12);
    if (!isStubbleRegion(sx, sy)) continue;

    let ang = getStubbleAngle(sx, sy);
    let rad = ang * Math.PI / 180;
    let isMoustache = sy < MOUTH_Y + 10 && Math.abs(sx - CX) < 175;
    let len = isMoustache ? random(16, 36) : random(11, 26);

    let mx = sx + Math.cos(rad) * len * 0.5 + random(-2, 2);
    let my = sy + Math.sin(rad) * len * 0.5;
    let ex = sx + Math.cos(rad + 0.12) * len;
    let ey = sy + Math.sin(rad + 0.12) * len;

    brush.set("2H", random(silverWhiskers), random(0.24, 0.38));
    brush.spline([[sx, sy, 0.95], [mx, my, 1.15], [ex, ey, 0.35]], 0.5);
  }

  // 3. Stark Salt-White Coarse Whiskers Popping Against Soft Grey Shading
  for (let i = 0; i < 720; i++) {
    let sx = random(95, width - 95);
    let sy = random(645, height - 15);
    if (!isStubbleRegion(sx, sy)) continue;

    let ang = getStubbleAngle(sx, sy);
    let rad = ang * Math.PI / 180;
    let isMoustache = sy < MOUTH_Y + 10 && Math.abs(sx - CX) < 175;
    let len = isMoustache ? random(18, 38) : random(10, 25);

    // Tiny dark pore/shadow at the base of the white bristle for hyperreal contrast
    brush.set("rotring", "#2b2724", 0.28);
    brush.line(sx - 1, sy - 1, sx + 1, sy + 1);

    // Crisp white whisker
    let col = random() < 0.65 ? "#ffffff" : "#f0ede6";
    let br = random() < 0.55 ? "cpencil" : "rotring";
    brush.set(br, col, random(0.26, 0.44));
    brush.line(sx, sy, sx + Math.cos(rad) * len, sy + Math.sin(rad) * len);
  }

  // 4. Sea-Salt Crystals Clinging to Stubble, Moustache, Chin & Weathered Skin
  // Each salt crystal is rendered as a tiny sharp geometric cluster with a micro-shadow underneath
  for (let i = 0; i < 580; i++) {
    let cx, cy;
    let rPick = random();
    if (rPick < 0.72) {
      // Concentrated in the moustache, chin, and jaw stubble
      cx = random(130, width - 130);
      cy = random(675, height - 20);
      if (!isStubbleRegion(cx, cy)) continue;
    } else if (rPick < 0.88) {
      // Clinging to eyebrows & temple crow's feet
      let side = random() < 0.5 ? -1 : 1;
      cx = CX + side * random(75, 420);
      cy = random(185, 385);
      if (isInsideOpenEye(cx, cy)) continue;
    } else {
      // Scattered dried sea-spray crystals on nose bridge & cheekbones
      cx = CX + random(-360, 360);
      cy = random(380, 680);
    }

    let crystalSize = random(2.2, 5.8);

    // Micro cast-shadow directly beneath the salt crystal (creates trompe-l'oeil 3D pop)
    brush.set("rotring", "#26221f", random(0.28, 0.42));
    brush.line(cx - crystalSize * 0.4, cy + crystalSize * 0.55,
               cx + crystalSize * 0.6, cy + crystalSize * 0.65);

    // Sharp crystalline white facet strokes
    brush.set("rotring", "#ffffff", random(0.36, 0.58));
    brush.line(cx - crystalSize * 0.5, cy, cx + crystalSize * 0.5, cy - crystalSize * 0.2);
    brush.line(cx - crystalSize * 0.15, cy - crystalSize * 0.5, cx + crystalSize * 0.25, cy + crystalSize * 0.45);

    // Secondary crystal grain in cluster
    if (random() < 0.48) {
      let ox = cx + random(-6, 6);
      let oy = cy + random(-5, 5);
      brush.set("rotring", "#f7f6f2", random(0.3, 0.45));
      brush.line(ox - 1.8, oy, ox + 1.8, oy - 1.2);
    }
  }
}

