};

// 3D Camera configuration (low diagonal viewpoint)
const CAM = {
  cx: 325,
  cy: 195,
  cz: 175,
  yaw: 23.5,
  pitch: 9.2,
  dist: 1460,
  focal: 1590,
  sx0: 555,
  sy0: 615
};

function project(x, y, z) {
  const radYaw = (CAM.yaw * Math.PI) / 180;
  const radPitch = (CAM.pitch * Math.PI) / 180;
  const cy = Math.cos(radYaw), sy = Math.sin(radYaw);
  const cp = Math.cos(radPitch), sp = Math.sin(radPitch);

  const dx = x - CAM.cx;
  const dy = y - CAM.cy;
  const dz = z - CAM.cz;

  const rx = dx * cy - dz * sy;
  const rz0 = dx * sy + dz * cy;

  const ry = dy * cp + rz0 * sp;
  const rz = -dy * sp + rz0 * cp;

  const sc = CAM.focal / (CAM.dist + rz);
  return [CAM.sx0 + rx * sc, CAM.sy0 - ry * sc, sc];
}

function drawPoly2D(pts, curvature = 0.04) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawPoly3D(pts3D, curvature = 0.04) {
  const pts2D = pts3D.map((p) => project(p[0], p[1], p[2]));
  drawPoly2D(pts2D, curvature);
}

function lerpPt3D(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

// Deterministic hash for tile-specific micro-variations
function hash(a, b, c = 0) {
  const n = Math.sin(a * 127.1 + b * 311.7 + c * 74.7) * 43758.5453;
  return n - Math.floor(n);
}

