// ============================================================================
// 2. BUILDING-SITE TIMBER PALLET
// ============================================================================
function drawBox3D(x0, x1, y0, y1, z0, z1, colFront, colSide, colTop, detailSeed = 1) {
  // Top face (y = y1)
  if (colTop) {
    brush.noStroke();
    brush.wash(colTop, 215);
    drawPoly3D([[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], 0.015);
    brush.noWash();
  }

  // Left receding face (x = x0)
  if (colSide) {
    brush.noStroke();
    brush.wash(colSide, 230);
    drawPoly3D([[x0, y0, z0], [x0, y1, z0], [x0, y1, z1], [x0, y0, z1]], 0.015);
    brush.noWash();

    // Dry wood-grain texture on side
    brush.hatchStyle("cpencil", PALETTE.umberBlack, 0.55);
    const pA = project(x0, y0, z0), pB = project(x0, y0, z1);
    const angSide = atan2(pB[1] - pA[1], pB[0] - pA[0]);
    brush.hatch(5.5, angSide, { rand: 0.12 });
    drawPoly3D([[x0, y0, z0], [x0, y1, z0], [x0, y1, z1], [x0, y0, z1]], 0.015);
    brush.noHatch();
  }

  // Front receding face (z = z0)
  if (colFront) {
    brush.noStroke();
    brush.wash(colFront, 225);
    drawPoly3D([[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], 0.015);
    brush.noWash();

    // Dry wood-grain hatching along front face
    brush.hatchStyle("cpencil", PALETTE.woodShadow, 0.55);
    const pA = project(x0, y0, z0), pB = project(x1, y0, z0);
    const angFront = atan2(pB[1] - pA[1], pB[0] - pA[0]);
    brush.hatch(5, angFront, { rand: 0.12 });
    drawPoly3D([[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], 0.015);
    brush.noHatch();
  }

  // Crisp graphite edges & splinters
  brush.set("2B", PALETTE.woodShadow, 0.65);
  const corners = [
    [[x0, y0, z0], [x1, y0, z0]],
    [[x0, y1, z0], [x1, y1, z0]],
    [[x0, y0, z0], [x0, y1, z0]],
    [[x1, y0, z0], [x1, y1, z0]],
    [[x0, y0, z0], [x0, y0, z1]],
    [[x0, y1, z0], [x0, y1, z1]],
    [[x0, y0, z1], [x0, y1, z1]]
  ];
  for (let c = 0; c < corners.length; c++) {
    const a = project(...corners[c][0]);
    const b = project(...corners[c][1]);
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // Wood splits & nail heads
  const ym = (y0 + y1) * 0.5;
  const s1 = project(x0 + 8, ym, z0);
  const s2 = project(x0 + Math.min(75, (x1 - x0) * 0.6), ym + (hash(detailSeed, 1) - 0.5) * 4, z0);
  brush.set("2H", PALETTE.umberBlack, 0.5);
  brush.line(s1[0], s1[1], s2[0], s2[1]);
}

function drawPallet() {
