    brush.fillBleed(0.25, "out");
    brush.fillTexture(0.6, 0.4);
    brush.fill(PALETTE.siennaMid, 95);
    drawPoly3D([[0, 0, pz0], [W, 0, pz0], [W, 0, pz1], [0, 0, pz1]], 0.02);
    brush.noFill();
  }
}

function drawDunnageBattens(yBase, hBatten) {
