// ============================================================================
// 3. CURVED CLAY ROOF TILE GEOMETRY & HYPERREAL RENDERING
// ============================================================================
// Parametric point on a single curved clay roof tile
// u in [0, 1] runs along the curved S/arch cross-section
// zPos runs along the barrel length
// wallOffset: 0 = outer surface, 1 = inner surface (offset by clay thickness T)
function getTilePt(x0, y0, zPos, u, wallOffset, cfg) {
  const W_chord = 66;
  const H_tier = cfg.hTier;
  const T_clay = 13.5;

  // Subtle kiln-warp variation along barrel length and per tile
  const zNorm = (zPos - cfg.z0) / Math.max(1, cfg.z1 - cfg.z0);
  const warp = Math.sin(u * Math.PI) * (cfg.warpAmp * (1 - 0.35 * zNorm));

  // Asymmetric S-barrel arch profile (bold convex arch + upturned water-channel lip near u=0)
  const archBulge =
    (44 + warp) * Math.sin(Math.PI * u) +
    11 * Math.sin(2 * Math.PI * u) -
    5 * Math.cos(Math.PI * u);

  // Chord tangent & normal in (x, y)
  const len = Math.hypot(W_chord, H_tier);
  const nx = -H_tier / len; // points left (-x)
  const ny = W_chord / len; // points up (+y)

  // Slight barrel pitch along Z so the front lip lifts slightly
  const zLift = (1 - zNorm) * 8;

  const totalNormalOffset = archBulge - wallOffset * T_clay;

  const px = x0 + cfg.jx + u * W_chord + nx * totalNormalOffset;
  const py = y0 + cfg.jy + zLift + u * H_tier + ny * totalNormalOffset;
  const pz = zPos + cfg.jz;

  return [px, py, pz];
}

function drawTileTier(tierIdx, yBase, hTier, numTiles) {
  const rows = [
    { rowIdx: 1, z0: 218, z1: 416 }, // Back row (drawn first)
    { rowIdx: 0, z0: 10, z1: 208 }   // Front row (drawn second)
  ];

  const dx = 41.5;
  const xStart = 18;

  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    // Draw from back-right (i = numTiles - 1) to front-left (i = 0)
    for (let i = numTiles - 1; i >= 0; i--) {
      const seed = tierIdx * 100 + row.rowIdx * 30 + i;
      const cfg = {
        tierIdx,
        rowIdx: row.rowIdx,
        tileIdx: i,
        isFrontRow: row.rowIdx === 0,
        isLeadingTile: i === 0,
        x0: xStart + i * dx,
        y0: yBase,
        hTier,
        z0: row.z0,
        z1: row.z1,
        dx,
        jx: (hash(seed, 1) - 0.5) * 3.2,
        jy: (hash(seed, 2) - 0.5) * 2.8,
        jz: (hash(seed, 3) - 0.5) * 3.5,
        warpAmp: (hash(seed, 4) - 0.5) * 6.5,
        hueMix: hash(seed, 5), // shifts between Burnt Sienna, Venetian Red, Raw Umber
        seed
      };
      drawSingleTile(cfg);
    }
  }
}

function drawSingleTile(cfg) {
  const { x0, y0, z0, z1, seed, isFrontRow, isLeadingTile, hueMix } = cfg;
  const stepsU = 14;

  // Choose tile's dominant kiln-fired clay tone within the Fired-Earth family
  const colLight = hueMix < 0.45 ? PALETTE.siennaLight : hueMix < 0.8 ? PALETTE.venetianLight : PALETTE.siennaMid;
  const colMid = hueMix < 0.45 ? PALETTE.siennaMid : hueMix < 0.8 ? PALETTE.venetianMid : PALETTE.umberLight;
  const colDeep = hueMix < 0.45 ? PALETTE.siennaDeep : hueMix < 0.8 ? PALETTE.venetianDeep : PALETTE.umberMid;

  // Precompute outer & inner arch points at front (z0) and back (z1)
  const frontOut = [], frontIn = [], backOut = [], backIn = [];
  for (let k = 0; k <= stepsU; k++) {
    const u = k / stepsU;
    frontOut.push(getTilePt(x0, y0, z0, u, 0, cfg));
    frontIn.push(getTilePt(x0, y0, z0, u, 1, cfg));
    backOut.push(getTilePt(x0, y0, z1, u, 0, cfg));
    backIn.push(getTilePt(x0, y0, z1, u, 1, cfg));
  }

  // -------------------------------------------------------------------------
  // A. DEEP CAST SHADOW POCKET & CONCAVE UNDERSIDE VAULT
  // -------------------------------------------------------------------------
  if (isFrontRow) {
    // Shadow cast onto the adjacent tile (i + 1) tucked under this tile's arch
    const shadowPoly = [];
    for (let k = 1; k <= stepsU - 1; k++) {
      shadowPoly.push(frontIn[k]);
    }
    for (let k = stepsU - 1; k >= 1; k--) {
      const p = frontIn[k];
      shadowPoly.push([p[0] + cfg.dx * 0.68, p[1] - 10, p[2] + 8]);
    }
    brush.noStroke();
    brush.wash(PALETTE.umberBlack, 195);
    drawPoly3D(shadowPoly, 0.04);
    brush.noWash();

    // Concave underside vault receding into Z under the lip
    const vaultPoly = [];
    for (let k = 1; k <= stepsU - 1; k++) vaultPoly.push(frontIn[k]);
    for (let k = stepsU - 1; k >= 1; k--) {
      const p = lerpPt3D(frontIn[k], backIn[k], 0.28);
      vaultPoly.push([p[0] + 10, p[1] - 8, p[2]]);
    }
    brush.wash(PALETTE.umberDeep, 210);
    drawPoly3D(vaultPoly, 0.04);
    brush.noWash();
  }

  // -------------------------------------------------------------------------
  // B. CURVED CLAY BARREL EXTERIOR (Layered Watercolor + Dry Chalky Mass)
  // -------------------------------------------------------------------------
  // For leading tile (i = 0), draw full u in [0, 1]; for nested tiles, u in [0.42, 1] is visible
  const uStartIdx = isLeadingTile ? 0 : 5;

  // Divide barrel into 2 cylindrical lighting bands:
  // Band 1: Lower/mid curve (u from uStartIdx to 9) - warm mid-tone turning into shadow
  // Band 2: Upper crest curve (u from 8 to stepsU) - catches overcast zenith light
  const band1 = [];
  for (let k = uStartIdx; k <= 10; k++) band1.push(frontOut[k]);
  for (let k = 10; k >= uStartIdx; k--) band1.push(backOut[k]);

  const band2 = [];
  for (let k = 8; k <= stepsU; k++) band2.push(frontOut[k]);
  for (let k = stepsU; k >= 8; k--) band2.push(backOut[k]);

  // Opaque clay base under-wash so tiles cleanly occlude tiles behind them
  const fullBarrel = [];
  for (let k = uStartIdx; k <= stepsU; k++) fullBarrel.push(frontOut[k]);
  for (let k = stepsU; k >= uStartIdx; k--) fullBarrel.push(backOut[k]);

  brush.noStroke();
  brush.wash(PALETTE.paper, 245);
  drawPoly3D(fullBarrel, 0.03);
  brush.noWash();

  // Layered Watercolor Washes (Burnt Sienna, Venetian Red, Raw Umber)
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.72, 0.48);

  brush.fill(colMid, 165);
  drawPoly3D(band1, 0.03);

  brush.fill(colLight, 155);
  drawPoly3D(band2, 0.03);

  // Raw umber overcast shadow wash along the lower belly and back depth
  if (isLeadingTile) {
    const bellyShadow = [];
    for (let k = 0; k <= 6; k++) bellyShadow.push(frontOut[k]);
    for (let k = 6; k >= 0; k--) bellyShadow.push(backOut[k]);
    brush.fill(PALETTE.umberMid, 165);
    drawPoly3D(bellyShadow, 0.03);
  } else {
    // Soft occlusion wash where tile tucks under the neighbor to its left
    const tuckShadow = [
      frontOut[uStartIdx],
      frontOut[uStartIdx + 3],
      backOut[uStartIdx + 3],
      backOut[uStartIdx]
    ];
    brush.fill(PALETTE.umberDeep, 150);
    drawPoly3D(tuckShadow, 0.02);
  }
  brush.noFill();

  // Dry Chalky Charcoal-like Mass scumbled over the watercolor so it reads as porous clay
  if (isFrontRow || isLeadingTile || cfg.tileIdx % 2 === 0) {
    const massCol = hueMix < 0.5 ? PALETTE.siennaLight : PALETTE.venetianLight;
    brush.mass("charcoal", massCol, {
      precision: 0.35,
      strength: isLeadingTile ? 0.65 : 0.45,
      gradient: 0.55,
      outline: false
    });
    drawPoly3D(band2, 0.03);
    brush.noMass();

    // Earthy umber dry mass in the turning shadow band
    if (isLeadingTile || cfg.tileIdx % 3 === 0) {
      brush.mass("cpencil", colDeep, {
        precision: 0.4,
        strength: 0.45,
        gradient: 0.6,
        outline: false
      });
      drawPoly3D(band1, 0.03);
      brush.noMass();
    }
  }

  // Barrel longitudinal hatching for porous extruded-clay texture
  const pF = project(...frontOut[11]);
  const pB = project(...backOut[11]);
  const barrelAngle = atan2(pB[1] - pF[1], pB[0] - pF[0]);

  brush.hatchStyle("cpencil", colDeep, 0.55);
  brush.hatch(isLeadingTile ? 4.5 : 6.0, barrelAngle, { rand: 0.15, gradient: 0.4 });
  drawPoly3D(fullBarrel, 0.03);
  brush.noHatch();

  // Dry scumble strokes along barrel
  const numScumbles = isLeadingTile ? 14 : 5;
  for (let s = 0; s < numScumbles; s++) {
    const u0 = isLeadingTile ? 0.1 + hash(seed, s + 10) * 0.85 : 0.52 + hash(seed, s + 10) * 0.44;
    const tZ0 = 0.05 + hash(seed, s + 30) * 0.55;
    const tZ1 = Math.min(0.95, tZ0 + 0.2 + hash(seed, s + 50) * 0.35);
    const sp1 = project(...getTilePt(x0, y0, z0 + (z1 - z0) * tZ0, u0, 0, cfg));
    const sp2 = project(...getTilePt(x0, y0, z0 + (z1 - z0) * tZ1, u0, 0, cfg));
    brush.set("clay_scumble", s % 2 === 0 ? PALETTE.bloomSoft : colDeep, 0.65 + hash(seed, s + 70) * 0.5);
    brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);
  }

  // -------------------------------------------------------------------------
  // C. PALE EFFLORESCENCE BLOOM (Chalky Mineral Salt Deposit on Fired Clay)
  // -------------------------------------------------------------------------
  if (isFrontRow || isLeadingTile) {
    const bloomU0 = isLeadingTile ? 0.28 + hash(seed, 80) * 0.35 : 0.58 + hash(seed, 80) * 0.22;
    const bloomU1 = Math.min(0.96, bloomU0 + (isLeadingTile ? 0.32 : 0.24));
    const bloomZ0 = z0 + (z1 - z0) * (0.04 + hash(seed, 81) * 0.22);
    const bloomZ1 = bloomZ0 + (z1 - z0) * (0.28 + hash(seed, 82) * 0.35);

    const bloomPts = [
      getTilePt(x0, y0, bloomZ0, bloomU0, 0, cfg),
      getTilePt(x0, y0, bloomZ0, (bloomU0 + bloomU1) * 0.5, 0, cfg),
      getTilePt(x0, y0, bloomZ0 + (bloomZ1 - bloomZ0) * 0.2, bloomU1, 0, cfg),
      getTilePt(x0, y0, bloomZ1, bloomU1 * 0.98, 0, cfg),
      getTilePt(x0, y0, bloomZ1, (bloomU0 + bloomU1) * 0.45, 0, cfg),
      getTilePt(x0, y0, bloomZ0 + (bloomZ1 - bloomZ0) * 0.7, bloomU0, 0, cfg)
    ];

    // Translucent chalky watercolor bloom
    brush.noStroke();
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.55, 0.25);
    brush.fill(PALETTE.bloomBright, isLeadingTile ? 95 : 80);
    drawPoly3D(bloomPts, 0.12);
    brush.noFill();

    // Powdery dry chalk spray & charcoal mass over the efflorescence patch
    const bStart = project(...getTilePt(x0, y0, bloomZ0, (bloomU0 + bloomU1) * 0.5, 0, cfg));
    const bEnd = project(...getTilePt(x0, y0, bloomZ1, (bloomU0 + bloomU1) * 0.5, 0, cfg));
    brush.set("chalk_bloom", PALETTE.bloomBright, isLeadingTile ? 1.15 : 0.85);
    brush.line(bStart[0], bStart[1], bEnd[0], bEnd[1]);

    // Second smaller salt halo near the front curved lip
    const lipBloomA = project(...getTilePt(x0, y0, z0 + 6, 0.72, 0, cfg));
    const lipBloomB = project(...getTilePt(x0, y0, z0 + 38, 0.86, 0, cfg));
    brush.set("chalk_bloom", PALETTE.bloomMid, 0.75);
    brush.line(lipBloomA[0], lipBloomA[1], lipBloomB[0], lipBloomB[1]);
  }

  // -------------------------------------------------------------------------
  // D. THE SCULPTURAL CURVED LIP (Front Rim at z = z0)
  // -------------------------------------------------------------------------
  // Draw the thick cross-sectional rim ribbon in 3 tonal segments so the curve turns in light
  const segRanges = [
    { k0: 0, k1: 5, col: colDeep },       // Lower steep lip skirt
    { k0: 5, k1: 11, col: colLight },     // Upper-left convex arch crest (catches overcast sky light)
    { k0: 11, k1: stepsU, col: colMid }   // Top-right lip flange
  ];

  for (let s = 0; s < segRanges.length; s++) {
    const { k0, k1, col } = segRanges[s];
    const segPoly = [];
    for (let k = k0; k <= k1; k++) segPoly.push(frontOut[k]);
    for (let k = k1; k >= k0; k--) segPoly.push(frontIn[k]);

    brush.noStroke();
    brush.wash(col, 235);
    drawPoly3D(segPoly, 0.03);
    brush.noWash();
  }

  // Pale chalky highlight along the upper curve of the lip
  if (isFrontRow) {
    const lipHi = [];
    for (let k = 5; k <= 11; k++) {
      const pO = frontOut[k], pI = frontIn[k];
      lipHi.push(lerpPt3D(pO, pI, 0.15));
    }
    for (let k = 11; k >= 5; k--) {
      const pO = frontOut[k], pI = frontIn[k];
      lipHi.push(lerpPt3D(pO, pI, 0.65));
    }
    brush.noStroke();
    brush.wash(PALETTE.bloomMid, 95);
    drawPoly3D(lipHi, 0.04);
    brush.noWash();
  }

  // -------------------------------------------------------------------------
  // E. CRISP PENCIL-SHARP CHIPS ON EACH TILE LIP
  // -------------------------------------------------------------------------
  // 2 to 3 angular fracture chips carved into the curved lip of each tile
  const chipLocations = isFrontRow ? [0.28 + hash(seed, 91) * 0.14, 0.62 + hash(seed, 92) * 0.18, 0.88 + hash(seed, 93) * 0.08] : [0.72 + hash(seed, 91) * 0.18];

  for (let c = 0; c < chipLocations.length; c++) {
    const uc = chipLocations[c];
    const du = 0.038 + hash(seed, c + 95) * 0.032;
    const uA = Math.max(0.04, uc - du);
    const uB = Math.min(0.96, uc + du);

    const pOutA = project(...getTilePt(x0, y0, z0, uA, 0, cfg));
    const pOutMid = project(...getTilePt(x0, y0, z0, uc, 0.58, cfg)); // notched inward into rim
    const pOutB = project(...getTilePt(x0, y0, z0, uB, 0, cfg));
    const pBackMid = project(...getTilePt(x0, y0, z0 + 14, uc, 0.18, cfg)); // fracture retreating into barrel

    // 1. Raw pale inner terracotta fracture plane (sky-facing)
    brush.noStroke();
    brush.wash(PALETTE.chipCoreLight, 240);
    drawPoly2D([pOutA, pOutMid, pOutB, pBackMid], 0.01);
    brush.noWash();

    // 2. Crisp dark step-shadow facet inside the chip notch
    brush.wash(PALETTE.umberBlack, 225);
    drawPoly2D([pOutA, pOutMid, pBackMid], 0.01);
    brush.noWash();

    // 3. Razor-sharp pencil outlines around the chip facets
    brush.set("2H", PALETTE.umberBlack, 0.6);
    brush.line(pOutA[0], pOutA[1], pOutMid[0], pOutMid[1]);
    brush.line(pOutMid[0], pOutMid[1], pOutB[0], pOutB[1]);
    brush.line(pOutA[0], pOutA[1], pBackMid[0], pBackMid[1]);
    brush.line(pBackMid[0], pBackMid[1], pOutB[0], pOutB[1]);

    brush.set("hairline", PALETTE.bloomBright, 0.7);
    brush.line(pOutMid[0], pOutMid[1], pOutB[0], pOutB[1]);
  }

  // -------------------------------------------------------------------------
  // F. CRISP GRAPHITE CONTOURS OF THE CURVED LIP & BARREL EDGES
  // -------------------------------------------------------------------------
  const outer2D = frontOut.map((p) => project(...p));
  const inner2D = frontIn.map((p) => project(...p));

  // Outer curved lip edge
  brush.set("2H", PALETTE.umberDeep, isFrontRow ? 0.78 : 0.55);
  const outerSpline = outer2D.map((p, idx) => [p[0], p[1], idx > 4 && idx < 11 ? 1.15 : 0.75]);
  brush.spline(outerSpline, 0.35);

  // Inner curved lip edge (heavier dark accent where arch undercuts into shadow)
  brush.set("HB", PALETTE.umberBlack, isFrontRow ? 0.95 : 0.65);
  const innerSpline = inner2D.map((p, idx) => [p[0], p[1], idx > 3 && idx < 12 ? 1.3 : 0.65]);
  brush.spline(innerSpline, 0.35);

  // Bottom lip toe edge (u = 0) & top lip flange edge (u = 1)
  brush.set("2H", PALETTE.umberBlack, 0.65);
  brush.line(outer2D[0][0], outer2D[0][1], inner2D[0][0], inner2D[0][1]);
  brush.line(outer2D[stepsU][0], outer2D[stepsU][1], inner2D[stepsU][0], inner2D[stepsU][1]);

  // Top edge of tile barrel receding along Z (u = 1)
  const topF = project(...frontOut[stepsU]);
  const topB = project(...backOut[stepsU]);
  brush.set("2H", PALETTE.umberDeep, 0.58);
  brush.line(topF[0], topF[1], topB[0], topB[1]);

  // Back arch rim at z = z1 (visible across the top crest)
  const backCrest2D = [];
  for (let k = uStartIdx; k <= stepsU; k++) {
    backCrest2D.push(project(...backOut[k]));
  }
  brush.set("2H", PALETTE.umberMid, 0.55);
  brush.spline(backCrest2D.map((p) => [p[0], p[1], 0.8]), 0.35);

  // If leading tile (i = 0), also draw bottom barrel edge receding along Z (u = 0)
  if (isLeadingTile) {
    const botF = project(...frontOut[0]);
    const botB = project(...backOut[0]);
    brush.set("HB", PALETTE.umberBlack, 0.8);
    brush.line(botF[0], botF[1], botB[0], botB[1]);
  }

  // -------------------------------------------------------------------------
  // G. FINE HAIRLINE CRACKS IN THE FIRED CLAY
  // -------------------------------------------------------------------------
  if (isFrontRow || isLeadingTile) {
    const numCracks = isLeadingTile ? 3 : 2;
    for (let cr = 0; cr < numCracks; cr++) {
      const uStart = isLeadingTile
        ? 0.22 + cr * 0.28 + (hash(seed, cr + 110) - 0.5) * 0.08
        : 0.58 + cr * 0.2 + (hash(seed, cr + 110) - 0.5) * 0.06;

      const crackLenZ = (z1 - z0) * (0.28 + hash(seed, cr + 120) * 0.42);
      const segs = 5;
      const crackPts = [];
      const crackHiPts = [];

      let currU = Math.min(0.95, Math.max(0.08, uStart));
      let currZ = z0 + (cr === 0 ? 0 : (z1 - z0) * 0.15 * hash(seed, cr + 130));

      for (let s = 0; s <= segs; s++) {
        const pt3D = getTilePt(x0, y0, currZ, currU, 0, cfg);
        const pt2D = project(...pt3D);
        crackPts.push([pt2D[0], pt2D[1], 1.0 - (s / segs) * 0.65]);
        crackHiPts.push([pt2D[0] + 1.1, pt2D[1] + 0.9, 0.8 - (s / segs) * 0.5]);

        currZ += crackLenZ / segs;
        currU = Math.min(0.96, Math.max(0.06, currU + (hash(seed, cr * 10 + s + 140) - 0.48) * 0.055));
      }

      // Pale relief edge alongside fissure
      brush.set("hairline", PALETTE.bloomBright, 0.65);
      brush.spline(crackHiPts, 0.15);

      // Dark razor-thin hairline crack
      brush.set("hairline", PALETTE.umberBlack, 0.95);
      brush.spline(crackPts, 0.15);

      // Tiny bifurcated branch off the main crack
      if (cr === 0 && crackPts.length >= 4) {
        const branchStart = crackPts[2];
        const bEnd3D = getTilePt(x0, y0, z0 + crackLenZ * 0.62, Math.min(0.96, currU + 0.07), 0, cfg);
        const bEnd2D = project(...bEnd3D);
        brush.set("hairline", PALETTE.umberBlack, 0.7);
        brush.line(branchStart[0], branchStart[1], bEnd2D[0], bEnd2D[1]);
      }
    }
  }
}

// ============================================================================
// 4. HORIZONTAL / ANGLED CAP TILES ON TOP OF THE STACK
// ============================================================================
function drawTopCapTiles(yTop) {
  // 3 loose curved tiles resting horizontally across the top of Tier 1
  const capSpecs = [
    { x0: 460, z0: 195, lenX: 195, widZ: 125, yawOffset: -8, seed: 501 },
    { x0: 210, z0: 175, lenX: 205, widZ: 130, yawOffset: 6, seed: 502 },
    { x0: 85, z0: 35, lenX: 210, widZ: 132, yawOffset: -4, seed: 503 }
  ];

  for (let c = 0; c < capSpecs.length; c++) {
    const sp = capSpecs[c];
    const steps = 12;
    const rad = (sp.yawOffset * Math.PI) / 180;
    const ca = Math.cos(rad), sa = Math.sin(rad);

    function capPt(s, tLen, wallOff) {
      // s in [0, 1] across arch width; tLen in [0, 1] along barrel length
      const localZ = (s - 0.5) * sp.widZ;
      const localX = tLen * sp.lenX;
      const archY = 44 * Math.sin(Math.PI * s) - wallOff * 12.5;
      const wx = sp.x0 + localX * ca - localZ * sa;
      const wz = sp.z0 + localX * sa + localZ * ca;
      const wy = yTop + archY;
      return [wx, wy, wz];
    }

    // Cast shadow onto the tier crest below
    brush.noStroke();
    brush.wash(PALETTE.umberBlack, 175);
    drawPoly3D([
      capPt(0.02, 0, 1),
      capPt(0.02, 1, 1),
      capPt(0.98, 1, 1),
      capPt(0.98, 0, 1)
    ], 0.03);
    brush.noWash();

    // Concave hollow arch shadow under the front lip (tLen = 0)
    const archUnder = [];
    for (let k = 0; k <= steps; k++) archUnder.push(capPt(k / steps, 0, 1));
    for (let k = steps; k >= 0; k--) archUnder.push(capPt(k / steps, 0.25, 1));
    brush.wash(PALETTE.umberBlack, 225);
    drawPoly3D(archUnder, 0.04);
    brush.noWash();

    // Top curved clay barrel surface
    const barrelPts = [];
    for (let k = 0; k <= steps; k++) barrelPts.push(capPt(k / steps, 0, 0));
    for (let k = steps; k >= 0; k--) barrelPts.push(capPt(k / steps, 1, 0));

    brush.wash(PALETTE.paper, 245);
    drawPoly3D(barrelPts, 0.03);
    brush.noWash();

    brush.fillBleed(0.25, "in");
    brush.fillTexture(0.7, 0.45);
    brush.fill(c === 1 ? PALETTE.venetianMid : PALETTE.siennaMid, 170);
    drawPoly3D(barrelPts, 0.03);

    // Highlight crest along top of arch (s in [0.3, 0.75])
    const crestPts = [];
    for (let k = 3; k <= 9; k++) crestPts.push(capPt(k / steps, 0, 0));
    for (let k = 9; k >= 3; k--) crestPts.push(capPt(k / steps, 1, 0));
    brush.fill(PALETTE.siennaLight, 145);
    drawPoly3D(crestPts, 0.03);

    // Pale efflorescence bloom on top barrel
    const bloomPts = [
      capPt(0.32, 0.18, 0),
      capPt(0.68, 0.22, 0),
      capPt(0.74, 0.68, 0),
      capPt(0.28, 0.62, 0)
    ];
    brush.fill(PALETTE.bloomBright, 90);
    drawPoly3D(bloomPts, 0.1);
    brush.noFill();

    brush.mass("charcoal", PALETTE.siennaLight, { precision: 0.35, strength: 0.55, gradient: 0.5, outline: false });
    drawPoly3D(crestPts, 0.03);
    brush.noMass();

    // Front curved arch lip (tLen = 0)
    const lipPts = [];
    for (let k = 0; k <= steps; k++) lipPts.push(capPt(k / steps, 0, 0));
    for (let k = steps; k >= 0; k--) lipPts.push(capPt(k / steps, 0, 1));
    brush.wash(PALETTE.siennaLight, 235);
    drawPoly3D(lipPts, 0.03);
    brush.noWash();

    // Crisp pencil outlines & chips on cap tile lip
    const out2D = [], in2D = [];
    for (let k = 0; k <= steps; k++) {
      out2D.push(project(...capPt(k / steps, 0, 0)));
      in2D.push(project(...capPt(k / steps, 0, 1)));
    }
    brush.set("2H", PALETTE.umberDeep, 0.75);
    brush.spline(out2D.map((p) => [p[0], p[1], 0.9]), 0.35);
    brush.set("HB", PALETTE.umberBlack, 0.95);
    brush.spline(in2D.map((p) => [p[0], p[1], 1.1]), 0.35);

    // Side edges of cap tile barrel
    const sA0 = project(...capPt(0, 0, 0)), sA1 = project(...capPt(0, 1, 0));
    const sB0 = project(...capPt(1, 0, 0)), sB1 = project(...capPt(1, 1, 0));
    brush.set("HB", PALETTE.umberBlack, 0.7);
    brush.line(sA0[0], sA0[1], sA1[0], sA1[1]);
    brush.line(sB0[0], sB0[1], sB1[0], sB1[1]);

    // Hairline crack on cap tile
    const crA = project(...capPt(0.48, 0, 0));
    const crM = project(...capPt(0.52, 0.25, 0));
    const crB = project(...capPt(0.46, 0.52, 0));
    brush.set("hairline", PALETTE.umberBlack, 0.95);
    brush.spline([[crA[0], crA[1], 1], [crM[0], crM[1], 0.8], [crB[0], crB[1], 0.4]], 0.2);
  }
}

