// =============================================================================
// GEOMETRY & LIGHTING HELPERS
// =============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Returns [0..1] illumination intensity at point (x, y) from all crepuscular rays
function getLightIntensity(x, y) {
  if (x < 130) return 0;
  let total = 0;
  for (let i = 0; i < RAYS.length; i++) {
    let r = RAYS[i];
    let dxW = r.wx - SUN.x;
    let dyW = r.wy - SUN.y;
    let distW = Math.hypot(dxW, dyW);
    let ux = dxW / distW;
    let uy = dyW / distW;
    let nx = -uy;
    let ny = ux;

    let dxP = x - SUN.x;
    let dyP = y - SUN.y;
    let proj = dxP * ux + dyP * uy;
    if (proj < distW * 0.96) continue;

    let perp = Math.abs(dxP * nx + dyP * ny);
    let localHalfW = r.halfW * (proj / distW);

    if (perp < localHalfW * 1.35) {
      let norm = perp / localHalfW;
      let profile = norm < 0.78 ? 1.0 : Math.max(0, 1.0 - (norm - 0.78) / 0.57);
      profile = profile * profile * (3 - 2 * profile);
      // Internal sub-streaks caused by wood splinters in the wall slits
      let streak = 0.82 + 0.18 * Math.sin(norm * 9.5 + i * 2.1);
      // Slight attenuation across the room
      let atten = map(proj, distW, distW + 1250, 1.0, 0.62, true);
      total += r.intensity * profile * streak * atten;
    }
  }
  return constrain(total, 0, 1.15);
}

// Bilinear interpolation on a quad [TL, TR, BR, BL]
function quadPt(q, u, v) {
  let xTop = lerp(q[0][0], q[1][0], u);
  let yTop = lerp(q[0][1], q[1][1], u);
  let xBot = lerp(q[3][0], q[2][0], u);
  let yBot = lerp(q[3][1], q[2][1], u);
  return [lerp(xTop, xBot, v), lerp(yTop, yBot, v)];
}

function lerpHex(c1, c2, t) {
  return lerpColor(color(c1), color(c2), constrain(t, 0, 1));
}

// =============================================================================
// 1. DEEP VELVETY CHARCOAL GROUND & WORKSHOP ARCHITECTURE
// =============================================================================

function drawWorkshopMurk() {
  resetBrushState();

  // Deep cool slate-indigo base washes
  const murkZones = [
    { pts: [[0, 0], [1200, 0], [1200, 1200], [0, 1200]], col: "#0b1018", op: 180 },
    { pts: [[240, 0], [1200, 0], [1200, 520], [240, 420]], col: "#0f1722", op: 110 },
    { pts: [[240, 400], [1180, 360], [1180, 860], [240, 860]], col: "#141f2e", op: 95 },
    { pts: [[0, 780], [1200, 740], [1200, 1200], [0, 1200]], col: "#090d14", op: 150 }
  ];

  for (let z of murkZones) {
    brush.wash(z.col, z.op);
    drawPoly(z.pts);
  }
  brush.noWash();

  // Dense charcoal mass passes for velvety depth
  const massBlocks = [
    { pts: [[250, 20], [1180, 20], [1180, 360], [250, 310]], col: "#0d131c", str: 0.65 },
    { pts: [[720, 280], [1190, 280], [1190, 820], [760, 820]], col: "#101824", str: 0.7 },
    { pts: [[0, 820], [620, 820], [520, 1190], [0, 1190]], col: "#080c12", str: 0.8 }
  ];

  for (let mb of massBlocks) {
    brush.mass("charcoal", mb.col, { precision: 0.35, strength: mb.str, gradient: 0.4, outline: false });
    drawPoly(mb.pts);
  }
  brush.noMass();

  // Ghostly background vertical wall planks in the back murk (x: 270..1200, y: 180..780)
  brush.set("charcoal", "#172230", 1.1);
  for (let x = 285; x < 1180; x += 58) {
    let jitterX = x + random(-3, 3);
    brush.set("charcoal", "#0a0f16", 1.4);
    brush.line(jitterX, 160, jitterX, 785);
    brush.set("2B", "#1e2c3d", 0.7);
    brush.line(jitterX + 3, 180, jitterX + 3, 770);

    // Subtle wood grain hatches on distant planks
    if (x < 920) {
      brush.set("fine_graphite", "#182433", 0.65);
      for (let g = 0; g < 9; g++) {
        let gx = jitterX + random(6, 52);
        let gy1 = random(210, 620);
        let gy2 = gy1 + random(45, 130);
        brush.line(gx, gy1, gx, gy2);
      }
    }
  }

  // Heavy overhead timber rafters & tie beams in upper murk
  const rafters = [
    [[240, 45], [1200, 10], [1200, 75], [240, 98]],
    [[250, 145], [1200, 115], [1200, 168], [250, 190]],
    [[420, 0], [510, 0], [340, 210], [275, 210]],
    [[780, 0], [870, 0], [720, 220], [650, 220]]
  ];

  for (let rf of rafters) {
    resetBrushState();
    brush.wash("#0b1017", 210);
    drawPoly(rf);
    brush.noWash();

    brush.hatchStyle("charcoal", "#16202d", 0.9);
    brush.hatch(9, 12, { rand: 0.15 });
    drawPoly(rf);
    brush.noHatch();

    // Faint cool edge highlight on underside of rafters
    brush.set("2B", "#263649", 0.8);
    brush.line(rf[3][0], rf[3][1], rf[2][0], rf[2][1]);
  }

  // Ghostly background workbench & hanging tools in the right murk (x: 760..1150, y: 430..790)
  resetBrushState();
  // Distant bench top
  brush.wash("#121b26", 190);
  drawPoly([[750, 560], [1170, 545], [1170, 582], [740, 598]]);
  // Distant bench legs
  drawPoly([[775, 596], [805, 595], [800, 790], [770, 790]]);
  drawPoly([[1080, 582], [1112, 580], [1110, 790], [1078, 790]]);
  brush.noWash();

  brush.set("2B", "#243447", 0.75);
  brush.line(750, 560, 1170, 545);
  brush.line(740, 598, 1170, 582);

  // Faint silhouettes of hanging clamps & hand saws on back wall rack (x: 820..1100, y: 310..500)
  brush.set("charcoal", "#1c2938", 1.1);
  brush.line(810, 340, 1130, 330); // tool rack bar
  for (let tx = 845; tx <= 1085; tx += 48) {
    let hLen = random(75, 135);
    brush.set("2B", "#16212e", 1.2);
    brush.line(tx, 332, tx, 332 + hLen);
    brush.line(tx - 8, 335, tx + 14, 335);
    brush.line(tx - 6, 332 + hLen, tx + 16, 332 + hLen);
    brush.set("fine_graphite", "#2b3d52", 0.55);
    brush.line(tx + 2, 335, tx + 2, 330 + hLen);
  }

  // Workshop floorboards (y: 775..1200) receding in perspective
  let floorLinesY = [780, 822, 872, 932, 1004, 1090, 1190];
  for (let i = 0; i < floorLinesY.length - 1; i++) {
    let y1 = floorLinesY[i];
    let y2 = floorLinesY[i + 1];
    // Horizontal plank seams slanting slightly
    brush.set("charcoal", "#070a0f", 1.2);
    brush.line(0, y1 + 18, 1200, y1 - 24);

    // Subtle cool plank tone modulated by floor light
    for (let sx = 60; sx < 1160; sx += 45) {
      let sy = lerp(y1, y2, 0.5) + map(sx, 0, 1200, 18, -24);
      let lit = getLightIntensity(sx, sy);
      let col = lerpHex("#121a24", "#4a5866", lit * 0.85);
      brush.set("2B", col, 0.8);
      brush.line(sx, sy + random(-6, 6), sx + 42, sy - 1 + random(-6, 6));
    }
  }

  // Smudged charcoal atmosphere across the whole background
  brush.set("velvet_charcoal", "#0b111a", 1.4);
  for (let i = 0; i < 65; i++) {
    let x1 = random(240, 1180);
    let y1 = random(40, 1150);
    // Avoid smudging heavily right over the hero focal area yet
    let angle = random(-15, 25);
    let len = random(90, 240);
    brush.line(x1, y1, x1 + cos(angle) * len, y1 + sin(angle) * len);
  }
}

// =============================================================================
// 2. LEFT TIMBER PLANK WALL & GLOWING SLITS
// =============================================================================

function drawLeftPlankWall() {
  resetBrushState();

  // Dark interior wall mass on the left (x: 0..275)
  brush.wash("#080c12", 235);
  drawPoly([[0, 0], [275, 0], [262, 920], [0, 980]]);
  brush.noWash();

  // Heavy vertical corner post at x: 238..278
  let postPts = [[238, 0], [278, 0], [264, 930], [226, 945]];
  brush.mass("charcoal", "#0d141e", { precision: 0.5, strength: 0.8, gradient: 0.3, outline: true });
  drawPoly(postPts);
  brush.noMass();

  // Vertical grain & splits on the corner post
  for (let i = 0; i < 28; i++) {
    let t = i / 28;
    let px1 = lerp(238, 276, t);
    let px2 = lerp(226, 262, t);
    brush.set("2B", i > 22 ? "#2b3b4e" : "#151f2c", 0.75);
    brush.line(px1, 0, px2, 935);
  }

  // Horizontal weathered siding planks on left wall (x: 0..245)
  const plankEdges = [0, 74, 122, 190, 222, 256, 358, 436, 525, 620, 725, 840, 960];
  for (let i = 0; i < plankEdges.length - 1; i++) {
    let yTopR = plankEdges[i];
    let yBotR = plankEdges[i + 1] - (i <= 5 ? 5 : 2); // leave gaps for the light slits!
    let yTopL = yTopR + 34;
    let yBotL = yBotR + 34;

    let pQuad = [[0, yTopL], [244, yTopR], [242, yBotR], [0, yBotL]];
    resetBrushState();
    brush.wash("#0b1018", 220);
    drawPoly(pQuad);
    brush.noWash();

    // Rough saw-textured wood grain on each horizontal wall plank
    brush.hatchStyle("charcoal", "#16212f", 0.8);
    brush.hatch(7, -8, { rand: 0.12 });
    drawPoly(pQuad);
    brush.noHatch();

    // Rim-lit plank edges next to the glowing slits
    if (i <= 6) {
      brush.set("cpencil", "#7a8fa3", 0.7);
      brush.line(30, lerp(yBotL, yBotR, 0.12), 238, yBotR);
      brush.set("beam_pencil", "#d8be8c", 0.8);
      brush.line(85, lerp(yBotL, yBotR, 0.35), 215, lerp(yBotL, yBotR, 0.88));
    }
  }

  // Render the incandescent light gaps / chinks between the planks where the rays burst through!
  for (let r of RAYS) {
    let slope = -0.14;
    let x1 = Math.max(18, r.wx - 75);
    let x2 = Math.min(240, r.wx + 42);
    let y1 = r.wy + (x1 - r.wx) * slope;
    let y2 = r.wy + (x2 - r.wx) * slope;
    let gapH = map(r.halfW, 9, 48, 3.5, 22);

    // Outer warm halation around the slit
    resetBrushState();
    brush.fill("#e8c88b", 120);
    brush.fillBleed(0.35, "out");
    drawPoly([
      [x1 - 6, y1 - gapH * 0.9],
      [x2 + 6, y2 - gapH * 0.9],
      [x2 + 6, y2 + gapH * 0.9],
      [x1 - 6, y1 + gapH * 0.9]
    ]);
    brush.noFill();

    // Crisp incandescent slit core
    brush.wash("#fff9eb", 245);
    drawPoly([
      [x1, y1 - gapH * 0.48],
      [x2, y2 - gapH * 0.48],
      [x2, y2 + gapH * 0.48],
      [x1, y1 + gapH * 0.48]
    ]);
    brush.noWash();

    // Pure white razor center & splinter silhouettes interrupting the wide hero gap
    brush.set("razor_etch", "#ffffff", 1.3);
    for (let s = -0.4; s <= 0.4; s += 0.2) {
      brush.line(x1, y1 + gapH * s, x2, y2 + gapH * s);
    }

    if (r.id === 4) {
      // Small vertical wood splinters/louver slats in the Hero Gap creating internal beam striations
      brush.set("razor_etch", "#1a1410", 1.4);
      brush.line(142, r.wy - 10, 140, r.wy + 14);
      brush.line(192, r.wy - 14, 190, r.wy + 10);
    }
  }
}

// =============================================================================
// 3. CREPUSCULAR RAYS UNDER-PASS (ATMOSPHERIC WASHES & INITIAL PENCIL STREAKS)
// =============================================================================

function drawCrepuscularUnderpass() {
  resetBrushState();

  // Soft volumetric washes along each ray
  for (let r of RAYS) {
    let dxW = r.wx - SUN.x;
    let dyW = r.wy - SUN.y;
    let distW = Math.hypot(dxW, dyW);
    let ux = dxW / distW;
    let uy = dyW / distW;
    let nx = -uy;
    let ny = ux;

    let len = 1350;
    let endX = r.wx + ux * len;
    let endY = r.wy + uy * len;
    let endHalfW = r.halfW * ((distW + len) / distW);

    let rayPoly = [
      [r.wx - nx * r.halfW * 0.7, r.wy - ny * r.halfW * 0.7],
      [endX - nx * endHalfW, endY - ny * endHalfW],
      [endX + nx * endHalfW, endY + ny * endHalfW],
      [r.wx + nx * r.halfW * 0.7, r.wy + ny * r.halfW * 0.7]
    ];

    // Cool pale blue-slate volumetric base wash
    brush.wash("#7f9bb3", Math.round(14 * r.intensity));
    drawPoly(rayPoly);

    // Inner pale amber late-afternoon glow
    let innerPoly = [
      [r.wx - nx * r.halfW * 0.42, r.wy - ny * r.halfW * 0.42],
      [endX - nx * endHalfW * 0.55, endY - ny * endHalfW * 0.55],
      [endX + nx * endHalfW * 0.55, endY + ny * endHalfW * 0.55],
      [r.wx + nx * r.halfW * 0.42, r.wy + ny * r.halfW * 0.42]
    ];
    brush.wash("#e8cfa0", Math.round(16 * r.intensity));
    drawPoly(innerPoly);
    brush.noWash();

    // First pass of long pencil streaks lifting the beams out of the charcoal murk
    let streakCount = Math.round(map(r.halfW, 9, 48, 45, 220) * r.intensity);
    for (let s = 0; s < streakCount; s++) {
      let t = random(-0.95, 0.95);
      // Bias slightly toward center and sharp outer boundaries
      if (random() < 0.28) t = random() < 0.5 ? random(-0.98, -0.78) : random(0.78, 0.98);

      let d1 = random(0, 880);
      let segLen = random(140, 480);
      let d2 = Math.min(1250, d1 + segLen);

      let w1 = r.halfW * ((distW + d1) / distW) * t;
      let w2 = r.halfW * ((distW + d2) / distW) * t;

      let sx1 = r.wx + ux * d1 + nx * w1;
      let sy1 = r.wy + uy * d1 + ny * w1;
      let sx2 = r.wx + ux * d2 + nx * w2;
      let sy2 = r.wy + uy * d2 + ny * w2;

      let isWarm = random() < r.warm;
      let col = isWarm
        ? (random() < 0.5 ? "#ebd5a7" : "#d9b87c")
        : (random() < 0.5 ? "#d8e4ed" : "#f2f6fa");

      brush.set("beam_pencil", col, random(0.65, 1.35));
      brush.line(sx1, sy1, sx2, sy2);
    }
  }
}

// =============================================================================
// 4. THE SAWHORSE (TIMBER TRESTLE IN PERSPECTIVE)
// =============================================================================

function drawTimberBeamFace(quad, baseDark, baseMid, litWarm, litBright, grainSteps = 28) {
  resetBrushState();

  // Subdivide along u so the timber face responds organically to the light beam
  let slices = 16;
  for (let i = 0; i < slices; i++) {
    let u0 = i / slices;
    let u1 = (i + 1) / slices;
    let p00 = quadPt(quad, u0, 0);
    let p10 = quadPt(quad, u1, 0);
    let p11 = quadPt(quad, u1, 1);
    let p01 = quadPt(quad, u0, 1);
    let mid = quadPt(quad, (u0 + u1) * 0.5, 0.5);
    let lit = getLightIntensity(mid[0], mid[1]);

    let c = lit < 0.35
      ? lerpHex(baseDark, baseMid, lit / 0.35)
      : lerpHex(baseMid, litWarm, (lit - 0.35) / 0.75);

    brush.wash(c, 225);
    drawPoly([p00, p10, p11, p01]);
  }
  brush.noWash();

  // Longitudinal wood grain lines & charcoal/pencil shading
  for (let g = 0; g <= grainSteps; g++) {
    let v = g / grainSteps;
    let subSegs = 12;
    for (let s = 0; s < subSegs; s++) {
      let u0 = s / subSegs;
      let u1 = (s + 1) / subSegs;
      let pt1 = quadPt(quad, u0, v + random(-0.015, 0.015));
      let pt2 = quadPt(quad, u1, v + random(-0.015, 0.015));
      let mx = (pt1[0] + pt2[0]) * 0.5;
      let my = (pt1[1] + pt2[1]) * 0.5;
      let lit = getLightIntensity(mx, my);

      let grainNoise = noise(s * 0.5, g * 0.35);
      let c = lit > 0.45
        ? (grainNoise > 0.52 ? lerpHex(litWarm, litBright, (lit - 0.4) * 1.1) : lerpHex(baseMid, litWarm, 0.6))
        : lerpHex(baseDark, baseMid, grainNoise * 0.8 + lit);

      brush.set(lit > 0.4 ? "fine_graphite" : "2B", c, random(0.6, 1.1));
      brush.line(pt1[0], pt1[1], pt2[0], pt2[1]);
    }
  }

  // Crisp edge definition
  for (let s = 0; s < 10; s++) {
    let u0 = s / 10;
    let u1 = (s + 1) / 10;
    let top0 = quadPt(quad, u0, 0);
    let top1 = quadPt(quad, u1, 0);
    let lit = getLightIntensity((top0[0] + top1[0]) * 0.5, (top0[1] + top1[1]) * 0.5);
    let edgeCol = lit > 0.45 ? litBright : "#253445";
    brush.set("razor_etch", edgeCol, lit > 0.45 ? 1.1 : 0.75);
    brush.line(top0[0], top0[1], top1[0], top1[1]);
  }
}

