// =============================================================================
// 5. THE HALF-CUT PINE BOARD & RAZOR-SHARP END GRAIN
// =============================================================================

function drawPineBoard() {
  resetBrushState();

  // Board geometry: extends from back-left (in cool murk) across the sawhorse
  // into the blazing core of the Hero Beam at front-right (x: 540..825, y: 580..730).
  const BLF = [185, 502]; // Back-Left-Far
  const BLN = [105, 544]; // Back-Left-Near
  const FRF = [822, 622]; // Front-Right-Far (top-right corner of end grain)
  const FRN = [712, 678]; // Front-Right-Near (top-left corner of end grain)

  const thick = 48; // Substantial 2-inch pine timber thickness
  const BoLN = [BLN[0], BLN[1] + 36];
  const BRN  = [FRN[0], FRN[1] + thick];
  const BRF  = [FRF[0], FRF[1] + thick];

  const topFace  = [BLF, FRF, FRN, BLN];
  const sideFace = [BLN, FRN, BRN, BoLN];
  const endFace  = [FRN, FRF, BRF, BRN];

  // Cast shadow of the pine board across the sawhorse ledger beam
  resetBrushState();
  brush.wash("#080c12", 185);
  drawPoly([[465, 688], [645, 626], [685, 650], [505, 715]]);
  brush.noWash();

  // --- A. TOP FACE OF THE PINE BOARD ---
  drawTimberBeamFace(topFace, "#121b26", "#2c3c4f", "#d9b782", "#faecd2", 42);

  // Cathedral heartwood grain arches & knots on the illuminated pine top face
  const grainLoops = 26;
  for (let l = 0; l < grainLoops; l++) {
    let uStart = map(l, 0, grainLoops, 0.15, 0.96);
    let uSpan = random(0.08, 0.22);
    let vCenter = 0.46 + 0.12 * Math.sin(l * 0.45);
    let vAmp = map(l % 7, 0, 6, 0.06, 0.38);

    let pts = [];
    for (let s = 0; s <= 14; s++) {
      let t = s / 14;
      let u = constrain(uStart + (t - 0.5) * uSpan, 0.02, 0.995);
      let v = constrain(vCenter + Math.sin(t * 180) * vAmp * (l % 2 === 0 ? 1 : -1), 0.04, 0.96);
      pts.push(quadPt(topFace, u, v));
    }

    let midPt = pts[7];
    let lit = getLightIntensity(midPt[0], midPt[1]);
    let ringCol = lit > 0.55
      ? lerpHex("#9e6b39", "#b8834d", random(0.2, 0.9))
      : lerpHex("#16202d", "#334457", lit * 1.5);

    brush.set(lit > 0.5 ? "razor_etch" : "fine_graphite", ringCol, lit > 0.5 ? 0.75 : 0.6);
    brush.spline(pts, 0.5);
  }

  // Two tight pine knots on the top face
  const knots = [
    { u: 0.64, v: 0.36, rx: 11, ry: 5.5 },
    { u: 0.86, v: 0.62, rx: 8.5, ry: 4.2 }
  ];
  for (let kn of knots) {
    let kp = quadPt(topFace, kn.u, kn.v);
    for (let r = 1.0; r >= 0.2; r -= 0.2) {
      let col = r > 0.6 ? "#805127" : (r > 0.35 ? "#4a2c13" : "#241407");
      brush.set("razor_etch", col, 0.9);
      let ePts = [];
      for (let a = 0; a < 360; a += 45) {
        ePts.push([kp[0] + cos(a) * kn.rx * r, kp[1] + sin(a) * kn.ry * r]);
      }
      brush.spline(ePts, 0.7);
    }
  }

  // --- B. FRONT-LEFT LONG SIDE FACE OF THE PINE BOARD ---
  drawTimberBeamFace(sideFace, "#0d131c", "#202e3e", "#b59260", "#e8cfa6", 28);

  // Subtle vertical planing chatter marks & bright upper arris edge
  for (let m = 0; m < 45; m++) {
    let u = random(0.42, 0.99);
    let pTop = quadPt(sideFace, u, 0.02);
    let pBot = quadPt(sideFace, u, 0.98);
    let lit = getLightIntensity(pTop[0], pTop[1]);
    if (lit > 0.45) {
      brush.set("razor_etch", random() < 0.5 ? "#9c784c" : "#f5e2be", 0.55);
      brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
    }
  }

  // Razor-sharp white/amber highlight along the front upper arris (BLN -> FRN) in the beam
  for (let s = 0; s < 24; s++) {
    let u0 = s / 24;
    let u1 = (s + 1) / 24;
    let p0 = quadPt(topFace, u0, 1.0);
    let p1 = quadPt(topFace, u1, 1.0);
    let lit = getLightIntensity((p0[0] + p1[0]) * 0.5, (p0[1] + p1[1]) * 0.5);
    if (lit > 0.35) {
      let col = lit > 0.75 ? "#ffffff" : "#f2ddb6";
      brush.set("razor_etch", col, map(lit, 0.35, 1.0, 0.7, 1.45));
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // --- C. RAZOR-CLEAR FRESH PINE END GRAIN (FRN - FRF - BRF - BRN) ---
  resetBrushState();

  // Warm luminous base of fresh-sawn pine end grain
  brush.wash("#f3dfc0", 245);
  drawPoly(endFace);
  brush.noWash();

  // Subtle tonal gradient across end grain (brightest at upper-left near FRN, warm amber toward BRF)
  for (let i = 0; i < 14; i++) {
    let u0 = i / 14;
    let u1 = (i + 1) / 14;
    let c = lerpHex("#fff6e6", "#dfbc86", u0 * 0.85);
    brush.wash(c, 120);
    drawPoly([
      quadPt(endFace, u0, 0),
      quadPt(endFace, u1, 0),
      quadPt(endFace, u1, 1),
      quadPt(endFace, u0, 1)
    ]);
  }
  brush.noWash();

  // Concentric annual growth rings centered near heartwood pith at (u = 0.74, v = 0.88)
  const pithU = 0.74;
  const pithV = 0.88;
  const numRings = 26;

  for (let r = 1; r <= numRings; r++) {
    let radU = r * 0.042;
    let radV = r * 0.088;

    let ringPts = [];
    let highlightPts = [];

    for (let a = 155; a <= 375; a += 4) {
      // Natural organic waviness in pine growth rings
      let wave = 1.0 + 0.035 * Math.sin(a * 3 + r * 1.7) + 0.02 * Math.cos(a * 5 - r);
      let u = pithU + cos(a) * radU * wave;
      let v = pithV + sin(a) * radV * wave;

      if (u >= 0.01 && u <= 0.99 && v >= 0.02 && v <= 0.98) {
        ringPts.push(quadPt(endFace, u, v));
        let uH = constrain(u - 0.012, 0.01, 0.99);
        let vH = constrain(v - 0.025, 0.02, 0.98);
        highlightPts.push(quadPt(endFace, uH, vH));
      }
    }

    if (ringPts.length >= 3) {
      // Crisp earlywood luminous band right beside the latewood ring
      brush.set("razor_etch", r % 2 === 0 ? "#ffffff" : "#fcf0d9", 0.95);
      brush.spline(highlightPts, 0.4);

      // Dense resinous latewood ring in warm sienna-amber & dark umber
      let lateCol = r < 7
        ? "#6b3e19" // darker heartwood near pith
        : (r % 3 === 0 ? "#7d4b21" : "#9e6836");
      brush.set("razor_etch", lateCol, random(0.85, 1.25));
      brush.spline(ringPts, 0.4);
    }
  }

  // Radial medullary rays & tiny pitch checks radiating from pith
  let pithPt = quadPt(endFace, pithU, pithV);
  for (let a = 185; a <= 345; a += 14) {
    let len = random(0.35, 0.85);
    let endU = constrain(pithU + cos(a) * len * 0.7, 0.03, 0.97);
    let endV = constrain(pithV + sin(a) * len * 0.9, 0.05, 0.95);
    let pEnd = quadPt(endFace, endU, endV);
    brush.set("razor_etch", a === 227 || a === 283 ? "#4a2a0f" : "#d4ae79", a === 227 ? 0.95 : 0.5);
    brush.line(pithPt[0], pithPt[1], pEnd[0], pEnd[1]);
  }

  // Fine diagonal saw-tooth kerf striations across the end grain face
  for (let k = 0; k < 38; k++) {
    let uTop = map(k, 0, 38, 0.02, 0.96);
    let uBot = constrain(uTop + 0.045, 0.03, 0.99);
    let p1 = quadPt(endFace, uTop, 0.03);
    let p2 = quadPt(endFace, uBot, 0.97);
    brush.set("razor_etch", k % 2 === 0 ? "#fffaf0" : "#b88a56", 0.45);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Crisp border highlights & fibrous lower saw-exit burr on the end grain
  brush.set("razor_etch", "#ffffff", 1.35);
  brush.line(FRN[0], FRN[1], FRF[0], FRF[1]); // Top end-grain arris
  brush.line(FRN[0], FRN[1], BRN[0], BRN[1]); // Left vertical end-grain arris

  brush.set("razor_etch", "#24160b", 1.1);
  brush.line(BRN[0], BRN[1], BRF[0], BRF[1]); // Bottom shadow edge
  brush.line(FRF[0], FRF[1], BRF[0], BRF[1]); // Far edge

  // Tiny fuzzy torn wood fibers along bottom edge of fresh end-grain cut
  for (let f = 0; f < 22; f++) {
    let t = random(0.05, 0.95);
    let bx = lerp(BRN[0], BRF[0], t);
    let by = lerp(BRN[1], BRF[1], t);
    brush.set("razor_etch", random() < 0.6 ? "#f7e3be" : "#c9a067", 0.65);
    brush.line(bx, by, bx + random(-2, 3), by + random(2, 6));
  }

  // --- D. THE HALF-CUT SAW KERF IN THE PINE BOARD ---
  // Located at u = 0.865 along the board (about 85px back from the end grain)
  const kerfU = 0.865;
  const kNearTop = quadPt(topFace, kerfU, 1.0);       // (~629, 659)
  const kFarStop = quadPt(topFace, kerfU + 0.01, 0.14); // (~708, 616)
  const kSideBot = quadPt(sideFace, kerfU, 0.72);     // (~629, 693)

  // Dark incised slot of the saw kerf
  brush.set("razor_etch", "#0b0704", 2.4);
  brush.line(kNearTop[0], kNearTop[1], kFarStop[0], kFarStop[1]);
  brush.line(kNearTop[0], kNearTop[1], kSideBot[0], kSideBot[1]);

  // Bright raw pine edge on the right lip of the kerf catching the light shaft
  brush.set("razor_etch", "#ffffff", 1.2);
  brush.line(kNearTop[0] + 2.2, kNearTop[1] + 0.5, kFarStop[0] + 2.2, kFarStop[1] + 0.5);
  brush.line(kNearTop[0] + 2.2, kNearTop[1] + 0.5, kSideBot[0] + 2.2, kSideBot[1]);
}

// =============================================================================
// 6. THE STEEL HANDSAW & RAZOR-SHARP GLINTING TEETH
// =============================================================================

function drawSawTeethStrip(x1, y1, x2, y2, toothPitch, toothDepth, brightFactor = 1.0) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let dist = Math.hypot(dx, dy);
  let ux = dx / dist;
  let uy = dy / dist;
  // Normal pointing downward-left (direction teeth point out from blade)
  let nx = -uy;
  let ny = ux;

  let count = Math.floor(dist / toothPitch);

  for (let i = 0; i < count; i++) {
    let d0 = i * toothPitch;
    let dMid = d0 + toothPitch * 0.38; // aggressive crosscut/rip rake angle
    let d1 = (i + 1) * toothPitch;

    let bx0 = x1 + ux * d0;
    let by0 = y1 + uy * d0;
    let bx1 = x1 + ux * d1;
    let by1 = y1 + uy * d1;

    // Alternating tooth set (left-set vs right-set teeth)
    let setOffset = (i % 2 === 0 ? 1.0 : 0.78) * toothDepth;
    let tx = x1 + ux * dMid + nx * setOffset;
    let ty = y1 + uy * dMid + ny * setOffset;

    // Dark steel tooth body triangle
    resetBrushState();
    brush.wash(i % 2 === 0 ? "#4a6278" : "#22303f", 240);
    drawPoly([[bx0, by0], [tx, ty], [bx1, by1]]);
    brush.noWash();

    // Razor-sharp bevel glint on the leading/trailing filed fleam face
    let glintCol = i % 2 === 0
      ? (brightFactor > 0.7 ? "#ffffff" : "#cde0ee")
      : (brightFactor > 0.7 ? "#d8ecfa" : "#89a4bd");

    brush.set("razor_etch", glintCol, i % 2 === 0 ? 1.05 : 0.75);
    brush.line(bx0, by0, tx, ty);

    // Secondary micro-glint at the needle tip of each tooth
    if (brightFactor > 0.65 && i % 2 === 0) {
      brush.set("razor_etch", "#ffffff", 1.3);
      brush.line(tx, ty, bx1 - ux * 1.2, by1 - uy * 1.2);
    }

    // Dark gullet shadow between teeth
    brush.set("razor_etch", "#0d141d", 0.8);
    brush.line(tx, ty, bx1, by1);
  }
}

function drawHandsaw() {
  resetBrushState();

  // The handsaw cuts diagonally through the kerf at (~629, 659) -> (~708, 616)
  // Upper-left heel near handle -> down-right toe protruding past and below the board!
  const HeelTop = [534, 464];
  const HeelBot = [486, 536];
  const KerfTop = [682, 608]; // Where blade spine crosses kerf line
  const KerfBot = [629, 659]; // Where toothed edge enters near edge of board

  // Protruding toe of the saw emerging below/past the kerf
  const ExitTop = [704, 628];
  const ExitBot = [678, 696];
  const ToeTop  = [792, 712];
  const ToeBot  = [764, 748];

  // --- A. PROTRUDING LOWER TOE OF THE SAW BLADE (emerging below the cut in bright light) ---
  const toeQuad = [ExitTop, ToeTop, ToeBot, ExitBot];
  resetBrushState();
  brush.wash("#3c5166", 240);
  drawPoly(toeQuad);
  brush.noWash();

  // Metallic steel sheen & specular gradient on the protruding blade tip
  for (let s = 0; s <= 24; s++) {
    let v = s / 24;
    let p1 = quadPt(toeQuad, 0, v);
    let p2 = quadPt(toeQuad, 1, v);
    let sheen = Math.sin(v * 180);
    let col = sheen > 0.65 ? "#dcebf7" : (sheen > 0.3 ? "#7b96b0" : "#2b3b4b");
    brush.set("fine_graphite", col, 0.85);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Razor-sharp steel teeth along the protruding lower edge (ExitBot -> ToeBot)
  drawSawTeethStrip(ExitBot[0], ExitBot[1], ToeBot[0], ToeBot[1], 5.4, 5.2, 1.0);

  // Crisp white highlight along the bevel of the toe tip
  brush.set("razor_etch", "#ffffff", 1.15);
  brush.line(ToeTop[0], ToeTop[1], ToeBot[0], ToeBot[1]);
  brush.line(ExitTop[0], ExitTop[1], ToeTop[0], ToeTop[1]);

  // --- B. MAIN UPPER SAW BLADE (Heel -> Kerf) ---
  const bladeQuad = [HeelTop, ExitTop, KerfBot, HeelBot];

  // Cast shadow of the saw blade falling onto the bright top face of the pine board
  resetBrushState();
  brush.wash("#1b242e", 160);
  drawPoly([
    [629, 659],
    [704, 628],
    [742, 652],
    [658, 678]
  ]);
  brush.noWash();

  // Base steel wash of main blade
  brush.wash("#334659", 245);
  drawPoly(bladeQuad);
  brush.noWash();

  // High-resolution metallic reflection & tempered steel grain across the blade
  let bladeSlices = 48;
  for (let i = 0; i <= bladeSlices; i++) {
    let u = i / bladeSlices;
    let pTop = quadPt(bladeQuad, u, 0);
    let pBot = quadPt(bladeQuad, u, 1);
    let mx = (pTop[0] + pBot[0]) * 0.5;
    let my = (pTop[1] + pBot[1]) * 0.5;
    let lit = getLightIntensity(mx, my);

    // Warm reflection of the pine board near the kerf (u > 0.62) + cool sky-steel sheen
    let band = 0.5 + 0.5 * Math.sin(u * 420 + 35);
    let c;
    if (u > 0.62 && lit > 0.55) {
      c = band > 0.65 ? "#f0f7fc" : lerpHex("#6e88a1", "#dfcba8", 0.45);
    } else if (lit > 0.4) {
      c = band > 0.7 ? "#d2e3f0" : lerpHex("#3a4f63", "#8aa4bd", lit * 0.85);
    } else {
      c = lerpHex("#18222e", "#344759", band * 0.6 + lit);
    }

    brush.set("fine_graphite", c, 0.95);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // Fine longitudinal steel polish scratches along the blade length
  for (let sc = 0; sc < 28; sc++) {
    let v = random(0.06, 0.94);
    let u1 = random(0.05, 0.65);
    let u2 = constrain(u1 + random(0.2, 0.45), 0.1, 0.98);
    let pt1 = quadPt(bladeQuad, u1, v);
    let pt2 = quadPt(bladeQuad, u2, v);
    let lit = getLightIntensity((pt1[0] + pt2[0]) * 0.5, (pt1[1] + pt2[1]) * 0.5);
    let col = lit > 0.5 ? (random() < 0.5 ? "#ffffff" : "#a8c1d6") : "#233140";
    brush.set("razor_etch", col, 0.6);
    brush.line(pt1[0], pt1[1], pt2[0], pt2[1]);
  }

  // Faint etched maker's medallion in the middle of the steel blade
  let medC = quadPt(bladeQuad, 0.54, 0.48);
  brush.set("razor_etch", "#b8cde0", 0.5);
  brush.circle(medC[0], medC[1], 14, 0.15);
  brush.circle(medC[0], medC[1], 9, 0.15);

  // Razor-sharp top spine highlight of the saw blade
  for (let s = 0; s < 16; s++) {
    let u0 = s / 16;
    let u1 = (s + 1) / 16;
    let p0 = quadPt(bladeQuad, u0, 0);
    let p1 = quadPt(bladeQuad, u1, 0);
    let lit = getLightIntensity((p0[0] + p1[0]) * 0.5, (p0[1] + p1[1]) * 0.5);
    brush.set("razor_etch", lit > 0.45 ? "#ffffff" : "#678199", lit > 0.45 ? 1.3 : 0.85);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Razor-sharp saw teeth along the upper cutting edge (HeelBot -> KerfBot) above the plank!
  drawSawTeethStrip(HeelBot[0], HeelBot[1], KerfBot[0], KerfBot[1], 5.4, 5.4, 0.92);

  // Re-establish the crisp wood lip overlapping the buried portion of the blade in the kerf
  brush.set("razor_etch", "#fff6e3", 1.25);
  brush.line(631, 659, 631, 692);
  brush.set("razor_etch", "#c79e65", 0.95);
  brush.line(633, 660, 633, 692);

  // --- C. CARVED WALNUT SAW HANDLE (TOTE) AT UPPER-LEFT HEEL ---
  resetBrushState();
  const handleOuter = [
    [452, 438], [508, 424], [552, 462], [538, 492],
    [504, 548], [464, 558], [432, 526], [436, 476]
  ];
  brush.wash("#241710", 245);
  drawPoly(handleOuter, 0.35);
  brush.noWash();

  // Warm polished walnut shading on handle
  brush.mass("charcoal", "#3b2519", { precision: 0.65, strength: 0.65, gradient: 0.5, outline: false });
  drawPoly([
    [458, 444], [506, 430], [546, 464], [526, 498], [472, 545], [442, 518]
  ], 0.3);
  brush.noMass();

  // Interior grip cutout hole of the saw handle
  const gripHole = [
    [462, 468], [488, 460], [502, 482], [482, 524], [458, 520], [452, 492]
  ];
  brush.wash("#0b1018", 250);
  drawPoly(gripHole, 0.4);
  brush.noWash();

  // Rim-light along the upper horn & bevel of the carved wooden handle
  brush.set("fine_graphite", "#9e714b", 1.1);
  brush.spline([[452, 438], [508, 424], [552, 462], [538, 492]], 0.4);
  brush.set("razor_etch", "#e8c895", 0.85);
  brush.spline([[465, 434], [508, 424], [548, 458]], 0.4);

  // Three polished brass split-nut screws fastening the handle to the steel blade
  const screws = [
    { x: 522, y: 468, r: 4.5 },
    { x: 502, y: 494, r: 4.2 },
    { x: 492, y: 522, r: 4.2 }
  ];
  for (let sc of screws) {
    resetBrushState();
    brush.wash("#b88d44", 245);
    brush.circle(sc.x, sc.y, sc.r, 0.1);
    brush.noWash();

    // Screw slot & specular brass glint
    brush.set("razor_etch", "#2b1b08", 0.9);
    brush.line(sc.x - 2.8, sc.y - 1.5, sc.x + 2.8, sc.y + 1.5);
    brush.set("razor_etch", "#fff8de", 1.1);
    brush.arc(sc.x, sc.y, sc.r * 0.85, 200, 330);
  }
}

