function drawCurledShaving(cx, cy, scaleSz, rotDeg, brightness = 1.0) {
  push();
  translate(cx, cy);
  rotate(rotDeg);

  // Cast shadow under the curled ribbon
  resetBrushState();
  brush.wash("#090d14", 175);
  drawPoly([
    [-16 * scaleSz, 5 * scaleSz],
    [22 * scaleSz, 4 * scaleSz],
    [26 * scaleSz, 14 * scaleSz],
    [-12 * scaleSz, 15 * scaleSz]
  ], 0.35);
  brush.noWash();

  // Build a 2.5-turn helical wood-shaving ribbon from back loops to front loops
  const loops = 3;
  for (let l = 0; l < loops; l++) {
    let xOff = (l - 1) * 11 * scaleSz;
    let rx = (13 - l * 1.8) * scaleSz;
    let ry = (8.5 - l * 1.1) * scaleSz;
    let ribbonW = (5.8 - l * 0.6) * scaleSz;

    // Back (inner shadowed) half of the curl loop
    let backTop = [];
    let backBot = [];
    for (let a = 170; a <= 370; a += 25) {
      let px = xOff + cos(a) * rx;
      let py = sin(a) * ry;
      backTop.push([px, py]);
      backBot.push([px + ribbonW * 0.45, py + ribbonW * 0.85]);
    }
    let backPoly = backTop.concat(backBot.slice().reverse());
    let innerCol = lerpHex("#2c3845", "#a87e49", brightness * 0.85);
    resetBrushState();
    brush.wash(innerCol, 235);
    drawPoly(backPoly, 0.25);
    brush.noWash();

    // Front (outer illuminated) half of the curl loop
    let frontTop = [];
    let frontBot = [];
    for (let a = -15; a <= 185; a += 22) {
      let px = xOff + cos(a) * rx;
      let py = sin(a) * ry;
      frontTop.push([px, py]);
      frontBot.push([px + ribbonW * 0.5, py + ribbonW * 0.92]);
    }
    let frontPoly = frontTop.concat(frontBot.slice().reverse());
    let outerCol = lerpHex("#4f5d6b", "#f5dfB8", brightness);
    resetBrushState();
    brush.wash(outerCol, 245);
    drawPoly(frontPoly, 0.25);
    brush.noWash();

    // Wood grain fiber lines along the outer ribbon
    let fiberCol = lerpHex("#384452", "#c79a5e", brightness);
    brush.set("razor_etch", fiberCol, 0.65);
    brush.spline(frontTop, 0.45);
    brush.spline(frontBot, 0.45);

    // Razor-sharp translucent white-amber edge highlight on the curl rim
    if (brightness > 0.5) {
      let rimCol = brightness > 0.82 ? "#ffffff" : "#fae8c6";
      brush.set("razor_etch", rimCol, 0.95 * brightness);
      brush.spline(frontTop.slice(1, frontTop.length - 1), 0.5);
    }
  }

  // Trailing tail of the wood shaving
  let tail1 = [
    [14 * scaleSz, 2 * scaleSz],
    [26 * scaleSz, -4 * scaleSz],
    [35 * scaleSz, 3 * scaleSz]
  ];
  let tailCol = lerpHex("#52606e", "#f7e5c4", brightness);
  brush.set("fine_graphite", tailCol, 1.4 * scaleSz);
  brush.spline(tail1, 0.5);
  if (brightness > 0.65) {
    brush.set("razor_etch", "#ffffff", 0.85);
    brush.spline(tail1, 0.5);
  }

  pop();
}

function drawSawdustMound(cx, cy, rx, ry, brightness = 1.0) {
  resetBrushState();

  // Soft shadow base
  brush.wash("#0c1118", 160);
  drawPoly([
    [cx - rx * 1.05, cy + ry * 0.2],
    [cx + rx * 1.05, cy + ry * 0.2],
    [cx + rx * 0.8, cy + ry * 0.95],
    [cx - rx * 0.8, cy + ry * 0.95]
  ], 0.35);

  // Warm granular sawdust body
  let bodyCol = lerpHex("#253240", "#dfc08e", brightness);
  brush.wash(bodyCol, 225);
  drawPoly([
    [cx - rx, cy + ry * 0.25],
    [cx - rx * 0.35, cy - ry * 0.85],
    [cx + rx * 0.3, cy - ry * 0.75],
    [cx + rx, cy + ry * 0.3],
    [cx + rx * 0.5, cy + ry * 0.65],
    [cx - rx * 0.5, cy + ry * 0.65]
  ], 0.4);
  brush.noWash();

  // Hundreds of individual crisp sawdust grains & micro-flecks
  let grainCount = Math.round((rx * ry) * 0.32);
  for (let i = 0; i < grainCount; i++) {
    let a = random(360);
    let r = Math.sqrt(random()) * 1.08;
    let gx = cx + cos(a) * rx * r;
    let gy = cy + sin(a) * ry * r * 0.75;

    // Brightest on upper-left slope facing the light shaft
    let isUpper = gy < cy + ry * 0.15 && gx < cx + rx * 0.45;
    let col;
    if (brightness > 0.65) {
      col = isUpper
        ? (random() < 0.45 ? "#ffffff" : "#fae9c8")
        : (random() < 0.5 ? "#c99f65" : "#8c6234");
    } else {
      col = isUpper ? "#7d8c99" : "#24313f";
    }

    brush.set("razor_etch", col, random(0.6, 1.2));
    let gl = random(1.2, 3.2);
    let ga = random(180);
    brush.line(gx, gy, gx + cos(ga) * gl, gy + sin(ga) * gl);
  }
}

