// =============================================================================
// 8. CREPUSCULAR PENCIL OVER-PASS, VOLUMETRIC OCCLUSION & DRIFTING MOTES
// =============================================================================

function drawCrepuscularOverpassAndMotes() {
  resetBrushState();

  // A. Volumetric shadow streaks cast INSIDE the beam down-right of solid objects
  // (board end, saw blade, sawhorse ledger)
  const shadowCasters = [
    { x: 785, y: 682, w: 32, len: 390 }, // Shadow behind pine board end
    { x: 510, y: 505, w: 24, len: 210 }, // Shadow behind walnut saw handle
    { x: 645, y: 655, w: 28, len: 360 }  // Shadow under sawhorse ledger
  ];

  for (let sc of shadowCasters) {
    let dx = sc.x - SUN.x;
    let dy = sc.y - SUN.y;
    let dist = Math.hypot(dx, dy);
    let ux = dx / dist;
    let uy = dy / dist;
    let nx = -uy;
    let ny = ux;

    for (let i = 0; i < 28; i++) {
      let off = random(-sc.w * 0.5, sc.w * 0.5);
      let d1 = random(15, 65);
      let d2 = d1 + random(110, sc.len);
      let x1 = sc.x + ux * d1 + nx * off;
      let y1 = sc.y + uy * d1 + ny * off;
      let x2 = sc.x + ux * d2 + nx * off * 1.18;
      let y2 = sc.y + uy * d2 + ny * off * 1.18;

      brush.set("beam_pencil", "#0d141e", random(0.8, 1.4));
      brush.line(x1, y1, x2, y2);
    }
  }

  // B. Crisp white & pale amber pencil over-pass lifting the crepuscular beams across the room
  for (let r of RAYS) {
    let dxW = r.wx - SUN.x;
    let dyW = r.wy - SUN.y;
    let distW = Math.hypot(dxW, dyW);
    let ux = dxW / distW;
    let uy = dyW / distW;
    let nx = -uy;
    let ny = ux;

    let overCount = Math.round(map(r.halfW, 9, 48, 55, 290) * r.intensity);

    for (let s = 0; s < overCount; s++) {
      // Emphasize razor-sharp upper and lower boundary edges of each beam
      let t;
      let edgeRoll = random();
      if (edgeRoll < 0.22) {
        t = random(-1.0, -0.82);
      } else if (edgeRoll < 0.44) {
        t = random(0.82, 1.0);
      } else {
        t = random(-0.85, 0.85);
      }

      let d1 = random(0, 960);
      let segLen = random(90, 380);
      let d2 = Math.min(1320, d1 + segLen);

      let w1 = r.halfW * ((distW + d1) / distW) * t;
      let w2 = r.halfW * ((distW + d2) / distW) * t;

      let sx1 = r.wx + ux * d1 + nx * w1;
      let sy1 = r.wy + uy * d1 + ny * w1;
      let sx2 = r.wx + ux * d2 + nx * w2;
      let sy2 = r.wy + uy * d2 + ny * w2;

      // Keep the hero focal zone (pine end grain & saw teeth) slightly clearer of heavy overcast
      let midX = (sx1 + sx2) * 0.5;
      let midY = (sy1 + sy2) * 0.5;
      let inHeroCore = (midX > 610 && midX < 825 && midY > 590 && midY < 735);
      if (inHeroCore && random() < 0.62) continue;

      let isWarm = random() < r.warm;
      let col;
      if (Math.abs(t) > 0.84) {
        // Razor-crisp white-silver & pale gold beam edges
        col = isWarm ? "#f5e3ba" : "#f4f9fc";
      } else {
        col = isWarm
          ? (random() < 0.5 ? "#ebd29e" : "#d9b474")
          : (random() < 0.5 ? "#dce8f2" : "#ffffff");
      }

      let bName = Math.abs(t) > 0.88 && d1 < 450 ? "cpencil" : "beam_pencil";
      let wMult = Math.abs(t) > 0.88 ? random(0.45, 0.85) : random(0.6, 1.25);
      brush.set(bName, col, wMult);
      brush.line(sx1, sy1, sx2, sy2);
    }
  }

  // C. Drifting sawdust motes suspended in the crepuscular shafts
  // 1. Soft atmospheric dust haze along the beams using mote_stipple
  for (let r of RAYS) {
    let dxW = r.wx - SUN.x;
    let dyW = r.wy - SUN.y;
    let distW = Math.hypot(dxW, dyW);
    let ux = dxW / distW;
    let uy = dyW / distW;

    brush.set("mote_stipple", "#ebd7ab", 0.9 * r.intensity);
    brush.line(r.wx + ux * 40, r.wy + uy * 40, r.wx + ux * 980, r.wy + uy * 980);
  }

  // 2. Individual crisp floating dust motes & tiny airborne wood fibers
  const totalMotes = 620;
  for (let m = 0; m < totalMotes; m++) {
    // Pick a ray (weighted toward the Hero Beam id=4)
    let r = random() < 0.58 ? RAYS[4] : random(RAYS);
    let dxW = r.wx - SUN.x;
    let dyW = r.wy - SUN.y;
    let distW = Math.hypot(dxW, dyW);
    let ux = dxW / distW;
    let uy = dyW / distW;
    let nx = -uy;
    let ny = ux;

    // Dense concentration near the wall slits and swirling around the active sawing zone (d ≈ 420..760)
    let distAlong = random() < 0.45 ? random(420, 790) : random(20, 1120);
    let localHalfW = r.halfW * ((distW + distAlong) / distW);
    let perpOff = random(-localHalfW * 0.96, localHalfW * 0.96);

    let mx = r.wx + ux * distAlong + nx * perpOff;
    let my = r.wy + uy * distAlong + ny * perpOff;

    if (mx < 140 || mx > 1185 || my < 20 || my > 1185) continue;

    let isHeroZone = (mx > 520 && mx < 860 && my > 480 && my < 790);
    let moteCol = random() < 0.52
      ? "#ffffff"
      : (random() < 0.65 ? "#f7e4b9" : "#d8e7f2");

    let sizeRoll = random();
    if (sizeRoll < 0.68) {
      // Pinpoint luminous mote
      brush.set("razor_etch", moteCol, random(0.65, 1.35));
      let ang = random(360);
      let d = random(0.8, 2.2);
      brush.line(mx, my, mx + cos(ang) * d, my + sin(ang) * d);
    } else if (sizeRoll < 0.92) {
      // Tiny drifting wood fiber streak catching the light
      brush.set("razor_etch", moteCol, random(0.75, 1.25));
      let ang = random(-35, 65);
      let d = random(2.5, 5.2);
      brush.line(mx, my, mx + cos(ang) * d, my + sin(ang) * d);
    } else {
      // Larger out-of-focus glowing dust speck with soft halo
      brush.set("cpencil", "#ebd4a2", 0.9);
      brush.circle(mx, my, random(1.4, 2.6), 0.2);
      brush.set("razor_etch", "#ffffff", 1.15);
      brush.line(mx - 0.8, my, mx + 0.8, my);
    }

    // Extra eddy of rising dust motes right around the saw blade kerf
    if (isHeroZone && random() < 0.35) {
      let ex = random(585, 765);
      let ey = random(540, 735);
      brush.set("razor_etch", random() < 0.6 ? "#ffffff" : "#fae6be", random(0.7, 1.3));
      brush.line(ex, ey, ex + random(-2, 2.5), ey + random(-2, 2.5));
    }
  }
}

