function drawVelvetVignette() {
  resetBrushState();

  // Deep cool charcoal smudges along upper-right, lower-left, and bottom corners
  // to heighten the luminous intimacy of the late-afternoon crepuscular beams.
  const corners = [
    [[780, 0], [1200, 0], [1200, 420], [960, 220]],
    [[0, 860], [340, 960], [460, 1200], [0, 1200]],
    [[0, 0], [180, 0], [120, 65], [0, 110]]
  ];

  for (let c of corners) {
    brush.wash("#06090e", 135);
    drawPoly(c);
  }
  brush.noWash();

  // Expressive charcoal edge strokes framing the darkness
  brush.set("velvet_charcoal", "#070b11", 1.5);
  for (let i = 0; i < 42; i++) {
    let side = i % 3;
    let x1, y1, x2, y2;
    if (side === 0) {
      // Top-right murk
      x1 = random(650, 1180);
      y1 = random(10, 260);
      x2 = x1 + random(60, 160);
      y2 = y1 + random(20, 80);
    } else if (side === 1) {
      // Bottom-left murk
      x1 = random(10, 380);
      y1 = random(820, 1180);
      x2 = x1 + random(50, 140);
      y2 = y1 + random(-30, 50);
    } else {
      // Far right edge murk above the beams
      x1 = random(980, 1190);
      y1 = random(180, 640);
      x2 = x1 + random(-40, 30);
      y2 = y1 + random(70, 160);
    }
    brush.line(x1, y1, x2, y2);
  }
}

// Hyperreal Diagonal Procession of Ghost Crabs (Ocypode ceratophthalmus)
// Paracas Mantle Embroidery Rhythm & Directional Coloured-Pencil Stitch-Work

const PALETTE = {
