  },
  cochineal: ["#380b15", "#631424", "#962034", "#c43548", "#e3626d", "#f5a8a2"],
  ochre:     ["#3d280b", "#6e4b16", "#a67526", "#d49f42", "#ecc46e", "#faecc8"],
