    carapaceMain: PALETTE.ochre,
    carapaceShield: PALETTE.cochineal,
    carapaceBranchial: PALETTE.olive,
    striae: PALETTE.ochre,
    groove: PALETTE.indigo,
    merus: PALETTE.cochineal,
