    striae: PALETTE.ochre,
    groove: PALETTE.indigo,
    merus: PALETTE.indigo,
    carpus: PALETTE.ochre,
    propodus: PALETTE.olive,
    dactylus: PALETTE.cochineal,
    clawPalm: PALETTE.ochre,
    clawFinger: PALETTE.olive,
    eyeStalk: PALETTE.olive,
    eyeHorn: PALETTE.cochineal
  },
  { // 3: Twilight Indigo & Burnished Gold Ochre
    carapaceMain: PALETTE.indigo,
    carapaceShield: PALETTE.ochre,
    carapaceBranchial: PALETTE.cochineal,
    striae: PALETTE.ochre,
    groove: PALETTE.olive,
    merus: PALETTE.ochre,
    carpus: PALETTE.indigo,
    propodus: PALETTE.cochineal,
    dactylus: PALETTE.ochre,
    clawPalm: PALETTE.cochineal,
    clawFinger: PALETTE.indigo,
    eyeStalk: PALETTE.ochre,
    eyeHorn: PALETTE.cochineal
  }
];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(42719);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.ground.abyss);
  brush.noField();

  // Procession basis vectors: marching from bottom-left to top-right (-43 deg)
  const marchAngle = -43;
  const radU = (marchAngle * Math.PI) / 180;
  const U = { x: Math.cos(radU), y: Math.sin(radU) }; // (0.731, -0.682)
  const V = { x: -Math.sin(radU), y: Math.cos(radU) }; // (0.682, 0.731)

  // Build lattice of ghost crabs in diagonal procession
  const crabs = buildProcessionLattice(U, V, marchAngle);

  // 1. Render dark wet twilight sand ground & textile-like wave interference ripples
  drawWetSandGround(U, V);

  // 2. Render faint crab tracks, dactylus puncture pits & claw drag marks between crabs
  for (let i = 0; i < crabs.length; i++) {
    drawCrabTracks(crabs[i], U, V);
  }

  // 3. Render wet sand cast shadows and twilight specular reflections beneath crabs
  for (let i = 0; i < crabs.length; i++) {
    drawCrabShadowAndReflection(crabs[i]);
  }

  // 4. Render each ghost crab in hyperreal directional coloured-pencil stitch-work
  for (let i = 0; i < crabs.length; i++) {
    drawGhostCrab(crabs[i]);
  }

  noLoop();
}

// ============================================================================
// SAFE P5.BRUSH WRAPPERS
// ============================================================================

function strokeLine(bName, col, weight, x1, y1, x2, y2) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(bName, col, weight, pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

function washPoly(pts, col, alpha = 210, curv = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// ============================================================================
// PROCESSION LATTICE & COORDINATE TRANSFORMS
// ============================================================================

function buildProcessionLattice(U, V, marchAngle) {
  const crabs = [];
  const laneSpacing = 322;
  const stepSpacing = 256;

  const lanes = [
    { vIdx: -2, uIndices: [-1, 0, 1] },
    { vIdx: -1, uIndices: [-1.5, -0.5, 0.5, 1.5] },
    { vIdx:  0, uIndices: [-3, -2, -1, 0, 1, 2, 3] },
    { vIdx:  1, uIndices: [-1.5, -0.5, 0.5, 1.5] },
    { vIdx:  2, uIndices: [-1, 0, 1] }
  ];

  let idx = 0;
  for (let l = 0; l < lanes.length; l++) {
    const lane = lanes[l];
    const vDist = lane.vIdx * laneSpacing;
    for (let k = 0; k < lane.uIndices.length; k++) {
      const uStep = lane.uIndices[k];
      const uDist = uStep * stepSpacing;

      // Subtle organic breathing in position, posture, scale, and color scheme
      const jitterU = random(-12, 12);
      const jitterV = random(-14, 14);
      const cx = 600 + (uDist + jitterU) * U.x + (vDist + jitterV) * V.x;
      const cy = 600 + (uDist + jitterU) * U.y + (vDist + jitterV) * V.y;

      // Keep crabs whose bodies or legs enter the 1200x1200 canvas
      if (cx < -110 || cx > 1310 || cy < -110 || cy > 1310) continue;

      const baseScale = lane.vIdx === 0 ? random(0.87, 0.94) : random(0.81, 0.89);
      const yawWobble = random(-6.5, 6.5);
      // Local (0, -1) points along heading when rotDeg = heading + 90
      const rotDeg = marchAngle + 90 + yawWobble;

      // Paracas mantle rhythmic color alternation across diagonal registers
      const schemeIdx = Math.abs(Math.round(uStep * 2 + lane.vIdx * 3 + 100)) % SCHEMES.length;

      crabs.push({
        id: idx++,
        cx,
        cy,
        scale: baseScale,
        rotDeg,
        rotRad: (rotDeg * Math.PI) / 180,
        scheme: SCHEMES[schemeIdx],
        schemeIdx,
        majorSide: (idx % 2 === 0) ? 1 : -1,
        gaitPhase: random(0, 360),
        eyeSpread: random(0.94, 1.08),
        clawOpen: random(0.0, 0.35)
      });
    }
  }
  return crabs;
}

function toWorld(crab, lx, ly) {
  const sx = lx * crab.scale;
  const sy = ly * crab.scale;
  const c = Math.cos(crab.rotRad);
  const s = Math.sin(crab.rotRad);
  return [
    crab.cx + sx * c - sy * s,
    crab.cy + sx * s + sy * c
  ];
}

function toWorldArray(crab, localPts) {
  const out = new Array(localPts.length);
  for (let i = 0; i < localPts.length; i++) {
    out[i] = toWorld(crab, localPts[i][0], localPts[i][1]);
  }
  return out;
}

// ============================================================================
// 1. DARK WET TWILIGHT SAND & PARACAS-INSPIRED RIPPLE WEAVE
// ============================================================================

function drawWetSandGround(U, V) {
  // Deep atmospheric twilight bands across the wet sand
  const bandCount = 26;
  for (let i = 0; i < bandCount; i++) {
    const t = i / (bandCount - 1);
    const vPos = (t - 0.5) * 1800;
    const bx = 600 + vPos * V.x;
    const by = 600 + vPos * V.y;
    const w = 1900;
    const h = 110;
    const p1 = [bx - w * U.x - h * V.x, by - w * U.y - h * V.y];
    const p2 = [bx + w * U.x - h * V.x, by + w * U.y - h * V.y];
    const p3 = [bx + w * U.x + h * V.x, by + w * U.y + h * V.y];
    const p4 = [bx - w * U.x + h * V.x, by - w * U.y + h * V.y];

    const col = (i % 3 === 0)
      ? PALETTE.ground.wetIndigo
      : (i % 3 === 1 ? PALETTE.ground.wetOlive : PALETTE.ground.wetPlum);
    washPoly([p1, p2, p3, p4], col, 95, 0.05);
  }

  // Wet sand directional stitch texture & tidal ripple lines
  const rippleRows = 75;
  for (let r = 0; r < rippleRows; r++) {
    const yBase = (r / (rippleRows - 1)) * 1260 - 30;
    const segments = 22;
    for (let s = 0; s < segments; s++) {
      const x1 = (s / segments) * 1260 - 30 + random(-8, 8);
      const nVal = noise(x1 * 0.004, yBase * 0.004);
      // Slight diagonal tidal swash angle (-16 to -38 deg)
      const angle = (-24 + (nVal - 0.5) * 28) * Math.PI / 180;
      const len = random(28, 56);
      const x2 = x1 + Math.cos(angle) * len;
      const y2 = yBase + Math.sin(angle) * len + (nVal - 0.5) * 18;

      let col = PALETTE.ground.rippleIndigo;
      if (nVal > 0.62) col = PALETTE.ground.rippleOlive;
      else if (nVal < 0.36) col = PALETTE.ground.rippleCochineal;
      else if (r % 7 === 0) col = PALETTE.ground.rippleOchre;

      strokeLine("cpencil", col, random(0.32, 0.55), x1, yBase, x2, y2);

      // Occasional wet twilight sky glint on damp sand grain crests
      if (random() < 0.09) {
        const glintCol = random() < 0.65 ? PALETTE.indigo[2] : PALETTE.ochre[1];
        strokeLine("2H", glintCol, 0.25, x1 + 4, yBase - 1, x1 + 16, yBase - 5);
      }
    }
  }

  // Subtle diagonal Paracas register lines whispered into the wet sand
  const laneOffsets = [-483, -161, 161, 483];
  for (let i = 0; i < laneOffsets.length; i++) {
    const vOff = laneOffsets[i];
    for (let u = -850; u <= 850; u += 26) {
      const px = 600 + u * U.x + vOff * V.x;
      const py = 600 + u * U.y + vOff * V.y;
      if (px < -20 || px > 1220 || py < -20 || py > 1220) continue;
      const stitchCol = (Math.abs(Math.floor(u / 26)) % 2 === 0)
        ? PALETTE.indigo[1]
        : PALETTE.olive[1];
      strokeLine(
        "cpencil",
        stitchCol,
        0.3,
        px - U.x * 9 + V.x * 2,
        py - U.y * 9 + V.y * 2,
        px + U.x * 9 - V.x * 2,
        py + U.y * 9 - V.y * 2
      );
    }
  }
}

// ============================================================================
// 2. FAINT GHOST CRAB TRACKS & DACTYLUS PUNCTURES IN WET SAND
// ============================================================================

function drawCrabTracks(crab, U, V) {
  // Tracks trail behind the crab (-U direction) across the gap to the following crab
  const trackLength = 215 * crab.scale;
  const steps = 11;
  const trackLateralOffsets = [-138, -108, -78, 78, 108, 138];

  for (let s = 1; s <= steps; s++) {
    const distBack = (s / steps) * trackLength + 45 * crab.scale;
    const fade = 1 - (s / (steps + 2)) * 0.55;

    for (let t = 0; t < trackLateralOffsets.length; t++) {
      const lat = trackLateralOffsets[t] * crab.scale;
      const stepJitterX = (noise(crab.id * 10 + s, t * 3) - 0.5) * 14;
      const stepJitterY = (noise(crab.id * 10 + t, s * 3) - 0.5) * 14;

      const tx = crab.cx - U.x * distBack + V.x * lat + stepJitterX;
      const ty = crab.cy - U.y * distBack + V.y * lat + stepJitterY;

      if (tx < -20 || tx > 1220 || ty < -20 || ty > 1220) continue;

      // Dark water-filled puncture dimple from sharp dactylus tip
      strokeLine("cpencil", PALETTE.ground.shadow, 0.55 * fade, tx - 4, ty - 2, tx + 4, ty + 2);
      strokeLine("cpencil", PALETTE.ground.shadow, 0.45 * fade, tx - 2, ty + 3, tx + 3, ty - 3);

      // Raised wet sand rim catching dim twilight ochre/indigo/olive reflection
      const rimCol = (t % 3 === 0)
        ? PALETTE.indigo[2]
        : (t % 3 === 1 ? PALETTE.ochre[1] : PALETTE.olive[2]);
      strokeLine("2H", rimCol, 0.28 * fade, tx - 5, ty + 3, tx + 2, ty + 5);

      // Occasional tiny water meniscus glint inside footprint pit
      if ((s + t) % 4 === 0) {
        strokeLine("2H", PALETTE.indigo[4], 0.22 * fade, tx - 1, ty - 1, tx + 2, ty - 2);
      }
    }

    // Faint central/asymmetrical claw drag streak in the wet sand
    const dragSide = crab.majorSide * 22 * crab.scale;
    const dx1 = crab.cx - U.x * distBack + V.x * dragSide;
    const dy1 = crab.cy - U.y * distBack + V.y * dragSide;
    const dx2 = dx1 - U.x * 16 + V.x * random(-3, 3);
    const dy2 = dy1 - U.y * 16 + V.y * random(-3, 3);
    if (dx1 > 0 && dx1 < 1200 && dy1 > 0 && dy1 < 1200) {
      strokeLine("cpencil", PALETTE.indigo[1], 0.28 * fade, dx1, dy1, dx2, dy2);
    }
  }
}

// ============================================================================
// 3. WET SAND SHADOWS & TWILIGHT SPECULAR REFLECTIONS
// ============================================================================

function drawCrabShadowAndReflection(crab) {
  // Soft abyssal cast shadow offset slightly toward lower-right (+lx, +ly)
  const shadowPoly = toWorldArray(crab, [
    [-58, -42], [62, -40], [72, 46], [-52, 48]
  ]);
  washPoly(shadowPoly, PALETTE.ground.shadow, 185, 0.25);

  // Extended leg-corridor shadow washes
  const leftLegShadow = toWorldArray(crab, [
    [-46, -34], [-162, -62], [-172, 28], [-118, 84], [-40, 36]
  ]);
  const rightLegShadow = toWorldArray(crab, [
    [46, -34], [168, -56], [176, 34], [124, 90], [40, 36]
  ]);
  washPoly(leftLegShadow, PALETTE.ground.shadow, 115, 0.2);
  washPoly(rightLegShadow, PALETTE.ground.shadow, 135, 0.2);

  // Wet sand mirror reflection streaks under claws, eyes, and bright leg joints
  const reflColorA = crab.scheme.carapaceMain[1];
  const reflColorB = crab.scheme.clawPalm[1];
  for (let i = -5; i <= 5; i++) {
    const lx = i * 24;
    const ly = Math.abs(i) * 6 + 44;
    const p1 = toWorld(crab, lx - 6, ly);
    const p2 = toWorld(crab, lx + 8, ly + 18);
    strokeLine("cpencil", i % 2 === 0 ? reflColorA : reflColorB, 0.35, p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// 4. HYPERREAL GHOST CRAB ANATOMY & DIRECTIONAL STITCH ENGINE
// ============================================================================

function drawGhostCrab(crab) {
  // Draw in anatomical back-to-front order:
  // 4A. Walking legs (Pairs 4, 3, 2, 1 on Left and Right)
  const legOrder = [3, 2, 1, 0];
  for (let i = 0; i < legOrder.length; i++) {
    const legIdx = legOrder[i];
    drawWalkingLeg(crab, -1, legIdx);
    drawWalkingLeg(crab, +1, legIdx);
  }

  // 4B. Asymmetric Chelipeds (Minor Claw and Major Claw tucked in front)
  drawCheliped(crab, -crab.majorSide, false);
  drawCheliped(crab, crab.majorSide, true);

  // 4C. Sculpted Carapace (Regions, Grooves, Branchial Striae, Pleon Collar)
  drawCarapace(crab);

  // 4D. Stalked Horned Eyes (Orbital Troughs, Peduncles, Glossy Corneas, Distal Horns)
  drawStalkedEyes(crab);
}

// ----------------------------------------------------------------------------
// 4A. JOINTED WALKING LEGS (Coxa, Bowed Merus, Carpus, Bristled Propodus, Dactylus)
// ----------------------------------------------------------------------------

function getLegJoints(crab, side, legIdx) {
  // Subtle gait phase shift per leg so the pattern breathes naturally
  const phase = crab.gaitPhase + legIdx * 85 + (side > 0 ? 40 : 0);
  const dx = Math.cos((phase * Math.PI) / 180) * 4.5;
  const dy = Math.sin((phase * Math.PI) / 180) * 5.5;

  const baseSpecs = [
    // Leg 0 (Anterior walking leg - reaches forward & outward)
    {
      p0: [43, -24],
      p1: [54, -28],
      p2: [104 + dx, -54 + dy],
      p3: [122 + dx, -47 + dy],
      p4: [145 + dx, -59 + dy],
      p5: [160 + dx, -72 + dy],
      wMerus: 13.5,
      wProp: 8.5,
      hasTuft: false
    },
    // Leg 1 (Second walking leg - longest and strongest)
    {
      p0: [47, -7],
      p1: [59, -9],
      p2: [118 + dx, -19 + dy],
      p3: [137 + dx, -8 + dy],
      p4: [162 + dx, -15 + dy],
      p5: [177 + dx, -24 + dy],
      wMerus: 15.0,
      wProp: 9.2,
      hasTuft: true
    },
    // Leg 2 (Third walking leg - long, carries sensory setae tuft)
    {
      p0: [46, 11],
      p1: [58, 13],
      p2: [114 + dx, 18 + dy],
      p3: [131 + dx, 31 + dy],
      p4: [154 + dx, 35 + dy],
      p5: [168 + dx, 31 + dy],
      wMerus: 14.2,
      wProp: 8.8,
      hasTuft: true
    },
    // Leg 3 (Fourth/Posterior walking leg - slender, swept back)
    {
      p0: [38, 28],
      p1: [48, 34],
      p2: [86 + dx, 53 + dy],
      p3: [99 + dx, 67 + dy],
      p4: [115 + dx, 79 + dy],
      p5: [124 + dx, 90 + dy],
      wMerus: 11.2,
      wProp: 7.0,
      hasTuft: false
    }
  ];

  const spec = baseSpecs[legIdx];
  return {
    p0: [side * spec.p0[0], spec.p0[1]],
    p1: [side * spec.p1[0], spec.p1[1]],
    p2: [side * spec.p2[0], spec.p2[1]],
    p3: [side * spec.p3[0], spec.p3[1]],
    p4: [side * spec.p4[0], spec.p4[1]],
    p5: [side * spec.p5[0], spec.p5[1]],
    wMerus: spec.wMerus,
    wProp: spec.wProp,
    hasTuft: spec.hasTuft
  };
}

function drawWalkingLeg(crab, side, legIdx) {
  const j = getLegJoints(crab, side, legIdx);
  const sc = crab.scheme;

  // Alternate segment palettes subtly between legs for rich Paracas textile rhythm
  const merusPal = (legIdx % 2 === 0) ? sc.merus : sc.carpus;
  const carpusPal = (legIdx % 2 === 0) ? sc.carpus : sc.propodus;
  const propPal = (legIdx % 2 === 0) ? sc.propodus : sc.merus;
  const dactPal = sc.dactylus;

  // 1. Coxa / Basis-Ischium basal ring
  drawStitchedSegment(crab, j.p0, j.p1, 10, 10, sc.groove, {
    bow: 0,
    stepsL: 2,
    stepsW: 4,
    crossStitches: false,
    glint: false
  });
  drawJointCollar(crab, j.p1, j.p0, 5.5, sc.striae[3], sc.groove[0]);

  // 2. Merus (long bowed thigh segment with dorsal carina ridge and cross-stitches)
  drawStitchedSegment(crab, j.p1, j.p2, 9.5, j.wMerus, merusPal, {
    wEnd: 9.5,
    bow: -5.5, // arched anteriorly (-Y)
    stepsL: 7,
    stepsW: 5,
    crossStitches: true,
    striaePal: sc.striae,
    glint: true
  });

  // Sensory hair tuft between basal segments on legs 2 & 3 (hallmark of Ocypode)
  if (j.hasTuft) {
    drawLegSetae(crab, j.p1, j.p2, 7, 1, sc.striae[2], sc.carapaceMain[3]);
  }
  drawJointCollar(crab, j.p2, j.p1, 5.2, sc.carapaceShield[4], sc.groove[0]);

  // 3. Carpus (curved knee segment)
  drawStitchedSegment(crab, j.p2, j.p3, 8.8, 8.2, carpusPal, {
    wEnd: 7.4,
    bow: -2.0,
    stepsL: 3,
    stepsW: 4,
    crossStitches: true,
    striaePal: sc.striae,
    glint: true
  });
  drawJointCollar(crab, j.p3, j.p2, 4.4, sc.striae[4], sc.groove[0]);

  // 4. Propodus (slender lower leg with trailing edge sensory bristles)
  drawStitchedSegment(crab, j.p3, j.p4, j.wProp, j.wProp * 0.82, propPal, {
    wEnd: 5.0,
    bow: -1.5,
    stepsL: 5,
    stepsW: 4,
    crossStitches: false,
    glint: true
  });
  drawLegSetae(crab, j.p3, j.p4, 8, 1, sc.ochre[3], sc.cochineal[3]);
  drawJointCollar(crab, j.p4, j.p3, 3.2, sc.ochre[4], sc.groove[0]);

  // 5. Dactylus (sharp curved tip piercing the dark wet sand)
  drawStitchedSegment(crab, j.p4, j.p5, 4.8, 3.2, dactPal, {
    wEnd: 0.8,
    bow: -2.2,
    stepsL: 4,
    stepsW: 3,
    crossStitches: false,
    glint: true
  });

  // Wet sand puncture dimple & specular water meniscus at dactylus tip P5
  const tipW = toWorld(crab, j.p5[0], j.p5[1]);
  strokeLine("cpencil", PALETTE.ground.shadow, 0.65, tipW[0] - 4, tipW[1] - 1, tipW[0] + 4, tipW[1] + 2);
  strokeLine("2H", PALETTE.indigo[4], 0.3, tipW[0] - 4, tipW[1] + 2, tipW[0] + 3, tipW[1] + 4);
  strokeLine("2H", PALETTE.glint[0], 0.25, tipW[0] - 2, tipW[1] + 1, tipW[0] + 1, tipW[1] + 2);
}

// Core Stitch-Segment Engine: renders a 3D curved limb segment with packed stitches
function drawStitchedSegment(crab, pA, pB, wStart, wMid, pal, opts) {
  const wEnd = opts.wEnd !== undefined ? opts.wEnd : wMid;
  const bow = opts.bow || 0;
  const stepsL = opts.stepsL || 5;
  const stepsW = opts.stepsW || 4;

  const dx = pB[0] - pA[0];
  const dy = pB[1] - pA[1];
  const len = Math.hypot(dx, dy) || 1;
  // Normal vector pointing roughly toward -Y (anterior/dorsal lit edge)
  let nx = -dy / len;
  let ny = dx / len;
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  }

  // Helper to sample point on segment at (s in [0,1], t in [-0.5, 0.5])
  function sampleSeg(s, t) {
    const bx = pA[0] + dx * s + nx * bow * Math.sin(s * Math.PI);
    const by = pA[1] + dy * s + ny * bow * Math.sin(s * Math.PI);
    const w = s < 0.5
      ? wStart + (wMid - wStart) * (s * 2)
      : wMid + (wEnd - wMid) * ((s - 0.5) * 2);
    return toWorld(crab, bx + nx * w * t, by + ny * w * t);
  }

  // 1. Solid dark under-wash so the limb has dense opaque body against dark ground
  const polyPts = [
    sampleSeg(0, -0.5),
    sampleSeg(0.5, -0.52),
    sampleSeg(1, -0.5),
    sampleSeg(1, 0.5),
    sampleSeg(0.5, 0.52),
    sampleSeg(0, 0.5)
  ];
  washPoly(polyPts, pal[0], 225, 0.15);

  // 2. Packed longitudinal stitch rows following the segment's bowed contour
  for (let iw = 0; iw < stepsW; iw++) {
    const t = -0.44 + (iw / Math.max(1, stepsW - 1)) * 0.88;
    // Cylindrical 3D shading across width: t near -0.22 faces the upper-left twilight sky
    let colIdx = 2;
    if (t < -0.32) colIdx = 3;
    else if (t < -0.05) colIdx = 4; // lit dorsal ridge
    else if (t < 0.25) colIdx = 2;
    else colIdx = 1; // ventral shadow edge

    const col = pal[colIdx];
    const weight = (colIdx === 4) ? 0.46 : 0.42;

    for (let il = 0; il < stepsL; il++) {
      const s0 = Math.max(0, (il - 0.08) / stepsL);
      const s1 = Math.min(1, (il + 1.08) / stepsL);
      const pt0 = sampleSeg(s0, t);
      const pt1 = sampleSeg(s1, t);
      strokeLine("cpencil", col, weight, pt0[0], pt0[1], pt1[0], pt1[1]);
    }
  }

  // 3. Cross-contour diagonal embroidery stitches (granulated striae on merus & carpus)
  if (opts.crossStitches && opts.striaePal) {
    const striaeCol = opts.striaePal[3];
    const shadowCol = pal[0];
    for (let il = 1; il < stepsL; il++) {
      const s = il / stepsL;
      const c0 = sampleSeg(s - 0.04, -0.42);
      const c1 = sampleSeg(s + 0.05, 0.12);
      const c2 = sampleSeg(s - 0.02, 0.44);
      strokeLine("cpencil", striaeCol, 0.36, c0[0], c0[1], c1[0], c1[1]);
      strokeLine("cpencil", shadowCol, 0.34, c1[0], c1[1], c2[0], c2[1]);
    }
  }

  // 4. Burnished wet shell glint along the dorsal carina ridge
  if (opts.glint) {
    const g0 = sampleSeg(0.28, -0.22);
    const g1 = sampleSeg(0.62, -0.22);
    strokeLine("2H", pal[5], 0.32, g0[0], g0[1], g1[0], g1[1]);
  }
}

function drawJointCollar(crab, pJoint, pPrev, radius, brightCol, darkCol) {
  const dx = pJoint[0] - pPrev[0];
  const dy = pJoint[1] - pPrev[1];
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;

  const jL = toWorld(crab, pJoint[0] + nx * radius, pJoint[1] + ny * radius);
  const jM = toWorld(crab, pJoint[0] + (dx / len) * 2.2, pJoint[1] + (dy / len) * 2.2);
  const jR = toWorld(crab, pJoint[0] - nx * radius, pJoint[1] - ny * radius);

  // Dark chitinous condyle socket + bright synovial membrane stitch arc
  strokeSpline("cpencil", darkCol, 0.55, [jL, jR], 0.3);
  strokeSpline("cpencil", brightCol, 0.44, [jL, jM, jR], 0.5);
}

function drawLegSetae(crab, pA, pB, count, dirSign, colA, colB) {
  const dx = pB[0] - pA[0];
  const dy = pB[1] - pA[1];
  const len = Math.hypot(dx, dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;
  if (ny < 0) {
    nx = -nx;
    ny = -ny;
  }

  for (let i = 1; i <= count; i++) {
    const s = i / (count + 1);
    const bx = pA[0] + dx * s + nx * 3.5 * dirSign;
    const by = pA[1] + dy * s + ny * 3.5 * dirSign;
    const tx = bx + nx * 8.5 * dirSign + (dx / len) * 3.5;
    const ty = by + ny * 8.5 * dirSign + (dy / len) * 3.5;
    const w0 = toWorld(crab, bx, by);
    const w1 = toWorld(crab, tx, ty);
    strokeLine("2H", i % 2 === 0 ? colA : colB, 0.24, w0[0], w0[1], w1[0], w1[1]);
  }
}

// ----------------------------------------------------------------------------
// 4B. ASYMMETRIC CHELIPEDS (Major & Minor Claws with Stridulating Ridge & Teeth)
// ----------------------------------------------------------------------------

function drawCheliped(crab, side, isMajor) {
  const sc = crab.scheme;
  const palmPal = sc.clawPalm;
  const fingerPal = sc.clawFinger;

  // Shoulder -> Elbow (Merus & Carpus tucked beside anterior carapace corner)
  const pShoulder = [side * 25, -33];
  const pElbow = [side * (isMajor ? 47 : 43), isMajor ? -56 : -52];

  drawStitchedSegment(crab, pShoulder, pElbow, 9.5, isMajor ? 12.5 : 10.0, sc.merus, {
    wEnd: isMajor ? 11.5 : 9.0,
    bow: -3.5,
    stepsL: 4,
    stepsW: 4,
    crossStitches: true,
    striaePal: sc.striae,
    glint: true
  });
  drawJointCollar(crab, pElbow, pShoulder, isMajor ? 6.0 : 4.8, palmPal[4], sc.groove[0]);

  // Sculpted Manus (Palm) & Pincers (Movable Upper Dactylus + Fixed Lower Pollex)
  const wristX = pElbow[0] - side * 2;
  const wristY = pElbow[1] - 2;
  const tipX = side * (isMajor ? 3 : 8);
  const tipY = isMajor ? -70 : -62;
  const palmDepth = isMajor ? 18.5 : 12.5;

  // Construct palm + fixed finger under-wash polygon
  const clawOutline = toWorldArray(crab, [
    [wristX, wristY - palmDepth * 0.45],
    [(wristX + tipX) * 0.55, wristY - palmDepth * 0.72],
    [tipX, tipY - 3.5],
    [tipX + side * 4, tipY + 2.5],
    [(wristX + tipX) * 0.5, wristY + palmDepth * 0.42],
    [wristX, wristY + palmDepth * 0.35]
  ]);
  washPoly(clawOutline, palmPal[0], 235, 0.25);

  // Contoured stitch rows wrapping the swollen convexity of the claw palm & fingers
  const rows = isMajor ? 6 : 5;
  const cols = isMajor ? 6 : 5;
  for (let r = 0; r < rows; r++) {
    const tr = r / (rows - 1); // 0 = upper dactylus crest, 1 = lower pollex keel
    const pal = (tr < 0.38 || tr > 0.72) ? fingerPal : palmPal;
    let cIdx = 2;
    if (tr < 0.22) cIdx = 4;
    else if (tr < 0.52) cIdx = 3;
    else if (tr < 0.78) cIdx = 2;
    else cIdx = 1;

    for (let c = 0; c < cols; c++) {
      const s0 = c / cols;
      const s1 = (c + 0.92) / cols;
      const pt0 = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, s0, tr, crab.clawOpen);
      const pt1 = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, s1, tr, crab.clawOpen);
      strokeLine("cpencil", pal[cIdx], 0.44, pt0[0], pt0[1], pt1[0], pt1[1]);
    }
  }

  // Serrated crushing tubercles (white-gold teeth) along pincer cutting gap
  const teethCount = isMajor ? 6 : 4;
  for (let k = 1; k <= teethCount; k++) {
    const s = 0.45 + (k / (teethCount + 1)) * 0.48;
    const tUpper = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, s, 0.44, crab.clawOpen);
    const tLower = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, s, 0.56, crab.clawOpen);
    strokeLine("2H", PALETTE.glint[0], 0.32, tUpper[0], tUpper[1], tLower[0], tLower[1]);
  }

  // Signature Ocypode stridulating ridge (vertical bead-row of golden tubercles on major palm)
  if (isMajor) {
    for (let b = 0; b < 6; b++) {
      const tb = 0.18 + (b / 5) * 0.62;
      const b0 = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, 0.34, tb, 0);
      const b1 = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, 0.41, tb, 0);
      strokeLine("cpencil", PALETTE.ochre[4], 0.42, b0[0], b0[1], b1[0], b1[1]);
    }
  }

  // Burnished wet specular glint on upper crest of the palm & movable dactylus
  const gA = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, 0.22, 0.16, crab.clawOpen);
  const gB = sampleClawSurface(crab, wristX, wristY, tipX, tipY, palmDepth, 0.62, 0.18, crab.clawOpen);
  strokeLine("2H", PALETTE.glint[0], 0.36, gA[0], gA[1], gB[0], gB[1]);
}

function sampleClawSurface(crab, wx, wy, tx, ty, depth, s, tr, clawOpen) {
  const x = wx + (tx - wx) * s;
  const arch = Math.sin(s * Math.PI) * depth;
  const taper = 1 - Math.pow(s, 1.4) * 0.78;
  // Slight pincer opening near tip (s > 0.5)
  let gapShift = 0;
  if (s > 0.45) {
    gapShift = (tr < 0.5 ? -1 : 1) * (s - 0.45) * 8 * clawOpen;
  }
  const yCenter = wy + (ty - wy) * s - Math.sin(s * Math.PI) * 4.5;
  const y = yCenter + (tr - 0.45) * (depth * taper + arch * 0.45) + gapShift;
  return toWorld(crab, x, y);
}

// ----------------------------------------------------------------------------
// 4C. SCULPTED CARAPACE (Sub-Quadrate Box Shell with Anatomical Regions)
// ----------------------------------------------------------------------------

function drawCarapace(crab) {
  const sc = crab.scheme;

  // 1. Sub-quadrate carapace base outline (wider anteriorly with sharp orbital spines)
  const carapaceContour = [
    [-46, -38], // Left external orbital spine
    [-14, -39], // Left supraorbital eave
    [0, -43],   // Deflexed median rostrum
    [14, -39],  // Right supraorbital eave
    [46, -38],  // Right external orbital spine
    [49, -12],  // Right epibranchial bulge
    [45, 16],   // Right mesobranchial margin
    [38, 37],   // Right metabranchial corner
    [0, 39],    // Posterior carapace margin
    [-38, 37],  // Left metabranchial corner
    [-45, 16],  // Left mesobranchial margin
    [-49, -12]  // Left epibranchial bulge
  ];
  washPoly(toWorldArray(crab, carapaceContour), sc.groove[0], 245, 0.12);

  // 2. Deep Cervical & H-Groove Furrows (shaded with dense indigo & olive stitch bands)
  drawCarapaceGrooves(crab, sc);

  // 3. Protogastric & Mesogastric Anterior Shield (sculpted concentric dome stitches)
  drawStitchedCushion(crab, {
    cx: 0, cy: -20, rx: 22, ry: 15,
    pal: sc.carapaceMain,
    rings: 5,
    segsPerRing: 10,
    lightBiasX: -0.25,
    lightBiasY: -0.25
  });

  // 4. Cardiac & Intestinal Posterior Shield (contrasting Paracas diamond/heart cushion)
  drawStitchedCushion(crab, {
    cx: 0, cy: 15, rx: 19, ry: 17,
    pal: sc.carapaceShield,
    rings: 5,
    segsPerRing: 9,
    lightBiasX: -0.2,
    lightBiasY: -0.2
  });

  // 5. Left & Right Hepatic + Branchial Gill Chambers (with oblique granular striae)
  drawBranchialChamber(crab, -1, sc);
  drawBranchialChamber(crab, +1, sc);

  // 6. Supraorbital Eaves, Median Rostrum, and Beaded Lateral Carina Borders
  drawCarapaceMarginsAndPleon(crab, sc);
}

function drawCarapaceGrooves(crab, sc) {
  // H-shaped gastro-cardiac groove in center of carapace
  const hLeft = toWorldArray(crab, [[-17, -14], [-13, -3], [-16, 12]]);
  const hRight = toWorldArray(crab, [[17, -14], [13, -3], [16, 12]]);
  const hCross = toWorldArray(crab, [[-14, -3], [0, -1], [14, -3]]);

  strokeSpline("cpencil", sc.groove[0], 0.7, hLeft, 0.4);
  strokeSpline("cpencil", sc.groove[0], 0.7, hRight, 0.4);
  strokeSpline("cpencil", sc.groove[0], 0.7, hCross, 0.4);
  strokeSpline("cpencil", sc.groove[2], 0.42, hCross, 0.4);

  // Muscle apodeme attachment dimples on either side of the H-groove
  const pL = toWorld(crab, -9, -3);
  const pR = toWorld(crab, 9, -3);
  strokeLine("2H", sc.striae[3], 0.3, pL[0] - 2, pL[1], pL[0] + 2, pL[1]);
  strokeLine("2H", sc.striae[3], 0.3, pR[0] - 2, pR[1], pR[0] + 2, pR[1]);
}

function drawStitchedCushion(crab, cfg) {
  // Base cushion wash
  const baseRing = [];
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    baseRing.push(toWorld(crab, cfg.cx + Math.cos(a) * cfg.rx, cfg.cy + Math.sin(a) * cfg.ry));
  }
  washPoly(baseRing, cfg.pal[1], 215, 0.25);

  // Concentric contoured stitch rings converging toward lit dome apex
  const apexX = cfg.cx + cfg.rx * cfg.lightBiasX;
  const apexY = cfg.cy + cfg.ry * cfg.lightBiasY;

  for (let r = cfg.rings; r >= 1; r--) {
    const tr = r / cfg.rings; // 1 = outer sulcus edge, 0.2 = inner dome apex
    const segs = Math.max(5, Math.round(cfg.segsPerRing * (0.45 + 0.55 * tr)));

    for (let s = 0; s < segs; s++) {
      const a0 = (s / segs) * Math.PI * 2;
      const a1 = ((s + 0.86) / segs) * Math.PI * 2;

      const x0 = apexX + (cfg.cx + Math.cos(a0) * cfg.rx - apexX) * tr;
      const y0 = apexY + (cfg.cy + Math.sin(a0) * cfg.ry - apexY) * tr;
      const x1 = apexX + (cfg.cx + Math.cos(a1) * cfg.rx - apexX) * tr;
      const y1 = apexY + (cfg.cy + Math.sin(a1) * cfg.ry - apexY) * tr;

      // Determine surface normal illumination toward upper-left (-X, -Y)
      const midA = (a0 + a1) * 0.5;
      const lightDot = -Math.cos(midA) * 0.55 - Math.sin(midA) * 0.75;
      let cIdx = 2;
      if (tr > 0.85) cIdx = 1;
      else if (tr < 0.38 && lightDot > -0.1) cIdx = 4;
      else if (lightDot > 0.25) cIdx = 4;
      else if (lightDot > -0.2) cIdx = 3;
      else cIdx = 1;

      const w0 = toWorld(crab, x0, y0);
      const w1 = toWorld(crab, x1, y1);
      strokeLine("cpencil", cfg.pal[cIdx], 0.44, w0[0], w0[1], w1[0], w1[1]);
    }
  }

  // Small burnished wet shell highlight on the dome crest
  const g0 = toWorld(crab, apexX - 4, apexY - 2);
  const g1 = toWorld(crab, apexX + 3, apexY - 4);
  const g2 = toWorld(crab, apexX - 2, apexY + 1);
  const g3 = toWorld(crab, apexX + 4, apexY - 1);
  strokeLine("2H", cfg.pal[5], 0.36, g0[0], g0[1], g1[0], g1[1]);
  strokeLine("2H", PALETTE.glint[0], 0.3, g2[0], g2[1], g3[0], g3[1]);
}

function drawBranchialChamber(crab, side, sc) {
  const pal = sc.carapaceBranchial;

  // Swollen lateral gill chamber dome (x from side*18 to side*45, y from -32 to +33)
  drawStitchedCushion(crab, {
    cx: side * 32,
    cy: 1,
    rx: 14.5,
    ry: 31,
    pal: pal,
    rings: 5,
    segsPerRing: 11,
    lightBiasX: side < 0 ? -0.25 : -0.15,
    lightBiasY: -0.22
  });

  // Oblique granular branchial striae (characteristic ridges of Ocypode carapace)
  const striaeCount = 6;
  for (let i = 0; i < striaeCount; i++) {
    const ty = -24 + (i / (striaeCount - 1)) * 50;
    const xOuter = side * (45 - Math.abs(ty) * 0.12);
    const xInner = side * 21;
    const yInner = ty + 8;

    const pOut = toWorld(crab, xOuter, ty);
    const pMid = toWorld(crab, (xOuter + xInner) * 0.5, (ty + yInner) * 0.5 - 1.5);
    const pIn = toWorld(crab, xInner, yInner);

    strokeSpline("cpencil", sc.striae[3], 0.42, [pOut, pMid, pIn], 0.4);
    if (side < 0 || i < 3) {
      strokeLine("2H", sc.striae[4], 0.26, pOut[0], pOut[1], pMid[0], pMid[1]);
    }
  }
}

function drawCarapaceMarginsAndPleon(crab, sc) {
  // 1. Sinuous Supraorbital Eaves & Deflexed Median Rostrum
  const eavePtsL = [[-46, -38], [-32, -35], [-16, -38], [-6, -39], [0, -44]];
  const eavePtsR = [[0, -44], [6, -39], [16, -38], [32, -35], [46, -38]];
  strokeSpline("cpencil", sc.striae[3], 0.55, toWorldArray(crab, eavePtsL), 0.5);
  strokeSpline("cpencil", sc.striae[3], 0.55, toWorldArray(crab, eavePtsR), 0.5);
  strokeSpline("2H", PALETTE.glint[0], 0.3, toWorldArray(crab, eavePtsL.slice(1, 4)), 0.5);

  // 2. Beaded Anterolateral & Posterolateral Carina Ridges (with external orbital spine)
  const steps = 11;
  for (let side of [-1, 1]) {
    for (let i = 0; i < steps; i++) {
      const t0 = i / steps;
      const t1 = (i + 0.82) / steps;
      const y0 = -38 + t0 * 75;
      const y1 = -38 + t1 * 75;
      const x0 = side * (46 + Math.sin(t0 * Math.PI) * 3.5 - t0 * 8);
      const x1 = side * (46 + Math.sin(t1 * Math.PI) * 3.5 - t1 * 8);
      const w0 = toWorld(crab, x0, y0);
      const w1 = toWorld(crab, x1, y1);
      const beadCol = (i % 2 === 0) ? sc.striae[4] : sc.carapaceMain[3];
      strokeLine("cpencil", beadCol, 0.48, w0[0], w0[1], w1[0], w1[1]);
    }
  }

  // 3. Posterior Carapace Rim & First Abdominal Segment (Pleon Tergite)
  for (let i = -5; i <= 4; i++) {
    const x0 = i * 7.2;
    const x1 = (i + 0.85) * 7.2;
    const w0 = toWorld(crab, x0, 37.5);
    const w1 = toWorld(crab, x1, 37.5);
    strokeLine("cpencil", sc.striae[3], 0.48, w0[0], w0[1], w1[0], w1[1]);
  }

  // Segmented abdominal pleon collar tucked behind the rear carapace edge
  const pleonPoly = toWorldArray(crab, [
    [-21, 38], [21, 38], [17, 45.5], [-17, 45.5]
  ]);
  washPoly(pleonPoly, sc.groove[0], 230, 0.15);
  for (let i = -4; i <= 4; i++) {
    const px = i * 4.2;
    const pTop = toWorld(crab, px, 38.5);
    const pBot = toWorld(crab, px * 0.85, 45.0);
    const col = (Math.abs(i) % 2 === 0) ? sc.striae[3] : sc.carapaceShield[3];
    strokeLine("cpencil", col, 0.42, pTop[0], pTop[1], pBot[0], pBot[1]);
  }
}

// ----------------------------------------------------------------------------
// 4D. STALKED HORNED EYES (Ocypode ceratophthalmus Peduncles, Corneas & Horns)
// ----------------------------------------------------------------------------

function drawStalkedEyes(crab) {
  const sc = crab.scheme;
  const spread = crab.eyeSpread;

  for (let side of [-1, 1]) {
    // 1. Deep orbital trough socket beneath supraorbital eave
    const troughPts = toWorldArray(crab, [
      [side * 8, -39],
      [side * 34, -37],
      [side * 38, -43],
      [side * 10, -44]
    ]);
    washPoly(troughPts, PALETTE.ground.shadow, 220, 0.2);

    // 2. Cylindrical Peduncular Eyestalk rising forward and outward
    const pBase = [side * 9, -40];
    const pCorneaBase = [side * 27 * spread, -53];
    drawStitchedSegment(crab, pBase, pCorneaBase, 6.2, 7.2, sc.eyeStalk, {
      wEnd: 7.5,
      bow: -2.0,
      stepsL: 4,
      stepsW: 3,
      crossStitches: true,
      striaePal: sc.striae,
      glint: true
    });

    // 3. Swollen Bulbous Cornea (glossy obsidian-indigo compound eye)
    const cx = side * 29.5 * spread;
    const cy = -56.5;
    const corneaPoly = toWorldArray(crab, [
      [cx - side * 4.5, cy + 4.5],
      [cx - side * 5.2, cy - 2.5],
      [cx + side * 1.5, cy - 6.2],
      [cx + side * 5.5, cy - 1.5],
      [cx + side * 3.8, cy + 4.8]
    ]);
    washPoly(corneaPoly, PALETTE.ground.shadow, 250, 0.35);

    // Curved compound-eye facet hatching in deep twilight indigo
    for (let f = -2; f <= 2; f++) {
      const f0 = toWorld(crab, cx - 3.5, cy + f * 1.6);
      const f1 = toWorld(crab, cx + 3.5, cy + f * 1.6 - 1.2);
      const fCol = f < 0 ? PALETTE.indigo[3] : PALETTE.indigo[1];
      strokeLine("cpencil", fCol, 0.36, f0[0], f0[1], f1[0], f1[1]);
    }

    // Glassy wet twilight sky reflection on cornea dome
    const h0 = toWorld(crab, cx - 2.2, cy - 2.8);
    const h1 = toWorld(crab, cx + 1.2, cy - 4.0);
    const h2 = toWorld(crab, cx - 1.0, cy - 1.2);
    const h3 = toWorld(crab, cx + 1.8, cy - 2.0);
    strokeLine("2H", PALETTE.glint[1], 0.42, h0[0], h0[1], h1[0], h1[1]);
    strokeLine("2H", PALETTE.glint[2], 0.34, h2[0], h2[1], h3[0], h3[1]);

    // 4. Distal Horn / Terminal Style (signature pointed horn beyond cornea)
    const pHornBase = [cx + side * 1.2, cy - 4.5];
    const pHornTip = [cx + side * 5.8, cy - 14.5];
    drawStitchedSegment(crab, pHornBase, pHornTip, 4.2, 2.8, sc.eyeHorn, {
      wEnd: 0.7,
      bow: -1.0,
      stepsL: 3,
      stepsW: 2,
      crossStitches: false,
      glint: true
    });
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4208);
  noiseSeed(4208);
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. STUDIO GREY GROUND & SUBTLE ATMOSPHERIC WASH
  // =========================================================================
  background("#dde0dc");

  // Soft studio paper grain and directional lighting falloff on background
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.2);

  // Deeper studio grey in upper-right and lower-right corners
  brush.fill("#c8ccc7", 75);
  brush.beginShape(0.3);
  brush.vertex(680, 0);
  brush.vertex(1200, 0);
  brush.vertex(1200, 1200);
  brush.vertex(520, 1200);
  brush.endShape(true);

  // Subtle warm muted-earth studio floor bounce in lower-left negative space
  brush.fill("#d6d0c5", 65);
  brush.beginShape(0.4);
  brush.vertex(0, 420);
  brush.vertex(680, 500);
  brush.vertex(560, 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);

  // Luminous pale studio highlight zone behind upper tube junction
  brush.fill("#eef1ee", 90);
  brush.circle(480, 320, 340, 0.2);
  brush.noFill();

  // Whisper-faint technical drafting datum lines in the studio background
  brush.set("2H", "#b8bdb7", 0.22);
  // Seat tube axis datum
  brush.line(862, 0, 565, 1200);
  // Top tube axis datum
  brush.line(0, 353, 960, 505);
  // Seatstay axis datum
  brush.line(580, 526, 1200, 842);
  // Technical dimension arc and crosshair ticks near junction
  brush.arc(740, 470, 250, 165, 255);
  brush.arc(740, 470, 290, -15, 32);
  for (let r = 160; r <= 320; r += 40) {
    let ang = 212;
    let cx = 740 + cos(ang) * r;
    let cy = 470 + sin(ang) * r;
    brush.line(cx - 5, cy - 5, cx + 5, cy + 5);
  }

  // =========================================================================
  // 2. 3D PARAMETRIC GEOMETRY OF THE CARBON MONOCOQUE FRAME JUNCTION
  // =========================================================================
  // Junction center P0 = (740, 470)
  // Seat Tube (ST): tilted 14 deg from vertical (goes from top-right to bottom-left)
  // Top Tube (TT): meets ST at P0, extends left-upward at -171 deg (9 deg slope)
  // Dropped Seatstay (SS): meets ST at (710, 590), extends right-downward at +27 deg

  const P0 = { x: 740, y: 470 };
  const stAngle = 104; // Down-left along seat tube: cos(104)=-0.2419, sin(104)=0.9703
  const stDir = { x: cos(stAngle), y: sin(stAngle) };
  const stNorm = { x: -stDir.y, y: stDir.x }; // Points down-right

  const ttAngle = -171; // Left-upward along top tube
  const ttDir = { x: cos(ttAngle), y: sin(ttAngle) };
  const ttNorm = { x: -ttDir.y, y: ttDir.x }; // Points upward-right

  const Pss = { x: 711, y: 586 };
  const ssAngle = 27; // Right-downward along dropped seatstay
  const ssDir = { x: cos(ssAngle), y: sin(ssAngle) };
  const ssNorm = { x: -ssDir.y, y: ssDir.x }; // Points upward-right

  // Smooth polynomial minimum for monocoque carbon fillet blending
  function smin(a, b, k) {
    let h = constrain(0.5 + (0.5 * (b - a)) / k, 0.0, 1.0);
    return lerp(b, a, h) - k * h * (1.0 - h);
  }

  // Evaluate signed distance, 3D height Z, tube ID, and local (u, v) coordinates
  function evalFrame(x, y) {
    // 1. Seat Tube & Seatpost coordinates
    let dx0 = x - P0.x;
    let dy0 = y - P0.y;
    let uST = dx0 * stDir.x + dy0 * stDir.y; // -480 (top) to +760 (bottom)
    let vST = dx0 * stNorm.x + dy0 * stNorm.y;

    // Seatpost step at uST = -245
    let isSeatpost = uST < -245;
    let rST = 94;
    if (isSeatpost) {
      rST = 74; // Aero carbon seatpost width
    } else if (uST < -225) {
      // Integrated alloy/carbon collar lip
      rST = 84 + 10 * smoothstep(-245, -225, uST);
    } else {
      // Subtle aero kammtail flare near junction and bottom bracket
      rST = 94 + 8 * exp(-pow(uST / 190, 2));
    }
    let dST = abs(vST) - rST;

    // 2. Top Tube coordinates (only for uTT > -40)
    let uTT = dx0 * ttDir.x + dy0 * ttDir.y; // 0 at junction, +800 at left edge
    let vTT = dx0 * ttNorm.x + dy0 * ttNorm.y;
    let rTT = 94 + 0.016 * constrain(uTT, 0, 800);
    // Cap top tube smoothly inside seat tube core
    let capTT = uTT < 0 ? -uTT * 1.4 : 0;
    let dTT = max(abs(vTT) - rTT, capTT - 35);

    // 3. Dropped Seatstay coordinates
    let dxs = x - Pss.x;
    let dys = y - Pss.y;
    let uSS = dxs * ssDir.x + dys * ssDir.y; // 0 at seat tube, +600 at right edge
    let vSS = dxs * ssNorm.x + dys * ssNorm.y;
    let rSS = 47 - 0.012 * constrain(uSS, 0, 600);
    let capSS = uSS < 0 ? -uSS * 1.5 : 0;
    let dSS = max(abs(vSS) - rSS, capSS - 25);

    // Smooth monocoque fillet between Top Tube and Seat Tube (only below collar)
    let kTT = uST > -210 ? 82 : 8;
    // Larger teardrop throat fillet in lower acute angle between TT and ST
    if (vTT < 0 && vST < 0 && uTT > -30 && uST > -20) {
      kTT = 108;
    }
    let dMain = smin(dST, dTT, kTT);

    // Smooth fillet between Seat Tube and Dropped Seatstay
    let kSS = 48;
    let dTotal = smin(dMain, dSS, kSS);

    // Compute 3D elevation Z(x,y) for true 3D surface normals
    let zST = dST < 0 ? sqrt(max(0, rST * rST - vST * vST)) : 0;
    let zTT =
      dTT < 0 && uTT > -50
        ? sqrt(max(0, rTT * rTT - vTT * vTT)) * smoothstep(-50, 40, uTT)
        : 0;
    let zSS =
      dSS < 0 && uSS > -40
        ? sqrt(max(0, rSS * rSS - vSS * vSS)) * smoothstep(-40, 35, uSS)
        : 0;

    // Fillet elevation boost where tubes merge
    let filletBoost = 0;
    if (dTotal < 0) {
      let edgeFactor = constrain(-dTotal / 95, 0, 1);
      let cylZ = max(zST, max(zTT, zSS));
      let domeZ = 95 * sqrt(max(0, 1 - pow(1 - edgeFactor, 2)));
      filletBoost = lerp(cylZ, max(cylZ, domeZ), 0.65);
    }

    // Determine dominant structural zone for carbon layup orientation
    // Layup seam curves through the miter between Top Tube and Seat Tube
    let seamMetric = uTT - 65 - abs(vTT) * 0.42 + (vST + 30) * 0.35;
    let zone = "ST";
    if (isSeatpost) {
      zone = "SP";
    } else if (dSS < dMain + 14 && uSS > 28 && vST > 10) {
      zone = "SS";
    } else if (seamMetric > 0 && uST > -215 && dTT < dST + 55) {
      zone = "TT";
    }

    return {
      d: dTotal,
      z: filletBoost,
      zone: zone,
      uST: uST,
      vST: vST,
      rST: rST,
      uTT: uTT,
      vTT: vTT,
      rTT: rTT,
      uSS: uSS,
      vSS: vSS,
      rSS: rSS,
      seamMetric: seamMetric
    };
  }

  function smoothstep(edge0, edge1, x) {
    let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
    return t * t * (3 - 2 * t);
  }

  // Compute unit 3D surface normal at (x, y) via central differences on Z
  function getNormal(x, y) {
    let eps = 2.5;
    let c = evalFrame(x, y);
    if (c.d > 0) return { x: 0, y: 0, z: 1, info: c };
    let zx1 = evalFrame(x + eps, y).z;
    let zx0 = evalFrame(x - eps, y).z;
    let zy1 = evalFrame(x, y + eps).z;
    let zy0 = evalFrame(x, y - eps).z;
    let dzdx = (zx1 - zx0) / (2 * eps);
    let dzdy = (zy1 - zy0) / (2 * eps);
    let nx = -dzdx;
    let ny = -dzdy;
    let nz = 1.0;
    let len = sqrt(nx * nx + ny * ny + nz * nz) || 1;
    return { x: nx / len, y: ny / len, z: nz / len, info: c };
  }

  // Evaluate whether a point (x, y) lies inside the Neon Chartreuse Decal
  function getDecalState(x, y, info) {
    if (!info) info = evalFrame(x, y);
    if (info.d > 0) return { inDecal: false, isEdge: false, isPinstripe: false };

    // Main geometric racing decal wrapping diagonally across the Top Tube into the upper fillet
    // plus a precision laser-cut stripe on the Seat Tube below the junction
    let u = info.uTT;
    let v = info.vTT;
    let diag1 = u + v * 0.58;

    // Band 1: Bold diagonal block on Top Tube (uTT ~ 115 to 315)
    // Cut out a crisp technical notch near the lower edge
    let inBand1 = diag1 > 118 && diag1 < 296 && info.uST > -190 && info.vST < 45;
    // Technical stencil cutout inside Band 1 (angled parallelogram slot)
    let slotU = diag1 - 155;
    let slotV = v - 22;
    if (slotU > 0 && slotU < 24 && slotV > -8 && slotV < 48) {
      inBand1 = false;
    }
    if (slotU > 38 && slotU < 52 && slotV > -8 && slotV < 48) {
      inBand1 = false;
    }

    // Companion razor pinstripe parallel to Band 1
    let inPin1 =
      (diag1 > 94 && diag1 < 104 && info.uST > -190 && info.vST < 35) ||
      (diag1 > 310 && diag1 < 318 && info.uST > -190 && info.vST < 35);

    // Band 2: Sharp chevron accent on Seat Tube just above/across the seatstay drop
    let stDiag = info.uST - info.vST * 0.65;
    let inBand2 =
      info.zone === "ST" &&
      stDiag > 185 &&
      stDiag < 238 &&
      info.vST < 38 &&
      info.uTT < 65;
    let inPin2 =
      info.zone === "ST" &&
      stDiag > 250 &&
      stDiag < 258 &&
      info.vST < 48 &&
      info.uTT < 65;

    let inDecal = inBand1 || inBand2 || inPin1 || inPin2;

    // Check distance to decal boundary for crisp marker edge & specular lip
    let distEdge = 999;
    if (info.uST > -190 && info.vST < 45) {
      distEdge = min(distEdge, min(abs(diag1 - 118), abs(diag1 - 296)));
      distEdge = min(distEdge, min(abs(diag1 - 94), abs(diag1 - 318)));
    }
    if (info.zone === "ST" && info.uTT < 65) {
      distEdge = min(distEdge, min(abs(stDiag - 185), abs(stDiag - 238)));
    }

    return {
      inDecal: inDecal,
      isMain: inBand1 || inBand2,
      isPinstripe: inPin1 || inPin2,
      distEdge: distEdge
    };
  }

  // =========================================================================
  // 3. UNDERPAINTING: GUNMETAL, GRAPHITE & EARTH-RESIN CARBON MATRIX
  // =========================================================================
  // Build accurate silhouette polygon points for the frame to batch base washes
  // Instead of a single complex self-intersecting polygon, scan horizontal strips
  // and group into tonal washes for deep gunmetal base, shadow core, and warm earth bounce.

  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.35, 0.25);

  // Base carbon matrix wash in horizontal scan bands (fast & exact)
  let stepY = 14;
  // Pass 1: Deep gunmetal-graphite base across all frame tubes
  brush.wash("#22272c", 235);
  for (let y = 0; y < 1200; y += stepY) {
    let segs = [];
    let inSeg = false;
    let xStart = 0;
    for (let x = 0; x <= 1200; x += 6) {
      let c = evalFrame(x, y);
      if (c.d <= 0 && !inSeg) {
        inSeg = true;
        xStart = x;
      } else if ((c.d > 0 || x === 1200) && inSeg) {
        inSeg = false;
        segs.push([xStart, x]);
      }
    }
    for (let s of segs) {
      if (s[1] - s[0] > 6) {
        brush.rect(s[0], y, s[1] - s[0], stepY + 1.5, "corner");
      }
    }
  }
  brush.noWash();

  // Pass 2: Warm muted-earth & raw-umber resin undertone in the lower/rear shadow cores
  brush.fill("#362e25", 135);
  for (let y = 20; y < 1180; y += 22) {
    for (let x = 20; x < 1180; x += 22) {
      let n = getNormal(x, y);
      if (n.info.d < -8) {
        // Shadow side facing down-right
        let shadowVal = n.x * 0.45 + n.y * 0.65;
        if (shadowVal > 0.18) {
          brush.circle(x, y, 20, 0.15);
        }
      }
    }
  }

  // Pass 3: Deep obsidian-gunmetal core shadow right before the bottom bounce light
  brush.fill("#111519", 160);
  for (let y = 20; y < 1180; y += 20) {
    for (let x = 20; x < 1180; x += 20) {
      let n = getNormal(x, y);
      if (n.info.d < -6) {
        let shadowBand = n.x * 0.52 + n.y * 0.58;
        if (shadowBand > 0.12 && shadowBand < 0.48) {
          brush.circle(x, y, 18, 0.12);
        }
      }
    }
  }
  brush.noFill();

  // =========================================================================
  // 4. DISCIPLINED PENCIL BASKETWEAVE CROSSHATCHING (3K CARBON TOWS)
  // =========================================================================
  // Each tow cell (i, j) is ~16x16px in surface UV space.
  // Warp tows have filaments along tube axis; Weft tows have filaments across tube.
  // Because of fiber crimp (diving over/under neighbors) and anisotropic reflection,
  // Warp and Weft tows catch the studio light at shifted angles across the cylinders!

  const lightDir = { x: -0.52, y: -0.62, z: 0.58 }; // Upper-left-front studio light
  const bounceDir = { x: 0.35, y: 0.72, z: 0.6 }; // Lower-right earth-toned floor bounce

  // Bucket arrays for batching pencil strokes by tone & pencil grade
  // 0: Deepest shadow (2B #0e1216)
  // 1: Dark gunmetal shadow (2B #181d23)
  // 2: Warm earth-charcoal dark (2B #28231e)
  // 3: Rich gunmetal mid-dark (HB #2b323a)
  // 4: Muted earth-graphite mid (HB #423c35)
  // 5: Neutral graphite midtone (HB #464e56)
  // 6: Cool slate mid-light (HB #5e6770)
  // 7: Warm titanium-graphite light (2H #78736a)
  // 8: Silver-graphite sheen (2H #8b95a0)
  // 9: High anisotropic tow gleam (2H #b2bcc6)
  // 10: Peak specular filament catchlight (cpencil #dce4ec)
  // 11: Crisp inter-tow crimp shadow ticks (rotring #101418)
  const buckets = Array.from({ length: 12 }, () => []);

  // Helper to generate one carbon tow cell at surface position (cx, cy)
  // with local tangent vector T = (tx, ty) and transverse vector B = (bx, by)
  function processTowCell(cx, cy, tx, ty, bx, by, i, j, towLen, towWid, zoneName) {
    let n = getNormal(cx, cy);
    if (n.info.d > -1.5) return; // Outside frame contour
    if (n.info.zone !== zoneName) return; // Respect monocoque layup seams

    // Skip tows fully buried under opaque part of neon decal (leave slight border overlap)
    let dec = getDecalState(cx, cy, n.info);
    if (dec.inDecal && dec.distEdge > 5) return;

    // Foreshorten tow width near cylinder silhouettes using surface normal Z
    let foreshorten = constrain(pow(n.z, 0.75), 0.22, 1.0);

    // 2x2 twill / shifted basketweave checker phase
    // (i + j) % 2 determines Warp (along tube) vs Weft (across tube)
    let isWarp = ((i + j) & 1) === 0;
    // Secondary 2x2 twill diagonal shift for authentic racing carbon rhythm
    let twillPhase = ((i + 2 * j) & 3) < 2 ? 1 : -1;

    // Anisotropic normal perturbation:
    // Warp filaments tilt along B and scatter specular along T;
    // Weft filaments tilt along T and scatter specular along B!
    let anisoShift = isWarp ? 0.24 : -0.24;
    let crimpShift = 0.11 * twillPhase;

    let nx = n.x + (isWarp ? bx * anisoShift + tx * crimpShift : tx * anisoShift + bx * crimpShift);
    let ny = n.y + (isWarp ? by * anisoShift + ty * crimpShift : ty * anisoShift + by * crimpShift);
    let nz = n.z;
    let nLen = sqrt(nx * nx + ny * ny + nz * nz) || 1;
    nx /= nLen;
    ny /= nLen;
    nz /= nLen;

    // Diffuse + anisotropic specular calculation
    let ndotl = max(0, nx * lightDir.x + ny * lightDir.y + nz * lightDir.z);
    // Half-vector with viewer (0, 0, 1)
    let hx = lightDir.x;
    let hy = lightDir.y;
    let hz = lightDir.z + 1.0;
    let hLen = sqrt(hx * hx + hy * hy + hz * hz);
    hx /= hLen;
    hy /= hLen;
    hz /= hLen;

    let ndoth = max(0, nx * hx + ny * hy + nz * hz);
    let spec = pow(ndoth, isWarp ? 14 : 9) * (isWarp ? 1.15 : 0.95);

    // Secondary warm floor bounce on shadow side
    let bounce = max(0, nx * bounceDir.x + ny * bounceDir.y + nz * bounceDir.z) * 0.28;

    let lum = constrain(ndotl * 0.62 + spec * 0.58 + bounce, 0, 1);

    // Subtle per-tow organic variation
    let jitter = (noise(i * 0.37, j * 0.37, zoneName.charCodeAt(0)) - 0.5) * 0.08;
    lum = constrain(lum + jitter, 0, 1);

    // Select primary pencil bucket from luminance and earth/cool balance
    let bIdx = 4;
    let isEarthTint = bounce > 0.14 && ndotl < 0.35;
    if (lum < 0.14) bIdx = 0;
    else if (lum < 0.24) bIdx = isEarthTint ? 2 : 1;
    else if (lum < 0.36) bIdx = isEarthTint ? 2 : 3;
    else if (lum < 0.48) bIdx = isEarthTint ? 4 : 5;
    else if (lum < 0.60) bIdx = 6;
    else if (lum < 0.72) bIdx = isEarthTint ? 7 : 8;
    else if (lum < 0.85) bIdx = 9;
    else bIdx = 10;

    // Direction of filaments inside this tow:
    // Warp runs along (tx, ty); Weft runs along (bx, by)
    let fx = isWarp ? tx : bx;
    let fy = isWarp ? ty : by;
    let px = isWarp ? bx : tx;
    let py = isWarp ? by : ty;

    let halfF = (isWarp ? towLen : towWid * foreshorten) * 0.46;
    let halfP = (isWarp ? towWid * foreshorten : towLen) * 0.44;

    // Number of disciplined parallel hatch lines in this tow cell (4 to 6 lines)
    let numLines = lum < 0.35 ? 6 : 5;
    for (let k = 0; k < numLines; k++) {
      let frac = numLines === 1 ? 0 : (k / (numLines - 1)) * 2 - 1; // -1 to +1
      let ox = cx + px * halfP * frac;
      let oy = cy + py * halfP * frac;

      let x1 = ox - fx * halfF;
      let y1 = oy - fy * halfF;
      let x2 = ox + fx * halfF;
      let y2 = oy + fy * halfF;

      buckets[bIdx].push([x1, y1, x2, y2]);

      // Crimp gradient: one end of the tow ribbon tucks into shadow under the crossing tow!
      if (k % 2 === 0 && bIdx > 1) {
        let tuckIdx = max(0, bIdx - 3);
        let xm = lerp(x1, x2, 0.32);
        let ym = lerp(y1, y2, 0.32);
        buckets[tuckIdx].push([x1, y1, xm, ym]);
      }
      // Highlight peak in the middle crown of the tow ribbon
      if (lum > 0.55 && (k === 1 || k === 2 || k === 3) && bIdx < 10) {
        let crownIdx = min(10, bIdx + 2);
        let xa = lerp(x1, x2, 0.28);
        let ya = lerp(y1, y2, 0.28);
        let xb = lerp(x1, x2, 0.78);
        let yb = lerp(y1, y2, 0.78);
        buckets[crownIdx].push([xa, ya, xb, yb]);
      }
    }

    // Cross-hatch shadow pass for deep shadow tows to build hyperreal graphite density
    if (lum < 0.32) {
      for (let k = -1; k <= 1; k++) {
        let ox = cx + fx * halfF * 0.55 * k;
        let oy = cy + fy * halfF * 0.55 * k;
        buckets[0].push([
          ox - px * halfP * 0.85,
          oy - py * halfP * 0.85,
          ox + px * halfP * 0.85,
          oy + py * halfP * 0.85
        ]);
      }
    }

    // Crisp micro-crimp shadow line at the boundary where this tow dives under its neighbor
    let bx1 = cx + fx * halfF - px * halfP * 0.9;
    let by1 = cy + fy * halfF - py * halfP * 0.9;
    let bx2 = cx + fx * halfF + px * halfP * 0.9;
    let by2 = cy + fy * halfF + py * halfP * 0.9;
    buckets[11].push([bx1, by1, bx2, by2]);
  }

  // Generate weave cells across the 4 structural zones:
  const towStep = 15.5;

  // Zone 1: Seat Tube (ST)
  for (let i = -16; i <= 50; i++) {
    let u = i * towStep;
    for (let j = -7; j <= 7; j++) {
      let v = j * towStep;
      // Subtle 3D cylindrical curve warps the tangent near the fillet
      let cx = P0.x + u * stDir.x + v * stNorm.x;
      let cy = P0.y + u * stDir.y + v * stNorm.y;
      processTowCell(
        cx,
        cy,
        stDir.x,
        stDir.y,
        stNorm.x,
        stNorm.y,
        i,
        j,
        towStep,
        towStep,
        "ST"
      );
    }
  }

  // Zone 2: Top Tube (TT) - weave flows along top tube and miters cleanly at the junction seam
  for (let i = -3; i <= 52; i++) {
    let u = i * towStep;
    for (let j = -8; j <= 8; j++) {
      let v = j * towStep;
      // Slight fillet flare distortion near u < 120
      let flare = u < 140 ? (140 - u) * 0.0018 * v : 0;
      let tx = ttDir.x - ttNorm.x * flare;
      let ty = ttDir.y - ttNorm.y * flare;
      let tLen = sqrt(tx * tx + ty * ty) || 1;
      tx /= tLen;
      ty /= tLen;
      let bx = -ty;
      let by = tx;

      let cx = P0.x + u * ttDir.x + v * ttNorm.x;
      let cy = P0.y + u * ttDir.y + v * ttNorm.y;
      processTowCell(cx, cy, tx, ty, bx, by, i, j, towStep, towStep, "TT");
    }
  }

  // Zone 3: Dropped Seatstay (SS)
  for (let i = 0; i <= 38; i++) {
    let u = i * towStep;
    for (let j = -4; j <= 4; j++) {
      let v = j * towStep;
      let cx = Pss.x + u * ssDir.x + v * ssNorm.x;
      let cy = Pss.y + u * ssDir.y + v * ssNorm.y;
      processTowCell(
        cx,
        cy,
        ssDir.x,
        ssDir.y,
        ssNorm.x,
        ssNorm.y,
        i,
        j,
        towStep,
        towStep,
        "SS"
      );
    }
  }

  // Zone 4: Aero Carbon Seatpost (SP) - tighter 1K weave / UD hybrid above collar
  let spStep = 12.5;
  for (let i = -42; i <= -19; i++) {
    let u = i * spStep;
    for (let j = -6; j <= 6; j++) {
      let v = j * spStep;
      let cx = P0.x + u * stDir.x + v * stNorm.x;
      let cy = P0.y + u * stDir.y + v * stNorm.y;
      processTowCell(
        cx,
        cy,
        stDir.x,
        stDir.y,
        stNorm.x,
        stNorm.y,
        i,
        j,
        spStep,
        spStep,
        "SP"
      );
    }
  }

  // Execute all batched pencil basketweave strokes in tonal order
  const bucketSpecs = [
    { brush: "2B", color: "#0d1115", weight: 0.58 },
    { brush: "2B", color: "#171c22", weight: 0.52 },
    { brush: "2B", color: "#27221c", weight: 0.52 },
    { brush: "HB", color: "#2a3138", weight: 0.48 },
    { brush: "HB", color: "#433c34", weight: 0.46 },
    { brush: "HB", color: "#454d55", weight: 0.45 },
    { brush: "HB", color: "#5d6670", weight: 0.44 },
    { brush: "2H", color: "#7c756b", weight: 0.42 },
    { brush: "2H", color: "#8c96a0", weight: 0.42 },
    { brush: "2H", color: "#b4bec8", weight: 0.40 },
    { brush: "cpencil", color: "#dfe7ef", weight: 0.38 },
    { brush: "rotring", color: "#0f1317", weight: 0.28 }
  ];

  for (let b = 0; b < buckets.length; b++) {
    let spec = bucketSpecs[b];
    let lines = buckets[b];
    if (lines.length === 0) continue;
    brush.set(spec.brush, spec.color, spec.weight);
    for (let i = 0; i < lines.length; i++) {
      let l = lines[i];
      brush.line(l[0], l[1], l[2], l[3]);
    }
  }

  // =========================================================================
  // 5. MONOCOQUE LAYUP SEAM & INTEGRATED TITANIUM SEATPOST CLAMP COLLAR
  // =========================================================================
  // Draw the subtle carbon layup overlap seam where Top Tube weave meets Seat Tube weave
  brush.set("rotring", "#14181d", 0.35);
  for (let t = -95; t <= 115; t += 4) {
    let v = t;
    let u = 65 + abs(v) * 0.42 - (v + 30) * 0.25;
    let sx = P0.x + u * ttDir.x + v * ttNorm.x;
    let sy = P0.y + u * ttDir.y + v * ttNorm.y;
    let c = evalFrame(sx, sy);
    if (c.d < -3) {
      brush.line(sx - 2, sy - 3, sx + 2, sy + 3);
    }
  }
  // Faint resin highlight along the miter seam
  brush.set("2H", "#858f99", 0.28);
  for (let t = -80; t <= 40; t += 6) {
    let v = t;
    let u = 63 + abs(v) * 0.42 - (v + 30) * 0.25;
    let sx = P0.x + u * ttDir.x + v * ttNorm.x;
    let sy = P0.y + u * ttDir.y + v * ttNorm.y;
    if (evalFrame(sx, sy).d < -5) {
      brush.line(sx, sy, sx + 1.5, sy + 4);
    }
  }

  // Integrated Seatpost Collar & Recessed Titanium Wedge Bolt around uST = -235
  let collarU = -235;
  let colCenter = {
    x: P0.x + collarU * stDir.x,
    y: P0.y + collarU * stDir.y
  };

  // Black-anodized collar bevel & rubber dust seal
  brush.set("marker", "#16191d", 1.1);
  brush.line(
    colCenter.x - stNorm.x * 78,
    colCenter.y - stNorm.y * 78,
    colCenter.x + stNorm.x * 78,
    colCenter.y + stNorm.y * 78
  );
  brush.set("rotring", "#090b0d", 0.65);
  brush.line(
    colCenter.x - stNorm.x * 76 - stDir.x * 6,
    colCenter.y - stNorm.y * 76 - stDir.y * 6,
    colCenter.x + stNorm.x * 76 - stDir.x * 6,
    colCenter.y + stNorm.y * 76 - stDir.y * 6
  );
  // Crisp top edge catchlight on the machined collar
  brush.set("2H", "#ced6de", 0.42);
  brush.line(
    colCenter.x - stNorm.x * 72 + stDir.x * 2,
    colCenter.y - stNorm.y * 72 + stDir.y * 2,
    colCenter.x + stNorm.x * 15 + stDir.x * 2,
    colCenter.y + stNorm.y * 15 + stDir.y * 2
  );

  // Recessed Titanium M5 Hex Bolt pocket on the upper-front of the seat tube collar
  let boltX = colCenter.x - stNorm.x * 36 + stDir.x * 22;
  let boltY = colCenter.y - stNorm.y * 36 + stDir.y * 22;
  // Pocket shadow
  brush.noStroke();
  brush.wash("#121518", 230);
  brush.circle(boltX, boltY, 15, 0.08);
  // Warm titanium washer & bolt head (muted earth-bronze metallic sheen)
  brush.wash("#7d7568", 240);
  brush.circle(boltX + 1.5, boltY + 1, 10.5, 0.05);
  brush.wash("#22201c", 245);
  brush.circle(boltX + 2, boltY + 1.5, 5.5, 0.05);
  brush.noWash();
  // Titanium specular rim
  brush.set("rotring", "#ebe5da", 0.45);
  brush.arc(boltX + 1.5, boltY + 1, 10.5, 195, 315);
  brush.set("rotring", "#0c0e10", 0.4);
  brush.circle(boltX, boltY, 15, 0.06);

  // Micro technical torque spec ticks next to bolt ("5.5 Nm" indicator marks)
  brush.set("rotring", "#a8b0b8", 0.26);
  for (let m = 0; m < 5; m++) {
    let tx = boltX + 22 + m * 4.5;
    let ty = boltY + 4 + m * 1.1;
    brush.line(tx, ty, tx - 1.5, ty + 5);
  }

  // =========================================================================
  // 6. NEON CHARTREUSE DECAL EDGE CUT CRISP IN MARKER
  // =========================================================================
  // Render the electric yellow / chartreuse decal in dense marker strokes that
  // wrap accurately around the 3D tube cylinders and shade into warm earth-olive in shadow.

  const decalBright = []; // Electric neon chartreuse (#d9ff00)
  const decalMid = []; // Vivid acid yellow-green (#bce300)
  const decalOlive = []; // Shaded earth-chartreuse (#889c14)
  const decalShadow = []; // Deep olive-umber core shadow (#555e10)

  // Scan along the Top Tube and Seat Tube decal zones with fine marker strokes
  // Top Tube Band 1 & Pinstripes
  for (let u = 85; u <= 330; u += 2.2) {
    for (let v = -102; v <= 102; v += 2.5) {
      let x = P0.x + u * ttDir.x + v * ttNorm.x;
      let y = P0.y + u * ttDir.y + v * ttNorm.y;
      let n = getNormal(x, y);
      if (n.info.d > -1.5) continue;
      let dec = getDecalState(x, y, n.info);
      if (!dec.inDecal) continue;

      let ndotl = n.x * lightDir.x + n.y * lightDir.y + n.z * lightDir.z;
      let segLen = 3.2;
      let sx1 = x - ttDir.x * segLen;
      let sy1 = y - ttDir.y * segLen;
      let sx2 = x + ttDir.x * segLen;
      let sy2 = y + ttDir.y * segLen;

      if (ndotl > 0.35) decalBright.push([sx1, sy1, sx2, sy2]);
      else if (ndotl > 0.05) decalMid.push([sx1, sy1, sx2, sy2]);
      else if (ndotl > -0.22) decalOlive.push([sx1, sy1, sx2, sy2]);
      else decalShadow.push([sx1, sy1, sx2, sy2]);
    }
  }

  // Seat Tube Band 2 & Pinstripe
  for (let u = 110; u <= 310; u += 2.2) {
    for (let v = -96; v <= 55; v += 2.5) {
      let x = P0.x + u * stDir.x + v * stNorm.x;
      let y = P0.y + u * stDir.y + v * stNorm.y;
      let n = getNormal(x, y);
      if (n.info.d > -1.5) continue;
      let dec = getDecalState(x, y, n.info);
      if (!dec.inDecal) continue;

      let ndotl = n.x * lightDir.x + n.y * lightDir.y + n.z * lightDir.z;
      let segLen = 3.2;
      let sx1 = x - stDir.x * segLen;
      let sy1 = y - stDir.y * segLen;
      let sx2 = x + stDir.x * segLen;
      let sy2 = y + stDir.y * segLen;

      if (ndotl > 0.32) decalBright.push([sx1, sy1, sx2, sy2]);
      else if (ndotl > 0.04) decalMid.push([sx1, sy1, sx2, sy2]);
      else if (ndotl > -0.22) decalOlive.push([sx1, sy1, sx2, sy2]);
      else decalShadow.push([sx1, sy1, sx2, sy2]);
    }
  }

  // Draw marker passes from dark shadow to electric neon chartreuse
  brush.set("marker", "#545d12", 0.95);
  for (let s of decalShadow) brush.line(s[0], s[1], s[2], s[3]);

  brush.set("marker", "#8ba116", 0.95);
  for (let s of decalOlive) brush.line(s[0], s[1], s[2], s[3]);

  brush.set("marker", "#bfe600", 0.95);
  for (let s of decalMid) brush.line(s[0], s[1], s[2], s[3]);

  brush.set("marker", "#dcff00", 1.0);
  for (let s of decalBright) brush.line(s[0], s[1], s[2], s[3]);

  // Razor-crisp marker & rotring cut edges along the decal boundaries
  // Plus a physical 1px vinyl thickness step highlight (#f4ff9c)
  function traceDecalCutLine(diagVal, isTopTube) {
    let pts = [];
    let highlightPts = [];
    if (isTopTube) {
      for (let v = -102; v <= 102; v += 3) {
        let u = diagVal - v * 0.58;
        let x = P0.x + u * ttDir.x + v * ttNorm.x;
        let y = P0.y + u * ttDir.y + v * ttNorm.y;
        let c = evalFrame(x, y);
        if (c.d < -1.5 && c.uST > -190 && c.vST < 45) {
          pts.push([x, y]);
          if (v < 25) highlightPts.push([x + 1.2, y - 0.8]);
        }
      }
    } else {
      for (let v = -96; v <= 46; v += 3) {
        let u = diagVal + v * 0.65;
        let x = P0.x + u * stDir.x + v * stNorm.x;
        let y = P0.y + u * stDir.y + v * stNorm.y;
        let c = evalFrame(x, y);
        if (c.d < -1.5 && c.zone === "ST" && c.uTT < 65) {
          pts.push([x, y]);
          if (v < 10) highlightPts.push([x - 1.2, y - 0.8]);
        }
      }
    }

    if (pts.length > 2) {
      brush.set("marker", "#d6fc00", 0.65);
      brush.spline(pts, 0.3);
      brush.set("rotring", "#191f05", 0.35);
      brush.spline(pts, 0.3);
    }
    if (highlightPts.length > 2) {
      brush.set("cpencil", "#f7ffb0", 0.42);
      brush.spline(highlightPts, 0.3);
    }
  }

  traceDecalCutLine(118, true);
  traceDecalCutLine(296, true);
  traceDecalCutLine(94, true);
  traceDecalCutLine(104, true);
  traceDecalCutLine(310, true);
  traceDecalCutLine(318, true);
  traceDecalCutLine(185, false);
  traceDecalCutLine(238, false);
  traceDecalCutLine(250, false);
  traceDecalCutLine(258, false);

  // Faint ghost of carbon basketweave texture showing through the decal in midtones
  brush.set("2H", "#9eb508", 0.25);
  for (let i = 7; i <= 20; i++) {
    for (let j = -6; j <= 4; j++) {
      let cx = P0.x + i * towStep * ttDir.x + j * towStep * ttNorm.x;
      let cy = P0.y + i * towStep * ttDir.y + j * towStep * ttNorm.y;
      let dec = getDecalState(cx, cy);
      if (dec.isMain) {
        brush.line(cx - 5, cy - 1, cx + 5, cy + 1);
      }
    }
  }

  // =========================================================================
  // 7. CLEAR LACQUER SHELL & CURVING WINDOW-REFLECTION HIGHLIGHT
  // =========================================================================
  // Compute the reflection of a paned studio window across the 3D surface normals!
  // Because getNormal(x, y) follows both the cylindrical curvature AND the concave
  // saddle fillet where top tube meets seat tube, the window reflection naturally
  // curves, pinches, and wraps across the monocoque junction!

  const winGlaze = []; // Soft outer Fresnel halo (#cad5e0)
  const winBody = []; // Crisp bright window reflection (#e6eef5)
  const winCore = []; // Pure specular lacquer highlight (#ffffff)
  const rimBounce = []; // Secondary lower-right studio floor reflection (#8e8477)

  for (let y = 8; y < 1192; y += 2.6) {
    for (let x = 8; x < 1192; x += 2.6) {
      let n = getNormal(x, y);
      if (n.info.d > -2) continue;

      // Reflection vector R for eye vector V = (0, 0, 1):
      // R = 2*(N.V)*N - V = (2*nx*nz, 2*ny*nz, 2*nz*nz - 1)
      let rx = 2 * n.x * n.z;
      let ry = 2 * n.y * n.z;

      // Studio window sits along the ridge where N tilts toward upper-left:
      // Trace a continuous curving reflection band across Top Tube, Fillet, Seat Tube, and Seatstay
      // Window cross-coordinate wCoord measures distance from the ideal reflection ridge
      let wRidge = rx * 0.64 + ry * 0.76 + 0.58;
      // Longitudinal position along the reflection band (for window mullion bars!)
      let wLong = (x - 620) * 0.68 - (y - 440) * 0.73;

      // Studio window mullion bars (3 crisp dark gaps where window frame bars cross the highlight)
      let inMullion =
        (wLong > -165 && wLong < -148) ||
        (wLong > 45 && wLong < 62) ||
        (wLong > 265 && wLong < 280) ||
        (wLong > -390 && wLong < -374);

      // Transverse window sash bar
      let inCrossBar = abs(wRidge - 0.015) < 0.016 && wLong > -148 && wLong < 265;

      //Tangent direction along the isophote contour (perpendicular to surface gradient)
      let tangX = -n.y;
      let tangY = n.x;
      let tLen = sqrt(tangX * tangX + tangY * tangY) || 1;
      tangX /= tLen;
      tangY /= tLen;

      if (abs(wRidge) < 0.14 && n.z > 0.35) {
        if (!inMullion && !inCrossBar) {
          let sLen = 4.2;
          let x1 = x - tangX * sLen;
          let y1 = y - tangY * sLen;
          let x2 = x + tangX * sLen;
          let y2 = y + tangY * sLen;

          winGlaze.push([x1, y1, x2, y2]);
          if (abs(wRidge) < 0.085) {
            winBody.push([x1, y1, x2, y2]);
          }
          if (abs(wRidge) < 0.042) {
            winCore.push([x1, y1, x2, y2]);
          }
        } else if (abs(wRidge) < 0.09) {
          // Subtle blue-grey lacquer sheen inside the window mullion gap
          winGlaze.push([
            x - tangX * 2.5,
            y - tangY * 2.5,
            x + tangX * 2.5,
            y + tangY * 2.5
          ]);
        }
      }

      // Secondary warm muted-earth floor reflection near the shadow-side silhouette rim
      let floorRidge = rx * 0.55 + ry * 0.82 - 0.76;
      if (abs(floorRidge) < 0.075 && n.z > 0.25 && n.z < 0.72) {
        rimBounce.push([
          x - tangX * 3.5,
          y - tangY * 3.5,
          x + tangX * 3.5,
          y + tangY * 3.5
        ]);
      }
    }
  }

  // Render the secondary earth-toned floor bounce reflection on the dark underside/rear of tubes
  brush.set("2H", "#8f8578", 0.45);
  for (let s of rimBounce) brush.line(s[0], s[1], s[2], s[3]);

  // Render the clear lacquer studio window reflection in layered luminous passes
  brush.set("2H", "#b8c5d1", 0.55);
  for (let s of winGlaze) brush.line(s[0], s[1], s[2], s[3]);

  brush.set("cpencil", "#e4edf5", 0.65);
  for (let s of winBody) brush.line(s[0], s[1], s[2], s[3]);

  brush.set("rotring", "#ffffff", 0.55);
  for (let s of winCore) brush.line(s[0], s[1], s[2], s[3]);

  // Extra razor-sharp continuous spline contour along the outer edge of the curving window reflection
  // where it sweeps from the Top Tube through the concave Fillet and down the Seat Tube
  let filletCurve = [];
  for (let t = 0; t <= 1; t += 0.025) {
    // Parametric sweep through the saddle of the junction
    let uT = lerp(420, 22, pow(t, 0.75));
    let uS = lerp(-12, 340, pow(t, 1.35));
    let blend = smoothstep(0.15, 0.85, t);
    let xT = P0.x + uT * ttDir.x - 42 * ttNorm.x;
    let yT = P0.y + uT * ttDir.y - 42 * ttNorm.y;
    let xS = P0.x + uS * stDir.x - 44 * stNorm.x;
    let yS = P0.y + uS * stDir.y - 44 * stNorm.y;
    // Pull slightly into the fillet throat at mid-transition
    let throatPull = 26 * sin(t * 180);
    let px = lerp(xT, xS, blend) - throatPull * 0.7;
    let py = lerp(yT, yS, blend) + throatPull * 0.7;
    filletCurve.push([px, py]);
  }
  brush.set("rotring", "#ffffff", 0.48);
  brush.spline(filletCurve, 0.5);

  // =========================================================================
  // 8. GRITTY ROAD SMEAR (MUTED EARTH TONES, SILT, UMBERS & QUARTZ GRIT)
  // =========================================================================
  // Placed across the lower Seat Tube, the Seatstay junction, and smeared
  // obliquely upward-left by wet tire spray and airflow across the carbon and decal!

  // 1. Translucent dried muddy water stain & tide-mark rings (watercolor fill)
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.75, 0.65);

  // Warm raw-umber / khaki silt stains on the lower seat tube and fillet throat
  const mudPatches = [
    { x: 662, y: 615, r: 46, col: "#6e5c49", op: 95 },
    { x: 638, y: 665, r: 38, col: "#574736", op: 110 },
    { x: 688, y: 562, r: 32, col: "#85725c", op: 85 },
    { x: 615, y: 740, r: 44, col: "#4d3e2e", op: 115 },
    { x: 650, y: 810, r: 35, col: "#7a6855", op: 90 },
    { x: 755, y: 625, r: 28, col: "#63513f", op: 100 },
    { x: 585, y: 505, r: 22, col: "#7d6a56", op: 80 }
  ];

  for (let p of mudPatches) {
    brush.fill(p.col, p.op);
    brush.circle(p.x, p.y, p.r, 0.38);
  }
  brush.noFill();

  // 2. Oblique wind-smeared road grime streaks (angled at ~ -32 deg from rear wheel spray)
  const smearAngle = -142; // Up and forward-left across the seat tube
  const sdx = cos(smearAngle);
  const sdy = sin(smearAngle);

  // Dry pigment / charcoal and colored pencil streaks in muted earth tones
  const earthStreaks = [
    { brush: "charcoal", col: "#3d3024", w: 0.7, count: 55 },
    { brush: "cpencil", col: "#6e5a46", w: 0.55, count: 70 },
    { brush: "cpencil", col: "#948069", w: 0.48, count: 65 },
    { brush: "2B", col: "#261e17", w: 0.5, count: 45 },
    { brush: "2H", col: "#b8a690", w: 0.38, count: 45 }
  ];

  for (let layer of earthStreaks) {
    brush.set(layer.brush, layer.col, layer.w);
    for (let i = 0; i < layer.count; i++) {
      // Cluster along a diagonal splash band from (770, 670) toward (540, 480) and down to (620, 890)
      let t = random();
      let baseX = lerp(745, 595, t) + randomGaussian(0, 36);
      let baseY = lerp(650, 520, t) + random(0, 260) * pow(random(), 1.4);

      let c = evalFrame(baseX, baseY);
      if (c.d < -4) {
        let len = random(12, 54);
        let wobble = random(-8, 8);
        let ang = smearAngle + wobble;
        let x2 = baseX + cos(ang) * len;
        let y2 = baseY + sin(ang) * len;
        if (evalFrame(x2, y2).d < -3) {
          brush.line(baseX, baseY, x2, y2);
        }
      }
    }
  }

  // 3. Spray stipple for fine road mist & dried silt dust
  brush.set("spray", "#594838", 0.65);
  brush.line(730, 640, 610, 545);
  brush.line(665, 760, 595, 650);
  brush.set("spray", "#a6937c", 0.55);
  brush.line(715, 620, 625, 555);
  brush.line(650, 790, 600, 700);

  // 4. Individual 3D Quartz / Asphalt Grit Particles sitting on the clearcoat
  // Each grain has a tiny dark contact shadow on its down-right side and a sharp mineral catchlight!
  const gritShadows = [];
  const gritBodies = [];
  const gritCatchlights = [];

  for (let i = 0; i < 190; i++) {
    let gx = random(545, 810);
    let gy = random(475, 920);
    // Concentrate along the main road spray trajectory
    let distBand = abs((gx - 660) * 0.65 + (gy - 640) * 0.76);
    if (distBand > 135 && random() < 0.75) continue;

    let c = evalFrame(gx, gy);
    if (c.d < -5) {
      let sz = random(1.2, 3.8);
      // Cast shadow down-right
      gritShadows.push([gx + 1.2, gy + 1.4, gx + 1.2 + sz, gy + 1.4 + sz * 0.6]);
      // Earthy grain body
      gritBodies.push([gx - sz * 0.5, gy, gx + sz * 0.5, gy + sz * 0.3]);
      // Mineral catchlight on upper-left of grain
      if (random() < 0.65) {
        gritCatchlights.push([gx - sz * 0.4, gy - sz * 0.4, gx + 0.4, gy - 0.2]);
      }
    }
  }

  brush.set("rotring", "#0b0907", 0.55);
  for (let g of gritShadows) brush.line(g[0], g[1], g[2], g[3]);

  brush.set("2B", "#4a3b2c", 0.7);
  for (let g of gritBodies) brush.line(g[0], g[1], g[2], g[3]);

  brush.set("rotring", "#ede4d7", 0.42);
  for (let g of gritCatchlights) brush.line(g[0], g[1], g[2], g[3]);

  // =========================================================================
  // 9. HYPERREAL BEAD OF SWEAT ON THE TOP TUBE LACQUER & DECAL EDGE
  // =========================================================================
  // Positioned at (468, 412) right across the upper-front curve of the Top Tube,
  // straddling the razor edge of the Neon Chartreuse Decal so it refracts both
  // the carbon weave and the electric yellow stripe!

  function drawSweatBead(bx, by, rx, ry, hasDecalRefraction) {
    // 1. Dark cast shadow down-right of the droplet
    brush.noStroke();
    brush.fillBleed(0.06, "out");
    brush.fill("#0c0f12", 185);
    brush.beginShape(0.45);
    for (let a = -25; a <= 145; a += 20) {
      let sx = bx + rx * 0.32 + cos(a) * rx * 1.05;
      let sy = by + ry * 0.38 + sin(a) * ry * 0.92;
      brush.vertex(sx, sy);
    }
    brush.endShape(true);

    // 2. Internal Caustic Lens Focus inside the cast shadow!
    // Because the sweat bead acts as a convex lens, it focuses a bright crescent into its own shadow
    brush.fill(hasDecalRefraction ? "#eaff47" : "#b8c6d4", 170);
    brush.circle(bx + rx * 0.38, by + ry * 0.42, rx * 0.52, 0.15);
    brush.noFill();

    // 3. Dark upper-left internal reflection meniscus (where studio light enters the dome)
    brush.set("2B", "#12161b", 0.75);
    for (let r = 0.72; r <= 0.98; r += 0.08) {
      let pts = [];
      for (let a = 145; a <= 315; a += 12) {
        pts.push([bx + cos(a) * rx * r, by + sin(a) * ry * r]);
      }
      brush.spline(pts, 0.4);
    }

    // 4. Magnified & warped refraction inside the bead (carbon crosshatching + chartreuse edge)
    if (hasDecalRefraction) {
      brush.set("marker", "#e2ff1a", 0.75);
      for (let t = -0.6; t <= 0.65; t += 0.18) {
        let yOff = t * ry * 0.75;
        let xSpan = sqrt(max(0, 1 - t * t)) * rx * 0.72;
        brush.line(bx - xSpan * 0.2, by + yOff, bx + xSpan * 0.85, by + yOff + 2);
      }
    }
    // Magnified curved carbon filaments inside the droplet lens
    brush.set("rotring", "#1b2128", 0.35);
    for (let k = -3; k <= 3; k++) {
      let cPts = [];
      for (let s = -0.75; s <= 0.75; s += 0.25) {
        let px = bx + s * rx * 0.75;
        let py = by + k * 3.5 + pow(s, 2) * 4.5;
        if (pow((px - bx) / rx, 2) + pow((py - by) / ry, 2) < 0.78) {
          cPts.push([px, py]);
        }
      }
      if (cPts.length > 2) brush.spline(cPts, 0.4);
    }

    // 5. Luminous lower-right internal meniscus bounce glow
    brush.set("cpencil", hasDecalRefraction ? "#f4ff8a" : "#d0dce8", 0.6);
    let glowPts = [];
    for (let a = -15; a <= 115; a += 12) {
      glowPts.push([bx + cos(a) * rx * 0.82, by + sin(a) * ry * 0.82]);
    }
    brush.spline(glowPts, 0.4);

    // 6. Crisp miniature studio window reflection on upper-left dome of the bead
    let hx = bx - rx * 0.36;
    let hy = by - ry * 0.36;
    brush.set("rotring", "#ffffff", 0.75);
    brush.arc(bx, by, rx * 0.68, 200, 252);
    brush.arc(bx, by, rx * 0.56, 202, 250);
    // Tiny secondary specular pinpoint
    brush.line(hx - 1, hy + rx * 0.28, hx + 1.5, hy + rx * 0.25);

    // 7. Outer contact meniscus ring (surface tension contact line on hydrophobic clearcoat)
    brush.set("rotring", "#0c1014", 0.38);
    let rimPts = [];
    for (let a = 0; a <= 360; a += 15) {
      // Slight gravity teardrop bulge on the bottom side
      let grav = a > 0 && a < 180 ? 1 + 0.08 * sin(a) : 1;
      rimPts.push([bx + cos(a) * rx * grav, by + sin(a) * ry * grav]);
    }
    brush.spline(rimPts, 0.45);
  }

  // Primary plump bead of sweat straddling the chartreuse decal edge on the Top Tube
  drawSweatBead(472, 412, 22, 18.5, true);

  // Secondary smaller satellite sweat beads nearby on the carbon weave
  drawSweatBead(424, 386, 9.5, 8.2, false);
  drawSweatBead(514, 434, 6.5, 5.8, true);
  drawSweatBead(445, 438, 4.2, 3.8, false);

  // Subtle dried salt trace / micro-condensation trail above the primary sweat bead
  brush.set("2H", "#b8c2cc", 0.26);
  let trailPts = [
    [452, 344],
    [458, 362],
    [465, 380],
    [470, 392]
  ];
  brush.spline(trailPts, 0.35);

  // =========================================================================
  // 10. PRECISION SILHOUETTE CONTOURS & FINAL HYPERREAL GRAPHITE ACCENTS
  // =========================================================================
  // Trace the exact outer boundary of the monocoque frame with crisp, varied
  // line weight: razor-sharp 2H/rotring against the bright studio light, and
  // deep 2B gunmetal-black along the underside shadow contours.

  const lightContour = [];
  const shadowContour = [];

  for (let y = 4; y < 1196; y += 3) {
    let prevD = evalFrame(0, y).d;
    for (let x = 3; x < 1196; x += 3) {
      let curD = evalFrame(x, y).d;
      if ((prevD > 0 && curD <= 0) || (prevD <= 0 && curD > 0)) {
        // Interpolate exact boundary crossing
        let frac = abs(prevD) / (abs(prevD) + abs(curD) + 0.0001);
        let bx = x - 3 + frac * 3;
        let by = y;
        let n = getNormal(bx + (prevD > 0 ? 3 : -3), by);
        if (n.x * lightDir.x + n.y * lightDir.y > 0) {
          lightContour.push([bx, by]);
        } else {
          shadowContour.push([bx, by]);
        }
      }
      prevD = curD;
    }
  }

  // Also scan vertically for nearly-horizontal Top Tube & Seatstay edges
  for (let x = 4; x < 1196; x += 3) {
    let prevD = evalFrame(x, 0).d;
    for (let y = 3; y < 1196; y += 3) {
      let curD = evalFrame(x, y).d;
      if ((prevD > 0 && curD <= 0) || (prevD <= 0 && curD > 0)) {
        let frac = abs(prevD) / (abs(prevD) + abs(curD) + 0.0001);
        let bx = x;
        let by = y - 3 + frac * 3;
        let n = getNormal(bx, by + (prevD > 0 ? 3 : -3));
        if (n.x * lightDir.x + n.y * lightDir.y > 0) {
          lightContour.push([bx, by]);
        } else {
          shadowContour.push([bx, by]);
        }
      }
      prevD = curD;
    }
  }

  // Crisp technical boundary ticks along the illuminated edges
  brush.set("rotring", "#2b323a", 0.36);
  for (let p of lightContour) {
    brush.line(p[0] - 1, p[1] - 1, p[0] + 1, p[1] + 1);
  }

  // Rich, heavy graphite boundary definition along the shadow edges
  brush.set("2B", "#0d1014", 0.58);
  for (let p of shadowContour) {
    brush.line(p[0] - 1.2, p[1] - 1.2, p[0] + 1.2, p[1] + 1.2);
  }

  noLoop();
}

