// Safe spline wrapper to prevent zero-length segment issues
function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let cleaned = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = cleaned[cleaned.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 2.2) {
      cleaned.push(pts[i]);
    }
  }
  if (cleaned.length < 2) return;
  if (cleaned.length === 2) {
    brush.line(cleaned[0][0], cleaned[0][1], cleaned[1][0], cleaned[1][1]);
  } else {
    brush.spline(cleaned, curvature);
  }
}

// Palette outer boundary point generator
function getPaletteContour(numPts = 120) {
  let pts = [];
  let cx = 610, cy = 605;
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    let rad = a * (PI / 180);
    // Kidney-oval artist palette shape
    let rx = 545 + 35 * cos(rad * 2 - 0.5);
    let ry = 535 + 25 * sin(rad * 2 + 0.3);
    // Indent for the kidney grip notch near bottom-right (around 42 degrees)
    let diff = atan2(sin(rad - 0.78), cos(rad - 0.78));
    let notch = exp(-pow(diff / 0.42, 2)) * 105;
    let r = (rx * ry) / sqrt(pow(ry * cos(rad), 2) + pow(rx * sin(rad), 2)) - notch;
    // Slight asymmetry for ergonomic curve
    let x = cx + r * cos(rad) - 18 * sin(rad);
    let y = cy + r * sin(rad) + 12 * cos(rad * 2);
    pts.push([x, y]);
  }
  return pts;
}

// Thumbhole contour generator
function getThumbholeContour(numPts = 60, offsetX = 0, offsetY = 0, scaleM = 1.0) {
  let pts = [];
  let hcx = 900 + offsetX;
  let hcy = 895 + offsetY;
  let tilt = -36 * (PI / 180);
  let rx = 96 * scaleM;
  let ry = 56 * scaleM;
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * TWO_PI;
    let lx = rx * cos(a);
    let ly = ry * sin(a);
    let x = hcx + lx * cos(tilt) - ly * sin(tilt);
    let y = hcy + lx * sin(tilt) + ly * cos(tilt);
    pts.push([x, y]);
  }
  return pts;
}

function drawShapeFromPts(pts, closeShape = true, curvature = 0.3) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

// ---------------------------------------------------------------------------
// 1. STUDIO TABLE & WELL-USED WOODEN PALETTE
// ---------------------------------------------------------------------------
function drawStudioAndPaletteBase() {
  background("#14171f");

  // Dark studio linen / tabletop texture in corners
  brush.noFill();
  brush.noWash();
  for (let i = 0; i < 95; i++) {
    let y = map(i, 0, 94, 10, 1190);
    brush.set("cream_marker", i % 2 === 0 ? "#181c26" : "#11141c", random(1.8, 3.2));
    brush.line(10, y + random(-6, 6), 1190, y + random(-6, 6));
  }

  let palPts = getPaletteContour(100);

  // Deep cast shadow of the wooden palette onto the studio table
  for (let layer = 5; layer >= 1; layer--) {
    let sx = layer * 5.5;
    let sy = layer * 7.0;
    let shPts = palPts.map(p => [p[0] + sx, p[1] + sy]);
    brush.noStroke();
    brush.wash("#07080c", map(layer, 1, 5, 130, 35));
    drawShapeFromPts(shPts, true, 0.3);
  }

  // Thick dark walnut side bevel of the wooden palette (bottom-right rim thickness)
  for (let step = 12; step >= 1; step--) {
    let bx = step * 1.1;
    let by = step * 1.35;
    let bevPts = palPts.map(p => [p[0] + bx, p[1] + by]);
    brush.noStroke();
    brush.wash(step > 6 ? "#2a160a" : "#442411", 220);
    drawShapeFromPts(bevPts, true, 0.3);
  }

  // Main warm oiled wood base wash
  brush.noStroke();
  brush.wash("#8f5931", 255);
  drawShapeFromPts(palPts, true, 0.3);

  // North-window daylight tonal gradient across the wood surface
  // Brighter honey-amber toward upper-left, deeper burnt umber toward lower-right
  let zoneColors = [
    { x: 430, y: 390, r: 440, col: "#b98050", op: 95 },
    { x: 350, y: 300, r: 330, col: "#cfa072", op: 80 },
    { x: 760, y: 780, r: 460, col: "#6b3d1c", op: 90 },
    { x: 880, y: 860, r: 320, col: "#522c12", op: 85 }
  ];
  for (let z of zoneColors) {
    brush.noStroke();
    brush.wash(z.col, z.op);
    brush.circle(z.x, z.y, z.r, 0.15);
  }

  // Sweeping wood grain lines clipped/constrained inside the palette
  let grainPalette = [
    "#5c3316", "#6e3f1d", "#7d4a24", "#986136",
    "#ad7446", "#c28b5b", "#cfa070", "#47250e"
  ];

  // Check if a point is inside the palette ellipse approximation
  function insidePalette(x, y) {
    let dx = (x - 610) / 540;
    let dy = (y - 605) / 530;
    let rad = atan2(y - 605, x - 610);
    let diff = atan2(sin(rad - 0.78), cos(rad - 0.78));
    let notch = exp(-pow(diff / 0.42, 2)) * 0.19;
    return (dx * dx + dy * dy) < pow(0.985 - notch, 2);
  }

  // Layered marker wood grain bands
  for (let g = 0; g < 220; g++) {
    let baseT = map(g, 0, 219, -520, 520);
    let col = grainPalette[floor(noise(g * 0.18) * grainPalette.length)];
    let isHighlight = (g % 7 === 0);
    if (isHighlight) col = "#d6a77a";
    let w = map(noise(g * 0.3), 0, 1, 0.5, 1.6);
    brush.set("glaze_marker", col, w);

    let pts = [];
    for (let s = -540; s <= 540; s += 28) {
      // Grain runs diagonally at ~ -22 degrees with cathedral arches
      let u = s;
      let cathedral = 38 * sin(s * 0.0055 + noise(g * 0.08) * 4.0)
                    + 18 * cos(s * 0.012 - g * 0.04);
      let v = baseT + cathedral;
      let ang = -22 * (PI / 180);
      let x = 610 + u * cos(ang) - v * sin(ang);
      let y = 605 + u * sin(ang) + v * cos(ang);
      if (insidePalette(x, y)) {
        pts.push([x, y, 0.7 + 0.4 * noise(s * 0.02, g * 0.1)]);
      } else if (pts.length >= 2) {
        safeSpline(pts, 0.4);
        pts = [];
      } else {
        pts = [];
      }
    }
    if (pts.length >= 2) safeSpline(pts, 0.4);
  }

  // Fine dark wood pores, medullary rays, and grain striations with soft_pencil & 2B
  for (let i = 0; i < 420; i++) {
    let gx = random(90, 1120);
    let gy = random(90, 1120);
    if (!insidePalette(gx, gy)) continue;
    let len = random(25, 110);
    let ang = -22 + random(-5, 5) + 8 * sin(gx * 0.005);
    let rad = ang * (PI / 180);
    let c = random() < 0.65 ? "#4a2710" : (random() < 0.5 ? "#331908" : "#d8ad80");
    brush.set("soft_pencil", c, random(0.5, 1.2));
    let p1x = gx - cos(rad) * len * 0.5;
    let p1y = gy - sin(rad) * len * 0.5;
    let p2x = gx + cos(rad) * len * 0.5;
    let p2y = gy + sin(rad) * len * 0.5;
    if (insidePalette(p1x, p1y) && insidePalette(p2x, p2y)) {
      brush.line(p1x, p1y, p2x, p2y);
    }
  }

  // Well-used mixing area stains & scrubbed turpentine washes (batched by color)
  let stains = [
    // Old warm ochre / raw sienna stain in central mixing zone
    { x: 470, y: 590, rx: 190, ry: 145, col: "#b58338", op: 52 },
    { x: 520, y: 510, rx: 165, ry: 120, col: "#c99b49", op: 48 },
    // Ghostly viridian / olive-grey smudge
    { x: 370, y: 540, rx: 145, ry: 110, col: "#5d6e49", op: 45 },
    // Faint rose-terracotta scraped wash near right-center
    { x: 690, y: 540, rx: 150, ry: 115, col: "#9e4738", op: 42 },
    // Pale titanium-turpentine milky haze in center
    { x: 520, y: 575, rx: 175, ry: 125, col: "#d5cbb8", op: 55 }
  ];

  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.35);
  for (let st of stains) {
    brush.noStroke();
    brush.fill(st.col, st.op);
    let pts = [];
    for (let a = 0; a < 360; a += 20) {
      let r = a * (PI / 180);
      let jitter = 0.82 + 0.35 * noise(cos(r) * 1.5 + st.x * 0.01, sin(r) * 1.5 + st.y * 0.01);
      pts.push([
        st.x + cos(r) * st.rx * jitter,
        st.y + sin(r) * st.ry * jitter
      ]);
    }
    drawShapeFromPts(pts, true, 0.4);
  }
  brush.noFill();

  // Scrubbed dry-brush & palette-knife scratches across the mixing zone
  let scratchColors = ["#e2d7c5", "#cbb89d", "#7b8c6a", "#b85d43", "#634024", "#e8dec8"];
  for (let i = 0; i < 165; i++) {
    let sx = randomGaussian(510, 135);
    let sy = randomGaussian(555, 115);
    if (!insidePalette(sx, sy)) continue;
    let ang = random(-55, 35);
    let rad = ang * (PI / 180);
    let len = random(18, 95);
    let col = random(scratchColors);
    brush.set(random() < 0.5 ? "cpencil" : "soft_pencil", col, random(0.6, 1.5));
    brush.line(
      sx - cos(rad) * len * 0.5,
      sy - sin(rad) * len * 0.5,
      sx + cos(rad) * len * 0.5,
      sy + sin(rad) * len * 0.5
    );
  }

  // Palette rim bevel highlight (top-left north-window catchlight) and dark inner rim line
  let topRimPts = [];
  let botRimPts = [];
  for (let i = 0; i < palPts.length; i++) {
    let p = palPts[i];
    let ang = atan2(p[1] - 605, p[0] - 610) * (180 / PI);
    if (ang < -15 || ang > 155) {
      topRimPts.push([p[0] + 2, p[1] + 2, 0.9]);
    } else {
      botRimPts.push([p[0] - 2, p[1] - 2, 0.9]);
    }
  }
  brush.set("cream_marker", "#e8c396", 0.55);
  safeSpline(topRimPts, 0.35);
  brush.set("gloss_pen", "#fff0d8", 0.75);
  safeSpline(topRimPts.slice(10, 52), 0.35);

  brush.set("cream_marker", "#361c0b", 0.65);
  safeSpline(botRimPts, 0.35);

  // -------------------------------------------------------------------------
  // THUMBHOLE (Cutout revealing dark studio tabletop + beveled inner wood wall)
  // -------------------------------------------------------------------------
  let holeOuter = getThumbholeContour(50, 0, 0, 1.05);
  let holeMain = getThumbholeContour(50, 0, 0, 1.0);
  let holeShift = getThumbholeContour(50, 9, 11, 0.98);

  // Recessed wood bevel inside thumbhole (lit on bottom-right, dark on top-left)
  brush.noStroke();
  brush.wash("#3b1f0d", 255);
  drawShapeFromPts(holeOuter, true, 0.35);

  brush.wash("#9e683b", 230);
  drawShapeFromPts(holeMain, true, 0.35);

  // Dark studio tabletop visible through the hole
  brush.wash("#0d0f14", 255);
  drawShapeFromPts(holeShift, true, 0.35);

  // Rim highlight & crust smudges around thumbhole
  brush.set("cream_marker", "#241206", 0.65);
  safeSpline(holeMain.slice(22, 48), 0.35);
  brush.set("gloss_pen", "#e6bc8a", 0.85);
  safeSpline(holeMain.slice(0, 22), 0.35);

  // Old dried paint smears clinging to the thumbhole edge
  let thumbSmears = [
    { a: 0.4, c1: "#8f3428", c2: "#d95b43" },
    { a: 1.1, c1: "#2d5a7b", c2: "#5ba4cf" },
    { a: 3.6, c1: "#8c6d23", c2: "#d4af48" },
    { a: 4.5, c1: "#969a9e", c2: "#e8ecef" }
  ];
  for (let sm of thumbSmears) {
    let tilt = -36 * (PI / 180);
    let lx = 96 * cos(sm.a), ly = 56 * sin(sm.a);
    let sx = 900 + lx * cos(tilt) - ly * sin(tilt);
    let sy = 895 + lx * sin(tilt) + ly * cos(tilt);
    brush.set("cream_marker", sm.c1, 0.9);
    brush.line(sx - 10, sy - 6, sx + 12, sy + 8);
    brush.set("crust_pastel", sm.c2, 0.85);
    brush.line(sx - 8, sy - 7, sx + 9, sy + 5);
  }
}

// ---------------------------------------------------------------------------
// 2. DRIED PAINT CRUSTS ALONG THE PALETTE EDGES
// ---------------------------------------------------------------------------
function drawDriedPaintCrusts() {
  let palPts = getPaletteContour(120);

  // Curated dried crust beds along the upper-left, top, right, and bottom edges
  let crustBeds = [
    // Top-left crusty ochre, olive & buff buildup
    { idxStart: 52, idxEnd: 66, radIn: 36, base: "#6b4c1b", mid: "#a67c2e", hi: "#d9b45b", crk: "#382509" },
    { idxStart: 56, idxEnd: 63, radIn: 52, base: "#3f4f2b", mid: "#637844", hi: "#94ab6f", crk: "#222b15" },
    // Top edge crusty old white, burnt sienna & grey-violet
    { idxStart: 67, idxEnd: 79, radIn: 32, base: "#733622", mid: "#a65235", hi: "#d47c59", crk: "#3d180d" },
    { idxStart: 71, idxEnd: 84, radIn: 45, base: "#7d7970", mid: "#b0aba0", hi: "#dedad0", crk: "#45423b" },
    // Upper-right crusty cerulean-grey, alizarin & yellow ochre
    { idxStart: 85, idxEnd: 97, radIn: 38, base: "#2d4c5e", mid: "#4d778f", hi: "#82b0c9", crk: "#162936" },
    { idxStart: 92, idxEnd: 103, radIn: 34, base: "#5e2228", mid: "#8f3942", hi: "#c2636d", crk: "#330e12" },
    // Right edge crusty Naples/raw umber scabs
    { idxStart: 102, idxEnd: 114, radIn: 35, base: "#6e521f", mid: "#ad8537", hi: "#dfc06d", crk: "#3b290a" },
    // Left-edge dried ultramarine & sap green crusts
    { idxStart: 38, idxEnd: 49, radIn: 34, base: "#213254", mid: "#3b5687", hi: "#6c8cc2", crk: "#10192e" },
    { idxStart: 28, idxEnd: 37, radIn: 30, base: "#4f3a24", mid: "#82613c", hi: "#b58d5d", crk: "#2b1e10" }
  ];

  for (let bed of crustBeds) {
    let patchPts = [];
    let shadowPts = [];
    for (let i = bed.idxStart; i <= bed.idxEnd; i++) {
      let p = palPts[i % palPts.length];
      let ang = atan2(p[1] - 605, p[0] - 610);
      let dIn = 12 + 16 * noise(i * 0.4, bed.radIn);
      let x = p[0] - cos(ang) * dIn;
      let y = p[1] - sin(ang) * dIn;
      patchPts.push([x, y]);
      shadowPts.push([x + 4.5, y + 5.5]);
    }
    for (let i = bed.idxEnd; i >= bed.idxStart; i--) {
      let p = palPts[i % palPts.length];
      let ang = atan2(p[1] - 605, p[0] - 610);
      let dIn = bed.radIn + 28 * noise(i * 0.55 + 10, bed.radIn);
      let x = p[0] - cos(ang) * dIn;
      let y = p[1] - sin(ang) * dIn;
      patchPts.push([x, y]);
      shadowPts.push([x + 4.5, y + 5.5]);
    }

    // Sharp cast shadow under the dried crust slab
    brush.noStroke();
    brush.wash(bed.crk, 165);
    drawShapeFromPts(shadowPts, true, 0.25);

    // Opaque dry base mass of the crust
    brush.wash(bed.base, 235);
    drawShapeFromPts(patchPts, true, 0.25);

    // Textured dry ridges and flaky impasto chunks inside the crust bed
    let cx = 0, cy = 0;
    for (let pt of patchPts) { cx += pt[0]; cy += pt[1]; }
    cx /= patchPts.length;
    cy /= patchPts.length;

    for (let k = 0; k < 28; k++) {
      let pA = random(patchPts);
      let pB = random(patchPts);
      let mx = lerp(pA[0], cx, random(0.1, 0.7)) + random(-12, 12);
      let my = lerp(pA[1], cy, random(0.1, 0.7)) + random(-12, 12);
      let len = random(10, 32);
      let tang = atan2(pB[1] - pA[1], pB[0] - pA[0]) + random(-0.4, 0.4);
      let x1 = mx - cos(tang) * len * 0.5;
      let y1 = my - sin(tang) * len * 0.5;
      let x2 = mx + cos(tang) * len * 0.5;
      let y2 = my + sin(tang) * len * 0.5;

      // Shadow crack on bottom-right of flake
      brush.set("soft_pencil", bed.crk, random(0.7, 1.3));
      brush.line(x1 + 2.5, y1 + 3.0, x2 + 2.5, y2 + 3.0);

      // Dry crusty midtone & highlight on top-left of flake
      brush.set("crust_pastel", k % 3 === 0 ? bed.hi : bed.mid, random(0.6, 1.25));
      brush.line(x1, y1, x2, y2);

      if (k % 4 === 0) {
        brush.set("cpencil", bed.hi, 0.85);
        brush.line(x1 - 1.5, y1 - 1.5, x2 - 1.5, y2 - 1.5);
      }
    }
  }

  // Scattered isolated dry paint crumbs and knife-scraped ridges around the perimeter
  let crumbColors = [
    ["#4a1216", "#b8332a", "#f27463"],
    ["#0c354f", "#1e78ad", "#7cc6f2"],
    ["#6e480b", "#d99b1e", "#fae178"],
    ["#525861", "#9da5b0", "#f0f4f8"],
    ["#2f4722", "#5d8a43", "#a2cc84"]
  ];
  for (let c = 0; c < 85; c++) {
    let idx = floor(random(22, 116));
    let p = palPts[idx % palPts.length];
    let ang = atan2(p[1] - 605, p[0] - 610);
    let distIn = random(18, 90);
    let x = p[0] - cos(ang) * distIn + random(-10, 10);
    let y = p[1] - sin(ang) * distIn + random(-10, 10);
    let pal = random(crumbColors);
    let r = random(4, 14);
    let dir = ang + HALF_PI + random(-0.5, 0.5);

    // Crumb drop shadow
    brush.set("soft_pencil", "#1f1208", 1.1);
    brush.line(
      x - cos(dir) * r + 2.5, y - sin(dir) * r + 3,
      x + cos(dir) * r + 2.5, y + sin(dir) * r + 3
    );
    // Crumb body
    brush.set("cream_marker", pal[1], random(0.35, 0.65));
    brush.line(x - cos(dir) * r, y - sin(dir) * r, x + cos(dir) * r, y + sin(dir) * r);
    // Crisp dry top edge
    brush.set("cpencil", pal[2], 0.85);
    brush.line(
      x - cos(dir) * r * 0.8 - 1.2, y - sin(dir) * r * 0.8 - 1.2,
      x + cos(dir) * r * 0.8 - 1.2, y + sin(dir) * r * 0.8 - 1.2
    );
  }
}

// ---------------------------------------------------------------------------
// 3. CRIMPED ALUMINIUM TUBE WITH ITS CAP OFF
// ---------------------------------------------------------------------------
function drawCrimpedTubeAndCap() {
  push();
  // Tube centered at lower-left of palette, pointing up-right toward the Cerulean coil
  let tx = 275, ty = 855;
  let tubeAngle = -32; // degrees
  translate(tx, ty);
  rotate(tubeAngle);

  // Coordinate system along the tube:
  // u in [-135, +135] is along the tube axis (tail at -135, nozzle at +145)
  // v is perpendicular width (wider at flat crimped tail ±56, tapering to ±36 at shoulder)

  // 1. Cast shadow of the aluminum tube & nozzle on the wooden palette
  // Light is from top-left; in rotated coords, shadow offset is roughly (+8, +16)
  brush.noStroke();
  brush.wash("#241206", 155);
  brush.beginShape(0.2);
  brush.vertex(-132 + 9, -54 + 16);
  brush.vertex(68 + 9, -37 + 16);
  brush.vertex(106 + 9, -11 + 15);
  brush.vertex(138 + 8, -9 + 14);
  brush.vertex(138 + 8, 9 + 14);
  brush.vertex(106 + 9, 11 + 15);
  brush.vertex(68 + 9, 37 + 16);
  brush.vertex(-132 + 9, 54 + 16);
