  brush.wash("#140902", 120);
  brush.beginShape(0.2);
  brush.vertex(-128 + 5, -50 + 9);
  brush.vertex(68 + 5, -35 + 9);
  brush.vertex(106 + 5, -10 + 9);
  brush.vertex(135 + 5, 9 + 9);
  brush.vertex(68 + 5, 35 + 9);
  brush.vertex(-128 + 5, 50 + 9);
