  // Cylindrical + crumpled metallic shading on the exposed aluminum rear half (u: -112 to -12)
  let metalBands = [
    { v1: -50, v2: -34, col: "#cdd6e0", w: 1.1 },
    { v1: -34, v2: -18, col: "#f1f5f9", w: 1.2 }, // bright north-window reflection
    { v1: -18, v2: -4,  col: "#94a3b8", w: 1.1 },
    { v1: -4,  v2: 14,  col: "#334155", w: 1.3 }, // dark core reflection
    { v1: 14,  v2: 32,  col: "#64748b", w: 1.1 },
    { v1: 32,  v2: 48,  col: "#a8825c", w: 1.0 }  // warm wood bounce reflection on underside
  ];
  for (let b of metalBands) {
