  safeSpline([[-98, -16], [-72, -32], [-42, -13]], 0.4);
  brush.set("gloss_pen", "#ffffff", 1.1);
  safeSpline([[-92, -19], [-72, -31], [-48, -16]], 0.4);

  // Dent 2: lower-right crinkle ridge around u = -55, v = +18
