  safeSpline([[-92, 14], [-62, 26], [-28, 12]], 0.4);
  brush.set("gloss_pen", "#e2e8f0", 0.95);
  safeSpline([[-90, 11], [-62, 23], [-30, 9]], 0.4);

  // Soft pencil axial brushing & crinkle shading on aluminum
  for (let i = 0; i < 36; i++) {
    let v = map(i, 0, 35, -48, 48);
    let c = v < -12 ? "#ffffff" : (v < 15 ? "#1e293b" : "#94a3b8");
    brush.set("soft_pencil", c, 0.65);
    brush.line(-110, v, -12, v * 0.83 + 3 * sin(i * 0.7));
  }

  // 3. Double-crimped tail fold at u in [-136, -108]
  let crimpRect = [[-136, -55], [-108, -54], [-108, 54], [-136, 55]];
  brush.noStroke();
  brush.wash("#94a3b8", 255);
  drawShapeFromPts(crimpRect, true, 0.1);

