  brush.set("cream_marker", "#f8fafc", 0.65);
  brush.line(-134, -53, -134, 53);
  brush.line(-121, -53, -121, 53);

  brush.set("cream_marker", "#334155", 0.65);
  brush.line(-126, -53, -126, 53);
  brush.line(-110, -53, -110, 53);

  // Stamped horizontal crimp teeth across the folded end
  for (let v = -50; v <= 50; v += 5.5) {
    brush.set("gloss_pen", "#1e293b", 0.7);
    brush.line(-135, v, -110, v);
    brush.set("gloss_pen", "#ffffff", 0.75);
    brush.line(-135, v - 1.6, -110, v - 1.6);
  }

  // 4. Paper Label Wrapper Band (u in [-14, +64])
  let labelPts = [
    [-14, -42], [25, -39], [64, -36],
