  ];
  brush.noStroke();
  brush.wash("#f5efe0", 255);
  drawShapeFromPts(labelPts, true, 0.15);

  // Cylindrical shading on the cream paper wrapper
  for (let v = -38; v <= 38; v += 3.5) {
    let col = "#f5efe0";
    if (v < -16) col = "#ffffff";
    else if (v > 22) col = "#b89f7d";
    else if (v > 4) col = "#d6ccb8";
    brush.set("cream_marker", col, 0.5);
    brush.line(-13, v * 1.05, 63, v * 0.94);
