  brush.set("rotring", "#1e293b", 0.85);
  brush.line(-10, -40, -10, 41);
  brush.line(60, -35, 60, 35);
  brush.set("rotring", "#b48327", 0.75);
  brush.line(20, -38, 20, 38);
  brush.line(52, -36, 52, 36);

