  // Artist's messy thumb smudge of Cerulean & Cadmium Red on the paper label!
  brush.set("cream_marker", "#0284c7", 0.75);
  safeSpline([[2, 16], [14, 22], [26, 19]], 0.4);
  brush.set("crust_pastel", "#dc2626", 0.65);
  safeSpline([[-6, -24], [6, -28], [15, -22]], 0.4);

  // 5. Conical Aluminum Shoulder (u in [64, 106])
  let shoulderPts = [[64, -36], [106, -12], [106, 12], [64, 36]];
