  brush.line(66, -20, 104, -6);

  // 6. Threaded Aluminum Nozzle (u in [106, 134], v in [-11, +11])
  let nozzlePts = [[106, -11], [134, -9], [134, 9], [106, 11]];
  brush.noStroke();
  brush.wash("#475569", 255);
  drawShapeFromPts(nozzlePts, true, 0.1);

  // Screw threads with crisp dark grooves and pinpoint silver highlights
  for (let u = 110; u <= 131; u += 5.2) {
    brush.set("rotring", "#0f172a", 0.95);
    brush.line(u, -11, u + 1.5, 11);
    brush.set("cream_marker", "#cbd5e1", 0.35);
