  brush.set("cream_marker", "#0096c7", 0.9);
  safeSpline([[133, -4], [143, -2], [147, 2]], 0.5);
  brush.set("cream_marker", "#38bdf8", 0.65);
  safeSpline([[134, -4], [142, -3], [145, 0]], 0.5);
  brush.set("gloss_pen", "#ffffff", 1.1);
  safeSpline([[135, -4], [141, -3], [144, -1]], 0.5);

  pop();

  // -------------------------------------------------------------------------
  // THE CAP OFF (Fluted white plastic cap lying on its side nearby)
  // -------------------------------------------------------------------------
  push();
  translate(405, 978);
