  // Cap body (flared frustum from u = -28 to +26)
  let capPts = [[-28, -16], [24, -21], [27, 0], [24, 21], [-28, 16], [-31, 0]];
  brush.noStroke();
  brush.wash("#cbd5e1", 255);
  drawShapeFromPts(capPts, true, 0.2);

  // Cylindrical shading + longitudinal grip flutes on the cap
  for (let v = -18; v <= 18; v += 4.2) {
