  brush.noStroke();
  brush.wash("#0f172a", 245);
  drawShapeFromPts(capOpen, true, 0.35);

  // Bright plastic lip rim around the opening + smear of cerulean blue paint
  brush.set("gloss_pen", "#f8fafc", 0.95);
  safeSpline(capOpen.slice(4, 11), 0.35);
  brush.set("cream_marker", "#0096c7", 0.55);
  safeSpline([[21, -18], [26, -12], [28, -4]], 0.4);
