  brush.line(23, -15, 26, -9);

  pop();
}

// ---------------------------------------------------------------------------
// 4. HYPERREAL STAR-NOZZLE EXTRUDED OIL PAINT ENGINE
// ---------------------------------------------------------------------------
// Renders a 3D coiled / piped paint extrusion with star-nozzle longitudinal
// flutes, creamy groove shadows, layered marker + soft pencil flanks,
// transverse squeeze ripples, linseed oil halo, drop shadow, and glossy crests.
function renderExtrudedPaintCoil(spineControlPts, palette, options = {}) {
  let numSteps = options.steps || 125;
  let numFlutes = options.numFlutes || 7; // visible star ridges across upper hemisphere
  let numChunks = options.chunks || 13;
  let chatterAmp = options.chatterAmp !== undefined ? options.chatterAmp : 0.045;
  let chatterFreq = options.chatterFreq || 26.0;
  let hasWhippedTip = options.whippedTip !== false;

  // Catmull-Rom / smooth interpolation of 3D spine: [x, y, z, r, twist]
  function sampleSpine(t) {
    let n = spineControlPts.length - 1;
    let ft = constrain(t * n, 0, n - 0.0001);
    let idx = floor(ft);
    let frac = ft - idx;
    let p0 = spineControlPts[max(0, idx - 1)];
    let p1 = spineControlPts[idx];
    let p2 = spineControlPts[min(n, idx + 1)];
    let p3 = spineControlPts[min(n, idx + 2)];

    let out = [];
    for (let k = 0; k < 5; k++) {
      let v0 = p0[k], v1 = p1[k], v2 = p2[k], v3 = p3[k];
      let a0 = -0.5 * v0 + 1.5 * v1 - 1.5 * v2 + 0.5 * v3;
      let a1 = v0 - 2.5 * v1 + 2.0 * v2 - 0.5 * v3;
      let a2 = -0.5 * v0 + 0.5 * v2;
      let a3 = v1;
      out.push(((a0 * frac + a1) * frac + a2) * frac + a3);
    }
    return out;
  }

  // Precompute dense spine samples and tangent frames
  let samples = [];
  for (let i = 0; i <= numSteps; i++) {
    let t = i / numSteps;
    let sp = sampleSpine(t);
    let spNext = sampleSpine(min(1.0, t + 0.008));
    let spPrev = sampleSpine(max(0.0, t - 0.008));

    // 3D foreshortening projection for overhead slightly-tilted camera
    let px = sp[0] - sp[2] * 0.16;
    let py = sp[1] - sp[2] * 0.22;
    let pxNext = spNext[0] - spNext[2] * 0.16;
    let pyNext = spNext[1] - spNext[2] * 0.22;
    let pxPrev = spPrev[0] - spPrev[2] * 0.16;
    let pyPrev = spPrev[1] - spPrev[2] * 0.22;

    let tx = pxNext - pxPrev;
    let ty = pyNext - pyPrev;
    let tLen = sqrt(tx * tx + ty * ty) || 1;
    tx /= tLen;
    ty /= tLen;

    // Cross-section normal in canvas plane
    let nx = -ty;
    let ny = tx;

    // Transverse squeeze ripples along the extrusion
    let ripple = 1.0 + chatterAmp * sin(t * chatterFreq * TWO_PI);

    samples.push({
      t: t,
      x: px,
      y: py,
      rawX: sp[0],
      rawY: sp[1],
      z: sp[2],
      r: sp[3] * ripple,
      twist: sp[4],
      tx: tx,
      ty: ty,
      nx: nx,
      ny: ny,
      rippleSlope: cos(t * chatterFreq * TWO_PI)
    });
  }

  // -------------------------------------------------------------------------
  // PASS A: Linseed Oil Ring & Soft Layered Cast Shadow on the Wood Palette
  // -------------------------------------------------------------------------
  // 1. Subtle darkened wet linseed oil halo soaked into the wood around the base
  for (let i = 0; i <= numSteps; i += 4) {
    let s = samples[i];
    if (s.z < 48) {
      brush.noStroke();
      brush.wash(palette.oilHalo || "#593315", 22);
      brush.circle(s.rawX, s.rawY, s.r * 1.24, 0.18);
    }
  }

  // 2. Multi-layer cast shadow projected along North-Window light vector (+0.48, +0.62)
  for (let shLayer = 3; shLayer >= 1; shLayer--) {
    let spread = shLayer * 4.5;
    let shCol = shLayer === 1 ? "#1a0c04" : "#301809";
    let shOp = shLayer === 1 ? 125 : (shLayer === 2 ? 75 : 42);
    brush.noStroke();
    brush.wash(shCol, shOp);
    for (let i = 0; i <= numSteps; i += 3) {
      let s = samples[i];
      let shX = s.rawX + s.z * 0.42 + 6 + spread * 0.4;
      let shY = s.rawY + s.z * 0.56 + 8 + spread * 0.5;
      brush.circle(shX, shY, max(4, s.r * 0.95 + spread), 0.12);
    }
  }

  // -------------------------------------------------------------------------
  // PASS B: Chunked Painter's Algorithm from Bottom of Coil (t=0) to Peak (t=1)
  // -------------------------------------------------------------------------
  // North-window light direction in 3D: from top-left-front
  let Lx = -0.54, Ly = -0.62, Lz = 0.57;
  // Halfway vector H between Light L and Viewer V=(0, 0, 1) for wet specular highlights
  let Hx = -0.32, Hy = -0.37, Hz = 0.87;

  // Helper to get projected 2D point on cross-section at sample s, flute angle phi, radius mult rm
  function getTubePt(s, phi, rm, pressureVal = 1.0) {
    let sinP = sin(phi);
    let cosP = cos(phi); // vertical elevation on tube cross-section
    let rEff = s.r * rm;
    let x = s.x + s.nx * (rEff * sinP) - (rEff * cosP) * 0.14;
    let y = s.y + s.ny * (rEff * sinP) - (rEff * cosP) * 0.22;
    return [x, y, pressureVal];
  }

  // Helper to evaluate lighting and specular at sample s, angle phi, and facet normal tilt
  function evalLight(s, phi, facetTilt) {
    let effPhi = constrain(phi + facetTilt, -1.48, 1.48);
    let sinP = sin(effPhi);
    let cosP = cos(effPhi);
    // 3D normal vector = sinP * N + cosP * Z + ripple contribution along T
    let rTilt = s.rippleSlope * 0.14;
    let wnx = s.nx * sinP + s.tx * rTilt;
    let wny = s.ny * sinP + s.ty * rTilt;
    let wnz = cosP;
    let nLen = sqrt(wnx * wnx + wny * wny + wnz * wnz) || 1;
    wnx /= nLen; wny /= nLen; wnz /= nLen;

    let diff = wnx * Lx + wny * Ly + wnz * Lz; // in [-1, 1]
    // Warm wood bounce light on lower-right facing flanks
    let bounce = max(0, wnx * 0.5 + wny * 0.6 - wnz * 0.25) * 0.28;
    let specDot = max(0, wnx * Hx + wny * Hy + wnz * Hz);
    let spec = pow(specDot, 13);
    return { diff: diff + bounce * 0.35, bounce: bounce, spec: spec };
  }

  // Pick pigment shade from 7-stop palette based on diffuse lighting
  function pickBodyColor(diffVal, bounceVal) {
    if (diffVal < -0.22) return palette.grooveDark;
    if (diffVal < 0.02) return bounceVal > 0.12 ? palette.bounceTone : palette.shadowFlank;
    if (diffVal < 0.28) return palette.midBody;
    if (diffVal < 0.54) return palette.vividBody;
    if (diffVal < 0.74) return palette.litFlank;
    return palette.brightCrest;
  }

  let chunkLen = numSteps / numChunks;

  for (let c = 0; c < numChunks; c++) {
    let iStart = max(0, floor(c * chunkLen) - 1);
    let iEnd = min(numSteps, ceil((c + 1) * chunkLen) + 1);

    // 1. Solid opaque undertone mass for this chunk (blocks out wood grain underneath)
    // Also tuck an ambient occlusion dark rim under the bottom-right edge of the chunk
    let aoPts = [];
    for (let i = iStart; i <= iEnd; i++) {
      let s = samples[i];
      aoPts.push(getTubePt(s, 1.38, 1.02, 0.9));
    }
    brush.set("cream_marker", palette.grooveAO, 0.75);
    safeSpline(aoPts, 0.45);

    // Solid base fill along the chunk width using overlapping thick marker bands
    for (let band = -0.82; band <= 0.82; band += 0.32) {
      let bPts = [];
      let avgR = 0;
      for (let i = iStart; i <= iEnd; i++) {
        let s = samples[i];
        avgR += s.r;
        bPts.push(getTubePt(s, band * 1.35, 0.92, 1.0));
      }
      avgR /= (iEnd - iStart + 1);
      let bandCol = band > 0.25 ? palette.shadowFlank : (band < -0.2 ? palette.vividBody : palette.midBody);
      brush.set("cream_marker", bandCol, max(0.45, avgR * 0.042));
      safeSpline(bPts, 0.45);
    }

    // 2. Render each Star-Nozzle Flute across the upper cross-section
    // Draw outer flutes first (|phi| near PI/2) and central top flutes last (phi near 0)
    let fluteIndices = [];
    for (let f = 0; f < numFlutes; f++) fluteIndices.push(f);
    fluteIndices.sort((a, b) => abs(b - (numFlutes - 1) / 2) - abs(a - (numFlutes - 1) / 2));

    let dPhi = 2.68 / numFlutes; // angular span of each star flute across visible hemisphere

    for (let f of fluteIndices) {
      let basePhi = -1.34 + (f + 0.5) * dPhi;

      // Collect points along this chunk for:
      // - Left valley (groove): phi - 0.48 * dPhi, r = 0.80
      // - Face A (left flank):  phi - 0.22 * dPhi, r = 0.94
      // - Ridge Crest:          phi,               r = 1.06
      // - Face B (right flank): phi + 0.22 * dPhi, r = 0.94
      // - Right valley:         phi + 0.48 * dPhi, r = 0.80
      let valleyLPts = [];
      let valleyRPts = [];
      let faceAPts = [];
      let faceBPts = [];
      let crestPts = [];
      let specPts = [];

      let sumDiffA = 0, sumDiffB = 0, sumBounceA = 0, sumBounceB = 0;
      let sumSpec = 0, avgR = 0, count = 0;

      for (let i = iStart; i <= iEnd; i++) {
        let s = samples[i];
        let phi = basePhi + s.twist;
        if (phi < -1.48 || phi > 1.48) continue;

        let edgeAtten = cos(phi * 0.85); // foreshortening attenuation near edges
        let wScale = constrain(edgeAtten * (s.r / 38), 0.25, 1.35);

        valleyLPts.push(getTubePt(s, phi - 0.48 * dPhi, 0.81, wScale));
        valleyRPts.push(getTubePt(s, phi + 0.48 * dPhi, 0.81, wScale));
        faceAPts.push(getTubePt(s, phi - 0.21 * dPhi, 0.94, wScale));
        faceBPts.push(getTubePt(s, phi + 0.21 * dPhi, 0.94, wScale));
        crestPts.push(getTubePt(s, phi, 1.06, wScale));

        // Evaluate lighting on Face A (tilted -0.52 rad), Face B (tilted +0.52 rad), and Crest
        let lA = evalLight(s, phi, -0.52);
        let lB = evalLight(s, phi, +0.52);
        let lC = evalLight(s, phi, 0.0);

        sumDiffA += lA.diff;
        sumDiffB += lB.diff;
        sumBounceA += lA.bounce;
        sumBounceB += lB.bounce;
        sumSpec += lC.spec;
        avgR += s.r;
        count++;

        if (lC.spec > 0.26) {
          let spP = map(lC.spec, 0.26, 1.0, 0.3, 1.35);
          specPts.push(getTubePt(s, phi - 0.03 * dPhi, 1.07, spP));
        }
      }

      if (count < 2) continue;
      let meanDiffA = sumDiffA / count;
      let meanDiffB = sumDiffB / count;
      let meanBounceA = sumBounceA / count;
      let meanBounceB = sumBounceB / count;
      let meanSpec = sumSpec / count;
      avgR /= count;

      let colA = pickBodyColor(meanDiffA, meanBounceA);
      let colB = pickBodyColor(meanDiffB, meanBounceB);
      let markerW = constrain(avgR * 0.022, 0.28, 1.15);

      // (a) Layered marker flanks (Face A & Face B)
      brush.set("cream_marker", colA, markerW);
      safeSpline(faceAPts, 0.45);

      brush.set("cream_marker", colB, markerW);
      safeSpline(faceBPts, 0.45);

      // (b) Creamy shadows in the star-nozzle grooves (valleys)
      let grooveCol = (meanDiffA + meanDiffB) * 0.5 < 0.05 ? palette.grooveAO : palette.grooveDark;
      brush.set("cream_marker", grooveCol, markerW * 0.58);
      safeSpline(valleyLPts, 0.45);
      if (f === numFlutes - 1) {
        safeSpline(valleyRPts, 0.45);
      }

      // Soft pencil darkening & creamy blending inside the groove
      brush.set("soft_pencil", palette.grooveAO, constrain(avgR * 0.025, 0.45, 1.15));
      safeSpline(valleyLPts, 0.45);

      // (c) Soft pencil modelling along the lit and shaded flanks
      let pencilColA = meanDiffA > 0.35 ? palette.brightCrest : palette.shadowFlank;
      let pencilColB = meanDiffB > 0.35 ? palette.vividBody : palette.grooveDark;
      brush.set("soft_pencil", pencilColA, constrain(avgR * 0.024, 0.4, 1.1));
      safeSpline(faceAPts, 0.45);
      brush.set("cpencil", pencilColB, constrain(avgR * 0.022, 0.4, 1.0));
      safeSpline(faceBPts, 0.45);

      // Transverse buttery squeeze striations across the flute flank
      if (avgR > 16) {
        for (let i = iStart + 1; i < iEnd; i += 3) {
          let s = samples[i];
          let phi = basePhi + s.twist;
          if (abs(phi) > 1.15) continue;
          let pVal = getTubePt(s, phi - 0.38 * dPhi, 0.86);
          let pCr = getTubePt(s, phi, 1.06);
          let pValR = getTubePt(s, phi + 0.38 * dPhi, 0.86);
          brush.set("soft_pencil", colA, 0.55);
          brush.line(pVal[0], pVal[1], pCr[0], pCr[1]);
          brush.set("soft_pencil", colB, 0.5);
          brush.line(pCr[0], pCr[1], pValR[0], pValR[1]);
        }
      }

      // (d) Sharp Extruded Ridge Crest
      let crestCol = (meanDiffA > 0.25 || meanDiffB > 0.25) ? palette.brightCrest : palette.litFlank;
      brush.set("cream_marker", crestCol, markerW * 0.48);
      safeSpline(crestPts, 0.45);

      brush.set("soft_pencil", meanSpec > 0.18 ? palette.subSpec : crestCol, constrain(avgR * 0.025, 0.5, 1.2));
      safeSpline(crestPts, 0.45);

      // (e) Glossy Wet Specular Crests along the sharp star ridges!
      if (specPts.length >= 2) {
        // Sub-specular glow ribbon
        brush.set("cream_marker", palette.subSpec, markerW * 0.36);
        safeSpline(specPts, 0.45);

        // Razor-sharp wet white specular glint
        brush.set("gloss_pen", palette.specWhite || "#ffffff", constrain(avgR * 0.032, 0.65, 1.45));
        safeSpline(specPts, 0.45);
      }
    }
  }

  // -------------------------------------------------------------------------
  // PASS C: Central Whipped Star Peak / Nozzle Pull-Off Tip at t = 1
  // -------------------------------------------------------------------------
  if (hasWhippedTip) {
    let tipS = samples[numSteps];
    let prevS = samples[max(0, numSteps - 8)];
    let hookX = tipS.x + tipS.tx * 14 - 5;
    let hookY = tipS.y + tipS.ty * 10 - 9;

    // Converging star flutes into the pinched hook peak
    for (let f = 0; f < numFlutes; f++) {
      let phi = -1.2 + (f / (numFlutes - 1)) * 2.4 + prevS.twist;
      let pStart = getTubePt(prevS, phi, 0.95, 0.9);
      let pMid = getTubePt(tipS, phi * 0.4, 0.75, 0.7);
      let col = phi < 0.1 ? palette.brightCrest : palette.shadowFlank;
      brush.set("cream_marker", col, 0.38);
      safeSpline([pStart, pMid, [hookX, hookY, 0.2]], 0.45);
      brush.set("soft_pencil", phi < 0 ? palette.subSpec : palette.grooveDark, 0.65);
      safeSpline([pStart, pMid, [hookX, hookY, 0.2]], 0.45);
    }
    // Blazing wet specular catchlight right on the whipped peak curl
    brush.set("gloss_pen", "#ffffff", 1.3);
    safeSpline([
      [prevS.x - 4, prevS.y - 5, 0.8],
      [tipS.x - 2, tipS.y - 4, 1.2],
      [hookX, hookY, 0.3]
    ], 0.45);
  }
}

// ---------------------------------------------------------------------------
// 5. PALETTE KNIFE SWIPE & MARBLED BUTTERCREAM SMEAR IN MIXING ZONE
// ---------------------------------------------------------------------------
function drawButteryKnifeSwipe() {
  // A luscious palette-knife drag where Titanium White, Naples Yellow & a kiss of
  // Cerulean Blue and Cadmium Red were pressed flat and sheared across the wood,
  // leaving rolled beads of displaced paint along the borders.
  let swipeSpine = [
    [405, 625], [455, 575], [515, 535], [575, 505], [630, 485]
  ];

  // 1. Cast shadow under the thick rolled edges of the knife swipe
  brush.set("cream_marker", "#291507", 1.2);
  safeSpline(swipeSpine.map(p => [p[0] + 6, p[1] + 34, 0.9]), 0.45);

  // 2. Sheared flat buttery ribbons inside the knife track
  let ribbons = [
    { off: -22, col: "#fef08a", w: 1.15 }, // Naples yellow upper ribbon
    { off: -12, col: "#fde047", w: 1.25 },
    { off: -2,  col: "#f8fafc", w: 1.35 }, // Creamy Titanium White core
    { off: 8,   col: "#e2e8f0", w: 1.20 },
    { off: 16,  col: "#38bdf8", w: 0.95 }, // Vein of Cerulean Blue
    { off: 23,  col: "#0284c7", w: 0.85 },
    { off: -18, col: "#ff4500", w: 0.55 }  // Streak of Cadmium Red
  ];

  for (let rb of ribbons) {
    let pts = swipeSpine.map((p, idx) => [
      p[0] + rb.off * 0.55,
      p[1] + rb.off + 4 * sin(idx * 1.2),
      idx === 4 ? 0.4 : 1.0
    ]);
    brush.set("cream_marker", rb.col, rb.w);
    safeSpline(pts, 0.45);
    brush.set("soft_pencil", rb.col, 0.85);
    safeSpline(pts, 0.45);
  }

  // 3. Displaced rolled paint bead along the top edge and bottom edge of the knife blade
  let topBead = swipeSpine.map((p, i) => [p[0] - 14, p[1] - 25 + 3 * cos(i), 0.95]);
  let botBead = swipeSpine.map((p, i) => [p[0] + 12, p[1] + 27 - 3 * sin(i), 0.95]);

  // Top bead: shadow groove + lit Naples yellow crest + specular line
  brush.set("soft_pencil", "#a16207", 1.1);
  safeSpline(topBead.map(p => [p[0] + 2, p[1] + 4, p[2]]), 0.45);
  brush.set("cream_marker", "#fef9c3", 0.65);
  safeSpline(topBead, 0.45);
  brush.set("gloss_pen", "#ffffff", 1.05);
  safeSpline(topBead.slice(0, 4), 0.45);

  // Bottom bead: shadow groove + cerulean/white rolled ridge + specular line
  brush.set("soft_pencil", "#0c4a6e", 1.1);
  safeSpline(botBead.map(p => [p[0] + 3, p[1] + 4, p[2]]), 0.45);
  brush.set("cream_marker", "#7dd3fc", 0.65);
  safeSpline(botBead, 0.45);
  brush.set("gloss_pen", "#ffffff", 0.95);
  safeSpline(botBead.slice(1, 4), 0.45);
}

// ---------------------------------------------------------------------------
// 6. THE FOUR HERO OIL PAINT EXTRUSIONS (TITANIUM WHITE, NAPLES YELLOW,
//    CADMIUM RED, CERULEAN BLUE)
// ---------------------------------------------------------------------------
function drawAllFreshPaintCoils() {
  // -------------------------------------------------------------------------
  // COLOR PALETTES FOR THE FOUR HERO PIGMENTS
  // -------------------------------------------------------------------------
  const TITANIUM_WHITE = {
    grooveAO:    "#5b6b7f", // cool slate-blue deep crevice
    grooveDark:  "#8496ab", // creamy cool north-light groove shadow
    shadowFlank: "#b3c2d4", // soft blue-grey shaded flank
    bounceTone:  "#d9cfc1", // warm wood bounce on lower flanks
    midBody:     "#dce5f0", // rich titanium body
    vividBody:   "#eef3f8", // luminous cool-ivory white
    litFlank:    "#f8fafc", // creamy lit slope
    brightCrest: "#ffffff", // pure titanium ridge
    subSpec:     "#ffffff",
    specWhite:   "#ffffff",
    oilHalo:     "#633a18"
  };

  const NAPLES_YELLOW = {
    grooveAO:    "#663a06", // deep caramel-ochre groove crevice
    grooveDark:  "#96580e", // rich warm ochre shadow
    shadowFlank: "#c47f0a", // golden-amber shaded flank
    bounceTone:  "#d97706", // warm honey bounce
    midBody:     "#eab308", // saturated buttery yellow
    vividBody:   "#facc15", // vivid luscious Naples yellow
    litFlank:    "#fde047", // bright sunny pastry cream
    brightCrest: "#fef08a", // pale lemon-custard ridge
    subSpec:     "#fef9c3", // glossy cream sheen
    specWhite:   "#ffffff",
    oilHalo:     "#5e3614"
  };

  const CADMIUM_RED = {
    grooveAO:    "#38050b", // abyssal claret-burgundy crevice
    grooveDark:  "#6e0b16", // deep crimson groove shadow
    shadowFlank: "#a31221", // rich cadmium-alizarin shaded flank
    bounceTone:  "#c81e2b", // warm glowing crimson bounce
    midBody:     "#dc2626", // pure saturated cadmium red
    vividBody:   "#ff2414", // blazing scarlet-vermilion
    litFlank:    "#ff4d2e", // fiery cadmium red-light
    brightCrest: "#ff7a59", // luminous coral-vermilion ridge
    subSpec:     "#ffb8a8", // wet glossy pink-salmon sheen
    specWhite:   "#fff5f5",
    oilHalo:     "#4f2810"
  };

  const CERULEAN_BLUE = {
    grooveAO:    "#042038", // deep Prussian-marine crevice
    grooveDark:  "#073d63", // rich deep cerulean groove shadow
    shadowFlank: "#036196", // saturated cobalt-cerulean flank
    bounceTone:  "#087ea8", // warm teal-tinted wood bounce
    midBody:     "#0088cc", // pure vivid cerulean blue
    vividBody:   "#00a6ed", // electric sky-cerulean
    litFlank:    "#38bdf8", // luminous cyan-blue slope
    brightCrest: "#7dd3fc", // bright icy sky ridge
    subSpec:     "#bae6fd", // wet glacier-blue sheen
    specWhite:   "#f0f9ff",
    oilHalo:     "#47260f"
  };

  // Helper to generate a spiral rosette control spine: [x, y, z, r, twist]
  function buildRosetteSpine(cx, cy, outerR, baseTubeR, turns, startDeg, tailPts = []) {
    let pts = [];
    for (let tp of tailPts) pts.push(tp);
    let numCtrl = 22;
    for (let i = 0; i <= numCtrl; i++) {
      let u = i / numCtrl;
      let ang = (startDeg + u * turns * 360) * (PI / 180);
      // Spiral radius tightens from outerR to 0 at the central peak
      let loopR = outerR * pow(1.0 - u, 0.88);
      let x = cx + cos(ang) * loopR;
      let y = cy + sin(ang) * loopR * 0.92;
      // Elevation climbs as the rosette coils on top of itself
      let z = 12 + 88 * pow(u, 1.15);
      // Tube cross-section stays fat through the body and tapers at the whipped tip
      let r = baseTubeR * (1.0 - 0.78 * pow(u, 2.2));
      let twist = u * 1.45;
      pts.push([x, y, z, max(5, r), twist]);
    }
    return pts;
  }

  // -------------------------------------------------------------------------
  // 1. TITANIUM WHITE ROSETTE (Upper-Left at 355, 325)
  // Fat double-tiered buttercream star rosette with a central whipped peak
  // -------------------------------------------------------------------------
  let whiteTail = [
    [255, 365, 8, 34, -0.2],
    [275, 405, 11, 41, -0.1]
  ];
  let whiteSpine = buildRosetteSpine(355, 325, 88, 43, 2.15, 145, whiteTail);
  renderExtrudedPaintCoil(whiteSpine, TITANIUM_WHITE, {
    steps: 135,
    numFlutes: 7,
    chunks: 14,
    chatterAmp: 0.04,
    chatterFreq: 28
  });

  // -------------------------------------------------------------------------
  // 2. NAPLES YELLOW SERPENTINE COIL & CROWN ROSETTE (Upper-Right at 695, 275)
  // Fat piped S-wave that coils back over itself into a high pastry rosette
  // -------------------------------------------------------------------------
  let naplesTail = [
    [545, 295, 8, 32, -0.35],
    [590, 240, 12, 39, -0.20],
    [655, 220, 16, 42, -0.05]
  ];
  let naplesSpine = buildRosetteSpine(705, 285, 82, 41, 1.85, -75, naplesTail);
  renderExtrudedPaintCoil(naplesSpine, NAPLES_YELLOW, {
    steps: 135,
    numFlutes: 7,
    chunks: 14,
    chatterAmp: 0.045,
    chatterFreq: 26
  });

  // -------------------------------------------------------------------------
  // 3. CADMIUM RED VOLUPTUOUS COIL & ROSETTE (Center-Right at 875, 545)
  // Luscious scarlet-vermilion coil with a sweeping entry tail and towering peak
  // -------------------------------------------------------------------------
  let redTail = [
    [745, 605, 9, 34, -0.3],
    [775, 645, 13, 42, -0.15],
    [835, 650, 17, 45, 0.0]
  ];
  let redSpine = buildRosetteSpine(875, 545, 92, 45, 2.05, 80, redTail);
  renderExtrudedPaintCoil(redSpine, CADMIUM_RED, {
    steps: 140,
    numFlutes: 7,
    chunks: 15,
    chatterAmp: 0.05,
    chatterFreq: 30
  });

  // -------------------------------------------------------------------------
  // 4. CERULEAN BLUE EXTRUDED FIGURE-8 COIL & ROSETTE (Lower-Center at 635, 795)
  // Freshly squeezed from the open aluminum tube nearby!
  // -------------------------------------------------------------------------
  let ceruleanSpine = [
    // Starts right near the open tube nozzle at (415, 765)
    [418, 768, 7,  20, -0.5],
    [455, 748, 10, 29, -0.35],
    [508, 755, 13, 36, -0.2],
    [555, 805, 16, 40, -0.05],
    [615, 865, 19, 43, 0.1],
    [695, 860, 23, 44, 0.25],
    [735, 795, 28, 44, 0.4],
    [705, 720, 35, 43, 0.55],
    [625, 705, 43, 42, 0.7],
    // Climbs on top of its own loop into a fat rosette crown
    [565, 755, 53, 40, 0.88],
    [585, 825, 63, 37, 1.05],
    [655, 825, 73, 33, 1.22],
    [675, 765, 82, 27, 1.38],
    [630, 750, 90, 19, 1.55],
    [620, 778, 97, 8,  1.72]
  ];
  renderExtrudedPaintCoil(ceruleanSpine, CERULEAN_BLUE, {
    steps: 145,
    numFlutes: 7,
    chunks: 15,
    chatterAmp: 0.048,
    chatterFreq: 32
  });

  // -------------------------------------------------------------------------
  // 5. SMALLER PIPED SATELLITE DOLLOPS (Extra tactile richness)
  // -------------------------------------------------------------------------
  // Plump mini-rosette of Cadmium Red-Orange near the mixing swipe (525, 445)
  let miniRedSpine = buildRosetteSpine(525, 440, 36, 24, 1.35, 30, [
    [480, 455, 7, 20, -0.15]
  ]);
  renderExtrudedPaintCoil(miniRedSpine, CADMIUM_RED, {
    steps: 65,
    numFlutes: 6,
    chunks: 8,
    chatterAmp: 0.04,
    chatterFreq: 18
  });

  // Plump piped curl of Naples Yellow beside the Titanium White (285, 515)
  let miniYellowSpine = buildRosetteSpine(285, 515, 38, 25, 1.4, -40, [
    [245, 545, 7, 21, -0.15]
  ]);
  renderExtrudedPaintCoil(miniYellowSpine, NAPLES_YELLOW, {
    steps: 65,
    numFlutes: 6,
    chunks: 8,
    chatterAmp: 0.04,
    chatterFreq: 18
  });
}

// ---------------------------------------------------------------------------
// 7. FINAL HYPERREAL MICRO-INCIDENTS & SPECULAR SPARKLE PASS
// ---------------------------------------------------------------------------
function drawFinalHyperrealPolish() {
  // Pinpoint north-window windowpane reflections on the highest wet paint peaks
  let wetPeaks = [
    // Titanium White peak & upper-left crest glints
    { x: 350, y: 298, dx: 12, dy: -6, w: 1.5 },
    { x: 315, y: 272, dx: 18, dy: -8, w: 1.35 },
    { x: 295, y: 315, dx: 10, dy: 14, w: 1.25 },
    // Naples Yellow peak & serpentine crest glints
    { x: 700, y: 258, dx: 14, dy: -5, w: 1.45 },
    { x: 662, y: 232, dx: 20, dy: -4, w: 1.35 },
    { x: 595, y: 232, dx: 16, dy: -7, w: 1.25 },
    // Cadmium Red peak & outer coil glints
    { x: 870, y: 518, dx: 14, dy: -7, w: 1.5 },
    { x: 830, y: 482, dx: 22, dy: -6, w: 1.35 },
    { x: 805, y: 530, dx: 8,  dy: 18, w: 1.25 },
    // Cerulean Blue peak & figure-8 loop glints
    { x: 616, y: 748, dx: 15, dy: -6, w: 1.5 },
    { x: 582, y: 718, dx: 20, dy: -5, w: 1.35 },
    { x: 472, y: 738, dx: 18, dy: 4,  w: 1.25 }
  ];

  for (let pk of wetPeaks) {
    brush.set("gloss_pen", "#ffffff", pk.w);
    safeSpline([
      [pk.x - pk.dx * 0.5, pk.y - pk.dy * 0.5, 0.4],
      [pk.x, pk.y, 1.3],
      [pk.x + pk.dx * 0.5, pk.y + pk.dy * 0.5, 0.4]
    ], 0.4);
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Studio table, oiled wooden palette, wood grain, stains & thumbhole
  drawStudioAndPaletteBase();

  // 2. Crusty dried oil paint accumulations around the palette perimeter
  drawDriedPaintCrusts();

  // 3. Buttery palette-knife swipe in the mixing zone
  drawButteryKnifeSwipe();

  // 4. Crimped aluminum paint tube and its unscrewed fluted cap
  drawCrimpedTubeAndCap();

  // 5. Fat, star-nozzle extruded coils & rosettes of Titanium White,
  //    Naples Yellow, Cadmium Red, and Cerulean Blue
  drawAllFreshPaintCoils();

  // 6. Final wet north-window specular catchlights
  drawFinalHyperrealPolish();

  noLoop();
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1127);
  noiseSeed(1127);

