// ---------------------------------------------------------------------------
// GEOMETRY & POLYGON HELPERS
// ---------------------------------------------------------------------------
function drawPolyFill(pts, col, alpha, bleed = 0.15, tex = 0.4, border = 0.25, curv = 0.3) {
  brush.noStroke();
  brush.noWash();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawPolyWash(pts, col, alpha, curv = 0.25) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function makeBlobPoints(cx, cy, rx, ry, rotDeg, n = 16, irreg = 0.08) {
  let pts = [];
  let ca = cos(rotDeg);
  let sa = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let rMod = 1 + random(-irreg, irreg);
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

