// ---------------------------------------------------------------------------
// 3. MILLET STALKS, LEAVES & PANICLES ENGINE
// ---------------------------------------------------------------------------
function evalQuadBezier(p0, p1, p2, t) {
  let u = 1 - t;
  return [
    u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0],
    u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]
  ];
}

function evalCubicBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  return [
    u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
    u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1]
  ];
}

function drawMilletStalk(p0, p1, p2, p3, baseThick, tipThick, nodesCount = 5) {
  let steps = 28;
  let leftEdge = [];
  let rightEdge = [];
  let centerPts = [];
  let normals = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalCubicBezier(p0, p1, p2, p3, t);
    let ptNext = evalCubicBezier(p0, p1, p2, p3, min(1, t + 0.02));
    let dx = ptNext[0] - pt[0];
    let dy = ptNext[1] - pt[1];
    let d = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / d;
    let ny = dx / d;
    let w = lerp(baseThick, tipThick, pow(t, 0.85)) * 0.5;

    // Slight swelling at culm nodes
    for (let n = 1; n < nodesCount; n++) {
      let nt = n / nodesCount;
      if (abs(t - nt) < 0.028) {
        w *= 1.22;
      }
    }

    centerPts.push(pt);
    normals.push([nx, ny, w]);
    leftEdge.push([pt[0] + nx * w, pt[1] + ny * w]);
    rightEdge.push([pt[0] - nx * w, pt[1] - ny * w]);
  }

  let poly = leftEdge.concat([...rightEdge].reverse());

  // Straw / ochre base wash + burnt sienna & pale azurite shading
  drawPolyWash(poly, "#D4A859", 185, 0.15);

  // Inner highlight core along the stalk
  brush.set("shaft_gouache", "#F2DFB6", 0.9);
  let hlPts = centerPts.map((p, idx) => [
    p[0] + normals[idx][0] * normals[idx][2] * 0.25,
    p[1] + normals[idx][1] * normals[idx][2] * 0.25,
    lerp(0.9, 0.3, idx / steps)
  ]);
  brush.spline(hlPts, 0.4);

  // Pale azurite / malachite cool mineral tint on shadow side
  brush.set("mineral_wash", "#588C83", 0.55);
  let shPts = centerPts.map((p, idx) => [
    p[0] - normals[idx][0] * normals[idx][2] * 0.35,
    p[1] - normals[idx][1] * normals[idx][2] * 0.35,
    lerp(0.8, 0.25, idx / steps)
  ]);
  brush.spline(shPts, 0.4);

  // Crisp hair-fine ink outlines on both margins of the culm
  brush.set("gongbi_ink", "#22150C", 0.85);
  brush.spline(leftEdge.map((p, i) => [p[0], p[1], lerp(0.9, 0.35, i / steps)]), 0.35);
  brush.spline(rightEdge.map((p, i) => [p[0], p[1], lerp(0.95, 0.4, i / steps)]), 0.35);

  // Culm nodes (joints) & dry leaf sheaths
  for (let n = 1; n < nodesCount; n++) {
    let idx = int((n / nodesCount) * steps);
    let lp = leftEdge[idx];
    let rp = rightEdge[idx];
    brush.set("gongbi_ink", "#1A0F08", 1.0);
    brush.line(lp[0], lp[1], rp[0], rp[1]);
    brush.set("mineral_wash", "#7D3716", 0.65);
    brush.line(lp[0], lp[1] + 2, rp[0], rp[1] + 2);
  }
}

function drawMilletLeaf(p0, p1, p2, p3, maxWidth, tone = "ochre", brokenTip = false) {
  let steps = 26;
  let leftEdge = [];
  let rightEdge = [];
  let midRib = [];

  // Optional twist point along leaf for 3D ribbon turn
  let twistT = random(0.55, 0.78);

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalCubicBezier(p0, p1, p2, p3, t);
    let ptNext = evalCubicBezier(p0, p1, p2, p3, min(1, t + 0.02));
    let dx = ptNext[0] - pt[0];
    let dy = ptNext[1] - pt[1];
    let d = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / d;
    let ny = dx / d;

    // Leaf width profile: narrow sheath base -> broad belly -> sharp acuminate tip
    let profile = sin(pow(t, 0.72) * 180);
    if (brokenTip && t > 0.88) profile = max(0.18, profile);

    // Subtle pinch where leaf twists in space
    let twistFactor = 1.0 - 0.55 * exp(-pow((t - twistT) / 0.11, 2));
    let w = maxWidth * 0.5 * profile * twistFactor;

    // Slight insect notch
    if (abs(t - 0.44) < 0.035) w *= 0.65;

    midRib.push([pt[0], pt[1], w]);
    leftEdge.push([pt[0] + nx * w, pt[1] + ny * w]);
    rightEdge.push([pt[0] - nx * w, pt[1] - ny * w]);
  }

  let poly = leftEdge.concat([...rightEdge].reverse());

  // Mineral washes on the leaf blade
  let baseCol = "#C8913D";
  let tipCol = "#8E3D19";
  let coolCol = "#69989C";
  if (tone === "malachite") {
    baseCol = "#5C916B";
    tipCol = "#B87E32";
  } else if (tone === "azurite") {
    baseCol = "#729BA3";
    tipCol = "#A46B2E";
  } else if (tone === "sienna") {
    baseCol = "#9C4A21";
    tipCol = "#5E2B14";
  }

  drawPolyFill(poly, baseCol, 52, 0.14, 0.45, 0.35, 0.15);
  drawPolyWash(poly, baseCol, 135, 0.15);

  // Distal half burnt sienna / autumn blight wash
  let tipPoly = leftEdge.slice(12).concat([...rightEdge.slice(12)].reverse());
  drawPolyFill(tipPoly, tipCol, 48, 0.18, 0.5, 0.35, 0.15);

  // Cool pale azurite underside turn beyond twistT
  let turnIdx = int(twistT * steps);
  if (turnIdx < steps - 3) {
    let turnPoly = leftEdge.slice(turnIdx).concat([...rightEdge.slice(turnIdx)].reverse());
    drawPolyWash(turnPoly, coolCol, 90, 0.15);
  }

  // Parallel longitudinal leaf veins in fine diluted ink
  for (let v of [-0.55, 0.55]) {
    let veinPts = [];
    for (let i = 1; i < steps; i++) {
      let t = i / steps;
      let lp = leftEdge[i];
      let rp = rightEdge[i];
      let vx = lerp(lp[0], rp[0], 0.5 + v * 0.5);
      let vy = lerp(lp[1], rp[1], 0.5 + v * 0.5);
      veinPts.push([vx, vy, lerp(0.7, 0.2, t)]);
    }
    brush.set("gongbi_barb", "#4A2A15", 0.75);
    brush.spline(veinPts, 0.35);
  }

  // Luminous cream-ochre midrib + crisp ink outline
  brush.set("shaft_gouache", "#F0DEC0", 0.75);
  brush.spline(midRib.map((p, i) => [p[0], p[1], lerp(0.95, 0.15, i / steps)]), 0.35);

  brush.set("gongbi_ink", "#1E120A", 0.85);
  brush.spline(midRib.map((p, i) => [p[0], p[1], lerp(0.8, 0.2, i / steps)]), 0.35);
  brush.spline(leftEdge.map((p, i) => [p[0], p[1], lerp(0.85, 0.3, i / steps)]), 0.35);
  brush.spline(rightEdge.map((p, i) => [p[0], p[1], lerp(0.85, 0.3, i / steps)]), 0.35);

  // Dry blight spots along leaf blade
  for (let s = 0; s < 7; s++) {
    let idx = int(random(5, steps - 3));
    let f = random(0.25, 0.75);
    let sx = lerp(leftEdge[idx][0], rightEdge[idx][0], f);
    let sy = lerp(leftEdge[idx][1], rightEdge[idx][1], f);
    brush.set("grain_dot", random() < 0.5 ? "#54220D" : "#24130B", random(0.5, 0.95));
    brush.line(sx, sy, sx + random(0.8, 2.2), sy + random(-0.8, 0.8));
  }
}

function drawMilletPanicle(p0, p1, p2, maxRadius = 22, malachiteRatio = 0.42) {
  let steps = 32;
  let spine = [];
  let normals = [];
  let hullLeft = [];
  let hullRight = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalQuadBezier(p0, p1, p2, t);
    let ptNext = evalQuadBezier(p0, p1, p2, min(1, t + 0.025));
    let dx = ptNext[0] - pt[0];
    let dy = ptNext[1] - pt[1];
    let d = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / d;
    let ny = dx / d;

    // Cylindrical-tapering foxtail millet panicle silhouette with lobular bulges
    let env = sin(pow(t, 0.68) * 180);
    let lobe = 0.85 + 0.18 * sin(t * 360 * 6.5);
    let r = maxRadius * env * lobe;

    spine.push([pt[0], pt[1], r, atan2(dy, dx)]);
    normals.push([nx, ny]);
    hullLeft.push([pt[0] + nx * r, pt[1] + ny * r]);
    hullRight.push([pt[0] - nx * r, pt[1] - ny * r]);
  }

  let hullPoly = hullLeft.concat([...hullRight].reverse());

  // 1. Mineral under-wash for the panicle mass (warm straw-ochre + burnt sienna core + malachite)
  drawPolyFill(hullPoly, "#C9963E", 58, 0.22, 0.55, 0.35, 0.2);
  drawPolyFill(hullPoly, "#7B451B", 38, 0.15, 0.5, 0.3, 0.2);
  drawPolyFill(hullPoly, "#4F8C67", 32, 0.2, 0.45, 0.25, 0.2);

  // 2. Central woody rachis (stem inside the spike)
  brush.set("gongbi_ink", "#3B2212", 0.9);
  brush.spline(spine.map((p, i) => [p[0], p[1], lerp(0.9, 0.2, i / steps)]), 0.35);

  // 3. Fine foxtail bristles (setae) radiating between the spikelets
  for (let i = 1; i < steps; i++) {
    let sp = spine[i];
    let nx = normals[i][0];
    let ny = normals[i][1];
    let r = sp[2];
    let tang = sp[3];

    for (let side of [-1, 1]) {
      let bristleCount = int(random(4, 8));
      for (let b = 0; b < bristleCount; b++) {
        let bx = sp[0] + nx * side * random(r * 0.3, r * 0.85);
        let by = sp[1] + ny * side * random(r * 0.3, r * 0.85);
        let bAng = tang + side * random(28, 72);
        let bLen = random(6, 15);
        brush.set("gongbi_barb", random() < 0.5 ? "#784C22" : "#2E1B0E", random(0.55, 0.85));
        brush.line(bx, by, bx + cos(bAng) * bLen, by + sin(bAng) * bLen);
      }
    }
  }

  // 4. Dotted grain by grain in malachite and straw!
  // Arranged in organic botanical lobules along the panicle
  let numLobes = 28;
  for (let l = 1; l < numLobes; l++) {
    let t = l / numLobes;
    let pt = evalQuadBezier(p0, p1, p2, t);
    let ptNext = evalQuadBezier(p0, p1, p2, min(1, t + 0.02));
    let dx = ptNext[0] - pt[0];
    let dy = ptNext[1] - pt[1];
    let d = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / d;
    let ny = dx / d;
    let env = sin(pow(t, 0.68) * 180);
    let rMax = maxRadius * env;

    // 2 to 3 lobules across the width at this station
    let grainsInSlice = int(map(rMax, 2, maxRadius, 4, 15));
    for (let g = 0; g < grainsInSlice; g++) {
      let spread = map(g, 0, max(1, grainsInSlice - 1), -0.95, 0.95) + random(-0.12, 0.12);
      let gx = pt[0] + nx * spread * rMax + random(-2.2, 2.2);
      let gy = pt[1] + ny * spread * rMax + random(-2.2, 2.2);

      let isMalachite = random() < malachiteRatio * (1 - abs(spread) * 0.25);
      drawSingleMilletGrain(gx, gy, isMalachite, abs(spread));
    }
  }
}

function drawSingleMilletGrain(gx, gy, isMalachite, edgeFactor = 0.3) {
  // Subtle dark glume / cupule shadow at base of grain
  brush.set("gongbi_ink", "#1F1209", 0.85);
  brush.line(gx - 1.4, gy + 0.8, gx + 0.6, gy + 1.4);

  // Main plump grain bead in mineral malachite or straw-ochre
  let grainCol;
  if (isMalachite) {
    grainCol = random(["#387D56", "#4E966C", "#68B084", "#7EC297"]);
  } else {
    grainCol = edgeFactor > 0.65
      ? random(["#E6C56E", "#F0D68A", "#D9AC4E"])
      : random(["#C78D32", "#DEA94B", "#AD6822", "#EBD080"]);
  }

  brush.set("grain_dot", grainCol, random(0.95, 1.35));
  brush.line(gx - 0.7, gy - 0.3, gx + 0.9, gy + 0.3);

  // Tiny luminous mineral specular dot on top of grain
  if (random() < 0.68) {
    let hlCol = isMalachite ? "#B8E6C8" : "#FFF3D1";
    brush.set("shaft_gouache", hlCol, 0.65);
    brush.line(gx - 0.2, gy - 0.6, gx + 0.3, gy - 0.5);
  }

  // Hair-fine ink rim around the glume
  brush.set("gongbi_barb", "#29180D", 0.7);
  brush.arc(gx, gy, random(1.8, 2.6), -30, 175);
}

