// ---------------------------------------------------------------------------
// 4 & 5. HYPERREAL GONGBI QUAIL ANATOMY & FEATHER ENGINE
// ---------------------------------------------------------------------------

/**
 * Renders a single hyperreal Gongbi feather with mineral wash, internal transverse
 * barring or breast scalloping, hair-fine barbules, unwavering ink contour,
 * and luminous straw-cream central shaft (rachis).
 */
function drawQuailFeather(cx, cy, len, wid, angleDeg, style = "mantle") {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);

  function toWorld(lx, ly) {
    return [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];
  }

  // Ovate-rounded feather contour in local coords: base at (0,0), tip at (len, 0)
  let localContour = [
    [0, 0],
    [len * 0.22, -wid * 0.42],
    [len * 0.58, -wid * 0.52],
    [len * 0.86, -wid * 0.38],
    [len * 1.0, 0],
    [len * 0.86, wid * 0.38],
    [len * 0.58, wid * 0.52],
    [len * 0.22, wid * 0.42]
  ];
  let worldContour = localContour.map(p => toWorld(p[0], p[1]));

  if (style === "mantle" || style === "scapular") {
    // High-contrast dark lampblack & burnt sienna feather with pale azurite-buff edge & bright shaft
    let baseCol = random() < 0.55 ? "#17110C" : "#3B1B0D";
    drawPolyWash(worldContour, baseCol, 210, 0.25);

    // Warm burnt sienna / gold ochre distal wash
    let tipZone = [
      toWorld(len * 0.45, -wid * 0.48),
      toWorld(len * 0.86, -wid * 0.38),
      toWorld(len * 1.0, 0),
      toWorld(len * 0.86, wid * 0.38),
      toWorld(len * 0.45, wid * 0.48)
    ];
    drawPolyWash(tipZone, random() < 0.6 ? "#8E3B16" : "#BA7C2C", 165, 0.25);

    // Transverse ochre/buff bars across the feather web
    let barPositions = [0.42, 0.68];
    for (let bp of barPositions) {
      let pTop = toWorld(len * bp, -wid * 0.44);
      let pMid = toWorld(len * (bp + 0.05), 0);
      let pBot = toWorld(len * bp, wid * 0.44);
      brush.set("mineral_wash", "#D69B43", 0.65);
      brush.spline([[pTop[0], pTop[1], 0.5], [pMid[0], pMid[1], 0.9], [pBot[0], pBot[1], 0.5]], 0.35);
    }

    // Fine diagonal feather barbules in lampblack and sepia
    let barbCount = int(map(len, 14, 48, 5, 11));
    for (let b = 1; b <= barbCount; b++) {
      let f = b / (barbCount + 1);
      let bx0 = len * f * 0.82;
      let bx1 = len * min(0.96, f * 0.82 + 0.16);
      let bw = wid * 0.46 * sin(f * 165);
      let p0 = toWorld(bx0, 0);
      let pU = toWorld(bx1, -bw);
      let pD = toWorld(bx1, bw);
      brush.set("gongbi_barb", "#120C08", 0.8);
      brush.line(p0[0], p0[1], pU[0], pU[1]);
      brush.line(p0[0], p0[1], pD[0], pD[1]);
    }

    // Pale azurite / warm buff terminal scallop margin
    let rimPts = [
      toWorld(len * 0.62, -wid * 0.48),
      toWorld(len * 0.88, -wid * 0.36),
      toWorld(len * 1.0, 0),
      toWorld(len * 0.88, wid * 0.36),
      toWorld(len * 0.62, wid * 0.48)
    ];
    brush.set("gongbi_barb", random() < 0.35 ? "#8FB4BE" : "#DFC9A0", 0.95);
    brush.spline(rimPts.map(p => [p[0], p[1], 0.7]), 0.35);

    // Unwavering hair-fine ink contour
    brush.set("gongbi_ink", "#140D09", 0.78);
    brush.spline(worldContour.concat([worldContour[0]]).map(p => [p[0], p[1], 0.65]), 0.3);

    // Signature luminous lance-shaped cream/straw central shaft streak!
    if (style === "scapular" || random() < 0.78) {
      let s0 = toWorld(len * 0.08, 0);
      let sMidU = toWorld(len * 0.55, -wid * 0.09);
      let sTip = toWorld(len * 0.95, 0);
      let sMidD = toWorld(len * 0.55, wid * 0.09);
      drawPolyWash([s0, sMidU, sTip, sMidD], "#F7E9C8", 235, 0.15);

      brush.set("gongbi_barb", "#1A100A", 0.65);
      brush.line(s0[0], s0[1], sTip[0], sTip[1]);
      brush.set("shaft_gouache", "#FFF6DF", 0.95);
      brush.line(s0[0], s0[1], sTip[0], sTip[1]);
    }
  } else if (style === "breast") {
    // Warm burnt sienna & golden ochre breast feather with delicate dark sub-terminal scallop & cream edge
    let bCol = random(["#A4481E", "#C47A2C", "#8E3916", "#D49542"]);
    drawPolyWash(worldContour, bCol, 185, 0.3);

    // Soft pale cream center-tip wash
    let tipWash = [
      toWorld(len * 0.55, -wid * 0.45),
      toWorld(len * 0.92, -wid * 0.32),
      toWorld(len * 1.0, 0),
      toWorld(len * 0.92, wid * 0.32),
      toWorld(len * 0.55, wid * 0.45)
    ];
    drawPolyWash(tipWash, "#EBD8B5", 145, 0.25);

    // Sub-terminal dark sepia/black scallop crescent
    let scalPts = [
      toWorld(len * 0.62, -wid * 0.42),
      toWorld(len * 0.84, -wid * 0.26),
      toWorld(len * 0.91, 0),
      toWorld(len * 0.84, wid * 0.26),
      toWorld(len * 0.62, wid * 0.42)
    ];
    brush.set("gongbi_ink", "#26140B", 0.9);
    brush.spline(scalPts.map(p => [p[0], p[1], 0.8]), 0.35);

    // Hair-fine barbules & outer contour
    for (let side of [-1, 1]) {
      let pA = toWorld(len * 0.3, 0);
      let pB = toWorld(len * 0.78, side * wid * 0.38);
      brush.set("gongbi_barb", "#6E2E12", 0.65);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    brush.set("gongbi_ink", "#2B170C", 0.68);
    brush.spline(worldContour.concat([worldContour[0]]).map(p => [p[0], p[1], 0.55]), 0.3);

    // Fine pale straw shaft line
    let s0 = toWorld(len * 0.12, 0);
    let s1 = toWorld(len * 0.94, 0);
    brush.set("shaft_gouache", "#F7EBD0", 0.8);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
  } else if (style === "flank") {
    // Bold chestnut-sienna flank feather with dark margins and wide cream central lance stripe
    drawPolyWash(worldContour, "#873314", 205, 0.25);

    // Dark lampblack internal flank bars
    let subPts = [
      toWorld(len * 0.35, -wid * 0.44),
      toWorld(len * 0.82, -wid * 0.34),
      toWorld(len * 0.94, 0),
      toWorld(len * 0.82, wid * 0.34),
      toWorld(len * 0.35, wid * 0.44)
    ];
    brush.set("gongbi_ink", "#170E09", 1.05);
    brush.spline(subPts.map(p => [p[0], p[1], 0.85]), 0.3);

    // Wide cream-buff central shaft stripe
    let stripe = [
      toWorld(len * 0.08, 0),
      toWorld(len * 0.52, -wid * 0.16),
      toWorld(len * 0.96, 0),
      toWorld(len * 0.52, wid * 0.16)
    ];
    drawPolyWash(stripe, "#F6E7C6", 230, 0.15);

    // Crisp outer contour & central rachis
    brush.set("gongbi_ink", "#1E1109", 0.78);
    brush.spline(worldContour.concat([worldContour[0]]).map(p => [p[0], p[1], 0.65]), 0.3);

    let s0 = toWorld(len * 0.08, 0);
    let s1 = toWorld(len * 0.95, 0);
    brush.set("shaft_gouache", "#FFF7E2", 0.95);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
  } else if (style === "belly") {
    // Soft warm cream and pale azurite-tinted downy belly feather
    let col = random() < 0.32 ? "#94B3BD" : "#E8D7B7";
    drawPolyWash(worldContour, col, 160, 0.3);

    let scal = [
      toWorld(len * 0.55, -wid * 0.42),
      toWorld(len * 0.88, 0),
      toWorld(len * 0.55, wid * 0.42)
    ];
    brush.set("gongbi_barb", "#6E5239", 0.65);
    brush.spline(scal.map(p => [p[0], p[1], 0.6]), 0.35);

    let s0 = toWorld(len * 0.15, 0);
    let s1 = toWorld(len * 0.9, 0);
    brush.set("shaft_gouache", "#FAF0D7", 0.7);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
  } else if (style === "covert") {
    // Wing covert: buff-ochre & pale azurite sheen with fine dark vermiculation
    let col = random(["#B57F39", "#8B4E24", "#6D949E", "#C99648"]);
    drawPolyWash(worldContour, col, 190, 0.25);

    // Transverse vermiculation bars
    for (let t of [0.38, 0.62, 0.82]) {
      let pU = toWorld(len * t, -wid * 0.4);
      let pM = toWorld(len * (t + 0.04), 0);
      let pD = toWorld(len * t, wid * 0.4);
      brush.set("gongbi_ink", "#1E120A", 0.75);
      brush.spline([[pU[0], pU[1], 0.6], [pM[0], pM[1], 0.8], [pD[0], pD[1], 0.6]], 0.3);
    }

    // Pale buff margin & bright shaft
    brush.set("gongbi_ink", "#1A1009", 0.75);
    brush.spline(worldContour.concat([worldContour[0]]).map(p => [p[0], p[1], 0.6]), 0.3);

    let s0 = toWorld(len * 0.1, 0);
    let s1 = toWorld(len * 0.94, 0);
    brush.set("shaft_gouache", "#F5E5C2", 0.9);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
  } else if (style === "primary") {
    // Stiff elongated flight feather (remex) with dark brown web, ochre mottling & crisp pale edge
    let primContour = [
      toWorld(0, 0),
      toWorld(len * 0.3, -wid * 0.42),
      toWorld(len * 0.85, -wid * 0.32),
      toWorld(len * 1.0, -wid * 0.05),
      toWorld(len * 0.88, wid * 0.28),
      toWorld(len * 0.3, wid * 0.38)
    ];
    drawPolyWash(primContour, "#2E1C11", 215, 0.18);

    // Mottled ochre notches along outer web
    for (let m = 0.25; m < 0.88; m += 0.14) {
      let p1 = toWorld(len * m, wid * 0.05);
      let p2 = toWorld(len * (m + 0.05), wid * 0.34);
      brush.set("mineral_wash", "#C98D3B", 0.55);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Fine parallel barbules across flight feather
    for (let b = 0.15; b < 0.92; b += 0.06) {
      let p0 = toWorld(len * b, 0);
      let pU = toWorld(len * (b + 0.06), -wid * 0.34);
      let pD = toWorld(len * (b + 0.06), wid * 0.28);
      brush.set("gongbi_barb", "#140B07", 0.7);
      brush.line(p0[0], p0[1], pU[0], pU[1]);
      brush.line(p0[0], p0[1], pD[0], pD[1]);
    }

    // Crisp outer edge & stiff central shaft
    brush.set("gongbi_ink", "#140C08", 0.82);
    brush.spline(primContour.concat([primContour[0]]).map(p => [p[0], p[1], 0.7]), 0.2);

    let s0 = toWorld(len * 0.05, 0);
    let s1 = toWorld(len * 0.97, -wid * 0.03);
    brush.set("shaft_gouache", "#F2DFB8", 0.92);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
  } else if (style === "crown") {
    // Small imbricated head feather in deep lampblack & russet
    let cCol = random() < 0.65 ? "#17100B" : "#7A2E12";
    drawPolyWash(worldContour, cCol, 215, 0.25);
    brush.set("gongbi_ink", "#120B07", 0.7);
    brush.spline(worldContour.concat([worldContour[0]]).map(p => [p[0], p[1], 0.6]), 0.3);
    if (random() < 0.5) {
      let s0 = toWorld(len * 0.2, 0);
      let s1 = toWorld(len * 0.9, 0);
      brush.set("shaft_gouache", "#EBD6AE", 0.7);
      brush.line(s0[0], s0[1], s1[0], s1[1]);
    }
  }
}

/**
 * Renders scaly avian tarsus and toes in yellow-ochre and fine ink.
 */
function drawQuailLeg(hipX, hipY, ankleX, ankleY, footX, footY, dir = -1) {
  // Tibiotarsus & tarsometatarsus bone wash
  let legPts = [
    [hipX - 5, hipY],
    [ankleX - 4, ankleY],
    [footX - 3, footY],
    [footX + 3, footY],
    [ankleX + 4, ankleY],
    [hipX + 5, hipY]
  ];
  drawPolyWash(legPts, "#D49B42", 210, 0.15);

  // Three forward toes + hind hallux
  let toes = [
    [footX + dir * 34, footY + 6, 4],   // Middle toe (longest)
    [footX + dir * 26, footY + 14, 3],  // Outer/foreground toe
    [footX + dir * 24, footY - 3, 3],   // Inner toe
    [footX - dir * 13, footY + 3, 2]    // Hind toe (hallux)
  ];

  for (let t of toes) {
    let tx = t[0];
    let ty = t[1];
    let scutes = t[2];

    brush.set("mineral_wash", "#C98E38", 0.75);
    brush.line(footX, footY, tx, ty);

    // Dorsal toe scutes (scales)
    for (let s = 0; s <= scutes; s++) {
      let f = s / (scutes + 1);
      let sx = lerp(footX, tx, f);
      let sy = lerp(footY, ty, f);
      brush.set("gongbi_ink", "#382210", 0.75);
      brush.arc(sx, sy, 2.6, -70, 110);
      brush.set("shaft_gouache", "#F7E5B9", 0.65);
      brush.line(sx - 1, sy - 1, sx + 1, sy - 1);
    }

    // Outline of toe
    brush.set("gongbi_ink", "#29180B", 0.8);
    brush.line(footX, footY - 1.8, tx, ty - 1.0);
    brush.line(footX, footY + 1.8, tx, ty + 1.2);

    // Sharp curved horn claw
    let cTipX = tx + dir * 7;
    let cTipY = ty + 3.5;
    brush.set("gongbi_ink", "#1C120B", 0.95);
    brush.spline([[tx, ty - 0.8, 0.9], [tx + dir * 4, ty + 0.5, 0.7], [cTipX, cTipY, 0.2]], 0.35);
    brush.line(tx, ty + 1.0, cTipX, cTipY);
  }

  // Tarsus imbricated scales along the ankle-to-foot shaft
  let steps = 8;
  for (let i = 0; i <= steps; i++) {
    let f = i / steps;
    let sx = lerp(ankleX, footX, f);
    let sy = lerp(ankleY, footY, f);
    brush.set("gongbi_ink", "#331E0E", 0.75);
    brush.line(sx - 3.2, sy, sx + 3.2, sy + 1.2);
    brush.set("shaft_gouache", "#F9E9C2", 0.65);
    brush.line(sx - 1.5, sy - 1.2, sx + 1.5, sy - 0.6);
  }

  // Leg shaft ink contours
  brush.set("gongbi_ink", "#26160B", 0.85);
  brush.line(hipX - 4, hipY, ankleX - 3.5, ankleY);
  brush.line(ankleX - 3.5, ankleY, footX - 2.8, footY);
  brush.line(hipX + 4, hipY, ankleX + 3.5, ankleY);
  brush.line(ankleX + 3.5, ankleY, footX + 2.8, footY);
}

/**
 * Renders the glossy black quail eye with orbital papillae (eyelid beads)
 * and crisp specular catchlight.
 */
function drawQuailEye(ex, ey, r = 8.5, lookDir = -1) {
  // Dark orbital socket shadow
  drawPolyWash(makeBlobPoints(ex, ey, r * 1.35, r * 1.15, 0, 14, 0.04), "#1F130B", 200, 0.25);

  // Deep obsidian-brown iris & pupil
  drawPolyWash(makeBlobPoints(ex, ey, r, r * 0.94, -5, 16, 0.02), "#0C0907", 250, 0.25);

  // Subtle warm burnt-sienna iris rim glow at lower crescent
  brush.set("gongbi_ink", "#6B3014", 0.9);
  brush.arc(ex, ey, r * 0.72, 25, 155);

  // Pure jet-black pupil core
  drawPolyWash(makeBlobPoints(ex, ey, r * 0.65, r * 0.65, 0, 12, 0.01), "#050404", 255, 0.25);

  // Crisp ink eyelid contour
  brush.set("gongbi_ink", "#080605", 1.1);
  brush.arc(ex, ey, r * 1.02, 0, 360);

  // Tiny cream-ochre orbital eyelid beads (papillae) around the eye ring
  let numBeads = 22;
  for (let i = 0; i < numBeads; i++) {
    let a = (i / numBeads) * 360;
    let bx = ex + cos(a) * (r * 1.16);
    let by = ey + sin(a) * (r * 1.06);
    brush.set("grain_dot", i % 2 === 0 ? "#E6CE9E" : "#C49552", 0.55);
    brush.line(bx - 0.4, by, bx + 0.4, by);
    brush.set("gongbi_barb", "#24150B", 0.55);
    brush.arc(bx, by, 1.3, 0, 180);
  }

  // Primary luminous white specular highlight (upper-front quadrant)
  let hx = ex + lookDir * (r * 0.34);
  let hy = ey - r * 0.34;
  brush.set("shaft_gouache", "#FFFDF7", 1.35);
  brush.line(hx - 1.2, hy + 0.4, hx + 1.2, hy - 0.6);
  brush.set("shaft_gouache", "#FFFFFF", 1.0);
  brush.line(hx - 0.5, hy, hx + 0.5, hy);

  // Secondary tiny sky-reflection dot on lower opposite rim
  let hx2 = ex - lookDir * (r * 0.38);
  let hy2 = ey + r * 0.36;
  brush.set("shaft_gouache", "#D9E8EE", 0.75);
  brush.line(hx2, hy2, hx2 + 0.6, hy2);
}

/**
 * Renders the finely curved quail beak with culmen highlight and nostril slit.
 */
function drawQuailBeak(bx, by, tipX, tipY, dir = -1) {
  let dx = tipX - bx;
  let dy = tipY - by;

  // Upper mandible
  let upperPts = [
    [bx, by - 10],
    [bx + dx * 0.52, by - 9 + dy * 0.35],
    [tipX, tipY + 1.5],
    [bx + dx * 0.45, by + 1 + dy * 0.5],
    [bx, by + 1]
  ];
  drawPolyWash(upperPts, "#4A3B2E", 225, 0.2);

  // Dark horn tip of upper mandible
  let tipPts = [
    [bx + dx * 0.45, by - 7 + dy * 0.4],
    [tipX, tipY + 1.5],
    [bx + dx * 0.45, by + 1 + dy * 0.5]
  ];
  drawPolyWash(tipPts, "#1C1612", 230, 0.15);

  // Lower mandible
  let lowerPts = [
    [bx + dir * 2, by + 1],
    [bx + dx * 0.5, by + 1 + dy * 0.5],
    [tipX - dir * 3, tipY + 2.2],
    [bx + dx * 0.42, by + 6.5 + dy * 0.5],
    [bx + dir * 4, by + 8]
  ];
  drawPolyWash(lowerPts, "#7D6A54", 215, 0.2);

  // Luminous horn culmen ridge highlight
  brush.set("shaft_gouache", "#E3D2B4", 0.85);
  brush.spline([
    [bx + dir * 2, by - 8.5, 0.8],
    [bx + dx * 0.5, by - 7.5 + dy * 0.35, 0.7],
    [tipX - dir * 3, tipY, 0.2]
  ], 0.35);

  // Nostril operculum & slit
  let nx = bx + dx * 0.28;
  let ny = by - 3.5 + dy * 0.25;
  brush.set("gongbi_ink", "#140D08", 0.9);
  brush.line(nx - dir * 3, ny - 0.5, nx + dir * 3.5, ny + 0.8);
  brush.set("shaft_gouache", "#C9B393", 0.65);
  brush.line(nx - dir * 2.5, ny - 1.5, nx + dir * 2.5, ny - 0.5);

  // Crisp gape line & beak contours
  brush.set("gongbi_ink", "#120B07", 0.95);
  brush.spline([
    [bx, by - 10, 0.85],
    [bx + dx * 0.55, by - 8.5 + dy * 0.35, 0.8],
    [tipX, tipY + 1.5, 0.4]
  ], 0.35);
  brush.spline([
    [bx - dir * 3, by + 1.5, 0.9],
    [bx + dx * 0.48, by + 0.8 + dy * 0.5, 0.8],
    [tipX, tipY + 1.5, 0.5]
  ], 0.3);
  brush.spline([
    [bx + dir * 3, by + 8, 0.8],
    [bx + dx * 0.45, by + 6 + dy * 0.5, 0.7],
    [tipX - dir * 3, tipY + 2, 0.4]
  ], 0.3);
}

// ===========================================================================
// 4. QUAIL A (STANDING ALERT, CENTER-RIGHT, FACING UPPER-LEFT)
// ===========================================================================
function drawAlertQuail() {
  // 1. Legs drawn first so lower belly plumage naturally overlaps the tibiotarsus
  drawQuailLeg(735, 845, 755, 882, 725, 922, -1); // Far/left leg
  drawQuailLeg(785, 850, 808, 890, 780, 932, -1); // Near/right leg

  // 2. Dozens of transparent mineral under-washes building the 3D volume of Quail A
  let bodySilhouette = [
    [575, 622], [608, 598], [648, 608], [695, 635],
    [775, 655], [855, 695], [915, 755], [952, 815],
    [912, 835], [845, 855], [765, 868], [685, 848],
    [625, 795], [595, 725], [588, 668]
  ];
  // Base warm ochre wash
  drawPolyFill(bodySilhouette, "#C88935", 65, 0.14, 0.45, 0.3, 0.25);
  // Burnt sienna mantle & breast wash
  drawPolyFill(makeBlobPoints(740, 735, 135, 82, 22, 16, 0.08), "#8F3B18", 68, 0.18, 0.5, 0.3);
  drawPolyFill(makeBlobPoints(648, 745, 65, 78, -15, 14, 0.08), "#A84A20", 62, 0.18, 0.45, 0.3);
  // Deep lampblack/umber upper back shadow wash
  drawPolyFill(makeBlobPoints(795, 720, 105, 52, 26, 16, 0.08), "#29170D", 72, 0.16, 0.5, 0.35);
  // Pale azurite mineral wash on lower belly, flank shadow & wing coverts
  drawPolyFill(makeBlobPoints(755, 835, 95, 38, 8, 14, 0.1), "#6E9BA8", 52, 0.2, 0.45, 0.25);
  drawPolyFill(makeBlobPoints(760, 765, 85, 45, 18, 14, 0.1), "#75A1AD", 38, 0.2, 0.4, 0.25);
  // Luminous cream throat & lower belly highlight wash
  drawPolyFill(makeBlobPoints(605, 662, 34, 26, -15, 12, 0.06), "#F2E2C2", 95, 0.12, 0.3, 0.2);

  // 3. Tail & Undertail Coverts (tucked at (890..958, 775..835))
  for (let i = 0; i < 11; i++) {
    let f = i / 10;
    let tx = lerp(885, 915, f) + random(-4, 4);
    let ty = lerp(765, 818, f) + random(-3, 3);
    let ang = lerp(22, 38, f);
    drawQuailFeather(tx, ty, random(34, 46), random(13, 17), ang, "mantle");
  }

  // 4. Downy Belly & Vent Tract (soft cream and pale azurite-grey feathers)
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 8; col++) {
      let bx = 685 + col * 22 + row * 6 + random(-3, 3);
      let by = 818 + row * 12 + sin(col * 22) * 8;
      let ang = 12 + col * 2;
      drawQuailFeather(bx, by, 24, 15, ang, "belly");
    }
  }

  // 5. Lower Back, Rump & Upper Mantle Tract (imbricated back-to-front so shafts overlap naturally)
  // Painted from posterior (near tail) to anterior (near nape) or layered along feather growth direction (pointing toward tail at ~20..32 deg)
  for (let row = 0; row < 9; row++) {
    // row 0 is anterior (near neck), row 8 is posterior (near rump);
    // In avian plumage, anterior feathers overlap posterior ones, so we draw posterior rows first!
    let rIdx = 8 - row;
    let tRow = rIdx / 8;
    let spineX = lerp(665, 875, tRow);
    let spineY = lerp(632, 758, tRow);
    let numFeathers = int(map(sin(tRow * 160), 0, 1, 5, 10));

    for (let k = 0; k < numFeathers; k++) {
      let spread = map(k, 0, max(1, numFeathers - 1), -1, 1);
      let fx = spineX - spread * 14 + random(-3, 3);
      let fy = spineY + (spread + 1) * 24 + random(-3, 3);
      let flen = map(sin(tRow * 150), 0, 1, 24, 42);
      let fwid = flen * 0.46;
      let fang = 24 + spread * 10 + tRow * 8;
      let fStyle = (k % 2 === 0 || abs(spread) < 0.4) ? "scapular" : "mantle";
      drawQuailFeather(fx, fy, flen, fwid, fang, fStyle);
    }
  }

  // 6. Wing Primaries, Secondaries & Coverts (folded wing on side of body)
  // Long stiff primaries extending back toward the tail
  for (let p = 0; p < 8; p++) {
    let px = 765 + p * 12;
    let py = 758 + p * 7;
    let plen = 72 - p * 3.5;
    let pwid = 13;
    let pang = 22 - p * 1.2;
    drawQuailFeather(px, py, plen, pwid, pang, "primary");
  }
  // Greater & Median Wing Coverts with pale azurite sheen and buff shaft streaks
  for (let tier = 2; tier >= 0; tier--) {
    let count = 7 - tier;
    for (let c = 0; c < count; c++) {
      let cx = 695 + tier * 24 + c * 15 + random(-2, 2);
      let cy = 715 + tier * 14 + c * 8 + random(-2, 2);
      let clen = 26 + tier * 5;
      let cwid = 14 + tier * 2;
      let cang = 22 + c * 2;
      drawQuailFeather(cx, cy, clen, cwid, cang, "covert");
    }
  }

  // 7. Bold Chestnut-and-Cream Flank Feathers (sweeping along lower side below the wing)
  for (let f = 6; f >= 0; f--) {
    let fx = 665 + f * 24 + random(-3, 3);
    let fy = 772 + f * 9 + random(-3, 3);
    let flen = 38 + sin((f / 6) * 180) * 12;
    let fwid = 18;
    let fang = 18 + f * 2.5;
    drawQuailFeather(fx, fy, flen, fwid, fang, "flank");
  }

  // 8. Scalloped Breast Feathers (burnt sienna, golden ochre, dark sub-margins)
  // Drawn from lower breast up to upper chest so upper feathers overlap lower ones
  for (let row = 6; row >= 0; row--) {
    let tR = row / 6;
    let count = int(lerp(4, 7, sin(tR * 160)));
    for (let col = 0; col < count; col++) {
      let fCol = col / max(1, count - 1);
      let bx = lerp(594, 655, fCol) + row * 8 + random(-2, 2);
      let by = 682 + row * 19 + fCol * 12 + random(-2, 2);
      let blen = lerp(18, 28, tR);
      let bwid = lerp(13, 19, tR);
      let bang = lerp(98, 42, fCol) - (1 - tR) * 12;
      drawQuailFeather(bx, by, blen, bwid, bang, "breast");
    }
  }

  // 9. Head, Crown, Supercilium & Speckled Throat
  // Creamy-buff throat base & cheek patch
  let throatPoly = [
    [568, 645], [608, 638], [642, 655], [645, 688], [605, 696], [582, 675]
  ];
  drawPolyWash(throatPoly, "#F3E4C6", 215, 0.25);

  // Warm russet-sienna cheek & malar stripe
  drawPolyWash(makeBlobPoints(618, 652, 22, 12, 18, 12, 0.06), "#9E421B", 180, 0.25);

  // Crown & Nape imbricated scale-like feathers (deep lampblack and burnt sienna)
  for (let r = 4; r >= 0; r--) {
    for (let c = 0; c < 6; c++) {
      let hx = 588 + c * 11 + r * 6 + random(-1.5, 1.5);
      let hy = 602 + r * 6 + c * 3.5 + random(-1.5, 1.5);
      drawQuailFeather(hx, hy, 14, 8, 18 + r * 4, "crown");
    }
  }

  // Bright cream-straw central crown stripe & prominent supercilium (eyebrow stripe)
  let supercilium = [
    [568, 622], [595, 610], [628, 614], [656, 628],
    [652, 635], [624, 623], [595, 619], [570, 628]
  ];
  drawPolyWash(supercilium, "#F7E9C8", 235, 0.2);
  for (let s = 0; s < 14; s++) {
    let t = s / 13;
    let sx = lerp(572, 652, t);
    let sy = lerp(624, 631, t) - sin(t * 180) * 9;
    brush.set("shaft_gouache", "#FFF6DF", 0.85);
    brush.line(sx, sy, sx + 7, sy + 1.5);
    brush.set("gongbi_barb", "#2E1B0E", 0.6);
    brush.line(sx, sy + 2, sx + 6, sy + 3);
  }

  // Meticulous Speckled Throat (double necklace of crisp lampblack & burnt-umber spots)
  for (let ring = 0; ring < 2; ring++) {
    let spots = ring === 0 ? 14 : 18;
    for (let i = 0; i < spots; i++) {
      let t = i / (spots - 1);
      let rad = ring === 0 ? 26 : 36;
      let ang = lerp(155, 25, t);
      let sx = 612 + cos(ang) * rad + random(-2, 2);
      let sy = 656 + sin(ang) * (rad * 0.85) + random(-2, 2);
      brush.set("grain_dot", i % 3 === 0 ? "#7D2E12" : "#170F0A", random(0.85, 1.25));
      brush.line(sx - 1.2, sy - 0.5, sx + 1.5, sy + 1.2);
    }
  }
  // Fine chin speckles
  for (let i = 0; i < 22; i++) {
    let sx = random(582, 635);
    let sy = random(648, 682);
    brush.set("gongbi_ink", "#2B180C", random(0.6, 0.95));
    brush.line(sx, sy, sx + 1.4, sy + 0.8);
  }

  // Ear covert patch (rufous-brown finely striated feathers behind eye)
  for (let e = 0; e < 12; e++) {
    let ex = 618 + random(-8, 14);
    let ey = 640 + random(-6, 8);
    brush.set("gongbi_ink", e % 2 === 0 ? "#6E2B11" : "#1F120A", 0.8);
    brush.line(ex, ey, ex + 8, ey + 3);
  }

  // Beak & Glossy Black Eye of Quail A
  drawQuailBeak(572, 635, 536, 642, -1);
  drawQuailEye(596, 629, 8.6, -1);
}

// ===========================================================================
// 5. QUAIL B (CROUCHED NESTLED, LOWER-CENTER, FACING RIGHT-DOWN)
// ===========================================================================
function drawNestledQuail() {
  // Quail B crouches serenely on its belly from (320, 880) to head at (660, 868),
  // facing right-downward toward the fallen millet grains.

  // 1. Subtle glimpse of Quail B's tucked yellow-ochre toes beneath the lower breast
  drawQuailLeg(535, 922, 520, 945, 548, 958, 1);

  // 2. Transparent Mineral Under-Washes (burnt sienna, ochre, lampblack, pale azurite)
  let bodyB = [
    [322, 888], [358, 835], [415, 785], [488, 762],
    [562, 772], [622, 805], [668, 835], [685, 868],
    [665, 902], [615, 932], [538, 948], [448, 945],
    [372, 925], [332, 905]
  ];
