  drawPolyFill(makeBlobPoints(495, 845, 138, 76, -6, 16, 0.08), "#913C18", 68, 0.18, 0.5, 0.32);
  // High-contrast lampblack & deep umber across upper mantle and scapulars
  drawPolyFill(makeBlobPoints(475, 808, 115, 48, -8, 16, 0.08), "#24130A", 76, 0.15, 0.52, 0.35);
