    let tx = lerp(375, 348, f) + random(-3, 3);
    let ty = lerp(848, 898, f) + random(-3, 3);
    let ang = lerp(168, 196, f);
    drawQuailFeather(tx, ty, random(34, 46), random(13, 16), ang, "mantle");
