      let bx = 545 - col * 22 + random(-3, 3);
      let by = 912 + row * 11 + sin(col * 24) * 6;
      drawQuailFeather(bx, by, 24, 15, 172 - col * 2, "belly");
    }
  }

  // 5. Arched Back, Rump & Scapulars (feathers point left-ward ~165..195 deg)
  // Drawn from posterior (left, near rump) to anterior (right, near shoulder/nape)
  for (let row = 0; row < 10; row++) {
    let tRow = row / 9; // 0 = posterior (left), 1 = anterior (right)
