      let by = 865 + row * 13 + fCol * 8 + random(-2, 2);
      let blen = lerp(18, 26, tR);
      let bwid = lerp(13, 18, tR);
      let bang = lerp(85, 138, fCol) + (1 - tR) * 10;
      drawQuailFeather(bx, by, blen, bwid, bang, "breast");
    }
  }

  // 9. Tucked Head, Crown, Supercilium, Speckled Throat, Eye & Beak (facing right-downward)
  let throatB = [
    [618, 868], [658, 868], [685, 882], [672, 908], [632, 912], [608, 892]
  ];
  drawPolyWash(throatB, "#F4E5C7", 220, 0.25);
  drawPolyWash(makeBlobPoints(638, 875, 20, 11, -12, 12, 0.06), "#9E421B", 175, 0.25);

