      drawQuailFeather(hx, hy, 14, 8, 165 - r * 3, "crown");
    }
  }

  // Luminous cream supercilium (eyebrow stripe) above Quail B's eye
  let superB = [
    [685, 852], [662, 838], [632, 838], [606, 848],
    [610, 855], [634, 846], [660, 846], [682, 858]
  ];
  drawPolyWash(superB, "#F7E9C8", 235, 0.2);
  for (let s = 0; s < 13; s++) {
