    let sx = lerp(680, 608, t);
    let sy = lerp(854, 850, t) - sin(t * 180) * 9;
    brush.set("shaft_gouache", "#FFF6DF", 0.85);
    brush.line(sx, sy, sx - 7, sy + 1);
    brush.set("gongbi_barb", "#2E1B0E", 0.6);
    brush.line(sx, sy + 2, sx - 6, sy + 2.5);
  }

  // Speckled Throat Necklace on Quail B
  for (let ring = 0; ring < 2; ring++) {
    let spots = ring === 0 ? 13 : 17;
    for (let i = 0; i < spots; i++) {
      let t = i / (spots - 1);
      let rad = ring === 0 ? 24 : 33;
      let ang = lerp(25, 155, t);
      let sx = 642 + cos(ang) * rad + random(-2, 2);
      let sy = 876 + sin(ang) * (rad * 0.82) + random(-2, 2);
      brush.set("grain_dot", i % 3 === 0 ? "#7D2E12" : "#170F0A", random(0.85, 1.25));
      brush.line(sx - 1.2, sy - 0.5, sx + 1.4, sy + 1.1);
    }
  }
  for (let i = 0; i < 18; i++) {
    let sx = random(622, 668);
    let sy = random(874, 902);
    brush.set("gongbi_ink", "#2B180C", random(0.6, 0.95));
    brush.line(sx, sy, sx + 1.4, sy + 0.8);
  }

  // Ear covert striations
  for (let e = 0; e < 11; e++) {
    let ex = 636 + random(-10, 8);
    let ey = 864 + random(-5, 7);
    brush.set("gongbi_ink", e % 2 === 0 ? "#6E2B11" : "#1F120A", 0.8);
    brush.line(ex, ey, ex - 8, ey + 2.5);
  }

  // Beak & Glossy Black Eye of Quail B (facing right-downward toward millet grains)
  drawQuailBeak(682, 868, 716, 882, 1);
  drawQuailEye(658, 858, 8.4, 1);
}

// ---------------------------------------------------------------------------
// 7. COURTLY RED CINNABAR COLLECTOR SEAL
// ---------------------------------------------------------------------------
function drawCollectorSeal(x, y) {
  let w = 44;
  let h = 64;
  let sealPts = [
    [x, y], [x + w, y], [x + w, y + h], [x, y + h]
  ];
  drawPolyWash(sealPts, "#A6261B", 195, 0.05);

  // Aged silk gaps & seal border in cinnabar vermilion
  brush.set("gongbi_ink", "#8C1A11", 1.1);
  brush.rect(x, y, w, h, "corner");

  // Archaic seal-script (Zhuanshu) glyphal lines in antique silk tone
  brush.set("shaft_gouache", "#DFCEAD", 1.05);
  // Upper character glyph
  brush.line(x + 10, y + 10, x + 34, y + 10);
  brush.line(x + 22, y + 7, x + 22, y + 28);
  brush.line(x + 12, y + 18, x + 32, y + 18);
  brush.line(x + 12, y + 18, x + 12, y + 28);
